window.FG_HUBEI = window.FG_HUBEI || [];
window.FG_HUBEI.push([{"id":"h0117","sections":[{"name":"","text":"（2004年9月24日湖北省第十届人民代表大会常务委员会第十一次会议通过）","level":0},{"name":"第一章 总则","text":"","level":1},{"name":"第二章 监察管辖和职责","text":"","level":1},{"name":"第三章 监察内容和程序","text":"","level":1},{"name":"第四章 法律责任","text":"","level":1},{"name":"第五章 附则","text":"","level":1},{"name":"第一章 总则","text":"第一条 为了规范劳动和社会保障监察行为，维护劳动者的合法权益，促进经济发展和社会稳定，根据《中华人民共和国劳动法》和有关法律、法规，结合本省实际，制定本条例。\n第二条 本条例所称劳动和社会保障监察是指县级以上人民政府劳动和社会保障行政部门依法对用人单位、劳动和社会保障服务机构遵守劳动和社会保障法律、法规的情况进行监督检查，并对违法行为进行处理的行政执法行为。\n本条例所称用人单位是指企业、民办非企业单位、个体经济组织。\n本条例所称劳动和社会保障服务机构是指职业介绍机构、职业培训机构、职业技能鉴定机构。\n对国家机关、事业组织、社会团体遵守劳动和社会保障法律、法规的情况实施劳动和社会保障监察，依照本条例的规定执行。\n第三条 县级以上人民政府劳动和社会保障行政部门主管本行政区域内的劳动和社会保障监察工作。\n县级以上人民政府有关部门应当在各自的职责范围内协同劳动和社会保障行政部门做好相关工作。\n第四条 各级工会组织依法对用人单位遵守劳动和社会保障法律、法规的情况进行监督。劳动和社会保障行政部门和工会组织应当建立并实行情况通报和工作联系制度。\n任何组织和个人对违反劳动和社会保障法律、法规的行为，有权向劳动和社会保障行政部门举报或者投诉。\n第五条 劳动和社会保障监察工作应当遵循合法、公正、公开以及教育与处罚相结合的原则，及时、准确地查处违反劳动和社会保障法律、法规的行为。\n第六条 劳动和社会保障监察工作经费列入同级财政预算。","level":1},{"name":"第二章 监察管辖和职责","text":"第七条 对用人单位的劳动和社会保障监察工作由用工行为发生地的县级以上人民政府劳动和社会保障行政部门管辖。\n对劳动和社会保障服务机构的劳动和社会保障监察工作由劳动和社会保障服务机构注册地或者登记地的县级以上人民政府劳动和社会保障行政部门管辖。\n上级人民政府劳动保障行政部门必要时可以直接对下一级管辖的监察对象实施劳动和社会保障监察；下级人民政府劳动和社会保障行政部门可以将重大监察事项提请上一级人民政府劳动和社会保障行政部门实施劳动和社会保障监察。\n对劳动和社会保障监察管辖发生争议的，报请共同的上一级人民政府劳动和社会保障行政部门指定管辖。\n第八条 劳动和社会保障行政部门依法履行下列监察职责：\n（一）宣传、执行劳动和社会保障法律、法规；\n（二）监督检查用人单位、劳动和社会保障服务机构遵守劳动和社会保障法律、法规的情况；\n（三）受理违反劳动和社会保障法律、法规行为的举报和投诉；\n（四）纠正和查处违反劳动和社会保障法律、法规的行为；\n（五）法律、法规规定的其他监察职责。\n第九条 劳动和社会保障监察人员应当具备相应的文化水平和专业知识，熟悉劳动和社会保障法律、法规和监察业务，忠于职守，文明执法，秉公办事，清正廉洁。","level":1},{"name":"第三章 监察内容和程序","text":"第十条 劳动和社会保障行政部门对下列事项实施监察：\n（一）制订和执行劳动管理制度情况；\n（二）招聘、使用劳动者情况；\n（三）订立、履行劳动合同和集体合同情况；\n（四）执行工作时间和休息、休假规定情况；\n（五）支付劳动者工资报酬和执行最低工资标准情况；\n（六）参加社会保险和缴纳社会保险费情况；\n（七）执行劳动保护有关规定和女职工、未成年工特殊劳动保护与禁止使用童工规定情况；\n（八）劳动和社会保障服务机构执行劳动和社会保障法律、法规情况；\n（九）法律、法规规定的其他监察内容。\n第十一条 劳动和社会保障行政部门在实施专项检查或者年度检查前，应当制定检查方案；实施检查后，将检查结果向被检查单位通报，必要时向社会公告。\n劳动和社会保障行政部门受理违反劳动和社会保障法律、法规行为的投诉和举报，应当予以登记，指定监察人员调查，并为举报人保密。\n第十二条 劳动和社会保障行政部门进行监察时，应当遵守下列规定：\n（一）由两名以上监察人员共同进行，监察人员应当向被检查单位出示执法证件和监察通知书；\n（二）告知监察的依据、内容、要求和方法；\n（三）询问或者现场检查应当制作笔录或者记录，笔录和记录应当由监察人员和被询问人或者被检查单位的有关人员签名或者盖章。被询问人或者被检查单位的有关人员拒绝签字或者盖章的，应当注明拒绝事由。\n劳动和社会保障行政部门可以根据需要向被检查单位下达询问通知书，被检查单位应当按照询问通知书的要求接受询问或者作出书面答复。\n第十三条 劳动和社会保障行政部门根据监察结果，按照下列方式处理：\n（一）违反劳动和社会保障法律、法规行为不成立的，应当停止检查；\n（二）违法行为情节较轻，依法可以不给予行政处罚的，应当作出相应的行政处理；\n（三）依法应当给予行政处罚的，依照有关法律、法规的规定作出行政处罚决定；\n（四）对属于劳动争议纠纷的，应当告知当事人依法申请劳动争议仲裁或者提起诉讼；对属于其他行政部门职责范围的案件，应当及时移送有处理权的部门查处；涉嫌犯罪的，应当移送司法机关处理。\n第十四条 劳动和社会保障行政部门查处违法行为，应当按照下列程序进行：\n（一）立案；\n（二）调查取证；\n（三）听取申辩或者听证；\n（四）依法作出行政处罚决定或者行政处理决定；\n（五）送达。\n劳动和社会保障行政部门在作出行政处罚决定之前，应当告知当事人作出行政处罚决定的事实、理由及依据，并告知当事人依法享有的权利。\n第十五条 劳动和社会保障行政部门查处违反劳动和社会保障法律、法规行为，应当自立案之日起30日内结案；情况复杂确实需要延长的，经劳动和社会保障行政部门负责人批准，可以适当延长，但延长期限不得超过30日。\n第十六条 劳动和社会保障监察人员可以依法对用人单位进行现场检查、录音、录像，查阅、复制有关资料，询问有关人员。被检查单位应当给予协助，不得阻挠。\n劳动和社会保障监察人员不得泄露被检查单位的商业秘密和技术秘密。\n劳动和社会保障行政部门实施监察，不得向被检查单位收取费用；超越管辖权限或者违反法定程序实施检查的，被检查单位有权予以拒绝。\n第十七条 劳动和社会保障监察人员在查处案件过程中有下列情形之一的，应当回避：\n（一）是本案当事人近亲属的；\n（二）本人或者其近亲属与本案有利害关系的；\n（三）与本案当事人有其他关系可能影响案件公正处理的。","level":1},{"name":"第四章 法律责任","text":"第十八条 法律、法规对违法行为已有处罚规定的，劳动和社会保障行政部门应当依照有关规定予以处罚。\n第十九条 用人单位有下列侵害劳动者合法权益情形之一的，由劳动和社会保障行政部门依照有关规定责令限期支付劳动者的工资报酬、经济补偿及赔偿金；逾期不改的，可并处5000元以上3万元以下罚款：\n（一）克扣或者无故拖欠劳动者工资的；\n（二）不支付劳动者延长工作时间的工资报酬的；\n（三）低于当地最低工资标准支付劳动者工资的。\n第二十条 用人单位提供虚假证明办理职工退休手续的，责令改正，可并处3000元以上1万元以下罚款。\n第二十一条 未经劳动和社会保障行政部门批准，擅自开办职业介绍、职业技能鉴定和职业培训机构或者滥发职业资格证书的，责令停止活动，没收违法所得，可并处违法所得1倍以上3倍以下罚款。\n职业介绍机构、职业培训机构与用人单位恶意串通损害劳动者合法权益的，责令停止活动和赔偿损失；情节严重的，可分别对违法双方处以3000元以上1万元以下罚款。\n第二十二条 有下列行为之一的，给予警告或者责令改正；情节严重的，可处3000元以上1万元以下罚款：\n（一）阻挠劳动和社会保障监察人员依法进行监督检查的；\n（二）隐瞒事实真相，出具伪证，或者隐匿、毁灭证据的；\n（三）拒绝按照劳动和社会保障监察询问通知书的要求接受询问或者拒绝提供有关资料的；\n（四）打击报复举报人的。\n第二十三条 当事人对依照本条例作出的行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。\n当事人在法定期限内不申请行政复议、不提起行政诉讼且不履行行政处罚决定的，由作出该决定的劳动和社会保障行政部门依法申请人民法院强制执行。\n第二十四条 劳动和社会保障监察人员有下列行为之一的，由其所在单位依法给予行政处分；构成犯罪的，依法追究刑事责任：\n（一）违反本条例规定，情节严重的；\n（二）玩忽职守、滥用职权、徇私舞弊的；\n（三）泄露有关检查单位的商业秘密和技术秘密的；\n（四）索取、收受当事人贿赂的。","level":1},{"name":"第五章 附则","text":"第二十五条 本条例自2004年12月1日起施行。","level":1}]},{"id":"h0118","sections":[{"name":"","text":"（2005年3月31日湖北省第十届人民代表大会常务委员会第十四次会议通过 2015年4月1日湖北省第十二届人民代表大会常务委员会第十四次会议修订 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第二次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了保障旅游者和旅游经营者合法权益，保护和合理利用旅游资源，规范旅游市场秩序，促进旅游业科学发展，根据《中华人民共和国旅游法》以及有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内旅游者的旅游活动以及旅游的资源保护、规划建设、经营服务、监督管理，适用本条例。\n第三条 发展旅游业应当有效保护旅游资源，突出地方特色，弘扬本地文化，坚持政府引导、社会参与、市场运作，统一规划、合理利用、科学管理，实现生态效益、社会效益、经济效益的统一。\n第四条 县级以上人民政府应当加强对本行政区域内旅游业发展的组织领导，将旅游业发展纳入国民经济和社会发展规划，推动旅游业发展与新型工业化、信息化、城镇化和农业现代化相结合，建立健全旅游综合协调体制机制，完善促进旅游业发展的政策和措施，实现旅游业可持续发展。\n省人民政府应当完善旅游标准化运行机制，健全旅游质量监督管理体系，加强全省旅游形象宣传，推进区域旅游一体化建设和旅游产品结构转变，培育旅游支柱产业，促进旅游重大项目和重点区域的协调发展，推动旅游强省建设。\n第五条 县级以上人民政府旅游主管部门负责本行政区域旅游业的管理、监督和服务工作。其他有关部门按照各自职责做好旅游业发展相关工作。\n第六条 各级人民政府及其有关部门、新闻媒体应当开展旅游生态文明宣传教育，引导旅游者、旅游经营者及其从业人员和旅游地居民增强保护旅游生态环境的意识，倡导健康、低碳、文明的旅游方式。\n第七条 旅游行业协会应当完善行业自律制度，推动旅游业诚信建设，发挥服务、引导、协调作用，依法维护行业合法权益和公平竞争秩序。","level":1},{"name":"第二章 旅游规划与促进","text":"第八条 县级以上人民政府应当根据国民经济和社会发展规划，组织编制旅游发展规划，对本行政区域的旅游资源保护、旅游基础设施和公共服务设施建设、旅游市场开发、旅游产业发展等进行总体部署。\n对跨行政区域且适宜整体利用的旅游资源进行利用时，由共同的上一级人民政府组织编制或者由相关人民政府协商编制统一的旅游发展规划，协调解决旅游规划实施中的重大问题。\n第九条 县级以上人民政府根据旅游发展规划，可以编制重点旅游资源开发利用、重大旅游项目建设的专项规划，对特定区域内的旅游资源保护以及旅游项目、设施、服务功能配套提出专门要求。\n第十条 编制旅游发展规划应当与国土空间规划、生态环境保护规划以及其他人文资源的保护和利用规划相衔接，并公开征求社会公众和专家的意见。\n各级人民政府应当对本级人民政府编制的旅游规划予以公布。\n第十一条 县级以上人民政府及其有关部门应当建立健全与境外、省内外的区域旅游合作机制，鼓励旅游客运经营者开发跨区域运营线路和产品，实现区域旅游客运一体化。\n第十二条 县级以上人民政府应当根据旅游业发展需要，统筹安排通往旅游景区的交通项目，合理规划建设旅游集散中心、中转站、旅游客运专线、自驾车营地等交通设施，加强景区旅游道路、步行道、停车场建设，推进旅游交通设施无障碍建设与改造，为旅游者提供便捷的交通服务。\n交通运输主管部门应当将游客运输纳入公共交通系统，合理布局旅游交通线路、旅游公共交通服务设施等；完善道路标识系统，主要交通干线和城市道路规划建设应当包括旅游交通标志、主要旅游景区指示标志牌等内容。\n第十三条 县级以上人民政府应当根据本地旅游业发展，在财政预算中安排资金，用于旅游规划编制、基础设施建设、资源保护、公共服务、人才培养和旅游形象推广等方面。\n县级以上人民政府有关部门应当对涉及景区的道路交通、安全保障、环境卫生、供水供电等配套设施的建设资金给予支持。\n第十四条 县级以上人民政府应当支持企业、其他组织和个人投资旅游业，培育壮大旅游市场主体，扶持特色旅游企业，鼓励发展专业旅游经营机构，组建跨界融合的产业集团和产业联盟。\n鼓励金融机构针对旅游企业、旅游项目创新信贷产品，加大信贷支持力度；鼓励保险机构开发旅游保险产品和服务。\n第十五条 县级以上人民政府及其有关部门应当围绕湖北旅游整体形象，结合实际，创新旅游宣传营销方式，加强特色旅游宣传推广，促进国内外客源市场开发。\n鼓励各类媒体宣传、推介本地的自然景观、人文景观、民俗风情等。\n第十六条 县级以上人民政府教育、旅游等有关部门支持大中专院校开展旅游管理学科体系建设，发展旅游职业教育，培养高端旅游专业人才；鼓励旅游企业与院校合作，加强旅游人才培训基地建设，开展旅游从业人员职业道德教育和技能培训，提高旅游从业人员素质。\n第十七条 县级以上人民政府及其有关部门应当制定相关政策措施，推动国家机关、企业事业单位和社会团体落实职工带薪年休假制度。","level":1},{"name":"第三章 旅游资源保护与利用","text":"第十八条 县级以上人民政府旅游主管部门应当加强本行政区域内旅游资源的普查、评价，建立旅游资源数据库和旅游资源保护情况通报制度，构建旅游资源保护体系，规范旅游资源的开发和利用。\n第十九条 开发利用旅游资源以及建设对旅游资源有影响的项目，应当严格执行旅游发展规划和专项规划，依法进行生态环境影响评价，制定旅游资源开发保护和恢复治理方案，实现可持续发展。\n利用自然资源开发的旅游项目，应当加强对自然资源和生物多样性的保护，不得破坏生态、污染环境；利用民族文化资源、历史建筑以及历史人文资源等开发的旅游项目，应当保持其民族特色、传统格局和历史风貌，不得擅自改建、迁移、拆除。涉及文物保护的，按照有关法律、法规的规定办理。\n第二十条 各级人民政府应当促进旅游与文化、工业、农业、卫生、体育、科教等领域的融合，推进文化旅游、休闲度假旅游、研学旅游、老年旅游等旅游产品的开发，支持建设符合市场需求的、多样化的旅游产品体系，发展新兴旅游业。\n第二十一条 省人民政府对具有旅游资源优势的民族自治地方、革命老区、集中连片贫困地区、库区以及旅游资源丰富的县、镇、传统村落的建设，给予资金和政策扶持。\n第二十二条 县级以上人民政府应当将乡村旅游与现代农业、新型城镇化有机结合，合理利用古镇古村、民族村寨，规范乡村旅游开发建设。\n旅游主管部门及有关部门应当发挥生态优势、突出乡村特色，通过政策扶持、宣传推介、协调指导等措施，鼓励开发观光、民俗、休闲等乡村旅游项目，推动农家乐规范化、特色化发展。\n支持村民自治组织、农村集体经济组织等参与发展乡村旅游。\n第二十三条 鼓励利用荒地、荒滩、废弃矿山等区域，因地制宜开发建设旅游项目；鼓励旅游经营者使用新能源、新材料，发展循环经济，创建绿色环保旅游企业。\n积极发掘、申报世界文化遗产，打造文化旅游品牌，开展文化旅游；鼓励依托民间艺术、手工艺、传统节日等开展民俗旅游。\n第二十四条 国有旅游资源经营权依法出让的，应当遵循公开、公平和公正的原则，通过拍卖、招标等方式进行，经营权有偿转让的收入按照国家相关规定管理。\n旅游经营者在经营期内违反旅游规划、造成旅游资源严重破坏或者长期闲置不开发利用的，由当地人民政府依法收回国有旅游资源经营权。\n第二十五条 县级以上人民政府及其有关部门应当规范旅游购物市场，推进特色商品购物区建设，扶持开发具有地方特色、民族特色、景区特点及文化内涵的旅游商品，培育旅游商品品牌，促进旅游商品的产业化发展。","level":1},{"name":"第四章 旅游者的权利与义务","text":"第二十六条 旅游者的合法权益受法律保护，任何单位和个人不得侵犯。\n老年人、残疾人、未成年人、现役军人等在旅游活动中依照法律、法规和有关规定享受便利和优惠。\n第二十七条 旅游者在旅游活动中享有下列权利：\n（一）对旅游经营者的资质、相关旅游产品和服务及价格享有真实、完整的知情权；\n（二）有权自主选择旅游产品、旅游经营者、旅游服务方式和服务项目，拒绝强制或者变相强制销售和服务；\n（三）按照约定获得质价相符的旅游服务；\n（四）旅游活动中人身、财产受到侵害时，有权依法获得赔偿；\n（五）人格尊严、民族风俗习惯和宗教信仰受到尊重；\n（六）对旅游经营者及其从业人员的违法行为进行监督；\n（七）在旅游活动中享有的其他合法权利。\n第二十八条 旅游者在旅游活动中应当履行下列义务：\n（一）遵守公共秩序和社会公德，爱护旅游设施，遵守安全、卫生规定，保护旅游资源和生态环境，文明旅游；\n（二）尊重当地民族风俗习惯和宗教信仰；\n（三）对旅游经营者如实告知与旅游活动相关的个人健康信息，履行旅游合同所约定的义务；\n（四）遇到不可抗力和突发事件时，对有关部门、机构或者旅游经营者采取的安全防范和应急处置措施，予以协助和配合；\n（五）积极配合有关组织和人员协商解决旅游活动中发生的纠纷，不得干扰他人的旅游活动，不得损害旅游经营者和旅游从业人员的合法权益；\n（六）出境旅游者不得在境外非法滞留，随团出境的旅游者不得擅自分团、脱团；\n（七）法律、法规规定的其他义务。\n第二十九条 旅游者与旅游经营者发生争议或者认为其合法权益受到侵害时，可以通过下列途径解决：\n（一）与旅游经营者协商；\n（二）向消费者协会、旅游投诉受理机构申请调解；\n（三）向公安、旅游、市场监督管理和物价等主管部门投诉；\n（四）旅游合同中约定有仲裁条款或者有书面仲裁协议的，提请仲裁机构仲裁；\n（五）向人民法院提起诉讼。","level":1},{"name":"第五章 旅游经营与服务","text":"第三十条 旅游经营者应当依法经营，遵守诚实守信、公平竞争的原则。\n旅游经营者和旅游从业人员已取得相应等级的，不得超越认证或者评定的等级进行宣传；未取得等级的，不得使用相应等级的标识和称谓。\n第三十一条 旅游经营者提供的旅游产品、服务和设施，应当符合国家标准、行业标准和地方标准。鼓励旅游经营者制定和实施严于国家标准、行业标准和地方标准的企业标准。\n第三十二条 旅游经营者从事旅游经营活动，应当遵守下列规定：\n（一）按照核定的经营范围开展活动，并在经营场所的醒目位置使用符合国家标准的公共信息图形符号，公示营业执照、经营许可证以及旅游咨询、投诉、救助电话等信息；\n（二）公开服务项目和收费标准，合理收费；\n（三）提供真实、准确的旅游服务信息，不得发布虚假广告或者进行虚假宣传，欺骗和误导旅游者；\n（四）对旅游者的个人信息予以保密；\n（五）按照约定的服务项目和服务质量标准提供安全卫生、质价相符的旅游服务，不得擅自改变服务项目，降低服务质量标准；\n（六）尊重旅游者自主选择商品和服务的权利，不得强制、纠缠、诱骗或者胁迫旅游者购买旅游商品和接受旅游服务；\n（七）法律、法规规定的其他行为。\n第三十三条 旅游经营者及其从业人员在旅游经营活动中应当向旅游者宣传旅游生态环境保护知识，引导旅游者健康、文明旅游，劝阻破坏旅游生态环境和违反社会公德的行为。\n第三十四条 旅游经营者的自主经营权受法律保护。旅游经营者有权拒绝违反法律、法规规定的收费、摊派和检查，有权拒绝旅游者违反法律、法规的要求。\n任何单位和个人不得非法获取、使用或者披露旅游经营者的营销计划、销售渠道、客户名单以及其他商业秘密。\n任何单位和个人不得阻碍外地旅游经营者进入本地旅游市场依法从事旅游经营活动。\n第三十五条 设立旅行社及其分支机构应当符合国家规定的条件，依法取得旅行社业务经营许可，并由旅游主管部门向社会公告。\n俱乐部、车友会、网络旅游经营者以及其他召集旅游者的单位和个人未取得旅行社业务经营许可的，不得从事旅行社业务。\n第三十六条 旅行社组织和安排旅游活动，应当与旅游者订立书面旅游合同，明确服务项目、质量、价格、违约责任等事项，并对旅游者需自行付费的项目进行约定。签订旅游合同，推荐使用旅游主管部门制定的合同示范文本。\n鼓励旅行社针对老年人、残疾人旅游需求和未成年人健康成长，推出经济实惠的旅游产品和服务项目。\n第三十七条 县级以上人民政府及其有关部门应当建立健全导游管理和评价制度，完善导游职级、服务质量与报酬相一致的激励机制，落实导游薪酬和社会保险制度。\n从事导游、领队业务的人员应当依法取得导游人员资格，并经旅行社委派，持证上岗，规范执业。\n第三十八条 支持旅行社参与政府采购和服务外包，接受国家机关、企业事业单位和社会团体的委托，为有关公务活动提供交通、住宿、餐饮、会务等服务。\n第三十九条 宾馆饭店适用一般工业企业相同的用水、用电、用气价格标准。\n第四十条 鼓励旅游经营者建立完善旅游电子商务平台，通过网络开展旅游信息发布、查询、预订等服务。\n网络旅游经营者应当按照规定在其网站主页醒目位置公开营业执照、许可证、支付方式、风险提示等信息，采取安全保障措施确保交易安全可靠；涉及由其他经营者实际提供服务的，应当从具有法定资质的旅游经营者中选择服务提供方，并向旅游者提供该经营者的名称、经营地址、联系方式等信息。\n公安、市场监督管理、旅游、经济和信息化、通信管理、金融等有关部门应当加强网络旅游经营管理，规范网络秩序。\n第四十一条 旅游经营者应当建立安全管理责任制和应急处置制度，配备旅游安全设施、设备和安全管理人员，保障旅游者人身、财产安全。\n旅游经营者经营潜水、漂流、蹦极、攀岩以及其他涉及人身安全的高风险旅游项目，应当符合国家有关安全标准，按照规定办理审批手续，并以明示的方式事先向旅游者作出说明或者警示。\n旅游经营者对发生的旅游安全事故应当及时采取救援措施，并向有关部门和事故发生地的人民政府报告。\n第四十二条 旅游经营者应当向合格的供应商订购旅游产品和服务。\n旅游经营者开展旅游活动租用客运车辆、船舶，应当选择具有相应资质的运输企业和已办理法定强制保险的车辆、船舶。\n承担旅游运输的车辆、船舶，应当配备符合规定的驾驶员、船员以及座位安全带、救生等安全设施设备，并不得超过核定的载客人数。\n第四十三条 景区应当设置区域界限标志、服务设施标志和游览导向标志。对具有危险性的区域和项目，应当设立明显的安全警示标志，并采取必要的防护措施。\n景区应当按照国家和省规定的标准，设置供水、供电、公共厕所等旅游配套服务设施，严格执行无障碍环境建设标准，完善语音提示、盲文提示等无障碍信息服务；加强老年人、残疾人、未成年人旅游服务设施建设，适当配备出行辅助器具。\n第四十四条 景区应当建立门票预约制度，制定游客流量控制方案，在旅游旺季通过旅游公共服务信息平台、游客服务中心以及景区入口处等，公布景区的实时流量和最大承载量，对景区游客进行最大承载量控制。游客数量可能达到最大承载量时，景区应当提前公告并向当地人民政府报告，及时采取疏导、分流等措施。\n景区应当对客运索道、大型游乐设施等旅游场所特种设备定期开展安全检测，向游客告知游览设施设备的最大承载人数并进行有效控制。\n第四十五条 景区票价应当与其规模、等级相适应，并保持合理、稳定。价格主管部门制定或者调整景区票价，应当征求同级旅游主管部门的意见，听取社会有关方面的意见，并按照规定召开听证会。\n利用公共资源建设的景区的门票以及景区内的游览场所、交通工具等另行收费项目，实行政府定价或者政府指导价；另行收费项目已收回投资成本的，应当相应降低价格或者取消收费。\n景区应当按照国家和省的有关规定，对老年人、残疾人、现役军人、儿童、学生等特定对象免费或者优惠开放，并明确标示减免票价的范围和标准。\n公益性的博物馆、图书馆、美术馆、爱国主义教育基地、科普教育基地、城市公园等，实行免费开放。\n第四十六条 景区管理机构应当统一管理景区范围内的旅游商品销售、餐饮、住宿、演艺等经营活动，加强景区内公共安全、环境与食品卫生的监督管理。","level":1},{"name":"第六章 旅游监督管理","text":"第四十七条 县级以上人民政府及其有关部门应当建立旅游市场综合治理机制，完善旅游联合执法体系，加强对旅游市场的管理和旅游服务质量的监督检查，依法查处旅游经营、服务中的违法行为，维护旅游市场秩序。\n第四十八条 县级以上人民政府应当加强对旅游安全工作的组织领导，建立旅游安全主体责任制，将旅游应急管理纳入政府应急管理体系，开展应急演练，健全旅游安全突发事件、高峰期大客流应对处置与救援机制，处理旅游突发事件；对旅游区域发生自然灾害、流行疾病或者其他可能危及旅游者人身财产安全的，及时发布旅游安全预警信息。\n第四十九条 省人民政府旅游主管部门和旅游地人民政府应当加强旅游信息化建设，建立全省及区域性旅游公共信息和咨询平台，健全旅游信息、咨询、救助等旅游公共服务体系，无偿向旅游者提供旅游景区、交通、气象、住宿、医疗急救、游客流量预警等旅游信息和咨询服务，实现智慧旅游。\n第五十条 县级以上人民政府旅游主管部门应当建立健全旅游标准化工作管理制度，开展旅游标准化的宣传和培训，加强监督检查，推动旅游业国家标准、行业标准和地方标准的贯彻实施。\n第五十一条 县级以上人民政府旅游主管部门及有关部门应当加强旅游市场诚信体系建设，建立和完善旅游相关企业、从业人员的诚信记录及违法信息共享机制，公开旅游企业资质、经营服务质量、失信惩戒记录等信息，公布严重违法企业和从业人员名单，保障旅游者知情权和监督权。\n鼓励和支持各类旅游行业协会对其会员企业实行诚信等级评定，建立行业诚信档案和行业诚信自律规则，促进旅游企业诚信经营。\n第五十二条 县级以上人民政府应当建立健全旅游投诉处理制度，指定或者设立统一的旅游投诉受理机构，公布旅游投诉监督电话、网站等，及时处理旅游投诉。\n旅游投诉受理机构收到投诉申请后，对符合受理条件的，应当在45日内处理完毕并告知投诉者；可以当场处理的，应当当场作出处理决定。对不符合受理条件的，应当在5日内通知投诉者并说明理由。对由其他主管部门处理的，应当即时移交有关部门处理并告知投诉者。","level":1},{"name":"第七章 法律责任","text":"第五十三条 违反本条例，法律、行政法规有规定的，从其规定。\n第五十四条 违反本条例规定，有下列情形之一的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）未按照规定执行旅游规划，造成旅游资源和生态环境破坏的；\n（二）未按照法定时限受理和处理旅游投诉或者未按照规定移送有关部门的；\n（三）向旅游经营者摊派费用，设置区域间旅游服务障碍的；\n（四）不依法履行旅游行政执法职责的；\n（五）其他滥用职权、玩忽职守、徇私舞弊的行为。\n第五十五条 旅游经营者在旅游经营活动中违反本条例，有下列行为之一的，按照以下规定予以处罚：\n（一）未取得等级而擅自使用等级标识、称谓的，由旅游主管部门责令改正，处1万元以上3万元以下罚款；逾期不改正的，由有关部门责令停业整顿。已取得相应等级，但使用等级标识、称谓不实的，由旅游主管部门责令改正，处2千元以上1万元以下罚款；逾期不改正的，降低或者取消所评定的等级；\n（二）使用不符合规定的车辆、船舶承担旅游运输的，由旅游主管部门责令改正，没收违法所得，处1万元以上5万元以下罚款；逾期不改正的，吊销业务经营许可证。旅游客运车辆、船舶超过核定载客人数的，由公安机关交通管理部门或者海事管理机构依法予以处罚；\n（三）强制、纠缠、诱骗或者胁迫旅游者购买商品、接受服务的，由旅游主管部门或者市场监督管理部门处2千元以上1万元以下罚款；情节严重的，处5千元以上2万元以下罚款。\n旅行社及导游有前款第三项行为的，依照有关法律、行政法规处罚。\n第五十六条 违反本条例规定，开发利用旅游资源未采取保护措施，造成生态环境或者人文资源破坏的，由旅游主管部门或者其他有关部门责令停止违法行为，恢复原状，依法予以处罚；构成犯罪的，依法追究刑事责任。\n第五十七条 旅游者破坏旅游资源、损坏旅游服务设施造成经济损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第五十八条 违反本条例规定，损害旅游者合法权益，造成旅游者人身伤害、财产损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附则","text":"第五十九条 本条例所称的旅游经营者，是指旅行社、景区、网络旅游经营者以及为旅游者提供交通、住宿、餐饮、购物、娱乐等经营服务的单位或者个人。\n第六十条 本条例自2015年6月1日起施行。","level":1}]},{"id":"h0119","sections":[{"name":"","text":"（2005年5月27日湖北省第十届人民代表大会常务委员会第十五次会议通过 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》修正）\n第一条 为了防御雷电灾害，保护公民的人身、财产安全和社会公共安全，促进经济建设和社会发展，根据《中华人民共和国气象法》和有关法律、法规，结合本省实际，制定本条例。\n第二条 本省行政区域内防御雷电灾害及其相关活动，适用本条例。\n本条例所称雷电灾害防御（以下简称防雷），是指对雷电灾害进行研究、监测、预警预报、防雷知识宣传教育，以及采用防雷装置，避免或者减轻雷电灾害的活动。\n第三条 县级以上气象主管机构负责本行政区域内防雷管理工作。未设气象主管机构的县（市、区）的防雷管理工作，由上一级气象主管机构负责。\n建设、规划、公安消防、工商行政管理、安全生产监督、质量技术监督等部门按照各自职责，协同做好有关防雷工作。\n第四条 防雷工作坚持安全第一、预防为主、防治结合原则。\n第五条 县级以上人民政府应当加强对防雷工作的领导，将防雷工作纳入当地经济和社会发展计划，制定并及时组织实施防雷应急预案和农村雷电灾害多发区的防雷措施，提高防雷能力。\n第六条 鼓励开展防雷科学技术和防雷新产品的研究、开发和推广应用，提高防雷技术水平。对在防雷工作中做出突出贡献的单位和个人，各级人民政府或者气象主管机构应当给予表彰和奖励。\n第七条 气象主管机构应当加强防雷科普教育的组织管理工作，利用各种形式和渠道定期开展公益性防雷知识宣传，增强公民的防雷意识。有关部门和新闻单位应当予以支持、配合。\n机关、企业、事业单位、群众性自治组织和社区，应当结合实际，做好本单位、本地方群众性的防雷知识宣传教育。\n第八条 气象主管机构应当组织对防雷技术和雷电监测预警系统的研究和开发，建立并完善雷电灾害监测、预警系统和工作规范，组织城乡雷电灾害调查、鉴定和评估，提高雷电灾害预警和防雷减灾服务能力。\n气象主管机构所属的气象台站应当开展雷电监测，及时向社会发布雷电预警预报。其他任何单位和个人不得向社会发布雷电预警预报。\n第九条 下列建（构）筑物、场所或者设施必须安装符合技术规范要求的防雷装置：\n（一）建筑物防雷设计规范规定的一、二、三类防雷建（构）筑物；\n（二）重要的计算机设备和网络系统、电力、通信、广播电视设施，重要的导航场所和设施；\n（三）易燃、易爆物品和化学危险物品的生产、储存设施和场所；\n（四）重要储备物资的库储场所；\n（五）法律、法规和规章规定应当安装防雷装置的其他场所和设施。\n前款规定范围以外的场所和设施，根据防雷安全的需要，可以安装防雷装置。\n第十条 必须安装防雷装置的新建、扩建、改建的建（构）筑物、场所和设施，建设单位应当将防雷装置的建设纳入计划，与主体工程或者整体项目同时设计、同时施工、同时投入使用。\n第十一条 从事防雷装置检测的企业和单位，必须具备相应的资质条件，并依照国家规定的资质认定权限取得省级以上气象主管机构颁发的资质证。禁止无资质或者超出资质范围承接防雷装置检测。\n防雷工程专业设计、施工、防雷装置检测必须执行国家防雷标准和技术规范。\n第十二条 依法必须安装防雷装置的，建设单位应当按照国家规定，将防雷设计文件和相关材料报送当地气象主管机构审核。气象主管机构应当依法出具审核意见。\n未经设计审核或者审核不合格的，建设单位不得开工建设。\n变更和修改防雷设计方案，应当重新报审。\n第十三条 气象主管机构应当按照国家有关规定受理防雷装置设计审核申请，并自受理申请之日起十个工作日内完成审核。\n第十四条 防雷工程的建设单位应当按照审核同意的设计方案进行施工，并根据施工进度，选择具有相应资质的防雷检测机构进行跟踪检测。防雷检测机构应当对隐蔽工程逐项检测，并对检测报告负责。检测报告作为竣工验收的技术依据。\n第十五条 依法必须安装的防雷装置竣工后，建设单位应当依照规定向当地气象主管机构申请验收。其中新建、改建、扩建的建筑工程竣工验收时，建设单位申请当地气象主管机构对其防雷装置同时进行验收。未经验收或者验收不合格的，建设单位不得投入使用。\n气象主管机构应当在受理验收申请之日起五个工作日内依法完成验收工作，出具验收结论，并建立验收档案。\n第十六条 防雷装置实行定期检测制度。依法必须安装的防雷装置每年检测一次，其中易燃、易爆物品和化学危险物品的生产、储存设施和场所的防雷装置每半年检测一次。\n第十七条 防雷检测机构应当在资质核定的范围内进行检测，并对检测报告负责。在检测中发现雷电灾害事故隐患的，应当及时通知委托单位，并向气象主管机构报告。\n第十八条 防雷装置使用单位应当定期委托防雷检测机构进行检测，做好防雷装置的日常维护，发现事故隐患应当及时采取措施修复或者更换。任何单位和个人不得损毁或者随意变动防雷装置。\n第十九条 防雷产品应当符合国家质量标准，并具有产品合格证书和使用说明书。\n禁止生产、销售不符合国家强制性标准或者国家明令淘汰的防雷产品。\n第二十条 遭受雷电灾害损失的单位和个人，应当及时向当地气象主管机构报告，并协助当地气象主管机构对雷电灾害情况的调查和鉴定。气象主管机构应当按照规定向当地人民政府和上级气象主管机构及时报告雷电灾情。\n第二十一条 气象主管机构及其工作人员有下列行为之一的，由主管机构责令改正，并可对直接负责的主管人员或者直接责任人员给予行政处分；触犯法律的，依法承担相应的法律责任：\n（一）违反规定发放防雷装置检测资质证书的；\n（二）违反法定程序和技术规范对防雷装置设计进行审核的；\n（三）违反法定程序和技术规范对防雷装置进行竣工验收的；\n（四）有其他徇私舞弊、玩忽职守、滥用职权行为的。\n第二十二条 违反本条例规定，有下列行为之一的，由县级以上气象主管机构按照权限责令限期改正，给予警告；逾期仍不改正的，可处1千元以上3万元以下的罚款；给他人造成损失的，依法承担赔偿责任：\n（一）依法必须安装防雷装置而未安装的；\n（二）防雷装置设计未经审核或者审核不合格擅自施工的；\n（三）防雷装置竣工后未经验收或者验收不合格投入使用的；\n（四）拒绝接受法定防雷检测机构对防雷装置依法实施的检测，或者擅自变动、损毁防雷装置的。\n第二十三条 违反本条例规定，未取得防雷装置检测资质以及超出资质范围开展业务的，由县级以上气象主管机构责令停止违法行为，没收违法所得，并可处1千元以上1万元以下的罚款；给他人造成损失的，依法承担赔偿责任。\n第二十四条 从事防雷装置检测的单位，出具虚假检测报告的，由县级以上气象主管机构责令改正，给予警告；拒不改正的，撤销其防雷装置检测资质；给他人造成损失的，依法承担赔偿责任。\n第二十五条 对违反本条例的行为，法律、行政法规已有处罚规定的，从其规定。\n第二十六条 本条例自2005年8月1日起施行。","level":0}]},{"id":"h0120","sections":[{"name":"","text":"（2005年11月26日湖北省第十届人民代表大会常务委员会第十八次会议通过）\n第一条 为了加强对企业负担的监督，维护企业的合法权益，促进经济发展，根据国家有关法律、法规，结合本省实际，制定本条例。\n第二条 本条例所称企业负担监督是指对国家机关、组织、事业单位及其工作人员违反法律、法规和规章规定，增加企业人力、财力和物力负担的行为的监督。\n第三条 县级以上人民政府应当加强对企业负担监督工作的领导，建立和完善企业负担监督的规章制度，组织、协调和督促有关部门依法做好企业负担的监督工作。\n省人民政府根据本条例可以制定企业负担监督的具体办法。\n第四条 省人民政府的经济委员会主管全省企业负担监督工作，市、州、县（区）人民政府经济（经贸）委员会（局）主管本行政区域内企业负担监督工作（以下简称企业负担监督主管部门）。\n企业负担监督主管部门履行下列职责：\n（一）监督检查涉及企业负担的法律、法规、规章以及其他规范性文件的执行情况，并就企业负担监督工作向同级人民政府提出建议；\n（二）受理有关企业负担的举报、投诉，提出意见移交有关部门处理，并组织查处重大复杂的举报、投诉；\n（三）督促、协调同级人民政府有关部门、下一级人民政府及其企业负担监督主管部门查处增加企业负担的案件。\n第五条 县级以上人民政府的财政、物价、监察、审计等部门应当加强与企业负担监督主管部门的配合，并按照各自的职责，依法做好企业负担监督查处工作。\n第六条 县级以上人民政府及其他国家机关、组织制定规范性文件，应当以法律、法规为依据，不得作出损害企业合法权益的规定。\n企业认为人民政府及其他国家机关、组织制定的规范性文件侵犯其合法权益的，可以依法要求制定机关和其他有关机关对规范性文件予以审查。\n第七条 下列涉及企业负担的事项，应当有法定依据；没有依据的，予以监督纠正：\n（一）涉及企业的行政事业性收费，以法律、法规、国务院及其财政、物价部门以及省人民政府的规定为依据，省人民政府所属工作部门和市、州、县（区）人民政府及其所属工作部门、乡（镇）人民政府无权自行设立；\n（二）涉及向企业收取的政府性基金，以法律、行政法规、国务院及其财政部门的规定为依据，地方各级人民政府及其所属工作部门无权自行设立；\n（三）涉及企业的集资，以法律、行政法规、国务院规定为依据，地方各级人民政府及其所属工作部门无权自行设立。\n第八条 省人民政府企业负担监督主管部门应当会同省财政、物价部门定期或者不定期对正在实施的涉及企业的行政事业性收费、政府性基金、集资项目及其标准进行清理审查，并将依法保留的项目列出目录，向社会公布；未列入目录的项目，一律不得实施，企业有权拒绝。\n第九条 对企业实施行政事业性收费时，实施机关工作人员应当出示物价部门颁发的收费许可证及收费依据，并出具省财政部门统一印制的行政事业性收费票据。\n第十条 企业对收费的项目、依据和标准有异议的，有权要求实施收费的机关予以说明，也可以向企业负担监督主管部门或者财政、物价部门查询，有关部门应当提供便利。实施收费的机关不能提供合法依据，或者企业负担监督主管部门及财政、物价部门对收费依据的合法性予以否定的，企业有权拒绝。\n第十一条 对企业实施行政处罚、行政许可，应当有法律、法规和规章依据。行政处罚应当在法定的行为、种类、幅度范围内实施；实施行政许可的，除法律、行政法规另有规定外，不得收取费用。\n第十二条 对企业实施行政处罚时，实施机关工作人员应当出示行政执法证件及处罚依据，并符合《中华人民共和国行政处罚法》和相关法律法规规定的程序；实施罚款的，应当出具省财政部门统一印制的票据。\n第十三条 行政机关对企业进行检查，应当以法律、法规为依据。\n各级人民政府及有关部门应当建立和完善对企业的检查制度，避免重复检查、多头检查。县级以上人民政府对所属工作部门开展的检查进行统筹安排和协调监督；实行垂直管理体制的行政机关的检查由其上一级机关予以协调监督。国家统一部署实施的全国性检查或者处理突发事件、查处违法案件的除外。\n第十四条 行政机关对企业进行检查时，执法人员应当出具检查通知书，并出示行政执法证件。检查通知书应当包括检查的依据、内容、时限以及实施检查的人员等内容。\n行政机关实施监督检查，不得妨碍企业正常的生产经营活动，不得索取或者收受企业的财物，不得谋取其他利益。\n企业在生产经营中，应当遵守法律法规，对行政机关依法实施的监督检查应当予以支持配合，不得无理拒绝或者抗拒。\n第十五条 邮政、电信、广播电视、铁路、公路、民航、供电、供水、供气等公用企业事业单位，应当严格执行国家和省物价部门批准的价格标准、价格政策，不得擅自提高商品和服务的价格。\n第十六条 企业有权自主选择有执业资格的社会中介机构为其提供服务。\n国家机关不得强制企业接受其指定的社会中介机构提供的服务。\n社会中介机构应当严格执行国家和省物价部门制定的价格政策，不得擅自提高收费标准。\n第十七条 禁止国家机关、组织、事业单位及其工作人员违反法律、法规实施下列增加企业负担的行为：\n（一）无偿占有、使用或者低价购买企业的产品、房产、汽车等财物和劳务，拖欠企业款项；\n（二）向企业索要财物或者要求报销各种费用、提供办案经费；\n（三）强制或者变相强制企业提供赞助、资助或者捐献财物；\n（四）强制企业刊登广告和参与有偿宣传报道或者订购和参编报刊、图书、音像资料等；\n（五）强制企业购买指定商品或者接受指定的检测、咨询、信息、商业保险等服务；\n（六）强制企业参加学会、协会、研究会以及培训、展览、考核、评比、达标并支付费用等活动；\n（七）要求企业为其他单位或者个人的债务提供担保；\n（八）违法增加企业负担的其他行为。\n第十八条 对违法增加企业负担的行为，企业有权向县级以上人民政府企业负担监督主管部门或者财政、物价、监察、审计等部门举报、投诉。\n任何单位和个人有权对增加企业负担的违法行为进行举报、投诉。\n第十九条 县级以上人民政府企业负担监督主管部门和财政、物价、监察、审计等部门应当建立和完善受理企业负担监督举报、投诉制度，完善举报、投诉信息网络，加强相互之间的协调、配合。\n企业负担监督主管部门应当向社会公布企业负担监督举报、投诉电话和网站等举报、投诉方式。\n第二十条 有关行政机关收到举报、投诉后，应当在5个工作日内作出受理或者不受理的决定。决定受理的，应当限时作出处理决定；决定不予受理的，应当向举报、投诉者说明理由；对应当由其他机关受理的举报、投诉，一般自收到举报、投诉之日起3个工作日内移送其他有权受理的机关。\n涉及两个以上行政机关有权受理的举报、投诉事项，由先收到举报、投诉的行政机关处理，也可以会同有关行政机关处理。\n第二十一条 举报、投诉事项办结后，有关行政机关应当将办理结果以书面或者口头方式告知举报、投诉者。\n对重大举报、投诉事项的处理结果，可以通过新闻媒体及时向社会予以曝光。\n第二十二条 举报、投诉者对举报、投诉事项的处理结果有异议的，可以向作出处理决定机关的上一级行政机关申请复查。上级行政机关认为下级行政机关对举报、投诉事项的处理确有不当的，可以重新处理或者责令下级行政机关重新处理。\n第二十三条 被举报、投诉的单位及其工作人员，在接受有关行政机关调查时，应当如实反映情况，不得阻扰和拒绝调查工作，不得打击报复举报、投诉者。\n有关行政机关应当为举报、投诉者保密。\n第二十四条 对违反本条例规定，违法增加企业负担的单位和个人，由县级以上人民政府企业负担监督主管部门或者有关部门责令改正，对单位给予通报批评，并由主管机关或者监察机关对负有直接责任的主管人员和其他直接责任人员给予行政处分；给企业造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第二十五条 妨碍企业负担监督主管部门及有关部门依法查处违法增加企业负担行为的，或者对举报、投诉违法增加企业负担的单位、个人进行打击报复的，由主管机关或者监察机关依法给予行政处分；违反治安管理法律法规的，由公安机关给予行政处罚；构成犯罪的，依法追究刑事责任。\n第二十六条 企业负担监督主管部门及有关部门不履行或者不正当履行企业负担监督职责的，由同级人民政府或者上一级主管机关给予通报批评，对负有直接责任的主管人员和其他直接责任人员给予行政处分。\n第二十七条 国家机关工作人员在查处违法增加企业负担行为时玩忽职守、滥用职权、徇私舞弊的，由其主管机关或者监察机关给予行政处分；构成犯罪的，依法追究刑事责任。\n第二十八条 本条例自2006年2月1日起施行。","level":0}]},{"id":"h0121","sections":[{"name":"","text":"（2005年11月26日湖北省第十届人民代表大会常务委员会第十八次会议通过 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第三次修正）\n第一条 为了加强对文物的保护、利用和管理，促进我省经济社会协调发展，根据《中华人民共和国文物保护法》和有关法律、法规，结合本省实际，制定本办法。\n第二条 本省行政区域内属于《中华人民共和国文物保护法》第二条规定的文物和具有科学价值的古脊椎动物化石和古人类化石的保护、利用和管理适用本办法。\n第三条 各级人民政府负责本行政区域内的文物保护工作，并将其纳入国民经济和社会发展规划，制定文物保护及文物事业发展的任务、目标和措施。\n县级以上人民政府文物行政部门对本行政区域内的文物保护实施监督管理，并对相关部门的文物保护工作予以指导。\n公安、工商行政、海关、国土资源、建设规划、交通、旅游、宗教等行政管理部门，应当在各自的职责范围内依法做好文物保护工作。县级以上各级人民政府根据需要，建立协调工作机制，加强对文物保护工作的领导。\n第四条 县级以上人民政府应当将文物保护经费列入本级财政预算，并随着财政收入增长而增长。\n第五条 各级人民政府及其有关部门应当加强文物保护的宣传教育，增强全民文物保护意识。\n鼓励公民、法人和其他组织依法以捐赠、展览、珍藏等形式，支持和参与文物保护事业。对文物保护事业作出突出贡献的单位和个人，由当地人民政府或者文物行政部门和其他有关部门给予表彰或者奖励。\n第六条 市、县级文物保护单位由本级人民政府核定公布，并报省人民政府备案；省级文物保护单位，由省人民政府核定公布，并报国务院备案；全国重点文物保护单位的核定公布，按照国家有关规定执行。\n尚未核定公布为文物保护单位的不可移动文物，由县级文物行政部门组织调查和审核，予以登记并公布。\n文物保护单位核定公布后，应当依法划定保护范围和建设控制地带，作出标志说明，建立记录档案，并区别情况设置专门机构或者指定专人负责管理。\n文物保护单位保护范围、建设控制地带的划定和保护，应当列为本行政区域城乡建设总体规划和详细规划的内容。\n第七条 文物保护单位保护范围和建设控制地带内的下列要素应当予以保护：\n（一）组成文物保护单位的各单体建筑物、构筑物、附属建筑、古建筑构件、碑刻、墓葬、遗址、古树名木；\n（二）附着于文物保护单位与其同期或者后期添加的、确有保存意义的雕塑、装饰、题记、加固或者改建物；\n（三）建设控制地带以内与文物保护单位相关的历史建筑物、纪念建筑物、街区及其他人文和自然环境风貌等。\n第八条 国务院核定公布的历史文化名城、省人民政府核定公布的历史文化街区、村镇，其所在地人民政府应当全面规划，采取有效措施，加强管理和保护。\n世界文化遗产所在地的县级以上人民政府应当加强对本行政区域内的世界文化遗产的保护，按照世界文化遗产保护国际公约和国家有关规定制定保护规划和保护措施，并公布实施。\n第九条 在文物保护单位的保护范围内，除因特殊情况需要按照法定程序报经批准外，不得进行与文物保护无关的建设工程，不得进行爆破、钻探、挖掘等作业。\n在文物保护单位的建设控制地带内，不得建设危及文物安全的设施，不得修建与文物保护单位的历史风貌和环境风貌不相协调的建筑物或者构筑物；工程设计方案应当根据文物保护单位的保护级别，经相应的文物行政部门同意后，报建设规划行政部门批准。\n对文物保护单位保护范围和建设控制地带内已有的危及文物保护单位安全、污染文物保护单位及其周边环境、影响文物保护单位历史风貌及景观的设施，所在地人民政府应当采取措施限期治理。\n第十条 建设工程选址，应当避开文物保护单位；因重大特殊情况不能避开的，应当实施原址保护；无法实施原址保护、必须进行迁移或者拆除的，应当依照有关法律、法规的规定进行。\n尚未核定公布为文物保护单位的不可移动文物，需要迁移异地保护或者确需拆除的，应当报省文物行政部门批准。\n需要迁移异地保护的不可移动文物的搬迁与复建，应当做好资料记录，制订保护方案，落实复建地址和经费。搬迁与复建工作应当同步进行，并由省文物行政部门组织验收。\n第十一条 非国有不可移动文物有损毁危险的，所有人应当采取积极保护措施，不具备修缮能力的，当地人民政府应当给予帮助；所有人具备修缮能力而拒不依法履行修缮义务的，县级以上人民政府可以给予抢救修缮，所需费用由所有人负担。\n县级以上人民政府根据文物保护的需要，并与非国有不可移动文物的所有人协商，可以置换或者征购其所有的不可移动文物。\n第十二条 文物保护单位的修缮、抢险加固，应当根据文物保护单位的级别报相应的文物行政部门批准；变更修缮、抢险加固方案的，必须经原审批机关批准。\n文物保护单位的修缮、迁移、重建，应当由取得文物保护资质证书的单位承担勘察设计、施工、监理。\n第十三条 国有不可移动文物不得转让、抵押。建立博物馆、保管所或者辟为参观游览场所的国有文物保护单位，不得作为企业资产经营；其门票收入，应当用于文物保护。\n使用不可移动文物，必须遵守不改变文物原状的原则，并依法接受文物行政部门的管理、监督。\n第十四条 一切考古发掘，必须经过省文物行政部门报国务院文物行政部门或者国务院批准后方可进行。\n除国务院文物行政部门按规定调用重要出土文物外，本省境内考古发掘的出土文物统一由省文物行政部门指定国有文物收藏单位收藏。\n第十五条 进行大型基本建设工程，建设单位应当事先报请省文物行政部门组织从事文物考古发掘的单位在工程范围内有可能埋藏文物的地方进行考古调查、勘探。\n在工程建设、生产活动以及房屋拆迁过程中发现文物或者可能属于文物的，施工、生产单位和个人必须及时停止施工、生产，保护现场，并立即报告当地文物行政部门。文物行政部门接到报告后，如无特殊情况，应当在24小时内赶到现场，并在7日内提出处理意见；发现重要文物的，应当立即上报国务院文物行政部门。当地公安机关应当协助做好现场安全保卫工作。\n需要考古发掘的，文物行政部门应当依照法定程序迅速组织考古发掘，考古发掘结束后应当立即通知恢复施工、生产。\n任何单位和个人不得阻扰文物行政部门和考古发掘单位及其工作人员依法进行调查、勘探和考古发掘工作。\n第十六条 因基本建设和生产建设需要而进行的考古调查、勘探、发掘，所需费用列入建设工程预算，由建设单位支付。具体支付标准和办法由省财政、价格主管部门会同文物行政部门制定。\n第十七条 古墓葬、古文化遗址保护范围内原已建成的工程设施和建设项目，不得再行增加建设项目和扩大生产规模。因生产活动可能造成对重要文物破坏的，所在地县级以上人民政府及其文物行政部门应当督促该生产单位及其上级主管部门采取措施，确保文物安全。\n古墓葬、古文化遗址保护范围内已经开辟有耕地的，在生产、生活活动中应当接受文物行政部门的指导、管理，保护好自然植被，防止水土流失。对文物埋藏较浅的耕地，地方人民政府应当采取措施，实行退耕保护。\n第十八条 设立博物馆以及具有博物馆性质的纪念馆、陈列馆等文物收藏单位，应当以收藏、展示文物和进行相关科学研究为主要目的，并具备以下条件：\n（一）有固定的场所、库房；\n（二）有必要的经费来源；\n（三）有一定数量的藏品；\n（四）有与文物收藏任务相适应的专业技术人员；\n（五）有符合规定的安全、消防设施并达到风险等级防护标准；\n（六）法律、法规规定的其他条件。\n设立文物收藏单位，应当报省文物行政部门备案。\n第十九条 博物馆、纪念馆、陈列馆和其他文物收藏单位对收藏的文物，应当按照国家有关规定区分等级，设置藏品档案，并报主管的文物行政部门备案。馆藏文物等级区分不准确、文物藏品档案不完整的，文物行政部门应当责令其改正。\n凡不具备收藏珍贵文物条件的国有文物收藏单位，其收藏的珍贵文物，文物行政部门可以指定具备条件的国有文物收藏单位代为收藏。文物收藏单位与代为收藏单位的权利和义务由双方协商确定。\n文物收藏单位可以根据其收藏的性质和任务征集藏品。\n第二十条 文物收藏单位的法定代表人对馆藏文物的安全负责。国有文物收藏单位应当定期对馆藏文物进行清查盘点。国有文物收藏单位的法定代表人离任时，必须按照馆藏文物档案办理馆藏文物移交手续，并由主管的文物行政部门作出书面检查结论。\n未经国务院文物行政部门或者省文物行政部门批准，任何单位或者个人不得调取国有文物收藏单位馆藏文物。\n国有文物收藏单位经批准进行文物调拨、交换、出借所得的补偿费用，必须用于改善文物的收藏条件和征集文物，任何单位或者个人不得侵占、挪用。\n第二十一条 复制、拓印、修复馆藏一级文物的，应当报国务院文物行政部门批准；复制、拓印、修复馆藏二级文物、三级文物的，应当报省文物行政部门批准。\n从事文物复制、拓印、修复的，应当报省文物行政部门批准，取得相应等级的资质证书，并由文物行政部门统一管理。文物复制品应当作出复制的标识、说明；不得以文物复制品冒充文物或者以文物仿制品冒充文物复制品，进行销售和宣传。\n第二十二条 文物保护单位在条件具备、保障文物安全的前提下，应当辟为参观游览场所，向公众开放。开放内容和接待容量应当根据其总体保护规划确定。\n文物收藏单位应当采取多种形式，陈列、展示所收藏的文物。国有文物收藏单位应当对学生、现役军人、老年人、残疾人等特殊社会群体实行门票减免。\n文物行政部门应当向社会提供必要的文物资源信息，并对文物利用进行指导和监督。\n第二十三条 设立文物商店，应当依照法律、行政法规的规定，办理工商营业执照，报省文物行政部门批准。\n依法设立的拍卖企业经营文物拍卖的，应当取得省文物行政部门颁发的文物拍卖许可证。\n文物商店应当对购买、销售的文物做出记录，并于购买、销售之日起3个月内向原审核的文物行政部门备案；文物拍卖企业应当对拍卖的文物做出记录，并将拍卖的文物记录于拍卖结束之日起3个月内向原审核的文物行政部门备案。\n第二十四条 文物收藏单位以外的公民、法人和其他组织可以通过依法继承或者接受赠与、从文物商店购买、文物拍卖企业拍卖、相互交换或者依法转让等合法方式取得文物，其收藏的文物可以依法流通，但法律、法规禁止流通的文物除外。\n第二十五条 县级以上人民政府应当将保证文物安全纳入领导责任制，古墓葬、古文化遗址保护任务较重的地方应当建立县、乡、村三级文物保护责任制。文物保护单位和文物收藏单位应当建立健全安全保卫及消防安全责任制。\n重要的文物保护单位和文物收藏单位应当设置安全保卫组织或者配备专门人员，负责文物的安全保卫工作，并接受公安机关的业务指导和监督。\n古墓葬、古文化遗址保护任务较重地方的县级人民政府，应当聘请适当数量的看护古墓葬、古文化遗址的人员，并给予经费补助。\n县级以上文物行政部门应当设立并向社会公布文物保护举报电话，及时受理文物保护、文物管理、文物安全等方面的投诉。\n第二十六条 文物保护单位和文物收藏单位的安全消防设施应当达到相应的风险等级防护标准，并做好设备器材的更新和定期维护工作。\n文物古建筑内禁止存放易燃、易爆物品。\n在属于文物保护单位的宗教活动场所内焚香、化纸、燃烛、燃灯的，应当在指定地点进行，并设专人管理。\n第二十七条 文物出境、入境应当按照法律、法规规定的程序办理。\n海关、公安、工商行政部门和其他机关依法收缴的文物，应当在结案后3个月内无偿移交文物行政部门依法处理。\n第二十八条 为制作出版物、音像制品，或者因新闻宣传、科学研究等需要拍摄馆藏文物和文物建筑的，拍摄单位应当服从文物行政部门监督管理，确保文物安全。\n第二十九条 违反本办法，造成文物灭失、损毁的，依法承担赔偿、修复等民事责任；依照有关法律、法规，应当由文物、建设规划、工商行政、公安等行政部门予以处罚的，从其规定；破坏、盗窃、盗掘、走私、非法侵占和出售文物等构成犯罪的，由司法机关依法追究刑事责任。\n第三十条 违反本办法第十五条，在工程建设、生产活动以及房屋拆迁过程中发现文物或者可能属于文物，在文物行政部门通知停工后仍强行施工、生产，或者在考古发掘结束前擅自恢复施工、生产的，由文物行政部门予以制止，责令采取补救措施；尚未造成严重后果的，由县级以上文物行政部门处以5千元以上5万元以下罚款；造成严重后果的，处以5万元以上50万元以下罚款。\n海关、公安、工商行政部门依法没收的文物，逾期不按规定移交的，由同级人民政府责令其限期移交，并可对负有责任的主管人员和其他直接责任人员给予行政处分。\n文物行政部门以及公安、工商行政、海关、建设规划等部门，违反本办法玩忽职守、滥用职权、徇私舞弊，造成珍贵文物损毁或者流失的，对负有责任的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。\n第三十一条 本办法自2006年2月1日起施行。湖北省第六届人民代表大会常务委员会第十八次会议通过、1993年9月20日湖北省第八届人民代表大会常务委员会第三次会议修正的《湖北省文物保护管理实施办法》同时废止。","level":0}]},{"id":"h0122","sections":[{"name":"","text":"（2016年2月27日长阳土家族自治县第八届人民代表大会第六次会议通过 2016年5月26日湖北省第十二届人民代表大会常务委员会第二十二次会议批准 根据2022年2月15日长阳土家族自治县第十届人民代表大会第二次会议通过 2022年5月26日湖北省第十三届人民代表大会常务委员会第三十一次会议批准的《长阳土家族自治县人民代表大会关于修改、废止部分单行条例的决定》修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了科学地制定和实施城镇规划，加强城镇建设和管理，创造整洁、优美、文明的环境，促进经济社会全面协调可持续发展，根据有关法律、法规和《长阳土家族自治县自治条例》，结合自治县实际，制定本条例。\n第二条 自治县城镇规划区内的规划建设和市政公用设施、园林绿化、市容环境卫生等方面的管理，适用本条例。\n第三条 本条例所称城镇，是指按照行政建制设立的镇。\n本条例所称城镇规划，是指自治县政府所在地镇规划区（以下简称“自治县城区”）和建制镇规划区。\n第四条 自治县城镇规划和建设，应当根据经济、社会发展需要、历史文化特点和自然环境，统一规划、合理布局，节约利用土地、保持民族和地方特色。\n第五条 自治县人民政府将城镇规划与建设纳入国民经济和社会发展规划，实行统一领导、分级负责的管理体制。\n城镇维护建设资金应当纳入财政预算，足额用于城镇建设并可以依法多渠道、多形式筹措资金，加大对城镇建设的投入。\n第六条 自治县人大常委会每年听取和审议县人民政府城镇规划建设管理工作报告；对城镇规划建设管理工作进行评议；对规划批准以后改变容积率、用地性质等其它重大事项听取和审议专项报告，必要时作出相应的决议决定。\n第七条 自治县自然资源和规划部门负责自治县城乡规划管理工作。自治县住房和城乡建设部门负责城乡建设管理工作。自治县城市管理执法部门负责市政公用设施、园林绿化、市容环境卫生管理工作，并依照有关法律法规规定开展城市管理执法。\n公安、市场监督管理、卫生健康、生态环境、交通运输等有关部门依照各自职责，做好城镇建设管理工作。\n建制镇人民政府负责本辖区城镇管理工作。城镇规划区内的居民委员会、村民委员会应当协助当地人民政府和有关部门做好所在地城镇建设管理的具体工作。\n第八条 首先接到举报的自然资源和规划部门、城市管理执法部门、乡镇人民政府为首问责任机关，应当依法及时处理。对于不属于其管辖范围的，应当在三日以内移交法定职能部门管辖。\n第九条 自治县鼓励自治县内外公民、法人和其他组织投资参与自治县城镇建设，并依法保护其合法权益。\n第十条 城镇规划区内的所有单位和个人都有维护城镇规划、市政公用设施、园林绿化以及市容环境卫生的义务，并有权举报、投诉违反城镇建设管理规定的行为。自治县城市管理执法部门应当建立违法举报平台，查证属实的，对举报者予以奖励。\n任何单位和个人都应当尊重市容环境卫生工人的劳动，不得妨碍、阻挠其正常工作。\n第十一条 自治县、建制镇人民政府对在城镇建设管理工作中作出显著成绩的单位和个人给予表彰和奖励。","level":1},{"name":"第二章 规划建设管理","text":"第十二条 自治县城区总体规划由自治县人民政府组织编制，经自治县人大常务委员会审查同意后，按照法定程序上报审批。其他建制镇的总体规划，由建制镇人民政府会同自治县自然资源和规划部门组织编制，经镇人民代表大会审议后，报自治县人民政府审批。\n自治县城区控制性详细规划由自治县自然资源和规划部门组织编制，报自治县人民政府审查批准。其他建制镇的控制性详细规划由镇人民政府组织编制，自治县自然资源和规划部门给予业务指导，报自治县人民政府批准。\n城镇规划经批准后，任何单位和个人不得擅自变更，确需调整的，由原制定机关按照规定程序办理。\n城市规划、城市管理相关规定应当依法向社会公开。\n第十三条 编制城镇规划应当对道路、港口、供水、供电、供气、消防、通信、文化、体育、广播电视、园林绿化、环境卫生、集贸市场、停车场、视频监控、垃圾处理、污水排放、公厕等设施的布局和建设统筹合理规划。任何单位和个人不得侵占规划用于上述设施建设的土地，不得改变规划用于上述设施建设的土地的用途。\n自治县住房和城乡建设部门应当根据城镇规划，遵循节约、便民的原则，合理有序安排前款所列设施的建设，有关单位和个人应积极配合、服从安排，避免重复开挖道路、浪费资源等现象发生。\n第十四条 自治县、建制镇人民政府在规划和建设中应当保护、支持具有民族特点的公用设施和民居等建筑，逐步形成自治县整体建筑的民族文化风格。\n第十五条 城镇规划区内的各项建设，必须依法取得建设用地规划许可证、建设工程规划许可证和建设工程施工许可证。以划拨方式提供国有土地使用权的，还应申请核发选址意见书。各类证书不得买卖或者转让。\n建设单位和个人从取得建设用地规划许可证之日起二年内未办理用地手续或者取得建设工程规划许可证之日起二年未动工兴建的，且未办理延期手续的，所取得的证书自行失效。\n第十六条 建设用地规划许可证和建设工程规划许可证核定的位置、范围、标高、建筑面积等内容不得擅自变更；确需变更的，须经原核发单位同意并办理有关手续。\n第十七条 禁止在城镇规划区非居住用地范围内建设单门独院式住宅。在城镇规划区居住用地范围内，农村村民在集体所有的土地上建设个人住宅的，建设用地每户不得超过140平方米。城镇居民建设个人住宅的，建设用地每户不得超过100平方米，不得占用集体土地。\n第十八条 城镇规划区内新建、改建、扩建各类建筑物，不得影响相邻建筑物的供水、排水、通风、采光和通行，不得影响文物古迹安全，不得破坏文物保护单位的环境风貌。\n任何单位和个人未经批准，不得占用公共空间在屋顶加层或者依附主体建筑搭建建筑物、构筑物。\n第十九条 在城镇规划区内，任何单位和个人不得占用或填堵河道、沟叉，不得占用河岸、水面搭建设施从事餐饮娱乐和水产养殖等活动。河道沿岸建设，应当服从防洪、绿化、环保和文物保护的要求。\n第二十条 在城镇规划区内从事开矿、采石、打井、挖砂取土、堆积渣土、填占水面等改变地形地貌的活动，必须经有关主管部门批准。\n第二十一条 在城市规划区内，禁止在公墓和农村的公益性墓地以外的其他任何地方埋葬遗体、建造坟墓。\n禁止占用耕地建造坟墓。\n第二十二条 经批准修建的临时建筑，使用期不得超过二年。确需延期的，可依法申请延期一年。\n第二十三条 禁止在室内装饰装修活动中改变建筑结构及有其他影响房屋使用安全的行为。搭建建筑物、构筑物，或者改变住宅外立面，在非承重外墙上开门窗的，应报经自治县自然资源和规划部门批准。","level":1},{"name":"第三章 市政公用设施管理","text":"第二十四条 城镇街道应当按照规定设置街名标志、照明、通信、交通、消防、环境卫生、视频监控等公共设施，任何单位和个人不得擅自移动、拆除或者损坏。\n依附于城镇道路建设的供电、供水、供气、通信、有线电视等各种管线、杆线设施，应当坚持先地下、后地上的施工原则，经自治县住房和城乡建设部门批准后，与道路同步建设。管线、杆线设置应当整齐有序，规范安装。\n城镇市政公用设施相关管理机构应当定期对市政公用设施进行维护或者更新，保持整洁、完好。\n第二十五条 任何单位和个人不得随意挖掘或者占用城镇道路、广场、防洪堤、停车场、绿地及供水、排水、供电、供气、通信等附属设施用地。确需要挖掘或临时占用的，必须按规定程序报经自治县城市管理执法部门或有关主管部门批准，并依法缴纳占用费或者挖掘修复费方可施工。\n新建、改建、扩建的城镇道路交付使用后五年内，大修的城镇道路竣工后三年内不得挖掘。因特殊情况需要挖掘的，须经自治县人民政府批准。\n依附于城镇道路的地下管线，因发生故障需要紧急抢修的，可先破路抢修，并及时办理审批手续，抢修完工后立即修复，保证路面质量和畅通。\n第二十六条 任何单位和个人未经批准，不得在城镇规划区内的桥梁、涵洞及其设施范围内挖砂取土、堆放物件、搭建设施和进行各种作业。\n第二十七条 履带车、铁轮车或超重、超高、超长车辆因特殊情况需要在城市道路上行驶的，须先经相关部门批准，通过城镇道路时应采取必要的保护措施，在不损坏道路及其设施的前提下，按指定的路线和时间通过。\n在城镇营运的机动车和非机动车应在规定的站、点、路段停靠或搭载乘客。\n禁止利用机动车或非机动车占用城镇道路进行销售、收购或者加工等活动。\n第二十八条 城镇规划区内的单位或者个人应当负责本单位和住宅相关排水设施的维修和养护，保持排水设施畅通。\n新建、改建、扩建工程需接通城镇排水设施和变更排水条件的，应当按照有关规定办理审批手续。\n任何单位和个人不得向排水设施、检查井、雨水口内倾倒垃圾、粪便、渣土以及有毒、有害、易燃易爆物质。\n第二十九条 禁止下列影响市政公用设施安全使用的行为：\n（一）损坏市政公用设施；\n（二）干扰市政公用设施正常运行；\n（三）擅自连接或者移动各种市政公用设施；\n（四）擅自在市政公用设施保护范围内进行施工或者堆放物料；\n（五）其他影响市政公用设施安全使用的行为。","level":1},{"name":"第四章 园林绿化管理","text":"第三十条 城镇规划区内的园林绿化管理按下列规定实施：\n（一）县城区内的公共绿地、风景林地、行道树及干道绿化带由园林绿化部门负责管理；其他建制镇的绿化由该建制镇人民政府负责管理。\n（二）公路、河道、铁路两侧的绿化由有关主管部门负责管理。\n（三）单位附属绿地和单位管界内的防护绿地由单位负责管理。\n（四）住宅区绿地由住宅区物业管理机构负责管理。\n第三十一条 城镇规划区内的古树名木实行专业养护机构保护管理和责任单位、责任人保护管理相结合的原则。园林绿化管理机构应按实际情况分株制定养护、管理方案，落实养护责任单位、责任人，并进行检查指导。\n禁止任何单位和个人擅自砍伐或者移植古树名木。\n第三十二条 城镇规划区内新建、改建、扩建工程建设项目，应当将园林绿化与主体工程项目同时规划、立项、设计和建设。\n新建项目绿化用地面积不得低于建设用地总面积的百分之三十，旧城改建区绿化用地面积不得低于建设用地总面积的百分之二十。因特殊原因无法达到规定的绿化面积标准的，按照有关规定执行。\n第三十三条 任何单位和个人不得擅自改变城镇规划区内绿地的用地性质。\n严格控制临时占用城镇绿地，因国家建设和其他特殊需要临时占用城镇绿化用地的，须经自治县城市管理执法部门批准，并缴纳绿地临时占用费。\n第三十四条 城镇规划区内所有山体、河岸均属绿化重点保护范围。禁止在绿化重点保护范围内擅自开山、炸石或者以其他方式破坏其地形、地貌、植被和景观。\n第三十五条 任何单位或者个人不得擅自砍伐、移植和修剪城镇树木。\n为保证管线的安全使用或者因其他特殊原因需要砍伐、移植、修剪城镇树木的，应当经自治县城市管理执法部门批准，申请单位负责承担砍伐、移植、修剪费用，由园林绿化部门组织施工。因不可抗力致使树木倾斜危及管线安全时，管线管理单位可先行修剪、扶正或者砍伐树木，但应当及时报告自治县城市管理执法部门和园林绿化部门。\n第三十六条 在城镇规划区内禁止下列损害城镇绿化及其设施的行为：\n（一）在树木上架设线缆；\n（二）就树盖房，设置广告、标语牌；\n（三）在树木上刻划、张贴或者悬挂物品；\n（四）在施工作业时借树木作为支撑物或固定物；\n（五）攀树、折枝、挖根或者剥损树干、树皮；\n（六）在树木下、绿地内搭灶生火或倾倒油污等有害物质；\n（七）在绿地内乱扔废弃物、堆放物料、放养牲畜家禽；\n（八）在绿地和道路两侧绿篱内挖坑取土；\n（九）损坏草坪、花坛、绿篱；\n（十）盗窃、损坏绿化设施；\n（十一）其他损害绿化及其设施的行为。","level":1},{"name":"第五章 市容环境卫生管理","text":"第三十七条 城镇规划区内建筑物的设计风格和色调应当符合城市规划要求，新建、改建、扩建建筑物应当与周围市容环境相协调。\n建筑物、构筑物外立面应当保持整洁，其市容环境卫生责任人应当按照城镇人民政府的规定定期进行清洗、粉刷和修饰。\n城镇主要街道两侧的建筑物和重点地区临街建筑物的屋顶、阳台外和窗外不得吊挂、晾晒、堆放影响市容的物品或者搭建构筑物。\n城镇主要街道两侧的建筑物和重点地区临街建筑物的外立面上安装窗栏、空调等设施，应当保持其安全、整洁，不得影响行人通行。\n第三十八条 任何单位和个人不得擅自在城镇道路两侧和公共场所堆放物料，搭建建筑物、构筑物或其他设施。\n禁止在城镇道路和其他公共场所的树木和护栏、电线杆、路牌等设施上晾晒、吊挂物品。\n禁止在城镇道路、广场等公共场所清洗车辆，从事车辆清洗、修理和废品收购、废弃物接纳作业的，应当保持经营场所周围的环境卫生，采取措施防止污水外流或者废弃物向外散落。\n第三十九条 任何单位和个人不得擅自占用城镇道路、桥梁、广场以及其他公共场所摆摊设点、销售或者加工制作商品。经依法批准临时占用城镇道路或者其他公共场所从事经营或者举办活动的，应当按照批准的时间、地点和要求进行。\n临街商场或门店的经营者不得超出门、窗、外墙搭建遮阳棚等附属设施，或者在临街面屋外摆摊经营、作业、展示商品。\n第四十条 在城镇规划区内运行的车辆应当保持外观整洁，车身不整洁的，应当及时清洗、维修。运载散体、流体物质的车辆必须有严实密封的防护设施，不得有泄漏、遗撒物污染路面。\n第四十一条 公民、法人和其他组织的名称、字号、标志等牌匾的设置，应当符合城镇容貌标准。\n户外广告、牌匾、灯箱、画廊、标语、宣传栏等户外设施的设置人应当加强设施的日常管理，保持外形美观、安全牢固以及功能完好。因画面污损、字体残缺、灯光显示不完整等影响市容的，应当及时维修或者更换。\n户外广告设置应当按照法律、法规的规定办理。\n第四十二条 自治县城市管理执法部门应当按照规划设置公共信息栏供公民发布信息，并负责日常管理和保持整洁。\n任何单位和个人不得在公共信息栏以外的地方随意刻画、涂写、张贴。\n第四十三条 禁止在人行道上乱停乱放和行驶机动车辆。\n在不影响行人正常通行的道路宽阔地段由城市管理执法部门会同公安机关交通管理部门划定停车区域。\n第四十四条 禁止下列影响环境卫生的行为：\n（一）随地吐痰、便溺；\n（二）乱扔瓜果皮核、纸屑、烟蒂、饮料罐、饭盒、口香糖、塑料袋等废弃物；\n（三）乱倒垃圾、污水、粪便，乱弃动物尸体；\n（四）散养、放养动物；\n（五）在露天场地或者公共垃圾收集容器内焚烧树叶、垃圾或者其他废弃物；\n（六）在道路或者公共场所抛撒、焚烧物品等；\n（七）其他有损环境卫生的行为。\n第四十五条 单位和个人应当按照市容环境卫生管理机构规定的地点和方式倾倒生活垃圾。餐饮经营服务者应当按照有关规定单独收集和处理餐厨垃圾。\n产生建筑垃圾的单位应当向自治县城市管理执法部门提出申请，获得建筑垃圾处置核准后，方可处置。居民装修房屋产生的垃圾，应当按照规定投放到指定地点，不得与生活垃圾混放。\n禁止向河道倾倒垃圾渣土以及其他污染河道、影响行洪的行为。\n产生生活垃圾的单位和个人应当按照有关规定缴纳垃圾处理费。建筑垃圾的处置按照国家和省、市有关规定执行。\n第四十六条 禁止在城镇规划建成区燃放烟花炮竹。具体办法由自治县人民政府规定。\n第四十七条 工业固体废物、医疗废物以及其他危险废物，必须按国家规定单独收集、运输和处置，禁止混入城市生活垃圾。\n第四十八条 因修建养护市政、供电、供水、供气、通信、防空、交通、消防、绿化、环卫等设施所产生的渣土、淤泥、枝叶以及其他废弃物，其作业单位应当及时清除。\n城市规划区内的所有建设施工单位应当实行封闭作业，不得在建设工地围栏外堆放建筑垃圾、工程渣土和建筑材料。施工中产生的垃圾、渣土应当集中堆放，及时清运，并采取措施防止尘土和污水污染周围环境。建设工程竣工后，施工单位应当及时平整建设工地，清除建筑废弃物，拆除施工临时设施。\n广场文化娱乐活动、商业经营活动及其他娱乐活动产生的噪音应当符合国家规定的标准。\n第四十九条 城镇生活垃圾、建筑垃圾处理场所等环境卫生设施的建设，应当符合环境卫生设施标准和技术规范要求。\n各类客运交通工具、公共场所及其他人流集散场所的经营管理单位，应当按照环境卫生设施设置标准设置垃圾收集容器。\n环境卫生设施的管理和使用单位应当加强对环境卫生设施的管理，定期进行保养、维修，保持其整洁、完好。\n任何单位和个人不得侵占、损坏或者擅自拆除、迁移、封闭环境卫生设施，不得擅自改变公共环境卫生设施的使用性质。因城镇建设确需拆除环境卫生设施的，建设单位应当事先提出拆迁还建方案，报自治县城市管理执法部门批准。城镇规划确定的环境卫生设施用地，不得擅自改变其用途。\n第五十条 市容环境卫生责任区责任人按照下列规定确定：\n（一）城镇区域内的主要道路及其他公共场所由市容环境卫生行政主管部门负责。\n（二）实行物业管理的住宅区，由物业管理单位负责；未实行物业管理的，由原产权单位负责，产权单位破产、停业的，由原主管单位负责，无主管单位的由居民委员会负责。\n（三）各类经营场所由经营管理者负责。\n（四）建筑工程施工现场由施工单位负责。\n（五）车站、码头、广场、影剧院、公共厕所等由经营管理者负责。\n（六）机关、团体、企事业由该单位负责。\n（七）临街房屋由房屋产权人或者使用人负责。\n第五十一条 市容环境卫生责任人应当履行下列责任：\n（一）保持市容整洁。无乱摆摊、搭建、张贴、涂写、刻画、吊挂、堆放等行为。\n（二）保持环境卫生整洁。无暴露垃圾、粪便、污水、污迹、渣土，路面无积水、无污泥。\n（三）保持环境卫生设施的整洁、完好。\n市容环境卫生责任人对在市容环境卫生责任区内发生的损害、破坏市容环境卫生行为，有权予以劝阻、制止或向自治县城市管理执法部门举报。自治县城市管理执法部门对市容环境卫生责任人不履行责任的，可以予以通报批评。","level":1},{"name":"第六章 法律责任","text":"第五十二条 违反本条例关于规划建设管理规定，有下列情形之一的，按照下列规定予以处罚：\n（一）未取得建设工程规划许可证或者违反建设工程规划许可证的规定进行建设，影响城镇规划，尚可采取改正措施的，由城市管理执法部门责令限期改正，补办手续，并处违法建筑工程造价百分之五以上百分之十以下的罚款；严重影响城镇规划，不能采取补救措施的，责令停止建设，限期拆除或者没收违法建筑物、构筑物及相关设施。\n（二）买卖、骗取建设用地规划许可证、乡村建设规划许可证或建设工程规划许可证的，由自治县自然资源和规划部门依法予以撤销，没收违法收入，并处1万元以上5万元以下罚款。\n（三）临时建筑物、构筑物超过批准期限不拆除的，由自治县自然资源和规划部门责令限期拆除，可以并处临时建设工程造价一倍以下的罚款。\n第五十三条 违反本条例有关市政公用设施管理规定，法律、法规有处罚规定的，从其规定；没有规定的，责令其限期改正，造成市政公用设施损失的，应当依法予以赔偿。\n第五十四条 违反本条例有关园林绿化管理规定，有下列行为之一的，由城市管理执法部门按下列规定予以处罚：\n（一）擅自改变城市绿化用地性质的，责令采取补救措施，并处1万元以下罚款。\n（二）砍伐、擅自迁移古树名木或者因养护不善致使古树名木受到损伤或者死亡的，责令停止侵害，并可处以罚款；造成损失的，依法承担赔偿责任；构成违反治安管理处罚行为的，由公安机关依法处理；构成犯罪的，依法追究其刑事责任。\n（三）擅自砍伐、修剪、移植城镇规划区内的树木，或有第三十六条所列损害城镇绿化及其设施行为之一的，责令改正或者采取补救措施，并可处200元以上2千元以下罚款。\n第五十五条 违反本条例有关市容环境卫生管理，法律、法规有规定的，从其规定。有下列行为之一的，由城市管理执法部门按照下列规定予以处理：\n（一）擅自占用城镇道路、桥梁、广场及其他公共场所摆摊设点从事经营销售或者加工制作商品的，责令停止违法行为，处50元以上1千元以下罚款。\n（二）侵占、损坏环境卫生设施，或者擅自拆除、迁移、封闭环境卫生设施，或者擅自改变公共环境卫生设施使用性质的，责令限期改正；情节严重的，可以并处环境卫生设施造价一倍以上二倍以下罚款。\n（三）市容环境卫生责任人不认真履行职责或有违反城镇环境卫生管理规定行为的，予以通报批评，责令限期改正，并视其情节轻重对其责任人给予处分。\n第五十六条 违反本条例有关市容管理的，未经批准或者未按照批准的要求和期限设置户外广告的，由城市管理执法部门责令改正，可以并处1千元以上2万元以下罚款，逾期未改正的，依法强制拆除。\n第五十七条 违反本条例第十七条规定在非居住用地范围内建设单门独院式住宅的，由自然资源和规划部门责令限期拆除。当事人逾期不拆除的，自治县人民政府可以责成有关部门强制拆除。\n违反本条例第二十一条规定的，由民政部门依照国家殡葬管理的相关规定予以处罚。\n违反本条例第四十三条、第四十六条规定的，由城市管理执法部门和公安、应急管理等部门依照法定职权予以处罚。\n第五十八条 以暴力或者其他方法阻挠、妨碍城市管理执法部门执法人员执行公务、构成违反治安管理规定的，由公安机关依法处理；情节严重，构成犯罪的，依法追究其刑事责任。\n第五十九条 当事人对行政行为不服的，可以依法申请行政复议或者提起行政诉讼。\n第六十条 城镇建设管理有关部门及其工作人员在实施城市建设管理工作中玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上一级行政主管部门给予处分；构成犯罪的，依法追究其刑事责任。\n第六十一条 城市管理执法部门应当加强日常巡查，发现正在建设中的违法建设行为，应当立即责令停止建设、限期拆除。","level":1},{"name":"第七章 附 则","text":"第六十二条 自治县所辖乡集镇和村庄建设区的规划、建设和管理，参照本条例执行。\n第六十三条 本条例自2016年9月1日起施行。","level":1}]},{"id":"h0123","sections":[{"name":"","text":"（2006年7月21日湖北省第十届人民代表大会常务委员会第二十二次会议通过）\n第一条 为了加强科学技术普及工作，提高公民的科学文化素质，促进科教兴鄂，推动经济发展和社会进步，根据《中华人民共和国科学技术普及法》和其他法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例所称科学技术普及（以下简称科普），是指用公众易于理解、接受和参与的方式，宣传科学技术知识、倡导科学方法、传播科学思想、弘扬科学精神的活动。\n本省行政区域内的国家机关、驻鄂部队、社会团体、企业事业单位、城乡基层群众性自治组织及其他组织，应当按照法律、行政法规和本条例的规定开展科普工作。\n科普事业是公益事业，提高公众科学技术素养是全社会的共同任务，社会各界都应当积极支持、广泛参与各类科普活动。\n第三条 科普工作应当坚持群众性、社会性、经常性的原则，因地制宜，根据不同对象的接受能力和需求，采取灵活多样的方式进行。\n科普工作应当坚持科学求实的精神，反对迷信和伪科学。任何单位和个人不得以科普为名传播不健康、不文明的行为方式和从事其他有损社会公共利益的活动。\n开展科普活动应当保守国家秘密，不得侵犯他人的知识产权和商业秘密。\n第四条 各级人民政府领导科普工作，将科普事业纳入本行政区域国民经济和社会发展规划，采取切实有效措施促进科普事业发展。\n县级以上各级人民政府应当建立科普工作联席会议制度，统筹、协调、指导本行政区域的科普工作，解决科普工作中的重大问题。\n各级人民政府应当将科普事业经费列入本级财政预算，并根据财力情况和实际需要逐步提高对科普事业的投入水平；县级以上各级人民政府有关部门应当安排一定的经费用于科普工作。科普经费应当专款专用，任何单位和个人不得克扣、截留、挪用。\n第五条 县级以上人民政府科学技术行政部门负责制定本行政区域内科普工作规划，部署科普工作，并开展督促检查，实行政策引导，推动科普事业的发展。\n县级以上人民政府其他有关行政部门按照各自的职责，负责有关的科普工作。\n第六条 各级科学技术协会是科普工作的主要社会力量，协助制定科普工作规划，为政府科普工作决策提供建议。各级科学技术协会应当充分发挥和利用自身优势，组织开展群众性、社会性、经常性的科普活动，支持有关社会组织和企业事业单位开展科普活动。\n工会、共青团、妇联、社科联等社会团体应当根据自身特点和所联系群体的实际，组织开展多种形式的科普活动。\n第七条 国家工作人员应当加强对现代科技知识、科学思想、科学方法的学习，增强科技意识，提高科学决策和科学管理能力。\n第八条 科普工作应当将提高青少年科学技术素养作为重点，在青少年中倡导科学精神，培养科技创新意识，增强科学实践能力。\n教育行政部门和中小学校应当结合教学活动和学生特点，加强对学生的科普教育，组织学生开展科技发明、科技制作、科技考察和科技夏（冬）令营等多种形式的校内外科普活动。\n第九条 科研机构、高等学校应当把科普工作纳入其工作计划，组织和支持科技人员、教师开展科普活动，鼓励其结合本职工作进行科普宣传；有条件的科研基地和实验室应当向社会开放。中小学校组织学生到科研基地和实验室参观，有关单位应当提供方便。\n第十条 企业事业单位应当结合本单位的生产经营和业务活动，鼓励职工学习生产技术和岗位技能，在职工中开展科技培训、技术竞赛和技术革新等活动，推动本单位的技术创新。\n鼓励企业事业单位制作公益性科普广告。\n第十一条 各级人民政府应当加强农村科普工作，采取有效措施，支持科普队伍建设，健全科普工作网络；省人民政府应当对民族自治地方和贫困地方的科普工作予以扶持。\n第十二条 县级以上农业、科技、教育行政等部门及科学技术协会应当组织农业院校、农业科研院所、农业技术推广机构及其他涉农单位，开展面向农民的农业科技培训，为农民提供科技信息服务，并会同劳动和社会保障部门适时开展农民工的技能培训；定期组织乡镇农业技术人员培训，扶持并发挥重点科技示范户、种植养殖大户等的引导和带动作用。\n第十三条 县级以上人民政府科技、文化、卫生、计划生育、环境保护等有关部门，应当组织下乡服务，开展科普活动。\n第十四条 农村基层组织应当根据实际需要开展科普活动，向农民宣传科学、文明的生产和生活方式。\n各类农村经济组织、农业技术推广机构和农村专业技术协会，应当结合推广先进适用技术向农民普及科学技术知识。\n社会各界应当支持并参与农村科普工作，鼓励以捐建科普图书室、捐赠科普图书和科普器材等多种形式，帮助农民提高科学文化素质。\n第十五条 城市居民委员会、社区组织和志愿者组织应当结合实际，开展以贴近居民生活为主要内容的科普活动。\n第十六条 市、州人民政府和有条件的县级人民政府所在地应当建立科普场馆；乡镇、街道办事处应当建立科普宣传橱窗或者科普活动室等设施。\n以政府投资为主建设的科普场馆和设施应当常年对公众开放，对青少年予以优惠和定期对中小学生免费开放，不得改变其用途；开展日常业务活动经费有困难的，同级财政应当给予必要的财政补贴，保证其正常运转。\n科技馆、博物馆、图书馆、文化馆、青少年宫和其他科普基地，应当充分发挥科普教育功能，积极开展科普活动。\n第十七条 鼓励科普创作和科普研究工作，培养科普创作人才。\n新闻出版部门应当加强科普作品的出版工作，影视单位应当加强科普影视作品的制作、发行和放映。出版、发行机构应当对科普作品的出版发行予以扶持和优惠。\n第十八条 报刊、广播、电视等媒体应当开设科普宣传专版、专栏和专题节目。\n鼓励单位和个人利用互联网站等现代传播媒体开展科普活动。鼓励各类媒体免费发布公益性科普广告。\n第十九条 医疗卫生机构和旅游景点、公园、商场、机场、车站、码头、影剧院、体育场馆等经营管理单位，应当根据各自的特点，利用相应的场所，面向社会开展科普宣传活动。\n第二十条 省人民政府设立科普奖励项目，并将其纳入省科学技术进步奖励范围，具体办法由省人民政府规定。\n第二十一条 鼓励社会组织和个人建立科普活动场所，兴办科普事业。\n鼓励省内外的社会组织和个人在本省设立科普基金或者捐赠财物，资助本省科普事业。对捐赠财物用于科普事业或者投资兴建科普场馆设施的，依照国家规定予以优惠。\n第二十二条 依法保护科普组织和科普工作者的合法权益，鼓励科普组织和科普工作者自主开展科普活动。科普组织和科普工作者依法兴办科普事业的，有关行政机关应当予以支持，提供方便，并依据国家规定给予优惠。\n第二十三条 扰乱科普活动或者科普场馆秩序，损坏用于科普活动的设备、设施，或者以科普为名进行有损社会公共利益活动的，由有关行政主管部门予以制止，并给予批评教育，依法责令其恢复原状或者赔偿损失；违反治安管理规定的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第二十四条 违反本条例规定，将政府投资为主建设的科普场馆和设施改变用途或者克扣、截留、挪用科普经费的，由县级以上人民政府责令限期改正和归还；对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第二十五条 国家工作人员不依法履行在科普工作中应当履行的职责，或者滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第二十六条 本条例自2006年10月1日起施行。","level":0}]},{"id":"h0124","sections":[{"name":"","text":"（2006年9月29日湖北省第十届人民代表大会常务委员会第二十三次会议通过 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第三次修正）\n第一条 为了保护和改善农业生态环境，防治农业环境污染和生态破坏，保证农产品质量安全，保障人体健康，推动农业清洁生产，发展农业循环经济，促进农业可持续发展，根据有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 在本省行政区域内从事与农业生态环境保护有关的生产、生活、经营、科研等活动，适用本条例。\n本条例所称农业生态环境，是指农业生物赖以生存和繁衍的各种天然和人工改造的自然因素的总体，包括土壤、水体、大气、生物等。\n第三条 农业生态环境保护实行统一规划，预防为主，教育与管理并重，源头控制与综合治理相结合。\n各级人民政府应当根据建设社会主义新农村的要求，将农业生态环境保护纳入国民经济和社会发展规划，加强农业生态环境建设，建立健全农业生态环境保护体系，提高农业生态环境保护科技水平，组织农业生态环境综合治理，落实农业生态环境保护目标责任，促进农业生态环境同经济社会发展相协调。\n各级人民政府应当加强农业生态环境保护的宣传教育，普及农业生态环境保护科学知识，引导公民和企事业组织参与农业生态环境保护，增强全社会保护农业生态环境的意识和法制观念。\n第四条 任何单位和个人都有权对污染和破坏农业生态环境的行为进行检举、控告。\n对在农业生态环境保护工作中做出显著成绩的单位和个人，由人民政府给予表彰、奖励。\n第五条 县级以上人民政府应当将农业生态环境保护经费纳入财政预算，并根据当地社会经济发展需要，增加对农业生态环境保护的投入。\n建立和完善农业生态补偿机制。对畜禽养殖废弃物和农作物秸秆的综合利用、农业投入品废弃物的回收利用、生物农药和生物有机肥的推广使用等，逐步实行农业生态补偿。具体办法由省人民政府制定。\n第六条 县级以上人民政府农业农村行政主管部门（以下简称农业农村行政主管部门）在职责范围内负责农业生态环境保护具体监督管理工作；生态环境行政主管部门对生态环境保护工作实施统一监督管理。\n县级以上人民政府林业、水行政等有关行政主管部门根据各自的职责，协助做好农业生态环境保护的有关工作。\n乡镇人民政府、村民委员会以及农村集体经济组织在其职责范围内，指导、帮助和教育当地村民开展农业生态环境保护活动。\n第七条 农业农村行政主管部门应当加强农业生态环境监测网络建设，会同生态环境行政主管部门组织开展农业生态环境质量监测和评价，并定期向本级人民政府报告农业生态环境状况和发展趋势。\n第八条 农业农村行政主管部门所属的农业生态环境保护机构必须严格履行农业生态环境保护的监督管理职责，其专职或者兼职农业生态环境监察员承担农业生态环境监督工作。\n第九条 农业农村行政主管部门应当加强耕地质量保护，对耕地质量进行定期监测，并指导、帮助农民和农业生产经营组织合理利用农业用地，推广测土配方施肥等先进技术。\n农民和农业生产经营组织应当科学培育地力，增施绿肥、农家肥、土杂肥等有机肥料，合理使用化肥、微生物肥和土壤调理剂，防止农用地的污染、破坏和地力衰退。\n第十条 县级以上人民政府及其农业农村等行政主管部门应当对依法划分的优先保护类、安全利用类和严格管控类农用地，采取相应的严格保护和风险管控措施。\n第十一条 使用农药应当严格遵守国家有关农药安全使用的规定。鼓励和支持农民和农业生产经营组织在农业生产过程中使用高效、低毒、低残留农药和生物农药，推广应用农作物病虫草鼠害综合防治技术。\n禁止在蔬菜、瓜果、茶叶、中药材、粮食、油料等农产品生产过程中使用剧毒、高毒、高残留农药。农业农村行政主管部门应当定期公布国家明令淘汰和禁止生产、销售、使用的农药品种目录。\n鼓励农民和农业生产经营组织使用环保型农用薄膜。农民和农业生产经营组织对盛装农药的容器、包装物、过期报废农药和不可降解的农用薄膜，应当予以回收，不得随意丢弃。县级以上人民政府及其农业农村、生态环境等行政主管部门应当设置相应的废弃物回收点，定期集中处理。回收处理的具体办法及相关的奖励措施由省人民政府制定。\n第十二条 各级人民政府应当加强乡村清洁工程建设，支持推广沼气综合利用技术，完善服务体系，鼓励农民和农业生产经营组织开发、利用沼气。\n农业农村行政主管部门应当加强对农作物秸秆综合利用的指导，推广秸秆综合利用技术。\n禁止露天焚烧农作物秸秆。\n第十三条 从事畜禽、水产规模养殖和农产品加工的单位和个人，应当对粪便、废水和其他废弃物进行综合利用和无害化处理，达到国家或者地方标准后，方可排放。\n县级以上人民政府及其农业农村、水行政、生态环境等行政主管部门应当加强对水产养殖行为的监督和管理。禁止在江河、湖泊、水库、运河围栏围网养殖、投肥（粪）养殖。\n第十四条 禁止向农田灌溉渠道排放工业废水或者医疗污水。\n向农田灌溉渠道排放城镇污水以及未综合利用的畜禽养殖粪污、水产养殖尾水、农产品加工废水的，应当保证其下游最近的灌溉取水点的水质符合农田灌溉用水水质标准。\n生态环境、农业农村、水行政等行政主管部门应当组织对农田灌溉水的水质及灌溉后的土壤、农产品进行定期监测，对不符合农田灌溉水质标准的污水，应当采取相应措施，防止污染土壤、地下水和农产品。\n第十五条 向农业生产区域排放废气、粉尘或者其他含有有毒有害物质的气体，超过国家和地方规定的排放标准的，应当按照国家有关规定限期治理。\n第十六条 禁止任何单位和个人在基本农田保护区内建窑、建房、建坟、挖砂、采石、采矿、取土、堆放固体废弃物或者进行其他破坏基本农田的活动。\n禁止任何单位和个人占用基本农田发展林果业和挖塘养鱼。\n禁止向农田和农用水源附近倾倒、弃置、堆放固体废弃物或者其他有毒有害物质。在其他农业用地修建处置、堆存固体废弃物场地的，必须符合国家生态环境保护标准，并征得当地农业农村行政主管部门同意。\n第十七条 县级以上人民政府应当加强农业生态环境污染的综合治理，恢复受污染的农田、水体和生态环境的基本功能。\n农业生态环境污染的治理应当结合治理工业污染、城镇生活污染、农业面源污染进行。农业建设、农业开发和农业技术推广活动，应当与农业生态环境保护、农业生态环境污染的治理相结合。\n第十八条 申请涉及农业生态环境保护的农业新技术和农用化学新产品鉴定的，应当提供农业生态环境影响评价资料；不符合农业生态环境保护要求的，不得通过鉴定和推广运用。\n第十九条 对农业生态环境有直接影响的建设项目，建设单位提交的生态环境影响报告书、生态环境影响报告表中，应当有农业生态环境影响评价的内容。生态环境行政主管部门审批生态环境影响报告书、生态环境影响报告表，应当征求同级相关行政主管部门的意见。\n第二十条 对国家重点保护野生植物和省重点保护野生植物的生长环境可能产生不利影响的建设项目，建设单位提交的生态环境影响报告书中应当对此作出专项评价；生态环境行政主管部门审批生态环境影响报告书时，应当征求同级野生植物行政主管部门的意见。\n第二十一条 省人民政府农业农村行政主管部门应当组织农业野生植物资源调查，建立资源档案，制定地方重点保护的农业野生植物保护规划。\n农业农村行政主管部门应当加强对农业野生植物的保护、研究和利用，建立农业野生植物原生境保护区、异地保护园和种质资源库。\n严格执行国家农业野生植物的采集、购销和出口管理制度。任何单位和个人不得随意采集、侵占、购销或者破坏省级以上重点野生植物保护名录中的农业野生植物。\n第二十二条 各级人民政府和有关部门应当采取措施，加强对农作物害虫、害鼠天敌的保护。\n禁止非法猎捕、出售、收购或者运输青蛙、蛇等农业野生有益生物。\n第二十三条 县级以上人民政府应当采取措施，扶持开发绿色食品和有机农产品，建立生态农业保护区，发展生态农业。\n农业农村行政主管部门依照法律法规的规定，加强对农产品质量安全和农业转基因生物安全的监督管理。\n第二十四条 从境外引进农业生物物种，应当依法办理进口审批与检疫审批。属于首次引进的，引进单位应当就引进物种对生态环境的潜在影响进行风险分析，并向审批部门提交风险评估报告。审批部门应当及时组织开展审查评估。有关部门应当组织对引进物种的跟踪观察，发现可能对农业生态环境造成危害的，应当及时采取相应的安全控制措施，避免危害的发生或者减轻、消除危害。\n农业农村行政主管部门应当加强对农业外来入侵生物的监控工作，并组织灭杀。\n第二十五条 县级以上人民政府应当制订农业生态环境污染事故和农业重大有害生物及外来生物入侵突发事件的应急处理预案，协调有关部门，采用科学手段，快速高效处置突发事件。\n第二十六条 造成农业生态环境污染事故的单位或者个人，必须立即采取有效防治措施排除或者减轻污染危害，及时告知可能受到污染危害的单位和居民，并向当地主管部门报告，依法接受调查处理。被调查的单位或者个人应当如实反映情况，提供必要的资料。\n发生重大农业环境污染事故，生态环境行政主管部门和农业农村行政主管部门应当及时向本级人民政府报告。\n因农业生态环境污染事故给农民和农业生产经营组织造成损失的，有关责任者应当依法赔偿；发生纠纷的，当事人可以要求生态环境行政主管部门或者农业农村行政主管部门进行处理。\n第二十七条 违反本条例规定的行为，法律法规有处罚规定的，从其规定。\n第二十八条 违反本条例规定，未经批准擅自从境外引进农业生物物种的，由县级以上人民政府有关部门按照职责分工，没收引进的外来物种，并处5万元以上25万元以下罚款。\n第二十九条 违反本条例规定，非法采集、侵占、购销、破坏省级重点保护农业野生植物的，由农业农村行政主管部门给予警告，责令停止违法行为，没收实物和违法所得，可并处1千元以上1万元以下罚款；造成严重后果的，处1万元以上5万元以下罚款。\n第三十条 违反本条例规定，拒绝、阻碍农业生态环境保护执法人员依法执行职务的，给予批评教育或者警告，责令改正；违反治安管理规定的，由公安机关依法处理；构成犯罪的，依法追究刑事责任。\n第三十一条 负有农业生态环境监督管理职责的部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，由其主管部门或者所在单位依法给予处分，构成犯罪的，依法追究刑事责任。\n第三十二条 本条例自2006年12月1日起施行。1993年2月13日湖北省第七届人民代表大会常务委员会第三十二次会议通过的《湖北省农业环境保护条例》同时废止。","level":0}]},{"id":"h0125","sections":[{"name":"","text":"（2006年9月29日湖北省第十届人民代表大会常务委员会第二十三次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了预防和查处窃电行为，维护供用电秩序和公共安全，保护电力企业和电力用户的合法权益，根据《中华人民共和国电力法》和有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本条例所称窃电行为，是指以非法占用电能为目的，故意采用下列方法不计量、少计量或者少计价的用电行为：\n（一）在电力企业或者其他单位、个人供用电的设施上擅自接线的；\n（二）绕越或者损坏用电计量装置的；\n（三）伪造或者非法开启用电计量装置的法定封印的；\n（四）致使用电计量装置不准或者失效的；\n（五）使用窃电装置的；\n（六）使用非法用电充值卡或者非法使用用电充值卡占用电能的；\n（七）实行两部制电价用户私自增加电力容量的；\n（八）非法改变用电计量装置的计量方法、标准的；\n（九）采用其他方法非法占用电能的。\n第三条 县级以上人民政府应当加强预防和查处窃电行为工作的领导，坚持预防为主、综合治理的原则，支持和监督有关部门依法预防和查处窃电行为。\n县级以上人民政府的电力行政主管部门负责本行政区域内供用电的监督管理工作，依法预防和查处窃电行为。\n公安、质量技术监督、工商行政管理等部门按照各自的职责，密切配合，依法预防和查处窃电行为。\n电力企业应当加强对窃电行为的防范，配合电力行政主管部门和其他部门查处窃电行为。\n第四条 任何单位和个人不得以任何方式窃电，不得教唆、胁迫、协助他人窃电，不得向他人传授窃电方法，不得制造、销售窃电装置。\n第五条 鼓励单位、个人对窃电和制造、销售、提供窃电装置等违法行为进行举报，自觉维护供用电秩序。\n有关部门应当为举报者保密；经查证举报属实的，应当给予奖励。","level":1},{"name":"第二章 用电安全防范与用电检查","text":"第六条 电力行政主管部门和电力企业应当经常进行电力法律法规、用电安全以及窃电行为危害性的宣传教育。\n机关、企业事业组织、社会团体和城乡基层组织，应当对本单位、本辖区人员进行安全用电、规范用电的宣传教育。\n传播媒体应当对损害电力企业和用户合法权益的行为进行舆论监督。\n第七条 电力企业应当定期或者不定期地进行用电安全与业务检查；加强防范窃电技术及产品的研究与开发，推广和采用防范窃电的技术和装备。\n第八条 电力企业安装和使用的用电计量装置，须经法定的或者授权的计量检定机构检定合格并加封，按照规定进行周期检定。电力企业应当对安装在用户处的用电计量装置进行检查。\n用户发现用电计量装置损坏、丢失或者发生故障的，应当及时告知电力企业。电力企业应当及时处理。\n第九条 电力企业和用户应当根据平等自愿、协商一致的原则签订供用电合同，明确双方的权利和义务。\n第十条 电力行政主管部门依法配备电力监督检查人员。电力监督检查人员有权向电力企业或者用户了解有关执行电力法律、法规的情况，查阅有关资料，并进入现场进行检查，发现窃电行为，有权制止和查处。\n电力监督检查人员进行检查时不得少于2人，并应当出示行政执法证件。\n第十一条 电力企业必须配备熟悉有关法律、法规和专业技能的用电检查人员。\n电力企业用电检查人员进行用电安全与业务检查时，不得少于2人，并应向用户出示用电检查证件。用户应当配合检查。\n第十二条 电力企业用电检查人员现场检查发现有窃电嫌疑的，应当加以制止，保护现场，收集和保留证据，并及时报告电力行政主管部门，由电力行政主管部门调查处理；发现违反治安管理行为的，应当直接向公安机关报案。\n用户对电力企业用电检查人员检查发现的窃电嫌疑没有异议的，根据供用电合同约定和国家有关规定，按所窃电量补交电费和支付违约使用电费。\n第十三条 采用暴力、威胁手段妨碍电力监督检查人员执行公务和妨碍电力企业用电检查人员进行用电检查的，公安机关应当依法处理。\n第十四条 电力企业为制止窃电行为，根据法律规定中断供电的，应当符合下列条件：\n（一）事先通知当事人；\n（二）采取了防范设备重大损失、人身伤害的措施；\n（三）不影响社会公共利益或者危害社会公共安全；\n（四）不影响当事人以外的其他用户的正常用电。\n第十五条 用户对电力企业以窃电为由中断供电有异议的，可以向电力企业所在地的电力行政主管部门投诉。\n受理投诉的电力行政主管部门应当在受理投诉之日起3日内作出是否恢复供电的决定。\n第十六条 有下列情形之一的，电力企业应当及时恢复供电，最迟不得超过24小时：\n（一）被中断供电的用户停止窃电行为并承担了相应责任；\n（二）被中断供电的用户按照有关规定提供了担保；\n（三）电力行政主管部门作出了恢复供电的决定。","level":1},{"name":"第三章 窃电行为的调查和处理","text":"第十七条 电力行政主管部门对涉嫌窃电行为的举报、投诉和电力企业及其用电检查人员的报告，以及其他有关行政主管部门移送和上级电力行政主管部门交办的案件应当及时受理，并指派电力监督检查人员调查。\n第十八条 电力行政主管部门对涉嫌窃电行为的调查结束后，应当根据不同情况，分别依法作出下列处理：\n（一）窃电事实不能成立的，予以撤销；\n（二）对窃电事实清楚、证据确凿的，作出行政处罚决定，并向当事人送达行政处罚决定通知书；\n（三）窃电行为轻微，及时改正和承担供用电合同约定的责任或者依法可以不予行政处罚的，不予行政处罚；\n（四）涉及治安、刑事案件的，移送公安、司法机关处理；\n（五）发现生产、销售窃电装置的，分别移送质量技术监督部门、工商行政管理部门处理。\n第十九条 公安机关对有关窃电行为的报案和行政主管部门、司法机关移送的有关违反治安管理案件应当及时受理，并依法查处。\n电力行政主管部门和公安机关对窃电行为的处理情况，应当相互告知。\n用户对电力行政主管部门和其他行政主管机关的行政处罚不服的，可以依法申请行政复议或者向人民法院提起行政诉讼。\n第二十条 窃电时间可以查明的，按照下列方法计算窃电量：\n（一）在供电设施上擅自接线用电的，窃电量按私接设备额定容量（千伏安视同千瓦）乘以窃电时间计算；用自制、改制以及无铭牌容量的用电设备窃电的，按照可实测的电流值确定设备容量乘以窃电时间计算；\n（二）私自增加电力容量的，按照超过合同约定的容量乘以使用时间计算；\n（三）采用上述第（一）项、第（二）项两种方法之外的其他不计量或者少计量方法窃电的，窃电量按计费电能表标定的最大额定电流值所指的容量乘以窃电时间计算；通过互感器窃电的，计算窃电量时还应当乘以实际使用互感器倍率。\n第二十一条 窃电时间不能查明的，按照下列方法确定窃电量：\n（一）能查明产量的，按照同类型用户的同类产品的单位耗电量和窃电单位的产品产量相乘计算用电量，加上其他辅助用电量，减去抄见电量；\n（二）用户现场检测系统装置正常计量的，按照用户现场检测系统装置记录电量减去抄见电量；\n（三）根据本条第（一）项、第（二）项的方法不能计算或者不能确定窃电量的，按照国家有关规定确定。\n第二十二条 窃电金额按照窃电量乘以当地当时的目录电价计算。\n窃取分时段电价的，按照销售目录电价的平段价格计算；窃电后转售电价高于销售目录电价的，按照转售的价格计算；转售电价低于销售目录电价的，按照销售目录电价计算。","level":1},{"name":"第四章 法律责任","text":"第二十三条 违反本条例规定的行为，法律、行政法规有处罚规定的，从其规定。\n第二十四条 对本条例第二条规定的窃电行为，由电力行政主管部门责令停止违法行为，追缴电费并处以应交电费5倍以下罚款。\n单位窃电的，除按照本条第一款规定处罚外，对实施窃电行为的单位予以公告；对单位直接负责的主管人员和其他直接责任人员处以警告，情节严重的，处以1000元以下罚款。\n第二十五条 制造窃电装置的，由质量技术监督部门责令停止违法行为，没收窃电装置及违法所得，并处2000元以上2万元以下罚款。\n销售窃电装置的，由工商行政管理部门责令停止违法行为，没收窃电装置及违法所得，并处2000元以上2万元以下罚款。\n第二十六条 教唆、胁迫、协助他人窃电或者向他人传授窃电方法的，由电力行政主管部门责令停止违法行为，没收违法所得，并处500元以上5000元以下罚款。\n第二十七条 窃电者的窃电行为造成供用电设施损坏、停电事故或者导致他人人身伤害、财产损失的，应当依法承担赔偿责任。\n第二十八条 电力企业违反本条例的规定中断供电或者未及时恢复供电，给用户造成损失的，应当依法承担赔偿责任。\n第二十九条 国家机关工作人员在履行预防和查处窃电行为职责中，玩忽职守、徇私舞弊、滥用职权、索贿受贿的，依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第五章 附则","text":"第三十条 本条例所称电力企业是指电网经营企业和供电企业。\n第三十一条 本条例自2007年1月1日起施行。","level":1}]},{"id":"h0126","sections":[{"name":"","text":"（2006年9月29日湖北省第十届人民代表大会常务委员会第二十三次会议通过 根据2010年7月30日湖北省第十一届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2011年12月1日湖北省第十一届人民代表大会常务委员会第二十七次会议《关于修改部分地方性法规中行政强制规定的决定》第二次修正 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》第三次修正 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》第四次修正）","level":0},{"name":"第二章 道路运输经营和出租","text":"","level":1},{"name":"第三章 道路运输相关业务","text":"","level":1},{"name":"第四章 监督检查","text":"","level":1},{"name":"第五章 法律责任","text":"","level":1},{"name":"第六章 附则","text":"","level":1},{"name":"第一章 总则","text":"第一条 为了规范道路运输经营和管理行为，维护道路运输市场秩序，保障道路运输安全，保护道路运输当事人的合法权益，促进道路运输业的发展，根据法律、行政法规的有关规定，结合本省实际，制定本条例。\n第二条 本省行政区域内从事道路运输经营、出租汽车客运经营、道路运输相关业务的，应当遵守本条例。\n前款所称道路运输经营包括道路旅客运输经营（以下简称客运经营）和道路货物运输经营（以下简称货运经营）；道路运输相关业务包括站场经营、机动车维修经营、机动车驾驶员培训、机动车综合性能检测、汽车租赁、装卸搬运、道路运输代理、货运配载信息服务、仓储理货、商品车发送等。\n第三条 县级以上人民政府交通主管部门负责组织领导本行政区域的道路运输管理工作。\n县级以上道路运输管理机构（以下简称运管机构）负责具体实施道路运输管理工作。\n公安、市场监督管理、建设、物价、应急管理、财政等部门，按照各自职责分工，做好道路运输管理的相关工作。\n第四条 县级以上人民政府应当根据国民经济和社会发展的需要制定本行政区域道路运输发展规划，并与城市和乡镇相关规划以及上级道路运输发展规划相衔接。道路运输发展规划由交通主管部门会同有关部门编制，报同级人民政府批准后实施。\n第五条 各级人民政府及其有关部门应当积极创造条件发展农村道路运输，提高乡镇和行政村的客运班车通车率，促进城乡道路运输业协调发展。\n县级以上人民政府交通、公安、市场监督管理、物价、财政、税务等部门应当采取措施，对农村道路运输事业予以支持和扶持，保障农副产品运输的绿色通道畅通；交通主管部门及其运管机构应当对农村道路运输从业人员的专业培训予以重点帮助。\n第六条 道路运输管理应当遵循公平、公正、公开和便民的原则，打破地区封锁和垄断，建立和完善统一、开放、竞争、有序的道路运输市场，满足人民群众的生活和生产需要。\n鼓励道路运输科技进步，推进道路运输信息化，引导道路运输企业实行规模化、集约化经营。\n县级以上人民政府及其公安、交通等部门应当加强对道路运输安全生产的宣传教育，检查、督促落实安全生产责任制度，提高道路运输安全生产的规范化水平。\n第七条 经营者应当具备法律、法规和国家标准、行业标准规定的安全生产条件，落实安全生产管理制度；不具备安全生产条件或者未落实安全生产管理制度的，不得从事道路运输经营活动。\n经营者应当对车辆、机具及站场的设施设备等进行经常性的维护、保养，并定期检测、检验，保证其正常运转。\n经营者应当依法经营，诚实守信，改善服务条件和手段，为服务对象提供安全、及时、优质的服务。\n第八条 从事道路运输经营、道路运输相关业务的经营者（以下简称经营者）应当按照核定的范围、项目、区域从事经营活动，遵守有关管理规定，实行明码标价。\n经营者暂停经营、终止经营、合并、分立，或者迁移经营场所、变更经营范围和项目、转移营运车辆所有权的，应当依法到原许可或者备案的机关办理有关手续。经营者终止经营的，应当依法处理善后事宜，并向作出许可决定的运管机构缴销相关许可证件。\n第九条 发生交通事故、自然灾害以及其他突发事件，需要承担应急运输任务的，经营者应当服从县级以上人民政府及其交通、公安等主管部门的统一调度和指挥。因承担应急运输任务所发生的费用，由车辆实际使用单位或者相应的人民政府给予合理补偿。","level":1},{"name":"第二章 道路运输经营和出租汽车客运经营","text":"第十条 从事客运、货运经营的，应当依法取得道路运输经营许可证和营业执照。准予道路运输经营许可的，运管机构应当向申请人投入运输的车辆配发道路运输证。\n客运经营者取得道路运输经营许可后，应当向公众连续提供运输服务，不得擅自暂停、终止或者转让班线运输。\n城市公共交通客运经营者从事跨越城市城区范围、行驶公路的客运经营的，应当依法取得相应的客运经营许可。\n第十一条 运管机构对可以通过服务质量招标的方式作出客运经营许可决定的，应当通过招标方式作出决定。通过服务质量招标方式取得许可的经营者应当按照承诺的服务内容、标准和价格提供服务。\n运管机构可以采取干支线路合并招标等方式开行偏远地区客运线路。\n申请从事乡村客运经营，其途经道路符合安全通行条件，车辆、人员等符合法定条件的，运管机构应当准予许可。\n从事乡村客运经营的，经许可机关同意，可以采取区域经营、循环运行等方式运营。\n第十二条 运管机构在审查批准客运班线的运行线路和停靠站点时，应当考虑径直快捷、经济合理、安全通畅、依线布局、方便乘客等因素。\n运管机构对途经三级以下（含三级）山区公路达不到夜间安全通行条件路段的，不予审批夜间客运班线。\n运管机构应当根据道路运输发展规划和客运市场供求状况，确定可供申请的客运线路，并定期向社会公布。\n第十三条 申请从事出租汽车客运经营的，应当具备下列条件：\n（一）有与其经营业务相适应并经检测合格的车辆；\n（二）有依法取得相应的机动车驾驶证和从业资格证的驾驶人员；\n（三）有健全的安全生产等管理制度；\n（四）法律、法规规定的其他条件。\n出租汽车客运经营许可期限为4年至8年，同一城市实行统一的经营许可期限。\n第十四条 从事出租汽车客运经营的，应当向所在地县级运管机构提出申请，其所在地在市辖区的，应当向市级运管机构提出申请，并提交符合本条例规定条件的相关材料。运管机构应当自受理申请之日起15日内审查完毕，作出许可或者不予许可的决定。准予许可的，运管机构应当向申请人颁发道路运输经营许可证，并按核定的车辆数量配发道路运输证和经营权证明；不予许可的，应当书面通知申请人并说明理由。\n出租汽车客运经营的具体管理办法由省人民政府制定。\n第十五条 为保障客运经营的普遍服务、方便群众，运管机构作出许可决定后，可以与申请人签订经营权使用合同。合同内容不得违反法律法规和损害国家、社会公共利益。\n第十六条 客运经营者应当按照规定的线路、停靠站点和公布的班次及时间、车辆型号、载客限额提供旅客运输服务，不得擅自变更线路、停靠站点、班次及时间和运输车辆，不得超载、强行招揽旅客或者将旅客移交他人运输。\n货运经营者不得运输法律、行政法规禁止运输的货物。法律、行政法规规定必须办理有关手续后方可运输的货物，货运经营者应当查验有关手续。\n第十七条 用于道路运输经营的载客汽车、重型载货汽车、半挂牵引车以及用于危险货物运输的专用车辆，应当安装、使用符合国家有关标准的车辆运行状态监控设备。运管机构工作人员可以对运行状态监控设备所采集的信息进行检查。\n第十八条 从事客运经营和危险货物运输的，应当依法分别为旅客或者危险货物投保承运人责任险。未按照规定投保的，运管机构可以依法查处。\n第十九条 运管机构应当将从事道路运输的经营者及其从业人员、车辆等有关情况定期向同级公安机关交通管理部门通报，公安机关交通管理部门应当定期向同级运管机构通报重大以上道路交通责任事故记录等有关情况。\n第二十条 从事危险货物运输的驾驶员、装卸管理人员、押运人员应当掌握危险货物运输的安全知识，并经市、州人民政府交通主管部门考核合格，取得资格证，方可上岗作业。\n运输、装卸危险货物，应当依照有关法律、法规、规章的规定和国家标准的要求并按照危险货物的危险特性，采取必要的安全防护措施。","level":1},{"name":"第三章 道路运输相关业务","text":"第二十一条 道路运输站场的建设应当符合交通运输和城乡建设总体规划，与公路、城市道路、城市公交系统和其他运输方式相互衔接和协调。\n交通主管部门应当会同建设、公安等部门统一规划，合理布局，在城区设置适当数量的道路客运车辆停靠站，方便旅客。\n第二十二条 运管机构在作出客运站场经营许可决定时，应当同时确定该站场接纳车辆的范围和可容纳车辆（班次）数量。客运站场应当按照确定的范围和可容纳车辆（班次）数量接纳经运管机构批准的车辆进站，并严格按照国家和省规定的项目和标准收费，按月或者按合同约定的时间结清所代售的票款。\n站场经营者应当配备相应的安全检查人员和设备，按照省应急管理部门和交通主管部门确定的项目和具体办法对进站经营的车辆进行安全检查，并防止乘客携带违禁物品乘车。\n第二十三条 客运站经营者应当在站场内公布其代理发售的客票的承运人，并按照进站发车的承运人取得许可的途经路线、停靠站点、日发班次及时间、车辆型号和车辆核定载客限额代理发售客票。客票上应当载明具体的承运人。\n推行客运联网售票和票款结算电子化，使用统一的计算机程序发售客票和结算票款。\n第二十四条 机动车维修经营者应当在经营场所的醒目位置悬挂机动车维修标志牌，公示维修项目的工时定额、收费标准和维修质量保证期，并按照国家规定的技术标准维修车辆，建立维修档案。\n机动车所有者可以自主选择机动车维修经营者维修车辆。除法律、法规规定外，任何单位或者个人不得强制或者变相强制机动车所有者到指定的机动车维修点维修车辆。\n第二十五条 机动车驾驶员培训经营者和教学人员应当按照备案的经营范围、教学场地和规定的培训学时开展培训业务，并按照驾驶员培训计时管理系统记录的培训学时和规定的收费标准收取培训费用。不得利用非教练车辆或者检测不合格的车辆从事驾驶员培训。运管机构应当加强对机动车驾驶员培训过程的监管。\n机动车驾驶培训学员应当凭培训记录和培训结业证报考机动车驾驶证，公安机关交通管理部门根据培训记录受理驾驶证考试申请，严格考试发证。\n第二十六条 从事营运的车辆应当按照国家规定定期进行综合性能检测。营运车辆在规定检验期内经安全技术检验合格的，不再重复进行安全技术检验。\n第二十七条 从事机动车综合性能检测经营的，应当具备下列条件：\n（一）有与其经营类别及项目相适应的场地；\n（二）有必要的设备、设施和技术人员；\n（三）有健全的机动车综合性能检测管理制度；\n（四）有必要的环境保护措施；\n（五）经省级市场监督管理部门或者其授权的机构计量认证考核合格。\n机动车综合性能检测实行社会化，任何国家机关以及车辆管理部门不得经营或者参与经营机动车综合性能检测业务。\n第二十八条 申请从事汽车租赁经营的，应当具备下列条件：\n（一）有不少于10辆经检测合格的车辆；\n（二）停车场面积不少于正常保有租赁汽车垂直投影面积的1.5倍；\n（三）有健全的安全生产管理制度；\n（四）有相应的专业人员和管理人员。\n第二十九条 从事机动车综合性能检测、汽车租赁、装卸搬运、道路运输代理、货运配载信息服务、仓储理货、商品车发送业务的，应当自取得营业执照之日起30日内向所在地县级运管机构备案。\n第三十条 机动车综合性能检测经营者应当按照国家有关技术标准和规范进行检测，并对其检测报告的真实性和准确性承担法律责任。\n第三十一条 汽车租赁经营者不得将非租赁经营者所属车辆、未办理汽车租赁经营合法手续的车辆用于租赁经营。\n汽车租赁经营者不得以提供驾驶员服务等方式从事或者变相从事道路运输经营活动。汽车租赁经营者和承租人不得利用租赁汽车从事客运经营活动。\n第三十二条 装卸搬运、道路运输代理、货运配载信息服务、仓储理货、商品车发送的经营者应当具备相应的经营条件，严格执行国家有关规定。\n道路运输代理经营者不得将所代理的运输业务交给非法的客货运输经营者承运，不得承接应当办理而未办理准运手续的货物运输代理业务。商品车发送经营者不得用被发送的车辆从事道路运输经营活动。","level":1},{"name":"第四章 监督检查","text":"第三十三条 县级以上人民政府交通主管部门应当加强对运管机构实施道路运输管理工作的指导监督；上级运管机构应当对下级运管机构的执法活动进行监督检查，及时纠正其违法或者不当的行政行为。\n运管机构应当公开受理举报、投诉的电话、通信地址、电子邮件信箱；对受理的投诉，应当在30日内予以答复。\n第三十四条 运管机构应当根据国家和省交通主管部门制定的质量信誉考核办法，对道路运输经营者及其从业人员的经营行为、服务质量、安全生产等实行考核，并向社会公布质量信誉考核结果。\n第三十五条 运管机构工作人员应当重点在道路运输及相关业务的经营场所、客货集散地和省人民政府批准设置的公路超限检测站站区进行监督检查；在公路路口进行监督检查时，不得随意拦截正常行驶的道路运输车辆。\n运管机构工作人员在执行监督检查任务时，应当佩戴标志，出示行政执法证件，文明执法。\n运管机构专用检查车辆应当按照国家交通主管部门制定的公路监督检查专用车辆管理办法进行配制和管理。\n第三十六条 运管机构工作人员实施监督检查时，被检查单位和个人应当如实提供有关资料和情况，接受监督检查。必要时，运管机构可以将违法行为信息向社会公布。\n第三十七条 运管机构工作人员在实施监督检查过程中发现车辆超载行为的，应当立即予以制止，并采取合理的措施安排旅客改乘或者强制卸货，所需费用由超载的经营者承担。运管机构对车辆超载的行为，应当及时通知公安机关交通管理部门依法查处，公安机关交通管理部门应当将查处情况及时通报运管机构。\n第三十八条 未取得道路运输经营许可擅自从事出租汽车客运经营的，县级以上运管机构可以暂扣车辆，并妥善保管，不得使用，不得收取或者变相收取保管费用。除因不可抗力外，造成车辆及随车物品遗失、损坏的，应当依法赔偿。当事人应当在15日内到运管机构接受处理，违法行为改正后，运管机构应当立即放行。\n道路运输经营车辆未按照规定进行机动车综合性能检测，或者其驾驶人员不符合规定条件的，县级以上运管机构可以责令停止车辆运行，限期予以改正。\n第三十九条 客运经营者发生安全责任事故的，应当采取措施，及时整改；运管机构对发生特大责任事故的经营者应当自事故发生之日起6个月内不予许可其相关的新增经营申请。","level":1},{"name":"第五章 法律责任","text":"第四十条 违反本条例的行为，法律、行政法规有处罚规定的，从其规定。\n第四十一条 已经依法取得道路运输经营许可的经营者，经监督检查发现其在经营过程中不符合法定条件，或者取得道路运输经营许可后连续6个月未从事相应经营活动的，由县级以上运管机构责令改正，拒不改正或者整改不合格的，暂扣其道路运输经营许可证件。\n经营者发生重大以上交通安全责任事故整改不合格的，由县级以上运管机构暂扣其道路运输经营许可证件。\n第四十二条 有下列情形之一的，由县级以上运管机构责令改正，可以处1000元以上5000元以下的罚款；情节严重的，可以暂扣相关道路运输经营许可证件：\n（一）使用无道路运输证的车辆从事经营的；\n（二）站场经营者不按规定代理发售客票或者不按规定结清所代售的票款的；\n（三）驾驶员培训经营者使用不符合规定的车辆、场地，未按照规定的培训学时开展培训业务，或者不按照规定填制和发放培训记录的。\n第四十三条 机动车综合性能检测、汽车租赁经营者有下列情形之一的，由县级以上运管机构责令改正；有违法所得的，没收违法所得；没有违法所得的或者违法所得不足3000元的，处5000元以上1万元以下的罚款；违法所得超过3000元的，处违法所得二倍以上五倍以下的罚款；情节严重的，责令停产停业：\n（一）未按国家有关技术标准和规范进行机动车综合性能检测或者出具虚假检测报告的；\n（二）汽车租赁经营者使用非租赁经营者所属的车辆或者未办理合法租赁经营手续的车辆用于租赁的。\n第四十四条 暂扣道路运输经营许可证件期限不得超过30日。被运管机构暂扣道路运输经营许可证件的，应当立即停止相关经营活动或者予以整改，拒不停止或者不予整改的，运管机构应当吊销其道路运输经营许可证件。\n第四十五条 经营者违反本条例第三十一条第二款、第三十二条第二款规定的，由县级以上运管机构责令改正，处警告或者50元以上500元以下的罚款；情节严重的，处500元以上3000元以下的罚款。\n第四十六条 无照、无证从事道路运输有关经营活动的，由市场监督管理部门、运管机构及其他许可审批部门依法查处。\n第四十七条 交通主管部门、运管机构和其他有关部门及其工作人员有下列行为之一的，对责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）违反本条例规定核发道路运输经营许可证件的；\n（二）参与或者变相参与道路运输经营、道路运输相关业务的；\n（三）发现违法行为不依法查处的；\n（四）对投诉超过规定期限未作出处理、答复的；\n（五）刁难当事人、乱收费或者索贿受贿的；\n（六）其他违法行为。","level":1},{"name":"第六章 附则","text":"第四十八条 本条例自2006年12月1日起施行。1997年9月28日湖北省第八届人民代表大会常务委员会第三十次会议通过的《湖北省道路运输管理条例》同时废止。","level":1}]},{"id":"h0127","sections":[{"name":"","text":"（2006年12月1日湖北省第十届人民代表大会常务委员会第二十四次会议通过 根据2011年12月1日湖北省第十一届人民代表大会常务委员会第二十七次会议《关于修改部分地方性法规中行政强制规定的决定》修正 2026年9月24日湖北省第十四届人民代表大会常务委员会第二十六次会议修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强无线电管理，维护空中电波秩序，有效开发、利用和保护无线电频谱资源，保证无线电业务的正常进行，服务经济社会高质量发展，根据《中华人民共和国生态环境法典》、《中华人民共和国无线电管理条例》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于在本省行政区域内使用无线电频率，设置、使用无线电台（站），研制、生产、进口、销售、维修无线电发射设备，使用辐射无线电波的非无线电设备，以及相关保障和监督管理活动等。\n军事系统的无线电管理，按照国家和军队有关规定执行。\n第三条 无线电频谱资源属于国家所有，实行统一规划、合理开发、有偿使用。\n无线电管理工作贯彻科学管理、保护资源、保障安全、促进发展的方针。\n第四条 省人民政府应当加强无线电管理工作的领导，将无线电管理工作纳入国民经济和社会发展规划，协调解决无线电管理工作中的重大问题，提高无线电频谱资源的经济社会效益。\n市（州）、县（市、区）人民政府应当明确具体部门，协助做好本行政区域内无线电管理工作。\n第五条 省无线电管理机构负责本省行政区域内除军事系统外的无线电管理工作，根据审批权限实施无线电频率使用许可，审查无线电台（站）的建设布局和台址，核发无线电台执照以及无线电台识别码（含呼号），负责无线电监测和干扰查处，协调处理无线电管理相关事宜。\n省无线电监测机构在省无线电管理机构领导下，对无线电信号实施监测，查找无线电干扰源和未经许可设置、使用的无线电台（站）。\n生态环境主管部门对电磁辐射污染防治工作实施统一监督管理。\n公安、自然资源、住房和城乡建设、交通运输、应急管理、市场监督管理、广播电视、国防动员、数据、国家安全、气象、铁路、海事、通信管理、民航、电力等部门和单位按照各自职责，做好无线电管理相关工作。\n第六条 省人民政府应当鼓励开展无线电基础理论研究和标准体系制定，支持无线电新技术、新产品、新业务的开发与应用，引导培育、创造和运用高质量、高价值知识产权，加强无线电技术在数字基础设施、技术创新、政务效率提升中的支撑作用，促进无线电产业发展。\n省无线电管理机构应当会同有关部门引导无线电技术应用场景拓展，推动新一代移动通信、智能制造、智能网联汽车、航空物流、北斗导航、低空经济等产业发展，服务构建现代化产业体系。\n第七条 县级以上人民政府及其有关部门应当建立健全无线电人才培养机制，加大政策支持和服务保障力度，提高无线电从业人员技术水平。\n第八条 省无线电管理机构应当会同有关部门组织开展无线电科普活动，普及无线电知识，宣传无线电管理法律法规和有关规定，增强社会公众依法使用无线电频谱资源、维护空中电波秩序的意识。\n第九条 无线电领域有关行业协会应当加强行业自律和诚信建设，依法提供信息交流、技术培训、业务咨询等服务，促进行业健康有序发展。","level":1},{"name":"第二章 无线电频率管理","text":"第十条 省无线电管理机构应当根据国家无线电管理规划和频率划分规定，结合本省经济社会发展实际，科学配置频谱资源，优先保障涉及国家安全、公共安全和公共利益的频率使用需求，重点支持战略性新兴产业的频率使用需求，统筹保障产业转型升级和民生领域的频率使用需求。\n第十一条 使用无线电频率应当依法取得许可，法律、行政法规规定不需要取得无线电频率使用许可的除外。\n省无线电管理机构依法实施国家无线电管理机构确定范围内的无线电频率使用许可，许可的条件、期限等按照国家有关规定执行。\n任何单位或者个人不得擅自使用无线电频率。无线电频率使用人不得擅自转让无线电频率使用权；确需转让的，受让人应当符合国家规定的条件，并依法办理相关手续。\n第十二条 鼓励和支持无线电频率共享。在技术条件允许、不发生有害干扰的前提下，省无线电管理机构可以作出允许两个以上单位或者个人在同一地域共用相同无线电频率的许可决定。\n第十三条 使用无线电频率应当依法缴纳无线电频率占用费。\n无线电频率占用费的减免按照国家有关规定执行。\n第十四条 省无线电管理机构应当定期组织开展无线电频率使用评估，并将评估结果作为科学配置和管理无线电频率的重要参考。\n除因不可抗力外，取得无线电频率使用许可后超过2年不使用或者使用率达不到许可证规定要求的，省无线电管理机构有权依法撤销其作出的无线电频率使用许可，收回无线电频率。","level":1},{"name":"第三章 无线电台（站）管理","text":"第十五条 设置、使用无线电台（站）应当依法取得无线电台执照，法律、行政法规规定不需要取得无线电台执照的除外。\n无线电台（站）设置、使用许可的范围、条件、期限，按照国家有关规定执行。\n省无线电管理机构核发的无线电台执照有效期届满后需要继续使用无线电台（站）的，应当在有效期届满30个工作日前向省无线电管理机构申请更换无线电台执照。\n第十六条 建设固定台址的无线电台（站）的选址，应当符合国土空间规划的要求，充分考虑电磁辐射对周边环境的影响，避开影响其功能发挥的建筑物、设施等。自然资源主管部门依法保障固定台址的无线电台（站）选址需求。\n设置大型无线电台（站）、地面公众移动通信基站，其台址布局规划应当符合资源共享的要求。\n鼓励符合条件的无线电台（站）的台址实行共建共享。\n第十七条 设置、使用有固定台址的无线电台（站）的单位或者个人，应当在无线电台（站）周边设置标识，按照有关规定对天线、馈线和铁塔、支架等附属物进行美化或者隐蔽，使其符合城市容貌标准，与周围环境相协调。\n设置、使用无线电台（站）的单位或者个人应当对无线电台（站）进行定期维护，保证其性能指标符合国家标准和无线电管理的有关规定，避免对其他依法设置、使用的无线电台（站）产生有害干扰。\n第十八条 使用无线电台（站）的单位或者个人不得故意收发无线电台执照许可事项之外的无线电信号，不得传播、公布或者利用无意接收的信息。\n任何单位或者个人不得利用无线电台（站）进行违法犯罪活动，不得为非法设置、使用无线电台（站）提供场所、设备等便利条件。\n第十九条 设置、使用无线电台（站）的单位或者个人应当遵守国家、省生态环境保护有关规定，采取电磁辐射污染防治措施，防止无线电波发射产生的电磁辐射污染环境。\n生态环境主管部门应当加强对电磁辐射排放情况的调查、监测。\n第二十条 无线电台执照有效期届满或者因其他原因终止使用无线电台（站）的，应当立即停止使用无线电台（站），及时办理注销手续，交回无线电台执照，并自无线电台执照注销之日起60个工作日内拆除无线电台（站）及天线等附属设备。未办理注销手续的，省无线电管理机构可以依法注销其核发的无线电台执照。\n无线电台执照被依法撤销、吊销的，应当立即停止使用无线电台（站），拆除无线电台（站）及天线等附属设备，交回无线电台执照。\n第二十一条 遇有危及国家安全、公共安全、生命财产安全的紧急情况或者为了保障重大社会活动的特殊需要，可以不经批准临时设置、使用无线电台（站），但是应当按照国家规定向无线电管理机构报告，并在紧急情况消除或者重大社会活动结束后及时关闭。\n第二十二条 业余无线电台的设置、使用按照国家有关规定执行。\n业余无线电台只能用于相互通信、技术研究和自我训练，并在业余业务或者卫星业余业务专用频率范围内收发信号，但是参与重大自然灾害等突发事件应急处置的除外。\n为突发事件应急处置的需要，业余无线电台可以与非业余无线电台通信，但通信内容应当限于与突发事件应急处置直接相关的紧急事务。\n不得利用业余无线电台从事营利性活动。","level":1},{"name":"第四章 无线电发射设备管理","text":"第二十三条 生产或者进口在国内销售、使用的无线电发射设备，应当符合产品质量等法律法规、国家标准和无线电管理的有关规定。\n第二十四条 除微功率短距离无线电发射设备外，生产或者进口在国内销售、使用的其他无线电发射设备，应当依法取得型号核准，并在设备上标注型号核准代码。\n销售依法取得型号核准的无线电发射设备，应当通过无线电发射设备销售备案信息平台向省无线电管理机构办理销售备案。\n不得销售未按照国家规定标注型号核准代码的无线电发射设备。\n维修无线电发射设备，不得改变无线电发射设备型号核准证核定的技术指标。\n第二十五条 研制、生产、销售和维修大功率无线电发射设备，应当采取措施有效抑制电波发射，不得对依法设置、使用的无线电台（站）产生有害干扰。进行实效发射试验的，应当依法向省无线电管理机构申请办理临时设置、使用无线电台（站）手续。\n第二十六条 生产或者进口在国内销售、使用的微功率短距离无线电发射设备，应当按照有关规定在微功率短距离无线电发射设备以及使用说明中标注微功率短距离无线电发射设备的专用标识。\n使用微功率短距离无线电发射设备的单位或者个人应当遵守国家有关规定，不得擅自改变使用场景、扩大发射频率范围、加大发射功率、擅自更改发射天线，不得对依法设置、使用的无线电台（站）产生有害干扰。对依法设置、使用的无线电台（站）产生有害干扰的，应当立即停止使用，在采取措施消除有害干扰后方可继续使用。\n第二十七条 生产、维修、使用民用无人驾驶航空器系统，应当遵守无线电管理法律法规以及国家有关规定。\n省无线电管理机构应当加强对民用无人驾驶航空器系统的无线电发射设备型号核准、无线电频率使用和无线电台（站）设置、使用等情况的监督管理，与有关部门开展技术协作和信息共享，为民用无人驾驶航空器管理工作提供无线电技术支持。\n无人驾驶航空器反制设备的配备、设置以及使用按照国家有关规定执行。\n第二十八条 任何单位或者个人不得擅自设置、使用无线电阻断、压制、干扰设备。\n因维护国家安全、保守国家秘密和保障国家重要考试等需要，确需设置、使用无线电阻断、压制、干扰设备的，应当符合国家、省有关规定，在必要的时间和区域内使用，并接受省无线电管理机构的监督指导。","level":1},{"name":"第五章 无线电监测和电波秩序维护","text":"第二十九条 省无线电管理机构应当定期对无线电频率的使用情况和在用的无线电台（站）进行检查和检测，保障无线电台（站）的正常使用，规范无线电发射设备使用，维护正常的无线电波秩序。\n第三十条 省无线电管理机构应当统筹建设无线电监测设施。县级以上人民政府应当将无线电监测设施建设纳入国土空间规划，保障其建设用地。\n国家机关、国有企业事业单位应当支持无线电监测设施建设，符合条件的公共基础设施应当向无线电监测设施建设开放。\n任何单位或者个人不得侵占、损毁或者擅自拆除无线电监测设施，不得妨碍其正常运行。\n县级以上人民政府应当按照国家有关标准对无线电监测设施周围的电磁环境予以保护。\n第三十一条 航空、航运、铁路等涉及电磁环境保护的重大建设项目，其选址方案的论证、报批，应当征求省无线电管理机构和有关行业主管部门的意见。\n自然资源主管部门在规划高层建筑时，对可能影响重要无线电台（站）电波传播通道的，其选址定点方案应当征求省无线电管理机构的意见。\n第三十二条 辐射无线电波的非无线电设备产生的无线电波辐射，应当符合国家标准和无线电管理的有关规定，不得对无线电业务或者依法设置、使用的无线电台（站）产生有害干扰；产生有害干扰的，设备所有者或者使用者应当采取措施予以消除。\n第三十三条 对船舶、航天器、航空器、铁路机车专用的无线电导航、遇险救助和安全通信等涉及人身安全的无线电频率予以特别保护。任何无线电发射设备和辐射无线电波的非无线电设备对其产生有害干扰的，应当立即消除有害干扰。\n第三十四条 举办重要会议、体育赛事、文化旅游活动等重大社会活动需要无线电安全保障的，主办单位或者承办单位应当向省无线电管理机构提出保障需求，并提供开展无线电安全保障所需的场所、电力等条件。\n第三十五条 任何单位或者个人有权投诉、举报无线电违法行为。\n省无线电管理机构应当建立健全无线电违法行为投诉、举报制度，向社会公布投诉、举报方式，及时调查和处理投诉、举报，将处理情况告知投诉、举报人，并按照规定给予激励。\n第三十六条 省无线电管理机构实施监督检查时，可以依法采取下列措施：\n（一）进入现场检查、勘验、取证；\n（二）要求被检查、调查的单位或者个人提供有关资料；\n（三）询问当事人和证人，制作询问笔录；\n（四）对非法的无线电发射活动，可以暂扣无线电发射设备或者查封无线电台（站），必要时可以采取技术性阻断措施。\n省无线电管理机构实施监督检查时，相关单位或者个人应当予以配合、协助，不得拒绝、妨碍或者阻挠。\n第三十七条 省无线电管理机构和市场监督管理部门应当加强协作配合、信息共享，依法查处违法生产、销售无线电发射设备的行为。\n第三十八条 省无线电管理机构和公安、应急管理、国防动员、国家安全等部门应当建立无线电安全保障联动机制，做好无线电监测与干扰查处等无线电安全保障工作。\n省无线电管理机构应当与其他省（自治区、直辖市）人民政府有关部门建立无线电管理协作机制，加强无线电监管联动和重大活动无线电安全联合保障，促进无线电管理数据资源共享，提升区域无线电管理水平。\n第三十九条 省无线电管理机构和其他有关部门、单位的工作人员应当对履行职责过程中知悉的通信秘密和无线电信号保密。","level":1},{"name":"第六章 法律责任","text":"第四十条 违反本条例，法律、法规有规定的，从其规定。\n第四十一条 违反本条例第十三条第一款规定，未按照国家规定缴纳无线电频率占用费的，由无线电管理机构责令限期缴纳；逾期未缴纳的，自滞纳之日起按日加收万分之五的滞纳金。\n第四十二条 违反本条例第十八条第二款规定，为非法设置、使用无线电台（站）提供场所、设备等便利条件的，由省无线电管理机构责令改正；拒不改正的，没收违法所得，处2千元以上2万元以下罚款。\n第四十三条 违反本条例第二十二条规定，超出业余无线电台使用属性之外的目的使用业余无线电台，或者利用业余无线电台从事营利性活动的，由省无线电管理机构责令改正，没收违法所得，可以并处3万元以下罚款；造成严重后果的，吊销业余无线电台执照，并处3万元以上10万元以下罚款。\n第四十四条 违反本条例第三十条第三款规定，侵占、损毁、擅自拆除无线电监测设施或者妨碍其正常运行的，由省无线电管理机构责令改正；拒不改正的，处2千元以上1万元以下罚款；情节严重的，处1万元以上5万元以下罚款；造成损失的，应当依法赔偿损失。\n第四十五条 国家机关及其工作人员在无线电管理工作中滥用职权、玩忽职守、徇私舞弊的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第四十六条 本条例自2026年12月1日起施行。","level":1}]},{"id":"h0128","sections":[{"name":"","text":"（2006年12月1日湖北省第十届人民代表大会常务委员会第二十四次会议通过）\n第一条 为了加强对农民负担的监督管理，减轻农民负担，保护农民的合法权益，促进社会主义新农村建设和农村社会和谐稳定，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例对下列涉及农民负担事项实施监督管理：\n（一）村范围内集体公益事业筹资；\n（二）农民直接受益的小型基础设施建设投工投劳；\n（三）易涝地区规定范围内公益性排涝水费；\n（四）行政事业性和经营服务性收费；\n（五）对村级集体经济组织和农民专业合作经济组织的收费；\n（六）农民承担的其他费用和劳务。\n对农民的补贴补偿和村级财政性补助资金的发放和使用，纳入农民负担监督管理的范围。\n第三条 各级人民政府负责本行政区域内的农民负担监督管理工作，落实谁主管、谁负责的部门责任制，建立健全分工协作、齐抓共管的工作机制。农民负担监督管理工作纳入各级领导干部岗位目标责任制，并作为考核领导干部的重要内容。\n各级人民政府应当在推进社会主义新农村建设过程中，加大对农业和农村公益事业的投入，指导、帮助和促进农村经济社会的发展。\n第四条 县级以上人民政府农业行政主管部门或者农民负担监督管理主管部门（以下统称农民负担主管部门）主管本行政区域内的农民负担监督管理工作，其工作经费应当列入本级年度财政预算。\n各级农民负担主管部门的职责是：\n（一）宣传贯彻有关农民负担的法律、法规和政策，组织实施本条例；\n（二）会同相关部门审核本级人民政府各部门和其他单位涉及农民负担的文件及规定、措施；\n（三）受理有关农民负担问题的举报和投诉，负责或者会同有关部门对违反本条例的行为进行调查处理；\n（四）对筹资筹劳、公益性排涝水费、土地征用补偿费、村级财政性补助资金等的管理、使用及收支情况组织开展专项审计；\n（五）建立和完善农民负担监测网点和监管机制，培训农民负担监督管理工作人员；\n（六）应当履行的其他职责。\n第五条 县级以上人民政府的发展改革、财政、价格、监察、工商、审计、信访等有关部门应当按照各自的职责，配合农民负担主管部门依法做好农民负担监督管理工作。\n各级涉农部门应当及时查处和纠正本部门、本系统加重或者变相加重农民负担的行为。禁止借助行政权力在办理农民婚姻登记、计划生育、住房建设、外出务工、子女入学等相关手续时搭车收取服务费，搭售商品。\n第六条 严格实行农民负担监督卡制度。经批准的筹资和投工投劳项目及标准、排涝水费以及对农民的补贴补偿等，应当由乡（镇）人民政府负责农民负担监督管理工作的机构，组织填入省农民负担主管部门统一印制或者监制的农民负担监督卡，由村民委员会组织发放到农户，并张榜公示。\n村民委员会必须按照农民负担监督卡收费和安排出劳。\n第七条 实行涉农收费公示制度。凡是向农民收取的各项行政事业性收费、实行政府定价和政府指导价的经营服务性收费，执收单位必须事先将收费依据、项目和标准予以公示，并按照公示的规定收费。\n农民对公示内容提出询问的，执收单位应当予以解答。\n第八条 村级范围内筹资筹劳，应当遵循村民自愿、群众受益、量力而行、民主议定、程序规范、上限控制、使用公开的原则，实行“一事一议”。议事范围为建制村，必要时按照受益主体和筹资主体相对应的原则，议事范围可以缩小为自然村或者村民小组。\n筹资的对象为本村户籍在册人口或者所议事项受益人口，筹劳的对象为符合上述条件的劳动力。每人每年承担的出资出劳数额不得突破省人民政府规定的上限控制标准。\n第九条 筹资筹劳应当用于本村范围内小型农田水利基本建设、修建和维护村级道路、血防灭螺、植树造林、村庄建设与整治以及村民会议或者村民代表会议决定需要兴办的其他集体生产、生活等公益事业项目，并注重使用效益。\n除前款规定之外的其他项目，不得列入筹资筹劳的使用范围。\n第十条 需要筹资筹劳的，由村民委员会、十分之一以上的村民联名或者三分之一以上的村民代表联名，提出预案。\n所提预案必须张榜公示，征求村民意见。在充分协商的基础上，由村民委员会将包括筹资筹劳事项、分摊办法、减免措施等内容的方案，提交村民会议或者村民代表会议依照法定程序审议和表决。\n召开村民代表会议讨论筹资筹劳事项的，村民委员会应当邀请村财务监督小组成员参加。村民代表会议有重要分歧意见时，应当提交村民会议决定。\n第十一条 筹资筹劳方案通过后，应当由乡（镇）人民政府负责农民负担监督管理工作的机构报县级农民负担主管部门审核后实施。\n筹资筹劳使用情况，由村财务监督小组审核，村民委员会公布，接受村民监督。\n第十二条 向农民筹资应当在农作物收获后筹集。向农民筹劳按照标准工日计算，原则上以投劳为主，在农闲时安排用工。农民自愿以资代劳的，其工价标准不得突破省人民政府规定的上限。禁止强制农民以资代劳。\n收款结算时，必须出具由省农民负担主管部门监制的内部结算凭证；不出具凭证的，农民有权拒付。\n第十三条 对烈士和因公牺牲军人的遗属、退伍伤残军人、五保户、特困户、丧失劳动能力的村民，应当免除其筹资义务。\n退伍伤残军人、在校学生、孕妇、分娩后未满一年的妇女、男年满六十周岁或者女年满五十五周岁的村民和丧失劳动能力的村民，不承担筹劳义务。\n第十四条 除因特大自然灾害确需农民投工投劳并经县级以上人民政府批准的外，禁止任何单位和个人强制农民无偿投工投劳。\n第十五条 易涝地区县乡两级水利工程农业排涝水费，按照实际受益面积和省人民政府批准的范围和标准分解到户，由财政部门征收，纳入财政专户储存，专项用于易涝地区的公益性排涝，严格实行收支两条线管理。\n第十六条 涉农行政事业性收费项目，必须以法律、法规、国务院及其财政、物价主管部门以及省人民政府的规定为依据。\n涉农行政事业性收费标准的制定和调整，必须由省财政、价格主管部门会同省农民负担主管部门批准，法律、行政法规另有规定的，从其规定。\n任何部门和单位不得违反规定擅自出台涉农收费的文件和措施；对违规出台的，农民有权拒绝。\n第十七条 涉农经营服务性收费，应当坚持公开、公正、自愿委托和质价相符原则。与农业生产和农民生活关系密切的重要经营服务性收费项目，应当列入政府定价目录，实行政府定价或者政府指导价管理。具体范围和目录由省人民政府确定。\n禁止将涉农的政府公益性服务由无偿变为有偿服务；禁止强制服务收费或者只收费不服务。政府公益性服务机构推介农业生产、生活资料不得从中牟利。\n第十八条 在农民、村集体经济组织以及农村中小学校中发行报刊书籍、开展保险，必须遵循自愿原则；禁止利用行政手段、行业权力强行征订报刊书籍或者强制投保。国家规定强制保险的除外。\n第十九条 行政机关、事业单位在农村设置机构或者配备人员所需经费，不得向农民、村集体经济组织以及农民专业合作经济组织摊派。\n任何部门和单位不得强制或者变相强制农民、村集体经济组织以及农民专业合作经济组织提供赞助、资助和捐献财物，不得要求农民出钱、出物、出工开展各类检查评比和达标升级活动。\n禁止村集体经济组织擅自设立项目向农民收费或者违法采用押金、违约金、罚款等方式管理村务。\n第二十条 农村中小学校收费必须严格执行国家和省有关规定，不得擅自向学生集资、摊派和滥收费用；向学生提供服务，必须坚持学生自愿原则，不得强制学生接受各种经营性服务。\n禁止任何部门和单位向学校或者学生强行摊派各种集资款和其他费用、强行推销各种商品。\n第二十一条 农业灌溉水费由供水单位与村组、农民或者用水单位直接签订合同，据实收取，不得平摊，不得变成固定性收费项目。\n向农民收取电费，必须执行国家和省人民政府的规定，禁止擅自提高收费标准和加收其他费用。\n第二十二条 农副产品收购必须严格执行国家收购政策的有关规定，不得压级压价。农副产品收购部门不得为任何部门和单位代扣农民的交售款。\n化肥、农药、兽药、农膜、种子等农业生产资料的销售列入政府定价目录的，必须严格按照规定执行；实行市场调节价的，不得有不正当价格行为，有法定价格干预措施和紧急措施的必须严格执行。\n第二十三条 政府提供给农民、村集体经济组织以及农民专业合作经济组织的各种补贴、补偿、专项投资、扶贫款、救灾救济款以及财政转移支付资金，任何单位和个人不得截留、抵扣、挪用、拖欠、私分和侵占。\n有关主管部门应当对前款所列款物的拨付和使用情况进行检查、审计，并公布结果，接受监督。\n第二十四条 对涉及农民负担的恶性案件、严重群体性事件或者造成重大影响的其他案（事）件，实行报告制度。案（事）件发生地政府及其有关部门应当立即核实并在1小时内向上一级政府及其有关部门报告，逐级上报到省政府的时间距事件发生不得超过3小时，不得迟报、谎报、瞒报和漏报。特殊情况下，可越级上报。\n案（事）件发生地的市、州和县级农民负担主管部门应当会同监察等部门对案（事）件进行调查，向本级人民政府提出处理建议，并于45日内向省农民负担主管部门上报处理结果。省农民负担主管部门视案（事）件的具体情形，可以会同同级监察等部门直接调查下级管辖的涉及农民负担案（事）件，并提出处理建议。\n第二十五条 县级以上农民负担主管部门和发展改革、财政、价格、监察、工商、审计、信访等部门，应当建立和完善受理农民负担举报、投诉制度，公布农民负担监督举报、投诉电话或者网站等，并加强相互之间的协调、配合。\n第二十六条 对违法增加农民负担的行为，任何组织或者个人有权向县级以上农民负担主管部门或者发展改革、财政、价格、监察、工商、审计、信访等部门举报、投诉。举报、投诉的受理和处理程序按照国家和省信访条例的有关规定执行。\n第二十七条 各级人民政府应当有计划、有重点地组织开展农民负担执法检查和专项检查，将检查情况及时通报，并向上一级人民政府报告。\n第二十八条 违反本条例规定有下列行为之一的，由农民负担主管部门批评教育，责令限期纠正。情节严重的，由行政主管机关或者行政监察机关依法追究责任单位主要负责人和直接责任人的责任，并可以对单位及相关责任人予以通报批评；构成犯罪的，由司法机关依法追究刑事责任：\n（一）未按照规定程序筹资筹劳、擅自改变资金用途或者劳务使用范围的；\n（二）向农民超限额筹资筹劳、无偿调用劳动力、强制收取以资代劳款的；\n（三）截留、抵扣、挪用、拖欠、私分、侵占政府提供给农民、村集体经济组织以及农民专业合作经济组织的各种资金、物资的；\n（四）强制农民参加保险、接受有偿服务、强行推销商品、报刊、书籍的；\n（五）违反规定向学校和学生收费、集资、摊派的；\n（六）涉农收费应当公示未予公示的；\n（七）阻止或者妨碍农民负担主管部门依法行使监督管理权的；\n（八）迟报、谎报、瞒报和漏报涉及农民负担恶性案件、严重群体性事件或者造成重大影响的其他案（事）件的；\n（九）其他违反本条例的行为。\n擅自向农民、村集体经济组织以及农民专业合作经济组织设置收费、集资、罚款和摊派项目的，由同级农民负担主管部门报请同级人民政府决定予以撤销，或者由上级农民负担主管部门会同本级主管部门责令其撤销；已非法收取款物的，责令退还。拒不退还款物的，对行政机关，由上级农民负担主管部门没收款物退还给农民；对企事业单位，由当地农民负担主管部门没收款物退还给农民，并处非法收取金额或者财物等值1倍以上3倍以下的罚款。\n第二十九条 对违反本条例规定，引发恶性案件、严重群体性事件或者造成重大影响的其他案（事）件的县、乡级人民政府和市、县级有关部门，应当追究其主要负责人和直接责任人的行政责任。具体办法由省人民政府规定。\n第三十条 农民负担主管部门和政府其他有关部门的工作人员不履行监督管理职责或者玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门给予行政处分；构成犯罪的，依法追究刑事责任。\n第三十一条 本条例自2007年2月1日起施行。1994年5月12日湖北省第八届人民代表大会常务委员会第七次会议审议通过、1997年12月3日湖北省第八届人民代表大会常务委员会第三十一次会议修订的《湖北省农民负担管理条例》同时废止。","level":0}]},{"id":"h0129","sections":[{"name":"","text":"（2007年3月29日湖北省第十届人民代表大会常务委员会第二十六次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了加强农村公路的建设、养护和管理，适应社会主义新农村建设需要，根据《中华人民共和国公路法》和有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内农村公路的规划、建设、养护和管理，适用本条例。\n本条例所称农村公路，是指按照国家技术标准修建的县道、乡道和村道。\n第三条 农村公路的发展应当遵循政府主导、各方参与、全面规划、节约土地、保护环境、建养并重、保障畅通的原则。\n第四条 县级人民政府是农村公路建设、养护和管理的责任主体，其交通主管部门具体负责农村公路建设、养护和管理工作。\n乡（镇）人民政府在县级人民政府确定的职责范围内，并在交通主管部门的组织指导下，负责乡道的建设和养护工作；村民委员会在县级人民政府及交通主管部门、乡（镇）人民政府指导帮助下，做好本村村道建设和日常养护的组织实施工作。\n第五条 县级以上人民政府应当把农村公路的建设和发展纳入本行政区域国民经济和社会发展规划和计划，逐步加大政府对农村公路的资金投入，促进农村公路持续健康发展。\n县级以上人民政府发改、财政、建设、国土资源、环境保护、水利、林业、审计、公安等部门，按照各自的职责做好农村公路工作。\n第六条 任何单位和个人都有爱护公路、公路用地及公路附属设施的义务，对破坏、损坏或者非法占用农村公路、公路用地、公路附属设施以及其他影响公路安全的违法行为，有权制止、检举和控告。\n第七条 禁止任何单位和个人在农村公路上非法设卡收费、罚款和拦截车辆。","level":1},{"name":"第二章 规划和建设","text":"第八条 农村公路规划应当根据国民经济和社会发展以及人民群众生产生活、农业生态环境的实际编制，与国道、省道发展规划和其他方式的交通运输发展规划相协调，与社会主义新农村建设规划相结合。\n第九条 县级以上人民政府交通主管部门会同同级有关部门，根据国家和省制定的农村公路规划，编制本行政区域的农村公路规划。\n县道规划由县级人民政府交通主管部门会同同级有关部门编制，经同级人民政府审定后，报上一级人民政府批准，并报省人民政府交通主管部门备案；乡道、村道规划由县级人民政府交通主管部门协助乡（镇）人民政府编制，报县级人民政府批准，并报上一级人民政府交通主管部门备案。\n经批准的农村公路规划需要修改的，由原编制机关提出修改方案，报原批准机关批准。\n农村公路渡口以及客运站场设施应当与农村公路统一规划、统一标准、同步建设。\n第十条 农村公路建设应当充分利用现有道路进行改建和扩建。县道按照不低于三级公路技术标准建设，乡道按照不低于四级公路技术标准建设。村道建设标准应当根据当地实际需要和经济条件确定，一般不低于四级公路技术标准。\n农村公路建设涉及土地征收、征用补偿的，依照有关法律法规的规定执行。\n第十一条 二级以上农村公路及中型以上桥梁、隧道建设项目和其他符合招标条件的农村公路建设项目，应当明确项目法人，并依法进行招标。依照国家有关规定可以不进行招标并采用“一事一议”的方式筹资筹劳的村道建设项目，经村民会议或者村民代表会议同意，可以不进行招标。\n县道建设项目的招标由县级人民政府交通主管部门负责组织。乡道、村道建设项目的招标，在县级人民政府交通主管部门的指导下，由乡（镇）人民政府组织或者委托有相应资质的招标代理机构办理。\n第十二条 村道建设项目的设计可以由县级以上人民政府交通主管部门组织有相关工程设计经验的技术人员承担，但中型以上桥梁、隧道建设项目的设计，应当由具有相应资质的设计单位承担。\n第十三条 县道建设项目的施工许可由市（州）人民政府交通主管部门实施。乡道建设项目的施工许可由县级人民政府交通主管部门实施。村道建设项目的施工应当报乡（镇）人民政府备案。\n第十四条 沥青（水泥混凝土）路面、桥梁、隧道等建设项目，应当选择具有相应资质的专业队伍施工。\n第十五条 二级以上农村公路及中型以上桥梁、隧道建设项目，应当通过招标选择具有相应资质的监理单位进行监理。其他农村公路建设项目，可以由县级人民政府交通主管部门组织进行监理。\n第十六条 县级以上人民政府交通主管部门、乡（镇）人民政府具体负责本行政区域内农村公路建设质量监督管理工作。县级人民政府交通主管部门、乡（镇）人民政府应当聘请技术专家和群众代表参与监督工作。\n农村公路建设施工现场应当设立质量责任公告牌，公告有关责任单位、责任人、主要质量控制指标和质量举报电话。\n第十七条 农村公路建设项目应当建立安全生产责任制和工程质量责任追究制。农村公路建设、施工和监理单位应当依据职责，明确安全、质量管理责任，落实安全、质量保证措施，加强安全与质量管理。\n铺筑沥青（水泥混凝土）路面的农村公路及中型以上桥梁、隧道建设项目，应当设定质量缺陷责任期和质量保证金。质量缺陷责任期为验收合格后1年，建设单位预留施工合同工程款总额的百分之五作为质量保证金。质量缺陷责任期满、无质量缺陷或者质量缺陷得到有效处置后，质量保证金应当返还施工单位。\n第十八条 农村公路建设项目应当进行交工、竣工验收；未经验收或者验收不合格的，不得交付使用。交工验收由项目法人负责。县道、乡道的竣工验收，按照本条例第十三条规定的施工许可权限，由县级以上人民政府交通主管部门负责；村道的竣工验收，由乡（镇）人民政府在县级人民政府交通主管部门的指导下组织进行。\n除二级以上农村公路及大型以上桥梁、隧道建设项目外，其他农村公路建设项目交工、竣工验收可以合并进行。\n建成的农村公路，应当按照国家有关规定设置必要的交通标志。\n第十九条 农村公路建设应当按照档案管理有关规定，收集、整理、保存工程资料，建立工程档案。","level":1},{"name":"第三章 养护和管理","text":"第二十条 农村公路养护应当按照技术规范和操作规程进行，做到路基、边坡稳定，路面、构造物完好，排水畅通，保证公路处于良好的技术状态。\n第二十一条 农村公路养护实行专业养护与群众养护、常年养护与季节性养护相结合的方式，并逐步实行以专业养护为主。\n四级以上农村公路大中修养护工程，逐步采取向社会公开招标的方式，择优选定养护作业单位；对等级较低、自然条件特殊、养护困难的农村公路，可以委托国道、省道养护单位养护，也可以采取建设、改造和养护一体化招标等方式进行养护。\n乡道、村道的日常养护由沿线乡（镇）人民政府、村民委员会采取群众性养护组织或者其他养护组织形式进行，也可以采取个人（农户）分段承包等方式进行。\n第二十二条 农村公路养护单位、组织或者个人在进行养护作业时，应当设置必要的交通安全设施与安全警示标志。县道、乡道因养护确需中断交通的，应当报县级以上人民政府交通主管部门同意，并采取必要形式提前向社会公告；村道养护确需中断交通的，应当报告村民委员会并告知村民。\n第二十三条 因严重自然灾害致使农村公路中断或者严重损坏时，县级、乡（镇）人民政府和村民委员会应当及时组织修复。必要时可以动员和组织沿线机关、团体、企业事业单位、当地群众进行抢修，尽快恢复交通。\n第二十四条 县级、乡（镇）人民政府和村民委员会应当按照绿化规划和谁种植、谁管理、谁受益的原则，组织和发动农村公路沿线的单位和个人实施公路绿化。属村民委员会集体种植的公路树木归集体所有，其收益主要用于村道养护。\n公路用地上的树木不得擅自砍伐，确需更新砍伐的，依照《中华人民共和国森林法》和有关法律法规的规定办理审批手续，并完成更新补种任务。\n第二十五条 村道两侧边缘起向外延伸不少于1米的范围为公路用地；村道两侧边缘起向外延伸不少于3米的范围为建筑控制区。村道公路用地和建筑控制区由县级人民政府划定并向社会公告。\n任何单位和个人不得在公路上及公路用地范围内非法挖砂、采石、取土、堆放物品、设置障碍、挖沟引水或者从事种植农作物、打场晒粮、倾倒垃圾、排放污物等损坏、污染公路以及影响公路安全畅通的行为，不得损毁、擅自移动、涂改公路标志或者擅自设置其他标志。除公路防护、养护需要外，禁止在村道建筑控制区内新建、扩建建筑物和地面构筑物。\n第二十六条 超过农村公路限定荷载标准的车辆不得擅自在农村公路上行驶。确需行驶的，必须经县级人民政府交通主管部门批准，并按照要求采取有效的防护措施；运载不可解体的超限物品的，应当按照指定的时间、路线、时速行驶，并悬挂明显标志。","level":1},{"name":"第四章 资金筹集与使用","text":"第二十七条 各级人民政府应当建立政府投资为主、农村村组为辅、鼓励社会各界共同参与的农村公路建设、养护和管理资金筹集机制。\n第二十八条 省人民政府对列入省级农村公路建设计划的建设项目实行定额补助。县级人民政府应当相应安排配套补助资金，并与省安排的定额补助资金同步到位。\n第二十九条 省人民政府交通主管部门应当按照国家规定并结合县（市）经济发展状况，统筹安排农村公路养护工程管理资金。县级人民政府应当根据省人民政府的规定，按照每年每公里一定数额的标准，安排乡道、村道的日常养护管理资金，并列入本级财政预算。\n第三十条 村民委员会采取“一事一议”筹资筹劳的方式筹集村道建设、养护资金，应当遵循村民自愿、量力而行的原则，并按照有关法律法规的规定办理。\n农村公路建设不得损害农民利益，不得采用强制手段向单位和个人集资。\n第三十一条 鼓励社会、企业事业单位和个人捐资用于农村公路建设、养护和管理；对做出突出贡献的，由县级以上人民政府予以表彰。\n第三十二条 农村公路建设、养护和管理资金应当严格管理、专款专用，实行年度审计制度，任何单位和个人不得侵占、挪用和截留。\n未完工项目的建设资金以及当年节余的养护和管理资金，可以结转下年度使用。","level":1},{"name":"第五章 法律责任","text":"第三十三条 违反本条例规定的行为，法律、行政法规有行政处罚规定的，从其规定；构成犯罪的，依法追究刑事责任；造成农村公路损害的，依法承担民事责任。\n第三十四条 违反本条例规定，有下列行为之一的，对责任单位予以通报批评，责令限期整改；情节严重的，对责任人依法给予行政处分：\n（一）农村公路建设、养护资金未按时到位的；\n（二）侵占、挪用和截留农村公路建设、养护资金的；\n（三）农村公路未经验收或者验收不合格即交付使用的；\n（四）在农村公路建设中采用强制手段向单位、个人集资的。\n违反本条例规定，在农村公路建设中发生质量违法行为的，依法对相关责任单位和责任人予以处罚。\n第三十五条 违反本条例规定，损坏、污染村道或者影响村道安全畅通的，或者损毁、擅自移动、涂改村道标志、擅自设置其他标志的，责令停止违法行为，限期改正。\n第三十六条 违反本条例规定，在村道建筑控制区内新建、扩建建筑物和地面构筑物的，责令限期拆除；逾期不拆除的，可以依法强制拆除，有关费用由违法者承担。\n第三十七条 违反本条例规定，超过限定的荷载标准擅自在村道上行驶的，责令停止违法行为，并处500元以上5000元以下罚款。\n第三十八条 国家工作人员在农村公路建设、养护和管理等工作中玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分。","level":1},{"name":"第六章 附则","text":"第三十九条 本条例自2007年6月1日起施行。","level":1}]},{"id":"h0130","sections":[{"name":"","text":"（2007年7月28日湖北省第十届人民代表大会常务委员会第二十八次会议通过 根据2014年9月25日湖北省第十二届人民代表大会常务委员会第十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》第三次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了促进农业机械化的发展，加强农业机械管理，维护农业机械使用者、生产者、经营者的合法权益，根据《中华人民共和国农业机械化促进法》等有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本条例所称农业机械，是指用于农业生产及其产品初加工等相关农事活动的机械、设备。\n第三条 在本省行政区域内从事农业机械科研、生产、经营、推广、使用、教育培训和监督管理等活动，适用本条例。\n第四条 县级以上人民政府应当将促进农业机械化纳入国民经济和社会发展规划，加大对农业机械化的资金投入和政策扶持，加强农业机械安全生产管理，完善农业机械化服务体系，促进农业机械化的发展。\n对促进农业机械化做出显著成绩的单位和个人，给予表彰、奖励。\n第五条 县级以上人民政府农业（农业机械）主管部门负责本行政区域的农业机械管理工作；其他有关部门按照各自的职责，相互配合，依法做好农业机械管理的相关工作。","level":1},{"name":"第二章 科技推广和质量保障","text":"第六条 县级以上人民政府根据农业和农村经济发展的需求，采取具体措施，鼓励和支持研究开发和引进先进适用、节能环保的农业机械及技术，对获得自主知识产权并有重要推广价值的农业机械科技成果实行专项资金扶持。\n鼓励高等学校、科研单位开办农业机械教育专业和拓展研究领域，通过普通教育、职业教育等多种形式培养农业机械专业人才；支持以科研开发、科研成果转让和科研成果投资入股以及合资合作等多种方式促进农业机械科研成果的转化。\n第七条 县级以上人民政府农业（农业机械）主管部门应当科学编制农业机械化技术推广规划和重点推广技术的年度计划，并按照规定程序组织实施。\n县级以上人民政府应当安排专项资金，用于农业机械新技术、新机具的推广和农业机械化综合示范区的建设。农业机械技术推广机构应当为农民和农业生产经营组织无偿提供公益性农业机械技术的推广与培训等服务。\n县级以上人民政府及其农业（农业机械）主管部门应当根据血吸虫疫区实际和以机代牛的需要，扶持、帮助血吸虫疫区提高农业机械化水平。\n第八条 省农业行政主管部门根据国家有关规定，会同同级财政、发展改革部门，按照公开、公平、公正的原则，确定、公布省支持推广的先进适用的农业机械产品目录，并定期调整。列入目录的产品，经农业机械生产者自愿提出申请，并通过省农业机械鉴定机构进行的先进性、适用性、安全性和可靠性鉴定，由省农业行政主管部门颁发农业机械推广鉴定证书和标志。\n禁止伪造、变造、转让和超期使用农业机械推广鉴定证书和标志。\n第九条 农业机械产品、维修、作业等质量标准应当执行国家标准或者行业标准。没有国家标准或者行业标准的，依法制定地方标准。\n对涉及人身安全、农产品质量安全和环境保护的农业机械产品，应当严格按照国家强制执行的技术规范执行。\n第十条 市场监督管理部门应当依法加强对农业机械产品质量的监督管理，督促农业机械生产者、销售者依法对其生产、销售的农业机械产品质量及相关售后服务负责。\n农业（农业机械）主管部门应当根据农业机械使用情况和农业生产的实际需要，定期组织对在用的农业机械产品的适用性、安全性、可靠性和售后服务状况进行调查，并公布调查结果。\n市场监督管理、农业（农业机械）主管部门应当设立举报、投诉电话和监督信箱，受理有关农业机械产品质量、维修质量和作业质量举报或者投诉。\n第十一条 农业机械鉴定机构受农业机械生产者或者销售者的委托，对其定型生产或者销售的农业机械产品进行适用性、安全性和可靠性检测，作出技术评价，并公布检测结果。","level":1},{"name":"第三章 社会化服务和扶持措施","text":"第十二条 各级人民政府应当采取措施，鼓励和扶持农业生产经营者共同使用、合作经营农业机械，培育和发展农业机械大户、农业机械专业服务组织，开拓和规范农业机械销售、维修和作业等服务市场，推进农业机械服务社会化，促进农业机械化和农业集约经营的有效结合。\n鼓励农业机械生产者、经营者、维修者依照法律、法规的规定，组织成立行业协会，实行行业自律，为会员提供服务，维护会员的合法权益。\n第十三条 县级以上人民政府及其农业（农业机械）主管部门应当建立农业机械信息网络，为农民和农业生产经营组织免费提供农业机械产品供求、作业市场需求、新产品及新技术推广、科研成果和农业机械管理等信息服务。\n第十四条 县级以上农业（农业机械）主管部门应当对农业机械跨行政区域作业实施组织协调和监督管理。\n公安、交通等部门应当采取有效措施，为跨区作业者提供通行、作业便利，维护作业秩序，保障作业者的人身和财产安全。\n跨行政区域作业的农业机械及其运输车辆通行费的减免，执行国家有关规定。\n第十五条 县级以上农业（农业机械）主管部门应当指导、促进农业机械维修网络建设，监督、规范农业机械维修市场秩序，提高农业机械维修质量。\n农业机械维修业务管理按照国家有关规定执行。\n第十六条 县级以上人民政府应当对农业机械生产企业的科研开发、技术创新、产品升级换代等给予资金扶持，并落实国家有关的金融、税收优惠政策。\n第十七条 各级人民政府应当鼓励、指导、扶持农民和农业生产经营组织购买、使用先进适用的农业机械。省财政应当依法安排专项资金，对农民和农业生产经营组织购买国家和地方政府支持推广的农业机械给予补贴，并根据农业机械化的发展需要逐步增加。\n第十八条 农民和农业生产经营组织从事农业机械生产作业的，享受国家规定的燃油补贴和农用电价。\n第十九条 各级人民政府应当增加对农村机耕道路、农业机械集中存放场库棚的建设和维护的投入，为农业机械作业创造条件。\n第二十条 发生自然灾害时，当地人民政府可以依法征用农业机械用于抢险救灾，并给予相应补偿。","level":1},{"name":"第四章 安全监督管理","text":"第二十一条 县级以上人民政府农业（农业机械）主管部门所属的农业机械安全监督管理机构（以下简称农机监理机构），依照法律规定负责本行政区域内农业机械的登记、检验及驾驶证的核发、审验，对在田间、场院、村道以及道路交通安全法规定以外的道路上行驶、作业的农业机械实施安全检查、违法违章行为的纠正处理和事故处理。\n农业机械的行驶证、驾驶证、号牌和检验合格标志由省农机监理机构监制。\n第二十二条 拖拉机、联合收割机等自走式农业机械应当经农机监理机构登记，并核发号牌、行驶证后，方可使用。\n申请拖拉机、联合收割机等自走式农业机械注册登记的，应当提交下列证明、凭证：\n（一）所有人的身份证明；\n（二）购机发票或者其他来历证明；\n（三）出厂合格证明或者进口凭证；\n（四）拖拉机交通事故责任强制保险凭证；\n（五）法律、行政法规规定应当提交的其他证明、凭证。\n第二十三条 驾驶拖拉机、联合收割机等自走式农业机械，应当向农机监理机构申领驾驶证。\n农机监理机构应当对符合国家规定的驾驶许可条件的申请人进行考试。考试合格的，核发驾驶证，并定期审验。\n第二十四条 对登记后的拖拉机、联合收割机等自走式农业机械，应当定期进行安全技术检验；检验合格的，由农机监理机构核发检验合格标志；未经检验或者检验不合格的，不得继续使用。\n第二十五条 农业机械驾驶、操作人员必须遵守国家有关法律、法规和农业机械安全操作规程，不得实施下列行为：\n（一）拖拉机违法载人或者超载货物；\n（二）驾驶、操作安全设备不全或者机件失灵的农业机械；\n（三）饮酒或者患有妨碍安全驾驶的疾病者驾驶、操作农业机械；\n（四）使用伪造、变造的登记证书、行驶证、驾驶证、号牌及检验合格标志。\n第二十六条 拖拉机驾驶培训学校、驾驶培训班应当按照国家有关规定，对学员进行相关法律、法规和驾驶技能的培训，保证培训质量。\n农业（农业机械）主管部门及其所属的农机监理机构，不得参与举办拖拉机驾驶培训学校、驾驶培训班。\n第二十七条 各级人民政府及其农业（农业机械）主管部门、农机监理机构应当加强农业机械安全法律、法规的宣传，指导、帮助村民委员会和农业生产经营组织对农业机械驾驶、操作人员进行经常性的安全教育。\n农机监理机构对非登记管理的脱粒机、粉碎机、插秧机、耕整机等容易造成人身伤害的农业机械的操作人员，应当免费进行安全教育和技术培训，并实施安全监督管理。\n第二十八条 农业机械行驶、作业时，造成人身伤亡和财产损失事故的，当事人应当立即向农机监理机构报告，农机监理机构接到事故报告后，应当及时调查处理。对属于公安机关调查处理范围内的事故，移送公安机关依法处理。\n发生重大、特大农机事故时，农机监理机构应当及时报告当地人民政府及有关部门。\n第二十九条 农机监理机构在处理违法违章行为和农机事故时，根据调查取证的需要可以暂扣当事人驾驶证、行驶证，并出具凭证；必要时可以指令当事人将肇事的农业机械停放到指定地点。处理完毕后，应当及时将所扣证件归还当事人。\n第三十条 公安机关、农业（农业机械）主管部门应当按照各自的职责，密切配合，共同做好农业机械交通安全监督管理工作。\n农机监理机构应当定期向公安机关交通管理部门提供拖拉机登记、安全技术检验以及拖拉机驾驶证发放的资料、数据。\n公安机关交通管理部门对拖拉机驾驶员作出暂扣、吊销驾驶证处罚或者记分处理的，应当定期将处罚和记分情况通报有关农机监理机构。\n第三十一条 农机监理工作人员在执行职务时，应当衣着整齐，佩带统一的“农机监理”标识，出示执法证件，文明、公正执法，接受群众监督。任何单位和个人不得拒绝、阻碍农机监理工作人员依法执行职务。\n农机监理机构在履行职责时，应当严格执行国家收支两条线的规定，罚没收入全额上缴财政，其工作经费由同级财政予以保证。","level":1},{"name":"第五章 法律责任","text":"第三十二条 违反本条例的行为，法律、行政法规有处罚规定的，从其规定。\n第三十三条 违反本条例第八条第二款规定的，由农业（农业机械）主管部门责令停止违法行为，没收违法所得，可处500元以上2000元以下的罚款；情节严重的，处2000元以上3万元以下的罚款。对滥用农业机械推广鉴定证书和标志的，注销其农业机械推广鉴定证书和标志，并予以公告。\n第三十四条 违反本条例规定，有下列行为之一的，由农机监理机构给予警告，责令停止违法行为，可处20元以上100元以下罚款；情节严重的，处100元以上500元以下罚款：\n（一）无驾驶证或者驾驶证未经审验及审验不合格驾驶农业机械的；\n（二）驾驶未办理登记注册或者驾驶未经安全技术检验及检验不合格的农业机械的；\n（三）违法载人或者超载货物的；\n（四）酒后驾驶作业的；\n（五）使用伪造、变造的登记证书、行驶证、驾驶证、号牌及检验合格标志的；\n（六）其他违法行为。\n第三十五条 拖拉机、联合收割机在行驶、作业过程中造成人身伤亡事故后驾驶人逃逸的，由农机监理机构吊销其驾驶证，且终生不得重新取得驾驶证；当事人故意破坏、伪造现场或者毁灭证据导致事故责任无法认定的，承担全部责任。\n第三十六条 农业（农业机械）主管部门、农机监理机构及其工作人员有下列行为之一的，由上级主管部门或者监察机关责令限期改正，对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）为不符合法定条件的农业机械或者驾驶人员发放登记证书、行驶证、驾驶证、号牌及检验合格标志的；\n（二）擅自制作农业机械登记证书、行驶证、驾驶证、号牌及检验合格标志的；\n（三）截留、挪用财政专项资金或者罚没收入的；\n（四）其他滥用职权、玩忽职守、徇私舞弊行为。","level":1},{"name":"第六章 附则","text":"第三十七条 本条例自2007年10月1日起施行。1998年7月31日湖北省第九届人民代表大会常务委员会第四次会议通过的《湖北省农业机械管理条例》同时废止。","level":1}]},{"id":"h0131","sections":[{"name":"","text":"（2007年9月29日湖北省第十届人民代表大会常务委员会第二十九次会议通过 根据2014年9月25日湖北省第十二届人民代表大会常务委员会第十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正）\n第一条 为了发展职业教育，提高劳动者素质，促进经济建设和社会发展，根据《中华人民共和国职业教育法》等法律、法规的规定，结合本省实际，制定本办法。\n第二条 本办法适用于本省行政区域内各类职业学校教育和职业培训。国家机关工作人员的专门培训按国家有关规定执行。\n职业学校教育主要指中、高等职业学校学历职业教育，职业培训包括就业前、在岗、转岗转业、学徒培训等各种类型的非学历职业教育。\n第三条 职业教育是国家教育事业的重要组成部分。发展职业教育，应当从经济建设和社会发展的实际需要出发，综合利用各类教育资源，逐步建立职业学校与职业培训并举、适应市场和劳动就业需求、结构合理、灵活开放的现代职业教育体系。\n重点发展中等职业教育，中等职业教育招生规模应当与普通高中招生规模大体相当；积极发展高等职业教育，满足经济和社会发展对高技能人才的需求；广泛开展各种形式的职业培训，有计划、有重点地组织开展对城乡劳动者职业技能培训。\n第四条 实行政府主导、依靠企业、充分发挥行业作用、社会力量积极参与、公办与民办共同发展的职业教育体制。各级人民政府应当将发展职业教育纳入本行政区域内经济和社会发展规划，通过多种方式统筹配置和优化职业教育资源，加大对职业教育事业的经费投入，加强对发展职业教育的宣传和舆论引导，并实行职业教育发展目标考核责任制。\n第五条 县级以上人民政府教育行政部门负责本行政区域内职业教育工作的统筹规划、综合协调和宏观管理；劳动和社会保障行政部门负责技工学校和以技能为主的职业培训工作的管理；其他有关行政部门按照各自职责，分别负责职业教育的有关工作。\n行业主管部门或者行业协会应当开展本行业人才需求预测并向教育、劳动和社会保障行政部门、职业学校和职业培训机构提供相关信息，积极支持和参与培养适应本行业需求的人才。\n县级以上人民政府建立职业教育工作部门联席会议制度，研究、协调、解决职业教育发展中的重大问题。\n第六条 各级人民政府及其教育、劳动和社会保障行政部门应当加强对各类职业学校、职业培训机构的管理和服务，并充分发挥公办职业学校、培训机构在公平办学、规范办学、提高办学质量方面的引导作用。\n各市、州应当重点建设好一所高等职业学校和若干所中等职业学校；各县（市）应当重点办好一所中等职业学校。\n第七条 鼓励和支持公民、法人和其他组织依法出资举办职业学校和职业培训机构。\n企业事业组织可以依法举办或者联合举办职业教育机构；也可以委托职业学校和职业培训机构对本单位的职工和准备录用人员实施各种形式的职业教育。\n鼓励民间资本通过捐资、参股等多种形式参与公办职业学校和职业培训机构的建设和发展。\n鼓励境内外机构和个人对职业教育提供资助和捐赠。境外机构和个人可以依照有关法律法规的规定，与境内机构和个人合作举办职业学校或者职业培训机构。\n第八条 设立职业学校或者职业培训机构，应当符合国家规定的条件，其所使用的名称，应当与其办学、培训的类型、层次等相适应，不得违反国家法律、法规的有关规定。省教育行政部门会同省劳动和社会保障行政部门就职业学校和职业培训机构名称的规范使用作出具体规定。\n第九条 设立高等职业学校由省人民政府审批，并报国家教育行政主管部门备案。\n设立中等职业学校由市（州）教育行政部门审批，其中技工学校的设立由市（州）、直管市、神农架林区劳动和社会保障行政部门审批。\n设立以技能为主的职业培训机构由县级以上人民政府劳动和社会保障行政部门审批。\n职业学校、职业培训机构设立、变更或者终止应当依法办理相关登记手续的，按照国家有关规定执行。\n第十条 职业学校或者职业培训机构的举办者应当按照国家规定的设立条件，向审批部门提交下列相关材料：\n（一）申办报告，包括培养目标、办学规模、办学层次、办学形式、办学条件、专业设置、发展规划等；\n（二）举办者的基本情况及相关资格证明文件；\n（三）拟任学校或者培训机构的主要负责人、教师的资格证明文件；\n（四）资产及经费来源的证明文件；\n（五）章程和管理制度。\n联合举办职业学校或者职业培训机构的，还应当提交联合办学合同。\n第十一条 职业学校和职业培训机构依法享有办学自主权，自主决定发展规划、专业设置、教学内容、教材选用、教师聘用以及自有资金的使用等事项。\n各级人民政府及其教育、劳动和社会保障行政部门及其他有关部门，应当依法保护职业学校和职业培训机构的办学自主权，为职业教育发展提供良好的公共服务和社会环境。\n第十二条 农村职业教育应当以培养农村实用人才为重点，与农村劳动力转移相结合，充分发挥农村各类职业学校、乡镇成人文化技术学校和农村技术推广培训机构在提高农村劳动力技能方面的作用。\n各级人民政府应当采取切实有效措施，加大对农村职业教育，尤其是贫困地区职业教育的扶持力度，优化农村教育布局和结构，办好农村职业学校和职业培训机构，完善农村职业教育网络。\n财政、教育、劳动和社会保障、农业、科技、扶贫等行政部门和组织，应当结合各自的职责为农村职业教育和农村劳动力的培训在经费、师资、场所、内容、信息等方面提供指导、帮助和服务。\n鼓励农村普通高中因地制宜地开设职业教育课程，适当增加职业教育教学内容。\n第十三条 注重发展残疾人职业教育。职业学校和职业培训机构应当依法接纳残疾学生，并安排好其学习和生活。\n第十四条 鼓励退役士兵到职业学校和职业培训机构接受职业教育。职业学校和职业培训机构可以根据退役士兵的特点，在招生录取、学制、教学时间、教学内容以及推荐就业等方面作出相应的优惠安排。\n第十五条 职业学校和职业培训机构应当运用计算机网络技术和网上教育资源等现代化教学手段开展职业教育，并面向全体学生开设信息技术课程。\n第十六条 鼓励职业学校和职业培训机构积极引进境外资金、人才、教材和设备，加强境内外交流和合作，学习借鉴先进的职业教育教学方法、管理手段、教育模式，提高职业教育的水平和质量。\n第十七条 教育、劳动和社会保障行政部门应当建立规范有序的职业教育招生制度，工商行政管理部门和新闻媒体应当依法加强对职业教育招生广告的审查和审核，禁止利用虚假广告招揽生源、扰乱招生秩序。在职业教育招生中，利用虚假广告欺骗误导他人的，工商行政管理部门应当依法及时查处。\n第十八条 对职业学校学生和接受职业培训的学生按照国家有关规定经考核合格后，分别发给学历证书、培训证书。\n职业学校的毕业生经过国家规定的选拔程序，可以接受高一级学校教育。\n第十九条 县级以上人民政府及其有关部门应当加强职业教育实训、实习基地建设，为职业学校学生增强实践能力和职业技能，实现职业教育的工学结合、校企合作提供服务和帮助。\n鼓励企业到职业学校参加实训基地建设，开展职业技能的教学示范活动。职业学校在校学生到企业事业单位进行生产实习的时间按照国家有关规定执行。\n省国有资产管理、经济、教育、劳动和社会保障等行政部门应当共同建立并落实企业接受职业学校学生实习的制度，拟定职业学校学生实习基地的企业名录，并予以公布。企业对于实习的学生、教师，应当依照国家有关规定安排适当的实习岗位并提供劳动安全保护，给予合理的劳动报酬。任何单位和个人不得克扣。企业积极履行接受职业学校学生实习义务的，依照国家有关规定享受税收优惠等政策。\n第二十条 职业学校毕业生申请与所学专业相关的中级以下职业技能鉴定时，免除理论考试；部分教学质量高、社会声誉好的中、高等职业学校开设的主要专业，经劳动和社会保障、教育和有关行政部门认定，其毕业生在获得学历证书的同时，可视同职业技能鉴定合格，取得相应的职业资格证书。颁发职业资格证书除工本费外，不得收取其他费用。\n第二十一条 县级以上人民政府及其有关部门应当采取有效措施，拓宽就业渠道，为职业学校毕业生和职业培训机构培训合格人员自主择业提供条件。\n人才市场、劳动力市场管理机构和毕业生就业服务机构应当定期向社会以及职业学校和职业培训机构提供人才、劳务需求信息，建立和完善推荐职业学校毕业生和培训合格人员就业的渠道和网络。\n用人单位应当严格执行国家有关就业准入制度。鼓励用人单位优先录用、聘用取得职业学校学历证书、职业资格证书和职业培训合格证书的人员。\n职业学校和职业培训机构可以采取与用人单位签订用人合同、定向培养等方式拓宽就业渠道，提高就业率。\n第二十二条 县级以上人民政府应当将职业教育教师的培养、培训工作纳入教师队伍建设总体规划，保证教师队伍适应职业教育发展的需要。省人民政府及其教育、劳动和社会保障行政部门应当建立职业教育教师的培训基地，组织职业教育教师到高等院校、企业进行免费培训。省和有条件的市、州应当每年拟定职业教育教师的培训计划，并公布实施。\n鼓励高等学校优秀毕业生和有实践经验的专业技术人员到职业学校和职业培训机构任教、兼职，职业学校和职业培训机构的专业教师和实习指导教师可以兼评其他专业技术职务（技术等级）。兼职教师的报酬由聘任的职业学校发给，兼职教师在原单位的工资、福利待遇不受影响。\n第二十三条 县级以上人民政府及其有关部门应当建立健全职业教育研究机构，组织做好职业教育教研、科研活动，加强面向企业、面向市场、面向社会实践的职业教育教材的研究、编辑、出版和发行。\n第二十四条 县级以上人民政府应当将职业教育经费列入本级财政预算，合理调整教育经费的支出结构，逐步增加公共财政对职业教育投入。\n建立职业教育专项经费，用于支持职业教育示范性学校和重点专业建设、实训基地建设、师资培养培训、农村贫困地区和少数民族地区的职业教育发展。\n城市教育费附加用于职业教育的比例不低于30%，农村贫困地区不低于50%。农村成人教育经费应当按照规定标准筹措和统筹安排。\n职业学校举办者应当按照学生人数平均经费标准足额拨付职业教育经费，并专款专用。\n职业学校学生人均经费标准由省人民政府制定。\n第二十五条 县级以上人民政府应当建立、完善职业教育的奖励、助学制度，依照国家规定对职业教育在校学生给予奖学金、助学金、助学贷款等帮助。\n职业学校的奖学金、助学金、助学贷款的发放、使用和管理情况必须予以公布，财政、教育、劳动和社会保障行政部门应当予以监督，审计部门依法予以审计。\n第二十六条 各类企业应当依法实施职业教育和职工培训，并承担相应的费用。根据企业从业人员的技术要求、培训任务、经济效益等不同情况，按照不低于职工工资总额1.5%至2.5%的比例提取职工教育培训经费，列入成本开支和专项科目，专款专用。企业技术改造和项目引进，应当安排资金用于职工技术培训。企业人数较少，不能自行组织所属职工开展职业培训的，可以委托具备相应条件的职业学校或者职业培训机构进行培训。\n第二十七条 中等以上职业学校和职业培训机构依照法律规定可以向学生收取学费。收费标准由省财政、物价行政部门会同省教育、劳动和社会保障行政部门根据专业情况、人均培养成本和社会承受能力等因素拟订和调整，报省人民政府批准后，向社会公布。\n对经济困难、残疾以及涉及艰苦行业专业的学生，应当酌情减免学费。\n第二十八条 县级以上人民政府及其有关部门应当将职业学校的基本建设纳入城乡建设规划，根据土地利用总体规划和土地利用年度计划，统筹安排职业学校的基本建设用地。\n职业学校用于教学和学生生活的基本建设，免征水电增容、商业网点、城市维护等配套费。\n第二十九条 县级以上人民政府及其有关部门应当切实减轻职业学校和职业培训机构的负担，任何单位和个人不得违反国家和省人民政府的规定，向职业学校和职业培训机构收取费用。对不符合规定的收费，职业学校和职业培训机构有权拒绝缴纳。\n职业学校和职业培训机构依法举办产业，开展社会服务等各项收益，主要用于自身职业教育的发展。\n任何单位和个人不得平调、划拨或者非法征收职业学校和职业培训机构的财产、资金。\n第三十条 各级金融机构应当按照国家有关规定及信贷原则，对职业学校基本建设、教育设备购置和校办产业予以支持。\n第三十一条 鼓励社会各界和公民个人对职业教育提供资助和捐赠，企业和个人对职业教育的资助和捐赠，按照国家规定享受税收优惠政策。\n第三十二条 县级以上人民政府应当建立职业教育督导制度和职业教育质量评估考核体系，定期对下级人民政府的职业教育工作以及职业学校和职业培训机构的办学条件、专业目录、教学管理、教学质量等方面进行督导评估；对人民政府职业教育工作督导评估的重点，包括职业教育工作联席会议制度的执行情况、财政经费拨付情况以及目标考核责任制的落实情况等。具体办法由省人民政府制定。\n职业学校和职业培训机构的行业主管部门对职业教育的办学条件和办学质量负有考核责任。\n职业学校和职业培训机构的办学条件和办学质量达不到国家规定的办学标准的，教育、劳动和社会保障行政部门应当责令其限期整改；仍达不到标准的，应当依法撤销其办学资格。\n第三十三条 教育、劳动和社会保障行政部门应当设立、公布举报电话，受理对职业教育中违法行为的投诉和举报，并及时查处。\n第三十四条 违反本办法规定，法律法规有处罚规定的，由有关部门依法予以处罚。\n对未经批准设立职业学校或者职业培训机构的，由县级以上人民政府教育或者劳动和社会保障行政部门予以取缔；有违法所得的，没收违法所得；造成受教育者损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第三十五条 教育、劳动和社会保障以及其他有关行政主管部门及其工作人员，在职业教育管理活动中玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第三十六条 本办法自2007年12月1日起施行。","level":0}]},{"id":"h0132","sections":[{"name":"","text":"（2008年2月29日长阳土家族自治县第七届人民代表大会第二次会议通过 2008年4月3日湖北省第十一届人民代表大会常务委员会第三次会议批准 根据2022年2月15日长阳土家族自治县第十届人民代表大会第二次会议通过2022年5月26日湖北省第十三届人民代表大会常务委员会第三十一次会议批准的《长阳土家族自治县人民代表大会关于修改、废止部分单行条例的决定》修正）\n第一条 为保证农产品质量安全，保障人民群众身体健康和生命安全，根据《中华人民共和国农产品质量安全法》《中华人民共和国农业法》等法律、法规的规定，结合自治县实际，制定本条例。\n第二条 本条例所称农产品，是指经种植、养殖、采集、捕捞形成的粮食、蔬菜、水果、油料、菌类、茶叶、烟叶、中草药、畜禽和畜禽产品、水产品等来源于农业的初级产品。\n第三条 在自治县行政区域内从事农产品的生产、经营活动以及对农产品质量安全实施监督管理，适用本条例。\n第四条 自治县人民政府统一领导、协调本行政区域内的农产品质量安全工作，并采取措施，建立健全农产品质量安全服务体系，提高农产品质量安全水平。\n自治县人民政府应当将保障农产品质量安全纳入本地方国民经济和社会发展规划，并组织实施。\n第五条 自治县人民政府设立农产品质量安全专项资金用于开展农产品质量安全工作。\n农产品质量安全专项资金按照当年一般预算收入的1％列入财政预算，实行国库集中支付，由农业农村主管部门提出用款计划，经自治县人民政府批准后执行，相关部门应当加强对该项资金使用情况的监督。\n第六条 自治县农业农村主管部门负责自治县行政区域内农产品质量安全的监督管理工作；自治县人民政府有关部门按照职责分工，负责农产品质量安全的有关工作。\n第七条 自治县人民政府及有关部门应当加强农产品质量安全知识的宣传，提高公众的农产品质量安全意识，引导农产品生产者、经营者加强质量安全管理，保障农产品的质量和安全。\n第八条 自治县行政区域内农产品质量安全依据国家农产品质量安全标准执行。\n第九条 自治县农业农村主管部门按照保障农产品质量安全的要求，根据农产品品种特性和生产区域大气、土壤、水体中有毒有害物质状况等因素，认为不适宜特定农产品生产的，提出禁止生产的区域，报自治县人民政府批准后公布。\n第十条 自治县人民政府采取流域综合治理，测土配方施肥，保护水源水质、土壤土质、生态环境，防治农业有害生物等多种措施，加强农产品生产基地建设，改善农产品生产条件。\n第十一条 自治县生态环境、农业农村主管部门对农产品产地的大气条件、土壤状况、水源水质、农业有害生物情况等进行经常性监测，并根据国家和省有关规定发布预警信息。\n在无公害农产品主产区设立工矿企业，具有环境评估资质的机构在进行环境评估时应当征得自治县农业农村主管部门的同意。\n第十二条 禁止违反法律、法规的规定向农产品产地排放或者倾倒废水、废气、固体废物或者其他有毒有害物质。\n农业生产用水和用作肥料的固体废物，应当符合国家规定的标准。\n第十三条 自治县鼓励农产品生产经营企业、农民专业合作经济组织和个人按照国家规定标准建设无公害农产品基地，开发具有地方特色的无公害农产品、绿色食品、有机食品，打造优质品牌，并按照国家有关规定申请无公害农产品产地认定、产品认证和绿色食品、有机食品认证。\n自治县人民政府鼓励农产品生产经营企业、农民专业合作经济组织或者其他符合条件的申请人，依法申请、使用地理标志产品专用标志。\n自治县人民政府对获得国家无公害农产品、绿色食品、有机食品认证和地理标志产品专用标志的单位或者个人给予奖励。\n第十四条 自治县农业农村主管部门应当依据国家保障农产品质量安全的标准和生产技术规范制定自治县农产品生产技术操作规程，并组织实施。\n自治县行政区域内农产品生产经营者必须严格执行农产品的质量安全标准和生产技术操作规程。\n第十五条 自治县农业农村主管部门和有关部门，应当组织农业科研教育机构和农业技术推广机构对农产品生产者进行技术培训和指导。乡（镇）人民政府以及村民委员会应当做好培训的组织工作。\n第十六条 自治县行政区域内农产品生产企业、农民专业合作经济组织应当依法建立农产品生产记录，如实记载下列事项：\n（一）使用农业投入品的名称、来源、用法、用量和使用、停用的日期；\n（二）动物疫病、植物病虫草害的发生和防治情况；\n（三）收获、屠宰或者捕捞的日期。\n农产品生产记录应当按照国家有关规定予以保存。禁止伪造农产品生产记录。\n第十七条 在自治县行政区域内从事农药、农作物种子、肥料、兽药、渔药、饲料和饲料添加剂等农业投入品生产经营的，必须遵守相关法律、法规的规定，取得生产或者经营许可；需登记备案的应当依法登记备案。\n第十八条 自治县农业农村主管部门及时公布国家禁止使用的农业投入品目录。\n自治县行政区域内禁止生产、经营、使用国家禁止使用的农药、兽药、渔药；禁止在高山蔬菜产区经营高毒、高残留农药；禁止在农产品生产中使用高毒、高残留农药。\n自治县行政区域内所有农产品生产应当坚持休药期和安全间隔期制度。\n第十九条 自治县人民政府鼓励农产品生产者采用物理措施和生物措施防治病虫害，鼓励科学使用有机肥、微生物肥料、生物农药和可降解地膜等无污染、无残留的无公害生产资料。\n第二十条 自治县依法实行农产品质量安全标识管理制度。\n第二十一条 农产品在包装、保鲜、贮存、运输过程中所使用的保鲜剂、防腐剂、添加剂等材料，应当符合国家有关强制性的技术规范。\n第二十二条 自治县行政区域内无公害农产品、绿色食品、有机食品生产基地的生产经营者不得以本基地名义，也不得准许他人以本基地名义对外销售非本基地生产的农产品。\n第二十三条 凡列入农业转基因生物标识管理目录的产品，应当按照农业转基因生物标识管理规定，予以正确标识或者标注。\n第二十四条 自治县农业农村主管部门在农产品质量安全监督检查中，履行下列职责：\n（一）对生产、销售的农产品进行现场检查；\n（二）调查了解农产品质量安全的有关情况；\n（三）查阅、复制与农产品质量安全有关的记录和其他资料；\n（四）依法查封、扣押经检测不符合农产品质量安全标准的农产品；\n（五）依法查处违反农产品质量安全法律、法规规定的其他行为。\n第二十五条 自治县农业农村主管部门应当制定农产品质量安全监测计划，依法建立健全监督网络。\n第二十六条 自治县农业农村主管部门应当定期组织具有合法资质的农产品质量安全检测机构对生产和市场上销售的农产品实施监督抽查。监督抽查结果报省农业农村主管部门公布。对不符合国家标准的农产品，自治县农业农村主管部门应当按照农产品质量安全责任追究制度的要求，查明责任人，依法予以处理或者向省农业农村主管部门提出处理建议。\n农产品生产者和销售者应当配合依法进行的监督抽查，拒绝接受的，应当视为质量检测不合格。\n第二十七条 自治县农业农村主管部门可以组织具有合法资质的农产品质量检测机构在主要农产品主产区设立农产品质量安全检测点，对外运农产品进行检测。\n自治县根据动植物防疫需要，依法设立动植物检疫站（点），对农产品实施检疫，严防外来危险性有害生物的侵入和传播。\n生产、调运农产品的公民、法人和其他组织，应当自觉接受农产品质量安全检测和动植物检疫。\n第二十八条 经检测不符合农产品质量安全强制性标准的农产品或者病死、死因不明的水产品、畜禽及其产品，不得销售，并由自治县农业农村主管部门监督生产者、销售者进行无害化处理；不能进行无害化处理的，依法予以销毁。销毁或者进行无害化处理的费用，由当事人承担。\n第二十九条 依法开展农产品质量安全监督抽查检测的机构在抽查检测时，不得向被抽查人收取费用，抽取的样品不得超过国务院农业农村主管部门规定的数量。\n已依法接受监督抽查的农产品，有关主管部门不得另行重复组织抽查。\n第三十条 农产品生产者、销售者对监督抽查检测结果有异议的、可以自收到检测结果之日起五日内，向组织实施农产品质量安全监督抽查的农业农村主管部门或者其上级农业农村主管部门申请复检。\n采用国务院农业农村主管部门会同有关部门认定的快速检测方法进行农产品质量安全监督抽查检测，被抽查人对检测结果有异议的，可以自收到检测结果时起四小时内申请复检。复检不得采用快速检测方法。\n因检测结果错误而给当事人造成损害的，应当依法承担赔偿责任。\n第三十一条 自治县行政区域内的农产品批发市场应当设立或者委托农产品质量安全检测机构，对进场销售的农产品质量安全状况进行抽查检测；发现不符合农产品质量安全标准的，应当要求销售者立即停止销售，并向农业农村主管部门报告。\n农产品经营企业对其销售的农产品，应当建立健全进货检查验收制度；经查验不符合农产品质量安全标准的，不得销售。\n第三十二条 违反本条例规定行为的处罚，国家法律、法规有规定的，从其规定。\n第三十三条 违反本条例第十八条第二款规定，有下列行为之一、构成犯罪的，由司法机关依法追究其刑事责任；尚不构成犯罪的，由自治县农业农村主管部门按照以下规定给予处罚：\n（一）在高山蔬菜产区销售高毒、高残留农药的，没收其经营的高毒、高残留农药，可以并处以1千元以上1万元以下的罚款；\n（二）在粮食、蔬菜、水果、茶叶、中草药等农产品生产中使用高毒、高残留农药的，其农产品禁止出售，并给予警告；造成危害后果的，视情节处以3千元以上3万元以下的罚款。\n第三十四条 获得农产品认证并加贴标志的产品，经检查、监测、鉴定，不符合相关农产品质量标准要求的，由自治县农业农村主管部门或者市场监督管理主管部门责令停止使用该农产品标志，并报请认证机构暂停或者撤销认证证书。\n未经认证或者认证期满未获得重新认证，使用无公害农产品、绿色食品、有机食品名称或标志的，由自治县农业农村主管部门责令限期改正；逾期拒不改正的，处以1千元以上5千元以下的罚款。\n第三十五条 自治县农产品质量安全监督管理人员不依法履行职责，或者滥用职权、玩忽职守、徇私舞弊的，由有关主管部门依法给予处分；构成犯罪的，由司法机关依法追究其刑事责任。\n第三十六条 当事人对行政机关依照本条例规定给予的行政处罚不服的，可以依法申请行政复议，或者直接向人民法院提起行政诉讼。逾期不申请行政复议也不向人民法院提起行政诉讼，又不履行行政处罚决定的，由作出行政处罚决定的行政机关依法申请人民法院强制执行。\n第三十七条 本条例自2008年7月1日起施行。","level":0}]},{"id":"h0133","sections":[{"name":"","text":"（2007年12月6日湖北省第十届人民代表大会常务委员会第三十次会议通过）\n第一条 为了保护和鼓励台湾同胞在本省投资，根据《中华人民共和国台湾同胞投资保护法》和有关法律、行政法规的规定，结合本省实际，制定本办法。\n第二条 台湾同胞以其在台湾地区或者台湾地区以外设立的公司、企业、其他经济组织或者个人名义来本省投资的，适用本办法。\n第三条 台湾同胞的投资、投资收益和其他合法权益受法律保护，任何机关、单位或者个人不得侵占、损害。\n台湾同胞投资应当遵守国家法律、法规，符合国家产业政策和投资导向，有利于本省经济和社会发展。\n第四条 各级人民政府应当鼓励、支持、引导、帮助台湾同胞投资，依法维护其合法权益。\n县级以上人民政府负责管理和指导台湾同胞投资工作；县级以上人民政府台湾事务办事机构负责做好台湾同胞投资的法律宣传与咨询服务，以及协调有关单位和部门做好台湾同胞投资等工作；其他有关国家机关和单位按照各自职责，做好涉及台湾同胞投资的工作。\n第五条 鼓励台湾同胞投资者在本省投资下列项目：\n（一）公共基础设施建设和能源、稀缺原材料开发项目；\n（二）先进制造业项目；\n（三）高新技术项目；\n（四）农产品深加工项目和农业综合开发项目；\n（五）企业技术改造项目；\n（六）资源综合开发利用、再生资源利用以及环境保护项目；\n（七）现代服务业项目；\n（八）国家和省鼓励投资的其他项目。\n第六条 台湾同胞在本省的投资形式和出资方式按照有关法律法规的规定执行。\n第七条 有关行政机关审批、办理台湾同胞投资事项时，应当提高效率，简化程序，做到合法、公正和公平，不得刁难、拖延或者谋取不正当利益。\n第八条 台湾同胞投资企业依法享有生产经营管理的自主权，不受任何机关、单位或者个人的非法干预和侵犯。\n第九条 台湾同胞在本省投资的，享受国家促进中部地区发展的优惠政策。台湾同胞在本省享受西部地区优惠政策的地方投资的，其待遇按照国家对西部地区优惠政策执行。\n第十条 因社会公共利益需要，必须拆迁台湾同胞拥有产权的生产经营建筑物和其他房产时，拆迁单位必须取得有权机关颁发的拆迁许可证，并与产权人签订安置补偿协议，安置方案应当有利于台湾同胞投资企业的生产经营和便利台湾同胞的工作、生活。\n第十一条 鼓励、支持台湾同胞投资企业科技创新和争创国家名牌产品、驰名商标、著名商标。\n依法保护台湾同胞投资企业的知识产权。对仿冒、伪造台湾同胞投资企业产品、商标等侵犯台湾同胞投资企业知识产权的行为，应当及时查处，侵权责任者应当依法承担赔偿责任。\n第十二条 各级人民政府及其有关部门应当为台湾同胞投资企业的产品进入市场提供帮助，不得限制台湾同胞投资企业产品进入本地市场。\n第十三条 涉及台湾同胞投资企业的行政事业性收费必须以法律、法规、规章的规定为依据，收费标准应当与本行政区域内其他同类企业相同。\n除法律、法规明确规定外，台湾同胞投资企业有权拒绝参加各类培训、评比、鉴定、考核、赞助、捐款捐物等活动。\n第十四条 在本省投资或者受聘于本省企业的台湾同胞及其随行眷属，在本省购物、住宿、就医、参观旅游、乘坐交通工具等，享受本省居民同等待遇。\n第十五条 在本省投资或者受聘于本省企业的台湾同胞及其随行眷属，从事经贸活动需要多次入出境的，可以按有关规定向公安机关申请办理一定期限多次有效入出境手续。\n第十六条 台湾同胞在本省居留期间，可以持台湾地区或者其他国家、地区有效机动车驾驶证以及按规定应当提供的证明文件，到公安机关申请换领机动车驾驶证或者临时驾驶证。\n第十七条 台湾同胞持台湾地区或者其他国家、地区卫生检验检疫机关的有效健康证明，经本省出入境卫生检验检疫机关验证后，依据有关法律、法规的规定可免作相关项目的健康检查。\n第十八条 在本省投资或者受聘于本省企业的台湾同胞，其子女就读中、小学的，当地教育行政主管部门应当为其提供方便，相关费用与本地居民相同。\n台湾同胞投资企业集中的地区，可以依法申请设立台湾同胞子女学校。台湾同胞子女学校应当接受所在地教育行政主管部门的指导和监督。\n第十九条 台湾同胞投资者可以获得各级人民政府和有关团体颁发的荣誉证书和授予的荣誉称号。\n第二十条 在本省投资的台湾同胞及其眷属可以根据有关规定申请在我省定居。定居后，仍可以享受台湾同胞投资者待遇。\n对符合条件的台湾同胞投资企业，可以准予台湾同胞投资者一定数量的亲属在台湾同胞投资企业所在城市落户。\n第二十一条 台湾同胞投资企业集中的地区，可以依法成立台湾同胞投资企业协会。\n台湾同胞投资企业协会依照法律、法规、规章和协会章程活动，其合法权益受法律保护。\n第二十二条 县级以上人民政府行政主管部门处理涉及台湾同胞或者台湾同胞投资企业的重大事项，应当告知本级人民政府台湾事务办事机构。\n第二十三条 台湾同胞投资者的合法权益受到侵害或者发生民事纠纷时，可以通过下列途径解决：\n（一）协商或者调解解决；\n（二）向台湾事务办事机构或者有关主管部门投诉；\n（三）申请行政复议；\n（四）提交仲裁机构裁决；\n（五）向人民法院提起诉讼。\n第二十四条 台湾事务办事机构设立的台商投诉协调专门机构，负责受理、协调本行政区域内台湾同胞及其投资企业的投诉事项。\n第二十五条 台湾事务办事机构收到投诉后，应当予以登记，并按下列方式处理：\n（一）对已经或者依法应当通过诉讼、仲裁、行政复议等法定途径解决的，应当告知投诉人依照有关法律、行政法规规定程序向有关机关提出；\n（二）对属于其他机关或者部门职责范围处理的投诉事项，应当及时转送相关机关或者部门；\n（三）对重大投诉事项或者投诉事项需要由几个部门共同处理的，可以提请同级人民政府处理或者上一级台湾事务办事机构处理。\n第二十六条 台湾事务办事机构转交有关机关或者部门处理的投诉事项，承办单位应当在三十日内办结，并将办理结果告知投诉人和台湾事务办事机构。\n第二十七条 涉及对台湾同胞依法作出限制人身自由的强制措施决定的，作出决定的机关应当在法定期限内通知该台湾同胞在内地的家属，并及时告知该台湾同胞工作单位所在地的县级以上台湾事务办事机构。\n第二十八条 国家机关及其工作人员违反本办法滥用职权，徇私舞弊，侵害台湾同胞投资者合法权益的，依法对其主要负责人和直接责任人给予行政处分；构成犯罪的，依法追究刑事责任。\n台湾同胞投资者的合法权益因国家机关及其工作人员违法行使职权受到损害的，可以依法申请国家赔偿。\n第二十九条 本办法自2008年2月1日起施行。","level":0}]},{"id":"h0134","sections":[{"name":"","text":"（2007年12月6日湖北省第十届人民代表大会常务委员会第三十次会议通过 根据2025年1月13日湖北省第十四届人民代表大会常务委员会第十五次会议《关于集中修改、废止部分省本级地方性法规的决定》修正）\n第一条 为了促进农民专业合作社发展，规范农民专业合作社组织及其行为，维护农民专业合作社及其成员的合法权益，根据《中华人民共和国农民专业合作社法》及有关法律法规，结合本省实际，制定本办法。\n第二条 农民专业合作社是指在农村家庭承包经营基础上，农产品的生产经营者或者农业生产经营服务的提供者、利用者，自愿联合、民主管理的互助性经济组织。\n第三条 农民专业合作社应当以农民为主体，以服务成员为宗旨，以市场为导向，坚持入社自愿、退社自由，全体成员地位平等，利益共享，风险共担。\n鼓励企业和其他经济组织以及个人依法参办、领办农民专业合作社。\n农民专业合作社应当依法登记，按照章程规范内部管理，开展农业生产经营和服务活动。\n第四条 县级以上人民政府应当将农民专业合作社发展纳入国民经济和社会发展规划，结合新农村建设、探索集体经济实现形式以及支持农业产业化经营和龙头企业发展，制定指导、扶持农民专业合作社发展的具体政策措施，建立和完善农民专业合作社信息交流平台，加强服务机构和队伍建设，并通过各种方式引导农民专业合作社发展适度规模经营，壮大农民专业合作社经济实力。\n乡镇人民政府以及村民委员会应当为农民专业合作社的设立、发展以及生产经营活动提供相应的便利和服务，并依法协助调解和处理生产经营中的矛盾纠纷。\n第五条 省人民政府农业农村主管部门以及市、州、县级农业农村（经管）部门主管本行政区域内农民专业合作社的指导、扶持、服务工作，重点做好试点培育、政策咨询、业务指导、项目扶持、统计备案等相关工作，其工作经费列入财政预算。\n县级以上人民政府有关部门以及其他有关组织，应当按照各自职责做好对农民专业合作社的指导、扶持、服务工作。\n第六条 农业农村（经管）部门及其他相关部门对创办农民专业合作社的，应当提供下列指导帮助：\n（一）开展农民专业合作社相关法律法规的宣传教育；\n（二）组织创办人员进行免费的专业知识和技术培训；\n（三）指导拟定农民专业合作社章程及相关的管理制度；\n（四）为农民专业合作社申请登记提供便捷服务。\n省人民政府农业农村主管部门应当每年拟定有关农民专业合作社工作的培训计划，并组织实施。\n第七条 农民专业合作社应当向市场监督管理部门提交相应资料，申请设立登记。登记机关应当自受理登记申请之日起二十日内办理完毕，向符合登记条件的申请者颁发营业执照，登记类型为农民专业合作社。\n登记机关应当将农民专业合作社的登记信息与同级农业农村（经管）部门共享。\n第八条 财政部门应当统筹各类资金，用于农民专业合作社开展信息交流、培训、农产品质量标准与认证、农业生产基础设施建设、市场营销和技术推广等活动；对革命老区、民族地区、脱贫地区以及保障粮食和重要农产品稳定安全供给的农民专业合作社给予优先扶持。\n第九条 各级政策性和商业性金融机构应当按照国家有关规定，拟定具体措施，采取多种形式，为农民专业合作社提供资金支持和金融服务。县级以上人民政府及其相关部门应当加强与金融机构的协调沟通，为农民专业合作社融资提供有效服务。\n各级信用担保机构，应当将农民专业合作社纳入贷款担保范围，为符合条件的农民专业合作社申请信用贷款提供担保服务。\n第十条 农民专业合作社可以作为农业建设项目的实施单位，独立申报、承担各类农业建设项目。各级人民政府投入的农业综合开发、扶贫开发、农业产业化等建设项目，应当予以公布，并优先安排和委托符合条件的农民专业合作社实施。\n第十一条 农民专业合作社享受国家规定的对农业生产、加工、流通、服务等相应的税收优惠政策。支持农民专业合作社发展的其他税收优惠政策，按照国家有关规定执行。\n第十二条 农民专业合作社的农产品生产基地、种植养殖场、农机示范推广和设施农业用地，符合土地利用总体规划的，按农业用地管理，作为农业生产结构调整用地，不需办农用地转用审批手续。\n农民专业合作社兴办加工企业所需的非农建设用地，自然资源部门应当优先安排用地计划，及时办理用地手续。\n第十三条 农民专业合作社从事种植养殖业，其种植、养殖环节用电执行农业生产电价。\n第十四条 鼓励农民专业合作社开发、申请认证绿色食品、有机食品、原产地地理标志和注册名优农产品商标。对获得绿色食品、有机食品、原产地地理标志证书和名优农产品商标的农民专业合作社给予奖励。具体办法由省人民政府制定。\n第十五条 农民专业合作社应当依法保障全体成员的合法权益，全体成员应当依法履行法律及章程规定的义务。\n农民专业合作社应当建立健全财务管理制度，完善利益分配机制，实行社务公开，加强民主监督。\n农民专业合作社理事长及其他管理人员依照法律及章程的规定履行生产经营和管理职权，任何单位和个人不得非法干预。\n农民专业合作社破产依照法律的有关规定办理。\n第十六条 农民专业合作社应当及时向成员提供生产经营服务，依照农产品质量安全法律法规，建立健全农产品生产记录、检测以及包装或者附加标识等质量安全管理制度。\n第十七条 任何单位和组织不得强迫农民建立、加入或者退出农民专业合作社，不得干预农民专业合作社的自主经营权和内部事务，不得强迫农民专业合作社及其成员接受有偿服务。\n任何单位和个人不得侵犯农民专业合作社的合法财产，不得违法向农民专业合作社及其成员集资、收费、罚款和摊派。\n第十八条 违反本办法第十五条第三款、第十七条第一款规定的，由农业农村（经管）部门责令改正；情节严重的，由有关主管机关追究责任单位主要负责人和直接责任人的责任；造成农民专业合作社及其成员经济损失的，承担相应的民事责任；构成犯罪的，由司法机关依法追究刑事责任。\n违反本办法第十七条第二款规定的，依照《湖北省农民负担监督管理条例》的有关规定予以处罚。\n第十九条 本办法自2008年2月1日起施行。","level":0}]},{"id":"h0135","sections":[{"name":"","text":"（2008年5月29日湖北省第十一届人民代表大会常务委员会第四次会议通过 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》修正）","level":0},{"name":"第三章 审查和批准决算，听取和审议国民经济和社会发展","text":"计划、预算的执行情况报告，听取和审议审计工作\n报告","level":1},{"name":"第四章 法律法规实施情况的检查","text":"","level":1},{"name":"第五章 规范性文件的备案审查","text":"","level":1},{"name":"第六章 询问和质询","text":"","level":1},{"name":"第七章 特定问题调查","text":"","level":1},{"name":"第八章 撤职案的审议和决定","text":"","level":1},{"name":"第九章 其他规定","text":"","level":1},{"name":"第十章 附则","text":"","level":1},{"name":"第一章 总则","text":"第一条 为了保障本省各级人民代表大会常务委员会（以下简称常务委员会）依法行使监督职权，根据《中华人民共和国各级人民代表大会常务委员会监督法》（以下简称监督法）和有关法律的规定，结合本省实际，制定本办法。\n第二条 常务委员会应当围绕国家工作大局，对关系改革发展稳定和人民群众切身利益、社会普遍关注的重大问题，开展监督工作，促进依法行政、公正司法。\n常务委员会依法实施的监督具有法律效力，被监督的机关及其工作人员应当接受监督。\n第三条 常务委员会按照民主集中制的原则，集体行使监督职权。\n常务委员会组成人员应当保持同人民代表大会代表和人民群众的联系，深入开展调查研究，依法履行职责。\n常务委员会与本级人民政府、人民法院和人民检察院应当建立工作联系制度，保证监督工作有效开展。\n第四条 常务委员会应当向本级人民代表大会报告监督工作情况，接受人民代表大会的监督，并根据人民代表大会的决议、决定，加强和改进监督工作。\n常务委员会应当向社会公开行使监督职权的情况，接受人民群众的监督。\n第五条 常务委员会主任会议（以下简称主任会议）依法处理常务委员会行使监督职权的重要日常工作。\n人民代表大会闭会期间，人民代表大会各专门委员会（以下简称专门委员会）在本级常务委员会领导下，协助常务委员会开展监督工作。\n常务委员会工作机构、办事机构根据常务委员会或者主任会议的决定，承办监督工作的具体事项。","level":1},{"name":"第二章 听取和审议人民政府、人民法院和人民检察院的专项工作报告","text":"第六条 常务委员会听取和审议专项工作报告的年度计划，由各专门委员会和常务委员会工作机构、办事机构，按照监督法第九条的规定收集整理，提出建议议题，交由常务委员会指定的工作机构汇总提出计划方案，并在征求常务委员会组成人员及相关方面意见后，于每年第一季度由主任会议通过。\n听取和审议专项工作报告的年度计划需要作个别调整的，由主任会议决定。\n人民政府、人民法院和人民检察院向常务委员会要求报告专项工作的，应当以书面形式提出并说明理由。\n第七条 常务委员会听取和审议专项工作报告前开展视察或者专题调查研究时，可以邀请当地人民代表大会代表以及相关专家参加。受邀人员可以列席或者旁听常务委员会会议，并对专项工作报告提出意见。\n常务委员会开展视察或者专题调查研究，应当通过适当方式，听取公民、法人和其他组织的意见。\n第八条 在常务委员会听取和审议专项工作报告四十日前，有关专门委员会或者常务委员会工作机构、办事机构将有关国家机关、组织以及人民群众等各方面对该项工作的意见进行汇总，以书面形式交由报告机关研究，报告机关应当在报告中对上述意见作出回应。\n有关专门委员会或者常务委员会工作机构对人民政府、人民法院和人民检察院送交征求意见的专项工作报告，应当在五日内提出修改意见，经常务委员会有关负责人审定后，以书面形式反馈给报告机关。报告机关应当根据修改意见对专项工作报告予以修改；确系不宜修改的，应当说明理由。\n第九条 专项工作报告不能按照监督法以及本办法的有关规定如期送交的，报告机关应当说明原因，由主任会议决定不列入当次常务委员会会议议程草案，并根据情况建议列入以后的常务委员会会议议程。\n第十条 专项工作报告的主要内容涉及重大、综合事项的，由人民政府负责人向常务委员会会议作报告；涉及其他事项的，可以由人民政府委托有关部门负责人向常务委员会会议作报告。\n人民法院、人民检察院的专项工作报告，由院长、检察长向常务委员会会议作报告；院长、检察长因故不能作报告的，可以委托副院长、副检察长向常务委员会会议作报告。\n提请常务委员会听取和审议的专项工作报告，必要时，应当附有相关的参阅资料或者典型材料。\n第十一条 常务委员会听取和审议专项工作报告，可以组织常务委员会组成人员、人大代表对报告机关的专项工作进行工作评议。\n第十二条 常务委员会组成人员对专项工作报告的审议意见，由有关专门委员会或者常务委员会工作机构、办事机构汇总整理，经主任会议决定，交报告机关研究处理。报告机关应当在六个月内向常务委员会提出处理情况的报告，并由有关专门委员会或者常务委员会工作机构对该报告提出意见。\n审议意见处理情况的报告以及有关专门委员会或者常务委员会工作机构对该报告提出的意见，一并由主任会议决定印发常务委员会会议审议。\n第十三条 主任会议根据常务委员会组成人员多数人的意见，对专项工作报告审议意见处理情况的报告，可以决定按下列方式处理：\n（一）提请常务委员会对专项工作报告作出决议，交由报告机关执行，并在决议规定期限内报告执行情况；\n（二）交由报告机关进一步研究后，就有关事项提出处理的补充报告；\n（三）退由报告机关重新向常务委员会提出处理情况的报告。\n补充报告、重新报告，应当在六十日内提出。","level":1},{"name":"第三章 审查和批准决算，听取和审议国民经济","text":"和社会发展计划、预算的执行情况报告，听取和审议\n审计工作报告\n第十四条 省人民政府一般在每年七月前，市、州和县级人民政府一般在每年九月前，提请本级常务委员会审议下列事项：\n（一）审查和批准上一年度的本级决算草案；\n（二）报告本年度上半年国民经济和社会发展计划（以下简称计划）、预算的执行情况。\n人民政府应当按照监督法第十八条以及本办法的规定提交决算草案和计划、预算执行情况的报告。\n常务委员会审查和批准决算的同时，听取和审议本级人民政府提出的审计机关关于上一年度预算执行和其他财政收支的审计工作报告。\n第十五条 计划、预算经本级人民代表大会批准后，应当严格执行。在执行过程中出现变更的，人民政府应当向常务委员会报告。有下列情形之一的，人民政府应当编制调整方案，并列明调整的原因、项目、指标或者数额等，于当年的十一月底以前提请常务委员会审查和批准：\n（一）计划中对国民经济和社会发展、国计民生有重要影响的指标以及约束性指标变动较大，需要调整的；\n（二）预算安排的农业、教育、科技、文化、卫生、社会保障等重点资金需要调减的；\n（三）省人民政府预计省级预算收入（支出）总额超过原批准的预算收入（支出）总额百分之三；市、州和县级人民政府预计本级预算收入（支出）总额超过原批准的预算收入（支出）总额一定比例的，具体比例由本级常务委员会决定。\n第十六条 预算执行中，动用当年超收收入追加支出，应当编制超收收入使用方案，由人民政府财政部门及时向财政经济委员会或者常务委员会有关工作机构通报情况。年终时，人民政府应当就预算超收收入的使用情况向本级常务委员会提出报告。\n第十七条 常务委员会依照监督法第十八条规定对决算草案和预算执行情况报告进行审查的同时，还应当审查下列内容：\n（一）执行先有预算、后有支出的情况，有无办理无预算拨款、超预算拨款、擅自改变支出用途等问题；\n（二）预算安排的重点建设项目资金的拨付和使用情况；\n（三）政府采购、国库集中收付以及行政事业性收费、罚没收入等政府非税收入管理制度的建立和执行情况。\n常务委员会认为必要时，可以听取人民政府有关上级财政转移支付资金使用情况、政府债务情况的专项报告。\n审计工作报告应当将常务委员会对决算草案和预算执行情况的审查内容作为主要事项列出；常务委员会可以要求同级人民政府对重大问题提出专项审计报告。\n第十八条 决算草案经本级常务委员会审查和批准后，人民政府财政部门应当自批准之日起二十日内向本级各部门批复决算、向下级人民政府财政部门下达资金结算。\n决算草案未能获得常务委员会批准的，人民政府应当根据常务委员会的审议意见依法重新编制决算草案，并在六十日内提请本级常务委员会审查和批准。\n第十九条 常务委员会对计划执行情况的报告，重点审查下列内容：\n（一）国民经济和社会发展主要计划目标实现情况；\n（二）对本行政区域经济社会发展有重大影响的事项、重大建设项目（含政府投资的重点项目）以及本级预算内固定资产投资计划的执行情况；\n（三）本级人民代表大会关于批准计划的决议的执行情况。\n第二十条 财政经济委员会或者常务委员会有关工作机构应当听取人民政府有关部门关于国民经济运行情况的汇报，对国民经济和社会发展情况开展视察、调查，研究分析经济形势。人民政府有关部门应当根据要求，提供经济运行情况的信息材料和相关说明。\n经济运行出现重大变化时，人民政府应当及时向常务委员会报告。\n第二十一条 国民经济和社会发展五年规划经人民代表大会批准后的第三年第四季度，人民政府应当将规划实施情况的中期评估报告提请本级常务委员会审议。报告对规划中的约束性指标的实施情况，应当逐项评估。规划经中期评估需要调整的，人民政府应当将调整方案提请本级常务委员会审查和批准。\n第二十二条 人民政府有关部门一般应当在常务委员会举行会议的三十日前，将计划、预算执行情况报告以及决算草案和预算、计划、规划调整方案，送交财政经济委员会初步审查或者送交常务委员会有关工作机构征求意见，由财政经济委员会或者常务委员会有关工作机构提出审查报告或者意见。\n提交决算草案和预算调整方案的主要内容包括：列到类、款的收支决算和预算调整资料，补助下级财政支出和接受上级财政资金及调整情况，主要预算单位部门决算、部门预算调整资料等。\n提交计划调整方案的主要内容包括：计划调整的原因、幅度、依据及其说明、论证材料，调整后计划执行效果的预期评估等。\n财政经济委员会或者常务委员会有关工作机构应当围绕相关审查工作组织开展调查研究，可以委托有关专业机构和人员协助初审或者提出审计意见。\n第二十三条 人民政府或者受其委托的审计机关应当在每年年底前，向本级常务委员会报告上一年度本级预算执行和其他财政收支审计有关问题的整改情况。\n常务委员会认为必要时，可以对审计工作报告作出决议，人民政府应当在决议规定的期限内，将执行决议的情况向常务委员会作出书面报告；对审计工作报告中反映的重点问题及其整改情况，可以交由财政经济委员会或者常务委员会有关工作机构开展跟踪监督。\n第二十四条 常务委员会组成人员对计划、预算执行情况报告和审计工作报告的审议意见的形成、反馈、处理等参照本办法第十二条、第十三条的有关规定执行。","level":1},{"name":"第四章 法律法规实施情况的检查","text":"第二十五条 常务委员会执法检查年度计划的拟订，参照本办法第六条的有关规定执行。\n常务委员会执法检查年度计划的实施，由有关专门委员会或者常务委员会工作机构、办事机构在调查研究后，拟订执法检查方案，提交主任会议通过。\n第二十六条 常务委员会执法检查组成员，从常务委员会组成人员、有关专门委员会组成人员中确定，并可以邀请本级以及被检查地方的人民代表大会代表和有关专业人员参加。执法检查组成员名单，由有关专门委员会和常务委员会工作机构提出建议，主任会议决定。\n全国人民代表大会常务委员会和省人民代表大会常务委员会委托下一级人民代表大会常务委员会进行执法检查时，受委托的常务委员会应当分别邀请当地的全国人民代表大会代表或者省人民代表大会代表参加。\n第二十七条 法律、法规实施主管机关根据常务委员会的执法检查安排，可以在本系统内先行组织自查，并在常务委员会开展执法检查时，如实汇报情况，提供资料。\n第二十八条 执法检查可以采取听取汇报、召开座谈会、走访、抽样调查、实地考察、问卷调查、设立专线电话以及查阅有关材料等方法进行。\n第二十九条 执法检查结束后十五日内，执法检查组应当按照监督法第二十六条规定的内容提出执法检查报告，由主任会议决定提请常务委员会会议审议。\n根据常务委员会听取和审议专项工作报告年度计划、执法检查年度计划的安排，执法检查报告内容与专项工作报告内容有关联的，应当将两个报告列入常务委员会同一次会议议题，先由有关机关报告专项工作情况，执法检查组再报告检查情况，常务委员会会议一并进行审议。\n第三十条 常务委员会根据下列情况可以依法组织执法情况跟踪检查：\n（一）法律、法规实施主管机关整改工作措施不力，常务委员会组成人员多数人不满意的；\n（二）法律、法规实施主管机关已经采取整改措施，但有必要对整改目标的实现情况进行跟踪检查的；\n（三）执法检查中发现的重大问题以及其他情况需要进行跟踪检查的。\n跟踪检查，由执法检查组或者常务委员会委托的有关专门委员会、常务委员会工作机构实施，并向常务委员会提出报告。\n第三十一条 常务委员会组成人员对执法检查报告的审议意见的形成、反馈、处理等参照本办法第十二条、第十三条的有关规定执行。执法检查报告应当一并交由法律、法规实施主管机关研究处理。\n执法检查中发现的涉嫌违法问题，统一转交有关机关依法处理。对重大涉嫌违法问题或者执法中存在的普遍性、倾向性问题，有关专门委员会或者常务委员会工作机构可以听取有关机关的汇报，必要时，由主任会议听取汇报并责成有关机关依法处理，报告处理结果。","level":1},{"name":"第五章 规范性文件的备案审查","text":"第三十二条 本办法所称规范性文件，是指由人民代表大会及其常务委员会作出或者人民政府发布的，涉及公民、法人和其他组织的权利义务关系，在本行政区域内具有普遍约束力的下列文件：\n（一）各级人民代表大会及其常务委员会作出的决议、决定；\n（二）省人民政府和设区的市、自治州人民政府制定的规章；\n（三）各级人民政府发布的决定、命令、规定、办法、细则等；\n（四）有解释权的机关对地方性法规、自治条例、单行条例和规章所作的解释。\n前款所列规范性文件自公布之日起三十日内，由制定机关按照下列规定报送备案：第（一）项报上一级常务委员会备案，第（二）项中的省规章和第（三）项报本级常务委员会备案，第（二）项中的设区的市、自治州规章报本级和上一级常务委员会备案，第（四）项报省人民代表大会常务委员会备案。\n报送规范性文件备案，应当提交专题备案报告、规范性文件文本及其相关说明材料。\n第三十三条 对报送备案的规范性文件，由常务委员会有关办事机构负责统一登记、建档，并分送有关专门委员会或者常务委员会工作机构。\n有关专门委员会或者常务委员会工作机构审查发现备案的规范性文件有立法法第九十六条、监督法第三十条所列情形的，可以通知有关制定机关说明情况，并根据情况，由负责审查的机构报常务委员会有关负责人同意后，向制定机关提出书面审查意见。\n第三十四条 规范性文件的制定机关自收到书面审查意见后三十日内，应当向有关专门委员会或者常务委员会工作机构反馈是否修改的意见并说明理由。有关专门委员会或者常务委员会工作机构研究后，认为制定机关不予修改的意见不当的，应当向主任会议提出处理意见或者依法提出建议撤销该规范性文件的议案，由主任会议决定提请常务委员会会议审议。\n第三十五条 常务委员会或者人民政府、人民法院、人民检察院，认为有关规范性文件不适当的，可以向有权审查的上一级或者本级常务委员会书面提出审查要求；其他国家机关和社会团体、企业事业组织以及公民，认为有关规范性文件不适当的，可以向有权审查的常务委员会书面提出审查建议。\n有关专门委员会或者常务委员会工作机构根据情况，以适当的方式将审查情况告知提出审查要求或者审查建议的单位或者个人。\n第三十六条 常务委员会发现本级人民政府所属工作部门制定的文件有不适当情形的，可以交由本级人民政府研究处理；发现本行政区域其他国家机关或者不属于本级人民政府直接管理的国家行政机关以及具有社会管理职能的其他组织的文件有不适当情形的，可以向有关机关提出或者通过上一级常务委员会向其上一级主管部门提出。","level":1},{"name":"第六章 询问和质询","text":"第三十七条 常务委员会会议审议有关议案和报告时，人民政府及其有关部门、人民法院和人民检察院，应当派负责人到会，听取意见，回答询问；常务委员会分组审议时，有关机关应当派员到各组听取意见。\n第三十八条 常务委员会组成人员向人民政府及其有关部门、人民法院和人民检察院提出询问的，可以由个人提出，也可以由两人以上联合提出；可以口头提出，也可以书面提出。\n人民政府及其有关部门、人民法院和人民检察院的负责人，应当当场答复询问；不能当场答复的，应当说明原因，并经询问人同意后，在确定的时间内答复。\n第三十九条 常务委员会组成人员按照监督法的有关规定提出质询案的，质询案的内容应当属于受质询机关的职责范围内的事项。\n质询案由常务委员会指定的工作机构负责接收，提交主任会议按照监督法有关规定决定交由受质询机关答复，并确定答复方式和时间。主任会议决定质询案口头答复的，由受质询机关的负责人到会答复。\n第四十条 提出质询案的常务委员会组成人员的过半数对答复不满意的，可以提出要求，经主任会议决定，由受质询机关再作答复。再作答复的，由受质询机关的负责人到会答复。\n第四十一条 常务委员会组成人员提出询问、质询案，要求有关机关提供相关材料的，除涉及保密事项以外，有关机关应当如实提供。","level":1},{"name":"第七章 特定问题调查","text":"第四十二条 特定问题调查，按照监督法的有关规定提议、决定。\n常务委员会会议在审议关于组织特定问题调查委员会的提议后，由主任会议提出关于组织特定问题调查委员会的决定草案以及调查委员会组成人员名单草案，提请常务委员会会议审议通过。\n调查委员会由主任委员、副主任委员和委员共五至九人组成；由主任会议在本级常务委员会组成人员、人民代表大会代表中提名，提请常务委员会审议通过后予以公布。\n第四十三条 特定问题调查委员会有权要求有关单位负责人汇报情况，调阅有关的案卷和材料，询问有关人员，组织听证、论证、专项审计和必要的鉴定。\n调查委员会对调查中涉及的国家秘密、商业秘密和个人隐私，应当依法保密。\n第四十四条 特定问题调查一般应当在调查委员会成立之日起九十日内完成，涉及重大复杂问题的，经主任会议决定，可以延长六十日。\n特定问题调查委员会应当集体讨论问题，并及时向常务委员会提出调查报告。调查报告的内容应当包括调查过程、调查结论及其依据和处理建议等。调查委员会成员对调查结论和处理建议有不同意见的，可以在调查报告中写明。调查委员会成员应当在调查报告上署名。","level":1},{"name":"第八章 撤职案的审议和决定","text":"第四十五条 人民政府、人民法院和人民检察院向本级常务委员会依法提出的撤职案，应当分别由人民政府主要负责人、人民法院院长、人民检察院检察长签署提出。\n主任会议依法提出的撤职案，由主任会议全体成员的过半数通过。\n五分之一以上常务委员会组成人员依法书面联名提出的撤职案，应当注明撤职案的联名领衔人。\n撤职案应当写明撤职的对象和理由，并提供有关材料。\n第四十六条 人民政府、人民法院和人民检察院提出撤职案的，由其负责人在常务委员会会议上作关于撤职案的说明。\n主任会议提出撤职案的，由主任会议委托的人员在常务委员会会议上作关于撤职案的说明。\n常务委员会组成人员联名提出撤职案的，由领衔人在常务委员会会议上作关于撤职案的说明。\n第四十七条 常务委员会会议审议撤职案时，有关机关的负责人应当到会听取审议情况，回答询问；必要时，应当提供相应材料。\n第四十八条 常务委员会审议撤职案，认为需要就有关问题作进一步调查的，有关机关应当及时调查核实并提出调查报告，由主任会议决定提请以后的常务委员会会议根据调查情况作出决定。\n撤职案在提请表决前，被提出撤职的人员有权在常务委员会会议上提出申辩意见，或者书面提出申辩意见，由主任会议决定印发常务委员会会议。\n撤职案的表决采用无记名投票的方式，由常务委员会全体组成人员的过半数通过。","level":1},{"name":"第九章 其他规定","text":"第四十九条 常务委员会可以通过听取和审议专项工作报告、组织执法检查等形式，依法实施对本行政区域内不属于本级人民政府直接管理的国家行政机关以及具有社会管理职能的其他组织和企业事业单位，遵守和执行法律、法规情况的监督。\n第五十条 人民群众通过来信来访，向常务委员会提出的建议、批评和意见以及申诉、控告和检举，按照《湖北省信访条例》的有关规定办理。\n对人民群众的来信来访反映的情况和问题，常务委员会有关工作机构或者办事机构应当定期归纳整理、综合分析，每季度、半年提出分析报告，并就常务委员会听取和审议专项工作报告、组织执法检查等提出相关建议。常务委员会可以听取对人民群众来信来访处理情况的专项工作报告。\n第五十一条 在常务委员会会议结束后十五日内，由常务委员会有关工作机构、办事机构向本级人民代表大会代表通报，并向社会公布下列内容：\n（一）常务委员会作出的决议、决定；\n（二）常务委员会听取和审议专项工作报告的年度计划、执法检查的年度计划；\n（三）常务委员会听取和审议的专项工作报告、计划执行情况报告、预算执行情况报告、审计工作报告、执法检查报告；\n（四）常务委员会组成人员对有关报告的审议意见以及工作评议情况；\n（五）对常务委员会决议、决定执行情况的报告；\n（六）对常务委员会组成人员审议意见处理情况的报告。\n第五十二条 常务委员会通过下列方式向本级人民代表大会代表通报有关行使监督职权的情况：\n（一）本级常务委员会公报；\n（二）专门信函或者电子邮件；\n（三）召开通报会；\n（四）委托下一级常务委员会通报；\n（五）其他适当方式。\n常务委员会举行会议时，可以邀请上一级和本级人民代表大会代表、下一级常务委员会负责人列席，参与讨论，提出意见。\n第五十三条 常务委员会通过下列渠道向社会公布有关行使监督职权的情况：\n（一）当地新闻媒体；\n（二）常务委员会及其他相关国家机关的网站；\n（三）常务委员会公报或者其他发行的刊物；\n（四）召开新闻发布会；\n（五）其他适当渠道。\n常务委员会举行会议时，可以邀请公民旁听。\n第五十四条 对违反监督法和本办法规定，不依法向常务委员会报告工作、不依法研究处理常务委员会提出的审议意见的，或者不认真执行常务委员会有关决议、决定的，或者不按照规定报送规范性文件的，主任会议根据常务委员会组成人员多数人的意见，可以责成有关机关负责人向常务委员会会议作出说明；情节严重的，可以责成有关机关作出书面检查，或者提请常务委员会依照其他法定监督方式实施监督。","level":1},{"name":"第十章 附则","text":"第五十五条 本办法自2008年9月1日起施行。","level":1}]},{"id":"h0136","sections":[{"name":"","text":"（2008年9月26日湖北省第十一届人民代表大会常务委员会第六次会议通过）\n第一条 为了加强血吸虫病防治（以下简称血防）工作，保障人体健康、动物健康和公共卫生，促进经济社会发展，根据国家有关法律、行政法规的规定，结合我省实际，制定本条例。\n第二条 血防工作实行预防为主、防治结合的方针，坚持综合治理、整体推进和人畜同步防治的原则，以控制传染源为重点，实行政府领导、部门负责、社会参与的工作机制。\n第三条 省人民政府和血防地区各级人民政府应当加强领导，研究制定本行政区域血防工作的方针政策，将血防工作纳入本地区经济和社会发展总体规划并组织实施，制定血防规划，部署防治工作任务，完善协调领导机制，解决血防工作中的重大问题，监督、考核本行政区域内的血防工作。\n血防工作实行政府目标管理和责任追究制。\n第四条 血防地区县级以上人民政府卫生（含血防，下同）主管部门负责本行政区域血防综合监督管理和指导工作，履行下列职责：\n（一）拟订本地区血防工作的具体政策、措施和防治规划；\n（二）组织协调各有关部门开展对血吸虫病的综合防治工作；\n（三）督促指导本地区血吸虫病的综合治理和科学防治工作；\n（四）监督检查本地区血吸虫病的预防、治疗、监测、控制和疫情管理；\n（五）组织查螺和高危易感地带药物灭螺工作；\n（六）指导血防技术，普及和宣传血防知识；\n（七）其他血防综合监督管理工作。\n农业（含畜牧兽医、农机、能源、水产，下同）、水利、国土资源、林业、交通、发展改革、财政、民政等其他主管部门共同配合，负责职责范围内的血防工作，并实施监督管理。\n凡与血防工作有关的机关、团体、企业事业单位，应当按有关规定将承担的血防工作任务列入工作计划，密切配合，共同做好血防工作。\n血防地区的中央、省属单位以及驻鄂部队，应当根据属地管理原则，按照所在地县级以上人民政府血防工作总体规划的要求，服从血防工作的统一安排和部署，同步开展防治工作。\n第五条 血防地区按规定设立的负责血吸虫病预防控制的机构（以下简称血吸虫病预防控制机构），承担辖区血防业务技术工作。\n血防地区县级以上人民政府应当加强县（市）、乡（镇）、村血防网络和队伍建设，血防重点地区县级人民政府应当确保乡镇有必需的血防预防人员从事血防工作。\n第六条 血防地区的村（居）民委员会应当依法组织村（居）民积极参加当地人民政府开展的血防活动，落实综合防控措施。\n鼓励社会各界关心、支持、参与血防活动和捐赠资助血防工作；鼓励和支持各类社会团体和志愿者积极参与血防工作。\n第七条 血防地区各级人民政府应当组织开展血防宣传教育，增强公众的血防意识。\n报刊、广播、电视、网站等各类新闻媒体应当开展公益性血防宣传教育。血防重点地区的新闻媒体应当在血吸虫病易感季节、学校暑假期间和较大洪涝灾害时，集中开展公益性血防宣传教育。\n血防地区教育主管部门应当将血防健康教育工作纳入中小学校目标责任考核体系，并进行督促和检查；中小学校应当将血防知识纳入学校教育内容，配合血防专业机构开展师生血吸虫病查治工作。\n各机关、团体、企业事业单位、其他经济组织以及村（居）民委员会应当组织本单位、本辖区内人员和村（居）民学习、普及血防知识，增强科学防护意识。\n第八条 省人民政府和血防地区各级人民政府应当组织有关部门采取以控制血吸虫病传染源，阻断血吸虫病传播途径为重点的综合防治措施，加强联防联控，做好血吸虫病的预防控制工作。\n省人民政府根据国家有关血吸虫病预防控制标准，将血防地区划分为重点防治地区和一般防治地区，实行分类防治。在重点防治地区的血防工作和项目建设上，应当整合资源、综合防治，实施区（流）域治理，整体推进。在一般防治地区应当做好疫情巩固和监测工作，进一步控制和阻断血吸虫病传播。\n省人民政府有关主管部门制订血防技术规范，指导血防地区和有关部门血防项目的实施。\n第九条 省人民政府和血防地区各级人民政府及其发展改革、财政、农业、卫生等主管部门，应当优先安排和实施农村建沼气池、改厕、改厨、改圈和建无害化卫生厕所等项目，改善农村卫生环境，有效控制血吸虫病传染源。\n血防地区的单位和居民应当修建使用无害化卫生厕所和沼气池；有钉螺地带的港口、码头、渡口和渔（船）民集散地应当修建使用无害化公共厕所；在有钉螺的水道两岸已建厕所和牲畜圈栏未达到无害化标准的，应当予以拆除或者设置粪便无害化处理设施。卫生、农业等主管部门应当对单位和居民修建使用无害化厕所和沼气池予以指导和监督。\n禁止向水体排放或者施用未经无害化处理的人畜粪便。\n第十条 血防地区各级人民政府应当引导和扶持血防地区调整农业种植结构，有钉螺的水田应当逐步改种旱作物或者水旱轮作，不宜改种旱作物的，应当采取其他有效灭螺措施。\n血防地区各级人民政府采取措施并落实耕牛查病、病牛淘汰及其资金补贴等措施，有计划地逐年减少和淘汰血防地区耕牛存栏数，分层推进农业机械代替耕牛作业，有效阻断血吸虫病传染源。农业主管部门负责对以机代牛农机用户的免费培训，并提供技术指导和服务。\n血吸虫病重点防治地区的农业主管部门应当推进牛、羊、猪等家畜的舍饲圈养，实行圈养家畜粪便的无害化处理，引导养殖户调整养殖模式，发展以禽代畜。\n第十一条 农业、水利等主管部门在血防地区实施农田水利工程、开挖鱼池、建设排灌渠道涵闸等项目时，必须落实防止钉螺扩散的措施。\n水利主管部门在血防地区应当按照疫区优先治水、治水优先灭螺的原则，优先安排安全饮用水建设项目。实施江河湖泊治理工程、灌区改造和小流域治理等水利工程项目时，应当同步配套建设防螺、阻螺设施。\n林业主管部门在血防地区实施退耕还林、防护林建设、野生动物植物保护、湿地保护和自然保护区建设等林业工程项目时，应当开展血吸虫病综合防治。对禁牧的洲（江、河、湖）滩，及时营造抑螺防螺林。\n交通主管部门在血防地区实施道路建设、航道清淤、新建或者改建航道船闸、修建码头等项目时，应当落实血防措施。\n国土资源主管部门应当优先在血防地区实施土地整理等项目，并落实血防设施。\n科技主管部门应当将血防科研项目列入重点科研计划，组织、鼓励科研机构、大专院校和社会各界开展血防研究，积极推广和引进血防新技术、新成果。\n因工程项目需要从有钉螺地带向非疫区供土、供水时，必须落实防止钉螺扩散的措施，并告知供土、供水地和工程项目所在地县级以上人民政府卫生主管部门，卫生主管部门应当予以监督。\n第十二条 血防地区县级人民政府卫生主管部门应当会同农业、水利、林业主管部门，根据血吸虫病监测等流行病学资料，划定、变更有钉螺地带，报经本级人民政府批准。当地人民政府应当及时公告并标明有钉螺地带。\n第十三条 禁止在有钉螺的洲滩等地带放养牛、羊、猪等家畜。禁止引种在有钉螺地带培育的芦苇等植物和农作物的种苗等。禁止在血吸虫病易感地带游泳以及未采取防护措施从事接触疫水的活动。\n血防地区的县（市）、乡（镇）人民政府应当制定禁牧的具体管理办法，明确禁牧监督责任、监管人员、资金安排等事项，并组织实施。农业、卫生等主管部门负责落实禁牧措施，对靠近村庄和人畜活动频繁的有钉螺的洲滩等地带设立禁牧铁丝网等必要的隔离设施，或者安排专人看管，并将禁牧情况定期向上级主管部门和同级人民政府报告。\n乡（镇）人民政府和村（居）民委员会，对设有警示标志的有钉螺的洲滩等地带和血吸虫病易感地带，应当协助做好保护警示标志和执行禁令的工作，劝阻违反禁令的行为。\n因生产、生活需要进入血吸虫病易感地带的人员，应当采取有效防护措施，防止感染血吸虫病。\n第十四条 血防地区交通、卫生、农业主管部门应当加强水上流动人员的防治工作，组织有关单位开展血吸虫病检查、治疗和健康咨询，实施粪便无害化处理。\n第十五条 同一流域的血防地区人民政府应当开展血吸虫病联防联控，组织有关部门和机构同步实施血防措施，整体推进血防工作。\n血防地区县级人民政府应当制定本行政区域的血吸虫病联防联控方案，组织乡（镇）人民政府同步实施。不同行政区域间的联防联控工作，由其共同的上一级人民政府制定联防联控方案，并组织同步实施。\n省人民政府根据全省血防工作的需要，确定省级重点联防联控区域，制定联防联控方案，并督促实施。\n任何单位或者个人不得因行政隶属关系不同等原因妨碍血防工作、推诿血防责任。\n第十六条 建设单位在血防地区兴建水利、交通、旅游、能源等大型建设项目，必须事先提请省级以上血吸虫病预防控制机构对施工环境进行血防卫生学评价。建设单位必须根据血吸虫病预防控制机构的意见，采取必要的血吸虫病预防、控制措施。施工期间，建设单位应当设专人负责工程的血防工作，并接受当地血吸虫病预防控制机构的指导；工程竣工后，应当告知当地血吸虫病预防控制机构，由其对工程地区的血吸虫病进行监测。\n第十七条 血防地区的村（居）民有参加查灭钉螺等义务。村（居）民委员会通过“一事一议”等方式，组织辖区内村（居）民积极参加血防义务劳动。\n农场、林场、养殖场、监狱、劳教场所、驻鄂部队所属单位的查灭钉螺工作以及航运、铁道、公路等用地范围内的查灭钉螺工作，根据属地管理原则，按照所在地卫生主管部门的统一部署和要求，由其经营管理者承担完成，上述单位的上级主管部门应当督促其经营管理者认真履行血防义务。\n第十八条 发现血吸虫病患者应当及早治疗，具备收治血吸虫病病人条件的医疗单位负责血吸虫病病人的检查、治疗，不得拒绝接收和治疗血吸虫病病人，因患有其他严重并发症需要转院治疗或者邀请其他医疗机构医务人员会诊的，应当按规定及时处置。\n第十九条 血防地区有关单位对因生产、工作必须接触疫水的人员应当按照血吸虫病预防控制机构的要求采取防护措施，并定期组织进行血吸虫病专项体检。\n血防地区各级人民政府及其有关主管部门对因防汛、抗洪抢险必须接触疫水的人员（含部队人员），应当按照血吸虫病预防控制机构的要求采取防护措施，并在防汛、抗洪抢险人员脱离现场后一个月内组织对其进行血吸虫病专项体检、治疗和定期追踪监测。\n第二十条 实行血吸虫病疫情报告制度。疫情报告的内容、程序、方式和时限按国家和省有关规定执行，不得隐瞒、谎报、缓报血吸虫病疫情。\n血吸虫病预防控制机构应当依法收集、分析、调查、核实血吸虫病疫情信息，由专门人员负责血吸虫病疫情信息管理工作。动物防疫监督机构应当依法收集、核实家畜血吸虫病疫情并按规定及时上报。\n血吸虫病预防控制机构和动物防疫监督机构，应当及时互相通报血吸虫病疫情信息。\n单位和个人发现血吸虫病疫情，应当向当地卫生主管部门或者血吸虫病预防控制机构、动物防疫监督机构报告。\n血防地区的村医务室承担本辖区疫情信息管理任务，协助做好血吸虫病检查、治疗等工作，县级以上财政应当给予经费补助。\n第二十一条 达到血吸虫病传播控制和传播阻断标准的地区，必须定期开展监测工作，巩固防治成果。\n血防地区发生新的疫情或者已达到传播控制和传播阻断标准的地区重新出现血吸虫病疫情的，当地卫生主管部门应当及时报告同级人民政府和上级卫生主管部门，并采取有效措施控制或者消灭疫情。当地人民政府应当及时以媒体、警示牌、通告等形式告知当地居民，增强防范意识。\n第二十二条 省人民政府和血防地区市、县级人民政府应当根据血防规划、计划，将实施规划、计划所必需的血防经费和其他相关经费优先全额纳入同级财政预算。血防经费必须专款专用，任何单位和个人不得挪用。\n省人民政府和血防地区市、县级人民政府应当根据血防项目规划，安排项目建设投资。\n省人民政府根据血防工作需要，对重点防治地区和经济困难的县（区）开展血防工作给予补助。\n第二十三条 各级人民政府发展改革主管部门在编制或者审批血防地区的卫生、农业、水利、林业、国土资源、交通等项目规划时，应当会同卫生等主管部门将血防设施纳入项目建设中统筹安排。血防设施应当与项目建设同时设计，同时施工，同时投入运行。\n第二十四条 血防预防人员（含畜牧血防预防人员）经费按照定编人数全额纳入同级财政预算。经批准设立的血防专科医院的人员经费由同级财政予以保障。\n第二十五条 对城乡居民免费提供抗血吸虫基本预防药物，对经济困难居民的血吸虫病治疗费用予以减免。对晚期血吸虫病病人按规定实行免费救治。\n已参加城镇基本医疗保险或者新型农村合作医疗的血吸虫病病人，其治疗血吸虫病的费用应当纳入城镇基本医疗保险或者新型农村合作医疗支付范围。\n因工作原因感染血吸虫病的人员，依照《工伤保险条例》的规定，享受工伤待遇。因防汛、抗洪抢险感染血吸虫病的人员，未参加工伤保险、医疗保险的，由当地血防医疗机构免费进行检查和治疗，所需费用由同级财政负担。\n第二十六条 建立血防监督员制度。血防地区县级以上人民政府可聘请血防监督员，由合格的血防专业人员兼任。血防监督员履行卫生主管部门赋予的血防监督职责，并接受同级卫生主管部门的管理。\n第二十七条 血防地区各级人民政府及其有关主管部门对符合以下条件之一的单位和个人，给予表彰或者奖励：\n（一）血防地区县级或者乡级行政区达到血防预期目标的；\n（二）血防工作成效显著的；\n（三）对血防工作有突出贡献的；\n（四）在血防科研工作中取得显著成绩的。\n第二十八条 从有钉螺地带向非疫区供土、供水时不落实防止钉螺扩散措施的，由县级人民政府有关主管部门依据各自职责责令违法单位或者个人停止违法行为并予以整改，对单位处2000元以上2万元以下的罚款，对个人处500元以上2000元以下罚款；逾期不整改的，由有关主管部门采取相关措施防止钉螺扩散，所需费用由违法单位或者个人承担。\n第二十九条 在有钉螺地带放养牛、羊、猪等家畜的，由县级人民政府农业主管部门给予警告，拒不改正的，处以50元以上200元以下的罚款；对放养的家畜可予以暂扣并进行强制检疫，经检疫已感染血吸虫病的，应当依照有关规定，督促家畜所有人及时淘汰处置。\n第三十条 血防地区人民政府及其有关主管部门、机构，未依法履行血吸虫病疫情通报、报告、公布职责，隐瞒、谎报或者授意他人隐瞒、谎报血吸虫病疫情，以及未采取有效措施造成疫情扩散致使公众身体健康遭受危害的，由本级人民政府或者上级人民政府及其主管部门对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第三十一条 倒卖、挪用国家免费供应的防治血吸虫病药品、灭螺药品或者物资的，由县级以上人民政府有关主管部门没收倒卖、挪用的药品及其违法所得，并处以违法所得五至十倍的罚款；对负有责任的主管人员和其他直接责任的人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第三十二条 单位或者个人向水体排放或者施用未经无害化处理的人畜粪便的，由所在地乡（镇）人民政府责令限期整改；逾期拒不整改的，由所在地乡（镇）人民政府组织整改，所需费用由单位或者个人承担。\n第三十三条 违反本条例规定的其他违法行为，有关法律和国务院《血吸虫病防治条例》等行政法规已有处罚规定的，从其规定。\n第三十四条 本条例自2008年12月1日起施行。1991年5月30日湖北省第七届人民代表大会常务委员会第二十次会议通过的《湖北省血吸虫病防治条例》同时废止。","level":0}]},{"id":"h0137","sections":[{"name":"","text":"（2009年3月26日湖北省第十一届人民代表大会常务委员会第九次会议通过 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了加强民用建筑节能管理，提高能源利用效率，建设资源节约型和环境友好型社会，根据《中华人民共和国节约能源法》、《民用建筑节能条例》等法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本条例所称民用建筑节能，是指在保证建筑使用功能和室内热环境质量的前提下，通过提高建筑围护结构的保温隔热性能、选用节能型的用能设备、促进可再生能源与建筑一体化应用等方式降低建筑使用过程中能源消耗的活动（以下简称建筑节能）。\n第三条 本省行政区域内新建（含改建、扩建）建筑节能、既有建筑节能改造、建筑用能系统运行节能及其相关管理活动，适用本条例。\n第四条 县级以上人民政府应当加强对建筑节能工作的领导，制定建筑节能中长期规划和政策措施，实行建筑节能目标责任制，建立建筑节能考核体系；引导和扶持建筑节能与新型墙体材料的科研、开发、生产和推广应用，培育建筑节能服务市场，健全建筑节能服务体系；对在建筑节能工作中作出显著成绩的单位和个人，给予表彰和奖励。\n第五条 县级以上建设主管部门负责本行政区域内建筑节能的监督管理工作，履行下列职责：\n（一）宣传、执行有关建筑节能的法律、法规；\n（二）拟订建筑节能中长期规划并组织实施；\n（三）拟订引导、扶持建筑节能事业发展的政策和措施；\n（四）组织建筑节能新技术、新工艺、新设备、新产品、新材料的研发和论证推广；\n（五）普及建筑节能知识，提供有关建筑节能的信息、技术、培训等服务；\n（六）对新建建筑节能、既有建筑节能改造以及建筑用能系统运行等实施监督管理；\n（七）法律、法规规定的其他职责。\n县级以上人民政府有关部门按照各自职责，负责建筑节能的相关管理工作。\n第六条 建筑规划、设计、施工、监理、检测、验收和能效测评，建筑节能新技术、新工艺、新设备、新产品和新材料的应用，以及建筑用能系统的运行管理应当执行国家、行业建筑节能标准。\n省建设主管部门应当依法制定地方建筑节能标准，并根据本省经济和社会发展的需要适时修订。\n建筑节能新材料和新产品尚未制定国家标准、行业标准、地方标准的，生产企业可以制定企业标准。\n第七条 省建设主管部门应当制定、公布建筑节能新技术、新工艺、新设备、新产品和新材料推广目录，以及技术、工艺、设备、产品和材料限制、禁止使用目录。列入禁止使用目录的不得在建筑中使用。","level":1},{"name":"第二章 建筑节能材料和可再生能源应用","text":"第八条 建筑节能材料应当经济实用，符合安全环保、建筑节能标准。\n县级以上建设主管部门应当采取措施，鼓励研发、推广应用建筑节能材料；鼓励建筑工程使用新型节能门窗和新型节能墙体材料，提高建筑围护结构的保温隔热性能。\n第九条 县级以上建设、市场监督管理等主管部门应当加强对建筑节能材料生产、销售、使用等环节的监督管理。\n县级以上建设主管部门应当建立建筑节能材料推广应用制度,鼓励建筑工程使用节能材料。\n第十条 逐步禁止生产和使用粘土砖。\n省人民政府应当根据各地经济社会发展水平，确定粘土砖生产企业的关停、转产期限；对在规定期限内关停、转产的粘土砖生产企业，采取“以奖代补”等方式予以扶持。具体办法由省人民政府制定。\n县级以上自然资源等部门应当严格控制现有粘土砖生产企业取土范围和规模，禁止向新建、改建、扩建粘土砖生产企业供地和发放采矿许可证。\n第十一条 推广应用散装水泥、预拌混凝土和预拌砂浆。县级以上城市城区应当分步实施禁止现场搅拌混凝土和砂浆的规定。\n第十二条 鼓励和扶持太阳能等可再生能源与建筑一体化应用。\n政府投资新建的公共建筑和既有大型公共建筑实施节能改造时，应当选择应用一种以上可再生能源。\n鼓励和扶持单位、个人安装使用太阳能利用系统。县级以上建设主管部门应当为具备太阳能集热利用条件的新建居住建筑使用太阳能热水系统，拟订政策措施和技术标准；建设单位应当依照相关规定和技术标准为住户预留、配置太阳能热水系统。","level":1},{"name":"第三章 新建建筑节能","text":"第十三条 规划主管部门应当对建筑工程的规划设计方案是否符合建筑节能强制性标准依法进行规划审查；对不符合建筑节能强制性标准的项目，规划主管部门不得颁发建设工程规划许可证。\n第十四条 施工图审查机构应当按照建筑节能强制性标准对施工图设计文件进行审查；对不符合建筑节能强制性标准的项目，施工图审查机构不得出具审查合格书，建设主管部门不得备案和颁发施工许可证。\n经审查合格的施工图设计文件不得擅自变更；确需变更建筑节能设计的，建设单位应当重新履行施工图审查程序。\n第十五条 建设单位应当按照建筑节能的法律、法规和标准，委托建筑工程设计及其审查、施工、监理、检测等单位从事相关的建筑节能活动，并在施工现场的显著位置公布建筑节能相关信息。\n第十六条 设计单位、施工单位、监理单位及其注册执业人员应当按照建筑节能强制性标准进行设计、施工、监理。\n施工单位应当对进入施工现场的建筑节能材料、产品、设备进行查验并按照规定见证取样，送法定的质量检验机构检验；不符合施工图设计文件要求的，不得使用。\n施工单位不按照建筑节能强制性标准施工的，监理单位应当要求施工单位改正；拒不改正的，监理单位应当督促暂停施工，及时向建设单位、建设主管部门或者其委托的建设工程质量监督机构报告。\n第十七条 建筑节能各分项工程完工后，建设单位或者监理单位应当及时组织分项工程验收；对不符合施工图设计文件和相关技术标准要求的，应当责成施工单位整改。\n建设单位组织竣工验收时，应当对建筑节能是否符合建筑节能强制性标准进行查验，并在竣工验收报告中注明建筑节能的实施内容；对不符合建筑节能强制性标准的项目，不得出具竣工验收合格报告。\n第十八条 建设主管部门应当对竣工验收资料进行审核，对不符合建筑节能强制性标准的项目，不予验收备案并责成建设单位限期整改。\n建设工程质量监督机构应当将建筑节能纳入建设工程质量监管的范围；在提交的建设工程质量监督报告中，应当提出建筑节能的专项监督意见。\n第十九条 房地产开发企业销售商品房时，应当按照国家规定在商品房买卖合同和住宅质量保证书、住宅使用说明书中载明所销售房屋的能源消耗指标、节能措施和保护要求、保温隔热工程保修期等信息，并在销售现场显著位置予以公布。","level":1},{"name":"第四章 既有建筑节能改造","text":"第二十条 县级以上建设主管部门应当会同有关部门依照建筑节能中长期规划，提出既有建筑节能改造计划，报本级人民政府批准后分步实施。\n第二十一条 既有建筑节能改造应当以国家机关办公建筑和公共建筑为重点。居住建筑节能改造应当在尊重建筑所有权人意愿的基础上逐步实施。\n第二十二条 既有建筑在改建、扩建和围护结构装饰装修、用能系统更新时，应当同步实施建筑节能改造，达到建筑节能相关标准。\n实施既有建筑节能改造，应当制定节能改造方案，经充分论证后，编制施工图设计文件，经施工图审查机构审查并出具审查合格书后，组织施工。\n第二十三条 县级以上人民政府应当制定优惠政策，鼓励社会资金采用多种模式投资既有建筑的节能改造，提供建筑节能服务。投资人有权按照约定分享既有建筑节能改造获得的收益。","level":1},{"name":"第五章 建筑用能系统运行节能","text":"第二十四条 县级以上建设主管部门应当会同房产管理等相关部门建立本行政区域国家机关办公建筑和大型公共建筑能耗调查、统计、分析和公布制度。国家机关办公建筑和大型公共建筑的所有权人或者使用权人应当建立健全建筑节能管理制度和用能系统操作规程，并向建设主管部门报送年度能耗情况。\n第二十五条 实行重点公共建筑用电定额和超定额加价制度。\n省节能工作主管部门应当会同省建设主管部门根据公共建筑的类型和能耗情况，制定重点公共建筑用电定额。超定额加价的具体办法由省人民政府制定。\n第二十六条 集中供热（冷）系统应当与建筑主体工程同步设计、同步施工、同步验收。\n建筑照明工程应当选用节能型产品，优化照明及控制方式，充分利用自然光，降低照明电耗。\n第二十七条 国家机关办公建筑、大型公共建筑、省级以上建筑节能示范工程和绿色建筑示范工程、财政支持实施节能改造的建筑，应当对建筑的能源利用效率进行测评和标识，并按照国家有关规定将测评结果予以公布，接受社会监督。\n鼓励其他建筑实施建筑能效测评和标识。\n第二十八条 从事建筑能效测评的机构，应当具备国家规定的专业人员和检测设备等条件，依法取得计量认证证书和资格证书，出具的测评报告应当真实、完整。","level":1},{"name":"第六章 激励措施","text":"第二十九条 县级以上人民政府应当设立建筑节能专项资金，用于鼓励扶持下列建筑节能工作：\n（一）建筑节能的科学技术研究、产品开发、标准制定和示范工程；\n（二）既有建筑节能改造；\n（三）可再生能源在建筑中的应用；\n（四）新型墙体材料和绿色建筑的推广应用；\n（五）建筑节能的宣传普及；\n（六）其他建筑节能工作。\n建筑节能专项资金主要来源如下：\n（一）财政拨款；\n（二）本条例规定的重点公共建筑用电超定额加价所得；\n（三）社会捐助等其他来源。\n第三十条 采用地源热泵技术的建筑项目，应当采取安全、环保的回灌措施，确保所抽取的地下水全部回灌；该项目的回灌技术方案应在办理取水许可申请时一并提交，项目投入使用前经水行政主管部门验收合格的，减免水资源费；其集中采暖空调系统按照建筑使用功能实行同类电价。\n列入可再生能源产业发展指导目录的建筑项目，依法享受税收优惠。\n第三十一条 鼓励对建筑屋顶等部位实施绿化，降低建筑能耗，其绿化面积可折算为建筑项目的绿化指标。具体办法由省建设主管部门制定。\n第三十二条 生产、使用列入推广目录的建筑节能新技术、新工艺、新设备、新产品和新材料的，依法享受税收优惠等扶持政策。\n经建筑能效测评获得低能耗建筑能效标识的节能建筑项目，其所得依法减免企业所得税。\n企业购置用于建筑节能专用设备的投资额，依法按照一定比例实行税额抵免。\n经省节能工作主管部门会同省建设主管部门认定符合国家和省资源综合利用目录的新型墙体材料，依法享受相应的税收优惠。\n第三十三条 鼓励金融机构向既有建筑节能改造提供信贷支持，县级以上人民政府可根据情况予以扶持。","level":1},{"name":"第七章 法律责任","text":"第三十四条 违反本条例规定，法律、行政法规有行政处罚规定的，从其规定；造成损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第三十五条 违反本条例规定，有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分：\n（一）批准向新建、改建、扩建粘土砖生产企业供地，发放采矿许可证的；\n（二）对规划设计方案不符合建筑节能强制性标准的建筑项目颁发建设工程规划许可证的；\n（三）对施工图设计文件不符合建筑节能强制性标准的建筑项目予以备案和颁发施工许可证的；\n（四）对不符合建筑节能强制性标准的建筑项目予以竣工验收备案的；\n（五）其他不依法履行监督管理职责的行为。\n第三十六条 对国家机关办公建筑和公共建筑从事本条例第二十二条第一款规定的相关活动时，未同步实施建筑节能改造的，由县级以上建设主管部门责令限期改正；逾期未改正，情节严重的，处1万元以上3万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分，并予通报。\n第三十七条 建筑所有权人或者使用权人违反本条例第二十四条规定，未报送年度建筑能耗情况或者报送情况不实的，由县级以上建设主管部门责令限期改正；逾期未改正的，予以通报。","level":1},{"name":"第八章 附则","text":"第三十八条 本条例自2009年6月1日起施行。","level":1}]},{"id":"h0138","sections":[{"name":"","text":"（2008年2月29日长阳土家族自治县第七届人民代表大会第二次会议通过 2008年4月3日湖北省第十一届人民代表大会常务委员会第三次会议批准 根据2022年2月15日长阳土家族自治县第十届人民代表大会第二次会议通过2022年5月26日湖北省第十三届人民代表大会常务委员会第三十一次会议批准的《长阳土家族自治县人民代表大会关于修改、废止部分单行条例的决定》修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强对矿产资源的勘查、开发和保护，促进经济社会全面、协调、可持续发展，根据《中华人民共和国民族区域自治法》《中华人民共和国矿产资源法》等有关法律、法规的规定，结合自治县实际，制定本条例。\n第二条 自治县行政区域内矿产资源的勘查、开采、经营、保护和监督管理活动，适用本条例。\n第三条 自治县人民政府应当加强矿产资源的保护工作，根据自治县行政区域内矿产资源状况，依法编制矿产资源规划。矿产资源的勘查、开采应当符合各级矿产资源总体规划及相关专项规划要求。\n鼓励公民、法人和其他组织在自治县境内依法勘查、开发利用矿产资源，自治县依法保护探矿权人和采矿权人的合法权益。\n第四条 自治县矿产资源实行有偿采（探）矿制度。勘查、开采矿产资源应当依法缴纳矿业权出让收益和矿业权占用费。\n矿业权出让收益和矿业权占用费县级分成部分纳入一般公共预算管理，用于地质调查及矿山生态环境修复等相关支出。\n第五条 在自治县行政区域内从事矿产资源勘查、开采的单位和个人，必须遵守法律、法规的规定，坚持以人为本，实行安全生产，维护职工的合法权益，照顾矿区居民的利益，不得妨碍当地群众正常的生产和生活。\n第六条 采矿权人必须按照采矿许可证规定的矿区范围和期限从事开采活动，并遵守国家有关劳动安全、矿山地质灾害防治、水土保持、土地复垦、土地占用和文物、环境保护等法律、法规的规定，有效保护、合理开采、综合利用矿产资源。\n采（探）矿权人应当建立矿山地质环境治理恢复基金，主要用于生态环境修复。\n第七条 自治县人民政府根据自治县财政状况和矿产资源保护管理工作的实际需要，将矿产资源保护和管理经费全额纳入财政预算。\n自治县争取国家和上级人民政府对自治县矿产资源保护、勘查和开发利用的扶持和帮助，依法享受国家关于矿产资源保护、勘查和开发利用的各项优惠政策。\n第八条 自治县自然资源和规划主管部门依法负责本行政区域内矿产资源保护、勘查和开发利用的监督管理工作。\n自治县公安、市场监督管理、应急管理、生态环境、人力资源和社会保障、科学技术和经济信息化等有关部门按照各自的职责，做好矿产资源保护和管理的有关工作。\n乡（镇）人民政府必须加强矿产资源的保护工作。\n第九条 自治县人民政府对在保护、勘查和开发利用矿产资源及相关科学技术研究活动中作出显著成绩的单位和个人给予表彰和奖励。\n第十条 公民、法人和其他组织对违反矿产资源管理、破坏矿产资源的违法行为有权制止、检举和控告，自治县自然资源和规划主管部门和乡（镇）人民政府应当公布举报途径和方式。","level":1},{"name":"第二章 矿产资源勘查、开采","text":"第十一条 在自治县行政区域内探矿的，必须符合国家规定的资质条件，并依法申请登记，取得矿产资源勘查许可证。\n申请取得国家出资勘查已经探明矿产地的区块的探矿权的，应当缴纳经国家认可的评估机构评估确认的该矿产地区块的矿业权出让收益。\n第十二条 探矿权人应当自领取矿产资源勘查许可证之日起6个月内开始施工。在施工之前，应当向登记管理机关报送施工报告，并自施工之日起10日内向自治县自然资源和规划主管部门报告施工情况。\n探矿权人因故须中途停止施工的，应当及时向登记管理机关提出停工申请，办理停工手续。停工时间最长不得超过6个月。\n探矿权人必须按照国家有关规定完成最低地质勘查资金投入。\n第十三条 探矿权人必须按照矿产资源勘查许可证规定的区块范围和期限从事探矿活动。不得超越批准的矿产资源勘查区块范围进行勘查作业；不得以探矿为名进行生产性采矿。\n第十四条 探矿权人在矿产资源勘查许可证有效期内进行勘查时，发现符合国家边探边采规定要求的复杂类型矿床的，可以申请开采，经登记管理机关批准，办理采矿登记手续。\n第十五条 开采矿产资源必须依法登记，取得采矿许可证。\n采矿权可以通过招标、拍卖的方式有偿取得。\n第十六条 采矿权申请人应当持下列资料，依法到登记管理机关办理采矿登记手续：\n（一）申请登记书和经自然资源和规划主管部门划定的矿区范围图；\n（二）与其申请开采的矿种和开采规模相适应的资金、技术、设备证明文件；\n（三）经储量审批机构审批的矿产勘查报告；\n（四）矿山设计或者矿山建设项目可行性研究报告及立项等有关批准文件；\n（五）矿产资源利用方案及审查意见；\n（六）矿山环境、矿山地质环境影响评价报告及审查意见；\n（七）水土保持方案及审查意见；\n（八）矿山安全预评价报告及审查意见；\n（九）土地复垦方案及审查意见；\n（十）上级自然资源主管部门规定的其他资料。\n第十七条 下列矿产资源的开采由自治县自然资源和规划主管部门审批登记，颁发采矿许可证：\n（一）开采除国务院规定的34种矿产资源以外的零星分散的矿产资源和只能用作普通建筑材料的砂、石、粘土矿产资源；\n（二）上级自然资源主管部门委托自治县自然资源和规划主管部门审批并颁发采矿许可证的矿产资源。\n第十八条 村级公路、小型农田水利基础设施建设需就地采挖普通砂、石、粘土的，经所在地乡（镇）人民政府审查同意、自治县自然资源和规划主管部门备案后，可以不办理采矿许可证。需异地采挖普通砂、石、粘土的，应当依法办理采矿许可证。\n个人自用采挖普通砂、石、粘土的，可以不办理采矿许可证。\n第十九条 禁止在下列区域内开采地表矿产：\n（一）清江库区两岸水位线以上至第一层山脊；\n（二）经批准设立的自然保护区范围内；\n（三）高速公路、国道、省道、大中型公路桥梁和公路隧道、铁路、天然气管线、通讯电缆、高压输变电线等重要设施法定保护范围内；\n（四）隔河岩大坝、招徕河大坝及其他电站、水库坝址规定保护范围内；\n（五）地质灾害高危地区；\n（六）文物保护区以及其他法律、法规规定的禁采区域内。\n在城镇规划区内从事开矿、采石、挖砂取土等改变地形地貌的活动，必须事先征得自治县有关主管部门同意。\n第二十条 登记管理机关在颁发采矿许可证后，自治县自然资源和规划主管部门应当对矿区范围予以公告。采矿权人应当按照划定的采矿区范围设置地面边界标志。\n第二十一条 采矿权人在取得采矿许可证后，开采矿产储量为中型以上在1年以内、开采小型和零星分散的在6个月以内，应当进行建设或者生产。逾期不进行建设或生产的，采矿许可证自行失效；因特殊情况可申请延期，但必须在期满前30日内提出申请。\n第二十二条 采矿权人应当向自治县自然资源和规划主管部门依法填报矿产资源勘查开采年度信息并按要求公示。\n第二十三条 采矿权人必须委托具有合法资质的测绘机构测绘井下井上工程对照图。自治县自然资源和规划主管部门可以对其测绘成果进行复测和鉴定。\n第二十四条 在矿产资源勘查许可证、采矿许可证有效期内需要变更登记内容的，应当向自然资源和规划主管部门申请办理勘查或者采矿许可证变更登记手续。\n第二十五条 采矿权人在采矿许可证有效期满需要继续采矿的，应当在采矿许可证有效期满前90日内，申请办理延续采矿权登记手续。\n采矿权人逾期不办理延续登记手续的，采矿许可证自行失效；继续采矿的，按无证采矿处理。\n第二十六条 采矿权人应当采取科学合理的开采顺序、开采方法和选矿工艺。矿山企业的开采回采率、选矿回收率和综合利用率应当达到相关要求。禁止采取破坏性开采方法开采矿产资源。\n第二十七条 采（探）矿涉及用地的，应当按照《中华人民共和国土地管理法》的规定取得土地使用权，并对被征（占）用土地的集体经济组织和土地承包经营权人依法进行补偿。\n第二十八条 采（探）矿权人在勘查、开采矿产资源造成地质环境、森林植被破坏或者引发地质灾害的，应当及时向所在地乡（镇）人民政府和自治县有关部门报告，并按照“谁破坏、谁治理”的原则，采取相应的措施进行恢复和治理。\n因采（探）矿引起山体滑坡、自然水源消落及其他对当地居民生产生活造成影响或者损害的，除及时进行治理和采取补救措施外，应当依法予以补偿或者赔偿。\n第二十九条 凡运销重要矿产品和在经济发展中有重要作用的矿产品实行准运制度。任何单位和个人不得违法运销国家统一收购的矿产品。\n禁止收购、销售、运输无采矿许可证的单位或者个人非法开采的矿产品。\n第三十条 自治县禁止一切非法采矿行为。对非法采矿点（场），自治县人民政府应当组织有关部门，采取必要措施予以取缔。\n第三十一条 利用自治县矿产资源设立矿产品加工、经营企业，应当优先安排在自治县区域内，企业的从业人员在同等条件下优先从自治县居民中录用。","level":1},{"name":"第三章 探矿权、采矿权转让","text":"第三十二条 转让探矿权、采矿权，必须依法审批。禁止非法转让探矿权、采矿权。\n第三十三条 取得采矿权的矿山企业，因企业合并、分立，与他人合资、合作经营或者因企业资产出售以及其他变更企业资产产权的情形，需要变更采矿权主体的，经依法批准，可以变更采矿权主体。\n第三十四条 转让探矿权，应当具备下列条件：\n（一）自颁发矿产资源勘查许可证之日起满2年，或者在勘查作业区内发现可供进一步勘查或者开采的矿产资源；\n（二）已完成规定的最低勘查投入；\n（三）探矿权属无争议；\n（四）按照国家有关规定已经缴纳矿业权占用费、矿业权出让收益的；\n（五）国务院自然资源主管部门规定的其他条件。\n第三十五条 转让采矿权，应当具备下列条件：\n（一）矿山企业投入采矿生产满1年；\n（二）采矿权属无争议；\n（三）按照国家有关规定已经缴纳矿业权占用费、矿业权出让收益和资源税；\n（四）国务院自然资源主管部门规定的其他条件。\n国有矿山企业在申请转让采矿权前，应当征得矿山企业主管部门同意。\n第三十六条 采（探）矿权的转让，除由国家和省自然资源主管部门审批之外的矿种，由自治县自然资源和规划主管部门负责审批。\n采（探）矿权转让的受让人，应当符合法律、法规规定的有关采（探）矿权申请人的条件。\n第三十七条 采（探）矿权人在申请转让采（探）矿权时，应当向审批管理机关提交下列资料：\n（一）转让申请书；\n（二）转让人与受让人签订的转让合同；\n（三）受让人资质条件的证明文件；\n（四）转让人具备转让条件的证明；\n（五）矿产资源勘查或者开采情况的报告；\n（六）审批管理机关要求提交的其他有关资料。\n国有矿山企业转让采矿权时还应当提交有主管部门同意转让采矿权的批准文件。","level":1},{"name":"第四章 法律责任","text":"第三十八条 违反本条例规定的，由自治县有关部门依照国家有关法律、法规的规定予以处罚；构成犯罪的，由司法机关依法追究其刑事责任。\n第三十九条 在勘查作业区或者矿山企业进行盗窃、抢夺、破坏矿产资源、矿产品、财物，扰乱生产、生活秩序，破坏勘查、采矿设施的，由公安机关依照治安管理处罚法的有关规定予以处罚；构成犯罪的，依法追究刑事责任。\n第四十条 阻碍国家机关工作人员对矿产资源勘查、开采依法进行监督管理，违反治安管理处罚法的，由公安机关按照治安管理处罚法的有关规定进行处罚；构成犯罪的，依法追究刑事责任。\n第四十一条 当事人对依照本条例规定给予的行政处罚不服的，可以依法申请行政复议，或者直接向人民法院提起诉讼。逾期不申请行政复议也不起诉，又不履行行政处罚决定的，作出行政处罚决定的行政机关依法申请人民法院强制执行。\n第四十二条 国家机关工作人员滥用职权、玩忽职守、徇私舞弊，由所在单位、上级主管部门或者监察机关依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第五章 附 则","text":"第四十三条 本条例自2008年7月1日起施行。","level":1}]},{"id":"h0139","sections":[{"name":"","text":"（2009年3月26日湖北省第十一届人民代表大会常务委员会第九次会议通过 根据2011年12月1日湖北省第十一届人民代表大会常务委员会第二十七次会议《关于修改部分地方性法规中行政强制规定的决定》修正 根据2022年11月25日湖北省第十三届人民代表大会常务委员会第三十四次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正）","level":0},{"name":"第一章 总则","text":"第一条 为规范高速公路管理，保障高速公路安全畅通，维护高速公路投资者、经营者和使用者的合法权益，充分发挥其经济效益和社会效益，根据《中华人民共和国公路法》和其他有关法律法规的规定，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内高速公路的规划、投资、建设、养护、经营、使用和管理。\n第三条 高速公路管理应当遵循集中统一、安全高效、生态环保、以人为本、便民利民的原则。\n第四条 省人民政府交通运输主管部门主管全省高速公路工作。\n省公安机关交通管理部门负责全省高速公路交通安全管理工作。\n省人民政府其他有关部门和高速公路沿线所在地人民政府应当积极配合，共同做好高速公路相关管理工作。\n第五条 省人民政府应当将全省高速公路的发展纳入国民经济和社会发展规划；省人民政府交通运输主管部门在广泛征询社会各界意见的基础上，根据国民经济和社会发展以及国防建设的需要，会同有关部门并商高速公路沿线所在地人民政府编制全省高速公路发展规划，报省人民政府批准后实施，并向社会公布。\n第六条 省人民政府应当制定本省高速公路突发事件应急预案。省人民政府有关部门和高速公路沿线所在地人民政府应当按照各自职责负责高速公路突发事件的应急处理工作。\n第七条 任何单位和个人不得破坏、损坏或者非法占用高速公路、高速公路用地及高速公路附属设施，不得在高速公路上及服务区内非法设卡、收费、罚款和拦截检查车辆。\n任何单位和个人都有爱护高速公路、高速公路用地及高速公路附属设施的义务，有权检举和控告破坏、损坏高速公路、高速公路用地、高速公路附属设施和影响高速公路安全的行为。\n第八条 因自然灾害致使高速公路交通中断，高速公路经营管理者应当维持现场秩序，组织养护作业单位及时修复，并依法向省人民政府交通运输主管部门和所在地人民政府报告；损坏严重难以及时修复的，所在地人民政府应当及时组织抢修。","level":1},{"name":"第二章 建设和养护","text":"第九条 高速公路建设应当遵循基本建设程序，严格执行国家规定的工程设计、施工和监理规范及技术标准，保证合理设计施工周期，确保工程质量。\n高速公路建设项目应当按照国家有关规定实行招投标制度、项目法人及资本金制度、合同管理制度、工程监理制度和工程质量责任追究制度。\n第十条 高速公路建设需要移动或者拆迁桥梁、渡槽、管道、杆线、电力和通讯设施等以及对其他道路设施造成损害的，高速公路建设单位应当按照不低于该设施原有的技术标准予以修复，或者给予相应的经济补偿。\n第十一条 国内外经济组织依法投资建设高速公路的应当实行特许经营。投资经营者的合法权益受法律保护。\n特许经营项目应当采取招投标方式选定投资经营者。\n省人民政府授权省人民政府交通运输主管部门或者市州人民政府与依法成立的高速公路企业项目法人，签订特许经营协议。\n高速公路企业项目法人因自身原因，无法继续投资、建设或者经营特许经营项目的，可以请求解除特许经营协议。未经省人民政府批准，高速公路企业项目法人不得以任何形式转让高速公路特许经营权。\n第十二条 国内外经济组织投资建设的高速公路可以采用委托方式经营管理。省人民政府交通运输主管部门应当制定和完善委托管理规范，加强指导和监督。\n第十三条 在高速公路规划、建设和经营管理过程中，应当采取措施，保护生态环境和文物古迹，防止水土流失，减少污水排放，降低交通噪声，恢复山体植被，做好公路绿化，保持路容路貌整洁美观。\n第十四条 省人民政府交通运输主管部门应当做好高速公路路网标志、标线的规划，并根据实际情况及时提出变更调整方案，科学合理地引导交通。高速公路经营管理者应当按照国家、省有关规范，清晰、准确设置高速公路标志、标线。\n高速公路经营管理者应当按照国家规定的高速公路养护质量标准、技术规范和操作规程，对高速公路进行养护，保障高速公路及其附属设施处于良好的技术状态。\n高速公路经营管理者应当加强高速公路养护巡查，高速公路及其附属设施遭受损坏的，应当及时组织力量修复；遭受重大损毁，交通严重受阻时，应当采取紧急措施，并报请省人民政府交通运输主管部门或者当地人民政府及时组织抢修，尽快恢复交通。\n第十五条 上跨高速公路的公路桥梁、下穿高速公路的道路、收费站连接线，应当在高速公路建成后移交给当地公路部门养护管理。\n第十六条 除日常维护外，高速公路经营管理者应当依法通过招投标方式，确定具有相应资质的单位对高速公路进行养护，并报省人民政府交通运输主管部门备案。\n省人民政府交通运输主管部门应当对高速公路及其附属设施的养护情况进行检查，对达不到高速公路养护规范要求的，应当责成高速公路经营管理者限期采取相应措施。\n第十七条 高速公路养护作业应当科学调度、统筹安排，确定合理的施工时间和工期，减少对车辆通行的影响。高速公路养护作业需要半幅封闭或者中断交通的，高速公路经营管理者应当报省人民政府交通运输主管部门和省公安机关交通管理部门同意，除紧急情况外，提前五天向社会公告，并在高速公路入口处设置公告牌，公告应当包含封闭或者中断交通的原因和施工的具体期限以及交通分流的线路。\n高速公路养护作业，应当在作业地点设置规范的施工、限速和导向等交通标志，作业人员应当穿着统一的安全标志服，其车辆、机械应当安装示警灯，喷涂明显的标志图案，作业时应当开启示警灯和危险报警闪光灯。过往车辆应当按照设置的导向标志行驶，注意避让作业车辆、机械和人员。","level":1},{"name":"第三章 经营服务","text":"第十八条 高速公路经营管理者经依法批准后可以收取车辆通行费。通行高速公路的货运车辆通行费根据国家、省的有关规定，按照车（轴）型收取。\n车辆通行费的收费标准，应当依照价格法律、行政法规的规定进行听证，并按照法定程序审查批准。\n第十九条 高速公路收费站应当在显著位置公布收费标准、收费单位、收费起止年限、监督电话等内容，文明收费，接受监督。\n通行高速公路的车辆应当足额交纳车辆通行费。车辆通行费的减免按照国家有关规定执行。任何单位和个人不得随意减免。\n第二十条 高速公路收费实行全省联网，统一结算和管理。联网方案、收费流程和结算规范，由省人民政府交通运输主管部门制定并组织实施和监督。\n新建高速公路项目应当根据全省高速公路联网运行和管理的需要，按照规定标准建设高速公路通信、监控、收费等管理系统和设施，经省人民政府交通运输主管部门组织检测合格后方可收取车辆通行费。\n已建成通车的高速公路不具备前款设施条件的，由高速公路经营管理者负责建设。\n省人民政府交通运输主管部门应当定期向高速公路经营管理者公布收费结算信息。高速公路经营管理者有权查询本单位的收费结算信息。\n第二十一条 高速公路经营管理者应当按照全省统一规划和要求，不断提高联网收费技术和管理水平。逐步推广高速公路全程监控、智能收费等系统，提高车辆通行能力。\n第二十二条 高速公路经营管理者应当根据车流量开通足够的收费道口，保证车辆畅通。\n高速公路经营管理者应当在收费站口、服务区、重要路段等区域逐步建立和完善电子信息平台，及时发布交通状况、施工作业等有关服务信息，由省人民政府交通运输主管部门监督实施。\n高速公路经营管理者应当及时向省人民政府交通运输主管部门提供收费、还贷、路况、交通流量、养护和管理等有关信息资料。\n第二十三条 高速公路经营管理者应当建立健全各项规章制度，依法经营，规范收费，提供优质服务。\n高速公路经营管理者应当加强对收费站工作人员的业务培训和职业道德教育，收费人员应当持证上岗，做到文明礼貌、规范服务。","level":1},{"name":"第四章 服务区管理","text":"第二十四条 高速公路服务区的设置应当遵循统筹规划、合理布局、功能完善、适度超前的原则。\n高速公路服务区应当与高速公路同步设计、同步建设、同步运营。省高速公路路网内服务区最大间距不得大于60公里。\n因养护维修等原因确需关闭服务区的，应当报省人民政府交通运输主管部门批准。\n第二十五条 省人民政府交通运输主管部门应当制定全省统一的服务区经营管理规范，加强监督管理工作。高速公路经营管理者负责所属高速公路服务区的建设、经营管理工作。\n高速公路服务区可以由高速公路经营管理者自主经营，也可以对外承包经营，对外承包经营的，应当采取服务质量招投标的方式确定经营者，经营者应当按照承诺的服务内容、标准提供服务。\n交通运输主管部门应当定期对服务区运营质量组织评价，并将评价结果向社会公布，接受社会监督。\n第二十六条 高速公路服务区应当提供下列服务设施：\n（一）短暂休息、停车场、饮用水供应、公共厕所等免费使用的公益性基本设施；\n（二）加油、购物、餐饮以及汽车维修等经营性基本设施；\n（三）绿化、水土保持、夜间照明及给排水、污水处理、备用电设备等功能性基本设施。\n服务区经营者应当保证服务区设施处于良好状态，保持服务区的安全、清洁、卫生。\n第二十七条 高速公路服务区经营者应当公开服务内容、标准、价格，依法经营，诚实守信，文明服务。禁止下列行为：\n（一）擅自扩大收费范围、提高服务收费标准；\n（二）强制他人接受有偿服务；\n（三）刁难、勒索和敲诈司乘人员；\n（四）收费不开具合法有效的票据；\n（五）其他违法违规行为。\n省人民政府交通运输主管部门应当对高速公路服务区承包经营者的承包经营行为是否符合经营服务规范进行监督检查。\n高速公路服务区所在地公安、卫生健康、生态环境、市场监督管理等部门应当依据各自职责加强对服务区治安、食品卫生、经营和服务的监督管理。","level":1},{"name":"第五章 路政管理","text":"第二十八条 省人民政府交通运输主管部门应当向各高速公路（含在建）派驻路政管理机构。\n高速公路路政执法经费从高速公路通行费中列支，纳入省级财政预算，具体办法由省人民政府交通运输主管部门会同财政主管部门制定。\n第二十九条 省人民政府交通运输主管部门应当加强对高速公路的监督管理，检查、制止各种非法侵占、损坏高速公路、高速公路用地、高速公路附属设施及其他违反本条例规定的行为。\n省人民政府交通运输主管部门及有关部门应当建立投诉、举报、奖励制度，公布举报电话、通讯地址、电子邮件地址，为举报者保密，并对举报属实者给予奖励。\n高速公路路政执法人员执行公务，应当公正廉洁、热情服务、着装整齐、佩戴标志、持证上岗、文明执法。\n第三十条 高速公路监督检查车辆应当按照国家有关规定设置统一的标志和示警灯。\n任何单位和个人不得擅自喷印、安装、使用与高速公路监督检查车辆相同或者相似的标志和示警灯。\n高速公路监督检查车辆在高速公路上依法执行抢险、救灾等紧急公务时，需要采取紧急通行措施的，应当确保交通安全。\n第三十一条 高速公路用地范围按照以下标准确定：\n（一）高速公路边沟（隔离栅）外缘起1米的区域；\n（二）无高速公路边沟（隔离栅）的，为公路路沿石外缘起5米的区域；\n（三）高速公路桥梁为桥梁垂直投影面外缘起1米的区域。\n第三十二条 在高速公路及其用地范围内，禁止从事下列活动：\n（一）抛洒、堆放物品，倾倒垃圾，排放污水；\n（二）设置棚屋、摊点、维修场及其他临时设施；\n（三）取土采石，挖损路面，堵塞通道、涵洞、填充边沟；\n（四）种植作物，放养牲畜；\n（五）擅自安装、拆除、涂改、移动高速公路附属设施、公路标志；\n（六）随意上下乘客、装卸货物、载物拖地行驶；\n（七）利用高速公路边沟排水、蓄水灌溉、养殖；\n（八）其他侵占、污染等损害性活动。\n第三十三条 在高速公路及其用地范围内从事下列活动，应当报省人民政府交通运输主管部门批准：\n（一）设置广告等非公路标志标牌；\n（二）修建跨（穿）越公路的建（构）筑物，架设杆线，埋设管道、缆线；\n（三）修建出入高速公路的交叉道口；\n（四）占（利）用、挖掘高速公路及其公路用地；\n（五）更新、砍伐公路树木。\n第三十四条 从高速公路用地外缘起50米的区域为高速公路建筑控制区。\n除公路防护、养护需要外，禁止在高速公路建筑控制区新建、扩建建筑物和地面构筑物，或者从事爆破、采空作业、取土、挖砂、挖沟、排污等可能危及高速公路安全的行为。控制区内原有的合法的建筑物、构筑物需要拆迁的，高速公路经营管理者应当依法给予补偿。\n第三十五条 在不影响安全的情况下，高速公路桥梁桥下空间可以用于绿化和绿道建设等公益用途。\n第三十六条 高速公路经营管理者应当保证高速公路隧道照明、通风、消防、监控等设施的正常使用，不得随意停止使用，不得影响车辆安全通行。\n高速公路消防安全工作由所在地消防救援机构负责。\n第三十七条 省人民政府交通运输主管部门应当在高速公路出入口、服务区、检测站进行超限运输检查，过往车辆应当按照引导标志行驶到指定地点接受检查，不得强行通过。\n高速公路经营管理者应当在高速公路入口、相关跨越高速公路的设施，设置车辆限载、限高、限宽、限长标志。\n第三十八条 在高速公路行车道、桥梁、匝道上和隧道内不得检修车辆，因突发故障临时检修的，应当将车辆移入紧急停车带，并对高速公路及其附属设施采取保护措施。\n第三十九条 车辆在高速公路上发生交通事故时，省公安机关交通管理部门、省人民政府交通运输主管部门应当立即派员赶赴现场，组织抢救伤者和保护财产。\n省公安机关交通管理部门负责调查事故现场，处理交通事故，维持事故现场的交通秩序并根据需要及时通知清障施救单位进行清障施救。\n省人民政府交通运输主管部门负责调查处理路产损失情况。省公安机关交通管理部门在处理交通事故涉及路产损失的，应当及时通知省人民政府交通运输主管部门。\n第四十条 高速公路清障施救服务由高速公路经营管理者统筹组织实施，接受公安机关交通管理部门、人民政府交通运输主管部门的现场组织调度。\n省人民政府交通运输主管部门应当统一监督管理和规范高速公路清障施救服务。公安机关交通管理、市场监督管理等部门在各自职责范围内依法对清障施救服务进行监督管理。\n清障施救服务应当符合就近、安全、便捷的原则，体现高速公路清障服务的公益属性。清障施救服务标准和规程由省人民政府交通运输主管部门会同省公安机关交通管理等部门制定。\n高速公路清障施救服务单位应当执行清障施救服务标准和规程，按照省人民政府交通运输主管部门确定的标准收费，不得擅自增加收费项目、扩大收费范围、提高收费标准。\n第四十一条 省公安机关交通管理部门和省人民政府交通运输主管部门在交通安全和路政管理工作中，应当加强配合，实现信息资源共享。\n因严重自然灾害、恶劣气候或者重特大交通事故等特殊情形影响车辆正常通行的，省公安机关交通管理部门和省人民政府交通运输主管部门应当及时相互通报路况信息，采取限制车速、间断放行等措施对车辆进行疏导。\n采取措施后仍难以保证交通安全确需封闭高速公路的，省公安机关交通管理部门应当征求省人民政府交通运输主管部门意见后实施，并及时向社会公告。\n高速公路经营管理者应当根据国家和本省有关应急规定，制定高速公路应急处置方案，组织应急处置队伍并定期开展应急处置方案演练。\n因重特大交通事故造成高速公路严重堵塞，难以及时恢复交通的，以及装载危险物品车辆发生故障可能造成严重后果的，高速公路所在地人民政府应当组织调集清障施救力量，协助清障施救，排除危险。","level":1},{"name":"第六章 法律责任","text":"第四十二条 违反本条例规定的行为，法律、行政法规有行政处罚规定的，从其规定；造成损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第四十三条 高速公路企业项目法人违反特许经营协议以及其他双方约定，造成高速公路项目不能满足开工条件、资金不能及时足额到位、工程不能按期进展、高速公路不能如期投入使用等严重后果又不请求解除特许经营协议的，省人民政府有权撤回特许经营权。\n第四十四条 违反本条例规定，高速公路经营管理者未按照国家技术规范和操作规程进行公路养护，影响高速公路安全运行的，由省人民政府交通运输主管部门责令限期改正；逾期未改正的，由省人民政府交通运输主管部门指定其他单位进行养护，所需养护费用由高速公路经营管理者承担；拒不承担的，由省人民政府交通运输主管部门申请人民法院强制执行。\n第四十五条 违反本条例规定，少交、逃交、拒交高速公路车辆通行费的，高速公路经营管理者有权拒绝其通行，并要求其补交应交车辆通行费，省人民政府交通运输主管部门可处以本省路网最远站至本站全程通行费2倍的罚款；故意堵塞收费车道的，实行强制牵移，由此造成的损失和产生的相关费用由当事人承担。\n第四十六条 高速公路经营管理者违反本条例规定，有下列情形之一的，由省人民政府交通运输主管部门责令限期改正；逾期未改正或者有其他严重情节的，可处5000元以上2万元以下的罚款：\n（一）未开通足够数量的收费道口，造成车辆堵塞的；\n（二）擅自减免车辆通行费的；\n（三）随意停止使用照明、通风等设施，影响车辆安全通行的；\n（四）未按照规定设置电子信息设备，及时向社会发布交通状况、施工作业等相关服务信息的；\n（五）养护作业擅自半幅封闭道路或者中断交通的。\n第四十七条 违反本条例，未按规定开通或者擅自关闭服务区，影响高速公路运营管理的，由省人民政府交通运输主管部门责令限期改正；逾期不改正的，处1万元以上5万元以下的罚款；仍不改正的，由省人民政府交通运输主管部门指定其他专业机构代为开通，有关费用由高速公路经营管理者承担。\n第四十八条 违反本条例规定，在高速公路上检修车辆未对高速公路及其附属设施采取保护措施的，由省人民政府交通运输主管部门责令改正；拒不改正的，可处100元以上300元以下的罚款。\n第四十九条 清障施救服务单位违反清障施救服务标准和规程的，由省人民政府交通运输主管部门责令改正，并可处1000元以上5000元以下的罚款；情节严重的，取消清障施救服务资格。\n第五十条 国家工作人员有下列行为之一的，由有权机关给予处分：\n（一）不依法实施行政许可的；\n（二）扩大罚款范围、变更罚款标准的；\n（三）收取高速公路路产损坏赔（补）偿费或者罚款不开具合法票据的；\n（四）利用职务上的便利收受他人财物或者谋取其他利益的；\n（五）滥用职权、徇私舞弊、故意刁难管理相对人或者强制他人接受有偿服务的；\n（六）玩忽职守使国家、集体财产遭受重大损失的；\n（七）发现违法行为不依法查处的；\n（八）其他违规违法行为。","level":1},{"name":"第七章 附则","text":"第五十一条 本条例有关用语含义如下：\n（一）“高速公路”是指按照国家公路工程技术标准建设的专供汽车分向、分车道行驶并应全部控制出入的多车道公路（含桥梁和隧道）。\n（二）“高速公路附属设施”包括高速公路的防护、安全、排水、养护、绿化、服务、监控、通信、收费、供电、供水、照明和交通标志、标线及管理等设施、设备和专用的建筑物、构筑物。\n（三）“非公路标志标牌”包括除国家标准规定公路标志以外的指路牌、地名牌、厂（店）名牌、宣传牌、广告牌、龙门架、霓虹灯、电子显示屏、橱窗、灯箱和其他标牌设施等。\n第五十二条 本条例自2009年6月1日起施行。1997年8月5日湖北省第八届人民代表大会常务委员会第二十九次会议通过的《湖北省高等级公路管理条例》同时废止。","level":1}]},{"id":"h0140","sections":[{"name":"","text":"（2009年7月31日湖北省第十一届人民代表大会常务委员会第十一次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了实施《中华人民共和国未成年人保护法》，结合本省实际，制定本办法。\n第二条 本省行政区域内未满十八周岁公民的保护，适用本办法。\n未成年人享有生存权、发展权、受教育权、受保护权、参与权等权利，其合法权益应当得到特殊、优先保护。\n第三条 国家机关、政党、社会团体、部队、企业事业单位、基层群众性自治组织、学校及家庭和每个成年公民应当共同关心、培养、教育未成年人，优化未成年人成长环境，教育和帮助未成年人增强自我保护意识和能力，促进未成年人在德、智、体、美等方面全面发展。\n对侵犯未成年人合法权益的行为，任何组织和个人都有权予以劝阻、制止或者向有关部门检举、控告。\n第四条 各级人民政府领导本行政区域内的未成年人保护工作，决定未成年人保护工作中的重大事项，将未成年人保护工作纳入国民经济和社会发展规划及年度计划，建立和落实未成年人保护工作责任制。\n教育、公安、民政、卫生、文化、人力资源和社会保障、工商、广播电影电视、新闻出版等部门以及审判检察机关共同配合，在各自职责范围内，做好未成年人保护工作。\n共产主义青年团、妇女联合会、工会、残疾人联合会、科学技术协会、关心下一代工作委员会以及其他社会组织，应当把维护未成年人合法权益作为重要职责，协助人民政府做好未成年人保护工作。\n乡镇人民政府、街道办事处应当确定专人负责未成年人保护工作。\n村（居）民委员会应当协助和配合做好本辖区内的未成年人保护工作。\n第五条 县级以上人民政府设立未成年人保护委员会，其办事机构设在同级共产主义青年团委员会，工作经费列入财政预算。\n未成年人保护委员会承担下列职责：\n（一）宣传贯彻有关未成年人保护的法律、法规，并对实施情况进行监督、检查；\n（二）制定未成年人保护工作发展规划、年度工作计划和相关工作制度；\n（三）组织、指导、协调有关部门做好未成年人保护、教育和救助工作；\n（四）接受有关侵犯未成年人合法权益的投诉、举报，督促相关部门及时处理；\n（五）开展未成年人保护工作的调查研究，向本级人民政府和有关部门提出意见和建议；\n（六）加强未成年人保护工作队伍建设；\n（七）做好有关未成年人保护的其他工作。\n第六条 各级人民政府和有关部门对保护未成年人和促进未成年人事业发展方面作出突出贡献的单位和个人，给予表彰和奖励。","level":1},{"name":"第二章 家庭保护","text":"第七条 父母或者其他监护人应当依法对未成年人履行监护职责和抚养、教育义务。家庭其他成年人有协助监护人关心、教育、保护未成年人的责任。\n父母或者其他监护人应当为未成年人创造良好、和睦的家庭环境，关注未成年人的生理、心理状况和行为习惯，以健康、良好的品行教育影响未成年人。\n父母或者其他监护人应当学习、掌握科学的教育和监护方法，配合学校做好未成年人的教育工作。\n未成年人的父母或者其他监护人所在单位、社区和基层组织，应当关心职工、村（居）民的家庭教育问题，教育、引导和督促职工、村（居）民重视对未成年人的教育和保护。\n第八条 父母或者其他监护人不得因未成年人的性别、健康状况、是否婚生以及有违法犯罪行为等任何理由，拒绝履行监护职责和抚养、教育义务。没有监护措施，不得让未满十六周岁的未成年人分户独居。\n禁止对未成年人实施殴打、辱骂、体罚等家庭暴力行为，禁止虐待、遗弃未成年人，禁止溺婴和其他残害婴儿的行为，不得歧视女性未成年人或者有残疾的未成年人。\n第九条 父母或者其他监护人应当预防和制止未成年人发生以下行为：\n（一）吸烟、酗酒、旷课、弃学、夜不归宿；\n（二）携带管制刀具、打架斗殴、辱骂他人；\n（三）偷窃、故意毁坏财物、强行向他人索要财物；\n（四）参与赌博或者变相赌博；\n（五）观看、收听色情、淫秽的音像制品、读物等；\n（六）进入法律、法规规定未成年人不适宜进入的互联网上网服务营业场所、营业性歌舞娱乐场所等活动场所，或者沉溺于网络、电玩游戏等；\n（七）其他违法或者违背社会公德的行为。\n禁止任何人教唆、引诱、胁迫未成年人实施不良行为或者违法犯罪行为。\n第十条 父母或者其他监护人应当保证未成年人接受并完成义务教育，不得使正在接受义务教育的未成年人中途辍学。\n第十一条 父母或者其他监护人应当妥善保护未成年人财产，除有利于未成年人的利益外，不得处分其财产。\n第十二条 父母因外出务工或者其他原因不能履行对未成年子女监护职责的，应当委托有监护能力的其他成年人代为监护，并提供生活保障。受委托监护人应当依法履行监护职责。\n委托监护时，父母应当听取有表达意愿能力的未成年子女意见，并及时将委托监护情况告知未成年子女所在学校和户籍所在地或者经常居住地的村（居）民委员会，村（居）民委员会和学校应当与受委托监护人保持联系，对未成年人提供必要的帮助。\n父母应当与未成年子女和受委托监护人保持经常联系，关心未成年子女生活、学习和身心健康情况。","level":1},{"name":"第三章 学校保护","text":"第十三条 学校、幼儿园应当尊重和维护未成年人受教育权，不得拒绝适龄未成年人入学。学校不得强迫未成年学生停课、退学或者违法开除未成年学生。\n第十四条 学校应当实施素质教育。义务教育阶段学校不得举行与入学挂钩的选拔考试，不得增加学生课业负担，不得公布学生成绩名次。\n教育行政部门应当将法制教育纳入教学大纲。学校应当配备专兼职法制教师，聘请兼职法制副校长或者法制辅导员，实行课堂教学与校外教育相结合，保证法制教育课时。\n学校应当根据未成年学生身心发展的特点，对其进行社会生活指导、心理健康辅导和青春期教育，配备心理健康辅导员。\n学校教师和其他教育工作者应当履行本职工作职责，严格遵守职业道德规范；教师不得开办、参与或者推荐学生参与有偿课外辅导补习班、家教。教育行政部门、学校应当采取措施，保证教师将主要精力用于校内教学。\n第十五条 学校、未成年学生父母或者其他监护人应当互相配合，合理安排课业，保证未成年人的睡眠、娱乐和体育锻炼时间。\n第十六条 学校、幼儿园、托儿所的教育工作者应当关心、爱护、平等对待未成年人，不得以成绩或者其他因素歧视未成年人；禁止对未成年人实施体罚或者侮辱、诽谤、恐吓、贬损等损害其身心健康的言行。\n第十七条 对有违纪行为的未成年学生，学校应当进行说服、教育和帮助；确需给予处分的，学校应当听取未成年学生及其父母或者其他监护人的陈述、申辩，并予以答复。未成年学生受到处分后已改正的，学校应当取消其处分决定，不列入品行记载。\n第十八条 学校、父母或者其他监护人应当加强对有严重不良行为未成年学生的教育、管理；无力管教或者管教无效的，可以按照有关规定送专门学校继续接受教育。学生在专门学校学习期间，原所在学校应当保留其学籍，其在专门学校学习的经历不记入个人档案。\n专门学校学生在复学、升学、就业等方面与普通学校学生享有同等权利，任何单位和个人不得歧视。\n第十九条 学校应当加强网络知识与技能教育，校内互联网上网场所应当优先为未成年学生提供健康有益的上网服务，不得出租或者承包经营。\n第二十条 鼓励和支持中小学校在节假日期间将文化体育设施对未成年人免费或者优惠开放。\n学校应当加强对学生的活动场地、设施的检查、维护，保证其使用安全，并不得将其移作与教学无关的非公益性用途。\n第二十一条 学校、幼儿园、托儿所校舍和其他设施建设应当符合国家抗震设防、消防、环境保护等规定，并进行经常性地安全、卫生检查。\n第二十二条 学校、幼儿园应当建立校园安全制度，配备或者聘请专兼职保卫人员。教职员工对学校及周边发生的扰乱教学秩序或者侵犯未成年学生人身、财产安全的行为应当及时制止，必要时向公安机关报告。\n学校、幼儿园组织未成年学生参加集会、文化娱乐、体育、社会实践等集体活动应当采取安全措施，防止发生人身安全事故。\n第二十三条 学校、幼儿园、托儿所应当制定突发事件应急预案，针对各种灾害、传染性疾病、食物中毒、意外伤害等突发事件进行的安全演练，每学期不少于一次。教育行政部门应当予以指导和监督。\n发生突发事件和未成年人人身伤害事故时，学校、幼儿园、托儿所应当优先保护未成年人的安全，及时救护，妥善处理，并向有关主管部门报告。\n第二十四条 学校、幼儿园不得组织未成年学生参加剪彩、奠基等商业性活动；确需组织未成年人参加公益性庆典和外事活动的，应当经县级以上人民政府教育行政部门批准。\n第二十五条 学校、幼儿园、托儿所除按国家和省规定收取费用外，不得另立收费项目或者提高收费标准；不得强迫或者变相强迫学生购买商品、教学辅助材料或者捐款捐物。","level":1},{"name":"第四章 社会保护","text":"第二十六条 各级人民政府应当将未成年人文化体育活动场所和设施建设纳入经济社会发展总体规划。县级以上行政区域应当至少建有一处综合性未成年人活动场所；新建或者扩建城镇、居民小区，应当配套建设向未成年人开放的社区活动场所。鼓励社会力量兴办未成年人活动场所，并加强管理。\n爱国主义教育基地、公共博物馆、图书馆、青少年宫、儿童活动中心应当免费对未成年人开放。展览馆、科技馆、文化馆、纪念馆、美术馆、体育场馆、公园、动物园、植物园等场馆，应当依照国家有关规定免费或者优惠对未成年人开放。\n第二十七条 公安、卫生、文化、环境保护、工商、住房和城乡建设等行政部门，应当加强对学校、幼儿园、托儿所周边治安、交通、食品安全、文化市场、环境、广告、市政设施等方面的监管和综合治理；对学校周边环境恶劣的地段，应当组织专项治理。\n前款规定的行政部门应当设立举报电话，教育行政部门应当统一制作列有各行政部门举报电话的标牌，悬挂在学校门口显著位置。\n第二十八条 公安、住房和城乡建设、交通运输行政部门应当在学校、幼儿园周边道路设置完善的交通标志、标线及交通安全设施；在城市学校、幼儿园周边有条件的道路设置上学、放学时段的临时停车泊位。\n使用车辆接送未成年人的单位或者个人，应当严格按照核定的车辆限乘人数接送未成年人，保证车辆的安全性能，并在显著位置设置未成年人乘用车辆标志。公安、教育行政部门和有关单位应当加强对接送未成年人车辆的检查监督，及时排除安全隐患。\n第二十九条 中小学校园周边二百米范围内不得开设互联网上网服务营业场所、营业性歌舞娱乐场所等不适宜未成年人活动的场所；不得设立易燃易爆、剧毒、放射性、腐蚀性等危险物品的生产、经营、储存、使用场所或者设施。\n第三十条 广播、电视、报纸、互联网等新闻媒体以及演艺团体，在其传播、创作活动中，应当强化有利于未成年人身心健康的社会责任，完善审查、审核机制，及时揭露侵害未成年人合法权益的行为，为未成年人健康成长营造良好的社会舆论氛围。\n第三十一条 互联网上网服务营业场所、营业性歌舞娱乐场所等不适宜未成年人活动的场所，不得允许未成年人进入；对难以判明是否成年的，应当要求其出示身份证件。经营者应当在显著位置设置未成年人禁入标志和主管部门的举报电话，主管部门应当监督实施。\n文化、公安、工商、通信管理等行政部门应当加强对互联网上网服务营业场所及网上信息内容的管理和监督检查，建立完善互联网上网服务营业场所义务监督员等制度，净化网络及上网服务营业场所环境；乡镇人民政府、街道办事处以及村（居）民委员会应当予以配合。\n第三十二条 各级人民政府及有关部门应当采取措施，鼓励和支持社区、学校以及有条件的单位建设、开放公益性互联网上网服务设施，推广绿色上网软件，为未成年人提供安全、健康、便利的上网服务。\n第三十三条 禁止向未成年人出售烟酒；对难以判明是否成年的，应当要求其出示身份证件。经营者应当在显著位置设置禁售标志和主管部门的举报电话，主管部门应当监督实施。\n任何单位和个人不得向未成年人提供烟酒。禁止在中小学校、幼儿园、托儿所的教室、寝室、活动室、阅览室和未成年人活动的其他室内场所吸烟、饮酒。\n第三十四条 任何组织和个人不得披露未成年人隐私。对未成年人的信件、日记、电子邮件、网上聊天记录、手机短信及其他个人信息，任何组织和个人不得隐匿、毁弃，未经本人或其监护人同意，不得擅自开拆、查阅。法律法规另有规定的除外。\n第三十五条 对于人民检察院不起诉，人民法院免予刑事处罚、判处管制、宣告缓刑，解除羁押、服刑期满以及解除劳动教养的未成年人，学校、企业事业单位、人力资源和社会保障行政部门应当保障其享有复学、升学、就业的权利，任何单位和个人不得歧视。\n第三十六条 任何单位和个人不得招用未满十六周岁的未成年人，国家另有规定的除外。\n依照国家有关规定招用已满十六周岁的未成年人，应当执行国家有关工种、劳动时间、劳动强度和劳动保护措施的规定，不得安排其从事过重、有毒、有害等危害未成年人身心健康的劳动或者危险作业。\n第三十七条 对因父母进城务工而随父母进城接受义务教育的未成年人，流入地人民政府应当采取措施，保障其享有与当地城镇居民子女同等的受教育权；流出地人民政府应当配合做好相关的服务保障工作。\n第三十八条 未成年人合法权益受到侵害时，当事人有权直接或者通过监护人向所在学校、当地村（居）民委员会或者有关部门请求保护和投诉、举报。\n接到保护请求的有关单位和组织应当及时采取救助措施，不得拒绝、推诿。\n未成年人遇有人身伤害危险而紧急求助时，首先接到求助请求的国家机关、企业事业单位和社会组织，应当及时提供救助。\n民政部门应当对弃儿、孤儿和流浪乞讨等生活无着以及因受虐待等需要及时救助的未成年人实施救助，并对孤儿、无法查明其父母或者其他监护人的以及其他生活无着的未成年人予以收留抚养。\n民政、卫生等行政部门应当完善相关政策，对患重大疾病且生活困难的未成年人实施医疗救助。\n第三十九条 教育行政部门可以根据实际情况，鼓励中小学校参加学校责任保险。\n提倡未成年学生自愿参加意外伤害保险。","level":1},{"name":"第五章 司法保护","text":"第四十条 公安机关、人民检察院、人民法院、司法行政部门应当在司法活动中保护未成年人的合法权益，坚持教育为主、惩罚为辅的原则，做好未成年人违法犯罪预防和矫治工作，教育、感化、挽救违法犯罪未成年人。\n公安机关、人民检察院、人民法院应当根据需要设立专门机构或者指定专人依法办理涉及未成年人的案件。\n第四十一条 公安机关、人民检察院讯问未成年犯罪嫌疑人，询问未成年被害人、未成年证人时，应当通知监护人到场。\n公安机关、人民检察院、人民法院在办理未成年人遭受性侵害案件时，应当采取措施保护未成年人的隐私权和名誉权，防止未成年被害人生理、心理上受到新的伤害。\n第四十二条 人民法院办理未成年人刑事案件，必要时委托未成年人保护委员会或者其他组织聘请社会调查员。\n社会调查员根据委托，可以对涉嫌犯罪的未成年人性格特点、家庭情况、社会交往、成长经历以及被指控犯罪前后的表现等情况进行调查，并制作书面材料供办案参考。\n社会调查员在开展调查过程中，不得披露被调查未成年人的有关信息和资料。\n第四十三条 保护未成年人继承、接受赠予或者以其他合法方式获得财产的权利。\n人民法院审理离婚案件，应当维护未成年人的合法权益，在涉及未成年子女抚养问题时，应当听取有表达意愿能力的未成年子女的意见，根据保障子女权益的原则和双方具体情况依法处理。\n第四十四条 对监护人侵害未成年人合法权益或者不履行监护职责的，未成年人可以申请行政救助、法律援助或者司法救助；村（居）民委员会或者与该争议事项无利害关系的其他法定代理人可以代为申请行政救助、法律援助或者司法救助。\n第四十五条 公安机关和其他有管辖权的机关接到未成年人受侵害案件的投诉、举报后应当及时受理，并在受理之日起30日内作出处理决定；重大复杂案件经其上级主管部门批准可延长15日。法律法规另有规定的除外。\n处理决定应当及时通知举报人、投诉人、被害人及其监护人。","level":1},{"name":"第六章 法律责任","text":"第四十六条 违反本办法规定，侵害未成年人合法权益，其他法律、法规已规定行政处罚的，从其规定；造成人身财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第四十七条 违反本办法第八条、第九条、第十条、第十一条、第十二条规定，由其所在单位或者村（居）民委员会予以劝诫、制止和教育。\n第四十八条 学校、幼儿园违反本办法规定，有下列情形之一的，由教育行政部门责令改正；拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予行政处分：\n（一）拒绝适龄未成年人入学，强迫未成年学生停课、退学或者违法开除未成年学生的；\n（二）将校内互联网上网场所出租或者承包经营的；\n（三）未建立校园安全制度，校园安全管理混乱的；\n（四）组织未成年学生参加剪彩、奠基等商业性活动的；\n（五）强迫或者变相强迫学生购买商品、教学辅助材料或者捐款捐物的。\n学校、幼儿园、托儿所的教育工作者对未成年人实施体罚或者侮辱、诽谤、恐吓、贬损等损害其身心健康的言行的，由其所在单位或者教育行政部门依法给予行政处分或者解聘。\n第四十九条 违反本办法第三十一条规定，互联网上网服务营业场所接纳未成年人进入的，由文化行政部门责令改正，并可处500元以上2000元以下罚款；拒不改正的，处2000元以上15000元以下罚款；情节严重的，责令停业整顿，直至吊销《网络文化经营许可证》。\n第五十条 违反本办法第三十三条第一款规定，向未成年人出售烟酒的，由负责烟草、酒类专卖的主管部门责令改正，并可处100元以上500元以下罚款；拒不改正的，处500元以上2000元以下的罚款。\n第五十一条 违反本办法第三十三条第二款规定，在中小学校、幼儿园、托儿所的教室、寝室、活动室、阅览室和未成年人活动的其他室内场所吸烟、饮酒的，所在学校（园、所）应当及时制止，予以批评教育；拒不改正的，由教育行政部门处以200元以下罚款。\n第五十二条 国家机关及其工作人员违反本办法规定，不履行保护未成年人合法权益职责或者在未成年人保护工作中滥用职权、玩忽职守、徇私舞弊的，由其所在单位或者上级主管机关责令改正；情节严重的，对直接负责的主管人员和直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第五十三条 本办法自2009年10月1日起施行。1992年11月30日湖北省第七届人民代表大会常务委员会第三十次会议通过，1997年12月3日湖北省第八届人民代表大会常务委员会第三十一次会议修改的《湖北省未成年人保护实施办法》同时废止。","level":1}]},{"id":"h0141","sections":[{"name":"","text":"（2009年7月31日湖北省第十一届人民代表大会常务委员会第十一次会议通过 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》第二次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了加快信息化建设，规范信息化管理，推动经济和社会发展，根据有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内的信息化发展规划与建设、信息产业发展、信息技术推广应用、信息资源开发利用、信息安全保障以及相关管理活动，适用本条例。\n第三条 信息化工作应当遵循统筹规划、资源共享、务求实效、安全可靠的原则。\n第四条 县级以上人民政府应当加强对信息化工作的领导，将信息化发展纳入国民经济和社会发展规划，建立健全信息化工作领导协调机制，推动信息技术创新和应用，加强信息化人才的培养和引进，开展信息化知识的宣传、普及，促进信息化发展。\n县级以上人民政府应当安排信息化专项资金，用于引导和推动信息化建设；鼓励企事业单位和个人加大对信息化发展资金的投入。\n乡镇人民政府应当推进本辖区内的信息化发展工作。\n县级以上人民政府应当对在信息化工作中取得显著成绩的单位和个人，给予表彰和奖励。\n第五条 县级以上人民政府信息化主管部门负责本行政区域内信息化发展的统一规划、组织协调和监督管理等工作。主要职责是：\n（一）贯彻执行国家和省有关信息化的法律、法规和规章；\n（二）指导和组织编制信息化发展规划；\n（三）指导和统筹本行政区域内的信息化发展工作，促进公共信息网络、信息应用系统之间的互联互通、资源共享；\n（四）引导信息资源的开发利用，促进信息技术的推广应用；\n（五）组织开展信息化知识和技能的宣传、普及，提高信息化技术的应用能力；\n（六）对本行政区域内信息化发展中出现的重大问题进行综合协调；\n（七）负责本行政区域内信息化指标的收集、整理和汇总工作。\n其他有关部门应当按照职责分工负责信息化发展的相关工作。\n第六条 县级以上人民政府应当建立信息化专家咨询制度。信息化的规划编制、标准制定、重要决策和重大项目建设，应当经过专家论证，听取专家意见。\n第七条 单位和个人从事信息化工程建设、信息技术推广应用、信息资源开发利用和信息安全保障等活动，应当执行国家和省有关信息化的标准和规范。\n第八条 单位和个人应当按照国家信息化指标体系的统一规定，及时准确地提供信息化统计资料，接受统计调查和统计监督。","level":1},{"name":"第二章 信息化发展规划与建设","text":"第九条 县级以上人民政府信息化主管部门应当会同有关部门，根据上级信息化发展规划和本行政区域国民经济和社会发展规划，编制本行政区域信息化发展规划，报本级人民政府批准后公布实施。\n根据国家通信网、计算机网、广播电视网三网融合及资源整合的原则，县级以上人民政府信息化主管部门会同通信管理、广播电视、住房和城乡建设等主管部门，结合本级信息化发展规划，编制本行政区域公共信息基础设施建设规划，并纳入本行政区域城乡规划。\n其他有关部门应当根据本行政区域信息化发展规划，编制本系统、本部门的信息化发展专项规划，报本级人民政府信息化主管部门备案。\n新建、改建、扩建公共信息基础设施，应当符合规划要求，并与相关的公共信息基础设施互联互通。\n第十条 县级以上人民政府应当及时公布信息化发展规划及其执行情况，接受社会监督。\n经批准的信息化发展规划不得擅自调整。因经济和社会发展确需变更的，应当经原批准机关批准。\n第十一条 县级以上人民政府应当加强对信息化工程的统筹规划和监督管理。\n使用或者部分使用财政性资金建设的信息化工程项目，有关部门在审批或者核准前，应当会同同级信息化主管部门，按照国家和省信息化发展规划、技术标准和规范、信息安全保障和信息资源共享的要求进行审查。\n非财政性资金投资建设的重大公共基础性信息化工程或者信息安全工程项目，建设单位在依法办理相应手续后，应当报信息化主管部门备案。\n第十二条 信息化工程建设依法实行项目法人负责制、招投标制、工程监理制、竣工验收制和质量负责制。\n第十三条 信息化工程项目竣工后，应当提供专业技术机构的技术验收测试报告，并按照国家和省有关规定进行验收；信息化主管部门应当对使用或者部分使用财政性资金投资建设的信息化工程项目竣工验收工作进行指导、监督。\n第十四条 使用或者部分使用财政性资金投资建设的信息化工程项目，应当进行绩效评估，并将评估结果作为信息化工作绩效评估和经费保障的重要依据。具体评估办法由省人民政府制定。\n第十五条 实行信息化工程质量保修制度。承揽信息化工程的单位应当对信息化工程承担保修责任。\n信息化工程的保修期，自工程竣工验收合格之日起不得少于三年。","level":1},{"name":"第三章 信息产业发展","text":"第十六条 县级以上人民政府应当根据信息化发展需要，制定相关政策措施，完善信息产业投资机制，培育和发展信息技术转让和知识产权交易市场；鼓励境内外企业、个人和其他组织投资信息产业。\n县级以上人民政府信息化主管部门应当定期公布信息产业关键技术和产品指南，引导和支持信息产业发展。\n第十七条 县级以上人民政府应当鼓励和引导企业增加信息技术开发和应用的投入，对具有自主知识产权的信息技术和信息产品给予重点扶持。\n软件企业、集成电路设计企业、信息服务企业及其所提供的软件产品和服务，按照国家和省有关规定认定后，依法享受税收减免等优惠政策。\n第十八条 县级以上人民政府及其相关部门应当支持电子信息设备销售和租赁、电子信息传输服务、计算机软件和系统集成服务、网络服务等信息服务业的发展，引导信息服务业拓宽服务领域，优化信息服务业结构，规范和管理信息服务业的经营活动。\n第十九条 设计、制造电子信息产品，应当按照相关行业标准采用资源利用率高、易回收处理、有利于环境保护的材料、技术和工艺，严格控制和限制电子信息产品中含有毒、有害物质或者元素的使用。","level":1},{"name":"第四章 信息技术推广应用","text":"第二十条 省人民政府信息化主管部门应当定期向社会公布具有自主知识产权的电子信息产品及软件产品目录。\n鼓励公众在信息化工程建设采购活动中，优先选择具有自主知识产权的电子信息产品及软件产品。\n第二十一条 县级以上人民政府信息化主管部门应当建立健全信息技术推广应用体系，组织编制信息技术推广应用指南，明确推广应用目标和重点领域，并组织实施重点推广应用项目。\n第二十二条 国家机关应当加强电子政务建设，推进信息技术在机关办公、社会管理、公共服务等方面的应用，提高管理、服务的能力和水平。\n县级以上人民政府信息化主管部门应当积极推进全省统一的电子政务网络体系建设，促进电子政务网络的纵向和横向间的互联互通。\n电子政务网络应当充分利用已有网络资源，避免重复建设。国家机关的各类应用系统，凡不宜通过互联网实现的，应当依托全省统一的电子政务网络平台；除特殊需要外，不得新建专用网络，已经建成的专用网络，应当按照规划和标准整合接入全省统一的电子政务网络。\n第二十三条 县级以上人民政府应当统筹城乡信息化发展，加大公共财政投入，支持农村信息基础设施和综合信息平台的建设及运行维护；鼓励通过信息化手段为农民提供生产生活实用信息服务，开发、利用和整合涉农信息资源，开展面向农民的信息化知识和技能培训。\n县级以上人民政府信息化主管部门应当加强对农村信息化基础设施、信息服务平台、信息服务体系建设的指导和协调。\n第二十四条 县级以上人民政府应当制定具体政策和措施，扶持和引导社区信息化建设，构建社区信息平台，改善基层社区服务。\n科技、教育、文化、医疗卫生、广播电视、新闻出版、社会保障、金融保险和公用事业等社会公共服务单位，应当根据本行业实际，逐步扩大信息技术应用领域，及时、准确、全面地提供与生产生活相关的信息服务。\n第二十五条 县级以上人民政府及有关部门应当大力促进信息化与工业化的融合，支持建设为企业信息化服务的公共服务平台，鼓励企业在设计、开发、生产、经营和管理等各方面推广应用信息技术，改造和提升传统产业，节约能源、降低消耗、减少污染物排放，促进企业技术进步、产品升级和效益提升。\n第二十六条 县级以上人民政府应当采取措施，推进电子商务的发展，运用信息技术建立和完善信用服务、安全认证、标准规范、在线支付和现代物流等体系，提升电子商务应用和服务水平。\n第二十七条 鼓励各类学校和社会力量开展信息技术教育培训，培养信息化专业人才。从事信息化教育培训活动的，应当具备国家和省规定的条件，有关部门应当加强监督管理。","level":1},{"name":"第五章 信息资源开发利用","text":"第二十八条 省人民政府信息化主管部门应当会同有关部门，制定和完善省信息资源开发标准和目录体系，引导和规范信息资源的合理开发利用。\n第二十九条 省人民政府信息化主管部门按照资源共享、协同服务的原则，组织、协调有关部门建设全省统一的人口、法人、自然资源和空间地理、宏观经济等重大公共基础数据库，有关部门应当给予必要的支持。公共基础数据库的建设和使用按照国家和省有关规定执行。\n国家机关和有关社会公共服务单位应当充分利用公共基础数据库，建设本行业、本部门的业务信息资源库及应用系统。\n有关部门和单位应当向公共基础数据库提供有关信息资源，公共基础数据库的建设和管理单位应当为国家机关无偿提供信息共享服务。\n第三十条 政府信息资源应当向社会公开，除法律、法规和规章另有规定外，有关单位应当在信息发生或者变更后20日内在政府公共信息网上发布，供单位和个人无偿查询。\n第三十一条 国家机关应当利用统一的电子政务网络平台和信息安全基础设施，建立健全政务信息交换机制，实现互联互通和资源共享。\n第三十二条 信息资源开发利用应当保守国家秘密，保护知识产权和个人隐私。\n公民、法人和其他组织有权向开发利用其信息的单位和个人了解相关情况，对不实的信息，有权要求修改或者清除。","level":1},{"name":"第六章 信息安全保障","text":"第三十三条 县级以上人民政府应当加强对信息安全保障工作的领导，建立信息安全应急处理协调机制，提高信息系统的安全防御能力和处理信息安全突发事件的能力。\n信息化、公安、国家安全、保密、密码管理、通信管理等部门应当按照国家和省有关规定，在各自职责范围内做好信息安全保障工作。存储过国家秘密信息或者商业秘密的计算机及其相关的配套设备、设施不再使用的，应当按照国家有关规定销毁。\n信息网络和信息系统的运行单位或者主管部门，应当建立信息安全保障工作责任制，制定本单位信息安全保护措施。\n第三十四条 信息系统建设、使用、管理，应当遵守国家有关安全、保密规定。\n信息安全防护设施应当与信息系统工程同步规划、同步设计、同步建设、同步验收、同步运行。\n信息安全防护设施建设投入占信息系统工程总投入的比例，不得低于国家和省规定的比例。\n第三十五条 实行信息系统安全等级保护和安全风险评估制度。\n信息系统的主管部门和运营、使用单位应当按照国家信息安全等级保护管理规范和技术标准，确定信息系统的安全保护等级，并进行相应的安全系统建设和安全风险评估。\n国家机关和有关社会公共服务单位的重要信息系统在投入使用前，应当由有关主管部门认可的信息安全测评机构对其进行安全性测评，测评合格的方可投入使用。测评机构应当对测评结果负责。\n第三十六条 县级以上人民政府信息化主管部门应当统筹规划，并会同有关部门建立信息安全处理协调机制、应急救援服务体系和信息安全通报制度。\n信息网络和信息系统的运行单位或者主管部门，应当制定信息安全应急处置预案，增强信息网络和信息系统的抗毁能力、灾难恢复能力。\n发生信息安全事故的单位和个人，应当按照有关规定及时向信息化主管部门、公安机关等部门报告，有关部门应当按照规定及时处理。\n第三十七条 任何单位和个人不得利用信息系统从事危害国家安全，损害国家利益、社会公共利益以及公民、法人或者其他组织的合法权益的活动；不得散布、传播违法信息；不得危害信息系统的安全。\n网络信息服务提供者发布的信息应当合法、真实，不得制作、复制、发布、传播含有法律、法规禁止内容的信息。\n信息网络和信息系统的运行单位或者主管部门，应当建立和完善信息安全监控系统，加强对信息内容的安全监管，防止违法信息的传播。","level":1},{"name":"第七章 法律责任","text":"第三十八条 违反本条例规定，法律、行政法规有行政处罚规定的，从其规定；造成人身财产损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第三十九条 违反本条例第二十九条第三款规定，有关部门和单位未提供信息资源和信息共享服务的，由县级以上人民政府信息化主管部门责令改正；拒不改正的，予以通报；对负有直接责任的主管人员和其他直接责任人员由有关部门依法给予处分。\n第四十条 信息化主管部门及其他有关部门的工作人员在信息化监督管理工作中有徇私舞弊、滥用职权、玩忽职守行为的，由有关部门依法给予处分。","level":1},{"name":"第八章 附则","text":"第四十一条 本条例所称信息化，是指充分利用信息技术，开发利用信息资源，促进信息交流和知识共享，提高经济增长质量，推动经济社会发展转型的历史进程。\n第四十二条 本条例自2009年10月1日起施行。","level":1}]},{"id":"h0142","sections":[{"name":"第一章 总 则","text":"第一条 为了规范本省各级人民代表大会常务委员会（以下简称人大常委会）人事任免工作，保障其依法行使人事任免权，根据《中华人民共和国地方各级人民代表大会和地方各级人民政府组织法》、《中华人民共和国监察法》、《中华人民共和国人民法院组织法》、《中华人民共和国人民检察院组织法》等有关法律及规定，结合本省实际，制定本条例。\n第二条 本省各级人大常委会任免本级人民代表大会及其常务委员会、人民政府、监察委员会、人民法院、人民检察院等国家机关的有关工作人员，适用本条例。\n第三条 本省各级人大常委会任免国家机关工作人员，应当坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚持党的领导、人民当家作主、依法治国有机统一，贯彻新时代党的组织路线和干部工作方针政策，坚持党管干部原则，充分发扬民主，严格依法办事。\n第四条 本省各级人民代表大会及其常务委员会的人事任免工作机构（以下简称人事任免工作机构）负责人事任免具体工作。","level":1},{"name":"第二章 任免范围","text":"","level":1},{"name":"第一节 人民代表大会及其常务委员会有关人员的任免","text":"第五条 根据本级人大常委会主任会议（以下简称主任会议）提名，任免以下人员职务：\n（一）人大常委会代表资格审查委员会主任委员、副主任委员、委员；\n（二）人大常委会工作委员会主任、副主任、委员；\n（三）人大常委会特定问题调查委员会主任委员、副主任委员、委员；\n（四）人大常委会副秘书长；\n（五）其他应当由人大常委会任免的人员。\n根据县（市、区）人大常委会主任会议的提名，任免本级人大常委会设立在街道的工作委员会主任、副主任、委员。\n在本级人民代表大会闭会期间，根据主任会议提名，任免本级人民代表大会专门委员会（以下简称专门委员会）的个别副主任委员、部分委员。\n第六条 在本级人民代表大会闭会期间，受理人大常委会组成人员、专门委员会组成人员书面提出的辞职请求，并决定是否接受辞职。决定接受辞职后，报本级人民代表大会备案。\n第七条 人大常委会主任因故不能工作或者缺位的时候，根据主任会议提名，由本级人大常委会在副主任中推选一名代理主任。\n人大常委会秘书长因故不能工作或者缺位的时候，根据主任会议提名，由本级人大常委会在人大常委会组成人员中推选一名代理秘书长。\n代理主任、代理秘书长的职务，直到主任、秘书长恢复工作或者人民代表大会下一次会议选出新的主任、秘书长为止。\n第八条 人大常委会组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务；如果担任上述职务，必须书面向本级人大常委会辞去人大常委会的职务。","level":2},{"name":"第二节 人民政府组成人员的任免","text":"第九条 在本级人民代表大会闭会期间，根据省长、市长、州长、县长、区长的提名，决定副省长、副市长、副州长、副县长、副区长的个别任免。\n第十条 根据省长、市长、州长、县长、区长的提名，决定本级人民政府秘书长、厅长、局长、委员会主任等组成人员的任免，由本级人民政府报上一级人民政府备案。\n第十一条 在本级人民代表大会闭会期间，受理本级人民政府领导人员书面提出的辞职请求，并决定是否接受辞职。决定接受辞职后，报本级人民代表大会备案。\n第十二条 在本级人民代表大会闭会期间，根据本级人民政府、主任会议或者人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以决定撤销本级人民政府个别副职领导人员和由本级人大常委会任命的本级人民政府其他组成人员的职务。\n第十三条 在本级人民代表大会闭会期间，省长、市长、州长、县长、区长因故不能担任职务的时候，根据主任会议提名，由本级人大常委会从本级人民政府副职领导人员中决定一名代理人选；如果代理人选不是副职领导人员，应当先决定任命其为副职领导人员，再决定其代理正职。","level":2},{"name":"第三节 监察委员会组成人员的任免","text":"第十四条 根据本级监察委员会主任提名，任免监察委员会副主任、委员。\n第十五条 在本级人民代表大会闭会期间，受理本级监察委员会主任书面提出的辞职请求，并决定是否接受辞职。决定接受辞职后，报本级人民代表大会备案。\n第十六条 在本级人民代表大会闭会期间，根据本级监察委员会、主任会议或者人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以撤销由本级人大常委会任命的监察委员会副主任、委员的职务。\n第十七条 在本级人民代表大会闭会期间，监察委员会主任因故不能担任职务的时候，根据主任会议提名，从本级监察委员会副主任中决定一名代理主任；如果代理人选不是副主任，应当先决定任命其为副主任，再决定其为代理主任。","level":2},{"name":"第四节 人民法院审判人员的任免","text":"第十八条 根据本级人民法院院长提名，任免人民法院副院长、审判委员会委员、庭长、副庭长、审判员。\n根据省人大常委会主任会议提名，决定任免有关专门人民法院、省高级人民法院直属中级法院院长。\n根据省高级人民法院院长提名，任免有关专门人民法院、省高级人民法院直属中级法院的副院长、审判委员会委员、庭长、副庭长、审判员。\n根据本级人民法院院长提名，任免其直属基层法院院长、副院长、审判委员会委员、庭长、副庭长、审判员。\n第十九条 在本级人民代表大会闭会期间，受理本级人民法院院长书面提出的辞职请求，并决定是否接受辞职。决定接受辞职后，报本级人民代表大会备案。\n第二十条 在本级人民代表大会闭会期间，根据主任会议提名，决定撤换本级人民法院院长，并依法报请上级人大常委会批准。\n第二十一条 在本级人民代表大会闭会期间，根据本级人民法院、主任会议或者人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以撤销由本级人大常委会任命的人民法院副院长、审判委员会委员、庭长、副庭长、审判员的职务。\n根据省高级人民法院、省人大常委会主任会议或者省人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以撤销有关专门人民法院、省高级人民法院直属中级法院的院长、副院长、审判委员会委员、庭长、副庭长、审判员的职务。\n根据本级人民法院、主任会议或者人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以撤销本级人民法院直属基层法院院长、副院长、审判委员会委员、庭长、副庭长、审判员的职务。\n第二十二条 在本级人民代表大会闭会期间，人民法院院长因故不能担任职务的时候，根据主任会议提名，从本级人民法院副院长中决定一名代理院长；如果代理人选不是副院长，应当先决定任命其为副院长，再决定其为代理院长。","level":2},{"name":"第五节 人民检察院检察人员的任免","text":"第二十三条 根据本级人民检察院检察长提名，任免人民检察院副检察长、检察委员会委员、检察员。\n根据省人民检察院检察长提名，决定任免省人民检察院分院检察长；任免省人民检察院分院副检察长、检察委员会委员、检察员。\n根据省、市（州）人民检察院检察长提名，任免其派出基层检察院检察长、副检察长、检察委员会委员、检察员。\n第二十四条 根据本级人民检察院检察长提名，批准任免下一级人民检察院检察长。\n第二十五条 在本级人民代表大会闭会期间，受理本级人民检察院检察长书面提出的辞职请求，并决定是否接受辞职。决定接受辞职后，由本级人民检察院报经上一级人民检察院检察长提请该级人大常委会批准，并由本级人大常委会报人民代表大会备案。\n第二十六条 在本级人民代表大会闭会期间，根据本级人民检察院、主任会议或者人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以撤销由本级人大常委会任命的人民检察院副检察长、检察委员会委员、检察员的职务。\n根据省人民检察院、省人大常委会主任会议或者省人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以撤销省人民检察院分院检察长、副检察长、检察委员会委员、检察员的职务。\n根据本级人民检察院、主任会议或者人大常委会五分之一以上组成人员书面联名依法提出的撤职案，可以撤销本级人民检察院派出基层检察院检察长、副检察长、检察委员会委员、检察员的职务。\n第二十七条 根据省人民检察院检察长的建议，省人大常委会可以撤换下级人民检察院检察长、副检察长、检察委员会委员。\n第二十八条 在本级人民代表大会闭会期间，人民检察院检察长因故不能担任职务的时候，根据主任会议提名，从本级人民检察院副检察长中决定一名代理检察长；如果代理人选不是副检察长，应当先决定任命其为副检察长，再决定其为代理检察长。决定代理检察长后，由本级人民检察院报经上一级人民检察院报该级人大常委会备案。","level":2},{"name":"第三章 任免程序","text":"第二十九条 提请人大常委会任免国家机关工作人员，应当向本级人大常委会书面提出人事任免议案。\n提请任命的，应当附有拟任命人员的简历及德、能、勤、绩、廉方面的情况、提名理由、任前公示情况或者其他需要说明的材料。\n提请免职或者撤职的，应当附有免职或者撤职理由等材料。\n提请任命人民政府新设或者改变名称部门的厅长、局长、委员会主任等组成人员时，应当附有批准设立该机构或者改变机构名称的文件。\n第三十条 人事任免议案应当在本级人大常委会举行会议的十日以前送达人大常委会。因特殊情况不能按期送达的，应当向主任会议作出说明，由主任会议决定是否提请人大常委会会议审议。\n第三十一条 省人大常委会对拟任命的省人民代表大会及其常务委员会有关人员，省人民政府秘书长、厅长、委员会主任等组成人员，省监察委员会副主任、委员，人民法院审判人员，人民检察院检察人员进行法律知识考试，由人事任免工作机构负责组织。市（州）、县（市、区）人大常委会对拟任命人员进行法律知识考试，由人事任免工作机构或者会同人大常委会其他有关工作机构负责组织。\n考试成绩应当向人大常委会报告，考试成绩五年内有效。\n第三十二条 人事任免工作机构审查人事任免议案，听取提请机关或者有关部门负责人介绍相关人选的情况；根据主任会议授权，必要时，可以组织到提请机关了解拟任命人员任职资格、条件及任前公示等有关情况。\n第三十三条 主任会议审议人事任免议案，听取提请机关或者有关部门负责人介绍相关人选的情况，人事任免工作机构报告对人事任免议案的审查情况。\n第三十四条 人大常委会举行会议前，应当将人事任免议案印发人大常委会组成人员。\n经主任会议决定，人事任免工作机构将审查情况向人大常委会会议报告或者将审查报告印发人大常委会组成人员。\n第三十五条 人大常委会会议审议人事任免议案前，听取提请机关或者有关部门负责人介绍相关人选的情况。\n人大常委会举行会议时，拟任命的本级人民政府副职领导人员、秘书长、厅长、局长、委员会主任等组成人员，人民法院副院长、人民检察院副检察长；有关专门人民法院、省高级人民法院直属中级法院院长，省人民检察院分院检察长等应当到会作拟任职发言。\n第三十六条 人大常委会会议审议人事任免议案时，提请机关或者有关部门应当派人列席会议，听取审议意见，回答询问。\n审议人事任免议案时，发现可能存在影响拟任命人员任命的重要问题的，主任会议可以决定暂缓提请表决，交有关机关调查、提出报告，再由主任会议决定是否再次提请人大常委会会议审议。\n第三十七条 列入人大常委会会议议程的人事任免议案，在提请表决前，提请机关要求撤回的，经主任会议同意，对该任免议案的审议即行终止。\n第三十八条 人大常委会五分之一以上的组成人员书面联名依法提出的撤职案，由主任会议决定是否提请人大常委会会议审议；或者由主任会议提议，经全体会议决定，组织调查委员会，由以后的人大常委会会议根据调查委员会的报告审议决定。\n第三十九条 撤职案在提请表决前，被提出撤职的人员有权在人大常委会会议上提出申辩意见，或者书面提出申辩意见，由主任会议决定印发人大常委会组成人员。\n第四十条 人大常委会会议表决人事任免事项应当采取逐人表决的方式。\n通过新的一届人大常委会代表资格审查委员会、工作委员会的组成人员，采取合并表决的方式。任免人民法院庭长、副庭长、审判员，有关专门人民法院、省高级人民法院直属中级法院的副院长、审判委员会委员、庭长、副庭长、审判员，直属基层法院院长、副院长、审判委员会委员、庭长、副庭长、审判员；人民检察院检察员，省人民检察院分院副检察长、检察委员会委员、检察员，派出基层检察院检察长、副检察长、检察委员会委员、检察员等职务，审议时人大常委会组成人员意见比较一致的，可以对同一任免案合并表决。\n拟任免人员同时被提请任职和免职时，应当先行任职表决，再行免职表决。对同一职务的任免，应当先行免职表决，再行任职表决。\n表决采取电子表决或者无记名投票的方式进行，可以赞成，可以反对，也可以弃权。任免案以人大常委会全体组成人员的过半数通过，表决结果由人大常委会会议主持人当场宣布。\n第四十一条 人大常委会对其任命的以下国家机关工作人员，颁发由人大常委会主任签署的任命书，主任缺位时加盖人大常委会公章：\n（一）人民政府副省长、副市（州）长、副县（市、区）长，秘书长、厅长、局长、委员会主任等组成人员；\n（二）监察委员会副主任、委员；\n（三）人民法院副院长、有关专门人民法院院长、省高级人民法院直属中级法院院长，以及其他审判人员；\n（四）人民检察院副检察长、省人民检察院分院检察长，以及其他检察人员；\n（五）其他由人大常委会任命的人员。\n对前款第（一）项至第（四）项所列人员，一般当场颁发任命书；对第（三）项中的其他审判人员，第（四）项中的其他检察人员，以及第（五）项所列人员，可以当场颁发任命书，也可以委托人事任免工作机构或者提请机关颁发任命书。\n第四十二条 拟任命人员在人大常委会会议上未获通过的，根据工作需要和任职条件，可以再提请人大常委会另一次会议任命，仍未获通过的，不得再提名为同一职务的人选。\n第四十三条 人大常委会任命的国家机关工作人员，在依照法定程序产生后，公开进行宪法宣誓。\n第四十四条 应当由人大常委会任免的国家机关工作人员，在人大常委会通过任职前，不得对外公布。\n人大常委会通过人事任免事项后，应当及时行文通知提请机关，提请机关接到任免通知后，应当及时通知任免人员到职或者离职。任免本级人民代表大会及其常务委员会有关人员不行文通知。\n人事任免议案通过后，由人大常委会以决定或者任免名单等方式在本级主要新闻媒体、人大常委会公报以及人大网站上公布。\n第四十五条 换届时，新的一届人民政府领导人员选举产生后，应当在两个月内提请人大常委会决定任命本级人民政府秘书长、厅长、局长、委员会主任等组成人员；人大常委会代表资格审查委员会和工作委员会的组成人员，有关专门人民法院院长、省高级人民法院直属中级法院院长，省人民检察院分院检察长，应当在新的一届人大常委会第一次或者第二次会议上任命；对不再担任原职务的人员不再提请免职。\n除前款规定外，由人大常委会任命的其他国家机关工作人员，职务无变动的，不再重新任命。\n第四十六条 由人大常委会任命的国家机关工作人员，因机构撤销、合并的，其职务由原提请机关注销并报本级人大常委会备案；任职期间去世的，其职务自行终止，由原提请机关报本级人大常委会备案。\n第四十七条 按规定程序报请批准新设立或者改变名称的人民政府部门的厅长、局长、委员会主任，由本级人大常委会按本条例有关规定决定任命。\n第四十八条 本级人民政府秘书长、厅长、局长、委员会主任等组成人员出缺时，省长、市长、州长、县长、区长一般在四个月内提请本级人大常委会决定任命人选，由本级人民政府报上一级人民政府备案。\n第四十九条 在人民代表大会闭会期间，人大常委会组成人员、专门委员会组成人员的代表资格被终止的，其人大常委会组成人员、专门委员会组成人员的职务相应终止，由本级人大常委会予以公告。\n人大常委会代表资格审查委员会组成人员，因代表资格被终止或者其他原因不再担任人大常委会组成人员职务的，其人大常委会代表资格审查委员会组成人员的职务相应终止，由本级人大常委会予以公告。\n人大常委会特定问题调查委员会组成人员的职务，随调查任务完成自行终止。","level":1},{"name":"第四章 监 督","text":"第五十条 人大常委会任命的国家机关工作人员，应当严格遵守宪法、法律、法规，认真执行人民代表大会及其常务委员会作出的决议、决定，自觉接受其监督。\n第五十一条 人大常委会通过听取和审议专项工作报告、执法检查、专题询问、专题调研等方式，依法对其任命的国家机关工作人员履职情况进行监督。\n第五十二条 人大常委会受理公民、法人和其他组织对其任命的国家机关工作人员的检举和控告，交由有关部门调查处理，有关部门应当将调查处理情况及时报告人大常委会。\n第五十三条 人大常委会任命的国家机关工作人员受到政务处分的，提请机关应当及时向本级人大常委会报备。","level":1},{"name":"第五章 附 则","text":"第五十四条 本条例自2009年12月1日起施行。1994年1月25日湖北省第八届人民代表大会常务委员会第五次会议通过、2003年11月29日湖北省第十届人民代表大会常务委员会第六次会议修订、2006年12月1日湖北省第十届人民代表大会常务委员会第二十四次会议修正的《湖北省人民代表大会常务委员会任免地方国家机关工作人员办法》同时废止。","level":1}]},{"id":"h0143","sections":[{"name":"第一章 总则","text":"第一条 为了促进和规范农村扶贫工作，加快贫困地区经济、社会、文化、生态建设，提高贫困地区人民生活水平，缩小城乡和区域发展差距，促进经济社会全面、协调、可持续发展，根据本省实际，制定本条例。\n第二条 本省行政区域内的农村扶贫活动适用本条例。\n本条例所称农村扶贫，是指各级人民政府通过资金、物资、教育、科技、文化、卫生、人才、社会保障等方面的支持，帮助农村贫困地区科学合理开发利用自然资源、人力资源，改善生存与发展环境，提高农村贫困人口综合素质和自我发展能力的扶持活动。\n第三条 农村扶贫应当坚持创新、协调、绿色、开放、共享的发展理念，坚持政府主导、群众主体、精准扶贫、因地制宜的原则，实现开发式、开放式、救济式扶贫相结合，农村扶贫与资源保护、生态建设相结合，增强贫困地区和贫困人口自我发展能力。\n第四条 农村扶贫工作应当将国务院和省人民政府确定的重点区域列为扶贫重点范围。\n贫困标准和农村扶贫范围由省人民政府确定和调整。","level":1},{"name":"第二章 政府责任与社会参与","text":"第五条 建立和完善省负总责、市州主导、县抓落实、乡镇实施的农村扶贫工作机制和激励约束机制。\n实行农村扶贫目标责任制和考核评价制度，将农村扶贫政策落实情况及目标任务完成情况作为各级人民政府和相关部门及其负责人考核评价的重要内容。\n第六条 县级以上人民政府扶贫开发主管部门负责本行政区域内的农村扶贫综合管理工作，其主要职责是：\n（一）拟定农村扶贫中长期发展规划和年度工作计划；\n（二）建立农村扶贫项目库，督促实施农村扶贫项目；\n（三）会同财政部门拟定财政扶贫资金分配计划和检查监督扶贫资金使用情况；\n（四）协调、督促农村扶贫相关政策措施的落实；\n（五）协助组织开展社会扶贫活动；\n（六）承担农村扶贫的其他相关工作。\n政府有关部门应当按照各自职责，做好农村扶贫工作。\n第七条 县级以上人民政府应当把农村扶贫纳入本行政区域经济和社会发展战略及中长期发展规划，并制定专项农村扶贫规划。\n政府各有关部门制定行业发展规划时，应当与本行政区域专项农村扶贫规划相衔接，统筹、优先安排贫困地区建设项目。\n第八条 省人民政府应当将财政扶贫投入纳入财政预算，逐年增加。\n各级财政应当坚持将农村扶贫开发作为优先保障重点，积极调整和优化财政支出结构，建立与本地区经济发展水平相适应的财政扶贫投入增长机制。省级财政扶贫投入应当按照国家扶贫投入的百分之四十至百分之五十配套安排。\n在脱贫攻坚期内，省、市（州）和有关县（市）分别按照当年地方财政收入增量的百分之十五增列专项扶贫预算，各级财政当年清理回收可统筹使用的存量资金中百分之五十以上用于农村扶贫。\n第九条 省人民政府及有关部门应当协助做好争取国家机关定点帮扶和发达地区对口支持等工作，组织实施帮扶和协作项目。\n第十条 县级以上人民政府应当明确有关部门的扶贫对象、扶贫任务和扶贫目标，建立扶贫对口帮扶制度。有关部门应当发挥各自优势，组织资金、项目、人才、技术，帮助对口帮扶县（市、区）、乡（镇）、村发展经济和社会事业。\n第十一条 县级以上人民政府及其扶贫开发主管部门应当建立扶贫信息平台，并按照国家和省规定的标准、程序，对贫困地区和贫困人口进行精准识别、建档立卡，实行动态管理。建立脱贫认定机制，保证脱贫的地区和人口在一定时期内继续享受扶贫相关政策。\n县级以上人民政府应当建立贫困监测和扶贫统计制度。统计部门负责贫困监测工作，扶贫开发主管部门负责统计扶贫项目、扶贫资金等事项。有关地方、单位和个人应当如实提供数据和资料。\n第十二条 鼓励支持企业事业单位、社会团体和个人到贫困地区参与经济建设，兴办教育、科技、文化、卫生、体育、社会福利等社会事业，从事科技推广、法律服务、人才引进、人员培训、劳务输出、进出口贸易等活动。\n支持扶贫基金会、老区建设促进会、扶贫开发协会以及其他组织和志愿者依法开展扶贫济困活动。\n鼓励社会各界和海内外人士向贫困地区捐赠资金、物资以及提供其他扶持。企业捐资、捐物参与农村扶贫，按照有关法律法规规定享受税收优惠。\n第十三条 县级以上人民政府应当完善贫困地区科技服务体系，加大技术创新引导资金对科技扶贫的支持，促进先进适用技术成果在贫困地区的转化。\n鼓励教育、科技、卫生人员定期到贫困地区服务，鼓励大专院校、科研院所、医疗机构为贫困地区培养人才，鼓励大、中专毕业生到贫困地区就业创业。\n第十四条 鼓励开展扶贫领域的国际交流与合作，引进境外资金参与农村扶贫。\n第十五条 鼓励和引导各类金融机构创新金融产品和服务方式，加大对扶贫开发的金融支持。\n推进实施扶贫再贷款，支持贫困地区县级统筹财政资金建立扶贫贷款风险补偿机制，开展扶贫小额信贷，发展普惠金融，扩大农业保险覆盖面。\n第十六条 县级以上人民政府应当对在农村扶贫工作中做出突出成绩的单位和个人，予以表彰和奖励。","level":1},{"name":"第三章 扶贫内容与主要途径","text":"第十七条 县级以上人民政府应当发展县域经济，建设现代农业，培育龙头企业，发展农村电子商务，兴办特色农产品加工业和乡村旅游业，多渠道转移贫困人口就业，提高贫困地区和贫困人口的收入水平。\n大力支持贫困地区发展村级集体经济、农民专业合作社和农民专业户规模经济。\n第十八条 农村扶贫应当坚持突出重点，整合资源，分类指导，将整村整乡（镇）、整县（市、区）推进与区域发展、连片开发相结合，将农村扶贫与新农村建设相结合，统筹解决不同类型贫困区域的脱贫致富问题。\n第十九条 县级以上人民政府应当积极支持贫困地区充分利用当地优势资源，集中力量扶持优势产业，制定优惠政策吸引外来资本投资贫困地区，参与经营，实施产业化扶贫。\n在不改变用途的情况下，利用财政专项扶贫资金或者其他涉农资金形成的资产，可以折股量化分配给所在贫困地区的贫困村和贫困户。\n鼓励农民专业合作社和企业通过土地经营权流转、土地托管和牲畜托养等方式，带动贫困户增加经济收入。\n第二十条 省人民政府应当加强贫困地区的农业综合开发、高效农田建设、土地整治、低丘岗地改造、低效林改造和高效经济林建设。\n第二十一条 加强贫困地区生态保护，建立和完善重点生态功能区转移支付制度及地区间生态补偿制度。因地制宜实施扶贫移民和生态移民，对生态保护重点地区、生存条件恶劣地区、地质灾害严重地区实行易地开发、搬迁扶贫。合理调整贫困地区基本农田保有指标，贫困地区的城乡建设用地增减挂钩指标可以在全省范围内使用。\n第二十二条 切实加强贫困地区劳动力职业技能培训和就业指导，组织引导贫困地区农村富余劳动力有序转移，关心、帮助解决贫困地区农民工的实际困难。\n第二十三条 县级以上人民政府应当加强贫困地区交通、水利、电力、通信、教育、科技、文化、卫生、广播电视、体育等基础设施建设，帮助解决行路、饮水、上学、就医、用电、听广播、看电视电影等困难和问题。\n第二十四条 加强贫困地区和贫困人口的基础教育和职业教育，制定和完善教育资助制度，确保贫困人口受教育权利，提高贫困人口文化教育水平。对贫困户子女实施免费高中教育和学杂费、基本生活费全免的职业教育。完善贫困户大学生学费减免和助学机制。\n建立和完善城市教师到贫困地区支教、任教制度。\n第二十五条 县级以上人民政府应当加强贫困地区医疗卫生基础设施和机构建设，制定和完善贫困地区医疗卫生人才引进和培训制度，建立城市医疗卫生人员支援贫困地区制度。提高参加新型农村合作医疗贫困人口医疗费用报销水平，完善大病医疗保障和疾病应急救助制度，建立重特大疾病保障机制。实施健康扶贫工程，加强贫困地区传染病、地方病、慢性病防治工作。\n第二十六条 省人民政府及其相关部门应当完善贫困地区教师、医疗卫生人员和农业技术人员聘用及职称评审政策，对长期在贫困地区服务的教师、医疗卫生人员和农业技术人员在职称晋升、聘用中给予倾斜；每年安排专项资金用于贫困地区乡村教师、乡村卫生院（室）的医疗卫生人员和农业技术人员的继续教育和实用技术培训。\n第二十七条 省人民政府应当加强贫困地区农村文化和体育的组织、设施、队伍建设，实施文化、体育扶贫工程。\n县级以上人民政府应当筹集资金，用于贫困地区图书馆、文化馆、体育活动中心等场所建设和历史文化遗迹的维护。\n第二十八条 加强贫困地区的人口与计划生育工作，推进优生优育工作，提高出生人口素质。\n第二十九条 完善与农村扶贫制度相衔接的农村养老保险、医疗保险、最低生活保障和五保供养等社会保障制度，建立低保标准、五保标准自然调整机制，实现扶贫标准与低保标准协调一致。对因灾因病等陷入暂时性贫困人口提供救济救助；对没有劳动能力、丧失劳动能力或者共同生活的家庭成员人均收入低于当地最低生活保障标准的贫困人口提供最低生活保障。\n第三十条 建立、完善自然灾害的监测和防控体系，加强应急救援、卫生防疫、转移安置等防灾减灾知识普及、技能培训和设施建设，提高贫困地区防灾减灾能力。\n第三十一条 县级以上人民政府应当将农村扶贫与农村基层组织建设相结合，实施农村人才培养计划，增强农村基层组织带领村民自力更生、脱贫致富的能力。","level":1},{"name":"第四章 扶贫项目与资金管理","text":"第三十二条 扶贫项目和资金管理应当遵循县为单位、整合资源、集中使用、规范审批、提高效益的原则。\n建立扶贫投入县级整合机制，资金项目审批权限下放到贫困县。在扶贫规划内，贫困县可以统筹整合使用专项扶贫资金、农业生产发展和农村基础设施建设等相关涉农资金及社会帮扶资金。\n教育、科技、文化、卫生等社会事业方面资金，应当结合扶贫任务和贫困人口变化情况，完善资金安排使用机制，精准有效使用。\n第三十三条 扶贫项目由建设单位依据农村扶贫规划和相关规定提出申请；重大扶贫项目立项应当提供立项申请报告、项目可行性研究报告和其他相关材料。\n到村到户扶贫项目的立项、设计、实施，应当征求扶持对象的意见，保障扶持对象的选择权和监督权。\n第三十四条 扶贫项目立项实行分级分类审批。县级以上人民政府扶贫项目主管部门按照各自的审批权限，分类审批扶贫项目，报省扶贫项目主管部门备案。\n第三十五条 各级扶贫项目主管部门建立扶贫项目库，组织有关部门编制年度扶贫项目建设计划，年度扶贫项目主要从扶贫项目库中择优选择。\n国家计划投资的开发项目符合贫困地区条件的，应当向贫困地区倾斜。\n年度扶贫项目建设计划批准后不得随意变更；确需变更的，报原批准部门审批。\n第三十六条 扶贫项目建设按照有关规定实行项目责任制、合同管理制、项目监理制、竣工验收制、项目档案登记制、项目政务公开制等，并依法进行环境影响评价。\n扶贫项目符合政府采购和招投标要求的，应当按照规定实行政府采购和招投标。\n第三十七条 项目建设单位负责扶贫项目的组织实施，实施扶贫项目前应当编制项目实施方案，建立项目档案。扶贫项目工程建成后，应当确定工程管护主体，明确管护责任。\n扶贫项目主管部门负责扶贫项目的监督管理。扶贫项目建设完成后，项目审批部门应当组织项目验收。\n第三十八条 扶贫资金主要包括财政扶贫资金、扶贫贴息贷款和以工代赈资金，以及有关部门筹集、社会捐赠的扶贫资金等，应当按照下列用途安排：\n（一）财政扶贫资金和有关部门筹集的资金重点用于贫困地区生产生活条件改善、扶贫产业发展、人力资源开发、扶贫移民；\n（二）扶贫贴息贷款重点用于扶贫龙头企业、农民专业合作组织和农户发展扶贫产业；\n（三）以工代赈资金重点用于贫困地区农村的基础设施建设；\n（四）社会捐赠扶贫资金按照捐赠者的意愿使用。\n各种扶贫资金不得用于规定以外的地区，不得用于地方其他建设，不得用于与扶贫无关的项目。\n贫困地区城乡建设用地异地增减挂钩增加的土地收益，应当全部用于本地扶贫。\n第三十九条 财政扶贫资金主要依据贫困地区自然条件、基础设施状况、贫困村和贫困人口数量、地方财政收入、农民人均收入、资金使用效益等因素进行分配。\n第四十条 中央财政扶贫资金的项目管理费按照国家规定提取；地方财政扶贫资金的项目管理费按照百分之一点五提取。项目管理费主要用于扶贫项目管理工作。\n第四十一条 各级财政部门应当设立财政扶贫资金专户，扶贫项目建设单位应当设立财政扶贫资金专账；财政扶贫资金应当实行县级财政报账制管理。\n财政扶贫资金实行专户管理，专款专用、国库支付、项目直达，任何单位和个人不得截留、挤占、挪用、套取。\n第四十二条 建立扶贫资金绩效考评机制，财政、扶贫开发主管部门会同有关部门对财政扶贫资金绩效进行考核评价。具体考评办法由省财政部门会同省扶贫开发主管部门共同制定。\n财政扶贫资金绩效考评的主要内容包括农村扶贫成果、财政扶贫资金管理情况以及财政扶贫资金预算安排和执行情况。\n第四十三条 财政、扶贫开发和其他扶贫项目主管部门依法对扶贫资金管理使用情况进行监督检查；审计部门依法对扶贫资金的分配、使用情况进行审计监督，对统筹整合使用的扶贫资金，应当根据其所在地县（市）决定进行审计监督。\n第四十四条 扶贫资金分配及使用情况、扶贫项目计划及实施情况应当向社会公示。扶贫项目主管部门应当公开受理电话和电子信箱，接受社会监督、咨询。公示内容包括：项目名称、实施单位及责任人、建设内容、建设地点、投资规模、完成时间及财政扶贫资金数额等。\n第四十五条 贫困村村民会议、村民代表会议和村民有权对本村扶贫资金使用情况及资金使用效益进行监督，行使知情权、选择权、民主决策权、参与实施权。\n第四十六条 对农村扶贫工作中的违法行为或者不依法履行职责的行为，任何单位和个人有权举报。对举报反映的问题，经查属实的，依法依规查处；经查不属实的，及时澄清，消除负面影响。\n第四十七条 建立农村扶贫工作容错免责机制。对农村扶贫工作中因市场变化或者不可抗力等因素导致未达到预期效果，但已经勤勉尽责并且未牟取私利的，主管机关或者上级主管部门不追究有关人员的责任。\n第四十八条 各级人民代表大会常务委员会应当适时听取和审议同级人民政府农村扶贫的专项工作报告，将农村扶贫工作作为监督检查的重要内容。","level":1},{"name":"第五章 法律责任","text":"第四十九条 违反本条例第三十五条第三款、第三十八条、第四十一条规定的，责令改正，由财政、审计、监察等部门依照国家有关规定处罚；情节严重的，其主要负责人应当引咎辞职；构成犯罪的，依法追究刑事责任。\n第五十条 国家工作人员在农村扶贫工作中滥用职权、玩忽职守、徇私舞弊的，给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第五十一条 本条例自2010年2月1日起施行。1996年11月12日湖北省第八届人民代表大会常务委员会第二十三次会议通过的《湖北省扶贫条例》同时废止。","level":1}]},{"id":"h0144","sections":[{"name":"","text":"（2010年5月27日湖北省第十一届人民代表大会常务委员会第十六次会议通过 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2020年6月3日湖北省第十三届人民代表大会常务委员会第十六次会议《关于集中修改、废止涉及取消证明事项的部分省本级地方性法规的决定》第三次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了促进就业，促进经济发展与扩大就业相协调，促进社会和谐稳定，根据《中华人民共和国就业促进法》和有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内各级人民政府、用人单位、劳动者、公共就业服务机构、职业中介机构和其他组织进行的与就业有关的活动，适用本条例。\n第三条 就业是民生之本，把扩大就业放在经济社会发展的突出位置，实施积极的就业政策，坚持政府促进就业、劳动者自主择业、市场调节就业的方针，以创业带动就业，多渠道扩大就业。\n第四条 劳动者依法享有平等就业、自主择业和获得就业帮助的权利。\n倡导劳动者树立正确的就业观念，提高就业能力和创业能力；鼓励劳动者自主创业、自谋职业。\n引导用人单位树立正确的用人观念，实行合理的用人标准，为劳动者就业创造良好环境。\n第五条 县级以上人民政府应当将扩大就业作为促进经济社会发展、改善民生的优先目标，纳入国民经济和社会发展规划，并制定促进就业的中长期规划和年度工作计划，创造就业条件，改善创业环境，加强失业调控，稳定和扩大就业。\n各级人民政府应当统筹做好高校（中专）毕业生等城镇新增劳动力、农村劳动力转移、失业人员和就业困难人员就业工作。\n第六条 各级人民政府应当建立促进就业工作目标责任制度，对所属有关部门和下级人民政府落实促进就业政策、开展促进就业工作情况进行考核、评估和监督检查，将高校（中专）毕业生等城镇新增劳动力就业、农村劳动力转移就业、失业人员和就业困难人员就业、创业带动就业、控制失业率作为考核的重要指标。\n各级人民政府及其有关部门对在促进就业工作中作出显著成绩的单位和个人，给予表彰和奖励。\n第七条 县级以上人民政府建立有关方面参加的促进就业工作联席会议制度，完善促进就业工作协调机制，协调解决就业工作中的重大问题。\n县级以上人民政府人力资源和社会保障部门具体负责本行政区域内的促进就业工作，其他有关部门按照各自的职责分工，共同做好促进就业工作。\n工会、共产主义青年团、妇女联合会、残疾人联合会、工商业联合会以及其他社会组织，协助人民政府开展促进就业工作，依法维护劳动者的合法权益。\n第八条 县级以上人民政府人力资源和社会保障部门应当对本条例实施情况进行监督检查，建立完善举报制度，及时受理对违反本条例行为的举报，并核实处理。","level":1},{"name":"第二章 就业促进","text":"第九条 各级人民政府应当落实国家有关发展劳动密集型产业和服务业的政策措施，扶持中小企业发展，鼓励、支持各类企业通过兴办产业或者拓展经营，多渠道、多方式增加就业岗位。\n第十条 县级以上人民政府安排政府投资和确定重大建设项目，应当将增加就业岗位作为评价项目的重要指标纳入评估制度，发挥投资和重大建设项目对就业的带动作用。\n第十一条 县级以上人民政府应当实行有利于促进就业的财政政策，根据就业状况和就业工作目标，在每年财政预算中安排一定比例资金作为就业专项资金，并逐年增加。具体比例由省人民政府规定。\n就业专项资金主要用于下列项目：\n（一）职业介绍、职业培训、创业培训、职业技能鉴定、公益性岗位、社会保险等补贴以及就业困难人员一次性创业补贴；\n（二）小额贷款担保基金、小额担保贷款贴息及代偿损失；\n（三）特定就业政策补助；\n（四）驻外劳务服务工作补助；\n（五）就业困难人员培训期间生活补助；\n（六）扶持公共就业服务；\n（七）对充分就业社区的奖励；\n（八）省人民政府批准促进就业的其他支出。\n就业专项资金必须专款专用，任何单位和个人不得截留、侵占和挪用。审计、财政部门应当依法对就业专项资金的使用和管理情况进行监督检查。具体管理办法由省人民政府制定。\n第十二条 鼓励企业增加就业岗位，扶持失业人员和残疾人就业。对下列企业、人员依法给予税收优惠：\n（一）吸纳符合国家规定条件的失业人员就业并达到规定要求的企业；\n（二）失业人员创办的中小企业；\n（三）安置残疾人达到规定比例或者集中使用残疾人的企业；\n（四）从事个体经营的符合国家规定条件的失业人员；\n（五）从事个体经营的残疾人；\n（六）国家和省规定给予税收优惠的其他企业、人员。\n前款第（四）项、第（五）项规定的人员，市场监督管理、卫生健康、住房和城乡建设、民政、自然资源等有关部门应当在经营条件、经营场地、经营环境等方面给予照顾，免除管理类、证照类、登记类等各类行政事业性费用。\n第十三条 县级以上人民政府应当制定、落实高校毕业生就业政策，拓宽就业渠道，加强就业服务，鼓励、引导其树立正确的就业观念和自主创业、自谋职业；高校应当结合就业市场和学科建设需求，合理设置专业，调整招生计划，为毕业生就业创造有利条件。\n鼓励高校毕业生到城乡基层、中小企业和非公有制企业就业。高校毕业生到城乡基层、中小企业和非公有制企业就业的，按照国家、省规定享受社会保险补贴、公益性岗位补贴、学费及助学贷款代偿、研究生招考、户籍迁移等优惠政策。国家机关录用公务员、事业单位招聘工作人员，应当按照国家、省有关规定优先录用有基层工作经历的高校毕业生。\n鼓励承担国家和地方重大科研项目的单位聘用高校毕业生参与研究，其劳务性费用和有关社会保险费补助按照国家有关规定从项目经费中列支。国有企业、事业单位应当发挥带动作用，积极吸纳高校毕业生就业。\n第十四条 各级人民政府应当统筹城乡就业，积极推进小城镇建设，发展乡镇企业，壮大县域经济，采取就地就近转移就业和劳动力输出相结合的方式，引导农村劳动力转移就业；在制定小城镇规划时，应当将本地区农村劳动力转移就业作为重要内容，同步规划、统筹安排。\n改善农村劳动者进城就业环境，完善其户籍迁移、子女就学、公共卫生、住房租购、工资支付保障和社会保险等方面政策措施，支持督促企业改善用工环境，保障其合法权益，为农村劳动者就业创造条件。\n建立被征地农民的就业保障制度，从土地出让收益中安排适当数量的资金，扶持被征地农民就业。因土地征收而直接受益的企业，应当提供适当岗位优先安排被征地农民就业。\n第十五条 各级人民政府应当完善和实施与非全日制、临时性、季节性等灵活就业相适应的劳动关系调整、工资支付和社会保险等政策，为灵活就业人员提供帮助和服务。\n第十六条 县级以上人民政府建立失业预警制度。根据失业率、长期失业者比例、失业平均周期等情况，确立失业预警线，制定应急预案，完善应急措施，明确应急责任，对可能出现的较大规模失业，实施预防、调节和控制。\n第十七条 县级以上人民政府应当健全完善失业保险制度，合理安排失业保险基金的用途，发挥失业保险保障基本生活、预防失业和促进就业的功能。具体办法由省人民政府制定。","level":1},{"name":"第三章 创业扶持","text":"第十八条 各级人民政府应当将扶持创业作为促进就业的重要措施，优化创业环境，落实优惠政策，简化办事程序，提高服务质量，鼓励、支持和帮助劳动者自主创业。\n第十九条 县级以上人民政府应当建立小额贷款担保服务体系，设立小额贷款担保基金，并根据需要积极扩大基金规模，为创业人员、劳动密集型中小企业提供贷款担保。\n建立小额贷款担保风险补偿机制，推行信用社区和联户担保等多种担保方式，为防范贷款担保风险、促进担保机构降低反担保条件或者取消反担保提供必要保障。\n建立小额担保贷款激励机制，对提供小额担保贷款，促进创业业绩突出的担保机构、金融机构、信用社区等给予工作经费补助。\n第二十条 存入社会保险基金和担保基金的金融机构，应当落实国家有关促进就业的金融政策，承办小额担保贷款业务，并按照存入担保基金额度的五倍发放贷款。\n担保机构、金融机构应当实行联合会审制度，对符合放贷条件的借款人，简化贷款手续，在收到贷款申请之日起的十五日内发放贷款。\n借款人按期归还贷款后再次申请贷款的，担保机构应当提供担保，金融机构应当根据其生产经营需要发放贷款，适当提高贷款额度，并在贷款期限、利率上给予优惠。\n劳动密集型中小企业吸纳失业人员达到规定比例的，金融机构应当按照国家规定的额度给予贷款支持，财政部门按照国家和省的规定给予贴息扶持。\n第二十一条 县级以上人民政府及其有关部门应当合理设置资金、人员、经营场所等行业准入标准，放宽出资方式、出资额和出资期限等条件，降低创业者市场准入门槛。\n创业者申请办理个体工商户、创办合伙企业或者个人独资企业登记，不受出资额限制。\n创业者在法律、法规允许的范围内，可以将家庭住所、租借房、临时商业用房等作为创业经营场所，将能有效利用的同一地址登记为多家企业或者个体工商户的经营场所。\n第二十二条 各级人民政府及其相关部门应当根据鼓励创业的需要，规划、建设或者划定适宜创业者经营的场所；鼓励经济技术开发区、工业园区、高新技术园区、大学科技园区、农业科技园开辟创业基地。对在政府投资兴建的创业基地内创业的，免收三年场租费用。\n第二十三条 失业人员在领取失业保险金期间创办个体、私营企业的，可以按规定一次性领取应享受期限的失业保险金。\n享受城市居民最低生活保障的人员创业后，其家庭月人均收入在当地城市居民最低生活保障标准一点五倍以内的，继续按原标准享受城市居民最低生活保障一年。\n对就业困难人员自主创业的，可以按规定从就业专项资金中给予一次性创业补贴。","level":1},{"name":"第四章 就业援助","text":"第二十四条 各级人民政府应当建立健全面向所有就业困难群体的就业援助制度，采取税费减免、贷款贴息、社会保险补贴、岗位补贴等办法，通过公益性岗位安置等途径，对就业困难人员实施优先扶持和重点帮助。\n落实零就业家庭就业援助制度，确保零就业家庭至少有一人实现就业。采取特别扶助措施，促进残疾人就业；用人单位应当按照国家规定安排残疾人就业。\n做好就业援助制度与失业保险制度、最低生活保障制度和最低工资制度之间的衔接，鼓励和引导就业援助对象积极主动就业。\n第二十五条 就业困难人员包括：\n（一）女性年满四十周岁或者男性年满五十周岁的失业人员；\n（二）连续失业一年以上的人员；\n（三）失地农民；\n（四）城镇零就业家庭成员或者享受城镇居民最低生活保障的人员；\n（五）农村零转移就业贫困家庭成员；\n（六）毕业一年以上未就业的高校毕业生；\n（七）残疾人；\n（八）各级社会福利机构供养的成年孤儿和社会成年孤儿。\n县级以上人民政府可以根据本地实际情况扩大援助范围。\n第二十六条 就业困难人员可以向住所地乡镇、街道、社区公共就业服务机构申请就业援助。乡镇、街道、社区公共就业服务机构应当对辖区内就业援助对象进行核实后，予以登记，建立专门台账，实行就业援助对象动态管理和援助责任制度，提供及时、有效的就业援助。\n第二十七条 鼓励各类用人单位招用就业困难人员。\n用人单位招用就业困难人员，签订劳动合同并缴纳社会保险费的，可以按规定享受社会保险补贴。招用就业困难人员达到规定条件的劳动密集型中小企业，可以申请小额担保贷款和享受贴息政策。\n公益性岗位安置就业困难人员的，可以按规定在一定期限内享受社会保险补贴和岗位补贴；就业困难人员灵活就业后申报就业并缴纳社会保险费的，可以按规定享受社会保险补贴。\n第二十八条 公益性岗位主要包括：\n（一）政府购买的基层社会管理类岗位；\n（二）乡镇、街道和社区开发的基层公共服务类岗位；\n（三）国家机关、事业单位、社会团体编制以外的后勤服务岗位；\n（四）独立工矿区为企业和社会提供的服务岗位；\n（五）政府开发的适合就业困难人员就业的其他岗位。\n各级人民政府应当采取多种形式，开发公益性岗位。政府投资开发的公益性岗位，应当优先安置符合岗位要求的就业困难人员。鼓励机关、企业事业单位等面向社会提供各类后勤服务岗位，安置就业困难人员。\n第二十九条 各级人民政府在资源开采型城市和独立工矿区发展与市场需求相适应的产业，有关部门应当采取区域协作、劳务输出、移民搬迁等措施，引导劳动者转移就业。\n对因资源枯竭或者经济结构调整、大中型水库建设等原因造成就业困难人员集中的地区，上级人民政府及其有关部门应当给予必要的帮助和扶持。","level":1},{"name":"第五章 公平就业","text":"第三十条 各级人民政府应当建立健全劳动者平等就业制度，优化公平就业的环境，消除就业歧视，保障公民平等就业权利。\n用人单位不得以民族、种族、性别、宗教信仰、户籍、婚姻状况、体貌等为由拒绝招用能够满足生产工作需要并具有同等工作能力的人员。\n公共就业服务机构、职业中介机构不得为用人单位提供歧视性就业服务。\n用人单位、广告经营者或者发布者、公共就业服务机构、职业中介机构发布招聘信息或者广告，不得有就业歧视性内容。\n第三十一条 用人单位招用人员，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。\n各民族劳动者享有平等的劳动权利。用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。\n各级人民政府应当统筹规划，为残疾人创造就业条件，保障残疾人的劳动权利不受侵害。\n第三十二条 用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定的传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国家卫生健康部门规定禁止从事的易使传染病扩散的工作。\n除法律、行政法规和国家卫生健康部门规定禁止乙肝病原携带者从事的工作外，用人单位招用人员，不得在就业体检中要求开展乙肝项目检测，不得要求提供乙肝项目检测报告，医疗卫生机构不得在就业体检中提供乙肝项目检测服务。\n第三十三条 农村劳动者进城就业享有与城镇劳动者平等的劳动权利，任何组织、个人不得对农村劳动者进城就业设置歧视性限制，不得对农村劳动者有就业歧视行为。","level":1},{"name":"第六章 公共就业服务","text":"第三十四条 省人民政府应当制定覆盖城乡的全省公共就业服务体系发展规划，建立健全统一、开放、便捷、高效的公共就业服务体系。\n县级以上人民政府应当设立公共就业服务机构，配备必要的工作人员，将公共就业服务经费纳入本级财政预算；加强乡村、街道、社区基层公共就业服务平台建设，整合、充实基层公共就业服务机构、人员、岗位，保障和改善工作条件，提升基层公共就业服务的能力和水平。\n县级以上人民政府人力资源和社会保障部门应当加强对基层公共就业服务工作的指导、服务，帮助解决其工作中的实际困难。省人民政府对基层公共就业服务平台建设给予一次性专项资助。\n第三十五条 县级以上人民政府应当加强公共就业服务信息网络及相关设施建设，实现省、市、县、街道（乡镇）、社区五级公共就业服务机构信息联网，保证公共就业服务信息互联互通、资源共享。\n第三十六条 公共就业服务机构建立综合性服务场所，开设服务窗口，集中为劳动者和用人单位提供一站式服务。\n公共就业服务机构应当按照国家制定的服务规范和标准，公开服务制度，完善服务功能，拓展服务项目，优化服务环境，为劳动者和用人单位提供优质高效服务。\n第三十七条 公共就业服务机构免费为劳动者提供下列就业服务：\n（一）就业政策法规咨询；\n（二）发布职业供求、职业培训、市场工资指导价位等人力资源市场信息；\n（三）职业指导、职业介绍、创业指导；\n（四）对就业援助对象实施就业援助；\n（五）办理就业登记、失业登记等事务；\n（六）其他公共就业服务。\n公共就业服务机构不得从事经营性活动。\n各级人民政府和有关部门、公共就业服务机构举办的招聘会不得向劳动者收取费用。\n第三十八条 全省实行统一的就业失业登记制度。\n公共就业服务机构负责就业登记和失业登记工作，建立专门台账，及时、准确记录劳动者就业与失业变动情况，并做好相应统计工作。\n就业失业登记证由省人民政府人力资源和社会保障部门统一制作，免费向劳动者发放。\n第三十九条 用人单位招用劳动者、终止或者解除与劳动者的劳动关系，应当到当地公共就业服务机构为劳动者办理登记手续。用人单位招用人员后，应当自招用之日起三十日内办理登记手续；用人单位终止或者解除与劳动者的劳动关系后，应当自终止或者解除劳动关系之日起十五日内办理登记手续。\n劳动者从事个体经营或者灵活就业的，由本人在乡镇、街道、社区公共就业服务机构办理就业登记手续。\n第四十条 在法定劳动年龄内，有劳动能力、有就业需求、处于无业状态的城镇常住人员，可以到公共就业服务机构进行失业登记。其中，没有就业经历的城镇户籍人员以及毕业后未能就业的各类学校毕业生，在户籍所在地登记；进城就业的农村劳动者和其他非本地户籍人员在常住地稳定就业满六个月的，失业后可以在常住地登记。\n劳动者进行失业登记时，应当如实提供身份证件、就业经历等相关信息。\n公共就业服务机构在办理失业登记时，应当向劳动者提供相关的公共就业服务、就业扶持政策咨询。\n第四十一条 县级以上人民政府应当建立、完善人力资源和就业、失业状况调查统计制度，开展人力资源和就业、失业状况的调查统计和分析研究，及时准确掌握人力资源市场状况。调查统计数据应当真实可靠，并定期公布。","level":1},{"name":"第七章 人力资源市场","text":"第四十二条 县级以上人民政府应当加强人力资源市场建设，培育和完善统一开放、竞争有序的城乡一体化人力资源市场，鼓励社会各方面依法开展就业服务，规范用人单位招聘、劳务派遣，劳动者求职，职业中介机构从事职业中介等行为。\n第四十三条 县级以上人民政府人力资源和社会保障部门应当完善人力资源市场信息发布制度，通过媒体、网络、宣传栏等多种形式向社会发布职业供求、市场工资指导价位、职业培训、人力资源分析等信息，为劳动者求职、用人单位招用人员、培训机构开展培训提供及时、准确的信息服务。\n第四十四条 劳动者求职，应当如实向公共就业服务机构、职业中介机构或者用人单位提供个人基本情况以及相关知识技能、工作经历、求职愿望等情况。\n用人单位招用人员，应当如实告知劳动者有关工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬、福利待遇和社会保险等情况以及劳动者要求了解的其他情况，依法保障劳动者的合法权益。\n第四十五条 县级以上人民政府及其人力资源和社会保障、市场监督管理等有关部门应当加强对职业中介机构的管理和服务，规范职业中介机构行为，引导其提高服务质量，发挥其促进就业的作用。\n设立职业中介机构，应当在市场监督管理部门办理登记后，向人力资源和社会保障部门申请行政许可。未经登记和许可，不得从事职业中介活动。\n各级人民政府及其人力资源和社会保障等有关部门不得创办或者与他人联合创办经营性的职业中介机构。\n第四十六条 职业中介机构开展业务活动，应当遵循合法、诚实信用、公平、公开的原则。\n职业中介机构应当在服务场所醒目位置放置许可证、营业执照等证件，标明服务项目、收费标准，公示从业人员姓名、照片等信息，公布投诉举报电话，并建立服务台账，记录服务对象、服务过程、服务结果和收费情况。\n县级以上人民政府对提供公益性就业服务的职业中介机构，应当按照规定给予补贴。\n第四十七条 职业中介机构不得有下列行为：\n（一）提供虚假就业信息；\n（二）为无合法证照的用人单位提供职业中介服务；\n（三）伪造、涂改、转让职业中介许可证；\n（四）扣押劳动者的居民身份证和其他证件，或者向劳动者收取押金；\n（五）介绍未满十六周岁的未成年人就业；\n（六）违规收取职业中介费用；\n（七）发布的就业信息中包含歧视性内容；\n（八）介绍劳动者从事法律、法规禁止从事的职业；\n（九）以暴力、胁迫、欺诈等方式进行职业中介活动；\n（十）其他违反法律、法规规定的行为。","level":1},{"name":"第八章 职业教育和培训","text":"第四十八条 县级以上人民政府应当大力发展职业教育和职业培训，建立健全职业教育、培训体系，完善政府、用人单位和个人共同负担的投入机制，鼓励和扶持企业事业单位和社会各界兴办职业教育、培训事业，促进劳动者提高职业技能，增强就业能力和创业能力。\n根据不同地区、不同行业的发展特点，统筹、整合各类职业教育、培训资源，重点扶持富有特色、适应市场、就业效果好的职业教育、培训机构，充分发挥其示范带动作用。\n第四十九条 企业应当依法加强职业教育和培训，突出职工的实际操作技能训练和劳动保护教育。\n企业应当根据国家有关规定，按照职工工资总额的百分之一点五至百分之二点五提取职工教育培训经费，专门用于职业技能培训和继续教育培训，其经费的提取和使用，向职工代表大会或者职工大会报告，并接受人力资源和社会保障部门、工会的监督。企业人数较少，不能自行组织所属职工开展职业培训的，可以委托具备相应条件的职业学校或者职业培训机构进行培训。\n鼓励和支持职业学校、职业培训机构与企业建立产教结合的培训机制，采取订单培训、定向培养等方式，为企业培养实用人才和熟练劳动者。\n第五十条 各级人民政府应当组织和引导失业人员、农村劳动者参加技能培训、创业培训，鼓励各类培训机构为失业人员和农村劳动者提供就业技能培训、创业培训，增强其就业能力和创业能力。失业人员和农村劳动者参加技能培训、创业培训的，按照有关规定享受政府培训补贴。\n完善职业培训补贴制度，规范培训机构的培训活动，建立健全培训补贴与培训质量、促进就业效果等挂钩考评机制，以及培训补贴使用的监督管理机制。享受职业培训补贴的，其培训机构由有关部门采取公开招标等方式确定。\n第五十一条 县级以上人民政府建立健全劳动预备制度。对有就业要求的初高中毕业生实行一定期限的职业教育和培训，使其取得相应的职业资格或者掌握一定的职业技能。劳动预备制度的教育培训期限，根据培训对象和岗位需求等情况确定。\n县级以上人民政府应当建立、完善职业教育的奖励、助学制度，对职业教育的在校学生给予奖学金、助学金、助学贷款及减免学费等帮助。\n第五十二条 县级以上人民政府应当制定优惠政策，鼓励企业事业单位接收高等院校、职业学校和职业培训机构的学生实习，并提供实习场所和实习指导教师；鼓励企业选派有实际经验的人员到高等院校、职业学校和职业培训机构担任实训教师，增强学生的实际操作能力。国有企业、事业单位应当在接受学生实习方面发挥示范作用。\n高等院校和职业学校应当完善实习制度，扩大实习基地范围，组织学生实习；开设就业指导课程，提高学生的求职能力。\n第五十三条 县级以上人民政府建立健全高校毕业生就业见习制度，组织离校未就业的高校毕业生到企业见习，提高其就业能力。对接收高校毕业生见习的用人单位按照规定给予见习岗位补贴。\n用人单位接收就业见习的高校毕业生，应当为其提供必要的工作生活条件，并按照规定发放基本生活补助。鼓励见习单位优先录用见习高校毕业生。\n第五十四条 县级以上人民政府应当加强公共就业实训基地和高技能人才培养示范基地建设，改善培训条件，提升培训质量，面向社会开展职业技能操作训练和职业技能鉴定服务。\n第五十五条 县级以上人民政府应当加强职业能力评价体系建设，对从事涉及公共安全、人身健康、生命财产安全等特殊工种的劳动者，依法实行职业资格证书制度，完善职业技能鉴定质量督导监管机制，确保职业技能鉴定质量。\n就业困难人员、进城就业的农村劳动者通过初次职业技能鉴定并取得职业资格证书的，按照有关规定给予一次性职业技能鉴定补贴。","level":1},{"name":"第九章 法律责任","text":"第五十六条 违反本条例规定，法律、行政法规有处罚规定的，从其规定。\n第五十七条 违反本条例第三十二条第二款规定，对用人单位由县级以上人民政府人力资源和社会保障部门责令改正，并处以一千元以上五千元以下的罚款，情节严重的，处以五千元以上一万元以下的罚款；对医疗卫生机构由县级以上人民政府卫生健康部门责令改正，给予通报批评；对当事人造成损害的，应当承担赔偿责任。\n第五十八条 违反本条例第四十七条第（六）项至第（十）项规定的，由县级以上人民政府人力资源和社会保障部门责令改正，没收违法所得，并处二千元以上一万元以下罚款，情节严重的，处一万元以上五万元以下罚款；对当事人造成损害的，承担赔偿责任。\n第五十九条 违反本条例第五十条第二款规定，培训机构采取虚报培训人数或者培训时间等手段套取政府培训补贴的，由县级以上人民政府人力资源和社会保障等部门责令退回，并处所套取培训补贴数额一至三倍的罚款；情节严重的，五年内不得参加享受政府培训补贴的招标。\n第六十条 各级人民政府、有关部门和单位及其工作人员违反本条例规定，有下列情形之一的，由其所在单位或者上级主管机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）不履行促进就业工作职责或者不落实就业扶持政策措施的；\n（二）虚报促进就业考核指标的；\n（三）截留、侵占、挪用就业专项资金的；\n（四）对劳动者实施就业歧视的；\n（五）对投诉举报故意推诿、拖延或者对侵犯劳动者就业权益的违法行为不予查处的；\n（六）其他滥用职权、玩忽职守、徇私舞弊的行为。","level":1},{"name":"第十章 附则","text":"第六十一条 本条例自2010年8月1日起施行。","level":1}]},{"id":"h0145","sections":[{"name":"","text":"（2010年7月30日湖北省第十一届人民代表大会常务委员会第十七次会议通过 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了促进农村可再生能源的开发利用和建设管理，保护和改善生态环境，推进社会主义新农村建设，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例所称农村可再生能源，是指农村生产生活所使用的生物质能（沼气及其他生物质燃气、秸秆、薪柴、生物炭等）、太阳能、风能等非化石能源。\n第三条 在本省行政区域内从事农村可再生能源开发利用及建设管理等活动，适用本条例。\n第四条 开发利用农村可再生能源应当坚持因地制宜、多能互补、综合利用、讲求效益和节约与开发并举的方针，遵循政府扶持、市场引导、群众自愿、社会参与的原则。\n农村可再生能源的开发利用应当与新农村建设、生态农业、生态环境保护、卫生防疫（血防）等相结合，发挥综合效益。\n第五条 县级以上人民政府应当加强领导，统筹规划，将农村可再生能源开发利用纳入国民经济和社会发展规划，与节能减排的总体要求相适应，作为优先发展的产业，制定相应的优惠政策和保障措施，加大对农村可再生能源开发利用和建设管理的投入，提高利用效率，促进农村可再生能源事业的可持续发展。\n第六条 农村可再生能源开发利用和建设的管理工作由县级以上人民政府农业农村主管部门具体负责，其他相关行政主管部门按照各自的职责，做好农村可再生能源开发利用管理工作。\n乡镇人民政府应当确定专职或者兼职人员，协助做好农村可再生能源开发利用管理工作。\n第七条 各级人民政府及其有关部门应当宣传开发利用和节约农村可再生能源知识，普及农村可再生能源应用技术；对在农村可再生能源开发利用工作中做出显著成绩的单位和个人给予表彰奖励。","level":1},{"name":"第二章 开发与推广应用","text":"第八条 各级人民政府应当鼓励支持科研单位、大专院校、企业和其他组织、个人，以多种形式开展农村可再生能源新技术、新产品的研究开发和科技成果转化；安排专项资金，用于支持农村可再生能源新技术、新产品的研究开发以及农村可再生能源开发利用示范工程的建设。\n鼓励开展秸秆沼气发酵、生物质热解气化、沼气进出料、沼肥综合利用等技术研究及其成套设备的开发。\n第九条 自主开发或者引进的农村可再生能源新技术，应当在推广地区经过试验证明具有先进性、适用性和安全性。\n引进国外新技术和新产品的，应当符合国家有关规定。\n第十条 鼓励科技人员依照国家有关规定通过技术转让、技术入股、技术咨询与服务等形式，加快农村可再生能源科技成果转化。\n第十一条 县级以上人民政府应当将农村可再生能源技术推广纳入农业技术推广体系。\n农业农村主管部门应当根据实际情况因地制宜地推广下列农村可再生能源技术与设备：\n（一）户用沼气及其综合利用、大中型沼气集中供气和生活污水厌氧净化等技术与设备；\n（二）秸秆气化、固化、炭化技术与设备；\n（三）太阳能、风能利用技术与设备；\n（四）省柴节能炉灶、炒茶灶、取暖设施等节能技术与设备；\n（五）其他先进适用的农村可再生能源技术及配套设备。\n第十二条 各级人民政府应当引导和支持乡镇兴建沼气净化工程，将户用沼气建设与改厨、改厕、改圈相结合，纳入村镇建设规划，分类指导，整体推进。\n鼓励企业和个人利用规模化养殖场的有机废弃物，建设沼气集中供气（发电）工程。\n农业农村主管部门应当组织沼气生产单位和个人对沼渣、沼液实行综合利用，发展无公害、绿色和有机农产品。\n第十三条 各级人民政府应当加强对秸秆能源化、太阳能、风能开发利用的指导。\n鼓励企业和个人兴建秸秆气化集中供气工程。农村新建或者改建、扩建公益性公共设施，具备条件的应当采用太阳能供水供热等技术和设备。农村居民住宅利用太阳能供水供热的，农业农村、住房和城乡建设等主管部门应当在规划、安装、使用和通用设计方案方面给予指导和帮助。","level":1},{"name":"第三章 政府扶持与服务","text":"第十四条 农业农村主管部门应当根据当地农村可再生能源资源、用能结构、用能水平和经济社会发展现状，科学制定农村可再生能源开发利用规划和计划，按照规定程序报同级人民政府批准后实施。\n第十五条 县级以上人民政府应当把开发利用农村可再生能源所需资金列入本级财政预算，并根据农村可再生能源发展需要逐步增加。\n对国家和省下达的农村可再生能源利用项目，下级人民政府应当按照规定落实配套资金。\n第十六条 各级人民政府及其相关部门应当建立、完善农村可再生能源开发利用和建设管理的相关制度，以提高农村可再生能源项目的使用率为目标，充分发挥农村可再生能源建设项目及资金的使用效益，并对开发利用规划、计划的执行情况和项目、资金的建设使用情况进行考核评价。\n第十七条 利用秸秆气化技术向农村集中供气以及应用秸秆气化、固化技术的项目所购置的设备，按照规定享受国家和省对沼气、农机设备的优惠扶持政策。农村居民住宅利用太阳能供水供热或者购买使用省柴节能炉灶的，按照规定享受国家和省的补贴。\n鼓励金融机构对利用荒山、荒坡或者边际土地发展能源植物，利用农作物秸秆、农业废弃物等生产生物质能的，在信贷资金方面给予优惠。\n第十八条 各级人民政府应当引导和支持农村可再生能源产业化经营，鼓励各种投资主体参与农村可再生能源工程项目建设，支持其开发、生产和经营农村可再生能源设备和产品，并依法保护投资者和生产经营者的合法权益。\n第十九条 农业农村主管部门应当安排专项资金对从事农村可再生能源推广与服务的专业技术人员进行安全知识、职业技能等培训，按照国家有关规定评定相应技术职称，保持专业技术人员队伍相对稳定。\n第二十条 省人民政府农业农村主管部门应当建立和完善农村可再生能源开发利用信息系统，为农村可再生能源生产者、经营者和使用者提供市场供求、新产品及新技术推广、科研成果和农村可再生能源管理等信息服务，并公布农村可再生能源项目建设和资金使用情况。\n第二十一条 农业农村主管部门应当建立和完善乡、镇农村可再生能源利用公益性服务网络，在政策咨询、规划设计、技术指导、安全检查等方面为用户提供便捷、高效的服务。\n加强农村可再生能源利用市场建设，支持组建相应的专业合作经济组织和村级服务网点，开展专业化、规范化服务。鼓励企业或其他组织、个人向农村可再生能源用户提供物资、技术及劳务等方面的社会化服务。","level":1},{"name":"第四章 质量监督与安全管理","text":"第二十二条 农业农村主管部门及其他相关部门应当加强对农村可再生能源开发利用的质量监督和安全管理，制定和完善安全操作规程，建立应急预案。\n第二十三条 农村可再生能源设备和产品的生产应当执行相关的国家标准、行业标准或者地方标准。\n第二十四条 生产涉及生命、财产安全的农村可再生能源设备和产品，应当按照国家规定办理工业产品生产许可证；销售此类产品的，应当按照规定查验设备和产品的生产许可证和编号。\n第二十五条 农业农村主管部门应当引导和督促农村可再生能源设备和产品的生产经营者推广安全可靠的技术、设备和产品，对用户传授安全操作知识，避免造成人身伤害和财产损失。\n农村可再生能源设备和产品的生产经营者，应当对其所生产经营设备和产品的质量负责。禁止生产、销售和使用国家明令淘汰的设备和产品。\n第二十六条 兴建下列农村可再生能源工程，应当由农业农村主管部门会同有关部门审核设计和施工方案：\n（一）单池容积100立方米以上的沼气工程和生活污水厌氧净化工程；\n（二）总装机容量在1千瓦以上50千瓦以下的风力或者太阳能发电工程；\n（三）日供气量300立方米以上的生物质气化工程（供气或者发电）；\n（四）集热面积100平方米以上5000平方米以下的太阳能集中供水供热工程。\n第二十七条 从事农村可再生能源工程施工、设备安装以及维修服务的技术人员，应当按照国家有关规定获得相应资格证书后，方可上岗。\n任何单位不得聘用未获得相应资格证书的人员从事农村可再生能源工程施工、设备安装以及维修服务。\n第二十八条 农业农村主管部门及其他相关部门应当定期组织对农村可再生能源工程、设备和产品的适用性、安全性、可靠性和售后服务状况进行检测、检查，并公布结果。\n从事农村可再生能源开发利用的单位和个人，应当按照要求如实提供有关数据和资料。\n第二十九条 农业农村、市场监督管理部门应当及时受理和查处有关农村可再生能源设备和产品质量的举报和投诉。","level":1},{"name":"第五章 法律责任","text":"第三十条 违反本条例规定，法律、行政法规有处罚规定的，从其规定。\n第三十一条 违反本条例第二十六条规定，设计和施工方案未经审核擅自开工建设的，由农业农村主管部门责令限期改正；逾期不改正的，处以5000元以上3万元以下罚款。\n第三十二条 违反本条例第二十七条规定，聘用未获得相应资格证书的人员从事农村可再生能源工程施工、设备安装以及维修服务的，由农业农村主管部门责令限期改正；逾期不改正的，处以1000元以上5000元以下罚款。\n第三十三条 农业农村主管部门及其他有关部门工作人员在农村可再生能源开发利用管理工作中，滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十四条 本条例自2010年10月1日起施行。","level":1}]},{"id":"h0146","sections":[{"name":"","text":"（2010年12月4日湖北省第十一届人民代表大会常务委员会第十九次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了加强对民用机场的净空保护，保障民用航空安全和人民生命财产安全，根据《中华人民共和国民用航空法》、《民用机场管理条例》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内民用机场的净空区域保护和电磁环境保护，适用本条例。\n第三条 民用机场所在地的县级以上人民政府应当加强民用机场净空安全工作的领导，建立完善民用机场净空安全保护工作责任制和协调机制，研究解决净空安全工作中的重大事项，将民用机场净空安全保护工作纳入本地安全生产责任目标考核体系，督促各有关部门依法履行净空安全监督管理职责。\n民用机场所在地的县级以上人民政府安全生产监督管理部门对民用机场净空安全保护工作实施综合监督管理，对有关部门和下级人民政府的民用机场净空安全保护工作实施指导协调、监督检查。\n民用机场所在地的县级以上人民政府规划、住房和城乡建设、公安、农业、环保、林业、国土资源、气象、无线电管理、工商行政管理等有关部门按照各自职责，做好民用机场净空安全保护工作。\n民用机场管理机构具体负责所属机场的净空安全保护工作。中国民用航空湖北地区空中交通管理部门（以下简称空中交通管理部门）按照职责，参与民用机场净空安全的管理工作。中国民用航空湖北安全监督管理部门（以下简称民航管理部门）对民用机场净空安全保护工作实施行业监督管理。\n第四条 民用机场管理机构应当坚持安全第一、预防为主，建立健全安全生产责任制，制定、完善有关安全生产应急预案，与民用机场所在地的人民政府建立联防机制，共同做好民用机场净空安全保护工作。\n第五条 任何单位和个人应当保护民用机场的净空安全，并有权向安全生产监督管理部门或者其他相关部门举报民用机场净空安全隐患或者危害民用机场净空安全的行为。\n对民用机场净空安全保护负有监督管理职责的部门应当制定并落实监督检查计划，建立举报制度，受理有关民用机场净空安全的举报，并组织调查核实，依法处理；举报事项涉及民用机场净空安全重大问题的，提请同级人民政府协调解决。\n第六条 民航管理部门、民用机场管理机构和民用机场所在地的各级人民政府及其相关部门应当加强民用机场净空安全保护的宣传、教育工作，提高公民对民用机场净空安全保护的意识。\n民用机场所在地的乡镇人民政府、街道办事处、村（居）民委员会应当配合做好辖区内民用机场净空安全保护的宣传、教育等相关工作。","level":1},{"name":"第二章 净空区域保护","text":"第七条 民用机场净空保护区域，是指为保障航空器在机场安全起飞和降落，按照民用机场净空障碍物限制图的要求划设的一定空间范围。\n第八条 民用机场管理机构应当按照国家规定和技术标准编制民用机场净空障碍物限制图，报国务院民用航空行政主管部门批准后，送民用机场所在地的县级以上人民政府规划、国土资源行政主管部门备案。\n第九条 民航管理部门和民用机场所在地的县级以上人民政府，应当按照国家有关规定划定民用机场净空保护区域，将其纳入当地城乡建设规划和土地利用总体规划管理，并向社会公布。\n民用机场新建、扩建前，机场所在地的县级以上人民政府应当在工程动工6个月前发布公告，并在当地主要媒体和周边地区刊登、张贴。对可能影响民用机场净空安全的建筑物及设施、树木、灯光或者其他障碍物，由民用机场所在地的县级以上人民政府或者其委托的相关部门组织障碍物所有者在规定的期限内清除、处理。对此造成的损失，应当依法给予补偿或者采取其他补救措施。\n民用机场新建、扩建公告发布后，任何单位和个人不得在净空保护区域内修建、种植、设置影响民用机场净空安全的障碍物。\n第十条 规划行政主管部门在审批民用机场净空保护区域内的建筑物或者设施项目时，应当书面征求民航管理部门的意见。民航管理部门应当在收到征求意见书之日起15日内作出书面答复。\n第十一条 在民用机场净空保护区域内，禁止下列行为：\n（一）修建超过民用机场净空障碍物限制高度的建筑物或者设施；\n（二）修建靶场、爆炸物仓库等影响飞行安全的建筑物或者设施；\n（三）排放大量烟雾、火焰、粉尘、废气等影响飞行安全的物质；\n（四）设置影响民用机场目视助航设施使用的灯光、标志或者物体；\n（五）种植影响飞行安全或者影响民用机场助航设施使用的植物；\n（六）在机场围界外5米范围内，搭建建筑物或者从事挖掘、堆积物体等影响机场运营安全的活动；\n（七）升放无人驾驶自由气球、系留气球和进行飞艇、热气球、滑翔机、动力伞等飞行活动；\n（八）放飞影响民用航空安全的鸟类动物和升放风筝、孔明灯等物体；\n（九）储存爆炸物品，燃放烟花、爆竹、焰火等；\n（十）进行超过净空保护高度要求的爆破或者作业；\n（十一）焚烧产生大量烟雾的农作物秸秆、工业废料、垃圾等物质；\n（十二）设置易吸引鸟类及其他动物的露天垃圾场、屠宰场、养殖场等场所；\n（十三）其他影响民用机场净空安全的活动。\n第十二条 在民用机场净空保护区域外，可能影响飞行安全的高大建筑物或者其他设施，其所有权人应当在民用机场管理机构的指导下按照国家有关规定设置飞行障碍灯和标志，并保持正常显示状态。\n第十三条 在民用机场净空保护区边界接壤的区域升放无人驾驶自由气球、系留气球的，必须依法经气象主管机构批准。升放无人驾驶自由气球的，还应当在拟升放2日前持气象主管机构的批准文件向当地空中交通管理部门提出升放申请，空中交通管理部门应当在拟升放1日前作出批准或者不予批准的决定，并通知申请人。\n第十四条 在民用机场净空保护区边界接壤的区域升放的无人驾驶自由气球、系留气球发生下列异常情形之一的，升放单位或者个人应当立即向空中交通管理部门和气象主管机构报告：\n（一）无人驾驶自由气球非正常运行的；\n（二）系留气球意外脱离系留的；\n（三）其他可能影响飞行安全的异常情形。\n第十五条 在民用机场净空保护区边界接壤的区域使用飞艇、热气球、滑翔机、动力伞等航空器从事航空飞行的单位或者个人，需要划定临时飞行空域的，应当持有关升空物体的种类、放飞起止时间、放飞高度、活动范围等文字材料，依法向空中交通管理部门提出书面申请；受理部门在收到申请之日起3日内，决定是否予以批准，并书面告知申请人。\n第十六条 在民用机场净空保护区域内，民用机场所在地的各级人民政府应当控制、减少吸引鸟类动物的农作物或者植物的晾晒场。\n第十七条 信鸽协会应当做好协会会员、俱乐部等的管理工作，监督其严格遵守有关规定，在饲养、放飞信鸽和组织竞赛等活动时，不得影响民用机场净空安全。\n第十八条 民航管理部门和民用机场管理机构应当加强对民用机场净空状况的核查。发现影响民用机场净空安全的情况，应当立即制止，并书面报告民用机场所在地的县级以上人民政府及相关部门。接到报告的县级以上人民政府及相关部门应当及时采取有效措施，消除对飞行安全的影响。","level":1},{"name":"第三章 电磁环境保护","text":"第十九条 民用机场电磁环境保护区域，是指为保证民用机场通信设施、设备正常工作而在其周围划定的限制电磁干扰信号和电磁障碍物体的区域。\n第二十条 民用机场所在地的县级以上人民政府无线电管理机构应当会同民航管理部门，按照国家规定和技术标准，划定和调整民用机场电磁环境保护区域，并向社会公布。\n民用机场电磁环境保护区域包括设置在民用机场总体规划区域内的民用航空无线电台（站）电磁环境保护区域和民用机场飞行区电磁环境保护区域。\n第二十一条 民用机场管理机构应当及时将最新的机场电磁环境保护区域报当地人民政府有关部门备案。\n第二十二条 在民用机场电磁环境保护区域内，任何单位或者个人设置的无线电发射设备及产生电磁辐射、反射的设施或者物体，不得妨碍民用航空无线电专用频率的正常使用。\n第二十三条 禁止在民用航空无线电台（站）电磁环境保护区域内，从事下列影响民用机场电磁环境的活动：\n（一）修建高压输电线、架空金属线、电气化铁路、公路、无线电发射设备试验发射场所等；\n（二）存放金属堆积物；\n（三）种植高大植物；\n（四）掘土、采砂、采石等改变地形地貌的活动；\n（五）修建其他可能影响民用机场电磁环境的建筑物或者设施，以及进行其他可能影响民用机场电磁环境的活动。\n省人民政府无线电管理机构和民航管理部门按照有关规定就前款所列行为制定具体管理办法。\n第二十四条 民用机场管理机构和民航管理部门发现民用航空无线电台（站）受到无线电发射设备以及产生电磁辐射、反射的设施或者物体等干扰源的干扰时，应当向民用机场所在地的县级以上人民政府无线电管理机构报告，无线电管理机构应当及时依法查处。","level":1},{"name":"第四章 法律责任","text":"第二十五条 违反本条例的规定，法律、行政法规有处罚规定的，从其规定。\n第二十六条 民用机场新建、扩建公告发布后，任何单位和个人在民用机场净空保护区域内修建、种植、设置影响民用机场净空安全的障碍物，由民用机场所在地的县级以上人民政府或者其委托的相关部门责令限期清除、处理。对此造成的损失，由修建、种植、设置该障碍物的单位和个人承担。\n第二十七条 违反本条例第十一条、第二十三条第一款规定的，由民用机场所在地的县级以上人民政府或者其委托的相关部门责令限期改正；情节严重的，处2万元以上10万元以下罚款。\n第二十八条 违反本条例第十三条、第十四条规定，未经批准升放无人驾驶自由气球、系留气球或者升放后发生异常情形时不及时报告的，按照职责分工由民用机场所在地的市、州以上人民政府气象主管机构或者空中交通管理部门责令改正，给予警告；情节严重的，处1万元以上5万元以下罚款。\n第二十九条 违反本条例第十五条规定，未经批准使用飞艇、热气球、滑翔机、动力伞等航空器从事航空飞行或者未按批准的飞行计划飞行的，由空中交通管理部门责令改正，给予警告；情节严重的，处2万元以上10万元以下罚款。\n第三十条 在民用机场净空安全保护工作中，有关国家工作人员违反本条例规定，滥用职权、玩忽职守、徇私舞弊的，由其主管部门或者行政监察部门依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第五章 附则","text":"第三十一条 本条例中下列用语的含义：\n民用机场，是指专供民用航空器起飞、降落、滑行、停放以及进行其他活动使用的划定区域，包括附属的建筑物、装置和设施。\n民用航空器，是指除用于执行军事、海关、警察飞行任务外的航空器。\n系留气球，是指系留于地面物体上、直径大于1.8米或者体积容量大于3.2立方米、轻于空气的充气物体。\n第三十二条 本条例自2011年3月1日起施行。","level":1}]},{"id":"h0147","sections":[{"name":"","text":"（2010年12月4日湖北省第十一届人民代表大会常务委员会第十九次会议通过 根据2020年6月3日湖北省第十三届人民代表大会常务委员会第十六次会议《关于集中修改、废止涉及取消证明事项的部分省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了保障适龄儿童、少年接受义务教育的权利，促进义务教育均衡发展和教育公平，全面实施素质教育，巩固提高义务教育水平，根据《中华人民共和国义务教育法》和其他有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省依法实施九年义务教育制度，并加快普及学前教育和高中阶段教育。\n义务教育是强制性、免费性、普及性的公益性事业，各级人民政府必须依法保障所有适龄儿童、少年平等接受义务教育。\n实施义务教育不收学费、杂费，并逐步实行免费提供教科书制度。实施义务教育所需的师资以及经费、图书、设备、校舍等，由县级以上人民政府依法予以保障。\n第三条 实施义务教育坚持优先发展、育人为本、改革创新、促进公平、提高质量的工作方针。\n县级以上人民政府应当合理配置教育资源，促进义务教育均衡发展，改善薄弱学校的办学条件，并采取措施，保障农村、贫困地区、少数民族地区实施义务教育。\n第四条 义务教育实行省人民政府统筹规划实施、县级人民政府为主管理的体制。\n省人民政府制定全省义务教育实施规划，决定义务教育工作中的重大事项，统筹落实全省义务教育经费，组织实施全省义务教育工作并进行督促检查。\n市（州）人民政府制定本行政区域义务教育实施规划，筹措本级政府义务教育经费，对所属部门和下级人民政府实施义务教育工作的情况进行督促检查。\n县级人民政府负责实施义务教育的具体管理工作，制定本行政区域义务教育事业发展规划，规划和建设学校，加强教师队伍建设，依法落实应当由本级政府承担的义务教育经费，保证学校正常运转和学校安全，维护学校周边秩序。\n县级以上人民政府教育行政部门具体负责义务教育实施工作，其他有关部门在各自职责范围内负责义务教育实施中的相关工作。\n乡镇人民政府、街道办事处按照规定的职责做好义务教育的实施工作。\n第五条 县级以上人民政府实行义务教育工作目标责任制度和问责制度，将义务教育均衡发展、入学保障、教师队伍建设、素质教育、经费投入、学校安全等情况，作为考核政府、有关部门及其负责人的重要内容。\n发生违反本条例的重大事件，妨碍义务教育实施，造成重大社会影响，负有直接领导责任的人民政府负责人或者教育行政部门负责人应当引咎辞职。","level":1},{"name":"第二章 均衡发展与教育公平","text":"第六条 县级以上人民政府应当将义务教育优先发展、均衡发展、促进教育公平纳入经济社会发展规划，建立健全保障机制，加大教育资源向农村、贫困地区、少数民族地区和薄弱学校倾斜的力度，加快消除学校之间、城乡之间和区域之间义务教育的差距，逐步实现义务教育师资配备均衡化、基础设施标准化、教育质量一体化。\n第七条 省人民政府完善义务教育经费财政转移支付制度，按照增长比例农村高于城市，贫困地区、少数民族地区高于经济较发达地区的原则，加大对农村、贫困地区、少数民族地区的转移支付。县级人民政府应当按照规定将义务教育转移支付资金全部用于义务教育。鼓励经济较发达地区支援贫困地区、少数民族地区实施义务教育。\n第八条 县级以上人民政府应当按照国家标准，加快实施义务教育学校标准化建设，加快改造薄弱学校，缩小校际差距。\n县级以上人民政府及其教育行政部门不得将学校分为重点学校和非重点学校。学校不得分设重点班和非重点班。\n建立完善优质普通高中招生名额均衡合理分配到初中学校的制度。\n第九条 省人民政府教育行政部门应当建立健全教师和校长的流动制度，完善鼓励政策，推进城乡之间、区域之间、校际之间教师、校长的合作交流和合理流动。\n县级人民政府及其教育、人力资源和社会保障等有关部门应当均衡配置教师资源，在编制调配、岗位设置、职务（职称）评聘、骨干教师配备、教师校长交流等方面，优先考虑农村学校和城镇薄弱学校，改善城乡学校教师学科、职称、年龄的分布结构，促进学校之间师资力量相对均衡。\n第十条 城镇学校教师到农村、贫困地区、少数民族地区从事义务教育一年以上的，在职务（职称）评聘、进修培训以及录取本省高等学校教育类专业研究生等方面，同等条件下予以优先。城镇中小学教师晋升高级教师职务（职称），应当具有在农村学校或者城镇薄弱学校任教一年以上的经历。\n特级教师、湖北名师、副高以上职务（职称）教师在达到退休年龄后，健康状况符合任教条件，自愿到农村学校、城镇薄弱学校任教的，可以按照国家和省的规定适当延长退休年龄。\n第十一条 实施农村义务教育学校教师特设岗位计划和农村教师资助行动计划，鼓励高等学校毕业生到农村、贫困地区、少数民族地区乡镇以下学校任教。高等学校毕业生参加教师特设岗位计划、资助行动计划的，按照国家、省有关规定，享受下列优惠政策：\n（一）国家规定由财政保障的工资待遇；\n（二）相应的社会保险待遇；\n（三）经费奖励或者助学贷款补偿；\n（四）继续在农村学校长期任教的，优先入编；\n（五）报考公务员、研究生的，同等条件下优先录取；\n（六）进入国有企事业单位工作的，按照同等条件人员确定其职务工资，任教年限计入工龄；\n（七）其他优惠政策。\n县级以上人民政府应当按照规定为异地交流教师、特岗教师、资教教师建立周转宿舍。\n第十二条 县级以上人民政府及其教育行政部门对长期在农村、贫困地区、少数民族地区工作的教师，应当予以关心、帮助，在工资、职务（职称）等方面实行倾斜政策，逐步提高津补贴标准，并通过多种形式妥善解决其住房困难。省人民政府设立专项奖励金，对在农村、贫困地区、少数民族地区长期从教、贡献突出的教师给予奖励。\n第十三条 县级以上人民政府及其教育行政部门建立教育资源共享机制，推动师资、教育教学设施设备、课程、管理和服务等资源共享，发展远程教育，发挥优质学校的示范带动作用。","level":1},{"name":"第三章 学生与入学保障","text":"第十四条 凡年满六周岁的儿童，其父母或者其他法定监护人必须送其入学接受并完成义务教育。\n适龄儿童、少年因身体状况需要延缓入学或者休学的，其父母或者其他法定监护人应当持病历等身体状况材料，按照规定提出申请，由当地乡镇人民政府或者县级人民政府教育行政部门批准。延缓入学或者休学的情形消除后，应当继续接受并完成义务教育。\n第十五条 适龄儿童、少年在户籍所在地学校免试、就近入学。学校不得采取考试或者变相考试的形式选拔学生，不得为选拔学生举办或者参与举办各种形式的培训班，不得将各种学科竞赛成绩、考级证书等作为新生入学和编班的依据。\n第十六条 县级人民政府教育行政部门根据辖区内适龄儿童、少年的数量和分布状况，合理确定并向社会公布每所公办学校的招生范围、招生人数。学校应当按照招生范围对口接收学生，招生办法和新生名单等信息应当向社会公布。\n禁止公办学校跨招生范围组织招生。\n第十七条 适龄儿童、少年随其父母或者其他法定监护人在非户籍所在地居住的，可以在其父母或者其他法定监护人工作或者居住地接受义务教育，当地人民政府应当为其提供平等接受教育的条件，教育行政部门应当按照有关规定予以保障。\n流浪未成年人、集中供养孤儿由所在未成年人救助保护中心、儿童福利机构送其入学。\n第十八条 学生因户籍变更等原因确需转学的，转出地和转入地的学校应当按照有关规定办理手续。学生学籍管理办法由省人民政府教育行政部门制定。\n第十九条 依法设立的招收适龄儿童、少年进行文艺、体育等专业训练的社会组织，应当保证所招收的适龄儿童、少年接受义务教育；依附普通学校实施义务教育的，应当和所依附的学校签订联合办学协议，明确双方的权利义务；自行实施义务教育的，应当按照国家规定将招生情况、办学条件、师资和经费保障、课程设置、教学计划等，报所在地县级人民政府教育行政部门批准。\n第二十条 县级人民政府应当建立政府主导、有关部门和农村基层组织参与的农村留守儿童关爱服务体系和动态监测机制。学校应当建立留守儿童档案和联系制度，完善留守儿童生活与心理关怀、疏导机制，关心留守儿童身心健康。\n教育行政部门和学校应当采取措施，保证进城务工人员子女融入所在城镇的义务教育，在入学、升学、编班、学籍管理、奖励、考核评价等方面，与城镇学生平等对待、平等教育。\n第二十一条 县级以上人民政府根据辖区内各类残疾适龄儿童、少年数量和分布状况，按照国家标准合理设置特殊教育学校（班），健全组织入学制度，改善办学条件，提高办学水平，保障残疾适龄儿童、少年接受并完成义务教育。\n普通学校应当接收具有接受普通教育能力的残疾适龄儿童、少年随班就读，并为其学习、生活、康复提供帮助。\n第二十二条 县级以上人民政府司法行政部门会同教育行政部门对未完成义务教育的未成年犯和被采取强制性教育措施的未成年人实施义务教育，所需经费由本级人民政府予以保障。\n未成年犯管教机构和未成年人强制性教育机构应当按照有关规定组织实施义务教育的教学活动。\n第二十三条 学校应当关心和爱护学生，尊重学生人格，维护学生合法权益。对违反学校管理制度的学生，应当予以批评教育，帮助学生改正错误，不得将其退学或者开除。对有法律规定严重不良行为的学生，其父母或者其他法定监护人以及学校可以按照有关法律、法规规定，经县级以上人民政府教育行政部门批准，将其转送专门学校接受义务教育。\n第二十四条 学校和村（居）民委员会发现未入学的适龄儿童、少年或者辍学学生的，应当及时向乡镇人民政府或者街道办事处报告。乡镇人民政府或者街道办事处应当与县级人民政府教育行政部门、学校采取措施，共同做好适龄儿童、少年入学和辍学学生复学工作。\n第二十五条 学生应当遵守学生行为规范和学校管理制度，尊敬师长，完成规定的学习任务，养成良好的思想品德和行为习惯。\n第二十六条 禁止用人单位招用应当接受义务教育的适龄儿童、少年。\n禁止任何组织或者个人利用适龄儿童、少年特别是残疾的适龄儿童、少年卖艺、乞讨。\n禁止任何单位或者个人组织、接纳学生参加非公益性庆典、演出。","level":1},{"name":"第四章 学校建设与安全","text":"第二十七条 县级以上人民政府根据本行政区域内居住的适龄儿童、少年的数量和分布状况、地理地质条件、交通环境等因素，依法制定学校设置规划，并将其纳入城乡建设总体规划。\n学校设置规划应当根据新城区开发、旧城区改造、乡镇和村庄撤并以及当地适龄儿童、少年数量增减情况适时调整。\n第二十八条 新建、改建、扩建居民区需要设置学校的，应当纳入教育设施专项规划。城乡规划行政部门在核发居民区建设项目建设工程规划许可证前，应当征求本级教育行政部门的意见。学校建设应当与居民区同步规划、同步建设、同步交付使用。当地人民政府应当依法提供所需建设用地，并对公办学校用地资金和建设资金予以保障。\n第二十九条 因城乡建设需要拆迁学校的，房屋拆迁人应当与当地教育行政部门协商，按照先建设后拆迁的原则，根据学校布局调整方案重新建设。重新建设应当确保校园规模和设施完整，用地面积不得少于原用地面积，存量资产不得减少。县级人民政府及其教育行政部门应当妥善安排学校拆迁后学生的就学。\n第三十条 学校建设应当符合国家规定的办学标准、选址要求和建设标准，适应教育教学需要，确保学生和教职工安全。加快实施中小学校舍安全工程。\n县级人民政府及其教育行政部门应当按照方便农村偏远地区低龄学生就近、安全入学的原则，合理规划布局，设置必要的教学点，并加强教育教学设施设备和师资配备。乡镇中心学校应当加强指导和管理，保证教学点的教育教学质量。\n第三十一条 县级人民政府按照国家、省规定的标准，加强农村寄宿制学校的建设和管理，配套完善教育教学设施设备以及宿舍、食堂、饮用水、厕所、沼气等生活设施，改善师生的生活环境和学习、工作条件，并根据寄宿制学校的特点，配备必要的工勤人员。工勤人员的工资和福利待遇，不得从寄宿学生生活补助费中列支。\n寄宿制学校应当建立健全安全、卫生、生活等管理制度，保障寄宿学生的人身安全和身心健康。\n第三十二条 县级以上人民政府及其有关部门、学校建立健全学校产权登记制度，明确产权关系，防止学校国有资产流失。\n任何单位和个人不得以任何名义改变或者变相改变公办学校的性质，不得侵占、破坏学校的校舍、场地和教育教学设施、设备。未经依法批准，不得将校舍、场地和教育教学设施设备转让、出租或者改变用途。\n实施义务教育的公办学校依法参与举办的民办学校，应当具有与公办学校相分离的独立校园和基本教育教学设施，实行独立的财务会计制度，具有独立的法人资格，独立招生，独立颁发学业证书。\n第三十三条 县级人民政府应当健全学校及周边综合治理联席会议制度和警校经常性联系制度，组织教育、公安、市场监督管理、文化和旅游、交通运输、卫生健康、生态环境、城市管理等部门以及乡镇人民政府（街道），维护学校周边治安、食品、交通等安全秩序，并落实学校配备安全保卫人员的规定，保障学校、学生、教师安全。村（居）民委员会应当予以协助。\n任何组织和个人不得违反国家有关安全防护距离的规定，在学校周边兴建存在安全隐患或者产生环境污染的企业、设施；不得违反国家有关规定在学校周边设立互联网上网服务营业场所、营业性歌舞娱乐场所；不得从事影响学校安全和教育教学的活动。城乡规划行政部门在办理学校周边建设工程规划许可证时，应当征求学校意见。\n第三十四条 县级人民政府定期组织对学校校舍安全进行检查，对需要维修、改造的，应当及时予以维修、改造；学校应当加强校舍的日常安全检查和维护。\n学校应当建立健全安全管理责任制度，加强对学生和教职工的安全教育，制定突发事件应急预案并定期组织演练，定期排查并及时处置安全隐患。发生自然灾害、突发事件危及学生人身安全时，学校、教师应当优先保护学生安全，及时、有效组织学生避险。\n学校应当按照国家和省的规定投保学生意外伤害校方责任保险，所需费用在学校公用经费中列支。\n第三十五条 学校应当严格执行国家和省规定的收费项目及标准，不得以任何名义和理由自行设定收费项目或者提高收费标准。\n学校应当实行校务公开，在校园醒目位置公示国家和省规定的收费项目、收费标准、收费依据，接受学生和家长的监督。\n第三十六条 学校实行校长负责制。校长应当符合国家规定的任职条件和资格，由县级人民政府教育行政部门依法聘任，并依照学校章程对学校实施管理。校长实行任期制，在同一所学校任职满两届的一般应当进行交流。推行校长职级制。\n学校应当建立健全与家长、社区的联系制度，建立家长委员会，为家庭教育提供指导。对涉及学生利益的重要决策事项，学校应当听取家长委员会的意见。","level":1},{"name":"第五章 教师队伍建设","text":"第三十七条 教师应当忠诚于人民的教育事业，为人师表，恪守职业道德，履行教育教学职责，完成教育教学工作任务，提高教育教学质量。\n依法维护教师权益，提高教师地位，保障教师待遇。全社会应当尊重教师。\n第三十八条 教师应当取得国家规定的教师资格，符合规定的教师岗位聘任条件。实行教师资格证书定期登记制度。\n省人民政府教育行政部门统一组织中小学教师资格考试和资格认定，统一组织新进教师招考。\n县级人民政府教育行政部门按照规定履行中小学教师的招聘录用、职务（职称）评聘、培养培训和考核等管理职能。\n建立完善教师补充机制，新进义务教育学校教师主要从免费师范生、特岗生或者资教生中招聘录用。\n第三十九条 县级以上人民政府应当保障教师的平均工资水平不低于或者高于当地公务员的平均工资水平，并按时足额发放。特殊教育教师的特殊岗位津贴，按照国家和省有关规定执行。\n县级以上人民政府应当保障教师的社会保险待遇，提高教师的医疗保障水平，改善教师的工作和生活条件。\n第四十条 逐步实行城乡统一的中小学编制标准。县级以上人民政府应当健全完善中小学编制管理制度，并根据学生人数变化和教育教学需要，建立动态调整机制，保持教师队伍年龄结构和专业结构的合理性、适应性。\n任何部门和单位不得挤占、挪用教师编制。\n第四十一条 县级以上人民政府教育行政部门应当加强教师培训机构建设，制定教师继续教育规划和培训计划，对教师实行每五年一个周期的全员培训。省人民政府教育行政部门统一规划、定期组织农村教师接受免费培训。\n第四十二条 实行教师绩效考核制度。学校应当将考核结果作为教师岗位聘任、职务（职称）晋升、绩效工资分配、实施奖惩等的重要依据。\n建立完善教师退出调整机制。对不能胜任教育教学工作的教师，由县级人民政府教育行政部门组织培训；经培训仍不能胜任教育教学工作的，应当调离教学岗位。\n第四十三条 公办学校教师不得从事或者组织学生参加有偿家教和有偿培训，不得到社会办学机构兼职兼课。","level":1},{"name":"第六章 教育教学与素质教育","text":"第四十四条 教育教学坚持德育为先、能力为重、全面发展的方针，遵循教育规律和学生身心发展规律，将德育、智育、体育、美育等有机统一在教育教学活动中，注重培养学生的学习能力、生活能力、创新能力和实践能力，全面实施素质教育。\n鼓励教师和校长在教育教学工作中创新教育思想、教育模式和教育方法，形成教学特色和办学风格。加快实施教育教学专家培养计划，倡导教育家办学。\n第四十五条 学校应当加强对学生的爱国主义、社会公德、传统美德、心理健康、劳动、法制教育和日常行为规范等教育，形成学校、家庭、社会相互配合的思想道德教育体系，促进学生养成良好的思想品德和行为习惯。\n第四十六条 学校应当按照国家确定的教育教学内容和课程设置、课时安排开展教育教学活动，改进和创新教育教学方法。推进小班教学，逐步实现按照小学三十五人以下、初中四十人以下编班的要求。\n县级人民政府及其教育行政部门应当按照规定为学校配齐音乐、美术、体育、科学技术等学科教师和相应的教育教学设备，保障学校开齐课程，开足课时。\n第四十七条 学校应当保证学生的课外活动时间，组织学生开展文化、科技、社会公益等社会实践活动。\n爱国主义教育基地、图书馆、青少年宫、博物馆、科技馆、纪念馆、少年儿童活动中心等按照规定对学生免费或者优惠开放，为学校开展素质教育提供支持。\n第四十八条 减轻学生过重的课业负担，是政府、学校、家庭和社会的共同责任。\n县级以上人民政府及其教育行政部门建立学生课业负担监测和公告制度，不得以升学率对地区和学校进行排名，不得下达升学指标。加强对社会补习机构和教辅市场的规范和管理。\n学校应当提高课堂教学质量和效果，减少作业量和考试次数，不得增加课时和教学难度，不得按照考试成绩对学生进行排名，不得利用假期、公休日、课余时间组织学生补课，不得动员、组织学生参加社会课业补习班。\n家长应当树立正确的教育观念，加强与学校的沟通配合，共同减轻学生过重的课业负担。新闻媒体等社会各方面应当为减轻学生过重的课业负担营造良好的社会氛围。\n第四十九条 县级以上人民政府及其教育行政部门建立健全以素质教育为核心的义务教育质量保障体系、监测评价体系和教学研究指导体系，推进素质教育的实施。\n县级以上人民政府教育行政部门对学校、教师实施素质教育的情况进行监测、考核评估和督促检查；发现不符合素质教育要求的，应当及时纠正。\n不得将升学率、学生学科考试成绩作为实施义务教育和考核评价学校、教师的单一标准。\n第五十条 学校必须选用经过审定并列入全省义务教育教学用书目录的教科书，国家另有规定的除外。提倡义务教育教科书循环使用。\n地方课程教科书须经省人民政府教育行政部门审定。未经审定的地方课程教科书不得出版、选用。教育行政部门应当加强对教科书和配套教辅资料选用的监督管理。\n任何单位和个人不得强制或者变相强制学校、教师、学生统一订购、使用教辅材料及报刊杂志。学校、教师不得强制或者变相强制学生统一订购、使用教辅材料及报刊杂志。","level":1},{"name":"第七章 投入保障与监督","text":"第五十一条 县级以上人民政府应当按照确保达到国家有关财政性教育经费所占比例的总体要求，将义务教育全面纳入财政保障范围，加大对义务教育的投入，保证本级财政用于实施义务教育的增长比例高于财政经常性收入的增长比例，保证按照在校学生人数平均的义务教育费用逐步增长，保证教职工工资和学生人均公用经费逐步增长。\n县级以上人民政府不得因上级财政增加转移支付而减少本级财政对义务教育经费的投入。\n第五十二条 省人民政府按照国家规定，结合本省经济和社会发展状况，制定不低于国家标准的学生人均公用经费标准。\n特殊教育学校（班）、寄宿制学校、少数民族学校（班）学生人均公用经费标准应当高于同类普通学校学生人均公用经费标准。\n第五十三条 义务教育经费投入实行县级以上人民政府根据职责共同负担，省人民政府负责统筹落实的体制。农村义务教育所需经费，由县级以上人民政府按照有关规定分项目、按比例分担。\n城市教育费附加和地方教育附加应当足额征收，按照规定用于均衡发展城乡义务教育。\n各级人民政府对农村适龄儿童、少年免费提供教科书，补助农村贫困家庭寄宿生生活费并逐步提高标准。\n第五十四条 县级以上人民政府按照教职工编制标准、工资标准、学校建设标准、学生人均公用经费标准以及贫困学生资助、困难学校安保、工勤人员聘用等所需开支，及时足额拨付义务教育经费，保证学校教育教学活动的正常开展。\n县级以上人民政府应当按照学生人均公用经费标准和学校实际接收人数，及时足额向接收进城务工人员子女的学校拨付教育经费。\n对接受政府委托实施义务教育的民办学校，县级以上人民政府按照国家和省的规定，拨付相应的教育经费。民办学校应当按照国家规定规范收费，改善办学条件，提高教学质量。\n第五十五条 义务教育经费必须用于义务教育。任何组织和个人不得挪用、侵占、截留义务教育经费，不得向学校非法收取或者摊派费用。\n学校不得将公用经费用于偿还债务或者发放教职工津贴、补助、奖金。\n第五十六条 县级以上人民政府建立健全义务教育经费的审计监督和统计公告制度，加强对实施义务教育经费拨付、使用、效益等的监督、检查。\n第五十七条 县级以上人民代表大会常务委员会通过听取专项工作报告、审查财政预算决算情况、开展执法检查等形式，依法对同级人民政府实施义务教育的情况进行监督。\n第五十八条 县级以上人民政府实行义务教育督导制度。教育督导机构代表政府对本级人民政府有关部门、下级人民政府以及实施义务教育的学校和其他教育机构实施义务教育情况进行督促指导，并接受上级教育督导机构的指导。\n义务教育督导实行教育督导部门为主，其他有关部门共同参与的工作机制。\n第五十九条 教育督导机构对下列事项进行督导：\n（一）有关法律、法规、规章和教育方针政策的执行情况；\n（二）义务教育普及和巩固提高情况；\n（三）学校、区域、城乡义务教育质量及师资配备、基础设施等均衡发展情况；\n（四）义务教育经费保障和使用情况；\n（五）教师的师德、业务水平、基本待遇、招聘录用、培养培训、编制配备等情况；\n（六）推进素质教育的情况；\n（七）教育教学质量的情况；\n（八）学校安全、生活管理的情况；\n（九）治理择校乱收费的情况；\n（十）其他需要督导的内容。\n第六十条 县级以上人民政府应当建立义务教育督导评价制度和督导评价结果公告制度、奖惩制度。督导评价结果作为评价义务教育工作的重要指标和考核主要领导干部的重要内容。\n教育督导机构依据督导评价结果向被督导单位下达督导意见书。需要整改的，被督导单位应当按照要求进行整改，并向教育督导机构报告整改情况。","level":1},{"name":"第八章 法律责任","text":"第六十一条 违反本条例规定的行为，法律、法规有处罚规定的，从其规定。\n第六十二条 县级以上人民政府及其教育行政等有关部门有下列情形之一的，由上级人民政府责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予处分：\n（一）以升学率对地区和学校进行排名或者对学校下达升学指标的；\n（二）未按照规定设置特殊教育学校（班）和寄宿制学校的；\n（三）未按照规定履行维护学校周边秩序和安全职责的；\n（四）未按照规定保障教师待遇、落实支教优惠政策的；\n（五）挤占、挪用教师编制的；\n（六）未按照规定均衡安排义务教育经费的；\n（七）违反本条例的其他行为。\n第六十三条 学校有下列情形之一的，由县级人民政府教育行政部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予处分：\n（一）公办学校跨招生范围组织招生的；\n（二）拒绝接收应当在本校接受义务教育的适龄儿童、少年就读的；\n（三）采取考试或者变相考试的形式选拔学生，为选拔学生举办或者参与举办培训班，将学科竞赛成绩、考级证书作为新生入学和编班依据的；\n（四）未采取有效措施防止学生辍学和动员辍学学生复学的；\n（五）将违反学校管理制度的学生退学或者开除的；\n（六）未按照课程设置规定开齐课程、开足课时的；\n（七）强制或者变相强制学生参加社会课业补习班或者订购、使用教辅材料及报刊杂志的；\n（八）擅自将公办学校校舍、场地和教育教学设施设备转让、出租或者改变用途的；\n（九）将公用经费用于偿还债务或者发放教职工津贴、补助、奖金的；\n（十）未按照规定履行校园安全管理责任的；\n（十一）违反本条例的其他行为。","level":1},{"name":"第九章 附则","text":"第六十四条 社会组织或者个人依法举办的民办学校实施义务教育的，依照民办教育促进法有关规定执行；民办教育促进法未作规定的，适用义务教育法与本条例。\n第六十五条 本条例自2011年3月1日起施行。1986年12月11日湖北省第六届人民代表大会第二十四次会议通过的《湖北省义务教育实施办法》同时废止。","level":1}]},{"id":"h0148","sections":[{"name":"","text":"（2011年4月2日湖北省第十一届人民代表大会常务委员会第二十三次会议通过 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了预防火灾和减少火灾危害，加强应急救援工作，保护人身、财产安全，维护公共安全，根据《中华人民共和国消防法》和其他有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内的消防以及相关应急救援工作，适用本条例。\n第三条 消防工作贯彻预防为主、防消结合的方针，按照政府统一领导、部门依法监管、单位全面负责、公民积极参与的原则，实行消防安全责任制，建立健全社会化的消防工作网络。\n第四条 各级人民政府负责本行政区域的消防工作，把消防工作纳入国民经济和社会发展规划、年度计划，将消防工作经费以及应急救援经费纳入本级财政预算，逐步增加投入，保障消防工作与经济社会发展相适应。\n第五条 县级以上人民政府应急管理部门对本行政区域内的消防工作实施监督管理，并由本级人民政府消防救援机构负责实施；其他有关部门在各自职责范围内依法做好消防工作。\n第六条 维护消防安全是全社会共同的责任。\n任何单位和个人都有保护消防设施、预防火灾、报告火警的义务；发现消防安全违法行为，有权劝阻、举报和投诉。\n任何单位和成年人都有参加有组织的灭火工作的义务。\n第七条 各级人民政府以及社会各界应当积极组织开展消防宣传教育，普及防火、灭火和应急逃生知识，提高公民的消防安全意识，预防火灾和减少火灾危害。\n鼓励、引导社会资本投入公共消防设施建设；鼓励、支持社会力量参与消防宣传教育、消防队伍建设、消防志愿服务、消防公益捐赠等公益活动。\n每年11月为本省消防安全宣传月，11月9日为本省消防日。\n第八条 各级人民政府和有关部门对在火灾预防、扑救以及应急救援工作中作出突出贡献的单位和个人，应当按照国家、省有关规定给予表彰、奖励。","level":1},{"name":"第二章 消防工作职责","text":"第九条 县级以上人民政府应当履行下列消防工作职责：\n（一）建立、落实消防工作责任制、问责制，将消防工作纳入政府年度工作考核体系和社会治安综合治理范围；\n（二）建立完善消防通信指挥、战勤保障系统和灭火抢险救援区域协作机制，制定应急救援预案；\n（三）加强公共消防设施和消防装备建设，根据需要增配复杂火灾扑救和特殊灾害事故抢险救援的装备；\n（四）组织开展消防安全检查，督促整改重大火灾隐患；\n（五）加强消防组织建设，建立综合性应急救援队伍，定期组织演练；\n（六）其他依法应当履行的消防工作职责。\n县级以上人民政府应当设立消防安全委员会，定期召开联席会议，研究、协调、解决消防工作中的重大问题，督促有关部门和单位落实消防安全责任，组织开展消防安全专项治理。\n政府主要负责人对本行政区域内的消防工作负全面领导责任，分管负责人对消防工作负直接领导责任。\n第十条 发展和改革部门应当将公共消防设施建设列入固定资产投资计划，并督促落实。\n住房和城乡建设部门应当将公共消防设施建设纳入城乡基础设施建设和改造计划，并负责组织实施。\n城管、供水、供电、通信等有关单位负责消防供水、供电、消防通信等公共消防设施的建设和日常管理维护，保证公共消防设施的完备、有效。\n水利、农业农村、交通运输等部门和乡镇人民政府应当将消防水源、消防车通道等农村公共消防设施建设纳入农村基础设施建设工程、项目，保障其正常使用，改善农村消防安全条件。\n第十一条 应急管理部门负责易燃易爆危险品的安全监督管理工作，组织编制和协调相关部门实施易燃易爆危险品事故应急救援预案。\n市场监督管理部门应当加强对生产、销售的消防产品质量的监督检查。\n第十二条 科技、司法行政、人力资源和社会保障等部门应当将消防安全知识列入科普、普法、职业教育培训内容。\n教育部门应当将消防安全知识纳入教学内容，指导、监督学校做好消防安全教育工作。学校应当制定消防安全教学计划，确定熟悉消防知识的教师或者聘请消防专业人员担任消防安全课教员，对学生开展有针对性的消防安全教育，每学年组织学生开展一次以上避险自救、应急疏散演练。\n文化和旅游、广播电视等部门应当组织做好消防宣传教育工作。报刊、广播、电影、电视、互联网站等公众媒体应当无偿开展消防宣传教育。\n第十三条 县级以上人民政府消防救援机构应当履行下列消防工作职责：\n（一）依法实施公众聚集场所投入使用、营业前的消防安全检查，并建档备查；\n（二）依法实施消防监督检查，查处消防安全违法行为；\n（三）开展消防宣传教育，组织消防安全培训，指导消防队伍建设；\n（四）依法对消防服务机构、消防产品进行监督管理；\n（五）组织灭火救援和依照国家规定参加其他应急救援工作；\n（六）调查火灾事故，统计火灾损失；\n（七）其他依法应当履行的消防工作职责。\n公安派出所按照有关规定实施日常消防监督检查，开展消防宣传教育，保护火灾现场，协助调查火灾原因。\n第十四条 乡镇人民政府、街道办事处应当建立健全消防工作制度，明确消防安全责任，落实消防安全措施，开展消防宣传教育、火灾隐患排查治理和灭火演练。\n村（居）民委员会应当开展群众性消防工作，确定消防安全管理人，组织制定防火安全公约，开展消防宣传教育，进行防火安全检查。\n家庭应当做好经常性的用火、用电、用油、用气安全自查。鼓励家庭自备简易灭火器材和自救逃生器具。\n第十五条 机关、团体、企业、事业等单位（以下统称单位）应当履行下列消防安全职责：\n（一）落实消防安全责任制，制定本单位的消防安全制度、消防安全操作规程，制定灭火和应急疏散预案；\n（二）按照国家标准、行业标准配置消防设施、器材，设置消防安全标志，并定期组织检验、维修，确保完好有效；\n（三）对建筑消防设施每年进行一次以上全面检测，确保完好有效，检测记录应当完整准确，存档备查；\n（四）保障疏散通道、安全出口、消防车通道畅通，保证防火防烟分区、防火间距符合消防技术标准；\n（五）组织防火检查，及时消除火灾隐患；\n（六）组织进行有针对性的消防演练；\n（七）法律、法规规定的其他消防安全职责。\n单位的主要负责人是本单位的消防安全责任人，对本单位的消防安全全面负责，逐级明确责任人员，落实工作经费，组织实施各项消防安全制度。\n第十六条 消防安全重点单位除应当履行本条例第十五条规定的职责外，还应当履行下列消防安全职责：\n（一）确定消防安全管理人，组织实施本单位的消防安全管理工作；\n（二）建立消防档案，确定消防安全重点部位，设置防火标志，实行严格管理；\n（三）实行每日防火巡查，并建立巡查记录；\n（四）对职工进行岗前消防安全培训，定期组织消防安全培训和消防演练。\n消防安全重点单位由县级以上人民政府消防救援机构确定，并由应急管理部门报本级人民政府备案。\n第十七条 从事生产加工、销售、餐饮、休闲娱乐、住宿服务等的个体工商业主应当根据生产经营特点，加强生产经营场所用火、用电、用油、用气以及仓储物品的消防安全管理，落实防火措施，配置必要的消防设备，保证疏散通道畅通，开展经常性的防火安全自查，消除火灾隐患。\n个体工商业主生产经营中具有下列情形之一的，应当履行单位的消防安全职责：\n（一）生产、经营、储存易燃易爆危险品的；\n（二）经营、使用建筑面积二百平方米以上的人员密集场所的；\n（三）从业人员十人以上的；\n（四）较大火灾危险性的其他情形。","level":1},{"name":"第三章 火灾预防","text":"第十八条 各级人民政府应当统筹城乡消防工作，编制包括消防安全布局、消防站、消防供水、消防通信、消防车通道、消防装备等内容的消防规划，将其纳入城乡规划，并负责组织实施。城乡规划缺少消防规划或者消防规划不合理的，上一级人民政府不得批准。公共消防设施应当与其他公共基础设施同步设计、同步建设、同步投入使用。\n对不符合消防安全布局的易燃易爆危险品生产、储存场所等重大火灾危险源，应当限期改造、搬迁。对不能满足灭火应急救援需要的公共消防设施，应当及时增建、改建、配置或者进行技术改造。对不符合消防安全要求的老城区、城中村和传统商品集散地区，应当加快进行消防改造。\n第十九条 建设工程按照国家工程建设消防技术标准需要进行消防设计的，建设单位应当依法委托具有相应资质的单位进行消防设计、施工和工程监理，不得要求设计、施工、工程监理单位违反国家工程建设消防技术标准，降低建设工程消防设计、施工质量。\n第二十条 属于国务院住房和城乡建设主管部门规定的特殊建设工程，建设单位应当将消防设计文件报送住房和城乡建设主管部门审查，住房和城乡建设主管部门依法对审查的结果负责；未经消防设计审查或者审查不合格的，建设单位、施工单位不得施工。其他建设工程，建设单位申请领取施工许可证或者申请批准开工报告时应当提供满足施工需要的消防设计图纸及技术资料；未提供的，有关部门不得发放施工许可证或者批准开工报告。\n属于国务院住房和城乡建设主管部门规定应当申请消防验收的建设工程竣工，建设单位应当向住房和城乡建设主管部门申请消防验收；未经消防验收或者消防验收不合格的，禁止投入使用。其他建设工程，建设单位在验收后应当报住房和城乡建设主管部门备案；住房和城乡建设主管部门应当进行抽查，经抽查不合格的，应当停止使用。\n第二十一条 建筑物或者场所改变用途，依据国家工程建设消防技术标准需要进行消防设计的，建筑物或者场所的所有权人或者使用人应当按照本条例第二十条的规定执行。\n第二十二条 建设工程施工现场的消防安全管理由施工单位负责。施工现场应当符合下列规定：\n（一）疏散通道、安全出口、消防车通道畅通；\n（二）配备相应种类、数量的消防器材并确保完好有效；\n（三）铺设与施工进度相适应的临时消防水源，安装消火栓；\n（四）办公场所、员工集体宿舍与作业区应当分开设置，并保持安全距离。\n施工单位不得在尚未竣工的建筑物内设置员工集体宿舍。\n第二十三条 公众聚集场所投入使用、营业前消防安全检查实行告知承诺管理。公众聚集场所在投入使用、营业前，建设单位或者使用单位应当向场所所在地的县级以上人民政府消防救援机构申请消防安全检查，作出场所符合消防技术标准和管理规定的承诺，提交规定的材料，并对其承诺和材料的真实性负责。\n消防救援机构对申请人提交的材料进行审查；申请材料齐全、符合法定形式的，应当予以许可。消防救援机构应当根据消防技术标准和管理规定，及时对作出承诺的公众聚集场所进行核查。\n申请人选择不采用告知承诺方式办理的，消防救援机构应当自受理申请之日起十个工作日内，根据消防技术标准和管理规定，对该场所进行检查。经检查符合消防安全要求的，应当予以许可。\n公众聚集场所未经消防救援机构许可的，不得投入使用、营业。\n第二十四条 消防产品应当符合国家标准；没有国家标准的，应当符合行业标准、地方标准。禁止生产、销售或者使用不合格的消防产品以及国家明令淘汰的消防产品。\n建筑构件、建筑材料、建筑保温材料和装修、装饰材料的防火性能应当符合国家标准；没有国家标准的，应当符合行业标准、地方标准。\n人员密集场所装修、装饰，应当按照消防技术标准要求，使用不燃、难燃材料。\n第二十五条 高层建筑应当按照国家规定配备火灾预防、灭火救援和火灾防护、避难、逃生等器材；其所有或者使用单位、业主应当逐级明确消防责任，加强防火巡查，及时消除火灾隐患，确保疏散通道、安全出口、消防车通道畅通和消防设施完好有效，开展灭火和自救演练。\n第二十六条 所有权人将建筑物或者场所提供给他人使用的，双方当事人应当在合同中明确各方的消防安全管理责任和消防设施、器材的设置、维护保养责任；未明确的，由建筑物或者场所的所有权人负责。\n第二十七条 有两个以上所有权人的建筑物，专有部分的消防安全由各所有权人分别负责，共有部分的消防安全由全体所有权人共同负责；全体所有权人应当成立组织、确定专人或者委托物业服务企业，对共有部分的消防安全进行管理。\n第二十八条 住宅区的物业服务企业应当对服务区域内的共用消防设施进行维护管理，提供消防安全防范服务。未建立物业服务企业的，住宅区所在的社区居民委员会应当组织业主协商确定维护管理办法。\n住宅区共用消防设施保修期内的维修等费用，由建设单位承担；保修期满后的维修、更新和改造费用，纳入共用设施设备专项维修资金开支范围；没有专项维修资金或者专项维修资金不足的，消防设施维修、更新和改造费用由业主按照约定承担，没有约定或者约定不明确的，按照各自专有部分建筑面积所占比例承担。\n物业服务企业对占用、堵塞、封闭疏散通道和安全出口、消防车通道、防火间距以及损坏消防设施器材的行为，应当予以劝阻、制止；对不听劝阻、制止的，应当及时向消防救援机构或者公安派出所报告。\n第二十九条 人员密集场所应当在醒目位置设置视频、警示牌或者采用广播等形式对公众提示下列事项：\n（一）场所存在的火灾危险性；\n（二）场所的安全逃生路线、安全出口的具体位置以及遇到火灾等紧急情况时正确逃生、自救方法；\n（三）场所内简易防护面罩、手电筒、灭火器等灭火、逃生设备器材的具体位置和使用方法。\n第三十条 公共交通工具应当按照国家、省有关规定配备消防器材，并加强日常维护，保证正常使用。\n禁止消防器材配备不全的公共交通工具载客、营运。禁止非法携带易燃易爆危险品乘坐公共交通工具。\n公共交通运营单位应当加强对工作人员的消防安全教育培训，提高工作人员使用消防器材和组织、引导乘客及时疏散的能力。\n第三十一条 设置有火灾自动报警、自动灭火等自动消防系统的单位，应当委托符合从业条件的消防设施维护保养检测机构对自动消防系统每年进行一次以上的检测和维修。\n消防控制室应当二十四小时有操作人员值守，及时处理报警信号。\n第三十二条 生产、储存、经营易燃易爆危险品的场所不得与居住场所设置在同一建筑物内，并应当与居住场所保持安全距离。\n生产、储存、经营其他物品的场所与居住场所设置在同一建筑物内的，应当按照国家消防安全技术要求，采取防火分隔措施，设置疏散、灭火和报警等消防设施，加强消防安全管理，开展经常性火灾隐患排查，确保场所消防安全。\n第三十三条 禁止在具有火灾、爆炸危险的场所吸烟、使用明火。因施工等特殊情况需要使用明火作业的，施工场所负责人应当按照单位消防安全制度的规定报请单位消防安全责任人批准，施工人员应当遵守消防安全规定，并采取相应的消防安全防护措施。\n第三十四条 消防设施维护保养检测、消防安全评估等消防技术服务机构应当符合从业条件，执业人员应当依法获得相应的资格；依照法律法规、国家标准、行业标准和执业准则，接受委托提供消防技术服务，并对服务质量负责。\n第三十五条 省人民政府及其人力资源和社会保障、消防救援机构等有关部门应当将消防特种岗位纳入社会职业范围，按照国家、省有关规定组织开展消防安全培训和职业技能鉴定，提升社会消防管理水平。\n有关单位应当组织下列人员接受消防安全培训：\n（一）消防安全重点单位的消防安全管理人；\n（二）专职消防队队员；\n（三）自动消防系统的操作人员；\n（四）消防设施、器材检测和维修保养人员；\n（五）消防工程设计、施工、监理人员；\n（六）进行电焊、气焊等具有火灾危险作业的人员；\n（七）从事易燃易爆危险物品生产、储存、运输、销售、装卸工作的操作人员；\n（八）其他依法需要培训的人员。\n前款第（一）、（二）、（三）、（四）项所列人员，经消防行业职业技能鉴定合格，持证上岗；第（五）、（六）、（七）、（八）项所列人员，依法应当取得相应职业资格的，经有关部门考试合格后，持证上岗。\n第三十六条 公众聚集场所的经营者和生产、储存、运输、销售易燃易爆危险品的企业应当健全火灾风险防范机制，保证履行消防安全职责，保障公众安全，投保火灾公众责任保险。\n鼓励生产、储存、运输、销售易燃易爆危险品的企业按照国家、省有关规定建立消防安全责任人员风险抵押金制度。","level":1},{"name":"第四章 消防组织","text":"第三十七条 县级以上人民政府应当按照国家规定标准建立国家综合性消防救援队、专职消防队，配备消防装备，承担火灾扑救工作。\n乡镇人民政府、街道办事处应当根据当地经济社会发展和消防工作需要，建立专职消防队、志愿消防队，或者依托当地公安派出所，建立治安联防消防队，承担火灾扑救工作。\n火灾危险性较大的大型企业以及民用机场、主要港口、高速公路超长隧道管理单位等应当依法建立单位专职消防队或者其他消防组织，承担本单位的火灾扑救工作。\n社区、村（居）民委员会、企业事业单位根据消防工作需要，建立志愿消防队，开展群众性自防自救工作。各类基层保安、联防组织应当承担相应的消防安全职责。\n省人民政府对乡镇多种形式的消防组织建设给予适当补贴。\n第三十八条 县级以上人民政府应当依托国家综合性消防救援队组建综合应急救援队伍，配备相应人员和装备，建立预警响应、指挥协调、信息通报、资源共享、培训演练、预案管理机制。\n综合应急救援队伍按照国家规定承担重大灾害事故和其他以抢救人员生命为主的应急救援工作。\n第三十九条 专职消防队应当依据规定标准配齐消防队员，配置相应消防车辆和器材装备；所需经费，由组建单位承担。\n依法建立的专职消防队，应当报当地消防救援机构验收；撤销单位专职消防队，应当事先征得当地消防救援机构同意。\n专职消防队队员依法享受社会保险和福利待遇。\n第四十条 国家综合性消防救援队、专职消防队应当制定、实施业务训练计划，维护、保养装备器材，开展经常性灭火救援演练，保持人员、消防装备器材处于战备状态。\n志愿消防队应当定期组织开展消防技能训练，提高火灾扑救和防火检查能力。\n消防救援机构应当对专职消防队、志愿消防队等消防组织进行业务指导；根据扑救火灾的需要，可以调动指挥专职消防队参加火灾扑救工作，提高火灾扑救综合能力。\n第四十一条 县级以上人民政府根据消防工作需要，招聘消防员、文职雇员，用于充实国家综合性消防救援队、政府专职消防队，从事执勤灭火和内部勤务工作。\n招聘的消防员、文职雇员的工资、社会保险、福利待遇等所需经费列入本级财政预算。","level":1},{"name":"第五章 灭火救援","text":"第四十二条 县级以上人民政府应当组织有关部门针对本行政区域内的火灾等灾害特点制定应急预案，建立应急反应和处置机制，为火灾扑救和应急救援工作提供人员、装备等保障。\n环保、气象、地震、测绘、通信、供水、供电、供油、供气等有关部门和单位，应当及时、无偿向消防救援机构提供可能影响消防安全、灭火和抢险救援工作的信息资料。\n第四十三条 任何人发现火灾都应当立即报警。任何单位、个人都应当为火灾报警无偿提供便利，不得阻拦报警。严禁谎报火警。\n任何单位发生火灾，必须立即组织力量扑救。邻近单位应当给予支援。\n第四十四条 国家综合性消防救援队、专职消防队实行二十四小时值勤。\n消防救援机构接到火警后，应当指令就近的国家综合性消防救援队赶赴现场；接到指令的国家综合性消防救援队必须立即赶赴现场，救助遇险人员，排除险情，扑灭火灾。\n第四十五条 国家综合性消防救援队在执行扑救火灾任务时，可以对因占用消防车通道而影响消防车辆通行的障碍物实施强制让道或者拆除。\n第四十六条 国家综合性消防救援队、专职消防队扑救火灾、实施应急救援，不得收取任何费用。\n火灾发生地人民政府应当对单位专职消防队、志愿消防队参加外单位灭火救援所损耗的燃料、灭火剂和器材、装备等给予补偿，对相关人员因参加灭火救援而损失的工资、产生的医疗费用给予补助，对灭火救援中表现突出的人员给予奖励。\n第四十七条 发生火灾事故造成人员伤亡或者重大财产损失的，火灾发生地县级人民政府应当组织或者责成有关单位和个人为受灾人员提供必要的生活和医疗救助。\n对因参加灭火救援受伤、致残或者死亡的人员，应当按照规定分别给予其生活保障或者医疗、抚恤待遇；符合烈士条件的，按照国家有关规定执行。\n第四十八条 各级消防救援机构应当在各自管辖权限范围内，按照法定程序调查火灾原因和统计火灾损失。\n火灾扑灭后，发生火灾的单位和相关人员应当按照消防救援机构的要求保护现场，接受事故调查，如实提供与火灾有关的情况。\n任何单位和个人不得妨碍和非法干预火灾事故调查。","level":1},{"name":"第六章 监督检查","text":"第四十九条 县级以上人民政府应当与本级人民政府有关部门和下一级人民政府签订消防工作目标责任书，并对其履行消防工作职责的情况进行监督检查和考核。\n第五十条 消防救援机构应当依法履行消防监督检查职责，公开执法依据、程序，建立执法档案，落实执法责任制。\n消防救援机构应当根据本地区火灾发生的规律、特点和火灾多发季节、重大节日、重大活动等消防安全需要，制定监督检查计划，组织开展监督检查工作。\n消防安全重点单位应当作为监督检查的重点。对人员密集场所应当进行经常性监督检查。\n公安派出所按照国家、省有关规定开展日常消防监督检查，并将辖区内个体工商业生产经营场所作为监督检查的重点。\n第五十一条 消防救援机构和公安派出所进行消防监督检查时，有权调阅有关消防工作的文件、记录，查看、测试消防设施、器材，核查日常防火管理、消防宣传教育培训、消防演练等情况。\n第五十二条 消防救援机构应当向社会公布消防安全违法行为监督举报、投诉电话。\n接到消防安全违法行为的举报、投诉，应当依法受理、登记，并按照下列规定进行实地核查：\n（一）对举报或者投诉占用、堵塞、封闭疏散通道、安全出口或者其他妨碍安全疏散行为，以及损坏、擅自停用消防设施器材的，应当在接到举报、投诉后二十四小时内进行核查；\n（二）对举报、投诉本款第（一）项以外的消防安全违法行为，应当在接到举报或者投诉之日起三日内进行核查。\n核查后，对消防安全违法行为依法处理。处理情况应当及时告知举报、投诉人；无法告知的，应当在受理登记中注明。\n第五十三条 消防救援机构、公安派出所在消防监督检查中发现火灾隐患的，应当责令有关单位或者个人立即采取措施消除隐患；对存在重大火灾隐患的，消防救援机构应当向社会公布，提示公众注意消防安全。\n有关单位和个人应当按照消防救援机构和公安派出所的整改意见，在规定期限内整改。消防救援机构和公安派出所应当对整改情况进行检查。\n不及时消除火灾隐患可能严重威胁公共安全的，消防救援机构应当依照规定对危险部位或者场所采取临时查封措施。\n火灾隐患消除后，当事人申请解除查封的，消防救援机构应当自收到申请之日起三日内进行检查，自检查之日起三日内作出是否同意解除临时查封的决定，并送达当事人。\n第五十四条 消防救援机构发现存在下列重大消防安全问题的，应当由应急管理部门书面报告本级人民政府：\n（一）不符合城乡消防安全布局的重大火灾危险源；\n（二）公共消防设施不符合消防安全要求；\n（三）影响公共安全的重大火灾隐患。\n人民政府应当及时组织或者责成有关部门、单位采取措施整改；对重大火灾隐患，应当挂牌督办，明确整改责任和期限，督促整改。\n第五十五条 消防救援机构对有消防安全违法行为的单位、场所作出责令停止施工、停止使用、停产停业决定，或者作出撤销原同意其使用、开业决定的，应当自作出决定之日起三日内将该决定抄送有关行政管理部门。\n有关行政管理部门应当自收到消防救援机构的决定之日起十日内依法处理，并将处理情况书面告知消防救援机构。\n第五十六条 消防救援机构应当通过网络或者广播、电视、报刊等新闻媒体定期公布辖区内存在严重消防安全违法行为的单位及其整改情况。\n第五十七条 住房和城乡建设主管部门、消防救援机构及其工作人员履行职责，应当自觉接受社会监督。\n任何单位和个人有权对住房和城乡建设主管部门、消防救援机构及其工作人员的违法、违纪行为进行检举、控告。收到检举、控告的机关，应当按照职责及时查处，并将处理结果告知举报人。","level":1},{"name":"第七章 法律责任","text":"第五十八条 违反本条例规定，法律、行政法规有处罚规定的，从其规定。\n第五十九条 各级人民政府及其有关部门违反本条例规定，未履行消防工作职责严重影响消防工作，或者未及时组织督促整改重大火灾隐患的，由上级或者所属人民政府予以通报，并责令限期改正；逾期不改正的，对直接负责的主管人员和其他直接责任人员给予处分；构成犯罪的，依法追究刑事责任。\n第六十条 违反本条例第十七条第一款规定，个体工商业主不依法履行消防安全职责的，由消防救援机构责令限期改正；逾期不改正的，责令停产停业，并处1000元以上1万元以下罚款。\n第六十一条 违反本条例第二十二条规定，施工现场不符合消防安全规定的，由消防救援机构责令限期改正；逾期不改正的，责令停止施工，并处5000元以上5万元以下罚款。\n第六十二条 违反本条例第二十四条第一款规定，生产、销售不合格的消防产品或者国家明令淘汰的消防产品的，由市场监督管理部门依照《中华人民共和国产品质量法》的规定从重处罚。人员密集场所使用不合格的消防产品或者国家明令淘汰的消防产品的，由消防救援机构责令限期改正；逾期不改正的，处5000元以上5万元以下罚款，并对其直接负责的主管人员和其他直接责任人员处500元以上2000元以下罚款；情节严重的，责令停产停业。\n第六十三条 违反本条例第二十九条规定，人员密集场所未依法提示消防安全事项的，由消防救援机构责令限期改正；逾期不改正的，处2000元以上1万元以下罚款。\n第六十四条 违反本条例第三十一条第一款规定，有关单位未依法对自动消防系统进行检测和维修的，由消防救援机构责令限期改正；逾期不改正的，处1000元以上1万元以下罚款。\n违反本条例第三十一条第二款规定，消防控制室没有操作人员二十四小时值守的，由消防救援机构处500元以上5000元以下罚款。\n第六十五条 违反本条例第三十五条第三款规定，有关消防从业人员未经消防行业职业技能鉴定并持证上岗的，由消防救援机构责令录用单位限期改正；逾期不改正的，处1000元以上1万元以下罚款。\n第六十六条 违反本条例第三十七条第三款规定，未依法建立单位专职消防队或者其他消防组织的，由其上级主管部门责令限期改正；逾期不改正的，对单位的主要负责人或者其他直接责任人给予处分。\n第六十七条 住房和城乡建设主管部门、消防救援机构工作人员有下列行为之一，依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）对不符合消防安全要求的消防设计文件、建设工程、场所准予审查合格、消防验收合格、消防安全检查合格的；\n（二）无故拖延消防设计审查、消防验收、消防安全检查，不在法定期限内履行职责的；\n（三）发现火灾隐患不及时责令有关单位、个人整改的；\n（四）利用职务为用户、建设单位指定或者变相指定消防产品的品牌、销售单位或者消防技术服务机构、消防设施施工单位的；\n（五）将消防车、消防艇以及消防器材、装备和设施用于与消防和应急救援无关的事项的；\n（六）不及时出警的；\n（七）不及时调查处理举报、投诉和消防安全违法行为的；\n（八）对消防安全违法行为仅予罚款，不依法履行监管职责的；\n（九）其他滥用职权、玩忽职守、徇私舞弊的行为。\n第六十八条 拒绝、阻碍消防监督检查人员依法履行职责，或者对履行职责的消防监督检查人员进行围攻、打骂、侮辱的，由公安机关依照《中华人民共和国治安管理处罚法》的规定处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附则","text":"第六十九条 本条例自2011年6月1日起施行。2000年3月31日湖北省第九届人民代表大会常务委员会第十七次会议通过的《湖北省实施〈中华人民共和国消防法〉办法》同时废止。","level":1}]},{"id":"h0149","sections":[{"name":"","text":"（2011年5月26日湖北省第十一届人民代表大会常务委员会第二十四次会议通过 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了完善国有资产监督管理体制，推动国家出资企业结构调整和发展方式转变，加强国有资本运营，增强国家出资企业整体竞争力，实现国有资产保值增值，根据《中华人民共和国企业国有资产法》、《中华人民共和国公司法》等法律、法规，结合本省实际，制定本条例。\n第二条 本条例所称企业国有资产（以下称国有资产），是指各级人民政府对企业各种形式的出资所形成的权益，主要包括：\n（一）各级人民政府出资的国有独资企业、国有独资公司、国有资本控股公司、国有资本参股公司中的国有资产；\n（二）按照《中华人民共和国公务员法》管理的行政单位、参照《中华人民共和国公务员法》管理的单位和财政全额拨款的事业单位投资的企业或者经济实体的国有资产；\n（三）各级人民政府授权履行出资人职责的机构管理的其他国有资产。\n第三条 各级人民政府分别代表国家对国家出资企业履行出资人职责，享有出资人权益，实行权利、义务和责任相统一，管资产和管人、管事相结合的国有资产管理体制。\n第四条 各级人民政府应当严格执行国有资产监督管理法律、法规，坚持政府的公共管理职能与国有资产出资人职能分开，坚持政企分开，实行所有权与经营权分离。","level":1},{"name":"第二章 履行出资人职责的机构及其职责","text":"第五条 省、市（州）人民政府国有资产监督管理机构，作为本级人民政府的直属特设机构，根据本级人民政府的授权，代表本级人民政府统一履行国有资产出资人职责。\n县级人民政府应当授权一个部门或者机构代表本级人民政府履行国有资产出资人职责。具备条件的县级人民政府，可以设置独立的国有资产监督管理机构，根据本级人民政府的授权，履行国有资产出资人职责。\n县级以上人民政府的国有资产监督管理机构，统称履行出资人职责的机构。\n上级人民政府履行出资人职责的机构依法对下级人民政府的国有资产监督管理工作进行指导和监督。\n第六条 履行出资人职责的机构的主要职责是：\n（一）依法对国家出资企业行使资产收益、参与重大决策和选择管理者等权利；\n（二）指导推进国有独资企业、国有独资公司、国有资本控股公司的改革和重组，提高企业效益；\n（三）对国有资产的保值增值情况进行监督，防止国有资产损失；\n（四）指导和促进国家出资企业建立现代企业制度，完善法人治理结构，尊重、维护企业经营自主权；\n（五）推动国家出资企业技术进步，提高创新能力；\n（六）指导和促进国家出资企业节约能源、保护环境，加强安全生产，实行民主管理，积极履行社会责任，维护职工合法权益；\n（七）履行出资人的其他职责、承办本级人民政府交办的其他事项。\n第七条 履行出资人职责的机构履行文化企业国有资产出资人职责，负责国有资产基础管理工作，委托有关部门对文化企业的国有资产实施具体监督管理。\n第八条 履行出资人职责的机构对本级人民政府负责，向本级人民政府报告履行出资人职责的情况，接受本级人民政府的监督和考核，对国有资产的保值增值负责。\n履行出资人职责的机构应当按照国家有关规定，定期向本级人民政府报告有关国有资产总量、结构、变动、收益等情况。","level":1},{"name":"第三章 国家出资企业","text":"第九条 本条例所称国家出资企业，是指各级人民政府出资的国有独资企业、国有独资公司，以及国有资本控股公司、国有资本参股公司。\n第十条 国家出资企业应当依法建立和完善法人治理结构。\n国家出资企业应当加强董事会的建设，建立外部董事和独立董事制度，优化董事会结构，确立董事会在法人治理结构中的核心地位。\n国家出资企业应当依法设立监事会。国有独资企业、国有独资公司监事会由履行出资人职责的机构委派的监事和职工代表共同组成，其中职工代表的比例不得低于三分之一。监事会主席由履行出资人职责的机构从监事会成员中指定。\n第十一条 国家出资企业对其动产、不动产和其他财产依照法律、法规以及企业章程享有占有、使用、收益及处分的权利。\n国家出资企业依法享有的法人财产权、经营自主权和其他合法权益受法律保护。履行出资人职责的机构应当确保出资到位，不得干预企业的日常经营管理活动。\n第十二条 国家出资企业根据公司章程，自主决定企业的日常经营管理，组织实施企业的经营计划，决定企业内部机构设置、人员聘用，制定公司基本管理制度。\n第十三条 国家出资企业应当加快以企业为主体的技术创新体制机制建设，加大研究与开发的投入，加强关键性、战略性技术的消化吸收和自主创新力度，增强持续创新能力。\n第十四条 国家出资企业应当建立健全内部监督管理制度，加强财务管理和审计监督，接受人民政府及其有关部门、机构依法实施的管理和监督，接受社会公众的监督，承担社会责任，对出资人负责。\n第十五条 国家出资企业依照法律规定，通过职工代表大会、工会或者其他形式，实行民主管理，维护职工合法权益。\n第十六条 国家出资企业应当加强全面风险管理，围绕企业总体经营目标，设立专职部门或者确定相关职能部门履行全面风险管理的职责，建立岗位授权、逐级审批等内部控制制度，建立健全全面风险管理体系。\n国家出资企业应当定期对风险管理工作进行自查，及时发现缺陷并改进。\n第十七条 国有独资企业、国有独资公司、国有资本控股公司应当建立健全企业法律顾问制度。\n大型国有独资企业、国有独资公司、国有资本控股公司应当设置专门的法律事务机构，配备企业总法律顾问，其他企业应当明确法律事务机构，配备企业法律顾问。\n第十八条 各级人民政府及其有关部门应当尊重和维护国家出资企业经营自主权，依法履行市场监管、社会管理、公共服务、行业指导等职能，建立和完善服务企业的相关制度，优化企业发展环境。","level":1},{"name":"第四章 国家出资企业管理者的选择、聘用与考核","text":"第十九条 履行出资人职责的机构应当建立健全适应现代企业制度要求的国家出资企业管理者选择、聘用、考核和激励约束机制。\n第二十条 履行出资人职责的机构依照有关规定，任免或者建议任免国家出资企业的下列人员：\n（一）任免国有独资企业的经理（厂长）、副经理（副厂长）、总会计师、总法律顾问和其他高级管理人员；\n（二）任免国有独资公司的董事长、副董事长、董事、监事会主席和监事；\n（三）依照公司章程，向国有资本控股公司、国有资本参股公司的股东会、股东大会提出董事、监事人选，推荐国有资本控股公司的董事长、副董事长和监事会主席人选。\n国家出资企业中应当由职工代表出任的董事、监事，依照有关法律、法规的规定由职工民主选举产生。\n第二十一条 履行出资人职责的机构任命或者建议任命的董事、监事、高级管理人员，应当具备下列条件：\n（一）遵守宪法、法律，履行忠实义务和勤勉义务；\n（二）有符合职位要求的专业知识和工作能力；\n（三）有能够正常履行职责的身体条件；\n（四）法律、法规规定的其他条件。\n董事、监事、高级管理人员在任职期间出现不符合前款规定情形或者出现《中华人民共和国公司法》规定的不得担任公司董事、监事、高级管理人员情形的，履行出资人职责的机构应当依法予以免职或者提出免职建议。\n第二十二条 未经履行出资人职责的机构同意，国有独资企业、国有独资公司的董事、高级管理人员不得在其他企业兼职。未经股东会、股东大会同意，国有资本控股公司、国有资本参股公司的董事、高级管理人员不得在经营同类业务的其他企业兼职。\n未经履行出资人职责的机构同意，国有独资公司的董事长不得兼任经理。未经股东会、股东大会同意，国有资本控股公司的董事长不得兼任经理。\n董事、高级管理人员不得兼任监事。\n第二十三条 履行出资人职责的机构应当建立国家出资企业管理者优胜劣汰机制，按照公开、平等、竞争、择优的原则，采取组织选拔、竞争上岗、公开招聘等方式任免或者建议任免本条例第二十条第一款所列人员。\n对年度和任期内考核不合格或者不适应岗位需要的，依照法定程序予以免职或者解聘。\n第二十四条 履行出资人职责的机构应当建立健全国家出资企业管理者经营业绩考核制度，按年度和任期实行分类考核。\n第二十五条 履行出资人职责的机构应当构建年薪制、股权激励、特别贡献奖等多种分配方式并存的企业管理者薪酬制度，将业绩考核结果与国有独资企业、国有独资公司、国有资本控股公司管理者的薪酬挂钩。\n建立健全国家出资企业管理者薪酬与职工薪酬增长的协调联动机制，促进企业收入分配公平合理。\n第二十六条 省人民政府应当深化国家出资企业改革，就企业家培育，企业管理者聘用、薪酬、奖励、股权激励机制等制定具体办法。","level":1},{"name":"第五章 关系国有资产出资人权益的重大事项","text":"第二十七条 关系国有资产出资人权益的重大事项是指：\n（一）企业合并、分立、改制、上市、解散、申请破产；\n（二）增加或者减少注册资本；\n（三）发行股票、公司债券；\n（四）企业年度财务预算、决算和利润分配；\n（五）企业重大投融资、为他人提供大额担保、资产转让、大额捐赠；\n（六）确定发展战略和主营业务范围；\n（七）企业收入分配及管理者的薪酬；\n（八）法律、法规和企业章程规定的其他重大事项。\n国家出资企业的改制、关联交易、资产评估、资产转让等重大事项依照《中华人民共和国企业国有资产法》进行。\n第二十八条 国家出资企业重大事项的决策应当经过专家论证、经理办公会讨论、董事会决策、股东会决定等法定程序。\n国家出资企业重大事项涉及政府公共管理审批事项的，应当先报经政府或者政府有关部门审批；对涉及面广、关系公众利益的重大事项，应当由政府或者政府有关部门组织专家论证、公示听证；对关系职工切身利益的重大事项，应当听取企业工会的意见，并通过职工代表大会或者其他形式听取职工的意见和建议。\n第二十九条 国有独资企业、国有独资公司有本条例第二十七条第一款第（一）项至第（四）项规定的重大事项，由履行出资人职责的机构决定。\n第三十条 国有独资企业、国有独资公司有本条例第二十七条第一款所列事项，除依照本条例第二十九条和有关法律、法规和企业章程的规定由履行出资人职责的机构决定外，国有独资企业由企业负责人集体讨论决定，国有独资公司由董事会决定，并应当自该事项决定之日起15日内报履行出资人职责的机构备案。\n国有独资企业、国有独资公司报送备案的重大事项违反法律、法规、企业章程的，履行出资人职责的机构应当督促纠正。\n第三十一条 国有资本控股公司、国有资本参股公司的重大事项，依照法律、法规和公司章程的规定，由公司股东会、股东大会或者董事会决定。履行决策程序时，履行出资人职责的机构委派的董事、股东代表应当按照委派机构的指示发表意见，行使表决权。\n第三十二条 国有独资企业、国有独资公司、国有资本控股公司的重大事项，根据法律、法规和本级人民政府规定应当报经本级人民政府批准的，履行出资人职责的机构在作出决定或者向其委派参加国有资本控股公司股东会会议、股东大会会议的股东代表作出指示前，应当依照法定程序报请本级人民政府批准。\n第三十三条 国有独资企业、国有独资公司、国有资本控股公司对本条例第二十七条第一款第（一）、（三）、（五）项重大事项履行决策程序时，应当向履行出资人职责的机构提供法律意见书，分析相关的法律风险，明确法律责任。","level":1},{"name":"第六章 国有资本经营预算","text":"第三十四条 县级以上人民政府建立国有资本经营预算制度，对国有资本收入及其支出实行预算管理。\n第三十五条 国家出资企业应当依照国家有关法律法规和企业章程分配利润，履行出资人职责的机构应当监督国家出资企业及时、足额上缴国有资本收入。\n第三十六条 县级以上人民政府的国有资本收入以及支出，应当编制国有资本经营预算。\n国有资本经营预算的收入包括：\n（一）国有独资企业、国有独资公司按规定上缴的利润；\n（二）国有资本控股公司、国有资本参股公司中国有股应分得的股息、红利；\n（三）国家出资企业国有资产转让净收入；\n（四）国家出资企业清算取得的净收入；\n（五）本级人民政府调入的收入；\n（六）其他收入。\n国有资本经营预算的支出包括：\n（一）费用性支出，即国家出资企业改革成本支出、履行出资人职责的机构的监管费用支出等；\n（二）资本性支出，即对国家出资企业和重点产业资本性投入等；\n（三）县级以上人民政府规定的其他支出。\n第三十七条 国有资本经营预算按年度单独编制，纳入本级人民政府预算，报本级人民代表大会批准。\n国有资本经营预算支出按照当年预算收入规模安排，不列赤字。\n第三十八条 县级以上人民政府财政部门负责国有资本经营预算草案的编制工作，履行出资人职责的机构向财政部门提出国有资本经营预算建议草案。","level":1},{"name":"第七章 国有资产监督","text":"第三十九条 各级人民代表大会常务委员会通过听取和审议本级人民政府履行出资人职责的情况和国有资产监督管理情况的专项工作报告，组织对本条例实施情况的执法检查，依法行使监督职权。\n第四十条 县级以上人民政府应当对其授权履行出资人职责的机构履行出资人职责的情况进行监督、考核和评价。\n第四十一条 审计机关应当对国有独资企业、国有独资公司、国有资本控股公司的财务收支进行监督，并对其管理者进行任期经济责任审计。\n第四十二条 县级以上人民政府应当向社会公众公布国有资产状况和国有资产监督管理工作情况，接受社会公众的监督。任何单位和个人有权对造成国有资产损失的行为向有关部门进行检举和控告。\n第四十三条 履行出资人职责的机构依照国家和省有关规定，负责国有资产的产权界定、产权登记、清产核资、资产统计、资产评估监管、综合评价等基础管理工作，对国有资产产权交易进行监督管理。\n履行出资人职责的机构应当编制本级人民政府国家出资企业的国有资产统计报告，并与国家出资企业的分户统计数据一同报送上级人民政府履行出资人职责的机构。\n第四十四条 履行出资人职责的机构依照国家和省规定的评价体系、标准和方法，对国家出资企业经营绩效进行评价，对国有资本保值增值结果进行确认。\n未经评价的经营绩效和未经确认的国有资本保值增值结果，不得作为国家出资企业业绩考核和工资总额确定等的依据。\n第四十五条 履行出资人职责的机构应当建立国家出资企业境外国有资产监督管理制度，规范企业境外投资及境外国有资产的登记、转让、考核等各项基础工作，强化风险防范和责任追究。\n第四十六条 履行出资人职责的机构应当建立国家出资企业涉诉国有资产监督管理制度。国家出资企业涉诉国有资产需要处置的，应当依法公开竞价处置。\n第四十七条 国家出资企业应当按照产权权属关系向履行出资人职责的机构申请办理国有资产产权登记，如实反映本企业国有资产经营情况。\n履行出资人职责的机构收到国家出资企业提交的符合产权登记规定的全部文件、资料后，在10日内作出核准产权登记或者不准予产权登记的决定；对不予登记的，应当自作出决定之日起3日内通知登记申请人，并说明原因。\n第四十八条 国家出资企业发生需要进行资产评估的事项时，由产权持有单位委托有资质的资产评估机构进行评估，履行出资人职责的机构应当按照国家规定的程序对资产评估结果进行核准或者备案。\n履行出资人职责的机构收到企业报送的国有资产评估结果后，对符合核准或者备案要求的，应当在20日内办理核准或者备案手续。\n第四十九条 国家出资企业的国有产权转让应当在依法设立的产权交易机构公开进行，不受地区、行业、出资或者隶属关系的限制。\n国家出资企业转让全部国有产权或者转让国有产权致使国家不再拥有控股地位的，应当报经本级人民政府批准。\n第五十条 国有独资企业、国有独资公司之间国有产权无偿划转，产权在同一履行出资人职责的机构监管的，由国家出资企业共同报履行出资人职责的机构批准。产权在不同履行出资人职责的机构监管的，依据划转双方的产权归属关系，由国家出资企业分别报同级履行出资人职责的机构批准。\n第五十一条 履行出资人职责的机构应当建立争端协调机制，协调国家出资企业之间、国家出资企业与其他企业之间的产权、债务、合同等纠纷。\n国家出资企业对其产权、债务、合同等纠纷，可以依法申请仲裁或者提起诉讼。\n第五十二条 省人民政府履行出资人职责的机构应当制定国家出资企业国有资产损失责任追究办法，报省人民政府批准后实施。","level":1},{"name":"第八章 法律责任","text":"第五十三条 违反本条例规定，法律、行政法规已有处罚规定的，从其规定。\n第五十四条 履行出资人职责的机构违反本条例规定，未依法履行出资人职责，违法干预企业生产经营，或者收受贿赂、徇私舞弊等造成国有资产损失的，对直接责任人和其他相关责任人依法给予处分；构成犯罪的，依法追究刑事责任。\n第五十五条 国有独资企业、国有独资公司、国有资本控股公司的管理者有下列行为之一，造成国有资产损失的，除依法承担赔偿责任外，履行出资人职责的机构应当对管理权限内的相关责任人扣发绩效薪金（奖金）或者予以处分，并视情节依法给予不得担任国有独资企业、国有独资公司、国有资本控股公司管理者的限制；对管理权限以外的责任人，由履行出资人职责的机构向相关部门提出处理建议：\n（一）利用职权收受贿赂或者取得其他非法收入和不当利益的；\n（二）侵占、挪用企业资产的；\n（三）在企业改制、财产转让等过程中，违反法律、法规和公平交易规则，将企业财产低价转让、低价折股的；\n（四）违反规定与本企业进行交易的；\n（五）不如实向资产评估机构、会计师事务所提供有关情况和资料，或者与资产评估机构、会计师事务所串通出具虚假资产评估报告、审计报告的；\n（六）违反法律、法规和企业章程规定的决策程序，决定企业重大事项的；\n（七）未经履行出资人职责的机构或者股东会、股东大会同意，在其他企业兼职的；\n（八）其他违反法律、法规和企业章程执行职务行为的。\n国家出资企业的管理者因前款所列行为取得的收入，依法予以追缴或者归国家出资企业所有。","level":1},{"name":"第九章 附则","text":"第五十六条 本条例自2011年8月1日起施行。","level":1}]},{"id":"h0150","sections":[{"name":"","text":"（2011年8月3日湖北省第十一届人民代表大会常务委员会第二十五次会议通过 根据2020年6月3日湖北省第十三届人民代表大会常务委员会第十六次会议《关于集中修改、废止涉及取消证明事项的部分省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了加强和规范法律援助工作，保障经济困难公民和其他符合法定条件的公民获得法律服务和帮助，促进社会公平正义与和谐社会建设，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内的法律援助活动，适用本条例。\n本条例所称法律援助，是指县级以上人民政府在司法行政部门设立的法律援助机构，组织法律服务机构或者法律服务人员，依法为经济困难公民和其他符合法定条件的公民，无偿提供法律咨询、代理、刑事辩护等法律服务的活动。\n法律服务机构包括律师事务所、基层法律服务所、公证机构、司法鉴定机构等。\n法律服务人员包括法律援助专职律师、律师事务所律师、基层法律服务工作者、公证员、司法鉴定人和法律援助志愿者。\n受援人，是指依法获得法律援助的公民。\n第三条 法律援助是政府的责任。县级以上人民政府应当将法律援助作为社会建设的重要内容，纳入国民经济和社会发展规划，建立健全覆盖城乡的法律援助服务体系，加强法律援助队伍建设；按照政府统一领导、部门配合、各负其责的原则，建立完善法律援助工作协调机制和目标管理责任制；将法律援助经费列入同级财政预算，逐步增加投入，保障法律援助事业与经济社会协调发展。\n第四条 省财政按照国家有关规定设立法律援助专项补助资金，扶持农村贫困地区、少数民族地区和革命老区开展法律援助。\n县级以上人民政府通过设立法律援助专项资金，多渠道筹集吸收社会捐助资金和社会公益资金，鼓励企业事业单位、其他社会组织和个人为法律援助事业提供捐助。\n法律援助经费以及相关专项资金应当专款专用，经费使用情况接受财政、审计等部门的监督，并向社会公示。\n第五条 县级以上人民政府司法行政部门监督管理本行政区域的法律援助工作。\n法律援助机构具体负责受理、审查法律援助申请，指派法律服务机构或者法律服务人员为符合条件的公民提供法律援助，并对其开展法律援助活动进行指导和监督。\n第六条 人民法院、人民检察院以及公安、财政、民政、人力资源和社会保障、卫生健康、市场监督管理、信访等国家机关，根据各自职责做好有关法律援助工作。\n乡镇人民政府、街道办事处以及社区、村（居）民委员会应当支持配合法律援助机构做好法律援助工作，并为辖区内需要法律援助的公民提供帮助。\n第七条 工会、共青团、妇联、残联等社会团体应当结合工作实际，为相关群体提供有关的法律服务。法律援助机构应当予以支持和帮助。\n鼓励、支持高等院校、企业事业单位以及其他社会组织利用自身资源，依法开展法律服务活动。鼓励、支持具有法律职业资格和法律专业知识、法律工作经验的人员参与法律援助活动。\n第八条 各级人民政府及司法行政部门应当加强法律援助制度宣传，普及法律援助知识，提高公民依法维护自身权益的意识和能力。\n新闻出版、广播电视、网络等公众媒体应当将法律援助作为公益性宣传的重要内容，为法律援助工作营造良好的社会氛围。\n第九条 县级以上人民政府及其司法行政部门对在法律援助工作中做出突出贡献的单位和个人予以表彰奖励。","level":1},{"name":"第二章 法律援助范围","text":"第十条 公民对下列事项需要代理，因经济困难没有委托代理人的，可以向法律援助机构申请法律援助：\n（一）依法请求国家赔偿的；\n（二）请求给予社会保险待遇或者最低生活保障待遇的；\n（三）请求发给抚恤金、救助金的；\n（四）请求给付赡养费、抚养费、扶养费的；\n（五）请求支付劳动报酬和维护其他劳动保障权益的；\n（六）主张因见义勇为行为或者为保护社会公共利益产生民事权益的；\n（七）因遭受家庭暴力、虐待、遗弃主张民事权益的；\n（八）因交通事故、工伤事故、医疗损害、食品安全、环境污染、产品质量以及农业生产资料等造成人身损害或者财产损失请求赔偿的；\n（九）国家和省规定的其他事项。\n市州、县人民政府根据本地实际，可以对前款规定以外的法律援助事项作出补充规定。\n第十一条 刑事诉讼中，犯罪嫌疑人、公诉案件中的被告人、公诉案件中的被害人及其法定代理人或者近亲属，以及自诉案件中的自诉人及其法定代理人，因经济困难没有聘请律师或者委托诉讼代理人的，可以向法律援助机构申请法律援助。\n第十二条 公诉人出庭公诉的案件，被告人因经济困难或者其他原因没有委托辩护人，人民法院为被告人指定辩护时，法律援助机构应当提供法律援助。\n被告人是盲、聋、哑人或者未成年人而没有委托辩护人的，或者被告人可能被判处死刑而没有委托辩护人的，人民法院为被告人指定辩护时，法律援助机构应当提供法律援助，无须对被告人进行经济状况的审查。\n第十三条 公民经济困难的标准，按照受理申请的法律援助机构所在县（市、区）公布的城乡居民最低生活保障标准的1.5倍以内执行。\n申请人因遭遇自然灾害等因素造成临时性经济困难的，其经济困难标准由法律援助机构参照前款规定，根据实际情况认定。\n因遭受家庭暴力、虐待、遗弃主张民事权益，申请法律援助的，其经济困难标准以申请人的个人经济困难状况为准。\n第十四条 人民法院、人民检察院、公安、信访等国家机关以及法律服务机构在工作过程中，发现当事人符合法律援助条件的，应当告知其可以向法律援助机构申请法律援助。","level":1},{"name":"第三章 法律援助申请和审查","text":"第十五条 公民申请法律援助由本人或者其委托人直接向法律援助机构提出；确有困难的，也可采用电话申请、邮寄申请、网上申请以及由法律援助机构上门受理等方式。\n采用电话申请、邮寄申请、网上申请等方式的，法律援助机构应当作书面记载。作出提供法律援助决定后，应当通知申请人进行书面确认，并按规定补办有关手续。\n第十六条 法律援助机构应当建立便民服务场所，开设申请法律援助服务窗口，完善无障碍配套服务设施，面向公众公开申请法律援助的事项范围、条件、程序、材料目录以及监督投诉电话，方便公民申请法律援助。\n第十七条 公民申请法律援助的事项属于诉讼事项的，向审理案件的人民法院所在地的法律援助机构提出；属于侦查或者审查起诉阶段刑事案件的，向办理案件的公安机关或者人民检察院所在地的法律援助机构提出。\n公民申请法律援助的事项属于非诉讼法律事项的，可以向有权处理机关所在地、申请人住所地或者事项发生地的法律援助机构提出。\n两个以上法律援助机构都可以受理法律援助申请的，申请人可以向其中任何一个法律援助机构提出申请。申请人就同一事项向两个以上法律援助机构提出申请的，由最先收到申请的法律援助机构受理。\n第十八条 被羁押的犯罪嫌疑人、被告人、服刑人员申请法律援助的，可以通过公安机关、人民检察院、人民法院或者监狱向法律援助机构提出。\n公安机关、人民检察院、人民法院或者监狱收到被羁押的犯罪嫌疑人、被告人、服刑人员提出的法律援助申请后，应当在24小时内转交有关法律援助机构。\n第十九条 申请人为无民事行为能力人或者限制民事行为能力人的，由其法定代理人代为提出申请。申请人没有法定代理人或者其法定代理人不履行申请义务的，由其住所地村（居）民委员会或者法律、法规规定的其他组织、人员代为提出申请。\n第二十条 公民申请法律援助应当提供下列材料：\n（一）身份证或者其他有效的身份证明，代理申请人还应当提交有代理权的证明；\n（二）经济困难承诺书；\n（三）与申请法律援助事项有关的材料。\n经济困难承诺书应当载明申请人家庭人口状况、就业状况、家庭财产、家庭人均收入等信息。\n第二十一条 法律援助机构收到法律援助申请后，应当及时进行审查，并根据下列情形作出处理：\n（一）对申请材料齐全、权利主张合法、事实清楚、证据充分的，当场作出提供法律援助的决定；\n（二）对申请材料不齐全的，应当一次性告知申请人作出补充或者说明；需要查证相关资料的，由法律援助机构予以查证；\n（三）对涉及重大疑难事项或者其他特殊案件的，应当在5日内作出是否提供法律援助的决定；\n（四）对不符合法律援助条件的，应当在5日内书面告知申请人并说明理由。\n第二十二条 申请人有下列情形之一的，法律援助机构可以直接认定为符合法律援助条件，无须出具经济困难承诺书：\n（一）属于农村五保供养对象的；\n（二）正在领取最低生活保障金、孤儿保障金或者生活困难救助金的；\n（三）在社会福利机构由政府供养的；\n（四）无固定生活来源的城镇零就业家庭，有特殊困难的残疾人、老年人、患有重大疾病的人；\n（五）农村进城务工人员请求支付劳动报酬或者工伤赔偿的；\n（六）主张因见义勇为行为或者为保护社会公共利益产生民事权益的。\n第二十三条 申请人有下列情形之一的，法律援助机构可以先行提供法律援助，事后由申请人补交有关材料：\n（一）申请人面临重大人身或者财产损害危险的；\n（二）申请事项法定期限即将届满的；\n（三）有其他紧急或者特殊情形的。\n第二十四条 申请人以人民法院司法救助决定书为依据申请法律援助，且符合本条例第十条、第十一条规定情形的，法律援助机构应当直接给予法律援助。受援人以法律援助机构的法律援助决定书为依据申请司法救助的，人民法院应当直接给予司法救助。\n第二十五条 申请人对法律援助机构作出不予法律援助的决定有异议的，可以自收到决定之日起15日内向主管该法律援助机构的司法行政部门申请复查，司法行政部门应当自收到复查申请之日起5日内进行复查。经复查认为申请人符合法律援助条件的，应当书面通知法律援助机构变更决定，及时向申请人提供法律援助，并告知申请人；认为不符合法律援助条件，维持法律援助机构决定的，应当将理由书面告知申请人。","level":1},{"name":"第四章 法律援助实施","text":"第二十六条 法律援助一般采取下列方式：\n（一）法律咨询、代拟法律文书；\n（二）刑事辩护、刑事代理；\n（三）民事、行政诉讼代理；\n（四）行政复议代理，劳动、人事争议仲裁代理和其他非诉讼法律事务代理；\n（五）公证援助和司法鉴定援助；\n（六）法律、法规规定的其他法律援助形式。\n第二十七条 由人民法院指定辩护的案件，人民法院在开庭10日前将指定辩护通知书和起诉书副本或者判决书副本送交法律援助机构；法律援助机构应当在收到指定辩护通知书等材料后及时指派法律服务人员，并在开庭3日前告知作出指定的人民法院。\n第二十八条 法律服务人员在办理法律援助案件时，凭法律援助公函查阅有关档案资料，有关单位应当给予配合和协助，国家机关、国有企业事业单位和社会团体应当免收相关查询、咨询、复制等费用。\n第二十九条 法律服务人员遇有下列情形之一的，应当向法律援助机构报告，法律援助机构经审查核实的，应当终止该项法律援助：\n（一）以欺骗、隐瞒事实或者其他不正当手段申请获得法律援助的；\n（二）先行提供法律援助时，发现受援人不符合法律援助条件的；\n（三）受援人的经济状况发生变化，不再符合法律援助条件的；\n（四）案件终止审理或者已被撤销的；\n（五）受援人另行委托律师或者其他代理人的；\n（六）受援人要求终止法律援助的；\n（七）受援人隐瞒与法律援助案件有关的情况，不协助、不配合法律援助机构和法律服务人员，使法律援助工作难以继续开展的。\n终止法律援助的，应当书面告知受援人，并说明理由。受援人有异议的，可以按照本条例第二十五条的规定申请复查。\n第三十条 法律服务人员从事法律援助应当恪守职业道德和执业纪律，依法维护受援人的合法权益，并不得实施下列行为：\n（一）无正当理由拒绝接受、拖延或者擅自终止实施法律援助；\n（二）向受援人收取财物或者牟取其他不正当利益；\n（三）对受援人隐瞒法律援助案件的进展情况；\n（四）泄露当事人的隐私。\n第三十一条 受援人有权向法律援助机构、法律服务机构或者法律服务人员了解法律援助案件的进展情况。法律服务人员没有依法履行职责的，受援人可以要求更换，法律援助机构经确认后应当另行安排法律服务人员提供法律援助。\n受援人应当配合法律服务人员开展法律援助工作，如实向办理法律援助案件的法律服务人员陈述与法律援助案件有关的情况，提供相关证据材料。\n受援人在受援期间因经济状况改善不再符合法律援助条件的，应当告知法律援助机构。\n第三十二条 受援人申请仲裁、公证、司法鉴定的，有关仲裁机构、公证机构、司法鉴定机构应当依照有关规定减免相关费用。\n第三十三条 办理法律援助案件的法律服务人员在案件结案时，应当及时向法律援助机构提交有关的法律文书、结案报告等材料。法律援助机构应当及时审查，并根据审查和案件情况支付办案补贴。\n法律援助办案补贴标准由省司法行政部门会同省财政部门，根据法律援助案件的平均成本等因素核定。办案补贴标准可以根据需要进行调整。\n第三十四条 司法行政部门及其法律援助机构应当按照规范、便捷、效率的原则，完善法律援助受理、审批、指派、承办等工作程序、工作制度和服务标准，提高法律援助的质量和效率。\n建立健全各级法律援助机构以及法律援助机构与相关国家机关、社会团体互联互通的法律援助信息平台，实现法律援助信息资源共享，畅通法律援助渠道。\n第三十五条 司法行政部门应当建立健全法律援助质量管理制度，制定办理法律援助案件的质量标准，开展法律援助质量监督、检查和评估，并以适当方式定期将法律援助情况向社会公布，接受社会监督。","level":1},{"name":"第五章 法律责任","text":"第三十六条 违反本条例，法律、行政法规有处罚规定的，从其规定。\n第三十七条 法律援助机构及其工作人员有下列情形之一的，对直接负责的主管人员以及其他直接责任人员依法给予处分；有违法所得的，没收违法所得；情节严重，构成犯罪的，依法追究刑事责任：\n（一）为不符合法律援助条件的人员提供法律援助，或者拒绝为符合法律援助条件的人员提供法律援助的；\n（二）办理法律援助案件收取财物或者牟取其他不正当利益的；\n（三）从事有偿法律服务的；\n（四）对受援人隐瞒法律援助案件进展情况的；\n（五）泄露当事人隐私的；\n（六）侵占、私分、挪用法律援助经费的。\n办理法律援助案件违法收取的财物，由司法行政部门责令退还；侵占、私分、挪用法律援助经费的，由司法行政部门责令追回。\n第三十八条 律师事务所拒绝法律援助机构的指派，不安排本所律师办理法律援助案件的，由司法行政部门给予警告、责令改正；情节严重的，责令停业整顿1个月以上3个月以下。\n律师无正当理由拒绝接受、擅自终止法律援助案件或者办理法律援助案件收取财物的，由司法行政部门给予警告、责令改正，退还违法收取的财物，可并处所收财物价值1倍以上3倍以下的罚款；情节严重的，责令停止执业1个月以上3个月以下。\n第三十九条 公民以隐瞒、欺骗或者其他不正当手段获得法律援助的，法律援助机构在终止法律援助后，应当向当事人追收相关法律援助费用。\n第四十条 有关国家机关、国有企业事业单位和社会团体以及仲裁机构、公证机构、司法鉴定机构，对法律援助事项，未按本条例规定减免相关费用的，由其主管部门责令改正，限期退还收取的费用。\n第四十一条 司法行政部门、其他有关国家机关的工作人员在法律援助工作中，未按照本条例规定履行相应职责的，由其所在单位或者上级主管部门责令改正，情节严重的，对直接负责的主管人员和直接责任人员给予处分。","level":1},{"name":"第六章 附则","text":"第四十二条 本条例自2011年10月1日起施行。","level":1}]},{"id":"h0151","sections":[{"name":"","text":"（2011年8月3日湖北省第十一届人民代表大会常务委员会第二十五次会议通过 根据2011年12月1日湖北省第十一届人民代表大会常务委员会第二十七次会议《关于修改部分地方性法规中行政强制规定的决定》第一次修正 根据2014年9月25日湖北省第十二届人民代表大会常务委员会第十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止废止部分省本级地方性法规的决定》第三次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了加强城乡规划管理，统筹城乡空间布局，改善人居环境，促进资源节约型、环境友好型社会建设，推进工业化、城镇化和农业现代化全面发展，根据《中华人民共和国城乡规划法》（以下简称《城乡规划法》）等法律、行政法规，结合本省实际，制定本条例。\n第二条 在本省行政区域内制定和实施城乡规划，在规划区内进行建设活动，适用本条例。\n本条例所称城乡规划，包括城镇体系规划、城市规划、镇规划、乡规划和村庄规划。城镇体系规划分为省域城镇体系规划、跨行政区域城镇体系规划、市（县）域城镇体系规划。城市规划、镇规划分为总体规划和详细规划。详细规划分为控制性详细规划和修建性详细规划。\n本条例所称规划区，是指城市、镇、乡和村庄的建成区以及因城乡建设和发展需要，必须实行规划控制的区域。\n第三条 城市和镇、乡应当依照《城乡规划法》和本条例编制城市规划、镇规划、乡规划。\n县级以上人民政府确定需要编制规划的村庄，应当编制村庄规划。其他村庄根据发展需要编制村庄规划，但城市总体规划、镇总体规划、乡规划确定的建设用地范围内的村庄，不单独编制村庄规划。\n第四条 制定和实施城乡规划，应当按照科学发展的要求，遵循城乡统筹、合理布局、节约土地、集约发展和先规划后建设的原则，注重保护生态环境，促进资源、能源节约和综合利用，保护历史文化遗产，体现地方特色和民族特色，保持传统风貌，并符合区域人口发展、国防建设、防灾减灾和公共卫生、公共安全的需要。\n第五条 城乡规划的编制应当依据国民经济和社会发展规划，与土地利用总体规划相衔接，体现主体功能区规划的要求，并处理好与交通、水利等相关规划的关系。\n城乡规划应当采取政府组织、部门合作、专家领衔、公众参与、科学决策的方式编制，并通过本行政区域的主要报刊、广播电视、网站等新闻媒体向社会公布。\n经依法批准的城乡规划必须严格执行，不得擅自修改；确需修改的，应当依照法定程序和权限进行。\n第六条 城乡规划工作是政府的重要职责。各级人民政府应当将城乡规划工作纳入国民经济和社会发展规划及年度计划，实行行政首长负责制，建立健全规划执行责任追究制度，确保城乡规划实行集中统一管理。\n各级人民政府应当加强城乡规划管理机构和人员队伍建设，将城乡规划的编制和管理经费纳入本级财政预算。跨区域的城乡规划编制经费，由共同的上一级人民政府统筹保障。\n省人民政府对贫困地区、少数民族地区和革命老区的镇、乡、村庄规划编制经费，予以资金补助。\n第七条 省人民政府城乡规划主管部门负责全省的城乡规划管理工作。\n县级以上人民政府城乡规划主管部门负责本行政区域内的城乡规划管理工作，其他有关行政主管部门按照各自职责做好城乡规划管理的相关工作。\n市辖区、各类开发区（园区）不设城乡规划管理机构；确需设立的，可由上一级人民政府城乡规划主管部门设置派出机构，具体负责该区域的城乡规划管理工作。\n乡、镇应当明确相关机构或者人员，依法承担有关城乡规划管理工作；县级以上人民政府及其城乡规划主管部门应当予以指导和帮助。\n第八条 县级以上人民政府应当建立由相关管理人员、专家学者和公众代表组成的城乡规划委员会。城乡规划委员会受本级人民政府委托，就城乡规划的重大问题进行审议、审查，提出意见。\n第九条 鼓励开展城乡规划科学技术研究，推广和应用先进技术、先进理念，推进城乡规划科学化、标准化、信息化。\n城乡规划主管部门应当建立规划管理信息系统，促进各有关行政管理部门之间的信息共享，保障城乡规划的科学制定、有效实施。\n第十条 城乡规划管理实行岗位证书制度，城乡规划管理人员必须持证上岗。具体办法由省人民政府城乡规划主管部门会同省人民政府人力资源和社会保障部门制定。","level":1},{"name":"第二章 城乡规划的制定与修改","text":"第十一条 省人民政府组织编制省域城镇体系规划，报国务院审批。\n跨行政区域的城镇体系规划和城市群规划、城市密集区规划等其他区域性规划，由共同上一级人民政府城乡规划主管部门负责组织编制，报本级人民政府审批。武汉城市圈规划由省有关部门会同城市圈有关城市人民政府共同组织编制，按照有关规定审批。\n市（县）域城镇体系规划由市（县）人民政府组织编制，报省人民政府审批，国家另有规定的除外。\n省人民政府及有条件的市（县）根据经济社会发展情况，适时组织编制城乡总体规划，推进城乡居民点和产业结构、基础设施以及社会事业的合理布局、科学协调发展，实现城乡规划全覆盖。城乡总体规划审查、报批程序按照城市总体规划有关程序执行。\n第十二条 市（县）人民政府在编制市（县）域城镇体系规划时，应当提出市（县）域村庄布局的指导意见。编制镇总体规划、乡规划应当同步制定镇、乡的村庄布局规划。\n第十三条 城市人民政府负责组织编制城市总体规划。省会城市及国务院确定的城市的总体规划，由省人民政府审查同意后，报国务院审批。其他城市的总体规划，由城市人民政府报省人民政府审批。\n省人民政府根据需要确定的镇以及神农架林区人民政府驻地镇的总体规划，由所在地县级人民政府组织编制，报省人民政府审批。县人民政府所在地镇的总体规划由县人民政府组织编制，报上一级人民政府审批。其他镇的总体规划由县级人民政府城乡规划主管部门、镇人民政府共同组织编制，报县级人民政府审批。\n第十四条 城镇体系规划、城市总体规划在报送审批前，应当先经本级人民代表大会常务委员会审议；镇总体规划、乡规划在报送审批前，应当先经镇、乡人民代表大会审议。常委会组成人员、代表的审议意见交由本级人民政府研究处理。\n乡规划、村庄规划由县级人民政府城乡规划主管部门、乡级人民政府共同组织编制，报县级人民政府审批。村庄规划报送审批前，应当经村民会议或者村民代表会议讨论同意。\n乡规划、村庄规划应当从实际出发，体现农村特色和新农村建设的要求，优先安排基础设施和公共服务设施。\n第十五条 城市、县人民政府城乡规划主管部门组织编制城市、县人民政府所在地镇的控制性详细规划，经本级人民政府批准后，报本级人民代表大会常务委员会和上一级人民政府备案。其他镇的控制性详细规划由镇人民政府组织编制，经上一级人民政府批准。\n编制控制性详细规划，应当依据城市总体规划、镇总体规划，具体规定各项控制指标和规划管理要求。\n控制性详细规划不得改变城市、镇总体规划的强制性内容；确需改变的，应当先按照程序修改城市、镇总体规划。\n第十六条 城市、县人民政府城乡规划主管部门应当组织编制重要街区、重点景观区、广场、公园、重要交通枢纽、城镇主要出入口、大型公共设施以及其他重要地块的修建性详细规划。对于涉及公共利益且投资规模较大的特别重要地块的修建性详细规划，应当先经本级人民代表大会常务委员会审议。\n其他修建性详细规划由建设单位组织编制。\n修建性详细规划应当符合控制性详细规划。\n第十七条 市（县）人民政府的有关部门应当会同城乡规划主管部门，依据城市总体规划组织编制专项规划，并依照相关规定审批，报本级人民代表大会常务委员会备案。\n国家、省风景名胜区和历史文化名城（镇、村）保护，应当单独编制规划，并按照有关规定审批。\n各级人民政府对本行政区域内风景名胜区和历史文化名城（镇、村）规划研究和编制工作，应当给予资金保障。\n第十八条 编制城乡规划应当包含“绿线、紫线、蓝线、黄线”等规划，并建立相应管理制度。\n第十九条 省会城市的城市规划应当统筹考虑省级以上国家机关用地布局和空间安排的需要。\n第二十条 各级人民政府及城乡规划主管部门应当按照公开、公平、公正的原则择优确定承担城乡规划编制任务的单位。承担城乡规划编制任务的单位应当具备相应的城乡规划编制资质，对规划编制质量负责。\n第二十一条 编制城乡规划应当执行国家、省有关技术规范和规定，组织科学论证。\n编制城乡规划应当按照规定进行环境影响评价，充分考虑防御灾害的需要，合理确定探测（观测）设施、防灾通道和避难场所，统筹安排相关基础设施。\n编制地质灾害易发区的城乡规划时，应当组织进行地质灾害危险性评估。\n各相关部门和单位应当根据编制规划需要，提供统计、勘察、测绘、地籍、气象、地震、地质、水资源、水文、环境以及地下设施等基础资料。\n第二十二条 城乡规划报送审批前，组织编制机关应当依法将城乡规划草案予以公告，并采取论证会、听证会或者其他方式征求专家和公众的意见，公告的时间不得少于30日。法律、行政法规规定不得公开的除外。\n组织编制机关应当充分考虑专家和公众的意见，并在报送审批的材料中附具意见采纳情况及理由。\n第二十三条 城乡规划及单独编制的各类专项规划和重要地段的建设工程设计方案批准前，审批机关应当组织专家和有关部门进行审查。\n第二十四条 城镇体系规划、城市总体规划、镇总体规划组织编制机关，应当组织有关部门和专家按照国家规定对规划实施情况进行评估，听取公众意见，向本级人民代表大会常务委员会、镇人民代表大会和原审批机关提出评估报告，并附具征求意见的情况。评估内容包括：\n（一）城市发展方向和空间布局是否与规划一致；\n（二）规划阶段性目标的落实情况；\n（三）各项强制性内容的执行情况；\n（四）规划委员会制度、信息公开制度、公众参与制度的建立和运行情况；\n（五）土地、交通、产业、环保、人口、财政、投资等相关政策对规划实施的影响；\n（六）依据总体规划的要求，制定各项专业规划、近期建设规划及控制性详细规划的情况；\n（七）其他相关建议。\n第二十五条 城镇体系规划、城市总体规划、镇总体规划的修改，必须符合《城乡规划法》规定的情形。\n城镇体系规划、城市总体规划、镇总体规划修改前，组织编制机关应当向原审批机关报告；修改涉及强制性内容的，报经原审批机关同意后，方可编制修改方案。\n第二十六条 有下列情形之一的，组织编制机关方可按照国家规定的权限和程序修改控制性详细规划：\n（一）因总体规划修改需要对控制性详细规划进行修改的；\n（二）因实施重大基础设施和公共服务设施、防灾减灾等重点工程项目需要修改的；\n（三）经评估确需修改的；\n（四）法律、法规规定的其他情形。\n控制性详细规划修改前，组织编制机关应当对修改的必要性组织论证，征求规划地段内利害关系人的意见，并向社会公示，提出报告，经原审批机关同意；修改涉及总体规划强制性内容的，应当先修改总体规划。\n修建性详细规划的修改，应当进行公示，并听取利害关系人的意见。\n第二十七条 因上级人民政府制定的城乡规划发生变更，或者审批机关经组织论证、听取各方面意见后认为确需修改的，可以修改乡规划、村庄规划。\n乡镇、村庄行政区划调整方案，应当与城乡规划中有关布局规划相衔接。\n第二十八条 城乡规划修改后，应当依照原审批程序报批。\n城市总体规划修改后，在报批前应先经本级人民代表大会常务委员会审议；镇总体规划、乡规划修改后，在报批前应先经镇、乡人民代表大会审议。","level":1},{"name":"第三章 城乡规划的实施与管理","text":"第二十九条 市（县）、镇人民政府应当根据城市总体规划、镇总体规划、土地利用总体规划以及国民经济和社会发展规划，制定近期建设规划，报总体规划审批机关备案。近期建设规划的规划期限为5年。\n城市土地储备、土地供应和相关建设活动应当与近期建设规划相协调。\n第三十条 城市新区的开发与建设，应当合理确定建设规模，充分利用现有市政基础设施和公共服务设施，体现地方特色。开发区应当纳入城乡规划统一管理，其建设用地应当符合土地利用总体规划。\n城镇旧区改建应当注重完善功能、改善环境，提高综合承载力，重点改造城市的危房区、棚户区及交通阻塞地区等地段，有效利用既有建筑。\n县级以上人民政府应当建立和完善城乡结合部建设管理制度，加强城乡结合部的规划管理，依法引导、规范城乡结合部的建设活动。\n第三十一条 严格“绿线、紫线、蓝线、黄线”规划管理，切实保护自然山体、水体和生态林地以及历史文化保护区。\n法律规定需要保护的用地以及城乡规划确定的林地、湿地、湖泊、山体、风景名胜区、重要历史建筑和街区、文物古迹、防震减灾通道和避难场所、危险废弃物处理场等用地，禁止擅自改变用途。\n第三十二条 城乡规划主管部门应当会同国土资源、公安、消防、环保、人防等有关部门编制地下空间开发利用规划，统筹安排交通设施、人防设施、公用设施及各类管网；地下空间开发利用应当履行规划审批、竣工核实手续。\n第三十三条 在城市、镇规划区内以出让方式提供国有土地使用权的，出让人在出让前应当持相关文件向项目所在地市（县）人民政府城乡规划主管部门申请规划条件，城乡规划主管部门应当依据控制性详细规划，提出规划条件。规划条件作为国有土地使用权出让合同的组成部分。\n规划条件包括出让地块的位置、用地面积、用地范围、使用性质、容积率、建筑密度、绿地率、公共设施、市政基础设施以及保障性住房配建等要求。\n第三十四条 城乡规划主管部门提出的容积率、用地性质等规划条件在土地出让后不得擅自变更。因涉及公共利益确需变更的，变更内容必须符合控制性详细规划，方可按照下列程序办理规划条件变更手续：\n（一）申请人向市（县）人民政府城乡规划主管部门提出书面申请材料并说明变更理由；\n（二）城乡规划主管部门应当组织专家对变更的必要性和规划方案的合理性进行论证；\n（三）经论证确需变更的，应当进行公示，征求利害关系人的意见，有听证申请的应当组织听证；\n（四）城乡规划主管部门依法提出变更建议并附论证、听证等相关材料，报市（县）人民政府批准；\n（五）经批准后，城乡规划主管部门办理变更规划手续，并及时通报同级国土资源行政主管部门；\n（六）根据变更后的规划条件补（退）土地出让金和相关规费，并签订国有土地使用权出让补充协议。\n规划条件变更涉及控制性详细规划强制性内容的，应当先修改控制性详细规划。\n第三十五条 建设项目依法需要办理选址意见书的，按照项目批准、核准权限实行分级管理。市（县）人民政府有关部门批准、核准的建设项目，由同级人民政府城乡规划主管部门核发。省级以上人民政府有关部门批准、核准的建设项目，由项目所在地的县级以上人民政府城乡规划主管部门提出初审意见，报省人民政府城乡规划主管部门核发。跨行政区域的建设项目由项目所在地的县级以上人民政府城乡规划主管部门提出初审意见，报共同上一级城乡规划主管部门核发。\n选址意见书按照下列程序办理：\n（一）建设单位持申请文件、地形图、重大项目选址环境影响评价等材料，向项目所在地城乡规划主管部门提交申请；\n（二）需要征求有关部门意见的，受理申请的机关应当及时征求意见，有关部门应当自收到征求意见书之日起5日内反馈；\n（三）受理申请的机关应当自受理申请之日起20日内作出决定。符合条件的，核发选址意见书。\n未按规定核发选址意见书的建设项目，有关部门不得批准、核准立项。\n第三十六条 城乡规划主管部门不得在城乡规划确定的建设用地范围以外作出规划许可。\n在城市、镇规划区内提供国有土地使用权的建设项目，建设单位应当取得建设用地规划许可证。\n以划拨方式提供国有土地使用权的建设项目，其建设用地规划许可证按照下列程序办理：\n（一）申请人持项目批准、核准、备案文件、国有土地划拨文件和建设工程相关材料，向项目所在地城乡规划主管部门提交申请；\n（二）需要征求有关部门意见的，受理申请的机关应当及时征求意见，有关部门应当自收到征求意见书之日起5日内反馈；\n（三）受理申请的机关应当依据控制性详细规划核定建设用地的位置、面积、允许建设的范围，自受理申请之日起20日内作出决定。符合条件的，核发建设用地规划许可证。\n以出让方式提供国有土地使用权的建设项目，由受让人持项目批准、核准、备案文件和土地出让合同等材料向城乡规划主管部门申请办理建设用地规划许可证。受理申请的机关自受理之日起20日内作出决定。符合条件的，核发建设用地规划许可证。\n第三十七条 在城市、镇规划区内进行工程建设的，应当按照下列程序办理建设工程规划许可证：\n（一）申请人持项目批准、核准、备案文件和土地使用的有关证明文件、建设用地规划许可证、符合规划条件的工程项目设计方案等相关材料，向城乡规划主管部门提交申请；\n（二）需要征求有关部门意见的，受理申请的机关应当及时征求意见，有关部门应当自收到征求意见书之日起5日内反馈；\n（三）受理申请的机关自受理申请之日起20日内作出决定。符合条件的，核发建设工程规划许可证。\n建设工程开工之前，由城乡规划主管部门组织定位、放线；其基础工程或者隐蔽工程完成后，由城乡规划主管部门组织验线，合格后方可继续施工。\n第三十八条 在乡、村庄规划区内进行乡镇企业、乡村公共设施、公益事业、村民住宅建设的，应当按照下列程序办理乡村建设规划许可证：\n（一）申请人持有关材料向所在地的乡镇人民政府提交申请；\n（二）乡镇人民政府自受理申请之日起10日内提出初审意见，报县级人民政府城乡规划主管部门审查；\n（三）受理申请的机关自收到初审意见之日起10日内作出决定。符合条件的，核发乡村建设规划许可证。\n使用原有宅基地进行村民住宅建设的，可由县级人民政府城乡规划主管部门委托乡镇人民政府自受理申请之日起10日内作出决定。符合条件的，核发乡村建设规划许可证。\n第三十九条 在城市、镇规划区内进行临时建设的，应当经市（县）人民政府城乡规划主管部门批准。有下列情形之一的，不得批准临时建设：\n（一）占用道路、河道或者机场、铁路、公路建设控制范围内土地的;\n（二）占用绿地、广场、公共停车场（库）、文物保护范围或者其他公共活动场地的;\n（三）占用高压走廊、压占地下管线或者影响管线敷设的;\n（四）市（县）人民政府规定的其他情形。\n第四十条 在规划区内修建的临时建筑不得超过2层，使用期不得超过2年。确需延期的，可依法申请延期1年。使用期满后，建设单位和个人必须在20日内自行拆除，清理现场；未自行拆除的，由所在地城市、县人民政府城乡规划主管部门责令限期拆除。因国家建设需要，拆除未超过批准期限的临时建筑应当给予适当补偿。\n禁止在临时用地上建设永久性建筑。建设单位或者个人不得擅自改变临时建筑和临时用地的用途。临时建筑不得办理房屋产权登记。\n第四十一条 设计单位应当按照城乡规划的技术规范和有关规定以及城乡规划主管部门提出的规划条件进行建设工程设计。\n第四十二条 城乡规划主管部门在建设工程竣工验收前，应当对建设工程是否符合规划条件予以核实。对符合规划条件的，核发规划条件核实证明；未经核实或者经核实不符合规划条件的，建设单位不得组织竣工验收，不得交付使用，房产主管部门不得办理房屋产权证件。\n建设单位应当在竣工验收后6个月内向城乡规划主管部门报送有关竣工验收资料。\n第四十三条 建设工程项目选址意见书、建设用地规划许可证、建设工程规划许可证和乡村建设规划许可证有效期为2年。确需延期的，可依法申请延期1年。\n第四十四条 城乡规划主管部门应当在规划许可后5日内向社会公布规划许可结果。\n建设单位在建设工程放线前，应当在建设施工场地醒目位置公示建设工程规划许可内容及附图，并在建设工程竣工经规划条件核实合格后予以撤除。\n第四十五条 建设工程使用人不得擅自改变规划许可确定的使用性质。确需改变的，应当向市（县）人民政府城乡规划、国土资源、房产主管部门申请办理变更手续，有关部门应当征求规划地段利害关系人意见；未办理变更手续的，不得擅自改变建设工程的使用性质和用途。","level":1},{"name":"第四章 城乡规划的监督检查","text":"第四十六条 各级人民政府应当每年向本级人民代表大会常务委员会或者乡镇人民代表大会和上一级人民政府报告城乡规划的实施情况。县级以上人民代表大会常务委员会通过听取和审议专项工作报告、执法检查等依法开展对城乡规划实施情况的监督，必要时作出相应的决议决定。\n第四十七条 县级以上人民政府应当建立健全城乡规划督察制度，加强对城乡规划编制、审批、实施、修改情况的监督检查，及时查处违法建设行为。城乡规划督察的具体办法由省人民政府制定。\n第四十八条 各级人民政府应当建立完善考核评价制度，对下级人民政府实施城乡规划、控制违法建设情况，定期开展考核评价。\n各级人民政府及其有关部门应当建立规划监督、行政执法、行政监察的协调、联动机制和查处违法建设的信息共享机制。\n街道办事处应当配合当地人民政府及城乡规划主管部门，对本辖区内规划建设活动开展监督、检查，协助有关部门依法处理违法建设行为。\n社区、村（居）民委员会、物业服务企业发现本区域内违法建设行为的，应当及时劝阻，并向城乡规划主管部门或者其他有关部门报告。\n第四十九条 城乡规划主管部门和有关部门应当建立城乡规划联动监测系统，完善城乡规划信息及违法建设监控平台，设立、公布监督举报电话、电子信箱等，接受公众和新闻媒体对城乡规划实施情况的监督。\n公民、法人和其他组织应当遵守城乡规划，服从规划管理，并有权就涉及其利害关系的建设活动是否符合规划的要求，向城乡规划主管部门查询。\n任何单位和个人有权向城乡规划主管部门或者有关部门举报、控告违反城乡规划的行为。对举报的事项，城乡规划主管部门或者有关部门应当及时处理，并为举报人保密。对举报重大违法建设的，予以奖励。\n第五十条 城乡规划主管部门应当建立健全公示制度，实行城乡规划批前批后公示，并提供监督检查处理结果的信息资料，依法接受社会监督。\n第五十一条 城乡规划主管部门查处违法建设工程时，无法确定其所有人、管理人的，应当通过政府网站、公示栏、有关媒体并在该违法建设场地醒目位置发布公告等，督促当事人依法接受处理。公告期不得少于60日。","level":1},{"name":"第五章 法律责任","text":"第五十二条 违反本条例规定，法律、行政法规已有处罚规定的，从其规定。\n第五十三条 有下列情形之一的，由上级人民政府或者有关主管机关依据职权责令改正，通报批评；对有关人民政府负责人和其他直接责任人员依法给予行政处分：\n（一）对城乡规划的领导、监管不力，造成重大损失和严重社会影响的；\n（二）在城市、镇总体规划确定的建设用地范围以外，违法设立各类开发区（园区）或者城市新区的；\n（三）依法应当组织编制城乡规划而未组织编制的；\n（四）违反法定权限和程序组织编制、审批、修改城乡规划的；\n（五）委托不具有相应资质等级的编制单位编制城乡规划的。\n第五十四条 城乡规划主管部门及其他有关部门有下列行为之一的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法予以行政处分：\n（一）对不符合法定条件擅自批准变更用地性质、容积率等规划条件的；\n（二）对未申请规划条件进行出让的土地核发土地使用证的；\n（三）对未依法取得建设工程规划许可证或者未经规划条件核实的工程核发房屋产权证件的；\n（四）对符合法定条件的行政许可申请未在法定期限内作出准予许可决定的。\n第五十五条 城乡规划报送审批前，城乡规划主管部门未按程序公示、听证等，由本级人民政府、上级人民政府城乡规划主管部门或者监察机关依据职权责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予行政处分。\n第五十六条 买卖、骗取建设项目选址意见书、建设用地规划许可证、建设工程规划许可证和乡村建设规划许可证的，由城乡规划主管部门依法予以撤销，没收违法收入，并处1万元以上5万元以下罚款。\n第五十七条 建设单位或者个人未按照规定在建设施工场地醒目位置公示建设工程规划许可内容及附图的，或者公示期未达到规定要求的，由县级以上人民政府确定的有关执法部门或者机构责令限期改正；逾期未改正的，处5000元以上1万元以下罚款。\n第五十八条 未取得建设工程规划许可证或者未按照建设工程规划许可证的规定进行建设，城乡规划主管部门依法实施行政处罚的，其违法收入按照该建设工程的销售平均单价或者市场评估单价与违法建设面积的乘积确定；建设工程造价按照有违法建设情形的单项工程整体造价确定，其中房屋建筑工程按照单体建筑物工程造价确定。\n第五十九条 城乡规划主管部门作出责令停止违法建设或者限期拆除的决定后，当事人不停止建设或者逾期不拆除的，城乡规划主管部门应当及时报由本级人民政府责成有关执法部门依法采取查封施工现场、强制拆除等措施，强制拆除所需费用由当事人承担。以暴力或者其他方法阻挠、妨碍依法执行公务的，依照法律有关规定处罚。\n对本条例第五十一条规定的情形，公告期满后，当事人未接受处理的，城乡规划主管部门报由本级人民政府责成有关部门对违法建设工程依法予以拆除或者没收。\n第六十条 城乡规划主管部门及其他有关部门工作人员在制定或者实施城乡规划中玩忽职守、滥用职权、徇私舞弊的，或者有其他失职、渎职行为，导致城乡规划管理失控的，依法给予行政处分。","level":1},{"name":"第六章 附则","text":"第六十一条 本条例所称市，是指按照行政建制设立的设区的市和县级市。\n第六十二条 本条例所称“绿线、紫线、蓝线、黄线”：\n绿线是指城乡规划中确定的各类绿地范围的控制线；\n紫线是指历史文化名城（镇、村）内的历史文化街区和历史建筑的保护范围界线；\n蓝线是指城乡规划中确定的江、河、湖、库、潭和湿地等地表水体保护和控制的地域界线；\n黄线是指城乡规划中确定的必须控制的基础设施、公共设施用地的控制界线。\n第六十三条 未设乡镇建制的农场、林场、渔场及独立工矿区的居民点，参照本条例执行。\n第六十四条 本条例自2011年10月1日起施行。1992年10月9日湖北省第七届人民代表大会常务委员会第二十九次会议通过，根据1998年7月31日湖北省第九届人民代表大会常务委员会第四次会议关于修改《湖北省实施〈中华人民共和国城市规划法〉办法》的决定修正的《湖北省实施〈中华人民共和国城市规划法〉办法》同时废止。","level":1}]},{"id":"h0152","sections":[{"name":"","text":"（2010年3月19日长阳土家族自治县第七届人民代表大会第四次会议通过 2010年5月27日湖北省第十一届人民代表大会常务委员会第十六次会议批准 根据2022年2月15日长阳土家族自治县第十届人民代表大会第二次会议通过 2022年5月26日湖北省第十三届人民代表大会常务委员会第三十一次会议批准的《长阳土家族自治县人民代表大会关于修改、废止部分单行条例的决定》修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了保护和合理开发旅游资源，规范旅游市场秩序，维护旅游者、旅游经营者的合法权益，促进自治县旅游业的发展，根据《中华人民共和国民族区域自治法》《湖北省旅游条例》等法律、法规的规定，结合自治县实际，制定本条例。\n第二条 自治县行政区域内的旅游规划、旅游促进与发展、旅游资源保护与利用、旅游经营活动与管理适用本条例。\n第三条 发展旅游业应当坚持政府主导、市场运作、社会参与、可持续发展的原则，坚持经济效益、社会效益和生态效益相统一。\n第四条 自治县人民政府应当将旅游业纳入本地方国民经济和社会发展规划，整合自治县旅游资源，制定促进旅游业发展的具体办法和措施。\n第五条 自治县人民政府文化和旅游主管部门负责本行政区域内旅游业的组织协调、行业指导和监督管理工作。其他相关部门应当按照各自职责共同做好旅游业的管理与服务工作。","level":1},{"name":"第二章 旅游促进与发展","text":"第六条 自治县人民政府应当建立旅游业发展联席会议制度，研究旅游业发展和旅游环境改善等重要事项，协调旅游资源的保护、开发和利用。\n第七条 自治县人民政府应当统筹协调交通、国土资源、电力、通讯、水利、农业、林业、文化、住房和城乡建设、环境保护等建设项目，不断改善旅游基础设施条件。\n重点旅游建设项目涉及重要基础设施建设的，应当列入自治县人民政府投资计划统筹安排。\n第八条 自治县人民政府应当在年度财政预算中安排一定比例的资金设立旅游业发展专项资金，并逐步增加。旅游业发展专项资金主要用于旅游宣传、资源保护、规划编制、产业扶持、公益设施建设、旅游交通基础设施建设、旅游安全监管等项支出。\n第九条 自治县人民政府应当组织引导旅游经营者对外开展旅游宣传促销活动，加强旅游宣传，大力拓展旅游市场。\n第十条 自治县人民政府规划和建设公共交通网络，应当兼顾旅游业发展的需要，逐步发展和完善旅游观光公共交通服务和道路客运站场设施；旅游观光交通线路和公共交通线路、停车场（站）等交通设施应当配套建设。\n旅游交通标识及主要旅游景区（点）交通指示标志，应当纳入自治县道路标识系统，由自治县文化和旅游主管部门会同交通运输主管部门统一规划，统一设置。\n第十一条 自治县鼓励投资者按照自治县旅游发展规划投资旅游业，开发旅游资源，建设旅游设施，从事旅游经营活动。其合法权益依法予以保护。\n第十二条 自治县鼓励发展旅游职业教育，推行在职继续教育，加强旅游人才的培养和引进，提高旅游从业人员素质。\n第十三条 自治县文化和旅游主管部门应当合理利用和挖掘民族文化资源，引导民族文化工作者、民族文化传承人和民间艺人等开发具有巴土文化特色的文化旅游产品，促进文化和旅游产业融合，协调发展。\n第十四条 自治县推行旅游服务标准化。文化和旅游主管部门应当会同市场监督管理主管部门组织实施旅游业的国家标准、行业标准和地方标准，督促和指导旅游经营者实行标准化管理及规范化服务。\n自治县鼓励研制、开发、生产、销售具有自治县特色的旅游商品或纪念品。\n第十五条 旅游经营者可以依法成立或者加入旅游行业协会。旅游行业协会应当遵守法律法规，加强行业自律，依照协会章程对会员的旅游经营活动进行协调指导，提供咨询，向文化和旅游主管部门提出有关旅游业发展的建议，维护旅游者和旅游经营者的合法权益。","level":1},{"name":"第三章 旅游规划","text":"第十六条 自治县文化和旅游主管部门应当按照规定科学编制自治县旅游发展规划，在征求上一级文化和旅游主管部门意见后，报自治县人民政府批准实施。旅游发展规划经批准后，不得擅自变更，确需变更的，应当按照原审批程序报批。\n新建、改建、扩建旅游项目，应当符合自治县旅游发展规划，并依法办理审批手续。\n第十七条 自治县人民政府应当加强统筹协调，促进土地利用、城市建设、生态环境和文物保护、交通、清江库区渔业养殖、风景名胜区和乡村建设等各种规划与旅游发展规划的衔接，充分体现旅游发展的功能需要。\n第十八条 涉及旅游环境的基础设施、交通、餐饮、住宿、文化娱乐、商贸购物等项目建设的规划编制，应当征求自治县文化和旅游主管部门的意见。\n第十九条 自治县文化和旅游主管部门应当加强对自治县旅游发展规划和旅游项目开发建设规划实施过程中的监督检查。\n第二十条 自治县自然资源和规划、农业农村主管部门在审批交通主干线两旁及景区（点）范围之内的房屋建筑时，应当指导建筑物所有人设计、修建或者改建具有民族风格的建筑。","level":1},{"name":"第四章 旅游资源保护与开发","text":"第二十一条 自治县文化和旅游主管部门负责对自治县境内的旅游资源按照有关标准进行普查、评估、论证，建立旅游资源档案，指导旅游资源保护和开发。其他相关部门应当予以配合。\n第二十二条 在旅游景区（点）和其它已经评估认定但尚未开发的旅游资源区域内，任何单位和个人不得擅自进行开山、采石、挖砂、取土、建房、采伐、渔猎、养殖、随意倾倒垃圾和直排污水等有损生态环境的行为。自治县文化和旅游主管部门对评估认定的旅游资源应当以适当方式向社会公布。\n自治县内从事清江水上运输的船舶，应当设置垃圾收集装置。禁止任何单位和个人向清江水域倾倒生活垃圾等有损生态环境的行为。\n第二十三条 依法进入市场流转的国有旅游资源经营权，应当遵循公开、公平、公正原则，通过拍卖、招标等方式进行。法律、法规有规定的，从其规定。\n取得经营权的法人、其他组织或者个人应当严格按照自治县旅游发展规划合理开发和经营，不得损害旅游资源。\n经营权有偿转让的收入应当依法专项用于旅游资源保护和旅游基础设施配套建设。\n第二十四条 自治县内从事旅游景区（点）开发应具备下列条件：\n（一）依法注册的企业法人；\n（二）有与经营业务相适应的资金；\n（三）有符合自治县旅游发展总体规划的项目开发建设规划，及符合旅游行业管理要求的经营方案；\n（四）有良好的企业信用。\n第二十五条 从事自治县内清江水上旅游经营业务，必须依法取得有关经营许可，并按规定办理相关手续后，方可开业。","level":1},{"name":"第五章 经营规范与权益保护","text":"第二十六条 在自治县设立旅行社的，必须符合有关法律、法规规定的设立条件，并取得《旅行社业务经营许可证》。\n未取得《旅行社业务经营许可证》的，不得经营旅行社业务，不得以业务交流合作、咨询服务、组织会务活动等名义变相经营旅行社业务。\n第二十七条 自治县文化和旅游主管部门根据省、市文化和旅游主管部门的授权，可以组织本行政区域内的景区（点）导游人员资格培训，颁发本行政区域内的景区（点）导游证。\n未取得导游证或者景区（点）导游证的人员，不得从事导游业务。导游或者景区（点）导游未经旅行社委派，不得私自承揽导游业务进行导游活动。\n第二十八条 在旅游景区（点）从事经营活动的单位和个人，应当遵守景区（点）有关管理制度，在规定的地点或区域经营，不得妨碍旅游者的正常游览。\n第二十九条 旅游经营者及其从业人员不得有下列行为：\n（一）纠缠、胁迫、诱骗旅游者或违背旅游者意愿强迫购物、接受服务，向旅游者索取额外费用；\n（二）冒用其他旅游经营者的名义经营旅游业务；\n（三）制作、发布虚假旅游信息，向旅游者隐瞒真实情况，提供质价不符的服务或者降低服务标准；\n（四）在旅游过程中强行滞留旅游团队或者中止服务；\n（五）擅自增加或者减少旅游项目、变更约定接待计划;\n（六）以零团费、负团费等低于成本的价格销售旅游产品；\n（七）法律法规禁止的其他行为。\n第三十条 旅游者在旅游活动中享有以下权利：\n（一）人身、财产安全得到保障；\n（二）人格尊严、民族风俗习惯和宗教信仰受到尊重；\n（三）自主选择旅游经营者、旅游服务项目和旅游服务方式；\n（四）了解旅游服务的内容、项目、规格、费用等真实情况；\n（五）按照旅游合同约定或者本条例规定，获得质价相符的旅游服务；\n（六）法律法规规定或者旅游合同约定的其他合法权利。\n第三十一条 旅游者在旅游活动中，应当履行下列义务：\n（一）遵守法律法规，遵守社会公德及文明旅游公约；\n（二）保护旅游资源和生态环境，爱护旅游设施；\n（三）尊重旅游地的宗教信仰和民族风俗习惯；\n（四）遵守旅游景区（点）依法制定的管理制度；\n（五）支付门票和其他有偿服务的费用；\n（六）法律、法规和规章规定的其他有关义务。\n第三十二条 旅游者的合法权益受到侵害或者与旅游经营者发生争议时，可以通过下列方式处理：\n（一）与旅游经营者协商和解；\n（二）向文化和旅游、市场监督管理等部门或者消费者协会投诉；\n（三）有仲裁协议的提请仲裁机构仲裁；\n（四）依法向人民法院提起诉讼。\n第三十三条 自治县文化和旅游主管部门应当建立健全旅游投诉受理制度，可以委托旅游质量监督管理机构负责受理旅游服务质量投诉。文化和旅游主管部门接到旅游者投诉后，应当及时作出是否受理的决定；情况复杂的最迟在7个工作日内作出是否受理的决定；不予受理的，应当说明理由。对应当由其他部门处理的，应当及时转交有关部门处理，并告知投诉者。\n自治县市场监督管理、公安、卫生健康、发展和改革等有关部门依照各自职责做好相关旅游投诉事件的处理。","level":1},{"name":"第六章 旅游安全","text":"第三十四条 自治县应急管理、交通运输、公安、卫生健康、水利和湖泊、农业农村、电力、通讯、市场监督管理、林业、气象等相关部门依据各自职责，加强对旅游交通、食品、游览、设施设备、卫生防疫、森林防火、防汛防雷等方面的检查和监督，排除隐患，确保旅游安全。\n第三十五条 自治县交通运输、文化和旅游、公安等部门依照各自职责，对自治县内水上旅游船舶进行监管。不具备安全条件的船舶不得承载游客。\n第三十六条 旅游经营者应当按规定建立安全管理责任制，制定旅游安全事故应急救援预案和安全救助机制，设立安全管理机构，配备专门人员，配置必要的旅游安全设施和设备，确保旅游者的人身、财产安全。\n经营涉及旅游者人身安全的漂流、探险等特种旅游项目，旅游经营者应当配备专业人员，提供安全保障，并依法为旅游者办理相关保险。\n第三十七条 旅游景区（点）应当设置地域界限、服务设施和游览导向等标志。对具有危险性的区域或者项目，应当设置明显的提示或警示标志，并采取必要的防护措施。","level":1},{"name":"第七章 法律责任","text":"第三十八条 违反本条例，法律、法规有处罚规定的，从其规定；没有规定的，依照本条例的规定执行。\n第三十九条 违反本条例的规定，有下列行为之一的，由自治县文化和旅游主管部门予以处罚：\n（一）未取得导游证从事导游活动或者景区（点）导游人员未经旅行社委派，私自承揽导游业务进行导游活动的，责令改正，并处1000元以上5000元以下的罚款；有违法所得的，没收违法所得；\n（二）在景区（点）擅自摆摊、设点，妨碍旅游者正常游览的，责令改正；拒不改正的，处100元以上1000元以下的罚款；\n（三）纠缠、胁迫、诱骗旅游者或者违背旅游者意愿强迫购物、接受服务，向旅游者索取额外费用的，责令改正，并可处500元以上2000元以下的罚款。\n前款规定（三）列举的行为违反治安管理规定的，由公安机关依法处理；构成犯罪的，依法追究刑事责任。\n第四十条 违反本条例第二十二条、第二十五条和第三十六条规定的，由有关部门依法处理。\n第四十一条 因旅游者的过错造成旅游资源破坏、旅游服务设施损坏的，旅游者应当依法承担赔偿责任；旅游者违反景区（点）管理制度，不按约定购买景区（点）门票或支付有偿服务费用的，旅游经营者有权按照规定向旅游者追索相关费用。\n第四十二条 自治县文化和旅游主管部门及相关管理部门工作人员在旅游业管理中玩忽职守、滥用职权、以权谋私的，由其所在单位或者主管部门给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附 则","text":"第四十三条 本条例自2010年9月1日起施行。2002年2月4日长阳土家族自治县第五届人民代表大会第四次会议通过，2002年3月28日湖北省第九届人民代表大会常务委员会第三十二次会议批准的《长阳土家族自治县实施〈湖北省旅游管理条例〉办法》同时废止。","level":1}]},{"id":"h0153","sections":[{"name":"","text":"（2011年9月29日湖北省第十一届人民代表大会常务委员会第二十六次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了保障电力建设和生产顺利进行，维护社会公共安全和公共利益，保护人民群众生命财产安全，促进经济社会和谐发展，根据《中华人民共和国电力法》、《电力设施保护条例》等有关法律法规，结合本省实际，制定本条例。\n第二条 本省行政区域内电力设施的建设与保护活动，适用本条例。\n本条例所称电力设施包括发电设施、变电设施、电力线路设施以及电力调度设施、电力通信设施、电力市场交易设施等有关辅助设施。\n第三条 电力设施建设与保护应当遵循安全、科学、效能、环保的原则。\n第四条 各级人民政府应当加强对本行政区域内电力设施建设与保护工作的领导，及时协调解决电力设施建设与保护工作中的重大问题，将电力设施建设与保护工作纳入任期目标和社会治安综合治理范围。\n县级以上人民政府设立的电力设施建设与保护领导机构，负责本行政区域内电力设施建设与保护的组织、协调工作。\n街道办事处及社区、村（居）民委员会协助当地人民政府及其有关部门做好电力设施建设与保护工作。\n第五条 县级以上人民政府电力行政主管部门按照本级人民政府确定的职责负责本行政区域内电力设施建设与保护的监督管理工作；其他有关部门按照各自职责，做好电力设施建设与保护的相关工作。\n第六条 各级人民政府及有关部门，街道办事处，社区、村（居）民委员会，电力设施所有人、管理人，各新闻媒体应当加强电力设施建设与保护法律法规和有关常识的宣传，提高社会公众的自觉保护意识。\n鼓励在电力设施建设与保护过程中创新管理方法，采用新技术，推广先进适用的科学研究成果，提高电力设施运行的质量和效率。\n第七条 电力设施所有人、管理人应当依法履行电力设施建设与保护的义务，接受政府有关部门和社会的监督。\n第八条 电力设施受法律保护。禁止任何单位和个人危害电力设施安全。任何单位和个人对危害电力设施的行为，有权制止和举报。\n对在电力设施保护工作中作出显著成绩的单位和个人，给予表彰和奖励。","level":1},{"name":"第二章 电力设施规划","text":"第九条 电力发展规划应当根据本行政区域的经济社会发展战略，结合工业化、城镇化、农业现代化以及新农村建设等需要，按照科学发展的要求，遵循统筹兼顾、合理布局、适度超前、确保安全、节约资源、保护环境和公众参与的原则制定和实施。\n省人民政府及其有关部门在制定、批准、实施电力发展规划过程中应当根据农村贫困地区、革命老区、少数民族地区、边远山区、库区的生态情况、地理环境和经济社会发展需要，对其予以扶持。\n第十条 县级以上人民政府应当将电力发展规划纳入国民经济和社会发展规划；电力发展规划由本级人民政府发展改革主管部门组织编制。\n第十一条 县级以上人民政府城乡规划主管部门应当会同发展改革主管部门、电力行政主管部门，根据城市总体规划、电力发展规划组织编制电力设施布局规划，并将其纳入城乡规划，依据城乡规划审批程序报法定机关批准实施。\n编制电力设施布局规划应当听取社会各方面的意见；经依法批准的电力设施布局规划应当及时公布，未经法定程序，不得变更。\n第十二条 土地利用总体规划与城乡规划及电力设施布局规划应当相互衔接，并统筹安排发电、变电设施用地，架空电力线路走廊和电缆通道。\n编制城市新区、旧城区改造及工业园区规划，应当将电力设施布局规划纳入其控制性详细规划，确保电力设施建设用地。\n新建住宅小区应当预留公用配套电力设施用地、用房和通道。\n电力设施布局规划应当与风景名胜区规划和历史文化名城、名镇、名村的保护等相互衔接。\n第十三条 电力设施布局规划公布后，任何单位和个人不得擅自在电力设施布局规划区域内开展妨碍电力设施布局规划实施的建设。\n第十四条 公路、铁路、城市道路、城市地下管网、隧道、公用涵道、桥梁等设施的规划和建设，应当考虑电力设施布局规划和相关设计规范，预留相应的电力通道。","level":1},{"name":"第三章 电力设施建设","text":"第十五条 电力设施建设应当按照电力发展规划及电力设施布局规划进行。\n电力设施建设单位应当依法在电力设施布局规划确定的发电、变电设施用地、架空电力线路走廊、电缆通道区域内进行电力设施建设。\n第十六条 电力设施建设应当遵守环境保护法律、法规的规定，电力设施建设项目应当依法进行环境影响评价。环境保护主管部门对电力设施建设项目的环境影响评价结果应当予以公布。\n第十七条 发电厂、变电站、开关站、换流站用地符合国家划拨用地目录的，依法通过划拨方式取得建设用地使用权。\n架空电力线路走廊（包括杆、塔基础）和地下电缆通道建设不实行征地，电力设施建设单位应当对杆、塔基础用地的建设用地使用权人或者土地承包经营权人给予一次性经济补偿。\n新建架空电力线路需要砍伐林木的，电力设施建设单位应当依法办理砍伐手续，并根据砍伐范围给予林木所有人或者经营人一次性经济补偿，与其签订在通道内不种植危及电力设施安全的植物的协议。\n具体补偿标准由省价格主管部门会同省电力行政主管部门制定，报省人民政府批准后执行。\n第十八条 城乡规划主管部门依据电力设施布局规划等对电力设施建设项目予以建设工程规划许可后，应当及时公告。\n电力设施建设单位应当按照建设工程规划开展项目建设。\n任何单位和个人不得在取得建设工程规划许可的范围内从事妨碍、危及电力设施建设的活动。\n第十九条 电力设施建设应当符合国家有关电力设施安全的行业标准和技术规范，并采取相应的安全防范措施。\n新建架空电力线路不得跨越储存易燃、易爆物品的仓库；确需跨越的，应当将易燃、易爆物品搬离，由电力设施建设单位给予适当经济补偿。\n220千伏及以下架空电力线路跨越房屋的，应当确保跨越安全距离。\n对500千伏及以上架空电力线路确需跨越的居民住宅以及在其走廊内按照安全需要应当拆除的其他房屋，电力设施建设单位应当依法实施拆迁并给予补偿。\n第二十条 电力电缆通过桥梁、公用涵道、地下通道、城市道路、城市管网，架空电力线路跨越铁路、公路、航道、水利工程设施的，电力设施建设单位应当依法办理相关手续，有关行政主管部门应当在法定时限内予以办理。由于电力设施建设造成相关设施损坏的，电力设施建设单位应当依法赔偿。\n第二十一条 城镇中心区电力设施建设所需电缆通道，由市政建设管理部门统筹建设。\n第二十二条 任何单位和个人不得从事下列阻挠或者危害电力设施建设的行为：\n（一）非法侵占电力设施建设项目依法征用的土地；\n（二）涂改、移动、损坏、拔除电力设施建设的测量标桩和标记；\n（三）破坏、封堵施工道路，截断施工水源或者电源；\n（四）强行承揽电力设施建设工程；\n（五）其他阻挠或者危害电力设施建设的行为。","level":1},{"name":"第四章 电力设施保护","text":"第二十三条 电力设施所有人、管理人应当切实履行社会责任和义务，加强对电力设施保护的宣传，建立健全安全管理和责任追究制度，落实各项人防、物防和技防措施，设立并维护电力设施安全警示标志，按照国家规范和技术标准对电力设施进行巡视、维护、检修，及时采取措施消除隐患。\n第二十四条 电力设施保护范围和保护区按照国家有关规定依法确定。\n800千伏、1000千伏电力线路保护区为导线边线向外侧水平延伸30米并垂直于地面所形成的两平行面内的区域。\n发电厂、变电站、换流站、开关站等厂（站）保护区为厂、站围墙外延伸3米所形成的区域。\n风力发电场保护区为风力发电设备区向外延伸50米的区域。\n第二十五条 县级以上人民政府电力行政主管部门应当按照国家有关规定对电力设施保护范围和电力设施保护区设立标志。\n任何单位和个人不得毁损、移动、破坏电力设施保护标志。\n第二十六条 任何单位和个人不得从事下列危害电力线路设施的行为：\n（一）直接或者操作其他物体碰触电力线路设施；\n（二）擅自在杆塔上张贴广告标语、悬挂广告牌及其他缆线和标志物；\n（三）在电力线路设施300米内放风筝或者升放无人驾驶自由气球、系留气球；\n（四）擅自攀爬变压器台架、杆塔和拉线；\n（五）损坏、擅自移动电力线路上的电气设备及通信设施；\n（六）擅自占用电缆通（管）道及其他管线敷设各类缆线；\n（七）其他危害行为。\n第二十七条 任何单位和个人不得在架空电力线路保护区从事下列危害行为：\n（一）种植可能危及电力设施和供电安全的高杆植物；\n（二）垂钓活动；\n（三）堆砌、填埋、铺垫等影响电力设施安全运行的作业或者活动；\n（四）燃放烟花爆竹；\n（五）新建、改建、扩建建筑物、构筑物；\n（六）其他危害行为。\n第二十八条 任何单位和个人不得在电力电缆保护区从事下列危害行为：\n（一）焚烧谷物、草料、木材、油料、垃圾等物品；\n（二）取土、开挖、采石、打桩、钻探或者倾倒腐蚀性化学物品等；\n（三）堆放易燃、易爆物品；\n（四）新建、改建、扩建建筑物、构筑物；\n（五）其他危害行为。\n第二十九条 在发电厂、变电站、换流站、开关站等厂、站保护区内，任何单位和个人不得从事下列活动：\n（一）堆放杂物、倾倒垃圾；\n（二）修建建筑物、构筑物；\n（三）开挖坑、渠；\n（四）堆放易燃、易爆物品；\n（五）焚烧谷物、草料、木材、油料、垃圾等物品；\n（六）其他危害行为。\n第三十条 在发电厂、变电站专用的水、油、气、灰、渣、煤等输送管线保护区及专用道路，任何单位和个人不得从事下列活动：\n（一）损坏或者封堵道路、管道；\n（二）擅自取土、挖沙、采石、打桩、钻探等作业；\n（三）修建建筑物、构筑物；\n（四）倾倒垃圾、矿渣和其他废弃物；\n（五）堆（排）放易燃、易爆及其他腐蚀性危险品、化学品；\n（六）其他危害行为。\n第三十一条 在电力设施保护区外，进行可能危及架空电力线路杆塔、拉线基础安全的作业时，应当遵守下列规定：\n（一）不得影响杆塔、拉线基础的稳定，可能导致基础不稳定的，有关单位和个人应当修筑符合技术标准或者安全要求的加固护坡；\n（二）不得损坏电力设施接地装置或者改变其埋设深度。\n第三十二条 任何单位和个人应当经县级以上人民政府电力行政主管部门批准，并采取安全防护措施后，方可进行下列作业：\n（一）在电力设施周围500米的区域内进行爆破作业；\n（二）在电力设施周围进行其他可能危及电力设施安全的作业。\n采取安全防护措施所需费用由作业人承担。\n第三十三条 电力设施所有人、管理人对危害电力设施的行为，有权予以制止，要求恢复原状、排除妨害、赔偿损失，当事人应当予以配合。\n危害行为严重影响电网安全时，电力行政主管部门应当责令当事人限期改正；逾期不改正的，供电企业可停止受理当事人的用电报装申请，或者按国家规定程序中止对当事人供电，直至危害行为消除。","level":1},{"name":"第五章 电力设施与其他设施相互关系的处理","text":"第三十四条 电力设施与其他公共设施、民用设施，在建设、改造和维护中出现相互妨碍事项时，应当妥善予以协调，兼顾各方利益，依法合理处理。\n第三十五条 新建、改建、扩建电力设施，应当与周围已建其他设施保持符合规定的安全距离。确需对其他设施予以迁移或者采取必要防护措施的，电力设施所有人、管理人应当与其他设施所有人协商，就迁移、防护措施及补偿等问题达成协议后方可施工，所需费用由电力设施所有人、管理人承担。\n铁路、公路、水利、电信、航运、城市道路、桥梁、涵道、管线等设施后于电力设施建设（包括改建、扩建）的，不得危及电力设施安全。确需对电力设施予以迁移或者采取必要保护措施的，建设单位应当事先与电力设施所有人、管理人达成协议，所需费用由建设单位承担。\n第三十六条 架空电力线路安全跨越房屋的，被跨越的房屋不得再行增加高度。超越房屋的物体高度或者房屋延伸出的物体长度应当符合安全距离的要求。\n第三十七条 电力设施与农作物、林木相互妨碍时，按照下列规定处理：\n（一）新建、改建或者扩建电力设施作业中，损害农作物或者林木的，电力设施建设单位应当与其所有人或者管理人达成协议，并按照国家和省有关规定给予一次性补偿。\n（二）在既有电力设施保护区内新种植或者自然生长的林木，可能危及电力设施安全的，电力设施所有人、管理人应当依法及时予以修剪或者砍伐，不予补偿。\n第三十八条 电力设施保护区内的城镇绿化树、公路行道树的管理单位应当对可能危及电力设施安全的林木进行定期修剪，保证林木的自然生长高度与架空电力线路等电力设施之间的距离符合安全要求；未及时修剪，造成电力线路损坏或者他人人身、财产损失的，应当承担相应的责任。\n电力设施所有人、管理人发现林木可能危及电力设施安全的，应当及时通知有关管理单位修剪。有关管理单位自收到通知之日起3日内应当予以修剪；不予修剪的，电力设施所有人、管理人应当进行修剪，并不补偿修剪林木的相关费用。\n第三十九条 有下列情形之一的，电力设施所有人、管理人可以对林木先行采取修剪、砍伐或者其他处理措施，事后应当及时通知林木所有人或者管理人，并按照有关规定补办相关手续：\n（一）林木已经严重危及电力设施安全或者人身安全，需要采取紧急措施处理的；\n（二）因林木造成电力供应中断，需要尽快恢复供电的；\n（三）处置电力设施突发事件，需要采取相应应急措施的。","level":1},{"name":"第六章 电力设施突发事件应急处置","text":"第四十条 各级人民政府负责本行政区域内的电力设施突发事件应急工作，建立应急救援组织和电力设施突发事件应急救援物资储备制度，保障电力设施突发事件应急处置工作的有序进行。\n县级以上人民政府电力行政主管部门应当制定和完善电力设施突发事件应急预案，报本级人民政府批准。\n第四十一条 电力企业应当制定本单位电力设施突发事件应急预案，报电力行政主管部门备案，并按照应急预案的要求，保障应急设施、设备、物资的储备和完好，定期开展应急演练。\n第四十二条 重大、特别重大电力设施突发事件发生后，当地人民政府应当立即向上级人民政府报告，并按照规定启动电力设施突发事件应急预案，及时采取措施开展处置工作。\n第四十三条 电力设施突发事件发生后，电力设施所有人、管理人应当立即启动本单位的电力设施突发事件应急预案，并采取下列措施：\n（一）消除危险源，控制事故扩大，确保群众人身安全；\n（二）对遭受破坏的电力设施进行抢修、排除障碍；\n（三）其他应急措施。\n第四十四条 电力设施突发事件处置过程中，依法征用单位或者个人的交通工具、房屋、设施、设备的，使用完后应当及时返还并支付补偿费用；造成毁损、灭失的，应当按照国家有关规定给予补偿。","level":1},{"name":"第七章 监督检查","text":"第四十五条 县级以上人民政府及其电力行政主管部门应当加强对电力设施建设与保护工作的监督管理，加强执法队伍建设，规范执法活动，协调电力执法过程中与相关方面的关系。\n电力行政主管部门可以委托符合法定条件的组织依法开展电力设施建设与保护监督管理活动。\n第四十六条 电力行政执法人员依法履行职责时，可以行使下列职权：\n（一）检查电力设施安全及用户用电情况；\n（二）查阅、复制必要的资料，询问有关人员；\n（三）依法收集相关证据；\n（四）法律、法规规定的其他职权。\n第四十七条 电力行政执法人员应当忠于职守、文明执法，不得泄露检查中获知的被检查单位的商业秘密。对发现的违法行为，应当立即制止，并依法调查处理。\n第四十八条 电力设施所有人、管理人和用户应当接受依法实施的监督检查，如实提供有关资料或者反映有关情况。\n第四十九条 电力行政主管部门等相关部门应当建立完善举报制度，公开举报电话、通信地址或者电子邮件信箱；对接到的举报，应当依法及时调查处理。","level":1},{"name":"第八章 法律责任","text":"第五十条 违反本条例规定，法律、行政法规已有处罚规定的，从其规定；构成犯罪的，依法追究刑事责任；造成损失的，依法承担民事责任。\n第五十一条 违反本条例第二十二条规定，由县级以上人民政府电力行政主管部门责令改正，要求恢复原状并赔偿损失；构成违反治安管理行为的，由公安机关依法进行处罚。\n第五十二条 违反本条例第二十六条规定，危害电力线路设施的，由县级以上人民政府电力行政主管部门责令限期改正；逾期不改正的，对单位处5000元以上2万元以下罚款，对个人处200元以上2000元以下罚款。\n第五十三条 违反本条例第二十七条、第二十八条、第二十九条、第三十条的规定，由县级以上人民政府电力行政主管部门责令停止违法行为，恢复原状；拒不停止违法行为的，对单位处5000元以上2万元以下罚款，对个人处200元以上2000元以下罚款；需要拆除违法建筑物、构筑物的，由当地人民政府依法责令强制拆除。\n第五十四条 违反本条例第三十二条规定，未经批准或者未采取安全措施，在电力设施周围进行爆破或者其他作业，危及电力设施安全的，由县级以上人民政府电力行政主管部门责令停止作业、恢复原状并赔偿损失。\n第五十五条 电力行政主管部门和其他有关行政管理部门及其工作人员在行使电力设施建设与保护职权过程中玩忽职守、滥用职权、徇私舞弊或者有其他失职、渎职行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第五十六条 电力设施所有人、管理人违反本条例规定，在电力设施建设与保护过程中疏于管理、玩忽职守，造成电力设施损坏，导致电力运行事故，给他人造成损害的，应当追究相应责任，并依法承担赔偿责任。","level":1},{"name":"第九章 附则","text":"第五十七条 核电设施的规划、建设与保护按照国家有关规定执行。\n第五十八条 本条例自2011年12月1日起施行。","level":1}]},{"id":"h0154","sections":[{"name":"","text":"（2011年9月29日湖北省第十一届人民代表大会常务委员会第二十六次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了防御和减轻地震灾害，保护人民生命和财产安全，促进经济社会可持续发展，根据《中华人民共和国防震减灾法》等有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内的防震减灾活动，适用本条例。\n第三条 防震减灾工作实行预防为主、防御与救助相结合的方针。\n第四条 县级以上人民政府应当加强对防震减灾工作的领导，建立健全防震减灾工作机构，加强防震减灾队伍建设和人才培养，完善防震减灾工作体系和联席会议制度，并将防震减灾工作纳入政府年度工作目标考核体系。\n省人民政府对地震重点监视防御区的地震工作机构人员配置、地震监测台网建设以及群测群防工作等落实情况，应当重点加强监督检查，并逐步实现在地震重点监视防御区有地震专门工作机构。\n县级以上人民政府地震工作主管部门和发展改革、财政、民政、住房和城乡建设、国土资源、水利、交通运输、卫生、公安、教育、新闻出版等有关部门，按照职责分工，各负其责，密切配合，共同做好防震减灾工作。\n乡镇人民政府、街道办事处在上级人民政府及其有关部门的指导下，做好防震减灾相关工作。\n第五条 县级以上人民政府应当根据上一级防震减灾规划和本行政区域的实际情况，编制防震减灾专项规划，并纳入国民经济和社会发展总体规划，实现防震减灾与经济社会发展同步规划、同步实施、同步发展。\n县级以上人民政府及其有关部门编制城乡规划、土地利用总体规划、主体功能区规划，应当听取地震工作主管部门意见，确保规划符合防震减灾的总体要求。\n第六条 县级以上人民政府应当将防震减灾工作所需经费纳入本级财政预算，并逐步增加投入，保障防震减灾工作需要。\n省、市（州）人民政府和地震重点监视防御区的县级人民政府应当设立防震减灾专项资金。防震减灾专项资金主要用于地震监测台网建设和维护、既有建筑抗震性能鉴定及加固指导、农村村民住宅和城市社区地震安全指导、防震减灾知识宣传教育、防震减灾业务培训、社会动员及地震应急演练、地震应急处置及装备、地震群测群防等工作。\n第七条 县级以上人民政府抗震救灾指挥机构负责统一领导、指挥和协调本行政区域内的抗震救灾工作,其日常工作由本级人民政府地震工作主管部门承担。\n第八条 县级以上人民政府应当坚持地震专业台网监测与群测群防相结合，加强地震群测群防体系建设，建立和完善地震宏观测报网、地震灾情速报网、地震知识宣传网，提高捕捉地震短期与临震宏观异常、报告灾情信息和普及防震抗震知识的能力。\n乡镇人民政府、街道办事处应当配备兼职防震减灾助理员；地震重点监视防御区、地震次生灾害易发区内的县级人民政府地震工作主管部门、乡镇人民政府、街道办事处应当指导帮助社区、村（居）民委员会建立防震减灾联络（观察）员队伍，组织开展群测群防活动。\n省人民政府应当结合抢险救灾体系建设，整合建设投入资源，对地震重点监视防御区内的贫困地区地震宏观测报网、地震灾情速报网、地震知识宣传网建设和防震减灾联络（观察）员队伍建设给予扶持。\n第九条 县级以上人民政府应当支持防震减灾科学技术研究，推广应用先进的科学技术成果，提高防震减灾工作科技水平。\n第十条 各级人民政府及其有关部门和单位应当把防震减灾知识作为全民素质教育的重要内容，加强防震减灾科普宣传，普及防震减灾知识，组织开展地震应急救援演练，增强公民防震减灾意识，提高全社会的防震减灾能力。\n每年5月12日所在周为全省防震减灾宣传活动周。\n第十一条 任何单位和个人都有依法参加防震减灾活动的义务。\n各级人民政府及其有关部门对在防震减灾工作中作出突出贡献的单位和个人给予表彰、奖励。","level":1},{"name":"第二章 地震监测预报","text":"第十二条 全省的地震监测台网实行统一规划，分级、分类管理。\n省级地震监测台网规划，由省人民政府地震工作主管部门根据全国地震监测台网总体规划和地震监测工作实际需要编制，报省人民政府批准后实施。\n市、县级地震监测台网规划，由市、县级人民政府地震工作主管部门根据省级地震监测台网规划和地震监测工作实际需要编制，报本级人民政府批准后实施。\n第十三条 重点水库及江河堤防、油（气）田及油（气）储备、矿山、石油化工、高速铁路、城市轨道交通、超高层建筑以及核电站等重大建设工程的建设单位，应当按照国家和省有关规定建设专用地震监测台网或者强震动监测设施，并将建设情况报省人民政府地震工作主管部门备案。\n建设专用地震监测台网或者强震动监测设施，应当遵守法律法规和国家标准，保证建设质量，其建设资金和运行维护经费由建设单位承担。\n省、市（州）地震工作主管部门对专用地震监测台网和强震动监测设施的建设给予指导。\n第十四条 地震工作主管部门会同国土资源、规划等部门按照有关规定，划定地震观测环境保护范围，设置保护标志，并将保护范围纳入土地利用总体规划和城乡总体规划。\n地震监测设施和地震观测环境依法受到保护。任何单位和个人不得侵占、毁损、拆除或者擅自移动地震监测设施，不得危害地震观测环境。\n第十五条 省人民政府地震工作主管部门应当建立健全省、市、县地震监测台网的监测数据实时传输系统，实现监测数据互联互通，并按照国家有关规定建立地震信息网站，依法向社会发布地震监测信息。\n县级以上人民政府地震工作主管部门应当向省地震监测台网中心实时传输监测数据，并将有关分析意见及时报送上一级人民政府地震工作主管部门。\n专用地震监测台网和强震动监测设施的管理单位应当向省地震监测台网中心实时传输监测数据，并及时报送有关分析意见。\n第十六条 省人民政府应当按照全国地震烈度速报系统建设的要求，建立和完善省地震烈度速报系统，保障系统正常运行，为抗震救灾和工程建设提供依据。\n第十七条 省人民政府地震工作主管部门根据地震活动趋势和震害预测结果，提出确定本省地震重点监视防御区的意见，报省人民政府批准。\n地震重点监视防御区的县级以上人民政府及其地震工作主管部门，应当增加地震监测台网密度，加强震情跟踪和流动监测工作，完善测震、地震前兆等综合监测系统。\n第十八条 单位和个人观测到可能与地震有关的异常现象时，可以向所在地县级以上人民政府地震工作主管部门或者乡镇人民政府、街道办事处、社区、村（居）委员会报告。乡镇人民政府、街道办事处、社区、村（居）委员会接到报告后应当及时向县级以上人民政府地震工作主管部门报告。地震工作主管部门应当对报告事项进行登记，立即组织调查核实并及时上报。\n第十九条 省、市（州）人民政府地震工作主管部门应当定期召开震情会商会，对地震预测意见和可能与地震有关的异常现象进行综合分析研究，形成震情会商意见，经评审后及时报本级人民政府。\n单位和个人提出的地震预测意见，应当以书面形式向县级以上人民政府地震工作主管部门报告。\n第二十条 地震预报意见和地震信息实行统一发布制度。本省行政区域内的地震预报意见，由省人民政府按照国家规定程序发布，地震信息由省人民政府地震工作主管部门发布。\n新闻媒体刊登或者播发地震预报消息应当以国家和省人民政府发布的地震预报为准。\n除发表本人或者本单位对长期、中期地震活动趋势的研究成果及进行相关学术交流外，任何单位和个人不得向社会散布地震预测意见。任何单位和个人不得向社会散布地震预报意见及其评审结果。对制造、散布地震谣言，影响社会安定的言行，各级人民政府及其地震工作主管部门应当及时采取措施予以澄清。\n第二十一条 一次齐发爆破用药相当于4000千克TNT炸药能量以上的爆破作业，爆破单位应当在实施爆破作业24小时前，将爆破地点、时间及用药量书面告知爆破作业实施地县级以上人民政府地震工作主管部门。","level":1},{"name":"第三章 地震灾害预防","text":"第二十二条 县级以上人民政府地震工作主管部门负责本行政区域内抗震设防要求和地震安全性评价的监督管理工作。\n第二十三条 县级以上人民政府应当组织开展地震活动断层探测和危险性评价，并将探测、评价结果作为制定城乡规划的依据，确保城乡建设避开地震活动断层等不利地段。\n第二十四条 新建、扩建、改建建设工程应当符合下列抗震设防要求：\n（一）一般建设工程按照地震动参数区划图或者地震小区划结果确定抗震设防要求；\n（二）重大建设工程和可能发生严重次生灾害的建设工程应当按照国家、省有关规定进行地震安全性评价，并根据经审定的地震安全性评价报告确定抗震设防要求；\n（三）位于地震动参数区划分界线8公里区域和地震研究程度、资料详细程度较差地区的建设工程，应当进行地震动参数复核，并根据地震动参数复核结果确定抗震设防要求；\n（四）学校、医院、商场、体育场馆等人员密集场所的建设工程，应当按照国家有关规定，高于当地房屋建筑的抗震设防要求进行设计和施工。\n建设单位对建设工程的抗震设计、施工的全过程负责，设计、施工、工程监理等单位依法对建设工程的抗震设计、施工质量负责。\n第二十五条 县级以上人民政府应当全面落实抗震设防要求，将建设工程的抗震设防要求纳入基本建设管理程序，加强对建设工程的勘察、设计、施工、监理、竣工验收等环节的抗震设防质量监督和管理。\n地震工作主管部门、住房和城乡建设部门应当加强抗震设防工作协调，科学确定和运用各类建设工程抗震设防要求，确保建设工程强制性标准与抗震设防要求的相互衔接。对地震重点监视防御区、人口稠密区和经济发达地区的交通、电力、通信、供水供气、水利等基础设施的抗震设防，应当根据实际情况适当提高设防标准，以增强其紧急情况下抗震抢险和救灾的能力。\n各级项目审批部门和设计图审查部门应当将地震工作主管部门确定的建设工程抗震设防要求作为项目审查、设计审核和竣工验收的依据和必备内容。\n第二十六条 县级以上人民政府应当组织有关部门按照国家有关规定，对未采取抗震设防措施或者抗震设防措施未达到要求的既有建筑，进行抗震性能鉴定，并由产权单位依照抗震设防要求采取必要的抗震加固措施。学校、医院、商场、体育场馆等人员密集场所的建设工程应当优先组织鉴定和加固。具体办法由省人民政府规定。\n第二十七条 县级以上人民政府应当加强农村村民住宅和乡村公共设施抗震设防的指导和管理，结合新农村建设、村庄整治以及危房改造等，推广适合不同地区的抗震设计和施工技术，建设抗震示范工程，支持、引导农村建造符合抗震设防要求的住宅和设施。\n对建制镇、集镇规划区公用建筑以及因扶贫搬迁、移民搬迁、灾区重建等而集中建设的村民住宅工程，应当按照抗震设防要求和建设工程的强制性标准进行抗震设防。\n第二十八条 县级以上人民政府应当利用广场、绿地、公园、学校、体育场馆等公共场所和设施，合理确定地震应急避难场所，统筹安排应急避难所需交通、供水、供电、排污等基础设施建设。\n学校、医院、商场、体育场馆等人员密集场所应当设置地震应急疏散通道，并配备必要的救生避险设施。\n地震应急避难场所、应急疏散通道应当设置明显的指示标志。\n第二十九条 机关、团体、企业事业单位应当按照所在地人民政府的要求，结合实际情况，制定防震减灾工作制度，落实相关措施，组织开展地震应急知识的宣传普及活动和地震应急救援演练。地震工作主管部门应当给予专业指导和帮助。\n学校应当将防震减灾知识纳入公共安全教学内容，加强对学生和教师职工地震应急知识教育，每学年组织一次以上地震应急救援和疏散演练，增强师生的安全避险和自救互救能力。\n报刊、广播、电视、互联网站等公众媒体应当开展地震灾害预防和应急、自救互救知识的公益宣传。","level":1},{"name":"第四章 地震应急救援、灾后安置和重建","text":"第三十条 各级人民政府及其有关部门应当加强抗震救灾指挥体系建设，制定地震应急预案，建立和完善相关制度和保障系统，明确职责分工，组织联合演练，健全指挥调度、协调联动、信息共享、社会动员等工作机制，提高地震应急救援、灾后安置组织指挥和应变能力。\n第三十一条 各级人民政府制定本行政区域的地震应急预案，报上一级人民政府地震工作主管部门备案。省会城市地震应急预案，同时报国务院地震工作主管部门备案。\n县级以上人民政府有关部门，根据本级人民政府地震应急预案，制定本部门地震应急预案，并报同级地震工作主管部门备案。\n交通、水利、电力、通信、供水供气等基础设施和学校、医院、商场、体育场馆等人员密集场所的经营管理单位，以及可能发生次生灾害的核电站、矿山、危险物品的生产经营单位，应当制定本单位地震应急预案，并报所在地县级人民政府地震工作主管部门备案。\n地震应急预案应当根据实际需要和形势变化适时修订。\n地震重点监视防御区的市、县、乡镇人民政府、街道办事处应当适时组织开展地震应急预案演练，检验预案执行情况，完善地震应急预案体系和联动协调机制。\n第三十二条 省人民政府和地震重点监视防御区的市、县级人民政府建立地震灾害紧急救援队伍。地震灾害紧急救援队伍可以依托现有消防或者其他应急救援队伍组建，也可以单独组建。\n地震重点监视防御区的乡镇人民政府、街道办事处依托专职消防队、治安联防消防队建立地震灾害紧急救援队伍，承担应急救援工作。\n地震灾害紧急救援队伍应当配备相应的装备和器材，开展培训和演练，提高救援能力。\n第三十三条 鼓励、支持社区、村（居）民委员会、企业事业单位根据需要建立志愿救援队伍，开展群众性自防自救工作。\n鼓励各类志愿者组织参与应急救援、抗震救灾活动。\n第三十四条 县级以上人民政府及其地震工作主管部门和其他有关部门，应当组织地震灾害紧急救援队伍、地震灾害志愿者队伍开展培训和演练，提高救援人员的应急救援和安全防护能力。\n第三十五条 临震预报发布后，相关区域的各级人民政府应当立即采取下列措施：\n（一）加强震情监视，及时报告、通报震情变化；\n（二）责成交通、水利、电力、通信、供水供气等基础设施和学校、医院、商场、体育场馆等人员密集场所经营管理单位，以及核电站、矿山、危险物品的生产经营单位立即采取紧急防护措施；\n（三）责令地震灾害紧急救援队伍和负有特定职责的人员进入待命状态；\n（四）适时组织群众疏散；\n（五）采取维护社会秩序稳定的措施；\n（六）加强地震应急知识和避险技能宣传；\n（七）督促落实抢险救灾准备工作。\n第三十六条 地震灾害发生后，各级人民政府应当按照有关规定立即启动地震应急预案。抗震救灾指挥机构应当立即组织有关部门和单位迅速调查受灾情况，提出地震应急救援力量配置方案，采取国家规定的紧急措施，并根据需要采取以下措施：\n（一）组织有关企业生产应急救援物资，组织、协调社会力量提供援助；\n（二）按规定为运送抗震救灾物资、设备、救援人员和灾区伤病员的车辆提供免费通行等服务；\n（三）向单位和个人征用、调用应急救援所需设备、设施、场地、交通工具和其他物资；\n（四）组织、调配志愿者和灾区群众有序参加抗震救灾活动，并为其提供信息和后勤保障等服务；\n（五）组织新闻媒体及时、准确报道震情、灾情及抗震救灾等信息。\n第三十七条 地震灾害发生后，省人民政府应当及时组织对地震灾害损失进行调查评估，为地震应急救援、灾后过渡性安置和恢复重建提供依据。\n地震灾区的县级以上人民政府地震工作主管部门以及环境保护、卫生、国土资源、水利等有关部门应当对环境、卫生防疫、次生灾害等进行监测和评估，并采取有效的防范措施。\n第三十八条 地震灾区各级人民政府应当妥善做好受灾群众的过渡性安置工作，组织开展生产自救。\n设置过渡性安置点应当考虑环境安全、交通、防疫、防火、防洪、基本农田保护等因素，配套建设必要的基础设施和公共服务设施，确保受灾群众的安全和基本生活需要。\n过渡性安置点所在地的有关部门应当对次生灾害、饮用水水质、食品卫生、疫情等加强监测，组织流行病学调查，开展心理辅导，整治环境卫生。公安机关应当加强治安管理，维护社会秩序。\n第三十九条 特别重大地震灾害发生后，省人民政府应当配合国家有关部门，编制地震灾后恢复重建规划。重大、较大及一般地震灾害发生后，省人民政府应当根据实际需要，组织有关部门和地震灾区的市、县级人民政府编制地震灾后恢复重建规划。\n编制地震灾后恢复重建规划，应当征求有关部门、单位、专家和公众特别是地震灾区受灾群众的意见；重大事项应当组织有关专家进行专题论证。","level":1},{"name":"第五章 监督检查","text":"第四十条 县级以上人民政府及其有关部门对下列防震减灾事项组织开展监督检查：\n（一）防震减灾规划的编制与实施；\n（二）防震减灾工作经费保障；\n（三）地震监测台网的规划、建设、运行，监测设施和监测环境的保护；\n（四）建设工程抗震设防措施与管理；\n（五）地震灾害紧急救援队伍的建设；\n（六）地震应急预案的编制与演练，地震应急避难场所的设置与管理；\n（七）抗震救灾物资储备；\n（八）防震减灾知识宣传教育；\n（九）其他防震减灾工作。\n第四十一条 县级以上人民政府住房和城乡建设、交通、铁路、水利、电力、地震等有关部门应当按照职责分工，加强对工程建设强制性标准、抗震设防要求执行情况和地震安全性评价工作的监督检查。\n第四十二条 县级以上人民政府卫生、食品药品监督、质量技术监督、工商行政管理、价格等有关部门和单位，应当加强对抗震救灾所需食品、药品、消毒产品、建筑材料等物资质量、价格的监督检查。\n第四十三条 县级以上人民政府地震、财政、民政等有关部门和审计机关应当加强对地震应急救援、地震灾后过渡性安置和恢复重建资金、物资以及社会捐赠款物使用情况的监督管理。","level":1},{"name":"第六章 法律责任","text":"第四十四条 违反本条例规定，法律、行政法规有处罚规定的，从其规定。\n第四十五条 违反本条例第十三条规定，未按照要求建设专用地震监测台网和强震动设施的，由县级以上人民政府地震工作主管部门责令限期改正；逾期不改正的，处5000元以上5万元以下的罚款。\n第四十六条 违反本条例第二十一条规定，爆破单位在实施爆破作业前未履行告知义务的，由爆破作业实施地县级以上人民政府地震工作主管部门给予警告；情节严重的，并处2000元以上5000元以下的罚款。\n第四十七条 违反本条例第二十四条第一款第（二）项规定，未进行地震安全性评价，或者未按照地震安全性评价报告确定的抗震设防要求进行抗震设防的，由县级以上人民政府地震工作主管部门责令限期改正；逾期不改正的，处3万元以上30万元以下的罚款。\n第四十八条 违反本条例第二十四条第一款第（一）、（三）、（四）项规定，对不需要进行地震安全性评价的建设工程，建设单位未按照地震工作主管部门确定的抗震设防要求进行抗震设防的，由县级以上人民政府地震工作主管部门会同有关部门责令限期改正；逾期不改正的，处1万元以上10万元以下的罚款。\n第四十九条 制造、散布地震谣言，引发群众恐慌，扰乱社会秩序，构成违反治安管理行为的，由公安机关依法处理；构成犯罪的，依法追究刑事责任。\n第五十条 县级以上人民政府地震工作主管部门以及其他有关行政管理部门的国家工作人员，在防震减灾工作中玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者监察机关依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第五十一条 本条例自2011年12月1日起施行。2001年5月31日湖北省第九届人民代表大会常务委员会第二十五次会议通过的《湖北省实施〈中华人民共和国防震减灾法〉办法》同时废止。","level":1}]},{"id":"h0155","sections":[{"name":"","text":"（2011年12月1日湖北省第十一届人民代表大会常务委员会第二十七次会议通过 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止废止部分省本级地方性法规的决定》第一次修正 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2022年11月25日湖北省第十三届人民代表大会常务委员会第三十四次会议《关于集中修改、废止部分省本级地方性法规的决定》第三次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了加强气象灾害的防御，积极应对气候变化，避免和减轻气象灾害造成的损失，保障人民生命财产安全，促进经济和社会全面、协调、可持续发展，根据《中华人民共和国气象法》及有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内的气象灾害防御活动，适用本条例。\n本条例所称气象灾害，是指暴雨（雪）、干旱、大雾、霾、雷电、大风、低温、高温、冰雹、霜冻、寒潮和台风等所造成的灾害。\n因气象因素引发的衍生、次生的地质灾害、森林火灾、植物病虫害、环境污染、流行疫情等灾害的防御工作，法律、行政法规有相关规定的，从其规定。\n第三条 气象灾害防御是基础性公益事业。气象灾害防御工作坚持政府主导、部门联动、社会参与、科学防御的原则。\n第四条 县级以上人民政府应当加强对气象灾害防御工作的领导，将气象灾害防御工作纳入本地区国民经济和社会发展规划，完善气象灾害防御体系建设，建立健全气象灾害防御工作的协调机制和防灾减灾责任制。\n气象灾害防御工作应当根据气象现代化的总体要求，提升气象预测预报能力、气象防灾减灾能力、应对气候变化能力、气象资源开发利用能力。\n第五条 县级以上气象主管机构负责本行政区域内气象灾害的监测、预报、预警、评估及人工影响天气管理工作；指导相关方面开展气象灾害防御活动；协助有关部门做好气象衍生、次生灾害的监测、预报、预警和减灾等工作。\n县级以上人民政府有关部门按照职责分工，做好气象灾害防御工作。\n乡镇人民政府、街道办事处以及社区、村（居）民委员会应当整合基层现有防灾人力资源，配备、明确气象灾害防御协理人员和信息人员。协理人员和信息人员在当地人民政府及有关部门的领导、指导下，开展气象灾害防御设施管理、气象灾情收集、气象灾害预警信息传播、气象科普宣传和气象为农服务。\n第六条 省人民政府应当合理配置气象灾害防御资源，促进气象灾害防御工作均衡发展，对革命老区、少数民族地区、贫困地区的灾害避难场所、公共防雷设施等基础设施建设、运行、管理、维护投入给予扶持和倾斜。\n第七条 任何单位和个人有义务参与气象灾害防御活动，在气象灾害发生后积极开展自救、互救。\n对在气象灾害防御工作中做出突出贡献的单位和个人，应当给予表彰和奖励。","level":1},{"name":"第二章 灾害预防","text":"第八条 县级以上人民政府应当组织气象等有关部门对本行政区域内易发的气象灾害种类、次数、强度和造成的损失等情况开展气象灾害普查，建立气象灾害数据库，按照气象灾害种类进行气象灾害风险评估，划定气象灾害风险区域，设立警示标志并予以公告。\n气象灾害风险评估应当包括以下内容：\n（一）气象灾害历史、现状分析；\n（二）气象灾害风险预估；\n（三）预防或者减轻气象灾害影响的对策和措施；\n（四）气象灾害风险评估结论。\n第九条 县级以上人民政府应当组织有关部门结合本地气象灾害特点、风险评估结果以及经济社会发展趋势，编制本行政区域的气象灾害防御规划，并根据气象灾害变化情况及时修订。\n气象灾害防御规划应当包括下列主要内容:\n（一）气象灾害防御的指导思想、原则、目标和任务；\n（二）气象灾害现状及发展趋势的预测、预估和评估；\n（三）气象灾害易发区域和重点防御区域；\n（四）气象灾害防御标准；\n（五）气象灾害防御项目、措施和实施方案；\n（六）气象灾害防御设施建设和管理；\n（七）气象灾害应急处置措施；\n（八）法律、法规规定的其他内容。\n第十条 气象灾害防御规划应当作为编制城乡规划，区域、流域建设开发利用规划和土地利用总体规划的重要依据。\n重大基础设施项目的选址和建设，应当符合防御气象灾害的要求。\n第十一条 各级人民政府、有关部门和单位应当根据当地气象主管机构所属气象台（站）提供的降雨、降雪、大风等灾害性天气情况及预测，及时组织开展各种排水设施检查，加强对地质灾害易发区、洪涝易发区等地的巡查；及时巡查电力、通信线路，做好交通疏导、积雪（冰）清除、线路维护等准备工作；及时组织开展江河、湖库、港口、工地、建（构）筑物防风避险的监督检查。\n第十二条 各级人民政府、有关部门和单位应当加强对机场、港口、高速公路、航道、铁路、渔场等重要场所和交通要道的大雾、霾的监测设施建设，及时向公众提供大雾、霾灾害监测信息，保障交通安全。\n第十三条 县级以上人民政府应当根据气象灾害防御工作的需要，配备必要的人员和人工影响天气设备、设施，建立统一协调的指挥和作业体系。\n干旱、冰雹、森林火灾多发区域和城市供水、工农业用水紧缺地区的水源地及其上游地区的各级人民政府应当根据实际情况，安排本级气象主管机构组织开展人工增雨（雪）或者防雹等人工影响天气作业，预防和避免发生严重灾情。\n第十四条 县级以上人民政府应当将防雷减灾工作纳入公共安全监督管理的范围。气象主管机构应当加强对雷电灾害防御工作的管理，提高雷电灾害监测预报及风险评估能力，依法进行雷电安全防护装置的设计审核、竣工验收。县级以上人民政府建设行政主管部门应当将防雷装置竣工验收资料纳入建设项目档案，并加强监督管理。\n《湖北省雷电灾害防御条例》有关雷电灾害防御已有规定的，从其规定。\n第十五条 城乡规划、重大工程建设项目、重大区域性经济开发项目和大型太阳能、风能等气候资源开发利用建设项目，应当进行气候可行性论证。\n气候可行性论证应当委托国家气象主管机构确认的具备气象可行性论证能力的单位进行，并使用符合国家气象技术标准的气象资料。","level":1},{"name":"第三章 灾害监测与预报预警","text":"第十六条 县级以上人民政府应当按照合理布局、有效利用、资源共享的原则，建立跨地区、跨部门的气象灾害联合监测网络和气象灾害监测信息共享平台，完善气象灾害监测体系和信息共享机制，健全应急监测队伍。\n有关部门和单位应当按照各自职责开展气象灾害及衍生、次生灾害的监测工作，并及时、准确、无偿地向气象灾害信息共享平台提供气象、水情、旱情、森林火险、地质险情、环境污染、植物病虫害等与气象灾害有关的监测信息，保障信息资源共享。\n气象主管机构对气象灾害监测信息共享平台进行统一管理和协调。\n第十七条 气象主管机构应当加强气象灾害综合监测、预报预警、应急服务等基础设施建设；在城市、乡镇以及气象灾害易发区域和气象灾害重点防御区域，统一规划设置加密气象观测站、应急移动气象灾害监测设施，完善气象灾害自动监测网点。\n有关部门和单位建设的气象监测站点应当符合气象标准和规范，并到当地气象主管机构备案。\n任何单位和个人不得侵占、损毁或者擅自移动气象灾害防御设施。\n第十八条 可能发生气象灾害时，有关监测网络成员单位应当进行加密观测；气象主管机构所属气象台（站）应当组织跨区域预报会商和监测联防，并根据天气变化情况，及时发布灾害性天气预警信息。\n第十九条 气象主管机构及其所属气象台（站）应当提高气象灾害预报、警报的准确性、时效性，做好灾害性、关键性、转折性天气预报、警报和灾害趋势预测，及时向本级人民政府报告，并通报相关防灾减灾机构和部门，不得瞒报、谎报。\n第二十条 气象主管机构所属气象台（站）应当按照职责和公共服务需要向社会统一发布灾害性天气警报和气象灾害预警信号，并根据天气变化情况及时补充、订正，其他组织和个人不得向社会发布灾害性天气警报和气象灾害预警信号。\n气象主管机构应当会同有关部门和单位建立、完善气象灾害预警系统，为防汛抗旱、森林防火、城市运行安全、工农业生产、公共卫生事件和突发环境事件应急处置、地质灾害防治、交通安全、应急救援等提供气象保障服务。\n第二十一条 有关部门和单位应当根据气象灾害防御的需要，在学校、医院、体育场（馆）、机场、高速公路、车站等公共场所及乡村显著位置，组织设立预警信息接收和播放设施。\n各级人民政府及有关部门应当加强边远农村、山区、渔区预警信息接收终端建设，因地制宜地利用有线广播、预警喇叭、显示屏等及时向受影响的公众传播信息。\n第二十二条 广播、电视、报纸、通信、网络等媒体载体应当及时、准确、无偿向社会播发或者刊登当地气象主管机构所属气象台（站）提供的适时灾害性天气警报、气象灾害预警信号，并根据当地气象台（站）的要求及时增播、插播或者刊登；不得拒绝传播，延误传播，更改、删减灾害性天气警报和气象灾害预警信号；不得传播虚假、过时的灾害性天气警报和预警信号。\n第二十三条 乡镇人民政府、街道办事处的气象灾害防御协理人员，社区、村（居）民委员会的气象灾害防御信息人员和学校、医院、体育场（馆）、机场、高速公路、车站等公共场所的管理单位确定的气象灾害防御联络人员，收到气象主管机构所属气象台（站）提供的灾害性天气警报、预警信号后，应当及时向受影响的公众传播。","level":1},{"name":"第四章 灾害应急","text":"第二十四条 县级以上人民政府应当组织有关部门、重点单位，根据气象灾害防御规划，制定本行政区域的气象灾害应急预案，报上一级人民政府、有关部门备案，并向社会公布。\n气象灾害应急预案应当包括启动标准、组织指挥体系与职责、预防与预警机制、处置措施和保障措施等内容。\n第二十五条 县级以上人民政府及其有关部门应当根据本地实际，整合现有防灾救助资源，建立健全气象灾害应急救援队伍，并按照应急预案的要求开展应急演练。\n鼓励志愿者参与气象灾害应急救援，帮助公众开展防灾、避灾工作。\n第二十六条 县级以上人民政府应当根据气象主管机构所属气象台（站）发布的灾害性天气警报、预警信号和可能造成的危害，适时启动相应级别的应急预案，并报告上一级人民政府；必要时，可以越级上报，并向当地驻军和可能受到危害的毗邻地区的人民政府通报。\n县级以上人民政府应当组织有关部门建立高风险区域、高敏感行业、高危人群气象灾害红色预警信号应对机制，推动气象灾害预警信号及时转化为气象灾害防御工作指令。\n第二十七条 发生重大气象灾害，当地人民政府及其有关部门应当根据气象灾害预警等级和应急预案，及时采取相应的应急措施，并及时予以公告。\n气象灾害发生地的单位和个人应当服从政府的决定、命令，配合政府和有关部门采取应急措施，做好应急救援工作。\n气象灾害发生地的社区、村（居）民委员会和其他单位应当按照当地人民政府的决定、命令，进行宣传动员，组织群众开展自救和互救，协助维护社会秩序；受到灾害威胁时，应当及时组织人员转移、疏散。\n第二十八条 气象灾害应急预案启动后，气象主管机构应当组织所属气象台（站）对灾害性天气进行跟踪监测，开展现场气象服务，及时向本级人民政府和有关部门报告灾害性天气实况、变化趋势，为本级人民政府组织防御气象灾害提供决策依据。\n第二十九条 任何单位和个人发现气象灾情，有义务向当地人民政府和气象主管机构、民政部门报告。\n禁止传播虚假或者非法获取的气象灾情。\n第三十条 县级以上人民政府应当根据气象主管机构提供的灾害性天气发生、发展趋势信息以及灾情发展情况，按照有关规定适时调整气象灾害级别或者作出解除气象灾害应急措施的决定。","level":1},{"name":"第五章 灾害防御保障","text":"第三十一条 各级人民政府应当加强气象灾害防御工作的组织与协调，完善与气象灾害防御工作有关的配套措施，明确部门职责分工，并纳入政府目标考核体系。\n第三十二条 县级以上人民政府应当组织开展气象灾害发生机理、预报和防御技术研究，推广先进适用的技术，健全气象灾害防御技术的标准和规范，提升气象灾害防御能力。\n第三十三条 各级人民政府及有关部门、各新闻媒体应当加强气象科普和防灾减灾知识宣传，增强社会公众防御气象灾害的意识，提高防灾减灾能力。\n教育部门应当将气象灾害防御知识纳入有关教学内容，在科协、气象等部门指导下开展科普活动，培养、提高学生气象灾害防范意识和自救、互救能力。\n第三十四条 建立和完善气象灾害防御投入机制。\n各级人民政府应当将气象灾害防御工作所需经费列入财政预算，保证气象灾害监测预警、信息发布、应急指挥及灾害救助等防灾减灾方面的建设、运行、管理与维护经费，并根据经济社会发展和气象灾害防御工作的需要逐步增加。\n鼓励单位和个人通过金融、保险等形式提高气象灾害风险防御能力。\n第三十五条 县级以上人民政府应当加强气象灾害防御队伍建设，形成统一领导、统筹协调、分级负责、分类管理的人才队伍管理体制，将气象灾害防御人才队伍建设纳入人才战略规划；建立完善专业人才、社会工作者和志愿者培训制度；建立有效的激励机制，稳定和加强基层人才队伍。","level":1},{"name":"第六章 法律责任","text":"第三十六条 违反本条例规定，法律、行政法规有处罚规定的，从其规定；造成损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第三十七条 违反本条例第十七条第三款规定的，由县级以上气象主管机构责令停止违法行为，限期恢复原状或者采取其他补救措施，可以并处5千元以上5万元以下的罚款。\n第三十八条 各级人民政府、各级气象主管机构和其他有关部门及其工作人员在气象灾害防御工作中有下列行为之一，由上级机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）未按照本条例第十六条第二款规定向气象灾害监测信息共享平台提供数据、信息的；\n（二）未按照规定采取气象灾害预防措施和应急处置措施的；\n（三）气象灾害发生后未及时组织开展应急救援工作的；\n（四）瞒报、谎报或者因玩忽职守漏报、错报灾害性天气警报、气象灾害预警信号的；\n（五）其他玩忽职守、滥用职权、徇私舞弊行为的。","level":1},{"name":"第七章 附则","text":"第三十九条 本条例自2012年2月1日起施行。","level":1}]},{"id":"h0156","sections":[{"name":"第一章 总则","text":"第一条 为了保障省人民代表大会代表（以下简称“代表”）依法行使提出建议、批评和意见的权利，做好交办、承办和监督工作，发挥代表作用，根据《中华人民共和国地方各级人民代表大会和地方各级人民政府组织法》、《中华人民共和国全国人民代表大会和地方各级人民代表大会代表法》的有关规定，结合本省实际，制定本规定。\n第二条 本规定所称代表建议、批评和意见，是指代表在省人民代表大会会议期间和闭会期间分别向省人民代表大会及其常务委员会提出的对各方面工作的建议、批评和意见。\n代表提出建议、批评和意见是法律赋予代表的权利，是执行代表职务，参加管理地方国家事务、管理经济和文化事业、管理社会事务的一项重要工作。\n第三条 办理代表建议、批评和意见是有关机关、组织的法定职责。有关机关、组织应当认真研究办理代表提出的建议、批评和意见，并负责答复代表。\n有关主管机关应当对承办单位办理代表建议、批评和意见工作进行考核。\n第四条 省人民代表大会常务委员会工作机构应当加强与有关机关、组织的联系、协调，共同研究代表建议、批评和意见办理工作中的问题，健全完善相关制度，提高办理工作的质量和效率。\n第五条 省人民代表大会常务委员会工作机构应当为代表提出建议、批评和意见提供必要的条件和服务。\n省人民代表大会会议期间，大会秘书处应当为代表提出建议、批评和意见提供条件和服务。各代表团应当配备专门工作人员，为代表提出建议、批评和意见做好服务保障工作。","level":1},{"name":"第二章 代表建议、批评和意见的提出","text":"第六条 代表有权对省人民代表大会及其常务委员会、省人民政府及其所属部门、省高级人民法院、省人民检察院和其他机关、组织的工作提出建议、批评和意见。\n第七条 代表应当与原选举单位和人民群众保持密切联系，积极参加代表培训、视察、专题调研、执法检查、代表小组活动等履职活动，深入实际，广泛听取各方面的意见和要求，围绕经济社会发展和人民群众普遍关心的问题，认真研究提出建议、批评和意见。代表建议、批评和意见应当明确具体，注重反映实际情况和问题。\n第八条 下列情形不作为代表建议、批评和意见提出：\n（一）不属于省级有关机关、组织职权范围内的事务的；\n（二）涉及解决代表本人及其亲属等个人问题的；\n（三）涉及具体司法案件的；\n（四）代转人民群众来信的；\n（五）属于学术探讨的；\n（六）属于产品推介的；\n（七）没有实际内容的；\n（八）其他不应当作为代表建议、批评和意见提出的。\n对属于上述情形的，省人民代表大会常务委员会工作机构向代表说明情况后，可以退回代表或者作代表来信处理。\n第九条 代表建议、批评和意见可以单独提出，也可以联名提出。代表联名提出的，领衔代表应当通过介绍情况、集体讨论等方式，使其他联名代表了解建议、批评和意见的内容，确认其能够真实表达自己的意愿后，再签名附议。\n代表建议、批评和意见一般以书面形式提出，并由代表亲笔签名；如以电子文本提出的，需由代表确认。\n第十条 代表可以撤回本人提出的建议、批评和意见。要求撤回的，应当以书面形式提出，其办理工作即行终止。","level":1},{"name":"第三章 代表建议、批评和意见的交办","text":"第十一条 代表建议、批评和意见的交办，根据国家机关、组织的职责分工，按照分级负责、归口办理的原则，确定承办单位。\n第十二条 代表向省人民代表大会及其常务委员会提出的对各方面工作的建议、批评和意见，由常务委员会工作机构交有关机关、组织承办。其中属于对省人民政府及其所属部门的建议、批评和意见，由常务委员会工作机构统一交省人民政府办公厅，再由省人民政府办公厅协调落实承办单位。属于对下级机关、组织的建议、批评和意见，由常务委员会工作机构通过各市（州）人民代表大会常务委员会交当地有关机关、组织承办。\n代表提出的解决本人及其亲属个人问题或者代转人民群众来信等事项，由常务委员会工作机构转作人民来信处理，并于转交之日起十日内告知代表。\n第十三条 代表在省人民代表大会会议期间提出的建议、批评和意见，由大会秘书处受理并研究提出交办意见，经大会主席团同意后交办。\n代表在省人民代表大会闭会期间提出的建议、批评和意见，由常务委员会工作机构受理，并于十日内交办。\n第十四条 代表建议、批评和意见需由两个以上单位共同办理的，交办时应当明确主办单位和协办单位。协办单位应当按照本单位职责，配合主办单位做好办理工作。\n代表建议、批评和意见需由两个以上单位分别办理的，交办时应当明确分办单位，由各分办单位按照各自的职责研究办理。\n第十五条 承办单位对代表建议、批评和意见应当及时研究，对不属于本单位职责范围内的代表建议、批评和意见，应当自收到之日起十日内书面向交办机构说明情况，经交办机构同意后退回，不得滞留、延误和自行转办。\n交办机构对于承办单位退回的代表建议、批评和意见，应当自收到之日起十日内重新确定承办单位并交办。\n第十六条 省人民代表大会常务委员会工作机构，应当在对代表建议、批评和意见进行调查研究、综合分析以及征求相关方面意见的基础上，提出拟重点办理的代表建议、批评和意见，经常务委员会主任会议研究确定后，交有关机关、组织重点研究办理。\n第十七条 拟重点办理的代表建议、批评和意见根据下列情形确定：\n（一）事关经济社会发展和人民群众普遍关心的重大问题；\n（二）代表反映比较集中的问题；\n（三）综合性强、涉及面广、办理难度大的问题；\n（四）与省人民代表大会常务委员会和省人民政府年度工作重点相一致的问题。\n第十八条 省人民代表大会常务委员会工作机构应当自代表建议、批评和意见交办之日起三十日内将交办情况书面告知代表。","level":1},{"name":"第四章 代表建议、批评和意见的承办","text":"第十九条 承办单位应当建立健全代表建议、批评和意见办理工作制度，实行主管领导、部门负责人和具体承办人员分级负责制，规范办理程序，注重办理质量，提高办理实效。\n第二十条 承办单位在办理代表建议、批评和意见的过程中，应当主动与代表联系，充分听取意见，共同研究解决办法。对重点办理的代表建议、批评和意见，应当邀请代表参与研究。代表对办理工作有不同意见的，可以向省人民代表大会常务委员会工作机构提出，常务委员会工作机构应当督促承办单位及时改进。\n代表建议、批评和意见涉及国家秘密的，承办单位应当依法做好保密工作。\n第二十一条 承办单位应当按照下列规定办理代表建议、批评和意见：\n（一）凡是有条件解决的问题，应当尽快解决并答复代表；\n（二）对应该解决但受条件限制暂时难以解决的问题，应当纳入工作计划，明确办理时限，答复代表并向代表说明情况，在妥善解决后再次答复代表；\n（三）对不符合法律规定和政策规定或者不具备条件无法解决的问题，应当向代表说明原因；\n（四）对属于上级机关、组织职权范围的问题，应当及时向上级机关、组织反映，并向代表说明情况。\n承办单位答复代表后，如因各类原因答复内容有所调整的，应当及时将调整内容向代表反馈并说明相关情况。\n第二十二条 对重点办理的代表建议、批评和意见，由承办单位的主要负责人负责研究办理。省人民代表大会相关专门委员会或者常务委员会工作机构可以选择部分重点办理的代表建议、批评和意见，向主任会议提出督办建议，由主任会议组织督办。\n第二十三条 承办单位应当自代表建议、批评和意见交办之日起三个月内将办理结果答复代表；涉及面广、办理难度大，不能按期办理完毕的代表建议、批评和意见，应当向交办机构和代表说明情况，自交办之日起六个月内答复代表。\n代表可以直接向承办单位或者通过省人民代表大会常务委员会工作机构了解所提建议、批评和意见的办理情况。\n第二十四条 由两个以上单位共同承办的代表建议、批评和意见，主办单位应当主动与协办单位协商，协办单位应当在收到代表建议、批评和意见两个月内将书面办理意见送交主办单位，由主办单位统一答复代表。主办单位答复代表时，应当向代表说明协办单位的办理意见。主办单位、协办单位意见不一致的，由主办单位协调，并将协调情况告知代表。省人民政府所属部门因意见不一致，经主办单位协调仍不能取得一致意见的，由省人民政府协调。\n由两个以上单位分别办理同一件代表建议、批评和意见的，承办单位应当根据各自的职责分别办理并答复代表。\n第二十五条 承办单位对代表联名提出的建议、批评和意见，应当分别答复参加联名的每一位代表。\n承办单位对内容相同的代表建议、批评和意见，可以并案办理，并分别答复代表。\n第二十六条 承办单位对代表建议、批评和意见的答复，应当按照统一格式行文，由承办单位负责人签发，并加盖本单位公章，注明承办负责人、承办人和联系人及联系方式。\n承办单位对代表建议、批评和意见的答复，应当及时抄送省人民代表大会常务委员会工作机构；属于省人民政府职权范围内的，应当同时抄送省人民政府办公厅。\n承办单位在代表建议、批评和意见全部办结后，应当及时向省人民代表大会常务委员会工作机构报告办理工作情况。\n第二十七条 代表对办理结果不满意的，可以向省人民代表大会常务委员会工作机构提出要求，由常务委员会工作机构研究后交承办单位组织重新办理，并在三个月内再次答复代表，属于省人民政府及其所属部门办理的，由常务委员会工作机构交省人民政府办公厅落实重新办理。","level":1},{"name":"第五章 代表建议、批评和意见办理的监督","text":"第二十八条 省人民代表大会常务委员会工作机构在法定办理期限内应当寄送代表建议、批评和意见征询意见表，征求代表对办理结果的意见。代表应当认真填写征询意见表，并在一个月内寄回省人民代表大会常务委员会工作机构。代表联名提出的建议、批评和意见的征询意见表，由领衔代表征求其他联名代表意见后反馈。\n代表对办理结果的反馈意见总体情况，由省人民代表大会常务委员会工作机构纳入关于代表建议、批评和意见交办情况的报告，向省人民代表大会常务委员会报告。\n第二十九条 省人民代表大会常务委员会及其工作机构应当加强与承办单位和相关代表的联系，及时掌握代表建议、批评和意见办理情况，通过召开督办会议，组织代表视察、专题调研、执法检查、办理工作测评等方式，督促办理工作的落实。\n省人民政府应当研究解决代表建议、批评和意见办理工作中的重大问题，加强对所属部门办理工作的组织协调和督促检查。\n各承办单位应当加强对具体办理工作的督促检查。\n第三十条 省人民代表大会常务委员会应当听取省人民政府、省高级人民法院、省人民检察院关于代表建议、批评和意见办理工作情况的报告。报告经省人民代表大会常务委员会审议后，印发下一次人民代表大会会议。\n代表建议、批评和意见办理工作情况，应当予以公开。省人民代表大会常务委员会工作机构关于代表建议、批评和意见交办情况的报告，省人民政府、省高级人民法院、省人民检察院关于代表建议、批评和意见办理情况的报告应当在省人民代表大会常务委员会公报及相关媒体上公开登载。\n第三十一条 省人民代表大会常务委员会工作机构应当加强代表建议、批评和意见办理工作的研究，总结推广办理工作经验，指导推进各有关方面改进办理工作，提高办理实效。\n省人民代表大会常务委员会对办理代表建议、批评和意见成效显著的单位和个人，应当予以表彰。\n第三十二条 承办单位违反本规定，有下列情形之一的，由其上级机关责令改正，省人民代表大会常务委员会主任会议可以要求承办单位说明情况，必要时，责成有关机关依法追究承办单位负责人及有关责任人员的责任：\n（一）对办理工作无故拒不受理或者敷衍塞责的；\n（二）隐瞒事实真相、弄虚作假的；\n（三）逾期不办理又不说明理由的；\n（四）贻误办理工作造成损失或者负面影响的；\n（五）对提出建议、批评和意见的代表进行刁难、威胁、打击报复的。","level":1},{"name":"第六章 附则","text":"第三十三条 本规定自2012年6月1日起施行。1996年7月24日湖北省第八届人民代表大会常务委员会第二十一次会议通过的《湖北省各级人民代表大会代表建议、批评和意见办理工作的规定》同时废止。","level":1}]},{"id":"h0157","sections":[{"name":"","text":"（2012年5月30日湖北省第十一届人民代表大会常务委员会第三十次会议通过 根据2021年9月29日湖北省第十三届人民代表大会常务委员会第二十六次会议《关于集中修改涉及长江保护法省本级地方性法规的决定》第一次修正 根据2022年11月25日湖北省第十三届人民代表大会常务委员会第三十四次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第三次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了加强湖泊保护，防止湖泊面积减少和水质污染，保障湖泊功能，保护和改善湖泊生态环境，促进经济社会可持续发展，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内的湖泊保护、利用和管理活动适用本条例。\n湖泊渔业生产活动和水生野生动植物的保护按照有关法律、法规的规定执行。\n法律、法规对湿地和风景名胜区、自然保护区内湖泊的保护另有规定的，从其规定。\n重要湖泊可根据其功能和实际需要，另行制定地方性法规或者政府规章，以加强保护。\n水库的水污染防治适用本条例。\n第三条 湖泊保护工作应当遵循保护优先、科学规划、综合治理、永续利用的原则，达到保面（容）积、保水质、保功能、保生态、保可持续利用的目标。\n第四条 湖泊保护实行名录制度。本省行政区域内湖泊保护名录，经省人民政府水行政主管部门会同发展改革、生态环境、自然资源、农业农村、林业、住房和城乡建设、交通运输、文化和旅游等有关主管部门根据湖泊的功能、面积，以及应保必保原则拟定和调整，由省人民政府确定和公布，并报省人大常委会备案。","level":1},{"name":"第二章 政府职责","text":"第五条 县级以上人民政府应当加强对湖泊保护工作的领导，将湖泊保护工作纳入国民经济和社会发展规划，协调解决湖泊保护工作中的重大问题。跨行政区域的湖泊保护工作，由其共同的上一级人民政府和区域内的人民政府负责。\n跨行政区域湖泊的保护机构及其职责由省人民政府确定。\n跨行政区域湖泊的保护机构应当切实履行湖泊保护职责，协助本级人民政府及其有关部门做好湖泊保护工作。\n第六条 湖泊保护实行政府行政首长负责制。\n上级人民政府对下级人民政府湖泊保护工作实行年度目标考核，考核目标包括湖泊数量、面（容）积、水质、功能、水污染防治、生态等内容。具体考核办法由省人民政府制定。\n湖泊保护年度目标考核结果，应当作为当地人民政府主要负责人、分管负责人和部门负责人任职、奖惩的重要依据。\n第七条 县级以上人民政府水行政主管部门主管本行政区域内的湖泊保护工作，依法履行以下职责：\n（一）湖泊状况普查和信息发布；\n（二）拟定湖泊保护规划及湖泊保护范围；\n（三）确定湖泊生态水位的管控指标；\n（四）湖泊水资源统一管理；\n（五）防汛抗旱水利设施建设；\n（六）涉湖工程建设项目的管理与监督；\n（七）湖泊水生态修复；\n（八）法律、法规等规定的其他职责。\n县级以上人民政府水行政主管部门应当明确相应的管理机构负责湖泊的日常保护工作。\n第八条 县级以上人民政府生态环境主管部门在湖泊保护工作中依法履行以下职责：\n（一）编制湖泊水生态环境保护规划；\n（二）编制与调整水功能区划；\n（三）水污染源的监督管理；\n（四）湖泊水质、水环境质量监测和信息发布；\n（五）水污染综合治理和监督；\n（六）审批涉湖建设项目生态环境影响报告书、生态环境影响报告表；\n（七）组织指导湖泊流域内城镇和农村环境综合整治工作；\n（八）法律、法规等规定的其他职责。\n县级以上人民政府农业农村主管部门在湖泊保护工作中依法履行以下职责：\n（一）设定禁渔区和确定禁渔期；\n（二）渔业种质资源保护；\n（三）渔业养殖的监管；\n（四）农业面源污染防治；\n（五）组织制定和实施渔业开发利用保护规划；\n（六）法律、法规等规定的其他职责。\n县级以上人民政府林业主管部门在湖泊保护工作中依法履行以下职责：\n（一）湿地自然保护区和湿地公园的建设、管理；\n（二）环湖生态防护林、水源涵养林工程建设；\n（三）湖泊湿地生态修复；\n（四）湖泊生物多样性的保护；\n（五）法律、法规等规定的其他职责。\n县级以上人民政府发展改革、财政、住房和城乡建设、自然资源、公安、交通运输、文化和旅游等其他主管部门按照各自职责做好湖泊保护工作。\n第九条 省、市、县、乡依法建立健全湖长制。各级湖长负责本行政区域湖泊管理和保护相关工作。\n县级以上人民政府应当建立和完善湖泊保护的部门联动机制，实行由政府负责人召集，相关部门参加的湖泊保护联席会议制度。\n联席会议由政府负责人主持，日常工作由水行政主管部门承担。\n第十条 各级人民政府应当建立和完善湖泊保护投入机制，将湖泊保护所需经费列入财政预算。\n第十一条 县级以上人民政府应当通过财政、税收、金融、土地使用、能源供应、政府采购等措施，鼓励和扶持企业为减少湖泊污染进行技术改造或者转产、搬迁、关闭。\n第十二条 县级以上人民政府应当根据湖泊保护规划的要求和恢复湖泊生态功能的需要，对居住在湖上，岸上无房屋、无耕地的渔民和居住在湖泊保护区内的其他农（渔）民实施生态移民，采取资金支持、技能培训、转移就业、社会保障等方式予以扶持。\n第十三条 对重要湖泊的保护，省人民政府应当建立生态保护补偿机制，在资金投入、基础设施建设等方面给予支持。\n第十四条 县级以上人民政府应当鼓励和支持湖泊保护的科学研究和技术创新，运用科技手段加强湖泊的监测、污染防治和生态修复。","level":1},{"name":"第三章 湖泊保护规划与保护范围","text":"第十五条 县级以上人民政府应当编制湖泊保护总体规划，并报上一级人民政府批准。国土空间规划、水生态环境保护规划、湿地保护规划和湖泊保护总体规划应当相互衔接。\n第十六条 县级以上人民政府水行政主管部门应当根据湖泊保护总体规划，按照管理权限，组织对列入湖泊保护名录的湖泊分别拟定湖泊保护详细规划，征求相关部门和公众意见，报本级人民政府批准后公布实施，并报本级人民代表大会常务委员会和上级水行政主管部门备案。\n湖泊保护详细规划应当包括湖泊保护范围，湖泊水功能区划分和水质保护目标，重要湖泊生态水位的管控指标，水域岸线空间管控要求，水域纳污能力和限制排污总量意见，防洪、除涝和水土流失防治目标，种植、养殖控制目标，退田（池）还湖，生态修复，绿色低碳发展等内容。\n第十七条 湖泊保护规划不得随意变更，确需修改的应当按照法定程序进行。\n各级人民政府及其有关部门不得违反湖泊保护规划批准开发利用湖泊资源，任何单位和个人不得违反湖泊保护规划开发利用湖泊资源。\n第十八条 实行湖泊普查制度。\n县级以上人民政府水行政主管部门应当定期组织实施湖泊状况普查，建立包括名称、位置、面（容）积、调蓄能力、主要功能等内容的湖泊档案。\n第十九条 县级以上人民政府应当依据湖泊保护规划，对湖泊进行勘界，划定湖泊保护范围，设立保护标志，确定保护责任单位和责任人，并向社会公示。\n第二十条 湖泊保护范围包括湖泊保护区和湖泊控制区。\n湖泊保护区按照湖泊设计洪水位划定，包括湖堤、湖泊水体、湖盆、湖洲、湖滩、湖心岛屿等。湖泊设计洪水位以外区域对湖泊保护有重要作用的，划为湖泊保护区。城市规划区内的湖泊，湖泊设计洪水位以外不少于50米的区域划为湖泊保护区。\n湖泊控制区在湖泊保护区外围根据湖泊保护的需要划定，原则上不少于保护区外围500米的范围。\n第二十一条 在湖泊保护区内，禁止建设与防洪、改善水环境、生态保护、航运和道路等公共设施无关的建筑物、构筑物。\n在湖泊保护区内建设防洪、改善水环境、生态保护、航运和道路等公共设施的，应当进行生态环境影响评价。\n建设单位经依法批准在湖泊保护区内从事建设的，应当做到工完场清；对影响湖泊保护的施工便道、施工围堰、建筑垃圾应当及时清除。\n第二十二条 禁止填湖建房、填湖建造公园、填湖造地、围湖造田、筑坝拦汊以及其他侵占和分割水面的行为。\n湖泊已经被围垦或者筑坝拦汊的，应当按照湖泊保护规划，逐步退田（圩）还湖。\n第二十三条 在湖泊保护范围内新设、改设、扩大排污口的，应当报经有管辖权的生态环境主管部门或者国务院生态环境主管部门流域生态环境监督管理机构同意，并由生态环境主管部门负责对该建设项目的生态环境影响报告书、生态环境影响报告表进行审批。新设、改设、扩大可能影响防洪、供水、堤防安全、河势稳定的排污口的，审批时应当征求水行政主管部门或者有关流域管理机构的意见；涉及通航、渔业水域的，应当征求交通运输、农业农村主管部门的意见。对未达到水质目标的水功能区，除污水集中处理设施排污口外，应当严格控制新设、改设或者扩大排污口。\n第二十四条 湖泊控制区内的土地开发利用应当与湖泊的公共使用功能相协调，预留公共进出通道和视线通廊。\n禁止在湖泊控制区内从事可能对湖泊产生污染的项目建设和其他危害湖泊生态环境的活动。","level":1},{"name":"第四章 湖泊水资源保护","text":"第二十五条 实行最严格的湖泊水资源保护制度。湖泊水资源配置实行统一调度、分级负责，优先满足城乡居民生活用水，保障基本生态用水、粮食安全用水，并统筹农业、工业、生态修复用水以及航运等需要，维持湖泊合理水位。\n第二十六条 省人民政府生态环境主管部门应当会同发展改革、水行政、农业农村、林业、住房和城乡建设、交通运输、文化和旅游等有关部门，按照流域综合规划、湖泊保护总体规划和经济社会发展需要，拟定和调整湖泊的水功能区划，依法报经批准和备案，并向社会公布。\n在湖泊内进行养殖、航运、旅游等活动，应当符合该湖泊的水功能区划要求。\n第二十七条 加强对湖泊饮用水水源地的保护。对具有饮用水水源地功能的湖泊，县级以上人民政府应当按照规定划定饮用水水源保护区，设立相关保护标志。水行政主管部门应当科学调度，防止水源枯竭；生态环境主管部门应当开展日常巡查和监测，防止水体污染。\n第二十八条 县级以上人民政府水行政主管部门应当会同生态环境、农业农村主管部门根据湖泊生态保护需要确定湖泊的最低水位线，设置最低水位线标志。\n湖泊水位接近最低水位线的，应当采取补水、限制取水等措施。\n第二十九条 省人民政府应当按照统一规划布局、统一标准方法、统一信息发布的要求，建立湖泊监测体系和监测信息协商共享机制。\n县级以上人民政府生态环境主管部门应当定期向社会公布本行政区域湖泊水环境质量监测信息；水文水资源信息由水行政主管部门统一发布；发布水文水资源信息涉及水环境质量的内容，应当与生态环境主管部门协商一致。","level":1},{"name":"第五章 湖泊水污染防治","text":"第三十条 省人民政府应当拟订湖泊重点水污染物排放总量削减和控制计划，逐级分解至县（市、区）人民政府，并落实到排污单位。\n第三十一条 县级以上人民政府生态环境主管部门应当按照水环境质量改善目标和水污染防治要求，确定湖泊水域重点污染物排放总量控制指标。\n县级以上人民政府生态环境主管部门应当对湖泊水质状况进行监测，发现湖泊水质未达到该水功能区水质要求的，应当及时报告有关人民政府采取治理措施，并向水行政主管部门通报。\n第三十二条 省人民政府生态环境主管部门根据湖泊水污染防治、产业结构优化和产业布局调整的需要，拟定湖泊重点水污染物排放限值适用的具体地域范围和期限，经省人民政府批准，并报国务院生态环境主管部门备案。\n第三十三条 对湖泊水环境质量不能满足水功能区要求的区域，生态环境主管部门应当暂停审批新增重点水污染物排放总量的建设项目的生态环境影响报告书、生态环境影响报告表。\n第三十四条 县级以上人民政府应当加强对湖泊流域内各类工业园区、工业集中区的统一规划布局，依法进行规划生态环境影响评价，配套建设污水集中处理设施。\n湖泊流域内建设项目应当符合国家和省产业政策；禁止新建造纸、印染、制革、电镀、化工、制药等排放含磷、氮、重金属等污染物的企业和项目；对已有的污染企业，县级以上人民政府及其有关部门应当依法责令其限期整改、转产或者关闭。\n第三十五条 县级以上人民政府农业农村主管部门和其他有关部门，应当采取措施指导湖泊流域内农业生产者科学、合理使用化肥、农药等农业投入品，控制过量和不当使用，防止造成水污染。\n县级以上人民政府农业农村主管部门应当科学规划湖泊流域内畜禽饲养区域，鼓励建设生态养殖场，通过发展沼气、生产有机肥和无害化畜禽粪便还田等方式实现畜禽粪污综合利用，减少畜禽养殖污染。\n第三十六条 禁止向湖泊排放未经处理或者处理未达标的工业废水、生活污水。\n禁止向湖泊及其最高水位线以下的滩地和岸坡以及法律法规规定的其他地点倾倒、堆放、贮存固体废物和其他污染物。\n禁止在属于饮用水水源保护区的湖泊水域设置排污口，从事可能污染饮用水水体的活动或者新建、改建、扩建法律、法规禁止建设的项目。\n第三十七条 县级以上人民政府应当统筹安排建设湖泊流域内城镇污水集中处理设施及配套管网、污泥无害化处理处置设施，合理规划建设雨水、污水单独收集设施，提高城镇污水收集率和处理率。新建、在建城镇污水处理厂，应当同步配套建设脱氮除磷设施；已建的城镇污水处理厂没有脱氮除磷设施的，应当增设脱氮除磷设施。\n污水处理厂出水水质应当符合国家和地方标准。\n第三十八条 各级人民政府应当加强湖泊流域内农村生活污水处理设施建设，结合生态乡、镇、村创建和农村环境综合整治活动，实施河塘清淤，改造和完善水利设施，利用河塘沟渠的自净能力处理生活污水。鼓励有条件的地方建设污水人工湿地处理设施、生物滤池设施和接触氧化池等集中或者分散污水处理设施。\n第三十九条 县（市、区）、乡镇人民政府应当统筹安排建设湖泊流域内城乡垃圾收集、运输、处置设施，在村庄设置垃圾收集点，对垃圾分类收集，对化肥、农药、除草剂等包装物分类处理，提高垃圾处理的减量化、无害化和资源化水平。\n第四十条 县级以上人民政府农业农村主管部门应当会同水行政、生态环境等主管部门，按照湖泊的水功能区划、水环境容量和防洪要求编制渔业养殖规划，确定具体的养殖水域、面积、种类和密度等，报本级人民政府批准。\n禁止在湖泊水域围网、围栏养殖；本条例实施前已经围网、围栏的，由县级以上人民政府限期拆除。\n禁止在湖泊水域养殖珍珠和投肥（粪）养殖。\n第四十一条 在湖泊保护范围内，县级以上人民政府应当科学规划旅游业，防止超环境能力过度发展；从事旅游开发应当符合湖泊保护规划的要求，并依法报经批准；有关部门在审批过程中，应当召开听证会听取公众意见。\n经批准设置的各类旅游观光、水上运动、休闲娱乐等设施不得影响水生态环境，应当与自然景观相协调，并配备污水集中处理设施，确保达标排放。\n第四十二条 湖泊内的船舶应当按照要求配备污水、废油、垃圾、粪便等污染物、废弃物收集设施。港口、码头等场所应当配备船舶污染物接收设施，并转移至其他场所进行无害化处理。\n在城区湖泊和具有饮用水水源功能的湖泊从事经营的船舶，不得使用汽油、柴油等污染水体的燃料。\n第四十三条 县级以上人民政府应当组织生态环境、水行政等主管部门编制湖泊水污染突发事件应急预案，定期开展应急演练，做好应急准备、应急处置和事后恢复等工作。","level":1},{"name":"第六章 湖泊生态保护和修复","text":"第四十四条 县级以上人民政府应当加强湖泊生态保护和修复工作，保护和改善湖泊生态系统。\n县级以上人民政府水行政主管部门应当会同生态环境、自然资源、农业农村、林业等主管部门开展湖泊生态环境调查，依法制定和实施修复方案。\n第四十五条 县级以上人民政府应当组织水行政、生态环境、林业、住房和城乡建设等主管部门，运用种植林木、生态补水、生物净化、截污治污、生态清淤、打捞蓝藻、江河湖泊连通等措施，对湖泊水生态系统以及主要入湖河道进行综合治理，逐步恢复湖泊水生态。\n第四十六条 县级以上人民政府林业主管部门应当依据湖泊保护详细规划，会同相关部门修复湖滨湿地，建设湿地恢复示范区，有计划、分步骤地组织实施环湖生态防护林、水源涵养林工程建设。\n第四十七条 维护湖泊生物多样性，保护湖泊生态系统，禁止猎取、捕杀和非法交易野生鸟类及其他湖泊珍稀动物；禁止采集和非法交易珍稀、濒危野生植物。\n在水生动物繁殖及其幼苗生长季节的重要湖区和洄游通道，农业农村主管部门应当设立禁渔区，确定禁渔期。在禁渔区内和禁渔期间，任何单位和个人不得进行捕捞和爆破、采砂等水下作业。\n县级以上人民政府应当组织农业农村等有关主管部门在科学论证的基础上，采取适量投放水生物、放养滤食性鱼类、底栖生物移植等措施修复水域生态系统，并对各类水生植物的残体以及有害水生植物进行清除。","level":1},{"name":"第七章 湖泊保护监督和公众参与","text":"第四十八条 省人民政府应当定期公布湖泊保护情况白皮书，对保护湖泊不力的市（州）、县（市、区）人民政府主要负责人实行约谈，督促其湖泊保护工作。\n第四十九条 县级以上人民政府水行政、生态环境、自然资源、住房和城乡建设、农业农村、林业等主管部门应当依照本条例和相关法律法规的规定，加强对湖泊保护、利用、管理的监督检查，发现违法行为及时查处；对不属于职责范围的，应当移交有管辖权的部门及时查处。\n第五十条 县级以上人民代表大会常务委员会应当通过听取和审议本级人民政府湖泊保护情况的专项工作报告、对本条例实施情况组织执法检查、开展专题询问、质询等方式，依法履行监督职责；必要时可以依法组织关于特定问题的调查。\n第五十一条 县级以上人民政府及其相关部门应当加强湖泊保护的宣传和教育工作，增强公众湖泊保护意识，建立公众参与的湖泊保护、管理和监督机制。\n第五十二条 县级以上人民政府及其相关部门应当定期发布湖泊保护的相关信息，保障公众知情权。\n编制湖泊保护规划、湖泊水生态环境保护规划、湖泊生态修复方案和审批沿湖周边建设项目生态环境影响报告书、生态环境影响报告表，应当采取多种形式征求公众的意见和建议，接受公众监督。\n第五十三条 广播、电视、报刊、网络等媒体应当开展湖泊保护公益性宣传，倡导促进环境友好的生活方式，发挥舆论引导和监督作用。\n第五十四条 鼓励社会各界、非政府组织、湖泊保护志愿者参与湖泊保护、管理和监督工作。\n鼓励社会力量投资或者以其他方式投入湖泊保护。\n社区、村（居）民委员会应当协助当地人民政府开展湖泊保护工作，督促、引导村（居）民依法履行保护湖泊义务。\n第五十五条 在湖泊保护范围内从事生产、经营活动的单位和个人，应当严格遵守湖泊保护法律、法规的规定和湖泊保护规划的规定，自觉接受相关部门和公众的监督，依法、合理、有序利用湖泊。\n第五十六条 县级以上人民政府及相关部门应当建立、完善湖泊保护的举报和奖励制度。\n任何单位和个人有权对危害湖泊的行为进行举报；有处理权限的部门接到检举和举报后，应当及时核查、处理。\n对保护湖泊成绩显著的单位和个人，应当给予表彰和奖励。","level":1},{"name":"第八章 法律责任","text":"第五十七条 违反本条例规定，法律、行政法规已有处罚规定的，从其规定。\n第五十八条 县级以上人民政府、有关主管部门及其工作人员违反本条例规定，有下列行为之一的，由上级人民政府或者有关主管机关依据职权责令改正，通报批评；对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）保护湖泊不力造成严重社会影响的；\n（二）未依法对湖泊进行勘界，划定保护范围，设立保护标志的；\n（三）未依法组织编制湖泊保护规划、湖泊水功能区划、湖泊水生态环境保护规划的；\n（四）违反湖泊保护规划批准开发利用湖泊资源的；\n（五）未依法履行有关公示、公布程序的；\n（六）有其他滥用职权、玩忽职守、徇私舞弊行为的。\n第五十九条 违反本条例第二十一条第一款的规定，在湖泊保护区内建设与防洪、改善水环境、生态保护、航运和道路等公共设施无关的建筑物、构筑物的，由县级以上人民政府水行政、自然资源等主管部门按照职责分工，责令停止违法行为，限期拆除并恢复原状，所需费用由违法者承担，没收违法所得，并处5万元以上50万元以下罚款。\n违反本条例第二十一条第三款规定，未及时清除影响湖泊保护的施工便道、施工围堰的，由县级以上人民政府水行政主管部门责令限期恢复原状，处5万元以上10万元以下罚款；逾期不清除的，由水行政主管部门指定有关单位代为清除，所需费用由违法行为人承担。\n第六十条 违反本条例第二十二条第一款的规定，在湖泊保护区内从事填湖建房、填湖建造公园、填湖造地、围湖造田、筑坝拦汊以及其他侵占和分割水面行为的，由县级以上人民政府水行政、自然资源等主管部门按照职责分工，责令停止违法行为，限期拆除并恢复原状，所需费用由违法者承担，没收违法所得，并处5万元以上50万元以下罚款。\n第六十一条 违反本条例第四十条第二款规定，围网、围栏养殖的，由县级以上人民政府农业农村主管部门责令限期拆除，没收违法所得；逾期不拆除的，由农业农村主管部门指定有关单位代为清除，所需费用由违法行为人承担，处1万元以上5万元以下罚款。\n违反本条例第四十条第三款在湖泊水域养殖珍珠的，由县级以上人民政府农业农村主管部门责令停止违法行为，没收违法所得，并处5万元以上10万元以下罚款。\n违反本条例第四十条第三款在湖泊水域投肥（粪）养殖的，由县级以上人民政府农业农村主管部门责令停止违法行为，采取补救措施，处500元以上1万元以下罚款。污染水体的，由县级以上人民政府生态环境主管部门责令停止违法行为，没收违法所得，并处5万元以上10万元以下罚款；情节严重的，处10万元以上30万元以下罚款，由发证机关吊销养殖证。","level":1},{"name":"第九章 附则","text":"第六十二条 本条例自2012年10月1日起施行。","level":1}]},{"id":"h0158","sections":[{"name":"","text":"（2012年7月27日湖北省第十一届人民代表大会常务委员会第三十一次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了稳定和完善以家庭承包经营为基础、统分结合的双层经营体制，维护农村土地承包经营当事人的合法权益，促进农业农村经济发展，维持农村社会稳定，根据《中华人民共和国物权法》、《中华人民共和国土地管理法》、《中华人民共和国农村土地承包法》、《中华人民共和国农村土地承包经营纠纷调解仲裁法》等有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内农村土地承包经营管理活动。\n本条例所称农村土地，是指农民集体所有和国家所有依法由农民集体使用的耕地、林地、草地、养殖水面，以及其他依法用于农业的土地。\n国有农牧渔良种场的土地承包经营参照本条例执行。\n第三条 农村土地所有者、承包方、流转受让方的合法权益受法律保护，任何组织和个人不得侵犯。\n支持、引导承包方依法、自愿、有偿地进行土地承包经营权流转，促进生产要素的合理流动和优化配置，提高农业规模化经营水平。\n农村土地承包经营应当保护和合理利用土地资源，未经依法批准不得将承包地用于非农建设。\n第四条 农村土地承包经营应当明晰所有权、稳定承包权、放活经营权，依照公平、公正、公开及有利于规模经营、发挥土地效益原则，稳步推进土地承包经营体制创新，促进工业化、城镇化和农业现代化。\n第五条 各级人民政府应当加强对农村土地承包工作的领导。农村土地承包经营管理工作经费应当列入本级财政预算予以保障。\n第六条 省人民政府农业、林业行政主管部门分别依照职责，负责指导全省农村土地承包经营管理工作。\n市、州、县（区）人民政府土地承包经营管理部门、林业行政主管部门分别依照职责，负责本行政区域内的农村土地承包经营管理工作。\n县级以上人民政府其他有关部门依照各自职责，做好农村土地承包经营管理相关工作。\n乡级人民政府负责本行政区域内农村土地承包经营管理工作。","level":1},{"name":"第二章 土地承包经营权的确立","text":"第七条 土地承包经营权通过承包方式取得，但法律另有规定的除外。\n土地承包采取农村集体经济组织内部的家庭承包方式。不宜采取家庭承包方式的荒山、荒沟、荒丘、荒滩等农村土地，采取招标、拍卖、公开协商等方式承包。\n第八条 农民集体所有和国家所有依法由农民集体使用的耕地、林地、草地等，依法由农村集体经济组织、村民委员会或者村民小组发包。\n农村集体经济组织成员对本集体经济组织发包的农村土地，依法享有平等承包权，以户为单位承包集体土地。\n任何组织和个人不得剥夺和非法限制农村集体经济组织成员承包土地的权利。\n第九条 符合下列条件之一的人员，为本集体经济组织成员：\n（一）世居本地且户籍在本集体经济组织的；\n（二）父母双方或者一方为本集体经济组织成员，本人户籍在本集体经济组织的；\n（三）因合法的婚姻、收养关系，户籍迁入本集体经济组织的；\n（四）根据国家移民政策，户籍迁入本集体经济组织的；\n（五）原户籍在本集体经济组织的现役义务兵、符合国家有关规定的士官、高等院校和中等职业技术学校的在校学生；\n（六）原户籍在本集体经济组织的正在服刑和其他被依法限制人身自由的人员。\n依法保障农村集体经济组织成员对本集体经济组织土地发包承包、征收征用等的知情权、参与权、决策权和监督权。\n第十条 发包方应当依照法定的承包原则和程序发包。承包期限不得超过法定年限。\n承包方案应当经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表同意，并报乡级土地承包经营管理机构备案。\n第十一条 承包耕地实施退耕还林工程后，原承包关系不变，由县级以上人民政府收回并注销土地承包经营权证，据实核发林权证。\n第十二条 承包期内，承包方可以向发包方提交书面申请，自愿将承包地交回发包方。承包方自愿交回承包地的，在剩余承包期内不得再要求承包土地。\n对自愿交回承包地的农民，县级以上人民政府应当制定相应政策，给予补偿、补助和相应的社会保障等。\n第十三条 以招标、拍卖、公开协商等方式发包荒山、荒沟、荒丘、荒滩等农村土地，应当事先经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表同意，并制定发包方案。将农村土地发包给本集体经济组织以外的单位或个人承包的，还应报乡级人民政府批准。\n发包方案应当包括下列内容：土地的名称、坐落、面积、用途，发包方式、底价，申请人的资信情况、经营能力，承包期限等。\n在同等条件下，本集体经济组织成员享有优先承包权。\n第十四条 以招标、拍卖、公开协商等方式发包的，发包方应当对承包申请人的资信情况和经营能力进行审查，确认承包资格。\n第十五条 以招标、拍卖方式承包的，承包价格通过公开竞标、竞价确定。以公开协商方式承包的，承包价格由发包方与承包方共同议定。\n第十六条 发包方应当与承包方签订书面承包合同。承包合同一式四份，发包方、承包方、乡级土地承包经营管理机构、县级以上人民政府土地承包经营管理部门各执一份。\n第十七条 承包合同自成立之日起生效。承包方自承包合同生效时取得土地承包经营权。\n第十八条 县级以上人民政府应当向承包方颁发土地承包经营权证，并登记造册，确认土地承包经营权。\n第十九条 承包合同和土地承包经营权证是承包方享有土地承包经营权的法律凭证，任何组织和个人不得扣留或者擅自更改。\n承包合同、土地承包经营权证示范文本由省人民政府农业行政主管部门按照国家标准统一制定。\n第二十条 承包合同、土地承包经营权证登记薄、土地承包经营权证记载的事项应当一致；记载不一致的，除有证据证明土地承包经营权证登记簿确有错误外，以土地承包经营权证登记簿为准。\n第二十一条 发包方、县级以上人民政府土地承包经营管理部门和乡级人民政府应当完善承包方案、承包合同、土地承包经营权证及其相关文件的登记、建档、保管和查询等工作。\n建立健全省市县乡四级联网的土地承包信息化管理服务系统，为社会提供信息服务。\n承包方有权查阅、复制与其承包地有关的土地承包经营权证登记簿和其他登记材料，有关部门及其工作人员应当为其提供方便，不得拒绝或者限制。","level":1},{"name":"第三章 土地承包经营权的保护","text":"第二十二条 承包方对承包的土地享有占有、使用、收益和依法流转的权利，有权自主组织生产经营和处置产品。\n第二十三条 承包期内，发包方不得收回承包地。\n承包期内，承包户全家迁入小城镇落户的，有权依法保留其土地承包经营权或者依法流转；迁入设区的市，转为非农业户口的，应当将承包地交回发包方。\n集体经济组织不得以村民会议决议、村规民约或者其他任何方式损害本集体经济组织成员的土地承包经营权，不得作出有差别或者歧视性待遇的决定。\n第二十四条 以家庭承包方式取得的土地承包经营权的分割，由家庭内部自行协商解决；协商不成的，按照土地承包仲裁委员会的仲裁裁决或者人民法院的判决及有关协议处理。\n第二十五条 承包期内，出嫁女、入赘婿、离婚或者丧偶者未取得新承包地的，发包方不得收回其原承包地。\n征地补偿费分配或者集体经济组织进行股份制改造时，妇女与男子享有同等权利。\n农村集体经济组织成员结婚或者迁居后在迁入地取得承包地的，迁入地的集体经济组织应当告知迁出地的集体经济组织。\n第二十六条 承包期内，发包方不得擅自调整承包地。有下列情形之一的，经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表同意，报乡级人民政府和县级以上人民政府土地承包经营管理部门批准，可以依法对承包地作适当调整：\n（一）因自然灾害严重毁损承包地的；\n（二）因建设公共设施、兴办公益事业占用承包地的；\n（三）承包期内应当取得承包地而没有取得的；\n（四）因土地被国家征收，承包方自愿放弃经济补偿（地上附着物和青苗补偿费除外），要求继续承包土地的；\n（五）法律、法规规定的其他情形。\n第二十七条 下列土地应当作为调整用地：\n（一）集体经济组织预留的机动地；\n（二）集体新增的土地；\n（三）承包方依法、自愿交回的土地；\n（四）发包方依法收回的土地；\n（五）其他依法可用于调整的土地。\n第二十八条 土地调整应当按照下列程序进行：\n（一）发包方依据本条例规定对符合条件的农户范围、调整顺序、调整面积等事项进行确认并拟订调整方案；\n（二）公示调整方案，公示期不得少于十五日；\n（三）依法召开村民会议或者村民代表会议，经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表同意，通过调整方案；\n（四）发包方将调整方案报乡级土地承包经营管理机构审核，并报县级人民政府土地承包经营管理部门批准；\n（五）发包方组织实施调整方案；\n（六）签订承包合同并办理变更登记手续。\n第二十九条 为了公共利益依法征收、征用承包地的，应当按照同地同价原则，对农村集体经济组织和原承包方及时足额给予补偿，或者适当调整承包地。具体办法由省人民政府另行制定。\n征收、征用土地前，应当将征地用途、范围、面积以及征地补偿标准、安置办法和办理征地补偿的期限等，在被征承包地所在的村集体经济组织予以公告，听取被征土地的农村集体经济组织和承包户的意见。\n征地方案确定后，征地主管部门应当商土地承包经营管理部门变更或者解除被征用地块的承包合同，办理相关手续。\n第三十条 征收、征用承包地的各项补偿费用应当自征地补偿、安置方案批准之日起三个月内全额支付。\n土地补偿费、安置补助费的使用、分配办法，由本集体经济组织成员讨论决定。依法补偿给被征地农户的费用，应当直接将补偿款支付给被征地农户。\n禁止非法征收、征用、占用农户承包地。对违法征收、征用、占用土地或者擅自扩大征地范围以及未按时足额支付补偿费的，承包户有权拒绝交地。\n第三十一条 县级以上人民政府应当为被征地农民办理相应的社会保障，免费进行职业技能培训，给予提供就业指导服务，为其自主创业提供贷款贴息，减免相关规费等。\n第三十二条 村集体经济组织公益事业和公共设施等建设占用承包地，应当经本集体经济组织成员的村民会议三分之二以上成员同意，在征得承包户同意并报县级人民政府土地承包经营管理部门批准后实施；用地单位应当对原承包户给予经济补偿，或者由发包方给原承包户适当调整土地。\n第三十三条 县级以上人民政府应当按照土地整理规划，因地制宜推进农村土地集中连片整治，提高耕地质量，建设高标准农田，集体经济组织、承包方、流转受让方应当支持、配合。\n土地整理不得减少承包户的承包地面积，不得借土地整理收回农户承包地。","level":1},{"name":"第四章 土地承包经营权的流转","text":"第三十四条 土地承包经营权流转应当在坚持农户家庭承包经营制度和稳定土地承包关系的基础上，依法、自愿、有偿进行。\n土地承包经营权流转不得改变承包地的集体所有性质，不得改变土地用途，不得损害农民土地承包权益。\n第三十五条 通过家庭承包取得的土地承包经营权可以采取转包、出租、互换、转让、股份合作等多种形式流转。\n通过招标、拍卖、公开协商等方式承包的农村土地依法登记取得土地承包经营权证的，在承包期内可以依法采取转让、出租、入股、抵押或者其他方式流转。\n第三十六条 承包方可以自行流转，也可以委托流转。\n承包方委托流转的，应当由承包方出具签名或者盖章的流转委托书，载明委托的事项、权限、期限及流转费支付方式等。未经承包方书面委托，任何组织和个人以承包方名义与流转受让方签订的土地承包经营权流转合同无效。\n第三十七条 土地承包经营权流转应当签订书面合同。流转主体涉及多个当事人的，合同可以由流转双方直接签订，也可以采取委托代理方式签订。\n流转合同一式四份，流转双方、发包方和乡级土地承包经营管理机构各执一份。\n土地承包经营权流转合同示范文本由省人民政府农业行政主管部门统一制定。\n第三十八条 在土地承包经营权流转期间，因国家政策重大调整的，经双方协商可以对合同的有关条款作相应修改，或者依法解除合同。\n第三十九条 家庭承包经营的土地承包权转让只能在同一集体经济组织内进行。转让双方应当事先向发包方提出书面申请，发包方应当在收到书面申请之日起十五日内给予答复。不同意转让的，应当书面说明理由。\n第四十条 承包方是土地承包经营权流转的主体，有权依法自主决定承包经营权是否流转、流转的对象和方式等，任何组织和个人不得强迫和阻碍。\n土地承包经营权流转的期限、价款及支付方式等，由承包方和流转受让方在承包期内协商确定，土地承包经营管理部门应当予以指导、监督。\n土地承包经营权流转收益归承包方所有，任何组织和个人不得擅自截留、扣缴。受承包方委托，集中连片流转的收益由发包方代为结算的，发包方应当将流转收益及时足额支付给承包方。\n第四十一条 承包方、流转受让方应当依法保护和合理利用土地，不得改变基本农田的性质。\n第四十二条 以家庭方式承包土地，承包方不能耕种的，应当委托他人代耕或者依法流转。弃耕抛荒连续两年以上的，发包方可以组织代耕，并书面通知承包方，但不得收回其承包地。承包方要求继续耕作其承包地的，应当提前通知发包方。\n县级以上人民政府应当对弃耕抛荒土地建立调查统计制度，制定激励措施，鼓励各类经营主体承租、经营弃耕抛荒土地，做好土地承包经营权流转工作。\n第四十三条 在确保承包方自主权的前提下，鼓励各类经营主体通过土地承包经营权流转开展规模经营，发展现代农业。\n土地整理等涉农资金应当优先安排规模经营项目。\n第四十四条 鼓励农民以土地经营权入股发展农业合作经营；股份合作终止时，入股的土地经营权应当退回原承包方。\n第四十五条 各级人民政府应当加强土地承包经营权流转管理和指导，建立健全土地承包经营权流转风险防范等各项制度。\n土地承包经营管理部门应当建立土地承包经营权流转服务平台，构建完善的流转信息网络，提供流转信息、法律政策咨询、流转基准价格指导、合同签订指导等服务；建立流转合同履行情况的监督检查制度，保证流转合同的严格履行，维护当事人合法权益。","level":1},{"name":"第五章 土地承包经营权证管理","text":"第四十六条 以家庭承包方式承包农村土地的，发包方应当自承包合同生效之日起三十日内，将土地承包方案、承包合同等材料报乡级土地承包经营管理机构；乡级土地承包经营管理机构对报送的材料应当在三十日内初审，并报县级以上人民政府土地承包经营管理部门予以审核，符合条件的，县级以上人民政府应当在三十日内颁发土地承包经营权证。\n以招标、拍卖、公开协商等方式承包荒山、荒沟、荒丘、荒滩等农村土地的，经本人申请，依法审核登记，由县级以上人民政府三十日内颁发土地承包经营权证。\n颁发土地承包经营权证等证书，除按照规定收取证书工本费外，不得收取其他费用。\n第四十七条 土地承包经营权证应当包括以下内容：\n（一）名称和编号；\n（二）发证机关及日期；\n（三）发包方、承包方代表及承包经营权共有人情况；\n（四）承包期限和起止日期；\n（五）承包土地名称、坐落、面积、用途；\n（六）其他应当注明的事项。\n第四十八条 承包地有下列情形之一的，应当依法变更承包合同，办理土地承包经营权证变更手续：\n（一）被部分征收或者退耕还林的；\n（二）土地整理发生变动的；\n（三）依法调整的；\n（四）因互换、转让以外的其他方式致使承包经营权分立、合并的；\n（五）承包方自愿交回部分承包地的；\n（六）法律法规规定的其他情形。\n承包方依法应当申请办理土地承包经营权证变更登记手续而未申请办理的，由发包方申请办理。\n变更家庭承包合同不得改变原承包期。\n第四十九条 办理土地承包经营权变更申请应当提交以下材料：\n（一）变更的书面请求；\n（二）原承包合同、已变更的承包合同原件及其他证明材料。\n第五十条 乡级土地承包经营管理机构受理变更申请后，应及时对申请材料进行审核。符合规定的，报请原发证机关办理变更手续。\n发证机关办理变更手续时，对于发生本条例第四十八条中（一）、（二）、（五）类情形的，应当依据变更后的承包合同分别在土地承包经营权证及土地承包经营权证登记簿中作变更登记；发生（三）、（四）类情形的，应当收回原承包合同及土地承包经营权证，依据变更后的合同颁发权证，重新登记。\n第五十一条 土地承包经营权证严重污损、毁坏、遗失的，承包方应当向乡级土地承包经营管理机构申请换发或者补发。经乡级土地承包经营管理机构审核后，原发证机关应当以土地承包经营权证登记薄为准及时换发或者补发。\n第五十二条 承包地有下列情形之一的，应当解除或者终止承包合同，由发证机关依法收回土地承包经营权证：\n（一）承包方自愿全部交回的；\n（二）全部征收的；\n（三）全部转让的；\n（四）承包期满的；\n（五）发包方依法全部收回的；\n（六）法律法规规定的其他情形。\n承包方无正当理由拒绝交回土地承包经营权证的，由原发证机关依法注销该证，并予以公告；承包方不服的，可以依法提出行政复议或者行政诉讼。","level":1},{"name":"第六章 争议解决和法律责任","text":"第五十三条 县级以上人民政府应当加大投入，加强土地承包经营纠纷调解仲裁体系建设，指导设立土地承包仲裁委员会。土地承包仲裁委员会的日常工作由当地土地承包经营管理部门承担。\n乡级人民政府依托土地承包经营管理机构设立土地承包经营纠纷调解委员会，村设调解员。\n省人民政府农业行政主管部门负责土地承包纠纷仲裁员培训和资格认定。\n第五十四条 发生土地承包经营纠纷，双方当事人可以自行协商解决，也可以申请村民委员会和乡级人民政府调解。\n当事人不愿协商、调解或者协商、调解不成的，可以向土地承包仲裁委员会申请仲裁，也可以直接向人民法院起诉。\n协商、调解、仲裁、诉讼期间，双方当事人不得影响对方的正常生产；对生产季节性强的种植业、养殖业等土地承包经营纠纷，可以裁定先行恢复生产。\n第五十五条 发包方有下列行为之一的，由县级以上人民政府土地承包经营管理部门责令限期改正；逾期不改正的，对直接责任人员处以1000元以上5000元以下的罚款；给承包方造成损失的，依法承担民事责任：\n（一）越权发包土地的；\n（二）约定的承包期不符合法定期限的；\n（三）未按照法定程序发包的；\n（四）剥夺、侵害本集体经济组织成员依法享有的土地承包经营权的；\n（五）干涉承包方依法享有的生产经营自主权的；\n（六）未经法定程序调整或者收回承包地的；\n（七）擅自变更、解除或者扣留承包方的承包合同的；\n（八）未按照规定申办土地承包经营权证，扣留或者擅自更改土地承包经营权证的；\n（九）强迫或者阻碍承包方进行土地承包经营权流转的；\n（十）侵占、截留、扣缴、挪用承包方流转收益的；\n（十一）其他侵害承包方土地承包经营权益的行为。\n第五十六条 承包方或者流转受让方改变土地农业用途或者对土地造成永久性损害的，由县级以上人民政府土地行政主管部门责令限期改正或者治理，并依法处以罚款；构成犯罪的，依法追究刑事责任。\n承包方占用应当交回的承包土地的，由县级以上人民政府土地承包经营管理部门责令限期改正，逾期不改正的，处500元以上2000元以下的罚款，并依法注销土地承包经营权证，予以公告；给他人造成损失的，依法承担民事责任。\n第五十七条 国家机关及其工作人员有下列行为之一的，由监察机关或者主管机关对主要负责人、直接负责的主管人员和其他直接责任人员依法给予行政处分；给承包方造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任：\n（一）利用职权非法干涉土地承包，强制变更、解除承包合同的；\n（二）非法干涉承包方依法享有的生产经营自主权的；\n（三）强迫或者阻碍承包方进行土地承包经营权流转的；\n（四）未按照规定办理土地承包经营权证的登记、颁发、变更、注销、撤销等相关手续的；\n（五）不依法调查处理有关土地承包的投诉、举报的；\n（六）无法定依据收取费用的；\n（七）非法征收、征用、占用承包地的；\n（八）截留、侵占、挪用土地承包经营权流转收益、惠农补贴以及征收土地的土地补偿费、安置补助费、青苗补偿费的；\n（九）其他侵害承包方土地承包经营权益的行为。\n第五十八条 违反本条例规定，法律、行政法规已有法律责任规定的，从其规定。","level":1},{"name":"第七章 附则","text":"第五十九条 养殖水面是指人工开挖或者天然形成的依法用于水产养殖的塘堰水面及相应附属设施用地。\n第六十条 林地的承包经营管理，国家和省另有规定的，从其规定。\n第六十一条 自留地、自留山是集体所有由农户长期占有、使用、收益的农用地，视为家庭承包地。\n第六十二条 本条例自2012年10月1日起施行。","level":1}]},{"id":"h0159","sections":[{"name":"第一章 总则","text":"第一条 为了保障流动人口的合法权益，加强流动人口服务和管理工作，维护社会和谐稳定，促进经济社会协调发展，根据法律、行政法规的有关规定，结合本省实际，制定本条例。\n第二条 本省行政区域内的流动人口服务和管理，适用本条例。\n本条例所称流动人口，是指离开户籍所在地县级行政区域到其他行政区域居住的人员，在设区市的市辖区之间流动的人员除外。流动人口，包括流入人口和流出人口。\n第三条 流动人口服务和管理工作，应当坚持以人为本、服务为先、公平对待、依法管理，有利于保障流动人口的合法权益，有利于流动人口融入当地社会，有利于社会管理创新，有利于人口有序流动。\n第四条 各级人民政府负责本行政区域内流动人口服务和管理工作,把流动人口服务和管理纳入国民经济和社会发展规划、年度计划，列入社会管理综合治理目标管理体系，建立考核评价机制，逐步实现流动人口与户籍人口基本公共服务均等化。\n各级人民政府应当将流动人口服务和管理工作所需经费列入本级财政预算，保障流动人口服务和管理工作与经济社会发展相适应。\n第五条 各级人民政府应当按照政府统一领导、社会管理综合治理委员会综合协调，公安机关为主、各部门各司其职，单位与公民参与的原则，建立流动人口服务和管理体制，健全省、市、县、乡（镇）、社区（村）五级流动人口服务和管理网络。\n第六条 县级以上社会管理综合治理委员会负责组织、协调、指导、督促、检查本行政区域内流动人口服务和管理工作。\n公安、发展和改革、人力资源和社会保障、教育、民政、司法行政、财政、住房和城乡建设、交通运输、农业、文化、卫生、人口和计划生育、工商行政管理等部门按照各自职责开展流动人口服务和管理工作。\n工会、共青团、妇联等人民团体应当结合各自职能开展流动人口服务和管理工作。\n乡镇人民政府、街道办事处具体负责流动人口日常服务和管理工作，根据实际需要在社区、村（居）民委员会建立流动人口服务和管理站（以下简称社区流动人口服务和管理站）。社区流动人口服务和管理站受政府相关部门委托，开展流动人口服务和管理工作。\n社区、村（居）民委员会以及相关单位和个人应当协助做好流动人口服务和管理工作。\n第七条 各级人民政府应当对在本地经济社会建设中做出突出贡献的流动人口，以及在流动人口服务和管理工作中成绩突出的单位和个人，给予表彰和奖励。","level":1},{"name":"第二章 流动人口的权益","text":"第八条 流动人口享有法律赋予公民的政治、经济、文化、社会以及人身、财产等各项权利和居住地提供的基本公共服务。\n全社会都应当尊重流动人口，禁止歧视流动人口。\n第九条 流动人口可以依法参加居住地人民代表大会、基层群众自治组织和企业职工（代表）大会选举等，参与居住地经济社会事务的管理，参加居住地劳动模范、先进工作者等的评选。\n第十条 流动人口享有与居住地户籍人口平等的劳动就业权利，依法取得劳动报酬、休息休假，获得劳动安全卫生保护、职业技能培训等，以及接受就业培训、职业介绍等政府公共就业服务。\n第十一条 与居住地的用人单位建立劳动关系的流动人口，有权依法参加基本养老保险、基本医疗保险、失业保险、工伤保险、生育保险，并享受相关待遇。\n灵活就业的流动人口，可以按照有关规定参加基本养老保险、基本医疗保险等，并享受相关待遇。\n第十二条 流动人口随迁子女与居住地户籍学生平等接受义务教育，在入学、升学、编班、学籍管理、奖励、考核评价等方面平等对待。\n流动人口随迁子女符合规定条件的，可以在居住地参加高级中等学校和普通高等学校招生考试。\n第十三条 流动人口在传染病防治、儿童规划免疫、妇幼保健、计划生育等方面，享受与居住地户籍人口同等的免费服务和优惠政策。\n第十四条 流动人口符合居住地规定条件的，可以申请政府提供的公共租赁住房，购买商品住房。\n第十五条 流动人口符合居住地规定条件的，可以申请法律咨询、法律援助、司法救助等法律服务。\n第十六条 流动人口中的农村进城务工人员在户籍地承包的土地，可以继续耕种，也可以依法流转。任何组织和个人不得强行收回其承包地，不得限制其土地承包经营权流转，不得侵占其土地流转收益。\n第十七条 居住证持有人在居住地享受下列便利：\n（一）按照国家有关规定办理出入境证件；\n（二）按照国家有关规定换领、补领居民身份证：\n（三）机动车登记；\n（四）申领机动车驾驶证；\n（五）报名参加职业资格考试、申请授予职业资格；\n（六）办理生育服务登记和其他计划生育证明材料；\n（七）国家规定的其他便利。\n第十八条 流动人口应当遵守法律、法规，遵守居住地社会秩序、社区居民自治章程和居民公约，按照规定申报居住登记、申领居住证。","level":1},{"name":"第三章 基本公共服务","text":"第十九条 县级以上人民政府应当建立完善流动人口服务保障机制，将流动人口的劳动就业、社会保障、公共教育、医疗卫生、住房租购、计划生育和法律服务等，纳入当地基本公共服务范围，在编制城乡规划、建设公用设施、制定公共服务政策等方面统筹兼顾、合理安排、公平对待、增加投入，提高城市公共承载能力，保障流动人口合法权益。\n第二十条 流动人口流入地和流出地的县级以上人民政府及其有关部门，应当按照以流入地为主、流入地与流出地协调配合的原则，完善协作机制，建立流动人口信息通报制度，实现工作对接，共同做好流动人口服务和管理工作。\n第二十一条 县级以上人民政府及其人力资源和社会保障行政部门应当建立健全统一开放、竞争有序的城乡一体化人力资源市场，清理、取消各种歧视、限制流动人口就业的规定以及行政审批、行政收费等，保障流动人口平等就业权利。\n任何单位和个人不得对流动人口就业设置歧视性限制，不得对流动人口就业或者用人单位招（聘）用流动人口设置收费项目，不得干涉用人单位合法招（聘）用流动人口。\n第二十二条 人力资源和社会保障行政部门应当为流动人口提供下列公共就业和劳动保障服务：\n（一）免费提供政策咨询和就业信息、就业指导和职业介绍；\n（二）制定职业技能培训规划，为流动人口开展创业培训和就业技能培训，并按规定给予相应补贴；\n（三）监督管理用人单位依法订立劳动合同，完善工资集体协商机制，扩大集体合同的覆盖面；\n（四）建立工资支付监控和保证金制度，规范用人单位工资支付行为;\n（五）加强人力资源市场管理，规范职业中介、劳务派遣，查处违法行为；\n（六）加强劳动保障监察，优先受理涉及工资支付、工伤赔偿等劳动纠纷，依法处理劳动争议。\n人力资源和社会保障、卫生行政部门应当建立健全流动人口社会保险体系，完善基本养老保险、基本医疗保险异地转移接续以及基本医疗保险异地就医结算等办法，保障流动人口依法参加基本养老、基本医疗等社会保险。\n第二十三条 各级工会应当组织已就业的流动人口加入工会，指导、帮助流动人口订立劳动合同，以劳动合同、工资支付、劳动安全保障为重点，完善劳动关系协调机制，依法调解劳动争议，参与劳动仲裁，监督用人单位履行法律法规规定的义务。\n第二十四条 用人单位和经营业主应当依法与被招（聘）用的流动人口订立劳动合同，办理社会保险，实行同工同酬，按时足额支付劳动报酬，开展岗位培训，并为流动人口提供安全卫生的劳动条件和环境。\n第二十五条 县级以上人民政府可以根据实际需要，在流动人口主要输出地设立驻外劳务服务机构，引导流动人口有序流动，开展维权服务。省人民政府及其相关部门对各地驻外劳务服务机构建设、保障和开展服务，给予指导和帮助。\n鼓励商会为流动人口创业、就业以及维权等提供咨询、帮助和服务。\n第二十六条 各级人民政府及其工商、税务等有关部门应当优化创业环境，落实优惠政策，简化办事程序，帮助、支持流动人口自主创业。\n第二十七条 教育行政部门应当将流动人口随迁子女义务教育纳入当地教育事业总体规划，统筹安排、检查督促全日制公办中小学接收流动人口随迁子女入学，并按实际在校人数拨付学校公用经费，保障流动人口随迁子女享有平等接受义务教育的权利。\n省人民政府教育行政部门按照国家有关规定，结合本省实际，制定流动人口随迁子女在居住地参加高级中等学校和普通高等学校招生考试的相关政策。\n义务教育学校不得拒绝接受流动人口随迁子女入学，不得提高入学门槛，不得违反国家规定乱收费。\n第二十八条 司法行政部门应当为流动人口提供法律宣传、法律咨询等服务，将流动人口中的弱势群体作为法律援助的重点，畅通流动人口寻求法律援助的渠道，完善法律援助异地协作机制，加强流动人口矛盾纠纷排查化解工作。\n对流动人口中的农村进城务工人员申请支付劳动报酬或者工伤赔偿等法律援助的，法律援助机构不再审核其经济困难条件。对符合司法救助条件的流动人口，司法机关应当及时提供司法救助。\n第二十九条 住房保障和城乡建设行政部门应当将流动人口基本住房保障纳入保障性住房建设规划，完善流动人口保障性住房供给体系，制定流动人口住房保障具体政策，为符合条件的流动人口提供公共租赁住房。\n鼓励、支持流动人口集中的开发区、工业园区、企业，建设面向流动人口的集体宿舍。\n第三十条 文化行政部门应当为流动人口提供公共文化服务，组织开展各类文化活动，满足流动人口精神文化需求。\n第三十一条 卫生行政部门应当将流动人口纳入公共卫生服务范围，普及公共卫生和传染病防治知识，检查督促城乡基层卫生服务机构为流动人口提供公共卫生服务，保障流动人口享受与居住地户籍人口同等待遇的规划疫苗接种、妇幼保健、传染病防控服务，并对流动人口相对集中的公共场所定期开展卫生监督检查。\n第三十二条 人口和计划生育行政部门应当做好流动人口计划生育宣传教育、优生优育、生殖健康服务工作，依法为育龄流动人口提供国家规定项目的免费避孕药具、计划生育技术服务和咨询服务，免费为育龄妇女办理流动人口婚育证明，依法落实流动人口计划生育政策。\n第三十三条 民政部门应当将流动人口困难群体纳入社会救助体系，为生活无着落的流浪乞讨人员和特殊困难的流动人口提供临时救助、慈善救助等服务，加强救助设施建设，完善救助服务功能。\n第三十四条 各级人民政府以及相关单位应当依法保障流动人口的选举权和被选举权等政治权利，鼓励、引导流动人口依法参与居住地经济社会事务管理，参与所在单位、组织和社区的民主决策、民主管理、民主监督，并在评选劳动模范和先进工作者等方面，与居住地户籍人口同等对待。\n第三十五条 各级人民政府应当加强对流动人口中刑释解教人员、精神病人和流浪乞讨人员等特殊人群的服务和管理，建立健全社会关怀帮扶体系。\n第三十六条 各级人民政府及其有关部门应当依法维护留守老人、妇女、儿童的合法权益，并重点加强农村留守儿童的教育关爱工作，构建学校、家庭、社会相结合的教育监护和关爱网络，关心农村留守儿童身心健康成长。\n第三十七条 县级以上人民政府公安、人力资源和社会保障、教育等有关部门和单位应当设立流动人口维权救助热线电话，依法及时处理流动人口的相关投诉。","level":1},{"name":"第四章 社会融合和管理创新","text":"第三十八条 各级人民政府应当加强流动人口服务和管理工作宣传，动员社会各界参与流动人口服务和管理工作，在全社会营造理解、尊重、关心流动人口的良好氛围，提高公众平等对待、热情服务流动人口的意识，帮助流动人口适应居住地生活，促进人民群众安居乐业。\n第三十九条 各级人民政府应当加强城乡社区建设，健全以社区为基础的流动人口服务管理体系，为流动人口提供方便、快捷的社会服务；发挥社区的社会融合功能，鼓励、支持流动人口参与社区自治，增强社区成员意识，提高自我管理、自我教育、自我服务的能力，促进流动人口融入当地社会。\n第四十条 县级以上人民政府应当根据当地经济社会发展水平和城市综合承载能力等，科学、合理编制人口发展规划，积极稳妥推进户籍管理制度改革，探索建立城乡统一的户口登记制度，引导和促进城乡社会融合。\n第四十一条 县级以上人民政府应当逐步将流动人口服务和管理纳入社区网格化服务管理范畴，完善政务服务综合信息管理平台，实现流动人口服务和管理基本信息与公安、人力资源和社会保障、教育、卫生、房屋管理、计划生育、民政等部门信息资源的互联共享，整合管理资源，建立流动人口信息实时采集录入以及跟进服务、跟进管理机制，提高流动人口服务管理效能和水平。\n县级人民政府根据流动人口服务管理的实际需要，按照省有关规定，聘用流动人口协管员，实时采集信息、代办综合服务，协助有关部门开展流动人口服务管理工作。流动人口协管员管理办法由省人民政府另行制定。\n第四十二条 县级以上人民政府建立流动人口居住登记、居住证制度。\n居住证是流动人口在居住地居住和享有居住地基本公共服务的证明。各级人民政府应当将流动人口基本公共服务纳入居住证制度，完善扩大居住证的使用功能。\n各级人民政府和有关部门应当积极创造条件，逐步扩大为居住证持有人提供公共服务和便利的范围，提高服务标准，并定期向社会公布居住证持有人享受的公共服务和便利的范围。\n公安机关负责流动人口居住登记、居住证发放和管理工作。社区流动人口服务和管理站受公安机关的委托，开展居住登记和居住证受理、发放等具体工作。\n第四十三条 流动人口应当自到达居住地七日内，持本人居民身份证或者其他有效身份证明向居住地公安派出所或者社区流动人口服务和管理站申报居住登记。\n未成年人或者行动不便的老年人、残疾人、孕妇等流动人口，可以由其监护人或者近亲属代为办理居住登记。\n公安派出所或者社区流动人口服务和管理站应当为流动人口办理居住登记提供方便；具备条件的，可以采取电话、网络、传真等方式，办理居住登记。\n第四十四条 下列流动人口，按照以下规定办理居住登记：\n（一）在宾馆、酒店、旅店、招待所以及可供住宿的其他经营性服务场所居住的人员，由经营单位办理住宿登记，并通过安装的治安管理信息系统及时传输登记的信息；\n（二）在医疗卫生机构住院就医的人员，由医疗卫生机构负责登记；\n（三）在学校、培训机构寄宿就学或者培训的人员，由学校、培训机构负责登记；\n（四）在民政部门救助站接受救助的人员，由救助站负责登记。\n第四十五条 流动人口到居住地居住登记半年以上，符合有合法稳定就业、合法稳定住所、连续就读条件之一的，可以申领居住证。\n社区流动人口服务和管理站收到流动人口申领居住证的材料后，应当在三日内送交公安派出所。\n公安机关接到流动人口申领居住证的材料后，应当及时审核，并自受理之日起十五日内制作发放居住证。在偏远地区、交通不便的地区或者因特殊情况，不能按期制作发放居住证的，设区的市级以上地方人民政府在实施办法中可以对制作发放时限作出延长规定，但延长后最长不得超过三十日。\n第四十六条 用人单位和经营业主招（聘）用流动人口的，由用人单位和经营业主负责居住登记和信息报送，并可以为招（聘）用的流动人口申请办理居住证。\n用人单位和经营业主应当建立健全单位内部流动人口服务管理制度，落实服务管理责任。\n第四十七条 居住证一人一证，每年签注一次；居住证持有人在居住地连续居住的，应当在居住每满一年之日前一个月内，到居住地公安派出所或者受公安机关委托的社区服务机构办理签注手续。\n已办理暂住证的流动人口办理居住证的，其居住期限连续计算。\n第四十八条 流动人口办理居住登记、首次领取居住证和办理居住证续签，办理单位不得收取任何费用。因遗失、损坏而补领、换领居住证的，应当缴纳工本费。收费标准由省人民政府物价部门会同财政部门核定。\n居住证持有人换领新证时，应当交回原证。\n第四十九条 居住证式样由省人民政府公安机关制定，县级以上人民政府公安机关制作、发放、管理。居住证管理办法由省人民政府另行制定。\n第五十条 任何单位和个人不得实施下列行为：\n（一）使用虚假证明材料骗领居住证；\n（二）出租、出借、转让居住证；\n（三）非法扣押他人居住证；\n（四）冒用他人居住证或者使用骗领的居住证；\n（五）购买、出售、使用伪造、变造的居住证。\n除公安机关人民警察依法执行职务外，任何单位和个人不得收缴或者扣押居住证。\n第五十一条 出租房屋供流动人口居住的，房屋出租人或者其委托人应当与承租人签订房屋租赁合同，登记承租人姓名、身份证件种类和号码、常住户口所在地等基本信息，督促其申报居住登记，并自流动人口入住之日起七日内，将登记信息报告当地公安派出所或者社区流动人口服务和管理站；流动人口终止居住的，应当在流动人口离开后七日内报告当地公安派出所或者社区流动人口服务和管理站。\n房屋出租人提供的出租房屋应当符合国家规定的安全条件，不得将房屋出租给无身份证件的人居住。\n第五十二条 流动人口承租房屋，应当如实向房屋出租人说明租住人数，出示有效身份证件，按照本条例规定申报居住登记、申领居住证。共同居住人员发生变更，应当在三日内告知房屋出租人以及居住地公安派出所或者社区流动人口服务和管理站。\n第五十三条 居住证持证人在居住地有合法稳定的职业和住所、连续居住并依法缴纳社会保险费满一定期限、符合计划生育政策并依法纳税的，可以申请居住地常住户口；与其共同居住生活的配偶、未婚子女、父母可以一并申请居住地常住户口。\n流动人口申请居住地常住户口实行年度总量控制，按照条件受理，依次轮候办理。对流动人口中的优秀人才、劳动模范、先进工作者以及有其它突出贡献者，优先落户。具体办法由设区的市以上人民政府制定。\n第五十四条 参与流动人口服务和管理工作的单位和个人对获悉的流动人口信息都负有保密义务，不得泄露或者用于法定职责以外的用途。","level":1},{"name":"第五章 法律责任","text":"第五十五条 违反本条例规定，侵犯流动人口合法权益的，按照相关法律、法规的规定进行处罚。\n第五十六条 违反本条例第四十三条规定，流动人口不按照规定申报居住登记的，由公安机关给予警告，责令限期改正。\n违反本条例第四十四条、第四十六条规定，负责登记的相关单位未按规定办理登记、报送信息或者登记不实的，由公安机关对相关单位予以警告，责令限期改正；逾期不改正的，处1000元以上5000元以下罚款；违反治安管理法律法规的，依法给予治安处罚。\n第五十七条 违反本条例第五十条第一款第一项、第二项、第三项规定，由公安机关给予警告、责令改正，处200元以下罚款。违反本条例第五十条第一款第四项、第五项规定，由公安机关处200元以上1000元以下罚款。上述违法行为有违法所得的，没收违法所得。伪造、变造的居住证和骗领的居住证，由公安机关予以收缴。\n第五十八条 违反本条例第五十一条规定，房屋出租人未依法报告承租的流动人口登记信息的，由公安机关给予警告，并责令限期改正；逾期不改正的，处500元以下罚款。\n第五十九条 各级人民政府及其有关部门、社区流动人口服务和管理站有下列行为之一的，由其主管部门责令改正，并对负责的主管人员和直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）不按照本条例规定为流动人口提供服务和权益保障的；\n（二）违反本条例规定向流动人口收取费用的；\n（三）对侵害流动人口合法权益的行为不依法及时处理的；\n（四）超越职权或者违反法定处罚情形、种类、幅度对流动人口或者相关单位、个人实施行政处罚的；\n（五）泄露流动人口信息或者用于法定职责以外用途的；\n（六）其他滥用职权、玩忽职守、徇私舞弊的违法行为。","level":1},{"name":"第六章 附则","text":"第六十条 香港特别行政区居民、澳门特别行政区居民、台湾地区居民和外国人、无国籍人在本省的居住管理，按照国家有关法律法规的规定办理。\n第六十一条 本条例所称其他有效身份证明，是指居民户口簿、军官证、警官证、士兵证、护照、驾驶证等国家规定的其他有效身份证明。\n第六十二条 本条例自2013年1月1日起施行。","level":1}]},{"id":"h0160","sections":[{"name":"","text":"（2012年9月29日湖北省第十一届人民代表大会常务委员会第三十二次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了继承和弘扬中华民族优秀传统文化，加强非物质文化遗产保护、保存工作，推动文化强省建设，根据《中华人民共和国非物质文化遗产法》和有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内非物质文化遗产的保护、保存工作，适用本条例。\n第三条 本条例所称非物质文化遗产，是指各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，以及与传统文化表现形式相关的实物和场所。包括：\n（一）传统口头文学以及作为其载体的语言；\n（二）传统美术、书法、音乐、舞蹈、戏剧、曲艺和杂技；\n（三）传统技艺、医药和历法；\n（四）传统礼仪、节庆等民俗；\n（五）传统体育和游艺；\n（六）其他非物质文化遗产。\n第四条 对非物质文化遗产应当采取认定、记录、建档等措施予以保存，对体现中华民族优秀传统文化，具有历史、文学、艺术、科学价值的非物质文化遗产应当采取传承、传播等措施予以保护。\n第五条 非物质文化遗产保护、保存工作应当贯彻保护为主、抢救第一、合理利用、传承发展的方针，坚持政府主导和社会参与，与建设文化强省的战略目标相适应。\n第六条 县级以上人民政府应当加强对非物质文化遗产保护、保存工作的领导，制定非物质文化遗产总体保护规划，将其纳入国民经济和社会发展规划；建立完善部门联席会议制度，协调解决工作中的重大问题；健全工作机构，加强队伍建设和人才培养；实行政府目标管理责任制，加强考核和监督检查。\n第七条 县级以上人民政府应当将非物质文化遗产保护、保存工作所需经费列入本级财政预算，并随着财政收入的增长而增加。\n县级以上人民政府设立用于非物质文化遗产调查和代表性项目名录保护、代表性传承人补贴、文化生态保护区建设等方面的专项资金。\n省、市（州）人民政府应当在项目、资金、基础设施建设等方面对少数民族地区、贫困地区非物质文化遗产保护、保存工作给予扶持。\n第八条 县级以上人民政府文化主管部门负责本行政区域内非物质文化遗产的保护、保存工作。\n县级以上人民政府发展和改革、财政、经济和信息、民族宗教、教育、国土资源、住房和城乡建设、卫生、体育、旅游等有关部门在各自职责范围内，负责有关非物质文化遗产的保护、保存工作。\n非物质文化遗产保护、保存工作涉及两个以上县级行政区域的，由共同的上一级人民政府及其文化主管部门予以协调。\n第九条 乡镇人民政府、街道办事处应当会同县级人民政府文化主管部门做好非物质文化遗产保护、保存工作。\n居民委员会、村民委员会应当协助当地人民政府做好非物质文化遗产保护、保存工作。\n鼓励和支持公民、法人和其他组织参与非物质文化遗产保护、保存工作。\n第十条 县级以上人民政府应当加强非物质文化遗产保护工作的宣传，提高全社会保护非物质文化遗产的意识。\n广播、电视、报刊、出版、网络等媒体单位应当开展非物质文化遗产代表性项目的宣传，普及非物质文化遗产知识。\n第十一条 县级以上人民政府对在非物质文化遗产保护、保存工作中做出突出贡献的单位和个人，应当给予表彰和奖励。","level":1},{"name":"第二章 非物质文化遗产的调查和代表性项目名录","text":"第十二条 县级以上人民政府文化主管部门应当定期组织开展非物质文化遗产普查，全面掌握本行政区域内非物质文化遗产的种类、数量、分布、生存环境、保护现状等情况，建立档案和相关数据库。普查情况向本级人民政府和上一级人民政府文化主管部门报告。\n第十三条 县级以上人民政府文化主管部门应当组织开展非物质文化遗产调查，对非物质文化遗产予以认定、记录、建档，建立健全调查信息共享机制。\n县级以上人民政府其他有关部门可以对其工作领域内的非物质文化遗产进行调查。调查取得的实物图片、资料复制件，应当汇交同级文化主管部门。\n公民、法人和其他组织可以依法进行非物质文化遗产调查。\n第十四条 县级以上人民政府应当建立本级非物质文化遗产代表性项目名录，将体现中华民族优秀传统文化，具有一定的历史、文学、艺术、科学价值和鲜明地域或者民族特色的非物质文化遗产列入名录予以保护。\n第十五条 公民、法人和其他组织可以向县级以上人民政府文化主管部门提出将非物质文化遗产列入代表性项目名录的申请或者建议。\n第十六条 市（州）、县级人民政府可以从本级非物质文化遗产代表性项目名录中向上一级人民政府文化主管部门推荐列入上一级非物质文化遗产代表性项目名录的项目。\n第十七条 向县级以上人民政府文化主管部门提交的申请材料或者推荐材料应当包含下列内容：\n（一）项目介绍，包括项目的名称、历史、现状和价值；\n（二）传承情况，包括传承范围、传承谱系、传承人的技艺水平、传承活动的社会影响；\n（三）保护要求，包括项目的保护单位、保护目标和采取的措施、步骤、管理制度；\n（四）有助于说明项目的视听资料等材料。\n第十八条 非物质文化遗产代表性项目的认定实行专家评审制度。\n评审工作应当遵循公开、公平、公正的原则。\n第十九条 县级以上人民政府文化主管部门应当组织五人以上专家组成专家评审小组，对推荐、申请或者建议列入本级非物质文化遗产代表性项目名录的项目进行初评，提出初评意见。\n县级以上人民政府文化主管部门应当组织七人以上专家组成专家评审委员会，对初评通过的非物质文化遗产代表性项目进行审议，提出审议意见。\n初评意见、审议意见分别经专家评审小组、专家评审委员会成员过半数通过。\n第二十条 县级以上人民政府文化主管部门可以建立由较高学术水平和良好职业道德的专家组成的非物质文化遗产专家库。\n专家评审小组和专家评审委员会从非物质文化遗产专家库中随机选择相关领域的专家组成。未建立非物质文化遗产专家库的，从相关领域选择专家组成。\n专家评审小组成员一般不得同时担任专家评审委员会成员。县级专家评审委员会组成人数不足七人的，专家评审小组成员可以参加专家评审委员会，但不得超过三人。\n第二十一条 县级以上人民政府文化主管部门应当将拟列入本级非物质文化遗产代表性项目名录的项目予以公示，征求公众意见。公示期不得少于二十日。\n公示期间，公民、法人和其他组织有异议的，应当书面提出。县级以上人民政府文化主管部门经过调查，认为异议不成立的，应当自收到异议之日起三十日内书面告知异议人并说明理由；认为异议成立的，应当按照规定程序重新组织评审。\n第二十二条 县级以上人民政府文化主管部门根据专家评审委员会的审议意见和公示结果，拟订本级非物质文化遗产代表性项目名录，报本级人民政府批准、公布，并报上一级人民政府文化主管部门备案。\n第二十三条 县级以上人民政府文化主管部门对通过调查或者其他途径发现濒临消失的非物质文化遗产，应当建立本级非物质文化遗产濒危项目目录，并将该目录报上一级人民政府文化主管部门备案。\n第二十四条 县级以上人民政府文化主管部门应当制定本级非物质文化遗产代表性项目保护规划，对本级非物质文化遗产代表性项目予以保护。\n制定非物质文化遗产代表性项目保护规划，应当对濒临消失的非物质文化遗产代表性项目予以重点保护。\n第二十五条 县级以上人民政府及其文化主管部门应当对非物质文化遗产濒危项目及时采取下列抢救性保护、保存措施：\n（一）采用文字、图片、录音、录像等方式进行记录和建档；\n（二）征集相关资料和实物；\n（三）保护、保存相关场所、遗迹；\n（四）其他抢救性保护、保存措施。\n第二十六条 县级以上人民政府应当对与非物质文化遗产代表性项目直接相关的建筑物、场所、遗迹及其附属物划定保护范围，作出标识说明，建立专门档案。\n标识说明包括非物质文化遗产代表性项目的名称、级别、简介等内容。\n第二十七条 县级以上人民政府及其文化主管部门应当对非物质文化遗产代表性项目保护规划的实施和濒危项目保护情况进行监督检查，对监督检查中发现的问题，应当及时纠正、处理。","level":1},{"name":"第三章 非物质文化遗产的传承与传播","text":"第二十八条 鼓励和支持开展非物质文化遗产代表性项目的传承、传播。\n第二十九条 县级以上人民政府文化主管部门对本级人民政府批准公布的非物质文化遗产代表性项目，可以认定代表性传承人和保护单位。\n第三十条 认定非物质文化遗产代表性项目的代表性传承人和保护单位，应当参照本条例有关非物质文化遗产代表性项目评审的规定，并将所认定的代表性传承人名单和保护单位予以公布。\n市（州）、县级非物质文化遗产代表性项目的代表性传承人和保护单位名单应当报上一级人民政府文化主管部门备案。\n第三十一条 非物质文化遗产代表性项目的代表性传承人应当符合下列条件：\n（一）熟练掌握其传承的非物质文化遗产；\n（二）在特定领域内具有代表性，并在一定区域内具有较大影响；\n（三）积极开展传承活动，培养后继人才。\n第三十二条 非物质文化遗产代表性项目的代表性传承人享有下列权利：\n（一）开展传艺、技艺展示、艺术创作、讲学及学术研究等活动；\n（二）按照有关规定享受传承补贴；\n（三）开展传承活动有困难的，可以向同级人民政府文化主管部门申请扶持；\n（四）其他与非物质文化遗产保护、保存相关的权利。\n第三十三条 非物质文化遗产代表性项目的代表性传承人应当履行下列义务：\n（一）采取收徒、培训、办学等方式传授技艺，培养新传承人；\n（二）妥善整理、保存相关的实物、资料；\n（三）配合有关部门进行非物质文化遗产调查；\n（四）参与非物质文化遗产公益性宣传。\n第三十四条 非物质文化遗产代表性项目的保护单位应当具备下列基本条件：\n（一）有该项目代表性传承人或者相对完整的资料；\n（二）有实施该项目保护计划的能力；\n（三）有开展传承、展示活动的场所和条件。\n第三十五条 非物质文化遗产代表性项目的保护单位应当履行下列职责：\n（一）全面收集该项目的实物、资料，并登记、整理、建档，妥善保存；\n（二）为该项目的传承及相关活动提供必要条件；\n（三）有效保护该项目相关的场所；\n（四）积极开展该项目的展示活动；\n（五）向当地人民政府文化主管部门报告项目保护实施情况，并接受监督。\n第三十六条 县级以上人民政府应当采取下列措施，鼓励、支持和保护非物质文化遗产代表性项目的代表性传承人开展传承与传播活动：\n（一）提供必要的传承场所；\n（二）资助其开展授徒、传艺、交流和传统节庆表演等活动，以及整理、出版有关技艺资料；\n（三）对高龄或者经济困难的代表性传承人，发放生活补贴；\n（四）支持其参与社会公益性活动；\n（五）支持其开展传承、传播活动的其他措施。\n教育、人力资源和社会保障等部门可以采取助学、奖学或者职业培训补贴等方式，资助代表性传承人的学徒学习技艺。\n第三十七条 县级以上人民政府文化主管部门应当定期对非物质文化遗产代表性项目的代表性传承人和保护单位进行考评。\n非物质文化遗产代表性项目的代表性传承人无正当理由不履行规定义务的，认定该项目代表性传承人的县级以上人民政府文化主管部门可以取消其代表性传承人资格，重新认定该项目的代表性传承人；丧失传承能力的，可以重新认定该项目的代表性传承人。\n非物质文化遗产代表性项目的保护单位无正当理由不履行规定职责的，认定该项目保护单位的县级以上人民政府文化主管部门可以取消其保护单位资格，重新认定该项目的保护单位。\n第三十八条 文化馆（群艺馆）、图书馆、艺术馆、博物馆、纪念馆、科技馆等公共文化机构，非物质文化遗产学术研究机构和保护工作机构，以及利用财政性资金举办的文艺表演团体、演出场所经营单位等，应当根据各自业务范围，开展非物质文化遗产的整理、研究、学术交流和非物质文化遗产代表性项目的传播活动。\n第三十九条 县级以上人民政府应当根据需要建设非物质文化遗产专项公共文化设施，用于非物质文化遗产代表性项目的收藏、展示和传承。\n鼓励和支持公民、法人和其他组织依法设立非物质文化遗产展示场所和传承场所，展示和传承非物质文化遗产代表性项目。\n鼓励公民、法人和其他组织将其所有的非物质文化遗产实物和资料捐赠或者委托给政府设立的公共文化机构收藏、保管、展出。\n第四十条 教育主管部门和中小学校应当将具有本地特色的非物质文化遗产知识编入地方教材，纳入素质教育内容，开展相关教育活动，提高青少年保护和传承非物质文化遗产的意识。","level":1},{"name":"第四章 非物质文化遗产的合理利用与发展","text":"第四十一条 鼓励和支持在有效保护的基础上，合理利用非物质文化遗产代表性项目，开发具有鲜明地域、民族特色和市场潜力的文化产品和文化服务。\n第四十二条 县级以上人民政府对适合生产性保护的非物质文化遗产代表性项目，鼓励采取与经贸、旅游相结合的方式进行保护、传承。\n县级以上人民政府应当合理规划布局，加强引导扶持，建设非物质文化遗产代表性项目生产性保护示范中心、示范基地或者示范园区，发挥示范带动作用，促进非物质文化遗产的物质化、市场化、社会化。\n第四十三条 县级以上人民政府对合理利用非物质文化遗产代表性项目的单位和个人，应当在资金、场所、宣传推介、产品销售等方面予以扶持和帮助。\n单位和个人合理利用非物质文化遗产代表性项目的，依法享受国家规定的税收优惠。\n第四十四条 县级以上人民政府应当采取限量开采、提高利用率等措施，保护与非物质文化遗产项目密切相关的动物、植物和珍稀矿产等天然原材料，严禁非法获取或者盗卖。\n第四十五条 对非物质文化遗产代表性项目数量集中、特色鲜明，形式和内涵保持完整的村镇、街区或者特定区域，可以依法设立文化生态保护区，实行区域性整体保护。\n第四十六条 设立文化生态保护区的，由县级以上人民政府文化主管部门会同城乡规划主管部门编制专项保护规划，听取文化生态保护区内居民的意见，报同级人民政府批准公布。\n文化生态保护区跨两个以上县级行政区域的，由共同的上一级人民政府批准公布。\n第四十七条 县级以上人民政府应当加强对文化生态保护区的保护和建设，在政策优惠、资金投入、基础设施建设等方面予以倾斜。\n第四十八条 鼓励和支持依法开展非物质文化遗产代表性项目国内外的合作与交流，提高非物质文化遗产的影响力，弘扬中华民族优秀传统文化。\n第四十九条 鼓励和支持公民、法人和其他组织参与非物质文化遗产的科学技术研究和非物质文化遗产保护、保存方法的研究。\n鼓励和支持职业学校、高等院校、科研机构设置非物质文化遗产相关专业和课程，或者建立教学、研究基地，开展非物质文化遗产科学研究，培养专业人才。\n第五十条 鼓励和支持以弘扬优秀非物质文化遗产为目的的文学艺术创作，有计划、有重点地开展优秀非物质文化遗产原始文献、典籍、资料的整理、翻译、出版和研究工作。\n第五十一条 利用非物质文化遗产代表性项目进行艺术创作、出版、产品开发、旅游活动等，应当尊重其原真形式和文化内涵，不得歪曲、贬损、滥用和过度开发。","level":1},{"name":"第五章 法律责任","text":"第五十二条 违反本条例规定，法律、行政法规有处罚规定的，从其规定。\n第五十三条 违反本条例规定，在申报非物质文化遗产代表性项目和保护单位、代表性传承人的过程中弄虚作假的，由县级以上人民政府文化主管部门给予警告；已认定为非物质文化遗产代表性项目和保护单位或者代表性传承人的，予以撤销，责令返还保护经费和传承补贴，并处以1000元以上1万元以下罚款，有违法所得的，没收违法所得。\n第五十四条 违反本条例规定，非物质文化遗产代表性项目保护单位不履行职责，造成非物质文化遗产实物、资料流失或者场所损毁的，由县级以上人民政府文化主管部门处以5000元以上3万元以下罚款。\n第五十五条 县级以上人民政府、有关主管部门和非物质文化遗产保护工作机构的工作人员，违反本条例规定，有下列行为之一的，由主管部门或者监察机关依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）不履行保护管理职责的；\n（二）在非物质文化遗产代表性项目和保护单位、代表性传承人评审认定过程中弄虚作假、徇私舞弊的；\n（三）不采取有效保护措施，造成濒危非物质文化遗产失传的；\n（四）贪污、挪用非物质文化遗产保护、保存经费的；\n（五）其他玩忽职守、滥用职权、徇私舞弊行为的。","level":1},{"name":"第六章 附则","text":"第五十六条 本条例自2012年12月1日起施行。","level":1}]},{"id":"h0161","sections":[{"name":"","text":"（2012年12月3日湖北省第十一届人民代表大会常务委员会第三十三次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了加强国防建设，提高国防动员和后备力量建设质量，增强国防动员能力，保障国防动员工作的顺利进行，根据《中华人民共和国国防动员法》和有关法律、行政法规的规定，结合本省实际，制定本办法。\n第二条 本省行政区域内国防动员的准备、实施以及相关活动，适用本办法。\n第三条 国防动员建设应当建立健全与国防安全需要相适应、与经济社会发展相协调、与突发事件应急机制相衔接的国防动员体系。\n第四条 国防动员坚持平战结合、军民结合、寓军于民的方针，遵循统一领导、全民参与、长期准备、重点建设、统筹兼顾、有序高效的原则。\n第五条 县级以上人民政府应当将国防动员工作纳入国民经济和社会发展计划，所需经费纳入本级财政预算，推动经济社会建设与国防动员建设相互促进、协调发展。\n开展重大国防动员活动所需经费，按照事权划分的原则予以专项保障。\n第六条 公民和组织应当依法履行国防动员义务，开展国防动员活动，完成国防动员任务。\n县级以上人民政府、军事机关和国防动员委员会对在国防动员工作中作出突出贡献的公民和组织，给予表彰和奖励。\n战时表彰和奖励按照国家有关规定执行。","level":1},{"name":"第二章 组织领导机构及其职责","text":"第七条 各级人民政府应当贯彻执行国防动员工作的方针、政策和法律、法规。在国家决定实施国防动员后，根据上级下达的任务，组织本行政区域国防动员的实施。\n县级以上人民政府应当依照法律规定的权限做好本行政区域的国防动员管理工作，根据国防动员的任务要求，加强国防动员工作的领导，健全完善组织机构，建立检查评估制度，督促各相关方面履行国防动员职责。\n第八条 国防动员工作实行以政府为主导、政府和军事机关共同负责的领导体制。\n县级以上国防动员委员会由本级人民政府及其有关部门和本级军事机关组成，负责组织、指导、协调本行政区域的国防动员工作。\n第九条 具备开展国防动员工作条件的县级以上各类经济技术开发区，应当按照规定建立国防动员机构或者指定机构和人员，负责国防动员工作。\n第十条 县级以上国防动员委员会的成员单位，由本级国防动员委员会确定，并报上一级国防动员委员会备案。各成员单位在各自职责范围内，负责有关的国防动员工作。\n第十一条 县级以上国防动员委员会根据工作需要，设立综合办公室和若干专业办公室，配备相应的工作人员，承担本级国防动员委员会的日常工作，依法履行国防动员的有关职责。\n第十二条 省国防动员委员会履行下列工作职责：\n（一）贯彻执行国务院、中央军事委员会和上级国防动员委员会有关国防动员工作的方针、政策和命令，依法开展国防动员工作；\n（二）组织、指导、协调人民武装动员、国民经济动员、科技动员、政治动员、信息动员、医疗卫生动员、装备动员和人民防空、交通战备、国防教育等工作；\n（三）组织编制省国防动员计划和实施预案；\n（四）检查评估省国防动员计划和实施预案的落实情况；\n（五）组织协调本省国防动员潜力统计调查工作；\n（六）指导市、县级国防动员委员会做好国防动员的各项工作；\n（七）法律、法规和上级国防动员委员会赋予的其他职责。\n第十三条 县级以上国防动员委员会在上级国防动员委员会指导下，履行本行政区域内国防动员工作职责。\n乡（镇）人民政府、街道办事处在上级国防动员委员会的指导下，完成相应的国防动员任务。\n第十四条 战时国防动员指挥机构依托同级国防动员委员会领导机构组建，负责组织、指挥辖区内的国防动员行动。","level":1},{"name":"第三章 国防动员计划、实施预案与潜力统计调查","text":"第十五条 县级以上国防动员委员会及其专业办公室应当根据国防动员的方针和原则、国防动员潜力和军事需求，以及上级国防动员计划和实施预案，结合本地区、本行业实际，编制国防动员计划和实施预案。军事需求由军队有关部门按照规定的权限和程序提出，县级以上人民政府相关部门和国防动员委员会办事机构应当协助军队有关部门做好对接和论证工作。\n国防动员计划包括总体计划和专项计划，国防动员实施预案包括总体预案和专项预案。\n总体计划和总体预案，由县级以上国防动员委员会编制，报同级人民政府和同级军事机关审批，并报上一级国防动员委员会备案。\n专项计划和专项预案，由县级以上国防动员委员会专业办公室会同当地军事机关、政府有关部门编制，报本级国防动员委员会审批，并报上一级国防动员委员会相应的专业办公室备案。\n第十六条 县级以上国防动员委员会及其专业办公室在编制国防动员计划时，应当与国民经济和社会发展计划相协调，与其他各类国防动员计划相衔接，明确任务和要求，保障国防动员建设项目顺利实施。\n第十七条 县级以上国防动员委员会及其专业办公室在编制国防动员实施预案时，应当与政府应急部门加强沟通协调，按照平战一体要求，明确军地联合指挥机构的组成、职责和任务，合理编组、训练、使用军民力量，建立情报信息、物资装备共享机制，使国防动员实施预案与突发事件应急处置预案在指挥、力量使用、信息和保障等方面相互衔接，做到统一指挥、统一部署、联合行动。\n县级以上国防动员委员会及其办事机构应当发挥辖区内中央大型企业事业单位在国防动员工作中的优势，在编制国防动员实施预案、组织实施国防动员演练等方面加强联系与沟通。\n第十八条 国防动员计划和实施预案一经批准，应当严格执行。因情势变化确需调整的，应当按照原审批程序报送审批。\n第十九条 县级以上国防动员委员会应当根据国防动员实施预案，组织开展国防动员演练，检验和完善实施预案，提高组织指挥和快速反应能力。\n国防动员的演练可以专门进行，也可以结合军队演习和抢险救灾、维护社会稳定等重大突发事件进行。\n第二十条 县级以上国防动员委员会应当建立健全国防动员计划和实施预案评估检查制度，加强对政府有关部门和军事机关执行情况的指导和监督，促进国防动员计划和实施预案的有效落实。\n第二十一条 全省国防动员潜力专项统计调查工作由省国防动员委员会负责组织协调。\n县级以上人民政府统计机构和有关部门应当根据国防动员的需要，准确及时地向本级国防动员委员会办事机构提供有关统计资料。提供的统计资料不能满足需要时，县级以上国防动员委员会专业办公室按照国家有关规定，可以组织本行政区域内的国防动员潜力专项统计调查，业务上接受本级人民政府统计机构的指导。\n第二十二条 国防动员潜力专项统计调查按照属地为主、条块结合的原则，以县为基本单位，由下而上逐级进行。对特大型企业和涉密军工企业的统计调查，由所在地国防动员委员会专业办公室报请上一级国防动员委员会相应的专业办公室进行。\n第二十三条 国防动员潜力专项统计调查分为平时统计调查和战时统计调查。\n平时统计调查根据需要进行，也可以采用年度核对的方式进行；战时统计调查按照国家国防动员委员会及其专业办公室的规定进行。\n第二十四条 国防动员潜力专项统计调查应当使用统一制发的提纲、表格（软件系统）和规范的文字、数字、法定计量单位及编码。\n第二十五条 国防动员潜力专项统计调查所涉及的单位和个人，应当真实、准确、完整、及时地提供统计调查所需的资料，不得虚报、瞒报、迟报、拒报统计调查资料。\n国防动员潜力专项统计调查工作人员，应当如实收集、报送统计调查资料，不得伪造、篡改和毁损统计调查资料，不得泄露统计调查对象的资料。\n国防动员潜力专项统计调查涉及国家秘密的，应当遵守国家保密规定。","level":1},{"name":"第四章 预备役人员的储备与征召","text":"第二十六条 县级以上人民政府兵役机关应当做好兵役登记、预备役登记和预备役人员的核对调整以及专业技术人才的登记、编组和训练工作，加强对预备役人员的教育、训练和管理，建立和完善相关制度，为军队战时扩编储备后备兵员和专业技术人员。\n县级以上人民政府有关部门、预备役人员所在乡（镇）人民政府、街道办事处或者企业事业单位协助兵役机关做好有关预备役人员的登记和管理教育工作。\n第二十七条 各级人民政府应当为预备役人员的训练、储备提供训练场地、物资经费等条件。\n预备役人员应当依法参加训练。参加训练期间，预备役人员是国家机关、社会团体、企业事业单位工作人员或者职工的，其所在单位应当保障其工资、奖金和福利待遇，其他预备役人员的误工补贴按照国家和省有关规定执行。\n第二十八条 预编到现役部队和编入预备役部队的预备役人员、预定征召的其他预备役人员，离开预备役登记地一个月以上的，应当向其预备役登记地的县级人民政府兵役机关报告去向、联系方式。联系方式发生变化的，应当及时报告变更情况。\n第二十九条 国家决定实施国防动员后，县级人民政府兵役机关应当根据上级命令，迅速向被征召的预备役人员下达征召通知，同时通知其所在单位。对外出务工的预备役人员，除直接通知本人和单位外，还应当通知其务工所在地的兵役机关。\n接到征召通知的预备役人员应当按照通知要求，到指定地点报到。确因伤病等原因不能应召的，经县级以上人民政府兵役机关批准，可以暂缓应召。\n第三十条 被征召的预备役人员所在单位应当协助当地兵役机关做好本单位预备役人员的征召工作，督促其按照规定的时间、地点报到，并为其提供必要的条件。\n预备役人员所在单位不得以任何理由阻扰其履行征召义务或者参加预备役训练。\n从事交通运输的单位和个人，接到运送被征召预备役人员任务的通知或者被征召人员提出运送请求，应当优先运送被征召的预备役人员。\n第三十一条 国家决定实施国防动员后，预定征召的预备役人员，未经其预备役登记地的县级人民政府兵役机关批准，不得离开预备役登记地；已经离开预备役登记地的，接到兵役机关通知后，应当立即返回或者到指定地点报到。","level":1},{"name":"第五章 基础建设与物资保障","text":"第三十二条 省人民政府发展和改革主管部门会同其他有关部门和军事机关，根据国家确定的与国防密切相关的建设项目和重要产品目录，拟定本省贯彻国防要求的建设项目和重要产品目录，报省人民政府批准。\n第三十三条 县级以上人民政府及其有关部门对公路干线、铁路、机场、港口、码头和能源基地等重要建设项目进行立项和布局时，应当按要求兼顾国防动员需要。\n第三十四条 列入目录的建设项目审批、核准和重要产品设计定型时，县级以上人民政府有关部门应当按照规定征求军事机关和本级国防动员委员会相关专业办公室的意见。\n第三十五条 承担列入目录的建设项目和重要产品研究、开发、生产的单位和个人，应当按照贯彻国防要求的技术规范以及标准进行设计、生产、施工、监理和验收，保证建设项目和重要产品的质量。\n县级以上人民政府及其有关部门应当及时掌握有关研究、开发、生产单位和个人贯彻国防要求的情况，加强对列入目录的建设项目和重要产品贯彻国防要求工作的监督管理。\n第三十六条 县级以上人民政府及其有关部门应当避免在重要涉密军工企业和单位周围安排建设项目。确实无法避开的，应当事先征求本级国防动员委员会办事机构、相关军工企业和单位的意见，并按照国防保密的要求，采取必要的安全措施。\n第三十七条 各级人民政府应当对承担军品科研、转产、扩大生产军品的单位，在经费、物资和技术等方面给予扶持，支持和帮助其开发、应用先进的军民两用技术，推广军民通用的技术标准，提高产品的军民两用兼容程度，增强转产、扩大生产军品的综合保障能力。\n第三十八条 承担转产、扩大生产军品和维修保障任务的单位，平时应当根据所担负的国防动员任务，按照需求导向、任务牵引、突出重点、军民兼容的要求，储备所需的设备、材料、配套产品和技术，建立所需的专业技术队伍，制定和完善相应的工作预案与措施，为战时军品生产做好准备。\n第三十九条 县级以上人民政府和承担战略物资储备任务的单位应当按照国家有关规定储备战略物资。战略物资储备应当规模适度、储存安全、调用方便、定期更换，保障战时的需要和调度及时有效。\n承担战略物资储备任务的单位，依法享受国家规定的补贴和其他政策优惠。\n第四十条 国家决定实施国防动员后，战略储备物资无法及时满足动员需要的，县级以上人民政府可以依法征用组织和个人所有或者使用的设施、设备、场所和其他物资。\n任何组织和个人都有接受依法征用民用资源的义务，不得拒绝、拖延。\n民用资源免予征用的范围，按照国家有关规定执行。\n第四十一条 国家决定实施国防动员后，县级以上人民政府根据对民用资源的征用需求，及时向有关组织和个人下达征用通知，对被征用的民用资源进行登记，并向被征用人出具凭证。按规定将被征用的民用资源交付使用单位时，应当办理交接手续。\n第四十二条 被征用的民用资源根据军事需求进行改造的，由县级以上人民政府会同有关军事机关共同组织实施。\n承担改造任务的单位应当按照使用单位提出的军事需求和改造方案，与使用单位共同研究提出改造实施方案，签订改造任务书，及时进行改造，按期保质保量交付使用。\n任何组织和个人不得阻碍对被征用的民用资源的改造。\n第四十三条 被征用的民用资源使用完毕，县级以上人民政府应当对民用资源的数量、质量、类型等情况进行清点、核实、登记，下达返还通知，办理返还手续，及时返还，不得无故拖延或者扣押所征用的民用资源。\n被征用的民用资源经过改造，不影响原使用功能的，经与被征用人协商并征得其同意，可以原物返还；影响原使用功能或者造成损坏的，应当进行修复，恢复原使用功能后返还。\n被征用的民用资源不能修复或者灭失的，以及因征用造成直接经济损失的，依法给予补偿。","level":1},{"name":"第六章 国防勤务","text":"第四十四条 国家决定实施国防动员后，县级以上人民政府应当根据国防动员实施的需要，动员符合法定条件的公民和组织担负支援保障军队作战、参加预防与救助战争灾害，以及协助维护社会秩序等国防勤务，并明确其规模、专业和具体任务。\n第四十五条 交通运输、邮政、电信、医药卫生、食品和粮食供应、工程建筑、能源化工、大型水利设施、民用核设施、新闻媒体、国防科研生产和市政设施保障等依法担负国防勤务的单位，应当按照专业对口、人员精干、应急有效的原则组建专业保障队伍，定期进行训练、演练，配备相关专业技术装备器材，提高专业保障队伍快速动员和遂行国防勤务能力。\n专业保障队伍应当与预备役部队、民兵组织分开组建，避免人员重复交叉。\n第四十六条 县级以上人民政府及其有关部门应当加强对专业保障队伍建设的指导，将专业保障队伍纳入应急救援体系，并为其组织建设、训练演练提供必要的保障，发挥专业保障队伍在应急救援行动中的作用。","level":1},{"name":"第七章 宣传教育","text":"第四十七条 各级人民政府领导本行政区域内的国防动员宣传教育工作，各级军事机关协助和支持当地人民政府做好国防动员宣传教育工作。\n第四十八条 各级人民政府应当将国防动员教育纳入全民教育体系，利用广播、报刊、电影电视、网络、出版等多种宣传手段，对公民进行爱国主义、革命英雄主义教育，增强公民的国防观念和依法履行国防动员义务的意识。\n第四十九条 国家机关、社会团体、企业事业单位和基层群众性自治组织，应当加强对所属人员的国防动员教育，使其掌握必要的国防知识与技能。\n第五十条 各级人民政府及其有关部门应当采取多种形式，积极组织开展拥军优属活动，按照国家有关规定做好抚恤优待工作，激励军人献身国防事业，在全社会形成热爱军队、尊重军人、关心军烈属的氛围。\n第五十一条 新闻出版、广播影视和网络传媒等单位，平时应当按照国防动员的需要做好宣传教育和相关工作，战时应当严格遵守新闻宣传管理规定，落实新闻审查制度，把握正确舆论导向，凝聚意志，鼓舞士气，调动社会各界保家卫国的积极性，营造有利的舆论环境。","level":1},{"name":"第八章 特别措施","text":"第五十二条 国家决定实施国防动员后，国务院、中央军事委员会决定在本省部分地区实行特别措施，由省人民政府、省军区根据国务院、中央军事委员会的决定，按照规定的权限、程序、内容、区域和时限，组织实施下列特别措施：\n（一）对金融、交通运输、邮政、电信、新闻出版、广播影视、信息网络、能源水源供应、医药卫生、食品和粮食供应、商业贸易等行业实行管制；\n（二）对人员活动的区域、时间、方式，以及物资、运载工具进出的区域进行必要的限制；\n（三）在国家机关、社会团体和企业事业单位实行特殊工作制度；\n（四）为武装力量优先提供各种交通保障；\n（五）需要采取的其他特别措施。\n第五十三条 省人民政府、省军区和省国防动员委员会应当根据特别措施的内容和要求，结合实际，制定具体实施方案，保证特别措施的有效实施。\n特别措施实施区域内的公民和组织在规定的时限内，应当服从组织实施特别措施的机关的管理。\n第五十四条 不需要实行特别措施时，省人民政府、省军区应当根据国务院、中央军事委员会的决定及时终止。","level":1},{"name":"第九章 法律责任","text":"第五十五条 违反本办法规定，法律、行政法规有处罚规定的，从其规定。\n第五十六条 企业事业单位有下列情形之一的，由县级以上人民政府责令限期改正；逾期不改的，强制其履行义务，并处5万元以上20万元以下的罚款；造成损失的，依法承担赔偿责任：\n（一）在承建的贯彻国防要求的建设项目中未按照国防要求和技术规范、标准进行设计或者施工、生产的；\n（二）因管理不善导致战略储备物资丢失、损坏或者不服从战略物资调用的；\n（三）拒绝、拖延民用资源征用或者阻碍对被征用的民用资源进行改造的；\n（四）未按照转产、扩大生产军品和维修保障任务的要求进行军品科研、生产和维修保障能力储备，或者未按照规定组建专业技术队伍的；\n（五）拒绝或者故意延误军事订货的。\n第五十七条 相关部门、企业事业单位阻挠公民履行征召、担负国防勤务义务或者拒绝、拖延执行专业保障任务的，由县级以上人民政府责令限期改正；逾期不改的，强制其履行义务，并处1万元以上5万元以下的罚款；造成损失的，依法承担赔偿责任。\n第五十八条 有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分：\n（一）泄露统计调查对象资料的；\n（二）虚报、瞒报、迟报、拒报统计调查资料的；\n（三）伪造、篡改和毁损统计调查资料的。\n第五十九条 县级以上国防动员委员会和县级以上人民政府有关部门的工作人员在国防动员工作中玩忽职守、滥用职权、以权谋私的，由其所在单位或者监察机关依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第十章 附则","text":"第六十条 本办法自2013年2月1日起施行。","level":1}]},{"id":"h0162","sections":[{"name":"","text":"（2012年12月3日湖北省第十一届人民代表大会常务委员会第三十三次会议通过 根据2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2021年9月29日湖北省第十三届人民代表大会常务委员会第二十六次会议《关于集中修改涉及长江保护法省本级地方性法规的决定》第三次修正 2026年5月28日湖北省第十四届人民代表大会常务委员会第二十四次会议修订）","level":0},{"name":"第一章 总则","text":"第一条 为了规范水路交通活动，保障水上交通安全，建设长江中游航运中心，促进水路交通事业高质量发展，根据《中华人民共和国生态环境法典》、《中华人民共和国长江保护法》、《中华人民共和国航道法》、《中华人民共和国港口法》、《国内水路运输管理条例》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内水路交通规划，航道和港口建设、养护、保护，港口和水路运输经营，水上交通安全和环保及其监督管理等活动。\n本省行政区域内长江干线的航道建设、养护、保护，长江干线的水上交通安全，以及军事港口、军事船舶的监督管理等，依照有关法律、行政法规的规定执行。\n第三条 水路交通发展应当遵循科学规划、综合利用、生态优先、绿色发展、安全畅通、便民利民的原则。\n第四条 县级以上人民政府应当加强对水路交通工作的领导，将水路交通事业纳入国民经济和社会发展规划，在财政预算中安排与水路交通发展相适应的建设、养护和管理资金，协调解决水路交通事业发展中的重大问题。\n第五条 县级以上人民政府交通运输主管部门主管本行政区域内水路交通工作。交通运输综合执法机构具体承担水路交通行政执法工作。\n县级以上人民政府自然资源、生态环境、水行政、农业农村、应急管理、市场监督管理、船舶工业行业管理等有关部门按照职责分工，做好水路交通管理相关工作。\n乡镇人民政府、街道办事处依法做好水路交通管理的相关工作。","level":1},{"name":"第二章 规划","text":"第六条 省人民政府应当科学规划和统筹建设基础设施布局完善、运输服务安全高效便捷、航运发展绿色智慧的水路交通体系，加强与长江流域相关省（市）水运协同发展，形成通江达海、辐射中西部、面向全国的长江中游航运中心。\n第七条 县级以上人民政府交通运输主管部门应当将航道、港口、多式联运等内容，统筹纳入本行政区域综合交通运输体系发展规划，支持和保障水路交通事业发展。\n第八条 全省航道规划由省人民政府交通运输主管部门会同发展改革、水行政等部门编制，报省人民政府会同国务院交通运输主管部门批准公布。\n具备开发通航条件和已通航的河流、湖泊、水库、人工运河应当纳入全省航道规划。\n第九条 港口规划应当依照《中华人民共和国港口法》及其有关规定编制、审批和公布实施。\n编制港区控制性详细规划，应当优化港区水域、陆域总体布局，统筹安排港区内集疏运、给排水、供电、通信、防洪、安全监督、口岸管理、环境保护等设施。\n第十条 航道、港口规划应当注重饮用水水源地保护，统筹水上交通安全、防洪、生态环境保护等需求。\n经依法批准的航道、港口规划是水路交通建设的依据，未经法定程序不得修改。\n第十一条 县级以上人民政府应当依据航道、港口规划，统筹港口、产业和城市布局，科学规划工业园区、物流园区、保税港区，因地制宜发展临港经济。\n第十二条 县级以上人民政府及其有关部门应当结合航道、港口沿线历史文化、地域特色，统筹推进沿线文化旅游配套设施一体化规划、建设、运营，打造具有荆楚特色的文化景观、精品航线，推动水路交通和文化旅游融合发展。","level":1},{"name":"第三章 航道","text":"第十三条 省人民政府应当推进航道体系建设，加强与国务院交通运输等相关部门的合作共建，加快长江中游深水航道建设。\n县级以上人民政府及其交通运输主管部门应当加快汉江、清江及其他重要河流等航道的建设，推动水系连通和省际省内水运畅通。\n第十四条 航道建设、养护以政府投入为主，鼓励以多种方式筹集资金。\n第十五条 政府全额投资或者社会组织、个人捐资建设的船闸，以及已经建成并实行免费通行的船闸不得收取船舶过闸费。\n其他依法新建、改建或者扩建船闸确需收取船舶过闸费的，应当报经省人民政府批准，由省人民政府发展改革主管部门会同交通运输、水行政主管部门核定收费标准。\n第十六条 县级以上人民政府交通运输主管部门应当制定航道养护计划并组织实施，加强对航道及其设施的监测、养护，保持航道及其设施处于良好的技术状态。任何单位和个人不得阻挠航道养护作业。\n因自然灾害、事故灾难等造成航道损坏、阻塞的，交通运输主管部门应当启动航道突发事件应急预案，尽快修复抢通；需要相关部门配合的，由县级以上人民政府组织。\n第十七条 县级以上人民政府交通运输主管部门应当合理安排航道养护作业，避免进行限制通航的集中作业和在通航高峰期作业；确需进行限制通航的作业的，应当提前发布通告，根据需要划定临时航道。\n养护作业时应当设置明显的作业标志，并采取有效措施，减少对过往船舶航行的影响。\n第十八条 除依法不需要进行航道通航条件影响评价的工程外，建设下列与航道有关的工程，建设单位应当在工程可行性研究阶段就建设项目对航道通航条件的影响作出评价，并报交通运输主管部门审核：\n（一）跨越、穿越航道的桥梁、隧道、管道、渡槽、缆线等建筑物、构筑物；\n（二）通航河流上的永久性拦河闸坝；\n（三）航道保护范围内的临河、临湖建筑物、构筑物，包括码头、取（排）水口、栈桥、护岸、船台、滑道、船坞、圈围工程等。\n第十九条 严格控制在通航河流上新建、改建、扩建拦河闸坝。确需建设的，应当经科学论证，并依法开展生态环境影响评价。\n在通航河流上建设永久性拦河闸坝的，建设单位应当按照航道发展规划技术等级同步建设通航建筑物、过鱼设施，妥善解决施工和蓄水期间船舶的安全通航，并承担建设和运行维护费用。过鱼设施应当符合相关设计规范，满足水生生物洄游等需求，并保持正常使用。\n在不通航的河流或者人工渠道上修建闸坝后可以通航的，建设单位应当同步修建规模适当的通航建筑物或者预留通航建筑物位置。\n闸坝工程施工和改造确需中断通航的，建设单位应当征得交通运输主管部门同意。\n第二十条 省人民政府生态环境主管部门应当会同交通运输、发展改革、水行政等部门组织对现有拦河闸坝开展生态环境影响评估。对不符合国家和本省生态保护要求的，责令限期整改或者采取措施逐步退出，同步开展生态修复。\n第二十一条 位于航道及其上游支流上的水工程，应当在规划、工程可行性研究、设计、施工和调度运行中统筹考虑下游航道设计最低通航水位所需的下泄流量，但水文条件超出实际标准的除外。\n具有河湖生态流量保障要求的水工程，其管理者应当将生态流量调度纳入日常运行调度规程，建立常规生态调度机制，开展生态流量泄放和监测，保证河湖生态流量。\n县级以上人民政府水行政主管部门应当加强河湖生态流量管理，对水工程的下泄流量不符合生态流量泄放要求的，提出整改措施并监督实施。\n第二十二条 通航建筑物所有权人应当明确通航建筑物运行单位，承担通航建筑物的运行操作、船舶调度、设备设施养护等工作。\n鼓励分属不同所有权人的通航建筑物委托统一的通航建筑物运行单位进行管理。\n第二十三条 通航建筑物运行单位应当按照相关规定和技术标准编制通航建筑物运行方案，报经交通运输主管部门批准后公布实施，不得擅自变更。运行方案不能适应船舶通行需要的，运行单位应当按照法定程序及时调整。\n通航建筑物运行单位应当按照批准的运行方案进行船舶调度，提高通行效率。鼓励提供智慧化船舶过闸服务。\n第二十四条 同一通航河流上建有多梯级通航建筑物的，相关航道管理部门应当建立协调联动机制，制定联合调度规程，保障船舶有序、高效通行。\n第二十五条 新建、改建、扩建桥梁应当统筹考虑船舶航行安全，满足航运实际和远期发展需要。\n在通航水域上建设桥梁等建筑物，建设单位应当按照国家有关规定和技术要求，设置航标和桥梁防撞装置。\n桥区水上航标由交通运输主管部门负责维护。桥涵标、桥柱标、桥梁水尺标和桥梁防撞装置由桥梁建设单位或者运营单位负责维护。\n第二十六条 禁止下列危害航道通航安全的行为：\n（一）在航道内设置渔具或者水产养殖设施的；\n（二）在航道和航道保护范围内倾倒砂石、泥土、垃圾以及其他废弃物的；\n（三）在通航建筑物及其引航道和船舶调度区内从事货物装卸、水上加油、船舶维修、捕鱼等，影响通航建筑物正常运行的；\n（四）在航道内游泳、漂流，严重影响通航安全的；\n（五）危害通航建筑物、航标等航道设施安全的；\n（六）其他危害航道通航安全的行为。\n第二十七条 在河道内采砂，应当依照有关法律、法规的规定进行。禁止在依法划定的砂石禁采区采砂、无证采砂、未按照批准的范围和作业方式采砂等非法采砂行为。\n在航道和航道保护范围内采砂，不得损害航道通航条件。\n第二十八条 任何单位和个人不得损坏或者擅自移动、拆除航道设施。\n损坏航道设施的，当事人应当立即报告所在地交通运输主管部门；交通运输主管部门应当及时组织修复，修复费用由当事人承担。\n因工程建设等确需移动、拆除航道设施的，应当征得交通运输主管部门同意，并由建设单位承担移动、拆除和重建费用。","level":1},{"name":"第四章 港口","text":"第二十九条 县级以上人民政府应当按照深水深用、节约使用和集约利用的原则，保护和合理开发利用港口岸线资源。\n港口岸线资源应当优先用于公用码头建设，保障集装箱、大宗散货等专业化、规模化公用港区以及船用新能源加注站、水上搜救基地等服务设施的岸线需求。\n第三十条 在港口总体规划区内建设港口设施，需要使用港口岸线的，应当依法向交通运输主管部门提出申请。\n港口岸线使用人不得擅自变更已批准的港口岸线使用范围和用途。确需变更的，应当按照批准程序办理变更手续。\n港口岸线使用人不得擅自转让港口岸线使用权。确需转让的，出让人与受让人应当共同提出申请，报原审批机关批准。\n批准使用港口岸线的建设项目，逾期未开工建设或者未按照批准用途使用的，由原审批机关依法收回岸线使用权。\n第三十一条 县级以上人民政府应当开展岸线普查、调查，加强港口岸线使用监督管理，对不符合港口总体规划的码头，责令其经营人限期改造或者拆除。\n县级以上人民政府应当优化港口岸线资源配置，支持现有码头进行专业化、自动化、智能化改造，引导闲置、利用率低的码头进行整合，支持有条件的企业将自用码头向社会开放经营。\n第三十二条 县级以上人民政府交通运输主管部门应当会同自然资源、水行政、生态环境等部门，在航道沿线统筹规划、合理设置水上服务区，为船舶提供加油、加气、加水、岸电接用、零配件供应和船员休息、购物、通讯等服务。\n第三十三条 县级以上人民政府交通运输主管部门应当会同有关部门统筹规划、合理设置锚地。\n公用锚地由县级以上人民政府确定的部门或者单位负责维护，其他锚地由经营人负责维护。\n锚地管理单位应当建设系泊设施，设置专用航标，配备必要的应急设施，保障锚地锚泊安全。\n第三十四条 港口工程建设项目应当遵守相关法律法规和标准规范，符合港口规划，按照国家规定的建设程序进行。\n港口工程建设项目的安全设施和生态环境保护设施，应当与主体工程同时设计、同时施工、同时投产使用。\n第三十五条 建设危险货物码头，应当公开征求公众意见，并在可行性研究阶段按照国家规定进行安全评价，编制安全预评价报告。涉及危险化学品的码头，还应当就其对周边设施或者人员密集区、环境敏感区等的影响依法进行安全条件论证。\n从事危险货物港口作业的经营人应当按照交通运输主管部门核定的范围和作业方式从事危险货物港口作业。\n从事危险货物港口作业的经营人应当确保其操作人员参加国家规定的安全作业培训与考核，并取得相应上岗资格后，方可上岗作业。\n第三十六条 港口经营人应当在许可范围内从事港口经营活动，建立健全安全生产责任制，制定相关应急预案，完善安全生产条件，采取有效措施保障安全生产。\n第三十七条 鼓励、支持港口经营人使用清洁能源或者新能源作业设备和运输装备，配备岸基供电设施，采用清洁生产方式，建设绿色港口。","level":1},{"name":"第五章 水路运输","text":"第三十八条 县级以上人民政府及其交通运输主管部门应当完善港口集疏运体系，支持公路、铁路、航空、管道等与水路多式联运，提高全省水路货运量占比。\n鼓励、支持港口经营人和水路运输经营者采用多式联运设备和技术，优化运输组织方式，提高水路运输效率。\n第三十九条 从事水路运输经营活动，应当依法取得经营许可，在核准的许可事项范围内经营。\n水路运输经营者投入运营的船舶应当取得船舶营运证件。禁止水路运输经营者擅自改装船舶增加载客定额、载货定额。\n第四十条 县级以上人民政府应当组织相关部门加强客运船舶停靠站点管理，规范停靠站点选址、建设标准、运营管理、安全监管等事项。\n县级以上人民政府交通运输主管部门应当规范客运船舶的运营行为，健全安全运营规程和服务质量评价体系，强化水路客运市场监督管理。\n第四十一条 小型客运船舶运输经营者应当依法进行市场主体登记，并及时向交通运输主管部门和相关行业主管部门报告开航、新增或者减少营运船舶、终止经营等情况。\n本条例所称小型客运船舶，是指核定载客十二人及以下，从事经营性旅客运输的船舶。\n第四十二条 县级以上人民政府应当推进船舶经纪、船舶管理、船舶代理、客货运代理等传统航运服务业转型升级，发展航运金融、航运信息咨询、人才培养与服务等现代航运服务业，支持航运服务集聚区建设。","level":1},{"name":"第六章 安全与环保","text":"第四十三条 县级以上人民政府应当加强水上交通安全管理，建立健全水上交通安全管理责任制度，完善执法联动和协作机制，制定水上交通安全事故应急预案，保障应急救援工作正常开展。\n第四十四条 县级以上人民政府交通运输主管部门按照国家和省有关规定对水上交通安全实施统一监督管理。\n县级以上人民政府自然资源、住房和城乡建设、水行政、农业农村、文化和旅游、体育等部门按照有关规定履行水上交通安全的行业监督管理职责。\n法律、法规未明确规定安全监督管理部门的，县级以上人民政府应当按照业务相近的原则确定安全监督管理部门。\n第四十五条 船舶应当依法进行登记和检验，按照国家规定配备持有适任证书或者其他适任证件的船员。船舶应当足额配备救生衣和救生浮具。\n船舶所有人或者经营人应当建立健全安全生产管理责任制度，保障安全生产投入，及时防范化解安全风险、排查消除安全隐患，并对船舶的交通安全负责。\n第四十六条 船舶设计、生产、修理企业应当向船舶工业行业管理部门备案，依法开展生产经营活动。\n船舶生产、修理企业和船用产品生产者应当对其生产、修理的船舶、船用产品的质量负责；未经检验或者检验不合格的，不得出厂。\n船舶检验机构负责船舶和按照国家规定应当进行检验的船用产品的检验工作。\n县级以上人民政府及其交通运输主管部门应当加强船舶检验机构和队伍建设，提升船舶检验技术能力和管理水平。\n第四十七条 无船名船号、无船舶证书、无船籍港的船舶和依法应当强制报废的船舶不得在本省水域航行、停泊、作业。\n县级以上人民政府应当及时组织交通运输、农业农村、水行政等部门对无船名船号、无船舶证书、无船籍港的船舶开展认定和处置工作。\n第四十八条 船舶通过桥区水域，应当采取相应措施，满足通航桥孔净空尺度等参数要求，确保安全通过。\n船舶不得在桥区水域内从事国家禁止的航行、作业等活动。除紧急情况或者航道疏浚、维护外，船舶不得在桥区水域停泊；因紧急情况停泊的，应当采取防撞等有效措施，并立即向交通运输主管部门报告，尽快驶离桥区水域。\n第四十九条 在通航水域或者岸线上进行可能影响通航安全的水上水下作业或者活动，应当依法报交通运输主管部门批准或者备案。\n建设单位、施工单位或者活动主办方应当在作业或者活动区域设置安全警示标志和显示信号，采取相应安全保障措施。\n第五十条 县级以上人民政府应当组织交通运输主管部门和相关部门制定乡镇自用船舶安全管理制度和标准规范，建立乡镇自用船舶数据档案，加强安全监督管理。\n乡镇人民政府、街道办事处应当在交通运输等部门指导下，对乡镇自用船舶进行登记造册，明确船名、权属、用途，加强安全知识宣传，做好日常管理工作。\n乡镇自用船舶不得超载，不得从事客货运输、游览娱乐等经营性活动，不得妨碍其他船舶正常航行。\n本条例所称乡镇自用船舶，是指家庭或者个人用于农（林）业生产、日常生活的非经营性船舶。\n第五十一条 设置和撤销渡口，由县级人民政府审批，相关情况应当及时向社会公布。停渡一年以上或者已完成渡改桥的渡口应当撤销。\n乡镇人民政府、街道办事处依法履行乡镇渡口渡船的安全管理职责。交通运输主管部门应当按照规定组织实施渡口、渡船、渡运安全监督检查。\n第五十二条 渡口应当根据其渡运对象的种类、数量、水域情况和过渡要求，合理设置码头、引道，配置必要的指示标志、船岸通讯和船舶助航、消防、安全救生等设施并定期维护。\n中小学校学生、学前儿童集中乘坐渡船的，值班船员应当督促穿着救生衣。\n第五十三条 有下列情形之一的，交通运输主管部门可以根据情况采取限时航行、单航、封航等临时性措施，并予公告：\n（一）恶劣天气、异常水情、自然灾害；\n（二）大范围水上施工作业；\n（三）影响航行的水上交通事故；\n（四）水上大型群众性活动或者体育比赛；\n（五）应急抢险；\n（六）对航行安全影响较大的其他情形。\n第五十四条 县级以上人民政府应当健全水上搜救机制，整合水上搜救资源，组建专业搜救队伍，配备必要的设施、设备，定期组织培训和应急演练，提高水上搜救能力。\n鼓励生产经营单位、社会组织和其他社会力量建立水上搜救队伍，参与水上搜救。\n第五十五条 船舶发生水上交通安全事故，当事人应当采取措施减少事故损失，并立即向交通运输主管部门报告。造成或者可能造成水体污染的，还应当报告生态环境主管部门。\n交通运输主管部门发现或者接到事故报告后，应当立即组织救助，启动应急预案，及时向事故发生地人民政府和上级主管部门报告。\n第五十六条 在航道、港口规划编制和工程建设时，应当依法开展生态环境影响评价，对饮用水水源保护区、自然保护地等重要、敏感生态功能区可能造成的影响进行科学论证，采取有效保护措施。未依法进行生态环境影响评价的开发利用规划，不得组织实施；未依法进行生态环境影响评价的建设项目，不得开工建设。\n开展生态环境影响评价，应当依法采取举行听证会、公开征求意见等方式，保障公众参与生态环境保护的权利。\n第五十七条 禁止船舶在依法划定的禁止航行区域内航行。\n严格限制在生态保护红线、自然保护地、饮用水水源保护区、水生生物重要栖息地水域实施航道整治工程。确需整治的，应当经科学论证，并依法办理相关手续。\n第五十八条 县级以上人民政府应当建立健全船舶污染物接收、转运和处置联合监管机制，统筹规划建设船舶污染物的接收、转运和处置设施。\n港口经营人应当配备相应的污染防治设施设备和器材，并按照规定接收和处理船舶垃圾、生活污水、含油污水、残油、废油等船舶污染物。\n船舶所有人、经营人应当遵守船舶污染防治法律、法规的规定，履行船舶污染防治义务。\n第五十九条 县级以上人民政府应当加快船舶更新改造，推进船型标准化；推动绿色智能船舶研发设计和推广应用，完善检验、认证等配套服务，统筹布局建设能源加注、充换电设施。\n鼓励船舶建设和改造受电设施，在停泊期间优先使用岸电；鼓励对使用清洁能源、新能源动力的船舶减免过闸费。\n鼓励、支持金融机构服务绿色智能船舶产业链发展，创新信贷、债券、保险、融资租赁等金融产品，支持绿色智能船舶推广应用。","level":1},{"name":"第七章 保障措施","text":"第六十条 县级以上人民政府应当加大对水路交通建设的资金投入，支持航道和港口建设及养护、绿色智能船舶发展、公益性渡口渡船建设维护及渡工补助、水上搜救体系建设、水上交通安全监管等水路交通事业。\n第六十一条 鼓励外资和民间资本依法平等投资水路交通基础设施建设、养护和经营。\n鼓励、支持港航企业通过上市、发行债券、发行资产证券化产品等方式筹集资金，建设港口码头及物流园区。\n鼓励各类金融机构开发和提供适合中小港航企业特点的金融产品和服务。\n第六十二条 县级以上人民政府及其有关部门应当加强水路交通职业教育和专业人才培养，提升从业人员素质；鼓励有条件的地方培养、引进国际化、高层次、复合型航运服务专业人才。\n支持高等院校航运相关专业发展，开展产学研合作。\n第六十三条 省人民政府交通运输主管部门应当加强物联网、大数据、人工智能等信息技术的推广应用，建设船、闸、港、货一体的智慧航运服务平台，提供导航助航、过闸、锚泊、安全预警等一站式服务。\n通航条件以及禁限航、船舶通行、船闸运行、港口调度、气象、水文、安全应急等信息，应当汇集至智慧航运服务平台并及时发布，供船舶所有人、经营人查询、使用。\n第六十四条 省人民政府交通运输主管部门应当制定水路交通公共数据资源目录和开放清单，明确数据项、提供单位、使用条件等信息，并实行动态更新。\n县级以上人民政府应当加强水路交通公共数据资源供给和规范流通利用，引导港航企业等主体依法开放利用数据。\n第六十五条 县级以上人民政府及其交通运输主管部门应当加强水路交通的监督管理，建立健全以信用为基础的监管机制，依法推进水路交通从业单位和从业人员信用信息的归集、共享、应用，实行守信激励和失信惩戒。\n第六十六条 县级以上人民政府及其交通运输等部门应当加强水路交通工作信息公开，完善公众参与程序，为其参与和监督水路交通工作提供便利。\n任何单位和个人有权对无证经营、超载运输、污染环境等违法行为进行投诉、举报。交通运输等部门应当依法调查核实并及时处理。","level":1},{"name":"第八章 法律责任","text":"第六十七条 违反本条例，法律、法规有规定的，从其规定。\n第六十八条 违反本条例第二十三条规定，通航建筑物运行单位未按照规定编制运行方案，擅自变更运行方案，或者未按照批准的运行方案进行船舶调度的，由交通运输主管部门责令限期改正；逾期未改正的，处1万元以上3万元以下罚款。\n第六十九条 违反本条例第二十六条规定，危害航道通航安全的，由交通运输主管部门责令改正，对单位处5千元以上5万元以下罚款，对个人处200元以上2千元以下罚款；造成损失的，依法承担赔偿责任。\n第七十条 违反本条例第三十九条第二款规定，水路运输经营者使用未取得船舶营运证件的船舶从事水路运输，或者擅自改装船舶增加载客定额、载货定额的，由交通运输主管部门责令该船停止经营，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足2万元的，处2万元以上10万元以下罚款。\n第七十一条 违反本条例第四十七条第一款规定，无船舶证书、无船籍港且无船名船号的船舶从事客货运输的，由交通运输主管部门责令停止违法行为，没收船舶、违法所得，可以并处船舶价值二倍以下罚款。\n第七十二条 国家机关及其工作人员在水路交通工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第九章 附则","text":"第七十三条 本条例自2026年8月1日起施行。","level":1}]},{"id":"h0163","sections":[{"name":"","text":"（2013年5月23日湖北省第十二届人民代表大会常务委员会第三次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了促进革命老区经济社会发展，提高人民生活水平，根据国家有关规定，结合本省实际，制定本条例。\n第二条 本条例所称革命老区，是指第二次国内革命战争和抗日战争时期在中国共产党领导下建立和发展起来的革命老根据地。本省革命老区的具体名录及重点扶持对象由省人民政府按照国家规定的标准确定并公布。\n第三条 促进革命老区发展坚持政府主导、部门帮扶、社会参与、自我发展，实行统筹兼顾与突出重点相结合、产业发展与基础设施建设相结合、经济发展与生态文明建设相结合、政策扶持与社会多元投入相结合、多方帮扶与自力更生相结合。\n第四条 省人民政府和革命老区所在地的市（州）、县级人民政府应当将革命老区发展纳入国民经济和社会发展规划及年度计划，制定优惠政策，加大投入，整合资源，组织、动员各方面力量支持革命老区发展。\n第五条 县级以上人民政府革命老区发展主管部门具体负责本行政区域内革命老区发展的组织协调工作；有关部门按照各自职责，做好本部门、本行业扶持革命老区工作。\n第六条 支持革命老区深化改革、扩大开放，运用市场机制，引进市场主体、项目和资金，促进革命老区发展。\n革命老区应当依靠人民群众，坚持自力更生、艰苦奋斗，发挥自身优势和潜力，增强自我发展能力。\n第七条 实行革命老区发展目标责任制和考核评价制度，建立科学考核评价体系，将目标任务完成情况作为政府及相关部门考核评价的重要内容。\n第八条 对促进革命老区发展作出突出贡献的单位和个人，县级以上人民政府应当给予表彰和奖励。","level":1},{"name":"第二章 规划与实施","text":"第九条 省人民政府应当制定革命老区发展规划，确定革命老区发展目标、工作重点、推进步骤、保障措施。\n制定革命老区发展规划应当从实际出发，与国家和省发展规划、发展战略相衔接，符合主体功能区规划的要求，尊重革命老区人民意愿，体现革命老区特色，其规划内容应当涵盖人力资源开发、基础设施建设、支柱和特色产业培育、社会事业发展、生态环境保护、民生改善和社会保障建设等方面。\n革命老区发展规划采取政府组织、部门合作、公众参与的方式编制；非经法定程序，不得擅自改变。\n第十条 加快革命老区基础设施建设，构建功能完善的基础设施体系。推进革命老区交通建设，加强县、乡、村公路升级改造，提高县乡公路建设和通村通组公路管理养护的补助标准，发展农村公交客运，加强交通安全管理。实施基本农田设施建设、小流域治理、水土保持和天然林保护工程，加强能源、通信、广播电视等基础设施建设，增强革命老区振兴发展的支撑力。\n第十一条 支持革命老区以产业为基础，以市场为导向，依靠科技进步，因地制宜发展支柱产业、特色产业，加强产业化、规模化、集约化，逐步壮大经济实力。提高革命老区居民收入，其增长幅度应当高于全省平均水平。\n第十二条 发展革命老区社会事业，促进基本公共服务均等化。\n加强对革命老区教育的投入，优化教育资源配置，推进革命老区教育的信息化、现代化，改善革命老区办学条件，发展职业技术教育和各类技术培训。加强边远艰苦地区教师生活保障，改善中小学寄宿生生活条件，提高家庭经济困难学生生活补助标准，实施中小学生营养改善计划。在高考招录中制定面向革命老区的定向招生计划，确保革命老区学生公平接受优质教育的机会。\n推进革命老区县（市）公共图书馆、文化馆、体育场所等公共设施建设与维护，支持乡镇文化站、群众性健身设施建设。\n完善新型农村合作医疗制度，健全农村医疗卫生服务体系，改善革命老区县级医疗卫生机构和乡村卫生院（室）的条件，提供优质的人口与计划生育服务，提升卫生服务保障能力和重大疾病、多发病的防控能力。\n完善革命老区的人力资源公共服务平台，提供就业信息、政策指导、权益保障等服务，扶持就业资金重点向革命老区倾斜。\n第十三条 完善与农村扶贫制度相衔接的革命老区社会保障制度，对因灾因病等陷入贫困人口提供救助。\n建立和完善对革命老区优抚对象的帮扶机制，解决老红军、老党员、烈军属、烈士后代、复退军人、五保户的生活困难。\n第十四条 加强革命老区生态建设和环境保护。实施生态修复工程，开展水生态系统治理，加强森林植被保护与恢复，加强地质灾害防治，提升生态环境质量。开发利用农村清洁能源，加强生活垃圾和污水处理，实行多种污染物协同控制，推进农村环境综合整治。生态建设和环境保护应当纳入革命老区发展目标考核评价的范围。\n第十五条 推进革命老区新农村建设，实施农村危房改造、扶贫搬迁、饮水安全工程、农村电网改造升级等项目建设，提高革命老区人民生活水平。\n第十六条 推进革命老区新型城镇化建设，建设产业聚集、商贸流通、生态良好、宜居休闲的中心城镇，培育具有红色文化、民俗风情、地方特色的城镇和村寨。支持革命老区创建区域中心城市。\n第十七条 大力宣传红色文化，弘扬革命老区精神。加强革命遗址遗迹保护，建立修缮、维护、利用机制。加大革命遗址遗迹保护的经费投入，提高爱国主义教育基地、革命传统教育基地免费开放的补助标准。充分发挥红色旅游资源优势，完善旅游配套服务，大力发展红色旅游。","level":1},{"name":"第三章 保障措施","text":"第十八条 加强革命老区产业发展扶持力度，对革命老区的产业从规划引导、项目安排、要素配置和财税扶持等方面给予重点支持和倾斜。\n建立健全产业发展激励约束机制，发展符合资源节约、环境友好要求的产业。\n第十九条 建立促进革命老区发展财政投入稳定增长机制，加大财政对革命老区资金转移支付力度。省人民政府应当在预算中安排革命老区发展专项资金并逐年增长，其幅度高于省级财政经常性收入的增长幅度。市（州）、县级人民政府应当根据本地实际和财力状况在预算中安排革命老区发展专项资金。\n第二十条 严格落实国家税收优惠政策。对在革命老区投资兴办的企业，按照规定给予省级开发区的土地供给、规费减免等优惠政策。\n第二十一条 依照国家规定，扩大扶贫贴息贷款规模，重点扶持产业化扶贫龙头企业，支持农村中小型基础设施建设及社会事业项目，带动产业结构调整、生产生活条件改善和农民增收。\n第二十二条 省人民政府及其有关部门应当采取措施，支持在革命老区设立村镇银行等新型农村金融机构，发展信用担保机构，创新担保机制，为企业发展提供有效的融资平台。\n鼓励金融机构加大对革命老区信贷支持力度，降低贷款门槛，在革命老区的信贷增长幅度应当高于其他地区。推广农业保险，提高农村抗灾能力。\n第二十三条 加强革命老区用地保障，在安排用地规划指标、土地利用年度计划等方面予以倾斜。支持开展农村土地综合整治工作，因地制宜开展低丘缓坡、荒滩等未利用地开发利用和工矿废弃地复耕利用，加大对废弃矿山植被恢复和生态建设工程的资金支持。\n第二十四条 建立革命老区生态环境共建共享的长效机制，完善森林资源保护、水源地保护、流域水环境保护等重点领域生态补偿制度，提高补偿标准。加强矿产资源开发利用管理，对重要矿种按照规定收取矿产资源补偿费。\n第二十五条 完善革命老区人才引进、培养、使用和激励机制，加大革命老区与发达地区干部、教师、医生和科技人员交流工作力度。国家和省重大人才工程和引智项目向革命老区倾斜，鼓励专业人才向革命老区流动。\n省人民政府及其相关部门定期组织对革命老区专业技术人员培训，在安排专项资金时，对基层专业技术人员的继续教育和实用技术培训给予倾斜。\n省人民政府应当制定政策，对长期在革命老区从事教育、科技、文化、卫生、农业等服务的专业技术人员，给予革命老区特殊工作津贴，在职务晋升、职称评定、业务培训、子女入学、医疗服务等方面实行倾斜。\n第二十六条 鼓励有条件的革命老区先行先试，县级以上人民政府应当整合、优化各方面资源，建立支持革命老区发展的长效机制。\n鼓励企业事业单位、社会团体和个人参与革命老区经济建设，推进教育、科技、文化、卫生、体育等社会事业发展。\n第二十七条 县级以上人民政府应当建立对口帮扶机制，协调和组织国家机关、企业事业单位、驻鄂部队、社会团体以及个人，参与革命老区对口帮扶和共建活动。对口帮扶单位应当发挥各自优势，在资金、项目、人才、技术上给予支持。\n县级以上人民政府应当充分发挥革命老区建设促进会（扶贫基金会）、扶贫开发协会和老科技工作者协会等社会团体在促进革命老区发展中的作用。","level":1},{"name":"第四章 监督管理","text":"第二十八条 革命老区发展资金由中央下拨财政扶贫资金、国家扶贫信贷资金、革命老区专项转移支付资金、县级以上人民政府预算安排的革命老区发展专项资金和政府部门安排的革命老区建设项目资金以及社会捐资组成，主要用于基础设施建设、重点产业培育、科技成果推广、民生与社会保障以及革命遗址遗迹保护等项目，专款专用。\n革命老区发展资金应当及时拨付到位，采取专账核算，实行国库集中支付，任何单位和个人不得截留、挤占、挪用、套取。\n省人民政府相关部门筹资用于革命老区建设的资金，应当列入部门管理的专项资金分配和项目实施计划，按时拨付到位。\n第二十九条 革命老区发展主管部门依据革命老区发展规划建立项目库，根据年度扶持资金计划和革命老区发展的需要确定年度扶持项目。项目实施实行法人责任制、招标投标制、建设监理制、合同管理制等。\n第三十条 使用省革命老区发展资金的，由被扶持单位向县级人民政府主管部门与财政部门提出项目申请和立项报告，由县级人民政府批准后报省及市（州）人民政府主管部门备案。\n项目主管部门应当对扶持项目的实施情况进行监督检查。项目确定下达后，项目单位应当严格组织实施，不得随意变更。确需变更的，按照原程序报批。\n第三十一条 建立健全革命老区发展资金的监督机制。\n财政、审计、监察等部门应当根据各自职责，对革命老区发展资金的管理使用情况进行监督检查、审计和监察。\n革命老区发展主管部门、项目主管部门应当对革命老区发展资金使用、项目实施等情况予以公告公示，公开受理电话和电子信箱，接受社会监督、咨询。\n任何单位和个人都有权对促进革命老区发展活动以及革命老区发展资金使用、项目实施情况等进行监督。\n第三十二条 革命老区人民代表大会常务委员会应当定期听取和审议本级人民政府促进革命老区发展的专项工作报告，将促进革命老区发展作为监督检查的重要内容。","level":1},{"name":"第五章 法律责任","text":"第三十三条 违反本条例，不按照规定实施扶持项目和使用资金的，由有关部门责令限期改正，并予通报批评。\n第三十四条 国家工作人员在促进革命老区发展工作中滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十五条 革命老区属于少数民族地区、边远地区或者贫困地区的，在适用本条例的同时，按照规定享有其他优惠政策。\n第三十六条 省人民政府及相关部门应当根据本条例，及时制定配套政策、措施。\n第三十七条 本条例自2013年8月1日起施行。2001年7月27日湖北省第九届人民代表大会常务委员会第二十六次会议通过的《湖北省扶持老区建设条例》同时废止。","level":1}]},{"id":"h0164","sections":[{"name":"","text":"（2013年11月29日湖北省第十二届人民代表大会常务委员会第六次会议通过 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了保护耕地资源和农业生态环境，提高耕地质量，促进农业现代化和可持续发展，根据《中华人民共和国生态环境法典》、《中华人民共和国农业法》、《中华人民共和国土地管理法》和《基本农田保护条例》等法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 在本省行政区域内从事耕地质量保护及其相关活动，适用本条例。\n本条例所称耕地质量，是指由耕地地力、田间基础设施、耕地土壤环境等构成的满足农作物生长适宜性、安全性和持续性的能力。\n第三条 耕地质量保护遵循科学规划、严格保护、综合治理、永续利用的原则。\n第四条 县级以上人民政府应当将耕地质量保护纳入国民经济和社会发展规划，根据本行政区域内耕地质量状况、国土空间规划和农业发展规划，制定与基本农田保护专项规划、农田水利建设规划、土地整治规划和农田防护林规划等相衔接的耕地质量保护中长期规划，并组织实施。\n第五条 县级以上人民政府农业农村主管部门负责本行政区域内耕地质量保护工作，其所属的耕地质量工作机构承担耕地质量调查、监测和评价等具体工作。\n县级以上人民政府自然资源主管部门负责土地整治、土地复垦实施中的耕地质量保护工作。\n县级以上人民政府其他相关部门按照各自职责，共同做好耕地质量保护相关工作。\n乡镇人民政府负责本行政区域内耕地质量保护工作。村（居）民委员会、农村集体经济组织应当指导并督促耕地使用者合理利用耕地，保护和提高耕地质量。\n第六条 县级以上人民政府应当按照国家和省相关规定，安排一定比例的专项资金用于耕地质量保护，并纳入同级财政预算。\n第七条 省人民政府应当鼓励支持耕地质量保护的基础性、适用性、前沿性科学技术研究，加大对耕地质量保护的科技投入。\n第八条 县级以上人民政府及其相关部门应当加强耕地质量保护的宣传教育，普及耕地质量保护知识，增强全社会的耕地质量保护意识。\n第九条 任何单位和个人都有保护耕地质量的义务，并有权对破坏耕地质量的行为进行劝阻、检举、控告。\n对耕地质量保护工作取得显著成绩的单位和个人，由县级以上人民政府及其相关部门给予表彰或者奖励。","level":1},{"name":"第二章 耕地质量建设","text":"第十条 县级以上人民政府应当组织相关部门和单位，依据耕地质量建设标准，积极推进农田水利基本建设、高标准农田建设、中低产田改造、农田防护林建设、地力培肥、土地整治、土地复垦、耕地土壤环境保护、退化和污染耕地修复等耕地质量建设项目，提高耕地质量。\n第十一条 耕地质量建设项目的主管部门应当健全耕地质量建设活动的管理制度，加强项目实施的监督管理，并在项目实施前将项目批复文件抄送农业农村主管部门。耕地质量建设项目的施工单位应当按照国家和省有关耕地质量的技术标准进行施工，并接受耕地质量管理部门的监督。\n第十二条 县级以上人民政府应当组织农业农村、自然资源主管部门，对国土空间规划确定的建设用地规模范围内的耕地编制耕作层土壤再利用方案。\n建设项目经批准占用耕地的，建设单位应当根据实际需要，按照耕作层土壤再利用方案的要求剥离耕作层土壤。剥离的耕作层土壤用于新开垦耕地、复垦耕地、劣质地或者其他耕地的土壤改良。\n第十三条 自然资源主管部门应当在土地整治项目规划设计方案中就耕地耕作层土壤剥离提出明确要求，并督促施工单位按设计方案剥离耕作层土壤。\n施工单位应当按照要求剥离耕地耕作层土壤，防止损坏耕地耕作层，保护耕地质量。\n第十四条 县级以上人民政府应当制定扶持政策、措施，鼓励下列耕地地力培肥行为：\n（一）建设绿肥良种繁育基地；\n（二）有机肥和配方肥的生产、推广；\n（三）耕地使用者运用测土配方施肥、秸秆还田、绿肥种植、有机肥和配方肥施用、保护性耕作等技术，改良土壤，提高地力；\n（四）新开发、复垦和整理耕地的后续培肥。\n县级以上人民政府农业农村主管部门应当加强对耕地地力培肥的培训和指导，及时解决应用中的技术问题。\n第十五条 禁止损毁或者非法占用田间基础设施。\n村（居）民委员会、农村集体经济组织应当组织耕地使用者维护田间基础设施，改善耕作条件。","level":1},{"name":"第三章 耕地养护与污染防治","text":"第十六条 县级以上人民政府及其相关部门应当根据耕地质量保护规划制定耕地质量保护措施，保护耕地资源，防止耕地污染、破坏和地力衰退。\n第十七条 县级以上人民政府农业农村主管部门应当建立耕地质量保护示范区和土壤污染防治与修复示范工程，组织开展地力培肥、污染防治、生态耕作方式等耕地质量保护技术和新型农机具的研究、示范与推广，加强对耕地使用者的指导、培训，推进科技成果的转化和产业化。\n第十八条 生产、销售的肥料、土壤调理剂、农药和除草剂，应当达到国家或者行业标准，并依法登记。\n耕地使用者应当科学、合理、安全使用肥料、土壤调理剂、农药、除草剂、农用薄膜等农业投入品，及时回收非降解残膜和投入品包装物，不得使用未依法登记的肥料和农药等农业投入品，防止、减少农业面源污染。\n耕地使用者不得使用未经无害化处理或者经处理后仍不符合国家规定要求的污泥、粉煤灰、城乡生活垃圾和其他有机废弃物作为肥料直接施入耕地，防止重金属、有机污染物和其他有毒有害物质污染耕地。\n县级以上人民政府农业农村主管部门应当指导耕地使用者科学、合理、安全使用农业投入品。\n第十九条 县级以上人民政府农业农村、生态环境主管部门应当加强对焚烧农作物秸秆危害的宣传，并制定激励措施，鼓励、扶持和指导农作物秸秆还田，修复、改善土壤，补充土壤有机质。\n第二十条 建设项目经批准确需临时占用耕地或者其田间基础设施的，建设单位在使用时应当采取保护措施，并自临时用地期满之日起一年内恢复种植条件。\n第二十一条 禁止向耕地排放或者倾倒废水、废气、固体废物等有毒有害物质。\n养殖场的畜禽粪便等养殖废弃物作为肥料直接施用的，应当符合无害化标准，防止污染耕地。\n第二十二条 耕地灌溉用水应当符合国家农田灌溉水质标准。\n县级以上地方人民政府生态环境、水行政主管部门应当加强水质监测，发现灌溉用水水质不符合国家农田灌溉水质标准的，应当及时报告本级人民政府，并采取治理和补救措施。\n第二十三条 县级以上人民政府应当采取工程、生物和农艺等措施，对耕地水土流失、土壤酸化沙化等耕地质量退化进行综合防治，保护和改善耕地生态环境。\n对受污染的耕地，县级以上人民政府农业农村、生态环境主管部门应当采取农艺调控、种植业结构调整、土壤污染治理与修复等措施开展耕地环境污染综合治理，减少或者消除污染，恢复其基本功能。对严重污染和地下水超采地区的耕地，依法科学合理调整土地用途，有序实现耕地休养生息。\n第二十四条 因事故或者其他突发性事件，造成耕地环境污染的，当事人必须立即采取处理措施，并向当地生态环境和农业农村主管部门报告。农业农村主管部门应当会同生态环境主管部门及时提出对受污染耕地的治理方案，责令责任人进行治理。","level":1},{"name":"第四章 耕地质量监测与监督管理","text":"第二十五条 省人民政府应当建立耕地质量监测与评价体系。\n县级以上人民政府农业农村主管部门应当会同生态环境、自然资源、水行政主管部门建立耕地质量监测和评价制度，健全耕地质量监测网络和预警体系，对耕地地力和环境状况进行动态监测，并向本级人民政府和上一级主管部门提出耕地质量报告以及建设与保护建议。\n县级以上人民政府应当根据耕地质量变化情况，组织相关部门采取相应措施，提高耕地质量。\n第二十六条 省人民政府农业农村主管部门应当会同生态环境、水行政主管部门每五年组织开展全省耕地质量详查，评价耕地质量等级，建立耕地质量档案，并将耕地质量调查、评价结果予以公示。\n第二十七条 耕地质量管理工作机构应当与耕地使用者签订协议，就耕地质量长期定位监测点的设立、保护、补偿等明确双方的权利义务。\n耕地质量管理工作机构应当在耕地质量长期定位监测点设立永久性标志。\n第二十八条 禁止损毁、擅自移动耕地质量长期定位监测点的基础设施和永久性标志。确需移动的，应当征得设立该监测点的耕地质量管理工作机构同意，所需费用由提出移动的单位或者个人承担。\n第二十九条 县级以上人民政府应当将耕地质量保护情况纳入耕地保护目标考核内容，建立耕地质量保护监督检查和约谈制度，定期组织相关部门对耕地质量保护情况进行检查，检查情况书面报告上一级人民政府。对耕地质量保护中发现严重问题的，上级人民政府应当对相关人民政府负责人进行诫勉谈话。\n县级以上人民政府应当加强耕地质量保护队伍建设，改善设施设备和工作条件，提高耕地质量保护水平。\n第三十条 非农建设项目经批准占用耕地的，占用耕地的单位应当开垦与所占耕地质量和数量相当的耕地。没有条件开垦或者开垦的耕地不符合要求的，应当按照规定缴纳耕地开垦费，专款用于开垦新的耕地。\n第三十一条 占补平衡补充耕地、补划基本农田项目竣工验收时，项目主管部门应当及时书面告知农业农村主管部门开展耕地地力评定工作。\n农业农村主管部门开展耕地地力评定工作，应当组织专家实地踏勘，采集土壤样品送有资质的土壤肥料检测机构进行检验，根据踏勘情况和土壤样品检验报告，及时出具耕地地力评定意见。耕地地力评定意见应当作为项目竣工验收的必要依据；耕地地力达不到标准的，项目不得通过竣工验收。","level":1},{"name":"第五章 法律责任","text":"第三十二条 违反本条例规定，法律、行政法规已有处罚规定的，从其规定。\n第三十三条 建设单位未按照本条例第十二条第二款规定，剥离耕作层土壤的，由县级以上人民政府农业农村主管部门责令限期改正；施工单位违反本条例第十三条第二款规定，损坏耕作层土壤的，由县级以上人民政府自然资源主管部门责令限期改正。逾期不改正或者无法改正的，按照耕作层土壤的损坏面积处以每平方米30元以上50元以下罚款。\n第三十四条 违反本条例第十五条第一款规定，损毁或者非法占用田间基础设施的，由县级以上人民政府农业农村主管部门责令停止违法行为，限期恢复原状或者修复；逾期未恢复原状或者修复的，依法赔偿损失，并由县级以上人民政府农业农村主管部门处以2000元以上1万元以下罚款。\n第三十五条 违反本条例第十八条第一款规定，生产、销售未依法登记的肥料、土壤调理剂的，由县级以上人民政府农业农村主管部门责令停止违法行为，没收违法产品，并处违法所得1倍以上3倍以下罚款；没有违法所得的，处以5000元以上2万元以下罚款。\n第三十六条 违反本条例第二十八条规定，损毁、擅自移动耕地质量长期定位监测点的基础设施和永久性标志的，由县级以上人民政府农业农村主管部门责令改正，恢复原状；不能恢复原状的，责令赔偿损失，并处1000元以上5000元以下罚款。\n第三十七条 国家机关及其工作人员在耕地质量保护工作中滥用职权、玩忽职守、徇私舞弊的，依法由所在单位或者上级主管部门对负有责任的领导人员和直接责任人员给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十八条 本条例自2014年2月1日起施行。","level":1}]},{"id":"h0165","sections":[{"name":"","text":"（2014年1月9日湖北省第十二届人民代表大会常务委员会第七次会议通过 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2021年9月29日湖北省第十三届人民代表大会常务委员会第二十六次会议《关于集中修改涉及长江保护法省本级地方性法规的决定》第二次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第三次修正）\n第一条 根据《中华人民共和国水法》、《中华人民共和国抗旱条例》等有关法律、行政法规，结合本省实际，制定本条例。\n第二条 抗旱工作应当优先满足城乡居民生活用水，保障基本生态用水、粮食安全用水，并统筹农业、工业、生态修复用水以及航运等需要。建立政府主导与市场引导相结合、开源与节流相结合、优化水资源配置与调整产业结构相结合、经济效益与社会效益相结合的抗旱长效机制。\n第三条 抗旱工作实行各级人民政府行政首长负责制，统一指挥、部门协作、分级负责、社会参与。\n县级以上人民政府应当将干旱灾害预防和抗旱减灾工作纳入国民经济和社会发展规划，加强干旱灾害预防和抗旱减灾基础设施建设，完善抗旱工程体系、指挥调度体系和服务体系。乡镇人民政府、街道办事处负责本行政区域内干旱灾害预防和抗旱减灾的组织协调工作，明确相应机构或者人员，承担旱情收集、监测、分析、上报和灾情统计核实、抗灾救灾物资发放等具体工作。\n县级以上防汛抗旱指挥机构在上级防汛抗旱指挥机构和本级人民政府的领导下，负责组织、指挥本行政区域内的抗旱工作。\n第四条 县级以上人民政府应当将抗旱工作所需经费纳入本级年度财政预算，保障抗旱工作的正常开展。抗旱经费应当专款专用，严格审计监督。\n建立和完善与经济社会发展水平以及抗旱减灾要求相适应的政府投入、受益者合理承担和社会资助相结合的多元化资金筹措机制。\n第五条 县级以上人民政府水行政主管部门应当会同有关部门组织编制本行政区域抗旱规划，县级以上人民政府应急管理部门应当会同有关部门组织编制相关抗旱预案。抗旱规划和抗旱预案经批准后实施。\n易旱区抗旱规划和抗旱预案应当重点突出应急备用水源工程、抗旱灌溉骨干工程、农村小微型水源工程建设等内容。\n县级以上防汛抗旱指挥机构应当按照抗旱预案规定，定期开展抗旱检查，监督有关部门和单位限期排除风险隐患，落实抗旱保障措施。\n第六条 建立健全最严格水资源管理制度，实行用水总量控制和定额管理相结合制度。\n省人民政府应当依据全省主体功能区划的统筹安排，指导各地建立与区域水资源和水环境承载能力相协调的产业结构和布局，重点推进粮食主产区和易旱区水资源配置工程建设，并在抗旱项目建设、节水农机补贴、低耗水企业发展等方面予以政策扶持和资金倾斜。\n县级以上人民政府应当根据本行政区域用水总量控制指标和行业用水定额，鼓励易旱区调整农作物种植结构和面积、渔业及畜禽养殖种类和规模，限制易旱区高耗水工业项目建设和高耗水服务业发展。\n第七条 县级以上人民政府应当按照抗旱规划，加强农田水利基础设施、城乡供水工程、抗旱应急水源及其配套设施的建设与改造，重点推进供水水源地、水源连通、循环用水等工程建设，提高抗旱供水能力和水资源利用效率。\n水工程所有者、经营管理者应当对水工程进行定期检查、维修和养护，保证其正常运行。\n水工程设施采取承包、租赁、股份制、股份合作制等方式经营的，经营者应当服从县级以上人民政府水行政主管部门的用水调度。\n第八条 各级人民政府应当加强节约用水新技术、新工艺、新设备研发和推广，推进各行业节水技术改造，鼓励再生水循环使用。大力发展节水农业，推广节水耕作技术。开展工业节水示范工程，对重点大中型企业进行节水技术改造，抓好高耗水、高污染行业节水管理。加快城乡供水管网改造，降低管网漏失率。推广普及节水器具，引导社会公众尽快淘汰不符合节水标准的生活用水器具。\n县级以上人民政府应当将建设节水设施、污水处理设施、再生水利用设施纳入城乡规划，采取有效措施，加强监督管理，防治水环境恶化造成的水质性缺水和资源枯竭。\n第九条 县级以上防汛抗旱指挥机构应当组织建设旱情监测网络和抗旱信息系统，加强干旱灾害监测，实现成员单位之间信息共享。\n县级以上人民政府水行政主管部门和其他有关部门，应当及时向本级人民政府防汛抗旱指挥机构提供水情、雨情、墒情、农情和供水用水等信息。\n县级以上气象主管机构、水文机构应当掌握降雨、墒情实况，分别预测降雨趋势和河流、湖泊、水库水情趋势，并适时发布气象干旱信息和水文干旱信息。地勘机构应当对易旱区地下水源进行普查，为抗旱打井提供信息支持。\n各级防汛抗旱指挥机构应当根据水情、雨情、墒情、旱情、灾情等信息，按照抗旱预案的规定，及时启动相应级别的应急响应。\n第十条 发生干旱灾害，县级以上人民政府水行政主管部门应当按照应急水量调度预案制定实施方案，明确调度的水量、时间、路线及有关部门的职责，对本行政区域内的水量实行统一调度。\n省管河流、水库及其他蓄水工程的抗旱调水由省人民政府水行政主管部门统一调度。跨行政区域的抗旱调水，由涉及区域共同的上一级防汛抗旱指挥机构统一调度。\n有关人民政府、单位和个人必须服从统一调度和指挥，严格执行调度指令。\n第十一条 发生轻度干旱或中度干旱，县级以上防汛抗旱指挥机构各成员单位可以采取下列措施：\n（一）调度河流、湖泊、水库（水电站）、塘堰水量，实施河湖联调、湖库联调、河库联调，优化配置水资源；\n（二）启用应急备用水源或者应急打井、挖泉，兴建蓄水池、水窖；\n（三）组织向饮水严重困难地区送水；\n（四）临时组织筑坝截水、架机抽水、挖渠输水、管网连通补水；\n（五）实施人工增雨作业；\n（六）有利于缓解旱情的其他措施。\n跨行政区域调水、截水的，应当报经共同的上一级水行政主管部门批准；旱情解除后，临时性取水、截水设施按照谁设置谁负责的原则及时拆除，并恢复原貌；涉及其他有关部门的，应当及时通报。\n第十二条 发生严重干旱或者特大干旱，采取本条例第十一条规定的措施仍不足以应对时，县级以上人民政府可以采取与干旱可能造成的危害程度和范围相适应的下列措施：\n（一）压减生产供水指标；\n（二）限制或暂停高耗水行业用水；\n（三）限制或者暂停排放工业污水；\n（四）暂停建设项目新增取水许可审批；\n（五）缩小农业供水范围或者减少农业供水量；\n（六）限时或者限量供应城乡居民生活用水，保障基本生活用水。\n第十三条 建立健全以抗旱服务组织为主体，以村级抗旱小组、农民抗旱协会和抗旱专业户为纽带的抗旱服务体系，引导和扶持社会志愿者参与抗旱服务。\n县级以上人民政府应当整合民兵、预备役人员、农机作业人员、农技推广人员、防汛机动抢险队、农民专业合作社等农村基层服务力量，培育抗旱服务组织，根据抗旱服务组织公益性服务的开展情况，从政策、资金和技术等方面给予扶持。\n抗旱服务组织主要承担下列抗旱任务：\n（一）为临时性饮水困难地区送水；\n（二）流动抗旱灌溉；\n（三）采取临时措施解决抗旱应急水源；\n（四）抗旱设施、设备的管理和维护；\n（五）受防汛抗旱指挥机构委托管理抗旱储备物资；\n（六）抗旱先进技术的咨询和示范推广；\n（七）防汛抗旱指挥机构交办的其他抗旱任务。\n第十四条 鼓励社会组织和个人兴办抗旱服务组织，引导服务组织参与公益性抗旱服务，采取政府订购、定向委托、奖励补助、招投标等方式，为农民提供优质的抗旱服务。\n抗旱服务组织从事抗旱服务，其合法权益受法律保护。跨行政区域调动抗旱服务组织执行抗旱服务任务的，应当按照谁调动谁负担的原则，支付抗旱服务费用。\n第十五条 不同行政区域之间因抗旱发生的水事纠纷，应当协商处理；协商不成的，由上一级人民政府裁决。\n第十六条 县级以上防汛抗旱指挥机构应当根据当地干旱灾害发生的程度和频率，储备必要的抗旱物资，并根据需要统一调用。石油、电力等企业应当保障抗旱救灾所需的能源供应。\n建立抗旱电费补贴制度，具体补贴标准和范围由省人民政府另行制定。\n第十七条 鼓励和支持发展农业政策性保险，并逐步扩大覆盖范围和险种。\n积极探索和建立健全干旱灾害保险制度。鼓励和扶持农民和农业生产经营组织建立服务农业的互助合作保险组织。鼓励商业性保险公司开展干旱灾害保险业务。\n第十八条 国家机关及其工作人员在抗旱工作中滥用职权、玩忽职守、徇私舞弊的，由所在单位或者上级主管机关、监察机关责令改正；对负有责任的领导人员和直接责任人员依法给予处分；涉嫌犯罪的，依法追究刑事责任。\n第十九条 本条例自2014年4月1日起施行。","level":0}]},{"id":"h0166","sections":[{"name":"","text":"（2014年1月22日湖北省第十二届人民代表大会第二次会议通过 根据2018年11月19日湖北省第十三届人民代表大会常务委员会第六次会议《关于集中修改、废止省本级生态环境保护相关地方性法规的决定》第一次修正 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2022年3月31日湖北省第十三届人民代表大会常务委员会第三十次会议《关于集中修改涉及行政处罚内容的省本级地方性法规的决定》第三次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第四次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了防治水污染，保护和改善水环境，保障用水安全，推进生态文明建设，促进经济社会可持续发展，根据《中华人民共和国生态环境法典》、《中华人民共和国水法》等有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内的江河、湖泊、水库、运河、渠道、塘堰、水井等地表水体和地下水体的污染防治。\n第三条 水污染防治坚持预防为主、严防严治、综合治理、公众参与、损害担责的原则。\n第四条 县级以上人民政府应当对本行政区域内的水环境质量负责，将水污染防治工作纳入国民经济和社会发展规划，建立财政资金和社会资金相结合的多元化资金投入和保障机制，采取有效措施，改善水环境质量。\n第五条 实行水污染防治政府行政首长负责制、目标责任制和水环境损害责任终身追究制。\n县级以上人民政府应当每年向本级人民代表大会或者其常务委员会报告本行政区域的水污染防治工作。\n第六条 任何单位和个人都有保护水环境的义务，享有获取符合安全、卫生标准的生产生活用水的权利。\n县级以上人民政府及其有关部门对在水污染防治工作中做出显著成绩的单位和个人给予表彰和奖励。","level":1},{"name":"第二章 政府职责","text":"第七条 省人民政府生态环境主管部门会同发展改革、水行政等有关部门，根据国家流域水生态环境保护规划和本地实际情况，编制本省行政区域内跨县（市、区）江河、湖泊的流域水生态环境保护规划，报省人民政府批准，并报国务院生态环境主管部门备案。\n县级以上人民政府根据依法批准的流域水生态环境保护规划和实际需要，组织编制本行政区域的水生态环境保护规划，明确水生态环境保护目标，保证本行政区域水体符合规定的水环境质量标准。\n乡镇人民政府、街道办事处根据法律法规的规定和上级人民政府的要求，开展有关水污染防治工作。\n第八条 省人民政府应当根据国家水环境质量标准、水污染物排放标准以及本省主要流域、地区水环境现状和经济、技术条件，对国家水环境质量标准和国家水污染物排放标准中未作规定的项目，制定本省水污染物排放标准，严格控制水污染物排放。\n对环境敏感区、生态脆弱区、水环境容量不足的区域，省人民政府应当制定严于国家标准的地方水污染物排放标准，实行水污染物排放总量控制。\n第九条 县级以上人民政府应当建立健全基层生态环境监测预警体系和生态环境执法体系，加强水环境保护执法队伍建设，组织开展教育培训，规范执法行为，提高基层环境保护执法能力和执法水平。\n第十条 县级以上人民政府生态环境主管部门对水污染防治实施统一监督管理，依法履行下列职责：\n（一）贯彻实施有关水污染防治的法律法规、政策措施；\n（二）会同有关部门编制水生态环境保护规划；\n（三）组织实施地方水污染物排放标准；\n（四）会同有关部门编制饮用水水源保护区的划定方案；\n（五）编制与调整水功能区划，提出水体限制排污总量意见，审批新建、改建、扩建进入地表水体的排污口的设置，监测、分析水功能区的水质状况;\n（六）建立水环境监测网络，统一监测和定期发布水环境质量信息；\n（七）编制水污染突发事件应急预案，调查处理水污染事件；\n（八）开展水环境保护执法；\n（九）法律法规规定的其他职责。\n第十一条 县级以上人民政府对水污染防治负有监督管理职责的有关部门，依照规定履行下列职责：\n（一）水行政主管部门负责编制与调整水资源保护规划；\n（二）农业农村主管部门依法管理农药、化肥等农业投入品的使用，指导畜禽、水产养殖的水污染防治，推广测土配方施肥，发展生态农业，防治农业面源污染；\n（三）城乡建设相关主管部门负责城乡垃圾处理，城镇污水集中处理设施及配套管网规划、建设和运营管理；\n（四）卫生健康主管部门负责饮用水安全卫生的监督管理，监督医疗机构废水无害化处理，参与饮用水水源污染突发事故的预防及应急处置；\n（五）自然资源主管部门负责勘探、采矿、开采地下水等过程中的水污染防治监督管理；\n（六）交通运输主管部门对船舶污染水域的防治实施监督管理；\n（七）林业主管部门负责湿地、水源涵养林、防护林的建设管理以及生态修复；\n（八）发展改革、经济和信息化、公安、监察、文化和旅游、应急管理等其他主管部门根据各自职责对水污染防治实施监督管理。\n第十二条 县级以上人民政府应当建立水污染防治的部门协调机制，实行由政府负责人召集、生态环境主管部门承担日常工作、有关部门参加的水污染防治联席会议制度，研究解决水污染防治监督管理工作中的重大问题。\n第十三条 省人民政府应当根据主体功能区划和生态保护的目标以及区域间经济社会发展水平，建立健全对饮用水水源保护区和江河、湖泊、水库上游地区以及有关重点生态功能区的水环境生态保护补偿机制，推动地区间建立横向生态保护补偿机制。\n生态保护补偿的具体办法由省人民政府制定。\n第十四条 县级以上人民政府应当支持水污染防治科学技术研究开发和推广应用，鼓励水污染防治产业的发展，提高水环境保护的科学技术水平。\n第十五条 县级以上人民政府应当鼓励企业实行清洁生产，按照清洁生产的要求进行技术改造，提高水循环利用率，减少废水和水污染物排放量,对为减少水污染进行技术改造或者转产的企业，通过财政、金融、土地使用、能源供应、政府采购等措施予以鼓励和扶持。\n第十六条 各级人民政府及有关部门应当加强水环境保护的宣传教育，增强公众水环境保护意识，拓展公众参与水环境保护途径，引导公众参与水环境保护工作。","level":1},{"name":"第三章 水污染预防","text":"第十七条 省人民政府生态环境主管部门会同有关部门依据《中华人民共和国生态环境法典》、《中华人民共和国水法》等法律法规规定拟定水功能区划，报经批准和备案，并向社会公布。\n经批准的水功能区划是水资源保护与开发利用、水污染防治和水环境综合治理的重要依据，未经法定程序不得修改。\n第十八条 重点水污染物排放实行总量控制制度。本省重点水污染物控制名录由省人民政府确定并公告。\n排放水污染物的，不得超过国家或者地方规定的水污染物排放标准和重点水污染物排放总量控制指标。\n第十九条 编制区域或者流域开发建设规划，新建、改建、扩建直接或者间接向水体排放污染物的建设项目和其他水上设施，应当依法进行生态环境影响评价。\n有下列情形之一的，生态环境主管部门应当暂停审批新增重点水污染物排放总量的建设项目的生态环境影响报告书、生态环境影响报告表，发展改革、自然资源等主管部门不得批准其建设，建设单位不得开工建设：\n（一）超过重点水污染物排放总量控制指标或者未完成水环境质量改善目标的；\n（二）重点保护水域水质未达到标准的；\n（三）规划未依法进行生态环境影响评价的；\n（四）开发区、工业园区生态环境保护基础设施不符合规定要求的；\n（五）法律法规和国家、省规定的其他情形。\n第二十条 直接或者间接向水体排放工业废水、医疗污水的企业事业单位和其他生产经营者，城镇污水集中处理设施的运营单位，以及其他依照法律、行政法规规定实行排污许可管理的企业事业单位和其他生产经营者，应当依法向生态环境主管部门申请取得排污许可证。禁止违反排污许可证的规定排放水污染物。\n餐饮、洗浴、洗涤、洗车经营者不得直接向水体排放污水。\n禁止通过暗管、渗井、渗坑、灌注、裂隙、溶洞、篡改或者伪造监测数据、以逃避现场检查为目的的临时停产、非紧急情况下开启应急排放通道、不正常运行水污染防治设施等逃避监管的方式排放水污染物。\n第二十一条 省人民政府应当根据水环境保护需要，制定禁止新建、改建、扩建的严重污染水环境的生产项目名录，并公布实施。\n县级以上人民政府及其发展改革、经济和信息化、城乡建设、生态环境、商务等主管部门，应当根据主体功能区划和本行政区域的资源环境承载能力与水环境容量，合理规划工业布局，禁止引进高污染、高环境风险项目，限期淘汰严重污染水环境的工艺和设备，公布不符合产业政策的污染企业名单，限期整治或者关闭不符合产业政策的污染企业。\n第二十二条 各级人民政府应当将发展生态农业列入扶持范围，在申请生态环境保护、清洁生产等相关资金和污染治理贷款贴息补助等方面给予支持。\n农业农村主管部门应当指导农业生产者科学合理使用农药、化肥等农业投入品，防止过度使用造成水体污染。\n水产养殖应当采取措施避免水体污染。禁止在江河、湖泊、水库、运河、塘堰养殖珍珠；禁止在江河、湖泊、水库、运河围栏围网养殖、投肥（粪）养殖。\n第二十三条 县级以上人民政府应当根据水生态环境保护规划和区域环境承载能力，依法划定畜禽养殖的禁养区，并向社会公布。\n禁养区内已有的畜禽养殖场由县级以上人民政府限期拆除；造成养殖者经济损失的，依法予以补偿。\n第二十四条 畜禽规模养殖排放的水污染物应当符合国家和地方排放标准。\n畜禽规模养殖经营者应当按照生态环境保护的要求收集、贮存、利用或者处置养殖废弃物，并采取防渗漏、防溢流等措施，防止污染水体。\n县级以上人民政府应当对畜禽规模养殖废弃物的综合利用、污染物处理设施建设等给予扶持；鼓励、引导建设集中式畜禽养殖废弃物综合利用和无害化处理设施，引入市场化机制运营。\n动物尸体及其他废弃物应当按照规定进行无害化处理，禁止向水体丢弃。\n第二十五条 建立饮用水水源保护区制度。饮用水水源保护区分为一级保护区和二级保护区；必要时，可以在饮用水水源保护区外围划定一定的区域作为准保护区。\n饮用水水源保护区的划定、调整和饮用水水源的保护，按照国家有关规定执行。\n第二十六条 禁止在饮用水水源保护区内设置排污口。禁止在饮用水水源保护区内倾倒、堆放、贮存可能造成水体污染的固体废物和其他污染物。\n禁止在饮用水水源一级保护区内从事与供水作业或者保护水源无关的可能污染饮用水水体的活动。禁止在饮用水水源一级保护区内新建、改建、扩建与供水设施和保护水源无关的建设项目；已建成的与供水设施和保护水源无关的建设项目，由县级以上人民政府责令限期拆除或者关闭。\n禁止在饮用水水源二级保护区内新建、改建、扩建排放污染物的建设项目；已建成的排放污染物的建设项目，由县级以上人民政府责令限期拆除或者关闭。\n禁止在饮用水水源准保护区内新建、扩建对水体污染严重的建设项目；改建建设项目，不得增加排污量。\n第二十七条 县级以上人民政府应当加强饮用水水源地隔离防护设施建设，在饮用水水源保护区的边界设立明确的地理界标、护栏围网和明显的警示标志、宣传标语。\n禁止损毁、擅自移动前款规定的地理界标、护栏围网和警示标志。\n第二十八条 县级以上人民政府及其有关部门应当根据保护饮用水水源的实际需要，在与饮用水水源保护区相邻的公路和航道，采取必要的防护措施，防止运输危险化学物品的车辆和船舶发生事故污染饮用水水体。\n第二十九条 县级以上人民政府应当加强农村饮用水水源保护和治理，安排资金，支持农村饮用水工程建设，促进城镇供水管网向农村延伸；加强农村生活垃圾的收集和处理，防止污染水体。\n第三十条 生态环境主管部门应当加强饮用水水源地的水环境质量监测和监督检查，每月在本地主要媒体及时发布饮用水水源地水环境质量监测信息。\n第三十一条 县级以上人民政府应当组织生态环境、自然资源、水行政等有关部门开展地下水污染状况调查评价。\n省人民政府生态环境主管部门会同水行政、自然资源等有关部门，根据地下水水文地质结构、污染状况、水资源禀赋及其使用功能等因素，划定地下水污染防治重点区。\n第三十二条 县级以上人民政府应当组织生态环境、自然资源、水行政等有关部门建立完善地下水环境监测网络和信息共享平台，实现对人口密集区、工业园区、地下水重点污染源区和饮用水水源地等重点地区的有效监测。\n第三十三条 化工园区和化工项目、矿山开采区、尾矿库、危险废物处置场、垃圾填埋场等的运营、管理单位，应当采取防渗漏等措施，并建设地下水水质监测井进行监测，定期向生态环境主管部门提交地下水水质监测报告，防止地下水污染。\n第三十四条 进行地下勘探、采矿、工程降排水、地下空间开发利用、人工回灌补给地下水等可能干扰地下含水层的活动，应当采取防护性措施，防止污染地下水。\n从事地下热水资源开发利用或者使用水源热泵技术、地源热泵技术的，应当采取有效措施，防止污染地下水。生态环境、自然资源、水行政等主管部门应当依法加强监督管理和指导。\n大口井、废弃机井的产权单位应当采取合理的封井措施和工艺，防止污染地下水。","level":1},{"name":"第四章 水污染治理","text":"第三十五条 建设项目的水污染防治设施应当与主体工程同时设计、同时施工、同时投产使用，水污染防治设施应当符合经批准的生态环境影响报告书、生态环境影响报告表的要求。\n排污单位应当建立水污染防治设施运行管理制度，保证设施正常运转和水污染物稳定达标排放；不得擅自拆除、停运或者闲置污水处理设施。因检修等原因需要停运或者部分停运污水处理设施的，应当征得生态环境主管部门同意。\n第三十六条 排放重点水污染物的工业项目应当进入开发区、工业园区等区域。\n开发区、工业园区等区域应当统筹规划、建设污水集中处理设施，实行工业污水集中处理。排污单位对污水进行预处理后向污水集中处理设施排放的，应当符合集中处理设施的接纳标准。\n第三十七条 城镇污水应当集中处理。县级以上人民政府应当根据城镇排水与污水处理规划，按照雨污分流原则，明确排水与排污管网、泵站、污水处理厂等城镇污水集中处理设施和污泥无害化处理处置设施的规模、布局、建设时序和保障措施，并在省人民政府规定的期限内完成。\n城镇新区的开发和建设应当按照先规划后建设的原则，优先安排排水与污水集中处理设施建设；旧城改造应当统筹规划、建设排污管网等城镇污水集中处理设施。\n第三十八条 县级以上人民政府应当加大投入力度，加强城镇排水与排污管网建设，提高污水收集处理率，保障城镇排水与排污管网建设和污水集中处理设施运行经费，污水处理收费不足以支付运行成本的，应当提高财政补贴水平。\n省人民政府应当每年公布市（州）、县（市、区）人民政府城镇污水集中处理设施的建设、运营、达标排放情况；对按期完成城镇污水集中处理设施建设的，予以鼓励和扶持。\n第三十九条 建设垃圾堆放场、处理场和垃圾处理设施，应当采取防渗漏等处理措施。禁止在毗邻地表水体的区域和泄洪区内建设垃圾堆放场、处理场和垃圾处理设施；已经建设的，由当地人民政府责令限期搬迁。\n第四十条 医疗机构、学校、科研院所、企业等单位的实验室、检验室、化验室产生的废液应当按照规定单独收集，进行安全处置，禁止排入排水管道或者直接排入水体。\n生态环境主管部门应当按照有关规定加强对实验室、检验室、化验室废液处理的监督管理，为有关单位依法处理废液提供指导。\n第四十一条 各级人民政府应当加强农村生活污水处理设施建设，对未纳入城镇排污管网的村庄的生活污水进行治理，优先采用生态、低能耗、资源化的污水处理技术；对在饮用水水源保护区、河道两侧等重点区域的村庄，应当建设污水处理设施，并保证建设及运转资金。\n第四十二条 交通运输、生态环境、农业农村、文化和旅游等主管部门应当建立船舶水上污染防治执法联动机制，对船舶污染物实行从船上到岸上的全程监管。\n船舶应当按照国家和本省的规定配备相应的防污设备和器材，并持有合法有效的防治水域环境污染的证书与文书。禁止违反法律法规的规定向水体排放船舶水污染物。\n港口、码头、水上服务区和船舶修造厂应当配备足够的船舶污染物、废弃物的接收设施，纳入城镇管网或者农村环卫管理。\n在具有饮用水水源功能的湖泊、水库航行或者停泊的船舶，应当使用清洁能源；对使用汽油、柴油等燃料的船舶，采取限制措施，逐步淘汰。\n第四十三条 省人民政府生态环境主管部门应当会同水行政主管部门在江河、湖泊、水库、运河的市（州）、县（市、区）交界处设置地表水环境质量监测断面，确定监测断面水体适用的水环境质量标准，定期监测并发布监测信息。\n江河、湖泊、水库、运河上游人民政府必须采取措施保证出界断面水质达标。\n第四十四条 跨市（州）、县（市、区）的江河、湖泊、水库、运河实行交界断面水质考核制度。\n上级人民政府对考核不达标的市（州）、县（市、区）人民政府责令限期整改；有关人民政府必须采取有效措施削减水污染物排放量，直至出界断面水质达标，并向下游受影响地区人民政府作出补偿。\n具体考核和补偿办法由省人民政府制定。\n第四十五条 跨行政区域江河、湖泊、水库、运河所在地人民政府及其有关部门应当建立联席会商制度，相互配合，共享信息，协调跨行政区域水污染防治工作，预防和处置跨行政区域的水污染事件。\n跨行政区域的水污染纠纷，可以由有关人民政府协商解决，或者由其共同的上级人民政府协调解决。\n第四十六条 县级以上人民政府应当对水污染严重的流域、区域，划定重点监管区，确定重点监管的行业和企业，制定治理计划，限期整治。\n县级以上人民政府应当组织有关部门开展水生态环境调查，制定修复方案，采取截污治污、清淤疏浚、调水引流、河湖连通、湿地修复、生态保护带建设等措施，对水生态系统进行综合治理，保护和修复水生态。\n第四十七条 县级以上人民政府及其有关部门应当在地下水污染突出的固体废物堆存、垃圾填埋、矿山开采、石油化工行业生产、农业面源污染严重等区域开展地下水污染修复工作。\n第四十八条 对因清理水产养殖、畜禽养殖，实施退田还湖、退渔还湖以及生态移民等导致转产转业的，县级以上人民政府应当采取资金支持、技能培训、转移就业、社会保障等方式予以扶持。\n第四十九条 县级以上人民政府应当发展环保市场，通过招标、委托等方式向社会购买服务，吸引各类市场主体开展水污染防治技术评估、水污染防治设施建设与运营、水污染治理和水环境修复等环保服务业务，促进水污染防治的市场化。","level":1},{"name":"第五章 监督与应急","text":"第五十条 上级人民政府对下级人民政府的水污染防治工作目标实施年度考核，向社会公布考核办法和结果，考核结果作为对县级以上人民政府主要负责人考核评价的内容。\n各级人民政府未完成水污染防治工作目标的，由上一级人民政府或者监察机关对其主要负责人进行诫勉谈话或者通报批评；不能尽职尽责,使辖区内水环境质量恶化，造成严重后果或者恶劣影响的，主要负责人应当引咎辞职。\n第五十一条 县级以上人民代表大会常务委员会应当通过听取和审议专项工作报告、组织执法检查、开展专题询问、质询等方式，对本级人民政府水污染防治工作依法履行监督职责；必要时可以依法组织关于特定问题的调查。\n第五十二条 负有水污染防治监督管理职责的部门应当建立完善水污染防治的举报制度。\n负有水污染防治监督管理职责的部门应当公布举报污染水环境行为的联系方式，对属于本部门职责范围的举报事项，应当及时处理；对不属于本部门职责范围的，应当及时转交有权处理的部门，并告知举报人。有关部门应当为举报人保密，对举报属实的予以奖励。\n第五十三条 省人民政府应当规划建设污染源、水环境质量、水量和水位监测网络，实现生态环境、水行政、自然资源、卫生健康等有关部门之间监测数据的共享。\n第五十四条 实行排污许可管理的企业事业单位和其他生产经营者应当按照规定对其所排放的水污染物进行监测，建立管理台账，并保存原始监测记录和管理台账。生态环境主管部门应当对其进行监督监测。\n实行排污许可重点管理的企业事业单位和其他生产经营者应当按照规定安装水污染物排放自动计量、监测设备和视频监控装置，并与生态环境主管部门的监控设备联网，保证监测设备正常运行，保存原始监测记录。\n第五十五条 负有水污染防治监督管理职责的部门应当对排污口、水污染防治设施、固体废物贮存和处置设施以及有毒物质存放场所进行环境安全监督检查。发现重大水污染事故隐患的，被检查的单位和个人应当采取应对措施，防止水污染事故发生。\n第五十六条 负有水污染防治监督管理职责的部门进行监督检查，可以依法采取下列措施：\n（一）进入排污场所实施现场检查，向有关单位和人员了解情况，查阅、复制有关文件资料；\n（二）发现影响水环境安全的违法行为，责令当场纠正或者限期改正；\n（三）责令立即消除或者限期消除水污染事故隐患；\n（四）责令停止使用不符合法律法规规定或者国家标准、行业标准的设施、设备；\n（五）依法查封、扣押有关场所、船舶、设施、设备、工具、物品。\n省人民政府生态环境主管部门可以对重大水污染事故和实行排污许可管理的企业事业单位和其他生产经营者实行挂牌督办，派驻专员监督执行。\n第五十七条 各级人民政府及其有关部门和可能发生水污染事故的企业事业单位，应当制定水污染事故的应急预案，并定期进行演练，做好应急准备。\n从事有毒物质生产、使用、运输、贮存、处置的单位和个人，应当按照规定配备水污染事故应急设施。\n第五十八条 水环境质量因严重干旱等不可抗力达不到功能区水质要求时，县级以上人民政府可以根据水污染物排放情况，要求排污者采取限制生产、停止生产等措施，减少水污染物排放，保障功能区的水环境质量达标。\n第五十九条 饮用水水源受到污染，可能危及供水安全的，生态环境主管部门应当责令有关排污单位采取停止排放水污染物等措施，通报饮用水供水单位和供水、卫生健康、水行政等有关部门，并及时向社会发布饮用水水源污染状况、应急措施和恢复供水等信息。跨行政区域的，还应当通报有关县级以上人民政府。\n县级以上人民政府以及有条件的乡镇人民政府应当规划、建设备用水源，保障应急状态下的饮用水供应。\n第六十条 对跨省的江河、湖泊、水库，交界地生态环境主管部门应当加强水质监测，发现异常或者发生水污染事故的，及时采取应急措施，并向省人民政府生态环境主管部门报告。省人民政府生态环境主管部门接到报告后，应当及时与相关省（市）生态环境主管部门协调沟通。","level":1},{"name":"第六章 信息公开与公众参与","text":"第六十一条 县级以上人民政府及其负有水污染防治监督管理职责的部门，应当建立水污染防治信息公开制度，完善公众参与程序，为公众参与和监督水污染防治工作提供便利；依法公开水环境质量，水环境监测，水污染突发事件，与水环境保护有关的行政许可、行政处罚，水环境质量限期达标情况，水污染物排放限期治理情况等信息。\n县级以上人民政府应当及时公布严重污染水环境的企业。\n实行排污许可管理的企业事业单位和其他生产经营者应当按照规定向社会公开水污染物排放种类、排放浓度和排放量，以及水污染防治设施的建设运行情况、自行监测数据等水污染物排放信息，接受社会监督。\n第六十二条 生态环境主管部门应当会同有关部门建立排污者环保诚信档案，记载其遵守生态环境保护法律法规和承担生态环境保护社会责任等情况，并纳入社会征信体系。\n排污者的环保诚信档案应当向社会公开，并作为财政支持、政府采购、银行信贷、外贸出口、企业信用、上市融资的重要依据。\n第六十三条 任何单位和个人都可以按照规定向政府及其有关部门申请获取相关的水环境信息，有关部门应当依法予以答复。\n使用公开的水环境信息，不得损害国家利益、公共利益和他人的合法权益。\n第六十四条 任何单位和个人都应当遵守水环境保护法律法规，提高水环境保护意识，养成节约用水、保护水环境的绿色环保生产生活方式。\n第六十五条 任何单位和个人都有权对污染水环境的行为向生态环境主管部门或者其他有关部门检举和控告。\n发现人民政府及其负有水污染防治监督管理职责的部门不依法履行职责的，可以向其上级机关或者监察机关举报。\n第六十六条 对污染水环境损害社会公共利益的行为，法律规定的机关和有关组织可以向人民法院提起诉讼。\n因水环境污染受到损害的当事人向人民法院提起诉讼的，负有水污染防治监督管理职责的部门和有关社会团体在确定污染源、污染范围及污染造成的损失等事故调查方面为当事人提供支持。\n法律援助机构对水环境污染公益诉讼和因水污染受到损害请求赔偿的经济困难公民提供法律援助。\n第六十七条 单位和个人可以对水环境保护的决策活动提出意见和建议。\n除依法需要保密的情形外，规划编制、项目审批、生态环境影响评价等与公众水环境权益密切相关的事项，应当公开，并通过听证会、论证会、座谈会等形式向可能受影响的公众说明情况，充分征求意见。听证会的结果应当作为决策的参考。\n第六十八条 学校和其他教育机构应当开展水环境保护宣传教育。\n报刊、广播、电视、网络等媒体应当加强对水环境保护法律法规以及相关科学知识、信息的宣传报道，对污染水环境的违法行为和处理结果依法进行舆论监督。\n鼓励群众性自治组织、社会组织以及环境保护志愿者开展水污染防治法律法规和相关科学知识的宣传，依法参与水污染防治工作，保护水环境。","level":1},{"name":"第七章 法律责任","text":"第六十九条 违反本条例的行为，法律、行政法规已有行政处罚规定的，从其规定。\n因水环境污染受到损害的单位和个人，有权依法要求污染者承担停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失等民事侵权责任。\n污染水环境违法行为涉嫌犯罪的，负有水污染防治监督管理职责的部门应当及时将案件移送司法机关，依法追究刑事责任。\n第七十条 国家机关及其工作人员在水污染防治工作中，有下列情形之一的，对负有责任的领导人员和直接责任人员，由其主管机关或者监察机关依法给予处分：\n（一）应当暂停审批新增重点水污染物排放总量的建设项目的生态环境影响报告书、生态环境影响报告表而不暂停审批的；\n（二）不依法作出行政许可的；\n（三）发现违法行为或者接到对违法行为的举报后不予查处的；\n（四）造成水环境功能退化或者跨行政区域水污染事故的；\n（五）违反产业政策批准项目造成环境污染或者生态破坏的；\n（六）未依法履行信息公开义务的；\n（七）其他不依法履行职责的行为。\n国家机关工作人员在水污染防治工作中作出或者执行违法的决定、命令的，应当承担相应的法律责任。\n第七十一条 违反本条例规定，新建、改建、扩建直接或者间接向水体排放污染物的建设项目和其他水上设施，未依法进行生态环境影响评价，建设单位擅自开工建设的，由生态环境主管部门责令其停止建设，并可以责令恢复原状，报批、审核类型为生态环境影响报告书的，处20万元以上100万元以下罚款，情节严重的，处100万元以上1000万元以下罚款；报批、审核类型为生态环境影响报告表的，处10万元以上50万元以下罚款，情节严重的，处50万元以上500万元以下罚款。被责令停止建设或者恢复原状，拒不执行的，由公安机关对其直接负责的主管人员和其他直接责任人员依法予以处罚。\n第七十二条 餐饮、洗浴、洗涤、洗车经营者直接向水体排放污水的，由生态环境主管部门责令停止违法行为，限期改正，没收违法所得，并处2万元以上5万元以下罚款；情节严重的，责令停业，依法吊销许可证。\n第七十三条 违反本条例规定，通过暗管、渗井、渗坑、灌注、裂隙、溶洞、篡改或者伪造监测数据、以逃避现场检查为目的的临时停产、非紧急情况下开启应急排放通道、不正常运行水污染防治设施等逃避监管的方式排放水污染物的，由生态环境主管部门责令改正，处10万元以上100万元以下罚款，责令限制生产、停产整治，由公安机关对其直接负责的主管人员和其他直接责任人员依法予以处罚；情节严重的，吊销排污许可证，报经有批准权的人民政府批准，责令停业、关闭，并由公安机关对其直接负责的主管人员和其他直接责任人员依法予以处罚。\n第七十四条 在江河、湖泊、水库、运河、塘堰养殖珍珠的，由农业农村主管部门责令停止违法行为，没收违法所得，并处5万元以上10万元以下罚款。\n在江河、湖泊、水库、运河违法围栏围网养殖的，由农业农村主管部门责令限期拆除，没收违法所得；逾期不拆除的，由农业农村主管部门依法确定有关单位代为拆除，所需费用由违法行为人承担，并处1万元以上5万元以下罚款。\n在江河、湖泊、水库、运河投肥（粪）养殖的，由农业农村主管部门责令停止违法行为，采取补救措施，处500元以上1万元以下罚款。污染水体的，由生态环境主管部门责令停止违法行为，没收违法所得，并处5万元以上10万元以下罚款；情节严重的，处10万元以上30万元以下罚款，由发证机关吊销养殖证。\n第七十五条 在饮用水水源保护区内倾倒、堆放、贮存可能造成水体污染的固体废物和其他污染物的，由生态环境主管部门责令停止违法行为，限期清除，处5万元以上10万元以下罚款。\n第七十六条 违反本条例规定，损毁或者擅自移动饮用水水源保护区地理界标、护栏围网和警示标志的，由生态环境主管部门责令停止违法行为，恢复原状；情节严重的，处2000元以上1万元以下罚款。\n第七十七条 违反本条例规定，未按照规定对所排放的水污染物进行监测，未建立管理台账，或者未安装水污染物排放监测设备，未按照规定与生态环境主管部门的监控设备联网，未保证监测设备正常运行，或者未保存原始监测记录、管理台账的，由生态环境主管部门责令改正，处2万元以上20万元以下罚款；拒不改正的，可以责令限制生产、停产整治。\n第七十八条 违反本条例规定，排污单位发生事故或者其他突发性事件，造成或者可能造成水污染事故，未及时报告的，由生态环境主管部门或者其他负有水污染防治监督管理职责的部门责令改正，处5万元以上50万元以下罚款，对直接负责的主管人员和其他直接责任人员处1万元以上10万元以下罚款，并可以暂扣或者吊销相关任职资格许可。\n第七十九条 违反《中华人民共和国生态环境法典》以及本条例规定排放水污染物，受到罚款处罚，被责令改正的，依法作出处罚决定的部门应当组织复查，发现其继续实施该违法行为、拒不改正或者拒绝、阻挠复查的，可以自责令改正之日的次日起，按照原罚款数额按日连续处罚，并及时采取措施制止违法行为。","level":1},{"name":"第八章 附则","text":"第八十条 本条例自2014年7月1日起施行。2000年12月1日湖北省第九届人民代表大会常务委员会第二十一次会议通过的《湖北省实施<中华人民共和国水污染防治法>办法》同时废止。","level":1}]},{"id":"h0167","sections":[{"name":"","text":"（2012年3月9日长阳土家族自治县第八届人民代表大会第二次会议通过 2012年5月30日湖北省第十一届人民代表大会常务委员会第三十次会议批准）\n第一条 为保障老年人合法权益，发展老年事业，弘扬中华民族敬老、养老、助老的美德，根据《中华人民共和国老年人权益保障法》、《湖北省实施<中华人民共和国老年人权益保障法\n>办法》等法律、法规，结合自治县实际，制定本条例。\n第二条 自治县行政区域内的老年人权益保障适用本条例。\n本条例所称老年人是指六十周岁以上的公民。\n第三条 老年人依法享有的一切权利受法律保护，任何单位和个人不得侵犯。\n禁止歧视、侮辱、虐待或者遗弃老年人。\n第四条 自治县人民政府应当加强对老年事业和老年人权益保障工作的领导，将老年事业纳入国民经济和社会发展规划，所需经费纳入财政预算，并根据自治县财政收入状况和老年事业\n发展需要，逐步增加投入，使老年事业与经济社会协调发展。\n自治县从本行政区域内发行的福利彩票和体育彩票公益金中确定一定比例，用于发展老年事业。\n第五条 自治县人民政府设立老龄工作机构，履行下列职责：\n（一）负责全县老年事业发展和老年人权益保障工作；\n（二）研究制定老年事业发展规划和有关政策，协调有关部门组织实施；\n（三）组织宣传有关老年事业的法律法规，推动有关部门做好老年人权益保障工作；\n（四）协调有关部门加强对老龄工作的宏观指导和综合管理，组织开展有利于老年人身心健康的各种活动；\n（五）指导、督促和检查老龄工作。\n第六条 自治县人民政府有关部门和单位应当在各自职责范围内做好老年人权益保障工作。\n自治县的机关、社会团体、企事业组织应当依法做好本单位老年人权益保障工作；乡镇人民政府应当落实人员，具体负责老年人权益保障工作；居民委员会、村民委员会和依法设立的老\n年人组织，应当及时反映老年人的要求，维护老年人合法权益，为老年人服务。\n第七条 每年重阳节为自治县的敬老日。\n自治县广泛开展敬老、养老、助老宣传教育活动，树立尊重、关心、帮助老年人的社会风尚。\n青少年组织、学校和幼儿园应当对青少年和儿童进行敬老、养老、助老的道德教育和维护老年人合法权益的法制教育。\n第八条 自治县重视老年人的知识、技能和经验，尊重其优良品德，发挥其专长和作用，对老有所为、作出重大贡献的老年人给予奖励，并对促进老年事业发展、维护老年人合法权益和\n敬老、养老、助老成绩显著的组织、家庭和个人给予表彰。\n第九条 自治县建立健全养老保障体系，保障老年人的基本生活。\n自治县建立城乡居民社会养老保险制度。\n自治县人民政府有关部门应当按时足额支付老年人依法享有的养老金和各项补贴，不得拖欠、克扣和挪用。\n第十条 自治县有条件的农村集体经济组织，可以将未承包的集体所有的部分土地、山林、水面、滩涂等作为养老基地，收益用于发展老年人福利事业；企事业单位可以从经营收入中划\n拨一定比例的资金用于老年人福利事业。\n第十一条 城镇无劳动能力、无生活来源、无赡养人和扶养人的老年人（以下简称“三无”老年人），或者其赡养人和扶养人确无赡养或者扶养能力的，可以按照自愿原则纳入社会福利\n机构施行集中供养，或者依法纳入城镇居民最低生活保障体系。\n农村“三无”老年人，或者其赡养人和扶养人确无赡养或者扶养能力的，按规定纳入农村五保供养范围。\n第十二条 自治县将住房困难的城镇低收入老年人家庭优先纳入住房保障范围，对享受农村最低生活保障待遇的老年人的家庭危房改造给予援助。\n对国有土地上的房屋依法征收时，老年人选择产权调换的，有关部门应当提供用于产权调换的房屋。\n自治县人民政府有关部门在办理老年人自有产权房过户手续时，应当查验经老年人本人签名同意的书面材料。\n笫十三条 自治县建立健全城乡医疗保障制度，保障老年人的基本医疗需要。有关部门在制定城乡医疗保障办法时，应当按照国家和省有关规定对老年人给予照顾。\n第十四条 自治县加强和完善养老服务体系建设。加大对公益性老年福利院、敬老院、老年公寓、托老所和服务设施的投入，建立与本行政区域内“三无”老年人总数相适应的公办养老\n服务机构。\n第十五条 自治县大力发展居家养老服务，依托社区为老年人提供生活照料、康复护理和精神慰藉等服务。对“三无”老年人、五保对象，以及生活贫困的无生活自理能力的老年人给予\n居家养老服务补贴。\n第十六条 鼓励、支持和引导社会力量以多种形式、多种渠道参与发展自治县养老服务业。对社会组织和个人经批准兴办养老服务机构的，给予以下优惠：\n（一）对新建非营利性养老服务业建设项目用地，可以采用划拨方式优先供地；对新建营利性养老服务业建设项目用地，可以协议出让方式供地，其国有土地使用权出让金按国家有关规\n定执行。\n（二）对新建养老服务机构，经自治县人民政府批准，免交城市建设和房屋建设的行政事业性收费（证照费除外），免交水、电、燃气增容费。\n（三）养老服务机构用水、用电、天然气等费用，按照当地居民民用收费标准收取；使用有线（数字）电视、电话、宽带互联网及办理其他有关通信业务，执行居民住宅类服务收费标准\n。\n（四）养老服务机构提供的养老服务依法免缴营业税。养老服务机构自用的房产、土地，依法免缴房产税、城镇土地使用税；对非自用的房产和土地，依法缴纳房产税、城镇土地使用税\n确有困难的，可依法申请减免。\n（五）对建筑达标、设施完备、管理规范、业绩突出的老年福利院、敬老院、老年公寓、托老所和其他老年人服务场所，给予适当的财政补贴。\n（六）对企事业单位、社会团体和个人等社会力量，通过公益性社会团体或者县级以上人民政府及其部门向福利性、非营利性养老服务机构的捐赠，在缴纳企业所得税和个人所得税前，\n根据国家有关规定予以扣除。\n第十七条 自治县提倡义务为老年人服务。\n鼓励邻里互助，提倡邻里关心、帮助有困难的老年人。\n鼓励、支持社会志愿者为老年人服务。\n第十八条 自治县人民政府有关部门建立养老服务人员培训、管理体制，建立专职、兼职和志愿者相结合的服务老年人队伍。\n第十九条 老年人不承担各种社会公益事业集资。农村老年人不承担筹资、筹劳的义务。\n第二十条 赡养人必须对老年人履行赡养义务，在经济上供养老年人，保证老年人的正常生活需要。\n对患病、生活不能自理的老年人，赡养人必须履行护理、照料责任。赡养人护理确有困难而请人代为护理时，所需费用应当由赡养人承担。\n赡养人不得以放弃继承权、老年人婚姻关系的变化等理由，拒绝履行赡养义务。\n第二十一条 赡养人之间或者赡养人与老年人之间就赡养义务发生争议时，赡养人或者老年人所在的单位、居民委员会、村民委员会或者所在地的司法调解组织应当主持签订赡养协议并\n监督执行。\n赡养费的标准不得低于家庭成员平均生活费标准。\n第二十二条 赡养人应当在精神上慰藉老年人。与老年人分开居住的赡养人，应当经常看望和问候老年人。\n赡养人的配偶及家庭成员应当协助赡养人履行赡养义务。\n第二十三条 赡养人应当尊重老年人的生活习惯，尊重老年人夫妻共同生活的意愿，不得违背其意愿分开赡养。\n第二十四条 赡养人有义务耕种老年人承包的土地，照管老年人的林木和牲畜等，收益归老年人所有。\n赡养人无力耕种或者经营的，征得老年人同意，可以做出妥善安排，收益归老年人支配。\n赡养人及其家庭成员，不得要求老年人承担其力不能及的劳动。\n第二十五条 老年人有依法处分自有财产的权利。对有独立生活能力的成年子女提出的资金、物资及其他方面的要求，老年人有拒绝的权利。\n第二十六条 老年人婚姻自由受法律保护。\n老年人有权携带自有财产再婚；子女或者其他亲属不得干涉老年人离婚、再婚及婚后的生活；不得以老年人婚姻关系的变化为由，索取、隐匿、分割、损毁或者限制使用和处分老年人的\n合法财产；赡养人的赡养义务不因老年人的婚姻关系变化而消除。\n第二十七条 老年人有接受继续教育的权利。\n自治县人民政府及相关部门应当加强对老年人教育的统筹规划和教育设施建设。\n鼓励和支持社会力量兴办各类老年学校。\n第二十八条 自治县鼓励和支持老年人开展各种形式的文化、体育、娱乐活动。\n广播、电视和网站等媒体应当积极开展敬老、助老宣传，开办老年人喜闻乐见的专题或者专栏。\n居民委员会、村民委员会应当在社区、行政村建立老年人活动场所和相应的设施。\n第二十九条 凡户籍在自治县行政区域内的老年人，均可凭有效证件享受以下优待：\n（一）对年满八十周岁的，由自治县人民政府发给每人每月不低于二十元的敬老金；对年满九十周岁的，由自治县人民政府发给每人每月不低于一百元的敬老金；对年满一百周岁的，由\n自治县人民政府发给每人每月不低于四百元的敬老金。\n（二）医疗机构在老年人挂号、诊治、交费、取药和住院时，应当提供优先服务。七十周岁以上的老年人免收普通门诊挂号费；行动不便的，应当免费提供担架、推车、助步器和其他设\n备；社区医疗机构应当为本社区内的老年人建立健康档案，开展卫生保健活动；自治县人民政府卫生主管部门和老龄工作机构，每年应当为本地一百周岁以上老年人免费体检一次。\n（三）城区内公共交通工具应当设置老年人专座，六十五周岁以上的老年人可免费乘坐城区内公共交通工具。\n（四）老年人可凭有效证件免费乘坐公共轮渡。\n（五）公园、公共图书馆、博物馆、美术馆、科技馆、纪念馆、烈士纪念建筑物、名人故居、文化馆等公益性文化设施，应当免费向老年人开放。\n（六）收费园林、旅游景点等，对六十周岁以上七十周岁以下老年人实行半价优惠，对七十周岁以上老年人实行免费。\n（七）需要收费的公共体育设施管理单位，应当根据设施的功能、特点为老年人健身活动提供价格优惠服务。\n（八）单独居住的老年人安装燃气、有线（数字）电视的，凭有效证件和乡级人民政府出具的证明，给予安装费百分之三十的优惠。\n（九）收费公共厕所应当向老年人免费开放。\n（十）享受城镇居民最低生活保障待遇或者纳入农村五保供养范围的老年人去世，殡葬部门应当免除其火化、遗体运送、骨灰寄存三项基本费用，由自治县人民政府民政主管部门在每年\n年终核实统计，报自治县人民政府财政主管部门核准后予以补助。\n第三十条 自治县人民法院应当优先审理、执行老年人提出的赡养费、养老金、抚恤金、财产纠纷、遗弃、虐待和暴力干涉老年人婚姻等涉及老年人权益的诉讼，不得推诿、拖延。\n老年人因其合法权益受侵害提起诉讼交纳诉讼费确有困难的，可以缓交、减交或者免交；需要获得律师帮助，但无力支付律师费用的，自治县法律援助机构应当及时为其提供法律援助。\n第三十一条 对赡养人不履行赡养义务的，由赡养人所在单位或者居民委员会、村民委员会给予批评教育，责令改正；对情节严重的，应当支持、帮助老年人依法向人民法院提起诉讼。\n第三十二条 违反本条例规定，不履行保护老年人合法权益职责的单位和个人，由其上级主管部门给予批评教育，责令改正，或由其所在组织给予行政处分；构成犯罪的，依法追究刑事\n责任。\n第三十三条 本条例自2012年10月1日起施行。","level":0}]},{"id":"h0168","sections":[{"name":"","text":"（2014年9月25日湖北省第十二届人民代表大会常务委员会第十一次会议通过 根据2025年1月13日湖北省第十四届人民代表大会常务委员会第十五次会议《关于集中修改、废止部分省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了规范人体器官捐献行为，保障人体器官捐献人合法权益，倡导捐献人体器官挽救生命的人道主义精神，根据有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内人体器官捐献及其有关活动，适用本条例。\n本条例所称人体器官捐献，是指自愿、无偿提供具有特定生理功能的心脏、肺脏、肝脏、肾脏、胰腺或者小肠等人体器官的全部或者部分用于移植的活动。\n第三条 人体器官捐献是社会公益性事业。提倡和鼓励公民捐献人体器官，有关单位和个人对捐献人体器官的行为应当给予支持。\n第四条 人体器官捐献应当遵循自愿、无偿的原则。\n公民享有捐献或者不捐献其人体器官的权利。任何组织和个人不得强迫、欺骗或者利诱他人捐献人体器官；不得利用人体器官捐献牟取非法利益，不得以任何形式买卖或者变相买卖人体器官。\n第五条 县级以上人民政府应当加强对人体器官捐献工作的领导，建立和完善人体器官捐献组织机构及工作机制，并将人体器官捐献工作经费纳入财政预算，支持人体器官捐献事业发展。\n第六条 县级以上人民政府及其有关部门、红十字会、医疗机构以及广播、电视、报刊、网络等媒体，应当开展人体器官捐献公益性宣传，普及人体器官捐献知识，营造良好舆论环境和社会氛围，科学引导公众积极参与，推动人体器官捐献工作的开展。\n第七条 县级以上人民政府及其有关部门和红十字会应当对在人体器官捐献工作中做出突出成绩的单位和个人给予表彰和奖励。","level":1},{"name":"第二章 组织职责","text":"第八条 县级以上人民政府卫生健康主管部门负责本行政区域内人体器官捐献的管理和监督工作。\n公安、财政、民政、交通运输等有关部门在各自职责范围内，做好人体器官捐献的有关工作。\n第九条 红十字会依法参与、推动人体器官捐献工作，开展人体器官捐献的宣传动员、意愿登记、捐献见证、缅怀纪念、人道关怀等工作，加强人体器官捐献组织网络、协调员队伍的建设和管理。\n第十条 省红十字会负责人体器官捐献协调员队伍建设，加强人体器官捐献协调员的登记注册、培训和管理等工作，并对其开展业务予以指导和监督。\n人体器官捐献协调员在红十字会的工作人员和医疗机构的医务人员中选定。\n人体器官捐献协调员管理办法由省人民政府制定。\n第十一条 人体器官捐献协调员负责人体器官捐献的知识普及、宣传咨询、信息报送，与捐献人及其亲属沟通交流，协助办理捐献手续，见证捐献并参与捐献人的缅怀纪念活动。\n人体器官捐献协调员应当遵守职业道德和操作规程，掌握有关法律、医学等专业知识，具备良好的沟通协调能力，为捐献人以及捐献执行人提供专业规范、文明友善的服务。","level":1},{"name":"第三章 登记和捐献","text":"第十二条 红十字会是人体器官捐献的登记机构。\n人体器官捐献登记机构应当向社会公布其名称、地址、联系方式和工作时间，并为捐献人办理登记提供便利条件。\n省红十字会应当建立健全人体器官捐献登记系统，实现与国家人体器官捐献登记系统信息共享。\n第十三条 自愿捐献其人体器官的公民，应当具有完全民事行为能力，以书面形式表示捐献意愿，并办理捐献登记。\n公民生前未表示不同意捐献其人体器官的，该公民死亡后，其配偶、成年子女、父母以书面形式共同表示同意捐献，方可捐献该公民的人体器官。\n公民生前表示不同意捐献其人体器官的，任何组织和个人不得捐献该公民的人体器官。\n第十四条 登记机构应当主动告知志愿登记的公民有关人体器官捐献的程序与事项，并向志愿登记者出具人体器官捐献志愿登记凭证。\n第十五条 公民对已经表示捐献其人体器官的意愿，有权予以撤销。人体器官捐献志愿登记者可以通过登记信息系统查阅或者修改本人登记信息，随时有权变更或者撤销本人捐献意愿。\n第十六条 捐献人死亡后由其捐献执行人通过红十字会实施人体器官捐献，捐献的人体器官经国家人体器官分配与共享系统统一分配后，由具有临床移植资质的医疗机构实施移植手术。","level":1},{"name":"第四章 权益保障","text":"第十七条 捐献人的捐献意愿、捐献行为和人格尊严受社会尊重和法律保护。\n第十八条 人体器官捐献完成后，医疗机构应当在红十字会协助下将遗体送殡葬单位火化后妥善安葬；捐献人近亲属要求自行安葬的，应当尊重其意愿，并按照有关规定办理。\n民政部门应当免除捐献人的基本殡葬费用，并为殡葬事宜提供便利条件。\n第十九条 患者申请人体器官移植手术，其配偶、直系血亲或者三代以内旁系血亲曾经捐献遗体器官的，在同等条件下优先排序。\n第二十条 红十字会应当向捐献人亲属颁发人体器官捐献荣誉证书，建立人体器官捐献纪念设施、纪念网站，提供缅怀场所，组织开展悼念活动。\n第二十一条 省红十字会设立人体器官捐献救助基金，为生活困难的捐受双方家庭提供必要的人道救助。\n救助基金通过政府财政拨款、彩票公益金投入以及企业事业单位、社会团体、个人捐赠等途径募集。\n救助基金的使用和监督管理办法由省人民政府制定。\n第二十二条 从事人体器官捐献工作的单位和个人不得泄露或者不正当使用人体器官捐受双方的个人信息和资料。\n第二十三条 人体器官捐献协调员、医务人员依法开展人体器官捐献工作，其合法权益受法律保护。","level":1},{"name":"第五章 监督管理","text":"第二十四条 省人民政府卫生健康主管部门应当制定人体器官捐献有关管理制度和技术标准。\n县级以上人民政府卫生健康主管部门应当对人体器官捐献有关管理制度及标准执行等工作实施监督、检查。\n第二十五条 红十字会应当将人体器官捐献的登记信息、完成捐献信息和有关工作情况，定期报同级人民政府卫生健康主管部门备案。\n第二十六条 医疗机构应当严格执行潜在捐献人信息报送制度。禁止医务人员、人体器官捐献协调员私自处理和买卖潜在捐献人信息。\n第二十七条 医疗机构及其医务人员获取、移植人体器官，应当对人体器官捐献人和获取的人体器官进行医学检查，对接受人接受人体器官移植的风险进行评估，并采取措施降低风险。\n第二十八条 具备临床移植资质的医疗机构应当建立专门档案，完整记录人体器官获取、移植等情况，并在七个工作日内向省人民政府卫生健康主管部门和省红十字会报告。\n第二十九条 捐献器官的分配应当符合医疗需要，遵循公平、公正、公开的原则。\n任何组织和个人不得在国家人体器官分配与共享系统外擅自分配捐献的器官。\n第三十条 卫生健康主管部门和红十字会的有关人体器官捐献工作，应当接受社会监督。\n任何组织和个人都有权向卫生健康主管部门或者其他有关部门投诉、举报涉及人体器官捐献的违法行为；接到举报的有关部门应当依法核实、处理，并将处理结果告知举报人或者向社会公布。","level":1},{"name":"第六章 法律责任","text":"第三十一条 违反本条例，法律、行政法规有处罚规定的，从其规定。\n第三十二条 县级以上人民政府卫生健康主管部门、红十字会、医疗机构及其工作人员违反本条例规定，在人体器官捐献工作中牟取非法利益，或者有其他滥用职权、玩忽职守、徇私舞弊行为的，对直接负责的主管人员和其他直接责任人员依法给予处分；有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第三十三条 本条例自2014年12月1日起施行。","level":1}]},{"id":"h0169","sections":[{"name":"","text":"（2014年9月25日湖北省第十二届人民代表大会常务委员会第十一次会议通过 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第二次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了促进森林资源保护和可持续利用，改善生态环境，规范森林资源流转行为，保护流转双方合法权益，根据《中华人民共和国民法典》、《中华人民共和国生态环境法典》、《中华人民共和国森林法》、《中华人民共和国农村土地承包法》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内森林资源流转及其管理活动。\n第三条 本条例所称森林资源，是指森林、林木和林地。\n本条例所称林权是指森林、林木的所有权、使用权和林地使用权。\n本条例所称森林资源流转是指森林、林木的所有权人、使用权人或者林地的使用权人，不改变林地所有权性质和用途，依法将全部或者部分林权转移给他人的行为。\n转移林权的单位或者个人为流出方，接受林权的单位或者个人为流入方。\n第四条 森林资源流转应当有利于保护、培育和合理利用森林资源，依法保护流转双方合法权益，不得损害国家、集体、社会公共利益和公民、法人、其他组织的合法权益。\n森林资源流转应当遵循依法、自愿、有偿、平等、公开、诚信原则。\n第五条 县级以上人民政府应当培育林权流转市场，建立流转交易平台，健全流转制度，规范流转秩序，依法处理流转纠纷，提供高效便捷的公共服务。\n第六条 县级以上人民政府林业主管部门负责本行政区域内森林资源流转监督管理工作，组织开展森林资源调查、监测、评价和流转服务，指导、支持有关调解组织和仲裁机构依法开展流转纠纷调处工作，健全流转服务体系。\n县级以上人民政府其他有关部门按照职责分工，做好森林资源流转管理及服务工作。\n乡（镇）人民政府、村民委员会应当开展森林资源流转法制宣传教育，指导、监督流转双方保护和合理利用森林资源，依法调解流转纠纷，维护流转双方合法权益。","level":1},{"name":"第二章 流转范围和程序","text":"第七条 下列森林、林木、林地使用权可以依法转让，也可以依法作价入股或者作为合资、合作造林、经营林木的出资、合作条件，但不得将林地改为非林地：\n（一）用材林、经济林、薪炭林；\n（二）用材林、经济林、薪炭林的林地使用权；\n（三）用材林、经济林、薪炭林的采伐迹地、火烧迹地的林地使用权；\n（四）国务院规定的其他森林、林木和其他林地使用权。\n鼓励宜林荒山、荒沟、荒丘、荒滩依法流转，开展林业生产经营活动。\n生态公益林和其它法律、行政法规禁止流转以及权属不清的森林资源不得流转。\n第八条 县级以上人民政府林业主管部门应当加强生态公益林保护与管理，在生态公益林所在区域设立标牌，标明四至边界、面积、林权权利人、管护责任人、保护管理责任和要求、监管单位、监督举报电话等内容。\n县级以上人民政府林业主管部门应当将生态公益林范围及变化、保护管理及其质量效益等情况，及时向社会公开。\n第九条 森林资源流转可以采取转让、转包、出租、互换、入股或者其他合法方式进行。\n第十条 国有森林资源流转应当遵守国家关于国有森林资源流转的规定，按照管理权限，报经县级以上人民政府林业及其他相关主管部门批准，并将流转方案向社会公示不少于三十日，依法公开进行招标或者拍卖。\n集体统一经营的森林资源流转，应当将该森林资源基本情况、流转方式、最低保留价、收益分配方案等在本集体经济组织内公示不少于三十日，依法经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表同意。\n农村集体经济组织成员通过家庭承包取得的林权的流转，应当经配偶及其他家庭成员协商一致。采取转让方式流转的，应当经发包方同意；采取转包、出租、互换或者其他方式流转的，应当报发包方备案。\n合资经营、合作经营或者权属共有的森林资源流转，应当依法征得合资方、合作方或者权属共有方的同意。\n第十一条 森林资源流转的期限一般不得超过三十年，最长不得超过七十年；法律、行政法规另有规定的，从其规定。\n家庭承包经营的森林资源的流转期限不得超过承包期的剩余期限。\n流入方对森林资源进行再流转，流转合同有约定的，从其约定；没有约定的，应当征得原流出方同意。再流转期限不得超过上一次流转合同确定的剩余期限。","level":1},{"name":"第三章 流转合同","text":"第十二条 森林资源流转双方应当在协商一致的基础上依法签订书面合同，并接受林业主管部门的监督。森林资源流转合同应当包括以下主要内容：\n（一）流转双方的名称（姓名）、住所；\n（二）流转森林资源的权属性质；\n（三）流转森林资源的现状，包括地点、四至边界、面积（附地形图）、林种、树种、蓄积量或者株数等；\n（四）流转的起止日期；\n（五）流转森林资源的经营方向、林木采伐利用方式和造林责任；\n（六）森林资源再流转的条件和程序；\n（七）合同期满时地上附着物及相关设施的处置；\n（八）森林资源保有量的要求；\n（九）流转双方的权利和义务；\n（十）流转价款、付款方式和时限；\n（十一）违约责任；\n（十二）争议解决方式。\n第十三条 流出方应当依照合同约定向流入方转移林权，协助流入方依法申请林权登记，监督流入方依法保护和合理利用森林资源，发现违法行为立即报告林业主管部门。\n第十四条 流入方有权按照流转合同约定，依法自主开展林业生产经营活动。\n第十五条 流入方应当依法保护和合理利用森林资源，保持森林资源数量不减少，提高森林生态质量，并遵守下列规定：\n（一）依法采伐森林、林木；\n（二）按照规定时限完成造林任务，开展森林资源培育；\n（三）承担森林防火、林业有害生物防治等责任；\n（四）不得擅自在林地兴建建筑物、擅自改变林地用途；\n（五）不得从事毁林开垦、采石、采砂、采土以及其他毁坏林木和林地的行为。\n第十六条 流入方应当依法保护依托森林资源生存的珍贵、濒危和有益的或者具有重要经济、科学研究价值的野生动物，原生地天然生长的珍贵植物和原生地生长并具有重要经济、科学研究、文化价值的濒危、稀有植物以及古树、名木。","level":1},{"name":"第四章 流转监督管理与服务","text":"第十七条 县级以上人民政府林业主管部门应当依法对森林资源流转实行监督管理，监督检查流入方保护和合理利用森林资源情况，发现破坏林地、毁坏林木、不按照规定造林等违法行为的，依法予以处理。\n县级以上人民政府林业主管部门应当完善公众参与途径，为公众参与森林资源保护工作提供便利；健全举报制度，及时核实举报情况，依法处理，并适时反馈处理情况。\n第十八条 县级以上人民政府林业主管部门应当建立流转信息库，及时公布流转信息，指导和办理流转手续，为当事人提供业务咨询。\n流转当事人有权查询、复制与其流转相关的登记资料，林业主管部门应当提供便利，不得拒绝或者限制。\n第十九条 森林资源依法流转后，流转双方向不动产登记机构提出林权登记申请，不动产登记机构应当按照规定办理登记。\n第二十条 除法律、行政法规另有规定的外，国有和集体统一经营的森林资源流转，应当由具备国家规定相应资质的资产评估机构依法进行森林资源资产评估。森林资源资产评估结果有效期一年。\n森林资源拍卖、招标的最低保留价和最终交易价格，一般不得低于森林资源资产评估价值的百分之九十；确需低于评估价值百分之九十进行交易的，应当按照本条例第十条的规定执行。\n第二十一条 流转期间依法征收、征用和占用林地的，林权权利人有权依法获得补偿。\n征收、征用和占用林地，应当依法足额支付林地补偿费、安置补助费、地上附着物和林木补偿费等费用，安排被征林地人员的社会保障费用。\n第二十二条 森林资源流转发生争议，由当事人依法协商解决。协商不成的，可以按照自愿、平等的原则选择人民调解、行政调解的方法进行解决，也可以提起诉讼或者按照双方约定申请仲裁。\n涉及农村土地承包经营权的森林资源流转争议，当事人协商、调解不成的，可以向农村土地承包仲裁机构申请仲裁，也可以直接提起诉讼。\n协商、调解、仲裁、诉讼期间，双方当事人不得影响对方的正常生产经营，且不得采伐有争议的森林、林木。\n第二十三条 森林资源流转后，其森林、林木的采伐按照国家有关规定办理，采伐量纳入所在地的县（市、区）的年森林采伐限额。森林、林木采伐后，流入方应当于当年或者次年内完成更新造林，并通过造林质量验收。\n第二十四条 鼓励通过森林资源流转发展林业专业合作社、家庭林场、合作林场等林业专业合作组织，引进和培育龙头企业，促进林业产业化、规模化、市场化、集约化经营。\n第二十五条 县级以上人民政府应当按照规定落实林业补助、贷款贴息、森林保险补贴等扶持政策，支持流转双方依法开展林业生产经营活动，保护和合理利用森林资源。\n鼓励银行、保险等金融机构拓展林权抵押贷款、林农小额信用贷款、森林保险等业务，加大林业信贷投入和保障支持。","level":1},{"name":"第五章 法律责任","text":"第二十六条 违反本条例，法律、行政法规已有处罚规定的，从其规定。\n第二十七条 流入方未按照国家规定完成造林任务的，由县级以上人民政府林业主管部门责令限期完成造林任务；逾期未完成的，不予核发林木采伐许可证，可以处未完成造林任务所需费用二倍以下罚款；对负有责任的领导人员和直接责任人员，依法给予处分。\n第二十八条 流转期满时林木未达到规定森林资源保有量的，由县级以上人民政府林业主管部门对流入方处达到该保有量所需费用二倍以下罚款。\n第二十九条 流入方未履行森林防火责任的，由县级以上人民政府林业主管部门、应急管理部门按照职责分工责令改正，对单位处2万元以上10万元以下罚款，对个人处1千元以上1万元以下罚款；拒不改正的，对单位处5万元以上20万元以下罚款，对个人处2千元以上2万元以下罚款。\n第三十条 流入方在生产经营过程中擅自改变林地用途的，由县级以上人民政府林业主管部门责令限期恢复植被和林业生产条件，可以处恢复植被和林业生产条件所需费用三倍以下罚款；拒不恢复植被和林业生产条件，或者恢复植被和林业生产条件不符合国家有关规定的，由县级以上人民政府林业主管部门依法组织代为履行，代为履行所需费用由违法者承担。\n第三十一条 流入方进行开垦、采石、采砂、采土或者其他活动，造成林木毁坏的，由县级以上人民政府林业主管部门责令停止违法行为，限期补种毁坏株数一倍以上三倍以下的树木，可以处毁坏林木价值二倍以上五倍以下罚款；拒不补种树木，或者补种不符合国家有关规定的，由县级以上人民政府林业主管部门依法组织代为履行，代为履行所需费用由违法者承担。造成林地毁坏的，由县级以上人民政府林业主管部门责令停止违法行为，限期恢复植被和林业生产条件，可以处恢复植被和林业生产条件所需费用三倍以下罚款；拒不恢复植被和林业生产条件，或者恢复植被和林业生产条件不符合国家有关规定的，由县级以上人民政府林业主管部门依法组织代为履行，代为履行所需费用由违法者承担。\n第三十二条 提供虚假材料骗取林权登记的，由不动产登记机构撤销其登记；给他人造成损害的，依法承担赔偿责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第三十三条 资产评估机构及其工作人员在森林资源资产评估中弄虚作假、徇私舞弊的，其评估结果无效；造成流转当事人损失的，应当依法赔偿；造成严重后果的，由有关部门依法吊销其资质证书；构成犯罪的，依法追究刑事责任。\n第三十四条 国家工作人员在森林资源流转管理工作中收受贿赂、滥用职权、玩忽职守、徇私舞弊的，由所在单位或者上级主管机关、监察机关责令改正，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十五条 本条例所称生态公益林，是指生态区位重要、生态状况脆弱，对国土生态安全、生物多样性保护和经济社会可持续发展具有重要作用，以提供公益性、社会性产品或者服务为主要利用方向和目的，并按照有关规定划定为生态公益林的森林、林木和林地，包括防护林和特种用途林。\n第三十六条 本条例自2014年12月1日起施行。","level":1}]},{"id":"h0170","sections":[{"name":"","text":"（2015年1月15日湖北省第十二届人民代表大会常务委员会第十三次会议通过 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了保障和促进东湖国家自主创新示范区建设，充分发挥其示范和辐射带动作用，根据有关法律、行政法规，制定本条例。\n第二条 东湖国家自主创新示范区（以下简称示范区）包括武汉东湖新技术开发区规划建设区域和省人民政府、武汉市人民政府（以下简称省、市人民政府）委托武汉东湖新技术开发区管理的区域。\n第三条 示范区坚持创新驱动战略和开放先导战略，增强自主创新能力，提高开放合作水平，依法推进改革发展创新，建设成为改革开放先行区、创新驱动示范区、高端产业聚集区和依法治理引领区。\n第四条 示范区鼓励各类主体创新创业，支持有利于创新创业的体制机制先行先试，营造鼓励创新创业、宽容失败的发展氛围，增强市场活力和发展动力。","level":1},{"name":"第二章 管理体制","text":"第五条 省、市人民政府应当加强对示范区建设的组织领导，建立健全决策、协调机制，研究解决示范区建设中的重大事项和问题。\n省、市人民政府相关部门应当按照各自职责，推进示范区的建设和发展。\n第六条 武汉东湖新技术开发区管理委员会（以下简称管委会）根据本条例规定，行使市人民政府相应的行政管理权限，承担相应的法律责任。管委会依法履行以下职责：\n（一）组织编制、实施示范区国民经济和社会发展规划、国土空间规划、产业发展规划等；\n（二）负责示范区内发展改革、经济和信息化、教育、科技、民政、财政、人力资源和社会保障、生态环境保护、住房和城乡建设、交通运输、水务、商务、文化、卫生和计划生育、知识产权、市场监督管理、审计、国有资产、安全生产、体育、统计、外事侨务、人防、城市综合管理等工作；\n（三）依法对示范区的土地进行管理，并负责土地及地上建筑的征收和补偿工作；\n（四）负责审批、管理示范区内的投资项目；\n（五）为示范区各类主体创新创业提供政策支持和公共服务；\n（六）履行本条例以及省、市人民政府赋予的其他职责。\n第七条 管委会按照精简、统一、效能的原则，在省、市机构编制管理部门核定的机构总数内，自主设立、调整工作机构，并报省、市机构编制管理部门备案。\n除法律、行政法规规定外，省、市人民政府有关部门在示范区内不再设立派出机构。依法设立的派出机构应当接受管委会的组织协调。\n第八条 管委会在省、市机构编制管理部门核定的编制和员额总数内，建立健全以全员聘用制为主的人事制度，创新符合示范区实际的多种形式的选人用人机制、薪酬激励机制和人才交流机制。省、市人民政府及其有关部门应当支持示范区人才的交流和使用。\n第九条 示范区享受一级财政管理权限。示范区财政收支纳入市级预算管理，接受市人民代表大会及其常务委员会的审查和监督。\n省、市财政加大对示范区转移支付力度，由示范区统筹用于科技创新和产业发展。具体办法由省、市人民政府制定，并报同级人民代表大会常务委员会备案。\n第十条 管委会依法公布行政权力清单，推行行政许可权、行政处罚权和行政强制权相对集中行使，建立合作协调和联动工作机制，优化执法环境，提高行政效率。\n第十一条 改革行政审批制度，实现行政审批办事不出示范区。\n省、市人民政府有关部门实施的示范区范围内的行政审批事项，由管委会负责实施。具体审批事项由省、市人民政府确定并对外公布。\n法律、行政法规规定由省、市人民政府有关部门先行审核，再报国家有关部门审批的示范区范围内的事项，委托管委会负责审核。省、市人民政府有关部门提供程序上的便利和支持。\n第十二条 管委会对市场主体实行以事中、事后监管为主的动态监管，建立抽查和责任追溯制度，实施企业年度报告公示和企业经营异常名录管理。完善市场主体信用信息系统，依法对社会公开，推行守信激励和失信惩戒联动机制。\n第十三条 管委会建立完善政务信息公开制度，主动公开示范区优惠政策、管理事项、收费项目和标准、办事程序、服务承诺等信息。","level":1},{"name":"第三章 规划建设与产业发展","text":"第十四条 管委会根据《东湖国家自主创新示范区发展规划纲要》，组织编制国民经济和社会发展规划、国土空间规划，报经市人民政府批准后组织实施。\n管委会按照关联功能集中、产业集聚和土地集约利用的原则，制定产业发展规划，统筹产业布局，合理设置产业基地和专业园区，构建具有比较优势和核心竞争力的产业体系。\n第十五条 示范区依托“武汉·中国光谷”品牌，重点发展光电子信息、生物医药、新能源和新材料、节能环保、智能制造等战略性新兴产业，加快发展互联网、云计算、大数据、地球空间信息及应用服务以及科技服务、金融服务等现代服务业，建设国际先进水平的创新型产业集群。\n第十六条 示范区围绕产业发展要求，支持企业制定、实施创新发展战略，提升企业自主创新能力和市场竞争力，形成一批具有全球影响力的创新型企业和国际知名品牌。\n省、市人民政府支持管委会采取措施，引进国内外领先的核心技术、产业链关键企业和领军企业。\n第十七条 示范区建立最严格的生态环境保护、资源节约利用、生态环境损害赔偿和责任追究制度。完善生态保护红线、排污许可管理及总量控制、规划和建设项目生态环境影响评价等制度，引导企业节约资源、保护环境。\n示范区制定产业优先发展目录，支持低能耗、低排放企业发展，鼓励企业实施清洁生产、保护和改善环境。禁止发展高能耗、高污染和高环境风险的产业项目。\n第十八条 省、市人民政府以及管委会统筹示范区与周边地区基础设施、公共设施和其他配套设施的建设与管理，实施交通、管网综合同步建设，完善配套服务功能。\n统筹安排，合理、高效利用土地资源。建立土地利用审查机制和土地节约集约利用评价及动态监测机制。示范区内闲置或者擅自变更用途的国有土地，管委会根据国家有关规定予以处理，纳入土地储备范围。除国家另有规定外，示范区出让国有土地使用权的各项收入，应当作为示范区基础设施建设资金实行专项管理。","level":1},{"name":"第四章 科技创新","text":"第十九条 支持示范区内企业加大研发投入，建立研发机构，开展技术创新，培育自主品牌，创新产业组织模式，提高自主创新能力。\n省人民政府授权管委会负责对示范区内企业进行高新技术企业资格认定和复审，并按照国家有关规定申报备案。经认定的高新技术企业依法享受税收优惠。\n第二十条 支持高等院校、科研院所和企业按照市场化机制建立新型产业技术研究机构，完善科技成果转化、产业化体制机制。\n支持企业与高等院校、科研院所采取委托研发、技术许可、技术转让、技术入股以及共建研发机构等形式，开展产学研用合作。\n支持企业联合高等院校、科研院所和其他创新主体组建产业技术创新联盟。符合条件的产业技术创新联盟可以申请登记为法人。\n第二十一条 示范区设立专项资金，支持科技企业孵化器和加速器的建设和发展。\n鼓励企业、高等院校、科研院所及其他组织和个人设立各类创新创业孵化服务机构，为创新创业主体提供投融资、市场推广、加速成长等深度服务，搭建专业技术公共平台、中试基地等创新服务平台。\n第二十二条 示范区内高等院校、科研院所等事业单位的科技成果，可以自主处置，科技主管部门和资产管理部门不再审批和备案。\n高等院校、科研院所等事业单位应当与项目完成人约定项目所产生的科技成果的使用权、处置权及收益分配比例。科技成果形成后一年内未实施转化的，在所有权不变的前提下，项目完成人书面告知单位后，可以自主实施转化，转化收益中至少百分之七十归项目完成人所有。\n涉及国家安全、国家利益和重大社会公共利益的项目，按照有关法律、法规的规定执行。\n高等院校、科研院所在示范区转化科技成果的，按照实现的技术交易额给予一定比例奖励。\n第二十三条 示范区设立知识产权专项资金，鼓励和支持知识产权的创造、运用、保护和管理。鼓励建设知识产权联盟和专利池，实现知识产权合作。\n建设有区域特色的知识产权交易市场，支持知识产权服务机构开展知识产权咨询、代理、评估、质押融资和托管运营等服务。\n支持创新主体实施标准战略，主导或者参与制定地方标准、行业标准、国家标准和国际标准，成立标准联盟，开展与国际、国内标准化组织的战略合作，推进技术标准的产业化应用。\n第二十四条 省、市人民政府拨付的科技专项资金，采取前资助、后补助、股权投资、贷款贴息等方式，支持示范区开展创新能力建设、科技研发与成果转化、产学研协同创新、创新创业平台建设。\n支持示范区内企业、高等院校、科研院所、产业技术创新联盟以及个人，按照国家规定申报和承担国内外重大科技项目。管委会对重大专项项目按照相应比例予以配套资金支持。\n示范区内的企业、高等院校、科研院所承担财政性资金资助的科技项目，按照国家规定的比例在项目经费中列支间接费用，用于支付项目实施过程中发生的管理、协调、监督、激励等费用。\n第二十五条 示范区建立健全实验室、大型科学仪器设备、科技文献、科技数据等科技资源开放共享和激励机制，引导各类科技资源面向社会提供服务。\n财政资金投资或者资助的科技资源开放共享所获收入自行支配。自有资金形成的科技资源面向社会提供服务的，管委会按照规定给予奖励。\n第二十六条 省、市人民政府及其财政、科技部门应当将示范区内符合条件的新技术、新产品、新服务纳入政府采购目录。\n省、市人民政府和管委会通过政府采购，采取首购、订购、实施首台（套）重大技术装备试验和示范项目等措施，推广应用示范区新技术、新产品、新服务。","level":1},{"name":"第五章 金融服务","text":"第二十七条 示范区引进国内外金融机构，设立各类要素交易所，构建多层次多元化的投融资体系和金融市场，建设资本特区，为示范区发展提供金融服务。\n省、市人民政府为示范区引进金融机构提供政策支持。\n第二十八条 鼓励国内外市场主体在示范区设立风险投资机构，开展创新创业风险投资活动。\n示范区设立创业投资和产业发展引导资金，采取阶段参股、跟进投资、风险补助等多种方式，引导和发展创业投资。\n支持在示范区内设立私募股权基金、证券机构、保险机构、信托机构及其分支机构，开展股权投资、并购等相关业务。\n鼓励各类资本发起设立科技投融资平台，参与示范区的创业投资。\n第二十九条 支持示范区内企业在国内外证券市场公开发行股票、债券。\n支持示范区内企业通过发行中小企业集合债券、集合票据、私募券、短期融资券等方式进行融资。\n支持示范区内企业在国家中小企业股份转让系统和区域股权交易市场挂牌，开展股份转让、融资和并购。\n示范区为企业利用多层次资本市场融资，提供相关辅导和服务。\n第三十条 鼓励银行金融机构在示范区设立分支机构，开展股权质押和知识产权质押贷款等科技金融服务。\n发展金融信托、期货投资、融资租赁、融资担保、小额贷款、商业保理等各类金融机构，为企业创新创业提供金融服务。\n鼓励保险机构创新保险产品及服务，分散创新创业风险。\n鼓励各类金融机构开展产品创新和跨业合作，支持民营资本进入金融领域，探索发展互联网金融等新型金融业态和服务，推动科技金融创新。\n第三十一条 建立示范区科技型中小企业融资风险担保补偿机制，设立专项资金，为金融机构开展针对示范区内科技型中小企业的信用贷款、信用保险、股权质押、知识产权质押、创业投资等业务提供风险担保补偿。\n管委会应当加强与金融监管部门、金融机构和企业的沟通协调，建立金融业务风险防范联动机制。","level":1},{"name":"第六章 人才支撑","text":"第三十二条 管委会制定创新创业型人才发展规划，建立人才信息平台，健全人才培养、引进、使用、评价、激励和服务机制，建设人才特区。\n省、市人民政府和管委会设立专项资金，对示范区引进高端领军人才和高层次人才、团队及其创新创业项目予以支持。\n政府有关部门和管委会及时解决引进人才及其家属的户籍、医疗、教育、住房和出入境等问题，优先办理有关手续，并在项目申报、科研条件保障等方面提供便利。\n第三十三条 省、市人民政府有关部门和管委会建立健全高等院校、科研院所与企业的人才双向交流机制。\n鼓励用人单位采取委托项目、合作研究、兼职等方式引进和使用科研人员。鼓励科研人员在示范区创办科技型企业，转化科技成果；将科技成果转化作为重要指标纳入科研人员考核评价体系；创新创业贡献杰出的科研人员，可以破格评定相应专业技术职称。\n示范区采取设立专项资金、建立创业基地、举办创新创业竞赛等形式，支持科研人员和大学生创新创业。支持各类创新创业孵化机构设立科研人员、大学生创业专区，为其创业提供指导和服务。\n第三十四条 示范区设立股权激励代持专项资金，支持企业、高等院校、科研院所采取科技成果入（折）股、股权奖励、科技成果收益分成等方式，对作出贡献的科研人员和管理人员给予股权和分红权激励。\n示范区企业探索建立股票期权激励制度，激励企业核心技术人员、高层管理人员创新创业。企业核心技术人员、高层管理人员达成业绩、服务年限等企业设定条件后，可以按照约定价格购入对应权益。\n第三十五条 支持国内外知名高等院校、科研院所、高端研究咨询机构在示范区合作建立人才培养机构，探索创新国际教育、人才合作模式，建设国际教育、人才合作试验区。\n支持企业与高等院校、科研院所、职业院校或者培训机构联合建立实习、实训基地，培养专业技术人才和技能型人才。","level":1},{"name":"第七章 开放合作","text":"第三十六条 示范区加快推进贸易投资自由化、便利化，搭建国际化发展平台，加强国际交流与合作，建立与国际贸易投资通行规则相衔接的制度体系和监管服务模式，培育国际化、市场化、法治化的营商环境，推动建设内陆自由贸易区。\n示范区建设各类投资者平等准入的市场环境，推进科技服务、金融服务、商贸服务、航运服务、文化服务和社会服务等领域扩大开放。\n示范区支持法律、信用、信息咨询、资产评估、审计、会计、国际标准认证等服务组织在区内设立机构、开展业务，为示范区发展和对外开放提供服务。\n第三十七条 示范区探索外商投资准入前国民待遇加负面清单管理模式。市场准入负面清单按照国家有关规定执行。\n支持示范区企业建立境外研发、生产基地和销售网络，开展对外投资。示范区对区内企业境外投资项目一般实行备案管理，按照国家规定对境外投资项目保留核准的除外。\n支持示范区企业境外参展和产品国际认证、申请境外专利、注册境外商标、境外投（议）标、收购或者许可实施境外先进专利技术、许可使用境外商标。\n第三十八条 示范区依法实行注册资本认缴登记制和工商先照后证登记制。\n市场主体取得营业执照，即可从事一般生产经营活动。从事需要许可的生产经营活动的，除法律、法规规定需要前置审批事项外，可以在取得营业执照后，再向主管部门申请办理。\n示范区实施工商营业执照、组织机构代码、税务登记证以及外商投资企业批准证书联办登记制度，对企业设立、变更、投资实行“一表申请、一口受理、一章审批”。\n第三十九条 示范区依托特色产业，发展高技术含量的出口贸易加工制造业以及离岸贸易、国际贸易结算、国际大宗商品交易、跨境电子商务、保税展示交易等开放经济业态。\n鼓励跨国公司在示范区内建立区域总部和研发中心，建立整合贸易、物流、结算等功能的营运中心。\n第四十条 发挥武汉东湖综合保税区功能，推进示范区建设开放特区。综合保税区与境外之间的管理为“一线”管理，综合保税区与境内区外之间的管理为“二线”管理。按照“一线放开、二线管住、区内自由”原则，在综合保税区建立与国际贸易发展需要相适应的监管模式。\n加强海关、检验检疫、税务、外汇等部门的协作，推行统一高效的口岸监管服务，实行海关、检验检疫一次申报、一次查验、一次放行，实现通关便利化。\n推进武汉东湖综合保税区对接国内外机场、公路、铁路、港口等综合口岸资源，建设示范区开放口岸门户。\n第四十一条 示范区应当根据区内科技创新和产业发展需要，组织开展与其他国家和地区科技园区、跨国公司的交流合作，推动人才交流、协同创新和产业合作。\n鼓励支持示范区与其他区域、城市建立战略合作关系，共建产业园区，加强产业分工和协作，推动区域科技创新和产业优化升级。","level":1},{"name":"第八章 法治环境","text":"第四十二条 管委会应当健全依法决策机制，规范行政决策和执行程序，建立重大决策公众参与、专家论证、风险评估、合法性审查、集体讨论决定和责任追究制度。\n设立示范区咨询委员会，为示范区拟订改革发展方案和实施重大决策提供咨询意见。\n第四十三条 示范区加强知识产权侵权预警和风险防范工作，健全知识产权侵权举报投诉、维权援助、纠纷调处机制，增强知识产权保护能力和水平。\n第四十四条 在示范区设立的仲裁机构应当依据法律、法规并借鉴国际民商事仲裁惯例，创新和完善仲裁规则，提高民商事纠纷仲裁的国际化程度，提供独立、公正、专业、高效的仲裁服务。\n示范区内的行业协会、商会以及民商事纠纷专业调解机构等可以参与示范区民商事纠纷调解。\n第四十五条 公民、法人或者其他组织对管委会制定的规范性文件有异议的，可以提请市人民政府进行审查。\n公民、法人或者其他组织不服管委会作出的行政行为，可以依法向市人民政府申请行政复议，或者依法提起行政诉讼。\n第四十六条 对不适应示范区经济社会发展的地方性法规、地方政府规章和其他规范性文件，制定主体就其在示范区的适用作出相应决定。\n第四十七条 示范区进行的创新活动，未能实现预期效果，但同时符合以下情形的，免予追究相关人员的责任：\n（一）创新方案的制定和实施不违反法律、法规规定；\n（二）相关人员履行了勤勉尽责义务；\n（三）未非法谋取私利，未恶意串通损害公共利益和他人合法权益。","level":1},{"name":"第九章 附则","text":"第四十八条 市人民代表大会及其常务委员会依据法律、行政法规和本条例，可以就示范区有关事项制定地方性法规，报省人民代表大会常务委员会批准后施行。\n经省、市人民政府批准的共建园区，可以参照施行本条例有关促进创新创业的政策措施。\n第四十九条 本条例自2015年3月1日起施行。","level":1}]},{"id":"h0171","sections":[{"name":"","text":"（2015年5月28日湖北省第十二届人民代表大会常务委员会第十五次会议通过 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了规范公共资源招标投标活动，加强公共资源招标投标监督管理，维护公共资源招标投标市场秩序，建立统一开放、竞争有序的公共资源招标投标市场体系，根据《中华人民共和国招标投标法》、《中华人民共和国政府采购法》等法律和行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内公共资源招标投标活动的监督管理。\n本条例所称公共资源招标投标是指使用国有资金的项目、国家融资的项目、国际组织或者外国政府贷款及援助资金的项目和其他涉及公共安全、公共利益的项目的招标投标活动。\n前款所列项目，依法必须进行招标投标的，应当列入公共资源招标投标目录。\n第三条 公共资源招标投标监督管理实行综合监督管理与部门监督管理相结合、行政监督与招标投标交易相分离的监督管理体制，统一交易规则，统一交易平台，统一服务标准，统一信息公开。\n第四条 县级以上人民政府公共资源交易管理委员会负责本行政区域内公共资源招标投标活动的指导、协调；公共资源交易综合监督管理机构（简称综合监督管理机构）作为管理委员会办公室，负责具体工作。\n县级以上人民政府综合监督管理机构履行下列职责：\n（一）依法对进入公共资源交易中心的招标投标活动实施综合监督管理；\n（二）制定公共资源招标投标交易规则、管理制度和工作流程；\n（三）协调处理公共资源招标投标活动中的争议和矛盾，依法查处公共资源招标投标活动中的违法行为；\n（四）建立和管理公共资源综合评标专家库，建立公共资源招标投标信用管理体系；\n（五）建立联动执法工作制度，协调招标投标执法工作，组织开展监督检查活动；\n（六）推进招标投标信息化工作；\n（七）法律法规规定的其他职责。\n县级以上人民政府发展改革、经济信息、财政、自然资源、住房和城乡建设、交通运输、水利、商务、国有资产监督管理等有关部门（简称有关行政监督部门），依法在各自职责范围内对公共资源招标投标活动实施监督管理。\n监察机关依法对公共资源招标投标活动有关监察对象实施监察。\n第五条 县级以上人民政府设立的公共资源交易中心，是为公共资源招标投标活动提供服务的交易场所，不得行使或者代行行政审批权，不得从事招标代理等中介服务。\n县级以上人民政府应当推进电子招标投标平台建设，利用信息网络开展电子招标投标。\n第六条 综合监督管理机构和有关行政监督部门应当建立和完善社会监督机制，主动接受社会监督。\n任何单位和个人有权对公共资源招标投标活动中的违法行为进行检举和控告，有监督管理职责的部门应当依法及时处理。\n新闻媒体应当加强对公共资源招标投标活动的舆论监督。","level":1},{"name":"第二章 目录和程序","text":"第七条 省人民政府应当制定进入公共资源交易中心进行交易的公共资源招标投标目录，并公布实施。\n公共资源招标投标目录制定、调整，涉及重大公共利益的，应当公开征求意见并组织论证或者听证。\n第八条 列入公共资源招标投标目录的项目应当按照分级管理的原则在公共资源交易中心进行交易，接受监督管理，禁止任何形式的场外交易。\n未列入公共资源招标投标目录的项目，招标人可以自愿进入公共资源交易中心进行交易，并接受监督管理。\n公共资源交易中心不以营利为目的，不得收取交易费用，业务经费纳入本级财政预算；确需收费的，应当报价格主管部门按照补偿运营成本原则核定收费项目和标准。\n第九条 县级以上人民政府应当整合公共资源交易平台，建立由制度规则、信息系统、运行机制和必要场所构成的公共资源交易平台，为公共资源招标投标活动提供交易保障、信息服务和监督支撑。\n县级以上人民政府综合监督管理机构应当建立公共资源招标投标交易、服务、监督信息系统，整合和共享市场信息、信用信息、监督信息、专家资源信息等，实现公共资源招标投标全流程电子化。\n第十条 招标项目的审批、核准部门应当在项目审批、核准之日起十日内，将项目审批、核准确定的招标范围、招标方式、招标组织形式公示。\n第十一条 项目具备法定招标条件的，招标人应当持项目审批、核准文件等材料到公共资源交易中心办理招标登记手续。\n对委托招标项目，招标代理机构还应当提供委托合同、招标代理资质等证明材料。\n第十二条 招标人采用资格预审办法对潜在投标人进行资格审查的，应当编制资格预审文件、发布资格预审公告。\n第十三条 资格预审公告、招标公告应当在国家规定的媒体和省综合监督管理机构建立的招标投标公共服务平台上发布。招标人发布的招标信息应当一致。\n第十四条 招标人应当在评标前二十四小时内从专家库中随机抽取资格预审专家或者评标专家。因特殊情况需要提前抽取的，应当经综合监督管理机构同意。评标专家的抽取信息应当保密。\n第十五条 参与招标投标活动的当事人应当遵守公共资源交易中心开标、评标现场工作规程，严格按照法律、法规和招标文件规定的程序开展开标、评标活动。\n公共资源交易中心应当按照规定将招标投标资料和现场监控音像资料及文字记录整理、归档、保存，提供查询服务，为综合监督管理机构和有关行政监督部门实施监督提供条件。\n第十六条 招标人应当自收到评标报告之日起三日内，在公共服务平台公示中标候选人名称及排序、投标报价、资质情况、质量目标、履约期限、项目经理情况、业绩情况等信息，公示期不得少于三日。\n评标委员会否决所有投标的，招标人应当在公共服务平台上公示。\n第十七条 招标人应当依法确定中标人。\n特殊工程招标投标项目，经省人民政府批准，招标人可以委托评标委员会从其推荐的合格中标候选人中，以公开透明、随机产生的方式确定中标人。\n第十八条 招标人和中标人应当自中标通知书发出之日起三十日内订立书面合同，合同的标的、价款、质量、履约期限等主要条款应当与招标文件和中标人的投标文件一致，不得另行签订背离合同实质性内容的其他协议。","level":1},{"name":"第三章 交易行为监管","text":"第十九条 招标人不得有下列行为：\n（一）采取化整为零或者以其他方式规避招标；\n（二）以不合理的条件排斥、歧视潜在投标人；\n（三）擅自中止、终止招标；\n（四）拒绝签订合同或者提出额外附加条件；\n（五）与投标人串通；\n（六）违反法律、法规的其他行为。\n第二十条 投标人不得有下列行为：\n（一）以他人名义、借用资质投标或者以其他方式弄虚作假骗取中标；\n（二）串通或者通过行贿等违法手段谋取中标；\n（三）捏造事实、伪造材料，或者以非法手段获取证明材料进行投诉；\n（四）拒绝签订合同或者提出额外附加条件；\n（五）违反法律、法规的其他行为。\n第二十一条 招标代理机构不得有下列行为：\n（一）借用他人资质或者超出资质范围从事招标代理业务；\n（二）与招标人、投标人串通损害国家利益、社会公共利益或者他人合法权益；\n（三）在代理过程中接受贿赂或者获取其他不正当利益；\n（四）泄露应当保密的信息以及隐匿、销毁应当保存的文件资料或者伪造、变造文件资料；\n（五）违反法律、法规的其他行为。\n第二十二条 资格审查委员会、评标委员会成员不得有下列行为：\n（一）向招标人征询确定中标人的意向；\n（二）接受单位、个人提出的倾向性意见或者排斥特定投标人的要求；\n（三）接受贿赂或者获取其他不正当利益；\n（四）玩忽职守等渎职行为；\n（五）违反法律、法规的其他行为。\n第二十三条 综合监督管理机构和有关行政监督部门应当建立完善举报受理和投诉处理机制，向社会公布投诉的途径和方式。\n综合监督管理机构负责协调、监督处理进入公共资源交易中心项目招标投标活动的投诉。\n投标人或者其他利害关系人认为在公共资源交易中心进行的招标投标活动不符合法律、法规规定的，可以向综合监督管理机构或者有关行政监督部门投诉。投诉应当有明确的诉求和必要的证明材料。\n综合监督管理机构或者有关行政监督部门收到投诉后，应当自收到投诉之日起三日内作出是否受理的决定；对于不属于本部门职责范围的，应当移送有管辖权的机关处理，并告知投诉人；属于本部门职责范围的，自受理投诉之日起三十日内作出书面处理答复。需要检验、检测、鉴定、专家评审的，所需时间不计算在内。\n第二十四条 综合监督管理机构和有关行政监督部门处理投诉，有权查阅、复制有关文件、资料，调查有关情况，相关单位和人员应当予以配合。必要时，可以责令暂停招标投标活动。\n第二十五条 综合监督管理机构和有关行政监督部门应当加强对公共资源招标投标违法行为的监督检查，发现问题及时查处，并互通情况。\n有关行政监督部门应当加强对公共资源招标投标履约行为的监督检查，发现问题及时查处，并将结果通报综合监督管理机构。","level":1},{"name":"第四章 专家和专家库","text":"第二十六条 省综合监督管理机构应当建立跨行业、跨地区的省综合评标专家库，实现评标专家资源共享。省有关行政监督部门和市（州）、县综合监督管理机构协助建立、管理专家库。\n评标专家实行分类管理，专业分类应当符合国家规定。\n第二十七条 实行评标专家资格管理制度，符合国家有关评标专家条件的人员，由个人或者单位向综合监督管理机构或者有关行政监督部门提出书面申请或者推荐，并提供有关证明材料。\n综合监督管理机构或者有关行政监督部门收到申请或者推荐后，应当组织对申请人或者被推荐人进行评审，并在评审后三十日内回复。对于符合条件的，确认其评标专家资格，纳入省综合评标专家库管理。\n综合监督管理机构会同有关行政监督部门开展评标专家的培训。\n第二十八条 省综合监督管理机构应当制定和完善省综合评标专家库建设管理办法及其配套制度，健全评标专家准入、考评、退出机制，实行定期更新和动态管理。\n评标专家应当依法履职，公正评标。对评标专家因身体健康状况、业务能力等原因不能胜任评标工作的，应当及时调整；对因信誉等原因不能胜任评标工作的，取消评标专家资格。\n第二十九条 综合评标专家库的管理、使用单位及其工作人员，不得利用工作之便非法干预评标专家抽取活动或者获取、泄露评标专家信息，不得与招标人或者投标人串通谋取非法利益。","level":1},{"name":"第五章 信用体系建设","text":"第三十条 综合监督管理机构负责招标投标信用体系建设，建立守信激励和失信惩戒机制。\n综合监督管理机构、有关行政监督部门和司法机关，应当互相通报招标投标交易和合同履行信息、行政管理和司法等信息，建立信用档案，实现信息数据的共享使用。\n第三十一条 综合监督管理机构应当建立招标人、招标代理机构、投标人、评标专家信用档案，健全招标投标诚信评价体系，开展招标投标信用评价，及时在公共服务平台公布评价结果，并向政府信用管理部门报送信用信息，实现信用信息的互联互通、互认共用。\n第三十二条 招标投标违法违规信息记录和信用评价结果应当作为资格审查、评标、定标的评审因素。\n第三十三条 有关行政监督部门应当在十五日内，将本部门对招标人、招标代理机构、投标人、评标委员会成员等当事人违法行为的行政处理决定，通报综合监督管理机构。综合监督管理机构应当在收到处理决定信息后五日内，将当事人违法违规不良记录在公共服务平台予以公布。\n第三十四条 招标投标行业协会应当在综合监督管理机构指导下，组织开展诚信教育和行业自律活动，协助建立健全信用体系。","level":1},{"name":"第六章 法律责任","text":"第三十五条 违反本条例，法律、行政法规有规定的，从其规定。\n第三十六条 违反本条例第八条第一款和第十九条第一项规定，在场外进行交易或者规避招标的，由综合监督管理机构责令限期改正，并依法予以处罚；拒不改正或者无法改正的，由有关行政部门依法暂停项目执行或者暂停资金拨付，由有关部门依法对直接负责的主管人员和其他责任人员给予处分。\n第三十七条 违反本条例规定，招标人有下列行为之一的，由综合监督管理机构责令限期改正；拒不改正的，责令暂停招标投标活动：\n（一）未将资格预审公告、招标公告在规定的媒体和公共服务平台上发布的；\n（二）未在规定的时间内公示中标候选人有关情况的。\n第三十八条 投标人、招标代理机构违反本条例第二十条、第二十一条规定的，由有关行政监督部门依法处罚；情节严重的，由综合监督管理机构取消投标人、招标代理机构三年进入公共资源交易中心参与交易活动的资格；情节特别严重的，取消永久进入公共资源交易中心参与交易活动的资格；构成犯罪的，依法追究刑事责任。\n评标专家违反本条例第二十二条规定的，由省综合监督管理机构取消评标专家资格，在公共服务平台予以公告，并依法予以处罚；构成犯罪的，依法追究刑事责任。\n第三十九条 专家库的管理、使用单位及其工作人员违反本条例第二十九条规定的，由综合监督管理机构给予警告，由有关部门依法对直接负责的主管人员和其他责任人员给予处分；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第四十条 在招标投标活动中串通投标、以他人名义投标或者以其他方式弄虚作假骗取中标的，由有关行政监督部门依法查处，综合监督管理机构协调监督；对于有关行政监督部门需要回避、没有行政监督部门查处或者行政监督部门查处职责交叉的，以及特别重大的违法行为，由综合监督管理机构依法查处；构成犯罪的，依法追究刑事责任。\n第四十一条 综合监督管理机构、行政监督部门和公共资源交易中心及其工作人员不依法履行职责、滥用职权的，由有关部门依法对直接负责的主管人员和其他责任人员给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第四十二条 本条例自2015年8月1日起施行。","level":1}]},{"id":"h0172","sections":[{"name":"","text":"（2015年7月30日湖北省第十二届人民代表大会常务委员会第十六次会议通过）\n根据《中华人民共和国立法法》的有关规定，湖北省第十二届人民代表大会常务委员会决定：黄石市、十堰市、襄阳市、宜昌市、荆州市、荆门市、鄂州市、孝感市、黄冈市、咸宁市、随州市、恩施土家族苗族自治州人民代表大会及其常务委员会自2016年1月1日起，可以开始制定地方性法规。","level":0}]},{"id":"h0173","sections":[{"name":"","text":"（2015年9月23日湖北省第十二届人民代表大会常务委员会第十七次会议通过 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了做好农村五保供养工作，保障农村五保供养对象的正常生活和合法权益，完善农村社会保障制度，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内的农村五保供养，适用本条例。\n本条例所称农村五保供养，是指对符合五保供养条件的农村居民，在吃、穿、住、医、葬等方面给予生活照顾、资金和物质保障。\n第三条 农村五保供养工作应当遵循应保尽保、公开公平公正的原则，坚持政府主导、社会参与、集中供养与分散供养相结合，供养标准和水平与经济社会发展相适应。\n第四条 县级以上人民政府是本行政区域农村五保供养工作的责任主体，应当加强对农村五保供养工作的组织领导和统筹协调，将农村五保供养纳入国民经济和社会发展规划，完善社会保障体系，健全医疗、教育、住房等专项救助制度，逐步提高农村五保供养水平。\n第五条 县级以上人民政府民政部门主管本行政区域的农村五保供养工作。发展改革、教育、公安、财政、人力资源和社会保障、自然资源、住房和城乡建设、农业农村、文化和旅游、卫生健康、医疗保障、残联等相关部门和单位，按照各自职责共同做好农村五保供养工作。\n乡镇人民政府、街道办事处负责组织实施农村五保供养对象（以下简称供养对象）的申请受理、审核和供养服务具体工作。村（居）民委员会协助乡镇人民政府、街道办事处做好供养对象的民主评议、公告和日常生活照料等工作。\n第六条 国家机关、社会团体、企业事业单位和其他组织应当采取措施，健全保障供养对象权益的各项制度，逐步改善供养对象生活、健康、安全以及参与社会发展的条件。\n各级人民政府及其相关部门和报刊、广播、电视、网络等媒体应当加强农村五保供养工作的宣传，形成全社会尊重、关心、帮助供养对象的社会风尚。\n第七条 对在农村五保供养工作中做出显著成绩的单位和个人，按照国家和省有关规定给予表彰、奖励。","level":1},{"name":"第二章 供养对象和内容","text":"第八条 无劳动能力、无生活来源且无法定赡养、抚养、扶养义务人，或者其法定赡养、抚养、扶养义务人无赡养、抚养、扶养能力的农村居民，享受农村五保供养待遇。\n已满六十周岁的老年人，未满十六周岁的未成年人以及经伤残鉴定丧失劳动能力的残疾人，视为无劳动能力。\n个人收入低于当地农村居民最低生活保障标准的，视为无生活来源。\n第九条 确认供养对象，应当按照下列程序办理：\n（一）由农村居民本人或者受委托人向户籍所在地的乡镇人民政府、街道办事处提出申请。本人申请有困难的，可以由村（居）民委员会代为提出申请。\n（二）乡镇人民政府、街道办事处应当自受理申请之日起十日内，对申请人的家庭状况、经济条件等进行核实，提出审核意见，并委托村（居）民委员会进行民主评议。对符合条件的，在申请人所在村（社区）进行公告，公告期不少于七日。无重大异议的，将审核意见和有关材料报送县级人民政府民政部门。\n（三）县级人民政府民政部门应当自收到审核意见之日起十五日内作出审批决定。对符合条件的，予以批准；对不符合条件不予批准的，应当向申请人书面说明理由。\n申请人认为本人符合农村五保供养条件，未获批准的，可以向审核、审批机关申请复查。审核、审批机关应当自收到复查申请之日起十五日内作出复查决定。\n第十条 县级以上人民政府民政部门应当建立农村居民家庭经济状况信息平台，为认定供养对象提供依据。\n乡镇人民政府、街道办事处和村（居）民委员会应当及时掌握辖区居民生活情况，主动为符合条件的人员依法办理供养。\n第十一条 农村五保供养包括下列内容：\n（一）供给粮油、副食品以及生活用燃料；\n（二）供给服装、被褥等生活用品和零用钱；\n（三）提供符合基本居住条件的住房；\n（四）提供疾病治疗、日常诊疗，对生活不能自理的给予照料；\n（五）办理丧葬事宜。\n供养对象未满十六周岁或者已满十六周岁正在接受义务教育、高中教育（含中等职业教育）、普通高等教育的，享受农村五保供养待遇，并根据不同教育阶段需求，采取减免相关费用、发放助学金、给予生活补助等方式，保障其学习和生活。\n第十二条 供养对象有下列情形之一的，不再享受农村五保供养待遇，由乡镇人民政府、街道办事处审核并报县级人民政府民政部门核准后，核销其供养资格：\n（一）已有具备供养能力的法定赡养人、抚养人、扶养义务人的；\n（二）重新获得稳定生活来源，个人收入超过当地农村最低生活保障标准的；\n（三）已满十六周岁，已完成义务教育、高中教育（含中等职业教育）和普通高等教育在校学习，且具有劳动能力的；\n（四）自愿申请停止农村五保供养待遇的；\n（五）其他不符合农村五保供养条件的。\n供养对象对核销结果有异议的，可以在收到核销通知书后三十日内向核准机关提出复查申请，核准机关应当在十五日内作出复查决定。\n第十三条 供养对象享有个人财产的所有权。任何单位和个人不得以五保供养为由，侵犯供养对象的房屋所有权、宅基地使用权、土地承包经营权等财产权益。供养对象将承包土地交由他人代耕的，其收益归该供养对象所有。\n供养对象退出供养或者死亡的，其个人财产按照约定和有关法律、法规的规定处理。","level":1},{"name":"第三章 供养形式","text":"第十四条 供养对象有权选择供养形式，可以选择当地供养服务机构集中供养，也可以选择在家分散供养。\n对残疾、未成年供养对象，县级人民政府民政部门应当提供有利于其身心发展的供养服务。\n第十五条 供养对象选择集中供养的，由供养服务机构提供供养服务。县级人民政府民政部门应当妥善安置符合集中供养条件的供养对象，必要时可在同一县（市、区）范围内就近跨区域调剂安排。\n供养对象选择分散供养的，可以由村（居）民委员会提供照料，也可以由供养服务机构提供代养、代管等服务。乡镇人民政府、街道办事处应当建立分散供养对象联系、帮扶制度，及时掌握其衣、食、住、医等方面的生活动态，帮助解决生活上的困难。\n第十六条 乡镇人民政府、街道办事处应当与村（居）民委员会或者供养服务机构、供养对象签订供养服务协议，约定各方权利和义务，保证供养对象享有符合要求的供养待遇，并报县级人民政府民政部门备案。\n村（居）民委员会可以委托分散供养对象的近亲属、居民或者其他组织进行照料，并与受委托人签订供养服务协议，落实服务责任和帮扶措施。\n第十七条 供养服务机构提供的供养服务，应当符合有关法律法规的规定和国家的标准规范，尊重少数民族习惯和宗教信仰，不得歧视、侮辱、虐待或者遗弃供养对象。\n各级人民政府及其相关部门应当扶持供养服务机构利用已有土地、山林、水面等开展农副业生产，其收入应当主要用于改善供养对象的生活，任何单位和个人不得侵占、挪用。\n鼓励供养对象参加有益身心健康和力所能及的生产活动，供养服务机构应当给予适当报酬或者奖励。\n第十八条 各级人民政府应当将分散供养对象居住的危陋房屋优先纳入农村危房改造计划，及时进行修缮，保证房屋安全、符合居住条件。\n乡镇人民政府、街道办事处可以与供养服务机构协商，利用闲置床位为部分分散供养对象在危房改造、取暖、防暑等特殊时期安排住宿，并提供与集中供养对象同等的服务。\n第十九条 各级人民政府及其相关部门、企业事业单位应当采取措施，对分散供养对象的基本生活保障支出给予政策优惠。供水、供电、供气、通信、有线电视等经营单位，按照规定为分散供养对象减免相关费用。\n村（居）民委员会可以从农村集体经营等收入中安排资金或者提供人力、物料，帮助改善分散供养对象的生活。\n第二十条 乡镇人民政府、街道办事处应当组织医疗机构为供养对象建立护理记录和健康档案，提供日常诊疗和体检服务。对因病需要住院治疗的，应当及时送往医疗机构诊治，并妥善安排其住院期间的生活照料和护理。\n对患有传染病、精神障碍等疾病不宜集中供养的供养对象，乡镇人民政府、街道办事处和县级人民政府民政、卫生健康部门应当妥善安排其供养和医疗服务，必要时送往专门的医疗机构治疗和托管。\n第二十一条 乡镇人民政府、街道办事处以及村（居）民委员会、供养服务机构应当关心供养对象的心理健康，为其提供心理疏导和亲情化服务。\n供养服务机构应当组织文化娱乐、体育健身等活动，丰富集中供养对象的精神生活。村（居）民委员会应当开放公共活动场所，方便分散供养对象健身、娱乐；鼓励社区居民通过邻里互助的形式帮助分散供养对象。\n供养对象的近亲属或者其他亲属应当看望和问候，给予供养对象家庭关爱和精神抚慰。\n第二十二条 供养对象的丧葬事宜，实行集中供养的，由供养服务机构负责办理，村（居）民委员会予以协助；实行分散供养的，由村（居）民委员会负责办理，当事人近亲属予以协助。\n丧葬费用由当地民政部门按照一年供养金标准予以一次性补助，并免除基本殡葬服务费用。当事人近亲属提出额外项目服务要求的，费用由其近亲属承担。","level":1},{"name":"第四章 供养服务机构","text":"第二十三条 供养服务机构是县级人民政府民政部门或者乡镇人民政府、街道办事处（以下简称主办机关）举办的，为供养对象提供供养服务的公益性机构。\n省人民政府民政部门应当制定统一的供养服务机构服务规范和标准。县级以上人民政府民政部门负责本行政区域内供养服务机构的管理和业务指导，对供养服务机构定期检查、考核。\n第二十四条 县级以上人民政府民政部门应当根据本级人民政府国民经济和社会发展规划，按照因地制宜、满足需要的原则，会同相关部门编制供养服务机构建设专项规划，并组织实施。\n第二十五条 县级人民政府民政部门或者乡镇人民政府、街道办事处应当根据实际需要建设供养服务机构。有条件的地区可以建设具有区域性中心供养服务功能的供养服务机构。\n供养服务机构的设施建设应当符合抗震、消防、环保等建筑设计规范和建设标准，坚持改建、扩建、新建相结合，并避开地质灾害易发区；建设项目竣工后，经相关部门验收合格，方可投入使用。\n第二十六条 省人民政府民政部门应当会同相关部门制定供养服务机构建设标准。\n供养服务机构的建设规模一般不少于六十张床位，每名供养对象的居住面积不少于六平方米。县级或者中心乡镇供养服务机构的建设规模，根据当地财力状况、供养人数及需求相应提高。\n供养服务机构应当建有厨房、餐厅、活动室、浴室、卫生间等辅助用房，配置基本生活设施、残疾人无障碍设施和医疗保健、文体娱乐、供暖降温、消防等设备。\n有条件的供养服务机构可以设立医务室，配备具有专业技术资格的医护人员。县级人民政府卫生健康部门和乡镇卫生院应当定期给予业务指导和培训。\n第二十七条 供养服务机构在确保当地供养对象集中供养需求和服务水平的基础上，可以向社会提供有偿寄养服务，其有偿服务项目和收费标准，应当符合国家和省有关规定。\n第二十八条 政府主办或者其他组织利用国有资产举办的供养服务机构，由县级人民政府事业单位登记管理机构依法办理事业单位法人登记。\n第二十九条 供养服务机构应当成立由主要负责人、工作人员和供养对象代表组成的管理委员会，实行民主管理；建立健全财务、档案、环境卫生等规章制度，定期公布供养资金、管理经费使用情况以及接受捐赠的款物、生产经营账目等，接受相关部门、供养对象和社会公众的监督。\n供养服务机构应当建立健全安全制度，落实安全责任，定期组织工作人员进行安全知识学习和培训，对供养对象进行安全知识教育，增强安全意识。\n第三十条 供养服务机构负责人和主要管理人员由主办机关聘任，并报上级民政部门备案；其他工作人员由供养服务机构聘用，并依法签订劳动合同，按规定办理相应的社会保险。\n供养服务机构应当因事、按需设岗，工作人员与供养对象比例不低于1:7；生活不能自理的供养对象超过30%的部分，工作人员按照1:3增配。\n县级人民政府民政部门应当定期组织工作人员进行业务培训。\n第三十一条 县级以上人民政府相关部门和单位应当支持供养服务机构的建设和发展，对其给予政策优惠：\n（一）减免城市基础设施配套费和有关行政事业性费用；\n（二）减免水、电、天然气、通信、有线电视等生活设施安装费，执行居民用水、用电、用气价格标准；\n（三）依法使用农村集体建设用地，并给予税收优惠；\n（四）面向社会提供的供养服务，依法免征营业税。","level":1},{"name":"第五章 供养保障和监督管理","text":"第三十二条 县级以上人民政府应当将农村五保供养资金和供养服务机构建设、管理资金纳入年度财政预算，实行专款专用。\n省人民政府对农村五保供养给予财政转移支付资金支持，并建立自然增长机制；对边远贫困地区农村五保供养加大财政补贴力度。\n各级福利彩票公益金地方留存部分，每年应当安排不低于15%的比例，用于支持供养服务机构建设和维护。\n第三十三条 农村五保供养标准按照上一年度当地农村居民人均消费支出确定，并不得低于80%。\n市州人民政府每年年初制定本行政区域的农村五保供养标准，报省人民政府备案后公布执行。\n第三十四条 集中供养对象的供养资金，由县级人民政府财政部门按时足额拨付到供养服务机构。分散供养对象的供养资金，实行社会化发放。\n供养资金应当全部用于供养对象的生活，任何单位和个人不得贪污、挪用、截留或者私分。\n第三十五条 乡镇人民政府、街道办事处和县级人民政府民政、人力资源和社会保障、卫生健康、医疗保障等部门，应当保障供养对象享受城乡居民养老保险、城乡居民基本医疗保险等待遇。\n供养对象参加城乡居民基本医疗保险的个人缴费部分，由政府给予全额补助；供养对象符合规定的基本医疗费用个人承担部分，经基本医疗保险、大病保险和其他补充医疗保险支付后，由医疗救助资金及其他方式全额补助。\n定点医疗机构应当免收供养对象门诊挂号费、床位费，为供养对象提供优质、便捷的医疗服务。\n第三十六条 县级以上人民政府及其相关部门应当加强对供养服务机构、村（居）民委员会安全工作的监督和指导，制定应急预案，落实各项防控措施，有效预防安全事故发生，保障供养对象的人身和财产安全。\n第三十七条 县级以上人民政府民政部门应当加强农村五保供养工作的管理，建立供养对象档案和数据库，向社会公开农村五保供养的申请条件、审批程序、供养标准以及供养资金使用、供养对象变动等情况，接受社会监督。\n县级以上人民政府财政部门和审计机关应当加强对供养资金使用情况的监督管理和审计。\n第三十八条 县级以上人民政府民政部门及其他相关部门应当建立投诉举报制度，受理农村五保供养工作的投诉和举报。对公民、法人或者其他组织投诉或者举报的问题，受理部门应当及时调查，按照规定处理。","level":1},{"name":"第六章 社会参与","text":"第三十九条 县级以上人民政府及其民政部门应当建立社会力量参与农村五保供养工作的机制和渠道，发布供养对象帮扶需求信息，为社会力量参与农村五保供养工作提供便利条件。\n第四十条 鼓励公民、法人和其他组织捐建供养服务机构、供养对象个人住房和其他相关设施。捐建建筑可以用捐赠单位名称、捐赠者姓名命名。\n鼓励公民、法人和其他组织为供养服务机构、供养对象捐赠款物。捐赠的款物，依法享受有关税收优惠政策。\n第四十一条 鼓励公民、法人和其他组织依法投资举办社会福利机构，为供养对象提供养护、康复、托管等服务。\n政府可以通过购买服务的方式，将供养对象委托民办社会福利机构或者有能力的社会组织集中供养，按当地供养标准支付生活、医疗、照料等费用，并给予适当补贴。\n县级以上人民政府民政部门应当对民办社会福利机构的服务范围、标准和质量等进行监督检查，切实维护供养对象的合法权益。\n第四十二条 鼓励国家机关、社会团体、企业事业单位将供养服务机构作为精神文明建设窗口和青少年尊老敬老教育基地。\n鼓励公民、法人和其他组织与供养服务机构或者供养对象结对帮扶，为供养对象提供帮助和生活照料。\n第四十三条 县级以上人民政府应当发挥志愿服务组织、社会工作服务机构和社会工作者的作用，为供养对象提供社会融入、能力提升、心理疏导等专业服务。","level":1},{"name":"第七章 法律责任","text":"第四十四条 违反本条例，法律、行政法规已有规定的，从其规定。\n第四十五条 国家机关及其工作人员有下列情形之一的，由其上级主管部门或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）未按照规定制定农村五保供养标准的；\n（二）未按照规定足额拨付农村五保供养资金的；\n（三）对符合农村五保供养条件的不予批准，或者对不符合农村五保供养条件的予以批准的；\n（四）未按照规定的供养标准和时间发放供养金的；\n（五）虚报供养对象人数，骗取农村五保供养资金的；\n（六）未履行监督管理责任，造成重大事故的；\n（七）其他侵犯供养对象合法权益的。\n第四十六条 供养服务机构及其工作人员或者村（居）民委员会以及受委托人有下列行为之一的，由县级人民政府民政部门或者乡镇人民政府、街道办事处责令限期改正；逾期不改正的，终止供养服务协议，对负有责任的主管人员和其他直接责任人员依法给予处分；造成损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任：\n（一）未尽到服务管理义务致使供养对象合法权益受到侵害的；\n（二）歧视、侮辱、虐待或者遗弃供养对象的；\n（三）侵占供养对象个人财产的；\n（四）私分、挪用、贪污供养资金、捐赠款物以及农副业生产经营收入的；\n（五）其他侵犯供养对象合法权益的行为。\n第四十七条 集中供养对象拒不遵守供养服务机构管理制度，扰乱正常生活秩序或者造成他人人身伤害、财产损失的，由乡镇人民政府、街道办事处予以批评教育；情节严重的，停止集中供养；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附则","text":"第四十八条 本条例自2015年12月1日起施行。1996年1月24日湖北省第八届人民代表大会常务委员会第十八次会议通过、2010年7月30日湖北省第十一届人民代表大会常务委员会第十七次会议修改的《湖北省农村五保供养工作规定》同时废止。","level":1}]},{"id":"h0174","sections":[{"name":"","text":"宪法是国家的根本法，是治国安邦的总章程，具有最高的法律地位、法律权威、法律效力。国家工作人员必须树立宪法意识，恪守宪法原则，弘扬宪法精神，履行宪法使命。为了彰显宪法权威，激励和教育国家工作人员忠于宪法、遵守宪法、维护宪法，加强宪法实施，规范湖北省国家工作人员宪法宣誓的组织工作，根据《全国人民代表大会常务委员会关于实行宪法宣誓制度的决定》，结合我省实际，制定本办法。\n一、全省各级人民代表大会及县级以上各级人民代表大会常务委员会选举或者决定任命的国家工作人员，以及各级人民政府及其部门、监察委员会、人民法院、人民检察院任命的国家工作人员，在就职时应当公开进行宪法宣誓。\n二、宣誓誓词如下：\n我宣誓：忠于中华人民共和国宪法，维护宪法权威，履行法定职责，忠于祖国、忠于人民，恪尽职守、廉洁奉公，接受人民监督，为建设富强民主文明和谐美丽的社会主义现代化强国努力奋斗!\n三、人民代表大会选举的本级人民代表大会常务委员会主任、副主任、秘书长、委员，乡、民族乡、镇的人民代表大会主席、副主席；省长、副省长，市(州)长、副市（州）长，县（市、区）长、副县（市、区）长，乡（镇）长、副乡（镇）长；监察委员会主任；人民法院院长；人民代表大会通过的本级人民代表大会专门委员会主任委员、副主任委员、委员，在依照法定程序产生后，进行宪法宣誓。宣誓仪式由本级人民代表大会会议主席团组织，主席团一位常务主席主持。集体宣誓时，由主席团在宣誓人中确定一名领誓人。\n人民代表大会选举的人民检察院检察长，待上一级人民代表大会常务委员会批准后，进行宪法宣誓。宣誓仪式由本级人民代表大会常务委员会主任会议组织，主任或者由主任委托一名主任会议成员主持。\n四、人民代表大会闭会期间，本级人民代表大会常务委员会任命或者决定任命的人民代表大会专门委员会个别副主任委员、部分委员，个别副省长、副市（州）长、副县（市、区）长，在依照法定程序产生后，进行宪法宣誓。宣誓仪式由本级人民代表大会常务委员会主任会议组织，主任或者由主任委托一名主任会议成员主持。集体宣誓时，由主任会议在宣誓人中确定一名领誓人。\n五、人民代表大会常务委员会任命或者决定任命的本级人民代表大会常务委员会副秘书长，代表资格审查委员会主任委员、副主任委员、委员，工作委员会主任、副主任、委员，人民代表大会专门委员会秘书长等其他人员；人民政府秘书长、厅长、局长、委员会主任等；监察委员会副主任、委员；人民法院副院长；人民检察院副检察长，在依照法定程序产生后，进行宪法宣誓。宣誓仪式由本级人民代表大会常务委员会主任会议组织，主任或者由主任委托一名主任会议成员主持。集体宣誓时，由主任会议在宣誓人中确定一名领誓人。\n人民代表大会常务委员会任命的人民法院的其他审判人员，人民检察院的其他检察人员，在依照法定程序产生后，进行宪法宣誓。宣誓仪式由本级人民法院、本级人民检察院分别组织。\n六、省人民代表大会常务委员会决定任命的武汉海事法院、汉江中级人民法院、武汉铁路运输中级法院院长，省人民检察院汉江分院、武汉铁路运输分院检察长，在依照法定程序产生后，进行宪法宣誓。宣誓仪式由省人民代表大会常务委员会主任会议组织，主任或者由主任委托一名主任会议成员主持。集体宣誓时，由主任会议在宣誓人中确定一名领誓人。\n省人民代表大会常务委员会任命的武汉海事法院、汉江中级人民法院、武汉铁路运输中级法院，以及武汉、襄阳铁路运输法院的其他审判人员；省人民检察院汉江分院、武汉铁路运输分院，以及武汉、襄阳铁路运输检察院的其他检察人员，在依照法定程序产生后，进行宪法宣誓。宣誓仪式由省高级人民法院、省人民检察院分别组织。\n七、人民政府及其各部门、监察委员会、人民法院、人民检察院任命的国家工作人员，在就职时进行宪法宣誓。宣誓仪式由人民政府及其各部门、监察委员会、人民法院、人民检察院分别组织。\n八、宪法宣誓应当在有关国家工作人员依照法定程序产生后及时进行。\n宣誓场所应当庄重、严肃，悬挂中华人民共和国国旗或者国徽。宣誓仪式应当奏唱中华人民共和国国歌。宣誓人员应当着装整洁、得体。\n宣誓仪式根据情况，可以采取单独宣誓或者集体宣誓的形式。单独宣誓时，宣誓人应当左手抚按《中华人民共和国宪法》，右手举拳，诵读誓词。集体宣誓时，由一人领誓，领誓人左手抚按《中华人民共和国宪法》，右手举拳，领诵誓词；其他宣誓人整齐排列，右手举拳，跟诵誓词。诵读誓词后，由领誓人报宣誓人，宣誓人同时各自报自己姓名。\n九、有关负责组织宣誓仪式的机关，可以根据本办法的规定并结合实际，制定宣誓的具体实施方案。\n十、本办法自2018年8月1日起施行。","level":0}]},{"id":"h0175","sections":[{"name":"","text":"（2013年7月26日长阳土家族自治县第八届人民代表大会第三次会议通过 2013年11月29日湖北省第十二届人民代表大会常务委员会第六次会议批准 根据2022年2月15日长阳土家族自治县第十届人民代表大会第二次会议通过 2022年5月26日湖北省第十三届人民代表大会常务委员会第三十一次会议批准的《长阳土家族自治县人民代表大会关于修改、废止部分单行条例的决定》修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强学校安全管理，保障学校及教职工人身安全，预防和处理学校安全事故，根据《中华人民共和国民族区域自治法》《中华人民共和国教育法》《中华人民共和国民法典》等法律、法规，结合自治县实际，制定本条例。\n第二条 自治县行政区域内普通中小学校、特殊教育中小学校、中等职业学校（以下统称学校）的安全工作适用本条例。\n第三条 学校安全工作坚持预防为主、依法管理、社会参与、各负其责的原则。\n第四条 自治县人民政府应当加强对学校安全工作的领导，建立工作协调机制，将学校安全工作纳入社会管理综合治理的考核内容，并按照方便农村偏远地区低龄学生就近、安全入学的原则，依法制定、调整学校设置规划，创造良好的安全环境，保障学校安全。\n第五条 自治县人民政府教育主管部门负责学校安全工作，指导、监督学校落实安全管理措施，协调处理学校安全事故，维护学校的正常教学秩序。\n公安、交通运输、住房和城乡建设、市场监督管理、应急管理、卫生健康、文化和旅游等主管部门，应当按照各自职责，负责学校安全工作。\n第六条 学校在教育教学活动期间，对学生负有安全教育、管理和保护的职责。\n学生应当遵守国家法律法规和学校纪律，自觉接受学校的安全教育和管理，不得从事危及自己、他人和学校安全的活动。\n学生监护人应当依法履行监护职责，配合、支持学校的安全教育和管理工作，加强对学生的安全教育和管理。\n学校可以组织成立学生家长委员会，监督、协助学校做好学校安全工作。\n第七条 自治县人民政府和学校举办者应当依法保障学校安全工作所需经费。\n学校不得以保障安全为由向学生收取任何费用。\n第八条 社会团体、企事业单位、其他社会组织和个人应当关注学生、教职工的人身安全，支持学校做好安全工作。","level":1},{"name":"第二章 安全教育","text":"第九条 自治县人民政府应当组织教育、公安、司法、住房和城乡建设、交通运输、文化和旅游、卫生健康、市场监督管理、应急管理、新闻出版等部门开展学校安全教育，预防和减少学生安全事故。\n第十条 自治县人民政府教育主管部门应当将安全教育列入教学计划，制定学生安全行为规范，指导学校对学生进行安全教育。\n第十一条 安全教育的主要内容包括交通安全、消防安全、食品安全、溺水预防、室内外教学安全、野外活动安全、疾病预防控制、预防不法侵害、避灾避险等。\n学校应当按照安全教育教学计划的要求，根据学生的不同年龄和认知水平，有针对性地集中开展安全防范和安全保护教育，提高学生的自我保护能力。","level":1},{"name":"第三章 安全管理","text":"第十二条 自治县人民政府教育主管部门应当指导、督促学校制定和落实安全责任制，将学校安全工作列入学校目标管理的内容，定期进行考核。\n第十三条 学校应当建立健全安全管理工作责任制，按照规定设立安全保卫机构或配备相应的专（兼）职安全保卫人员，做好安全管理的具体工作。\n学校校长是学校安全的第一责任人。\n第十四条 学校安全保卫机构和安全保卫人员应当落实学校安全保卫制度，完善出入校园登记制度，维护学校安全。\n为学校提供安全保卫服务的单位和个人应当符合国家有关规定的条件。\n第十五条 学校应当建立学生健康档案，提醒学生监护人对学生健康实行定期体检。\n学校应当对已知的特异体质的学生给予关注和照顾，在教育教学活动中采取必要的防护措施，并依法保护学生的个人隐私。\n学生在学校突发疾病的，学校应当及时将学生送医疗机构治疗，并及时通知学生监护人。\n第十六条 学校应当加强对学生的心理健康教育，设立心理咨询室，并配备专（兼）职心理咨询辅导员，开展学生心理卫生咨询辅导，帮助学生减轻心理压力，防止发生自伤、自残、他伤事故。\n第十七条 学校应当配备消防设施和器材，并定期进行检验、维修，确保消防设施和器材完好、有效。消防部门应当对消防设施和器材定期进行检查，并指导学校开展消防安全教育和应急演练。\n学校应当在走道、楼梯口等校园内容易发生危险的地方，设置安全警示标志牌、指示牌和应急照明装置等防护设施，在容易发生拥挤的通道和时段，安排人员引导学生有序通过。安全出口、通道应当保持畅通。\n第十八条 学校应当加强校园饮食卫生和商品质量管理，可以设立由教师、学生、家长代表组成的膳食监督委员会，履行监督职责。学校食堂从业人员应当取得健康证明，并遵守国家食品卫生管理的规定。\n第十九条 学校应当设立医务室或卫生保健室，配备专（兼）职卫生人员和必要的医疗用品，并制定学校疾病预防控制方案和公共卫生应急预案。\n学生患有精神疾病或者其他可能对学校安全造成重要影响的疾病，学校和学生监护人应当采取有效措施，防止学校发生安全事故。\n学校提供给学生的饮用水、食品和药品等，必须符合国家相关规定。\n第二十条 建设校舍及校内其他建（构）筑物，应当符合工程建设管理规定，未通过验收的，不得投入使用。\n学校应当定期对校舍、校内其他建（构）筑物、教学设施以及各类特种设施等进行安全检查，发现安全隐患的，应当及时维修并采取必要的防护措施；发现重大安全隐患的，应当停止使用，并及时报告自治县人民政府教育主管部门和其他相关部门。\n对有危险性的设施设备、科学教研试验仪器及其他有毒有害物品、易燃易爆物品，应当依法建立健全使用和管理制度，存放于安全地点，指定专人保管，并对生产的有毒有害废弃物统一收集、分类储存，交由具备相应资质的单位运输、处理。\n学校发现周边存在危害学校及学生和教职工人身安全的情形或者重大安全隐患的，应当及时采取有效预防措施并向所在地的乡镇人民政府和自治县人民政府有关主管部门报告。\n第二十一条 提供学生住宿的学校应当建立健全学生宿舍安全管理制度，明确专（兼）职教职工负责学生的生活管理和安全工作。\n第二十二条 学校组织学生参加教学实验（实习）、军事训练、公益劳动或者社会实践、集会、文化体育等活动，应当事先告知学生需要注意的安全事项，并采取必要的防护措施。\n学校不得组织学生从事接触易燃、易爆、有毒、有害等危险品的劳动以及超越其行为能力或者自我保护能力的其它危险性活动。\n第二十三条 禁止学生及其他人员擅自携带易燃易爆物品、有毒物品、管制刀具和其他危险物品进入校园。学校安全保卫机构或者安全保卫人员应当对上述危险物品进行经常性检查，并报告公安机关予以收缴。\n教职工、学生发现有危及学生、教职工人身安全的行为或者安全隐患的，应当及时采取适当的方式制止并向学校报告。\n学校教职工应当遵守国家法律、法规和工作纪律。\n第二十四条 自治县行政区域内用于运载学生的校车应当符合国家和省有关校车安全管理法律、法规的规定，运载学生的船舶等应当符合国家和省相关法律、法规的规定，保障学生安全。\n第二十五条 生产、经营、储存易燃、易爆、有毒、有害或者其他危险品以及从事高空高压等对周围环境有高度危险作业的，应当按照规定与学校保持安全距离。\n学校周边废水、废气、工业固体废物、噪声、放射性物质和其它污染物的排放应当符合国家和省规定的标准。\n第二十六条 自治县人民政府公安机关应当与学校建立定期联系制度，除指导学校做好内部治安防范工作，及时发现和消除学校治安隐患，依法查处扰乱学校治安的违法案件外，还应当加强学校周边的治安、交通巡逻，在位于交通事故易发路段或者道路通行情况复杂路段的学校，在学生上学和放学时段，加强对学校出入口道路交通秩序的维护。\n第二十七条 自治县人民政府交通运输、自然资源和规划、水利和湖泊主管部门应当加强对交通运输工具的监督管理，定期检查学校周边山体、水流状况，发现危及学校安全的，应当立即通知学校并采取相应措施，消除安全隐患。\n住房和城乡建设主管部门应当对学校周边在建工程进行监督管理，发现安全隐患的，应当依法及时督促建设单位予以整改。\n燃气、电力、通信、供水排水等设置有地下管网检修井口的单位，按照各自职责负责学校周边地下管网、井盖的巡查、检修和安全防范工作，相关主管部门负责监督管理。\n第二十八条 自治县人民政府文化和旅游主管部门应当依法禁止在学校及其周边200米范围内设立互联网上网服务营业场所、营业性娱乐场所。\n新闻出版、市场监督管理、卫生健康、城市管理执法等主管部门应当按照各自职责对学校及其周边有关经营场所和流动商贩进行监督管理，依法查处出售非法出版物、假冒伪劣产品、不符合安全标准的食品和无证经营、占道经营等违法行为。\n第二十九条 自治县人民政府教育主管部门应当建立学校突发事件风险管理应急处置机制。\n学校应当制定火灾、地震、气象灾害、突发公共卫生事件以及其他突发事件应急处置预案，建立风险隐患排查与整治机制，定期开展紧急疏散演练和人身安全防范技能演练。\n第三十条 学校发生突发事件时应当优先救护学生，及时通知学生监护人，并向自治县人民政府教育主管部门报告。\n第三十一条 学生监护人对学生的特定疾病、特异体质或者其他异常生理、心理情况，应当如实告知学校。","level":1},{"name":"第四章 安全事故处理","text":"第三十二条 学校发生安全事故的，应当按照国家和省有关规定处理。\n第三十三条 学生因侵权受到人身损害的，按下列规定处理：\n（一）具有完全民事行为能力的学生在学校学习、生活期间受到人身损害的，按照过错责任处理；\n（二）无民事行为能力的学生在学校学习、生活期间受到人身损害的，学校应当承担责任，但能够证明学校尽到教育、管理职责的，学校不承担责任；\n（三）限制民事行为能力的学生在学校学习、生活期间受到人身损害的，学校未尽到教育、管理职责的，应当承担责任；\n（四）无民事行为能力或者限制民事行为能力的学生在学校学习、生活期间，受到学校以外的人员人身损害的，由侵权人承担侵权责任；学校未尽到管理职责的，承担相应责任。\n第三十四条 因不可抗力发生安全事故，学校能证明尽到教育管理职责的，学校不承担赔偿责任。\n第三十五条 学生人身损害事故的赔偿，可以按照下列方式处理：\n（一）学校与学生监护人协商处理；\n（二）向学校所在地的乡镇人民调解委员会申请调解；\n（三）向教育主管部门或者其他有关部门申请调解；\n（四）依法向人民法院提起诉讼。\n第三十六条 学校、学生监护人自愿申请调解的，自治县人民政府教育主管部门或者其他有关主管部门、人民调解委员会应当受理，并自受理之日起30日内完成调解工作；必要时可适当延长期限，但最长不得超过60日。法律、法规另有规定的，从其规定。\n第三十七条 教职工、学生受到侵害造成人身损害的，应当获得医疗费、护理费、交通费等为治疗和康复支出的合理费用的赔偿，以及因误工减少的收入补偿。造成死亡的，还应当获得丧葬费和死亡赔偿金。\n第三十八条 在学生人身损害事故调查处理过程中，禁止下列行为：\n（一）侮辱、殴打、恐吓、扣留教职工、学生及其监护人或者事故处理人员；\n（二）侵占、损毁学校建筑和教育教学、生活服务设施设备及其他财产；\n（三）扰乱学校正常教学秩序和社会秩序；\n（四）其他妨碍、影响事故调查处理的行为。","level":1},{"name":"第五章 法律责任","text":"第三十九条 违反本条例规定的行为，法律、法规有处罚规定的，从其规定。\n第四十条 自治县国家机关及其工作人员违反本条例的，由所在单位或者上级有关部门对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。\n第四十一条 学校违反本条例，未履行安全教育和管理职责的，由自治县人民政府教育主管部门或者其他有关主管部门予以批评教育、警告，责令改正；造成重大或者特大伤亡事故的，对学校负责人和其他直接责任人给予处分；构成违反治安管理行为的，依法予以治安处罚；构成犯罪的，依法追究刑事责任。\n学校教职员工有侮辱、体罚、变相体罚等伤害学生行为或者对学生伤害事故负有责任的，由自治县人民政府教育主管部门给予批评教育；情节严重的，给予处分；构成犯罪的，依法追究刑事责任。\n因学校教职工在履行职务中故意或重大过失造成学校发生安全事故的，学校承担赔偿责任后，可以向有关责任人员追偿。\n第四十二条 侮辱、殴打学生、教职工，干扰学校教学秩序的，由公安机关依法处理；造成学校财产损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第四十三条 学校食堂从业人员生产、经营不符合食品卫生标准的食品，由自治县人民政府市场监督管理主管部门责令停止经营，销毁有毒有害食品，并对直接责任人处1000元以上5000以下罚款；造成食物中毒事故或者其他食源性疾患的，处5000元以上30000元以下的罚款。构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第四十四条 本条例下列用语的含义为：\n（一）学生，是指在本条例第二条规定的学校全日制就读的受教育者；\n（二）教职工，是指学校各级管理人员、教师以及学校的其他员工；\n（三）学校安全，是指学校校园、学校周边以及学校组织的校外活动的安全；\n（四）学校周边，是指国家和本省规定的应当与学校保持安全距离的区域，没有规定的，指距离学校红线200米以内的区域。\n第四十五条 自治县行政区域内托儿所、幼儿园发生的安全事故，参照本条例执行。\n第四十六条 本条例自2014年3月1日起施行。","level":1}]},{"id":"h0176","sections":[{"name":"","text":"（2015年11月26日湖北省第十二届人民代表大会常务委员会第十八次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了弘扬奉献、友爱、互助、进步的志愿精神，鼓励、引导和规范志愿服务活动，维护志愿者、志愿服务组织和志愿服务对象的合法权益，促进志愿服务事业健康发展，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内的志愿服务及其相关工作，适用本条例。\n第三条 本条例所称志愿服务，是指不以获取报酬为目的，自愿以自己的时间、知识、技能和体力等帮助他人、服务社会的公益性活动。\n本条例所称志愿者，是指从事志愿服务活动的个人。\n本条例所称志愿服务组织，是指从事志愿服务的非营利性社会公益组织。\n第四条 志愿服务应当遵循自愿、无偿、平等、诚信、合法的原则，不得违背社会公德，不得损害社会公共利益和他人合法权益。\n第五条 县级以上精神文明建设指导机构负责本行政区域内志愿服务的统筹规划、协调指导和督促检查等工作。\n第六条 县级以上人民政府应当将志愿服务事业纳入国民经济和社会发展规划，制定和完善志愿服务的支持和保障政策，合理安排志愿服务所需资金，引导和促进志愿服务事业发展。\n县级以上人民政府民政部门负责本行政区域内志愿服务行政管理工作。其他有关部门在各自职责范围内，做好志愿服务相关工作。\n乡镇人民政府、街道办事处应当鼓励和支持在本地区开展志愿服务，为志愿服务提供便利条件。\n共青团、工会、妇联、残联等群团组织做好与志愿服务相关的组织指导工作。\n第七条 省人民政府民政部门应当建立统一的志愿服务信息平台，与各级志愿服务信息平台互联互通，为志愿者注册、培训交流以及志愿服务信息发布等提供便利条件，实现志愿者、志愿服务组织、志愿服务项目、志愿服务需求的对接。\n第八条 省、市（州）、县（市、区）志愿者协会负责协调本行政区域内各类志愿服务组织开展志愿服务活动，为志愿者和志愿服务组织提供服务，依法维护志愿者和志愿服务组织的合法权益。\n第九条 全社会应当支持志愿服务活动，尊重志愿者提供的志愿服务。\n各级人民政府及其有关部门应当采取多种形式开展志愿服务公益宣传，传播志愿服务文化，弘扬志愿精神，提升志愿服务水平。\n广播、电视、报刊、网站等媒体应当通过新闻报道、专题专栏、公益广告等形式，经常性地开展志愿服务宣传。","level":1},{"name":"第二章 志愿者","text":"第十条 志愿者应当具备相应民事行为能力以及与其从事的志愿服务相适应的知识、技能和身体条件等。\n未成年人经其监护人同意或者由其监护人陪同，可以参加与其年龄、身心状况等相适应的志愿服务。\n第十一条 志愿者享有以下权利：\n（一）自愿加入或者退出志愿服务组织；\n（二）自愿参加志愿服务活动，有权拒绝参加与志愿服务无关或者超出其能力的活动；\n（三）获得与志愿服务相关的真实、完整的信息；\n（四）接受志愿服务所需的知识和技能培训；\n（五）获得从事志愿服务活动必要的条件和保障；\n（六）要求志愿服务组织出具本人的志愿服务证明；\n（七）参加志愿服务活动遭受人身意外伤害时，获得相应的救助；\n（八）对志愿服务组织进行监督，提出意见和建议；\n（九）法律、法规以及志愿服务组织章程规定的其他权利。\n第十二条 志愿者应当履行以下义务：\n（一）遵守志愿服务组织的章程和管理制度；\n（二）提供真实、准确的个人信息；\n（三）履行志愿服务承诺或者协议约定，完成志愿服务活动；\n（四）尊重志愿服务对象的意愿、人格和个人隐私；\n（五）法律、法规规定的其他义务。\n第十三条 志愿者可以自行在志愿服务信息平台注册，或者经本人同意，由其所属的志愿服务组织代为注册，成为注册志愿者。","level":1},{"name":"第三章 志愿服务组织","text":"第十四条 符合规定条件的志愿服务组织，依法在县级以上人民政府民政部门进行登记。\n县级以上人民政府民政部门应当简化登记手续，提供便捷服务，并向社会公告依法登记的志愿服务组织的名称、住所、服务范围以及设立、变更、注销等信息。\n志愿服务组织可以依托城乡社区、公园、广场、车站、机场等服务平台，建立志愿服务站点。\n第十五条 志愿服务组织应当履行以下职责：\n（一）制定志愿服务计划并组织实施；\n（二）发布志愿服务信息；\n（三）负责志愿者的招募、注册、激励、评价等工作；\n（四）对志愿者进行志愿服务知识、技能培训和安全教育；\n（五）为志愿者提供必要的条件和保障，帮助解决与志愿服务活动相关的实际困难；\n（六）依法筹集、管理和使用志愿服务经费、物资等；\n（七）根据志愿者的要求，如实出具志愿服务证明；\n（八）组织开展志愿服务的宣传、交流与合作；\n（九）法律、法规和志愿服务组织章程规定的其他职责。\n第十六条 志愿服务组织招募志愿者，应当公告志愿服务项目、服务内容、志愿者的条件和数量等信息，告知志愿服务过程中可能发生的风险。\n第十七条 志愿服务组织应当真实、完整记录志愿者的个人基本信息、志愿服务信息、培训信息、表彰奖励信息等，并录入志愿服务信息平台。\n未经志愿者本人同意，志愿服务组织不得公开或者泄露志愿者依法受保护的信息。\n第十八条 国家机关、企业事业单位、人民团体、基层群众性自治组织可以结合工作特点，发挥自身优势，组织本单位职工、社区居民开展志愿服务活动；也可以以志愿服务队等形式，申请成为志愿服务组织的分支机构或者团体成员。","level":1},{"name":"第四章 志愿服务活动","text":"第十九条 志愿服务的范围包括扶贫济困、支教助学、科技推广、文化体育、医疗卫生、法律服务、环境保护、心理咨询、社区事务、文明劝导、应急救援、大型社会活动等。\n鼓励优先为未成年人、老年人、残疾人和其他有特殊困难需要帮助的社会群体提供志愿服务。\n第二十条 志愿服务组织可以自行组织开展志愿服务活动，也可以根据有关组织和个人的申请或者委托，开展志愿服务活动。\n支持有志愿服务需求的组织和个人，通过志愿服务组织获得志愿服务。\n第二十一条 志愿者、志愿服务组织和志愿服务对象应当就志愿服务有关事项协商一致。\n志愿服务组织安排志愿者参加志愿服务活动，有下列情形之一的，有关方面应当签订书面志愿服务协议：\n（一）有较高人身安全风险的；\n（二）连续提供三个月以上专职服务的；\n（三）为大型社会活动提供志愿服务的；\n（四）组织境外人员开展志愿服务活动的；\n（五）法律、法规规定的其他情形。\n第二十二条 书面志愿服务协议应当包括以下内容：\n（一）志愿服务的时间、地点、内容和方式；\n（二）当事人的权利与义务；\n（三）志愿服务的基本保障条件和风险防范措施；\n（四）协议的变更和解除；\n（五）法律责任和争议解决方式；\n（六）其他需要明确的事项。\n第二十三条 鼓励和支持具备医学、心理、法律、科技、文艺、体育等专业知识和技能的志愿者开展专业性志愿服务活动。\n志愿服务组织开展专业性志愿服务活动时，应当有相关专业技术人员参加并指导。\n开展有职业资格要求的志愿服务活动，应当安排具备相应职业资格证书或者执业许可证书的志愿者参加。\n第二十四条 各级人民政府应当推动企业、学校、医院等成立志愿服务队进社区，引导慈善组织和其他社会组织到社区开展志愿服务活动。\n鼓励基层群众性自治组织依托社区综合服务设施，建立志愿服务平台，支持志愿者、志愿服务组织到社区开展志愿服务活动。\n第二十五条 县级以上人民政府民政部门应当鼓励社会工作服务机构与志愿服务组织建立联动机制，在组织策划、项目运作、资源共享等方面进行协作。\n第二十六条 志愿服务组织和志愿者参加应对突发事件志愿服务时，应当接受当地人民政府设立的应急指挥机构或者其委托的志愿服务组织的统一协调和管理。\n第二十七条 任何组织和个人不得强行指派志愿者或者志愿服务组织提供志愿服务，不得利用志愿服务的名义从事违法活动或者营利性活动。\n志愿服务组织和志愿者不得向志愿服务对象收取或者变相收取费用。","level":1},{"name":"第五章 保障与激励","text":"第二十八条 志愿服务经费来源包括：\n（一）政府财政支持；\n（二）依法获得的社会捐赠、资助；\n（三）基金会资助；\n（四）其他合法收入。\n第二十九条 志愿服务经费主要用于：\n（一）开展志愿服务活动；\n（二）开展志愿者培训、志愿服务宣传；\n（三）为志愿者参加志愿服务办理人身意外伤害保险；\n（四）对在志愿服务活动期间遭受人身意外伤害的志愿者予以救助；\n（五）对在志愿服务事业中做出突出贡献的组织和个人予以奖励；\n（六）其他与志愿服务有关的事项。\n志愿服务经费应当专款专用，任何组织和个人不得私分、挪用或者侵占。\n志愿服务经费的筹集、使用和管理情况，应当依法接受有关部门和社会的监督。\n第三十条 具备条件的地方可以依法设立志愿服务基金会，为志愿服务事业发展提供支持和保障。\n鼓励有条件的组织和个人依法设立志愿服务基金。志愿服务基金的筹集、使用和管理按照有关法律、法规执行。\n第三十一条 鼓励组织和个人对志愿服务进行捐赠。捐赠人依法享受税收等优惠。\n第三十二条 县级以上人民政府及其有关部门、群团组织可以通过政府购买公共服务等方式支持开展志愿服务，并依照有关规定将相关情况向社会公开。\n第三十三条 志愿服务组织应当为参加有较高人身安全风险的志愿服务活动的志愿者办理人身意外伤害保险。\n大型社会活动的举办者应当为志愿者办理人身意外伤害保险。\n鼓励保险公司根据志愿服务的特点，设立相关险种，对志愿者实行免费或者优惠承保。\n第三十四条 鼓励和支持国家机关、企业事业单位、人民团体、社会组织等为志愿者提供志愿服务专业知识和技能培训，并对本单位的志愿者参加志愿服务活动给予支持。\n第三十五条 县级以上人民政府可以将志愿服务工作纳入创建文明城区、文明街道（乡镇）、文明社区（村）、文明单位的考核内容。\n鼓励将志愿精神纳入市民公约、村规民约和行业规范等。\n第三十六条 教育行政主管部门、学校等应当将志愿服务教育纳入青少年思想品德教育内容，培育青少年的志愿精神，鼓励和支持青少年参加力所能及的志愿服务活动。\n第三十七条 实行注册志愿者星级评定制度，志愿者协会根据志愿服务时间和服务质量等，对注册志愿者进行星级评定。\n志愿者参加志愿服务的工时，可以换取一定的社区服务。换取社区服务的办法，由县级人民政府民政部门制定。\n第三十八条 对在志愿服务事业中做出突出贡献的志愿者、志愿服务组织以及优秀志愿服务项目，县级以上人民政府和精神文明建设指导机构应当予以表彰和奖励。","level":1},{"name":"第六章 法律责任","text":"第三十九条 违反本条例，法律、法规有规定的，从其规定。\n第四十条 志愿者在志愿服务中受到损害的，依照下列情形分别处理：\n（一）因志愿服务组织过错受到损害的，由志愿服务组织依法承担民事责任；\n（二）因志愿服务对象或者第三人过错受到损害的，由志愿服务对象或者第三人依法承担民事责任，志愿服务组织应当协助志愿者向志愿服务对象或者第三人追究法律责任；\n（三）因不可抗力受到损害的，志愿服务组织应当给予适当补偿。\n志愿者参加志愿服务组织安排的志愿服务活动，对志愿服务对象造成损害的，由志愿服务组织依法承担民事责任；志愿者有故意或者重大过失的，志愿服务组织依法追偿。\n第四十一条 志愿服务组织有下列行为之一的，由民政部门、公安机关予以制止，责令改正；情节严重的，撤销登记；构成犯罪的，依法追究刑事责任：\n（一）利用志愿服务名义从事违法活动或者营利性活动的；\n（二）伪造志愿服务记录、提供虚假志愿服务证明的；\n（三）侵犯志愿者或者志愿服务对象的个人隐私和其他依法受保护的信息的；\n（四）私分、挪用或者侵占志愿服务经费、物资的；\n（五）其他违反法律、法规规定的行为。","level":1},{"name":"第七章 附则","text":"第四十二条 本条例自2016年2月1日起施行。2006年5月26日湖北省第十届人民代表大会常务委员会第二十一次会议通过的《湖北省青年志愿服务条例》同时废止。","level":1}]},{"id":"h0177","sections":[{"name":"","text":"（2016年1月13日湖北省第十二届人民代表大会常务委员会第十九次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了引领、推动、规范和保障全面深化改革，加快体制机制创新，激励和保护改革者，增强改革发展动力和创业创新活力，根据法律、行政法规的有关规定，结合本省实际，制定本条例。\n第二条 本省范围内经济体制、政治体制、文化体制、社会体制、生态文明体制等改革与改革促进工作，适用本条例。\n第三条 全面深化改革必须坚持中国共产党的领导，坚持全面建成小康社会、全面深化改革、全面依法治国、全面从严治党的战略布局，贯彻落实创新、协调、绿色、开放、共享的发展理念，解放思想，求真务实，增强社会活力和综合实力，加快推动“建成支点、走在前列”进程，全面推进富强、创新、法治、文明、幸福湖北建设。\n第四条 全面深化改革应当坚持问题导向、科学决策，顶层设计、基层首创，立法引领、法治保障，统筹协调、循序渐进，公众满意、成果共享的原则。\n第五条 鼓励和支持社会公众参与改革，共同营造勇于改革、敢于创新、崇尚成功、允许试错、宽容失败的社会氛围。","level":1},{"name":"第二章 目标任务","text":"第六条 全面深化改革应当适应国家实施“一带一路”、促进中部地区全面崛起、长江经济带和长江中游城市群建设等重大战略需要，坚持绿色决定生死、市场决定取舍、民生决定目的“三维纲要”，深入推进“一元多层次”战略体系，以经济体制改革为重点，加大重要领域和关键环节改革力度，加快完善各方面体制机制，形成系统完备、科学规范、运行有效的制度体系，推进省域治理体系和治理能力现代化，力争湖北全面深化改革走在全国前列。\n第七条 坚持和完善社会主义基本经济制度，激发各种所有制经济发展活力。适应和引领经济发展新常态，推进供给侧结构性改革，以市场化改革为重点，深化国有企业改革，支持非公有制经济健康发展，完善社会主义市场经济体制机制，形成竞争有序、富有活力的经济发展新格局。\n加快完善现代市场体系，构建开放型经济新体制。健全使市场在资源配置中起决定性作用和更好发挥政府作用的制度体系，加快转变政府职能，深化行政体制、财税体制、投融资体制、科技体制等改革，全面推进创新发展，深入实施开放先导战略，形成有利于扩大开放的体制机制，加快建成内陆开放高地。\n健全城乡一体化发展体制机制，推进城乡要素平等交换、合理配置和基本公共服务均等化。深化农村集体产权制度改革，加快构建新型农业经营体系，提升县域经济实力，完善新型城镇化健康发展体制机制，健全公共服务保障体系，统筹做好城市工作，推进城乡协调发展，保障城乡居民共享改革成果。\n第八条 加强社会主义民主政治建设，推进人大工作制度机制创新，推进协商民主广泛多层制度化发展，加强基层民主建设；加快法治湖北建设，建立健全法治建设体制机制，推进科学立法、严格执法、公正司法、全民守法。\n深入推进依法行政，健全依法决策机制，深化行政执法体制改革，完善执法程序，推行综合执法，严格执法责任，建设法治政府和服务型政府。\n深入推进司法体制改革，完善司法机关依法独立公正行使审判权和检察权的制度，促进公正司法，提高司法公信力。\n第九条 创新文化发展体制机制，坚持把社会效益放在首位，实现社会效益和经济效益相统一。推进文化管理体制改革，完善公共文化服务体系和文化市场体系，推动公共文化和文化产业互动发展，激发全社会文化创造活力，突出荆楚文化特色，提升文化软实力。\n第十条 推进社会事业和社会治理改革创新，深化教育领域综合改革，健全促进就业创业体制机制，优化收入分配机制，健全完善社会保障体系，全面深化医药卫生体制改革；加强和创新社会治理，完善城乡网格化管理和社会化服务，健全公共安全体系，推进军民深度融合发展，保障和改善民生，维护社会和谐稳定。\n第十一条 加快生态省建设体制机制创新，建立绿色低碳循环发展产业体系，建立健全生态保护与环境治理体系，建立完善绿色发展体制机制，健全生态环境和自然资源资产监督管理体制，加快自然资源及产品价格改革，建立生态文明技术创新机制，促进资源节约型、环境友好型社会建设。\n加快主体功能区建设，加强三峡库区、武陵山区、大别山区、秦巴山区、丹江口库区、神农架林区等重要生态区域保护和建设，完善生态补偿和财政转移支付制度。\n完善生态文明建设督察与考评工作机制，实行生态环境损害责任终身追究和赔偿制度。\n第十二条 建立健全组织领导、决策实施、保障激励、监督考核、容错免责、纠偏以及责任追究机制，促进全面深化改革目标任务实现。","level":1},{"name":"第三章 工作职责","text":"第十三条 省全面深化改革领导机构领导全省全面深化改革工作，负责中央全面深化改革决策部署在本省的贯彻落实，以及本省全面深化改革总体设计、统筹协调、整体推进、督促落实；其下设的办事机构，负责处理省全面深化改革领导机构日常工作。\n省全面深化改革领导机构下设的改革专项领导机构，负责贯彻落实中央和省全面深化改革决策部署，研究相关领域的重要改革任务，协调推动有关专项改革政策措施的制定和实施，承担省全面深化改革领导机构交办的专项工作任务。\n第十四条 市、州、直管市、神农架林区全面深化改革领导机构及县（市、区）有关机构负责落实和推进本行政区域内的全面深化改革工作。\n第十五条 县级以上人民代表大会及其常务委员会应当依法行使职权，充分发挥职能作用，保障和促进全面深化改革。\n各级人民政府及其部门应当持续推进简政放权、放管结合、优化服务，创新行政管理方式，加强事中、事后监管，有效引导市场主体行为，提高行政效能和服务水平，激发市场活力和社会创造力。\n各级人民法院、人民检察院应当依法履行司法职能，完善对权利的司法保障和对权力的司法监督，维护社会公平正义，为全面深化改革提供司法保障。\n各级国家机关及其部门应当加强改革工作的协同配合，加强对下级国家机关及其部门改革工作的领导或者指导。\n人民团体、企业事业单位和社会组织等应当在各自职责范围内做好改革工作。\n第十六条 国家机关、人民团体、企业事业单位和社会组织（以下简称改革主体）的负责人和工作人员应当依法履职，积极推进本地区本单位的改革工作。\n改革主体的主要负责人是全面深化改革的第一责任人。","level":1},{"name":"第四章 决策与实施","text":"第十七条 全面深化改革的决策与实施应当经过提出方案、专家论证、审议决定、组织实施、督察考评、反馈完善等程序。\n涉及改革发展全局、社会公众利益的重大改革方案通过前应当进行风险评估。\n改革方案应当向社会公布，但涉及国家秘密和商业秘密的除外。\n第十八条 各级全面深化改革领导机构应当制定全面深化改革工作中长期规划和年度计划，统筹长远目标和阶段性任务。具体改革工作应当制定内容明确、具有针对性和可操作性的方案。\n重大改革方案应当报送本级全面深化改革领导机构审定，一般性改革方案应当报送本级改革专项领导机构审定。所有改革规划、计划、方案和其他相关文件，应当于通过之日起三十日内报送本级全面深化改革领导机构和上级主管单位备案。\n第十九条 涉及跨地区、跨部门、跨领域或者重大利益关系调整的改革事项，有关单位应当加强沟通协商；未能达成一致意见的，应当及时提请有权机关或者共同的上级全面深化改革领导机构协调解决。\n第二十条 各级全面深化改革领导机构应当建立健全决策咨询制度，发挥专家学者、改革智库的作用。\n建立健全改革建议征集制度，通过座谈会、论证会、听证会和新闻媒体、电子网络平台等多种形式，广泛征集社会各界的意见和建议，为社会公众参与改革提供便利。\n鼓励社会公众对改革方案提出意见和建议，对改革决策实施进行监督，对改革效果进行评价。\n第二十一条 改革涉及面广、情况复杂或者需要探索改革方法的，应当在局部地区或者个别单位进行试点。\n鼓励和支持国家级开发区、改革试点（试验）区域和单位，大胆探索，先行先试，加快创新主体、创新平台、创新链条、创新环境等建设，形成可复制、可推广的经验，发挥试点（试验）对全局性改革的示范、突破和带动作用。\n第二十二条 鼓励和支持基层进行差别化探索，建立与基层改革实际需要相匹配的权责体系，为基层开展改革探索提供政策咨询和业务指导，发挥基层积极性和创造力。\n第二十三条 改革主体应当全面准确实施改革决策部署，提出改革任务清单、改革成果检验形式和改革时间表，加强统筹协调，强化改革责任，保障各项改革措施有效落实。\n建立健全改革立项、实施、督察、考评等工作制度，完善改革工作程序，总结改革实践经验，探索改革规律，提高改革质量和效益。\n第二十四条 改革主体应当对改革项目实施情况进行效果评估，涉及改革发展全局、社会公众利益的重大改革，应当委托第三方进行评估。评估结果可以向社会公布，并应当作为完善改革决策的重要依据。","level":1},{"name":"第五章 保障与激励","text":"第二十五条 地方立法应当主动适应全面深化改革和经济社会发展需要，坚持立法和改革决策相衔接，加强重点领域立法，引领和规范改革全过程，做到重大改革于法有据，巩固和发展改革成果。\n对不适应、不符合全面深化改革和经济社会发展需要或者与法律、行政法规规定不一致的地方性法规、地方政府规章和其他规范性文件，应当及时予以清理、修改或者废止。\n改革事项确需在相关地方性法规修改、废止之前先行先试的，应当在提请省人民代表大会常务委员会批准后实施。\n第二十六条 各级人民政府及其部门应当依法履行职能，推进机构、职能、权限、程序、责任法定化；适应全面深化改革和经济社会发展需要，适时推进机构改革，调整工作职能和人员编制。\n县级以上人民政府应当依法建立完善清单化管理制度，实行权力清单、责任清单、市场准入负面清单和涉企收费目录清单等管理。\n县级以上人民政府应当建立网上统一审批平台，推进集中审批、并联审批，规范行政审批行为，提高行政审批效率。\n第二十七条 财政预算单位开展改革创新所需要的工作经费应当纳入部门预算，其他单位应当保障必要的改革工作经费。\n县级以上人民政府设立改革项目促进资金，对本地区重点改革项目、年度优秀改革项目、困难地方和单位承担的改革试点项目和其他确需资助的改革项目予以支持。\n第二十八条 建立健全全面深化改革中的依法维权和化解纠纷机制，畅通利益表达、协商沟通、救济救助渠道，发挥法治在维护群众权益、化解社会矛盾中的作用。\n建立信访事项澄清保护机制。有关单位应当妥善处理涉及改革的信访事项，对反映的问题经查属实的，依法处理；对反映的问题经查不属实的，及时澄清是非，消除负面影响，依法处理诬告和陷害行为。\n第二十九条 改革主体应当及时发布改革信息，回应社会关切，引导社会预期；宣传改革举措，凝聚改革共识，汇集改革智慧，形成改革合力。\n新闻媒体应当加强对全面深化改革的舆论引导，积极宣传报道改革先进典型和成功经验，营造促进改革的良好社会氛围。\n第三十条 深化干部人事制度改革，坚持正确的用人导向，选拔任用想改革、谋改革、善改革且实绩突出的干部。\n建立健全人才培养、引进、使用、评价、激励和服务机制，营造引智聚才和改革创新的良好环境。\n第三十一条 设立湖北改革奖，对在改革工作中作出突出贡献的单位和个人给予表彰和奖励。","level":1},{"name":"第六章 监督与考核","text":"第三十二条 各级全面深化改革领导机构及其办事机构、专项领导机构和改革项目牵头单位应当健全分级督察责任体系，采取日常督察、专项督察、重点督察、全面督察等方式，了解改革方案设计、主体责任落实、实施进展、经济社会效益等情况，推动改革决策部署取得实效。\n第三十三条 县级以上人民政府、人民法院、人民检察院应当向本级人民代表大会及其常务委员会报告年度全面深化改革工作情况，自觉接受监督。\n县级以上人民代表大会常务委员会应当采取听取和审议专项工作报告、专题询问、执法检查、规范性文件备案审查等方式，对贯彻执行全面深化改革决策部署和相关法律法规实施情况开展监督；采取组织人大代表视察、开展专题调研、提出议案和建议批评意见等方式，发挥人大代表在全面深化改革中的作用。\n第三十四条 任何单位和个人有权对改革事项提出建议、批评和意见；对改革工作中超越法定权限和违反法定程序，或者抵制、阻扰、延误改革，或者拒不执行改革决定的行为，进行举报、投诉。对举报人和投诉人的合法权益依法予以保护。\n县级以上人民政府应当建立举报、投诉平台，及时受理、核实、处理单位和个人的举报、投诉，自觉接受社会监督。\n第三十五条 省全面深化改革领导机构应当加强对全省各级全面深化改革考核评价工作的组织领导。\n全面深化改革工作应当纳入全省地方和单位年度目标考核内容，建立分级分类考评机制，采取日常督办和定期考核相结合方式，必要时可以委托第三方进行评估，重点考核年度改革项目实施情况与效果、跨年度改革项目实施进展情况。\n考核结果作为干部评价、任用的重要依据。","level":1},{"name":"第七章 法律责任","text":"第三十六条 有关单位的改革工作有下列情形之一的，由本级全面深化改革领导机构、主管机关或者上级主管部门责令其予以纠正；必要时，可以要求其停止有关改革工作：\n（一）明显偏离改革预期目标、方向的；\n（二）违反法定程序作出改革决策的；\n（三）按照法定程序作出改革决策，但造成不良后果的；\n（四）改革决策实施过程中群众意见较大，经评估难以继续进行的；\n（五）其他应当纠正或者停止的情形。\n第三十七条 国家工作人员在改革工作中有下列情形之一的，由本级全面深化改革领导机构、主管机关或者上级主管部门按照管理权限，责令其予以改正，并根据情节轻重，给予批评教育、处分或者依法追究其责任：\n（一）超越法定权限或者滥用职权的；\n（二）抵制、阻扰、延误改革或者拒不执行改革决定的；\n（三）非法牟取私利的；\n（四）与他人恶意串通，损害公共利益或者他人合法权益的。\n第三十八条 改革工作未达到预期效果或者已造成一定负面影响和损失，但同时符合以下情形的，全面深化改革领导机构、主管机关或者上级主管部门对有关单位和个人不作负面评价，不追究有关人员的责任：\n（一）改革方案的制定和实施不违反法律、法规有关规定的；\n（二）相关人员已经履行了勤勉尽责义务的；\n（三）未非法牟取私利的；\n（四）未与他人恶意串通损害公共利益或者他人合法权益的。\n因法律、法规的修改或者国家政策调整等原因，导致改革工作未达到预期效果或者造成一定负面影响和损失的，不追究有关人员的责任。","level":1},{"name":"第八章 附则","text":"第三十九条 本条例自2016年3月1日起施行。","level":1}]},{"id":"h0178","sections":[{"name":"","text":"（2016年2月1日湖北省第十二届人民代表大会第四次会议通过 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了预防和治理土壤污染，保护和改善土壤环境，保障公众健康和安全，实现土壤资源的可持续利用，根据《中华人民共和国环境保护法》等有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内的土壤污染防治及其相关活动，适用本条例。\n土壤污染，是指因某种物质进入土壤，导致土壤化学、物理、生物等方面特性的改变，影响土壤有效利用，危害人体健康或者破坏生态环境，造成土壤环境质量恶化的现象。\n第三条 土壤污染防治应当遵循保护优先、预防为主、风险管控、综合治理、污染者担责的原则，实行政府主导、部门协同、社会参与的工作机制。\n第四条 县级以上人民政府对本行政区域内的土壤环境质量负责，应当将土壤污染防治工作纳入国民经济和社会发展规划，制定土壤污染防治政策和措施，提高土壤污染防治能力，改善土壤环境。\n县级以上人民政府应当统筹财政资金投入、土地出让收益等，建立土壤污染防治专项资金，完善财政资金和社会资金相结合的多元化资金投入与保障机制。\n乡镇人民政府、街道办事处根据法律、法规的规定和上级人民政府有关部门的委托，开展有关土壤污染防治工作。村（居）民委员会协助政府开展有关土壤污染防治工作，引导村（居）民保护土壤环境。\n第五条 县级以上人民政府应当支持土壤污染防治科学技术的研究开发、成果转化和推广应用，鼓励土壤污染防治产业的发展，提高土壤环境保护的科学技术水平。\n第六条 全社会都应当遵守环境保护法律、法规，养成绿色环保的生产生活方式，采取有效措施保护土壤环境，防治土壤污染。\n各级人民政府及有关部门和媒体应当加强土壤环境保护的宣传教育，将相关法律、法规纳入普法规划，增强公众土壤环境保护意识，拓展公众参与土壤环境保护途径，引导公众参与土壤环境保护工作。\n县级以上人民政府及有关部门应当对在土壤污染防治工作中做出显著成绩的单位和个人，给予表彰和奖励。","level":1},{"name":"第二章 土壤污染防治的监督管理","text":"第七条 县级以上环境保护委员会应当建立由政府主要负责人召集、有关部门参加、生态环境主管部门承担日常工作的土壤污染防治综合协调机制，研究、协调、解决土壤污染防治工作中的重大问题和事项。\n第八条 县级以上人民政府生态环境主管部门对本行政区域内的土壤污染防治工作实施统一监督管理，具体履行下列职责：\n（一）实施土壤污染防治的法律、法规和政策措施；\n（二）会同有关部门编制土壤污染防治规划；\n（三）组织开展土壤环境质量状况调查；\n（四）建立土壤环境监测制度和监测数据共享机制，定期发布土壤环境质量信息；\n（五）批准污染地块的土壤污染控制计划或者修复方案，并监督实施；\n（六）编制土壤污染突发事件应急预案，调查处理土壤污染事件；\n（七）依法开展土壤环境保护督查、执法；\n（八）法律、法规规定的其他职责。\n县级以上人民政府应当建立健全基层土壤环境监察执法体系，加强土壤环境保护执法队伍建设，组织开展教育培训，规范执法行为，提高基层环境保护执法能力和执法水平。\n第九条 县级以上人民政府农业农村主管部门负责本行政区域内的农产品产地土壤污染防治的监督管理，组织实施农产品产地土壤环境的调查、监测、评价和科学研究，以及已污染农产品产地土壤的治理，承担农产品产地污染事故的调查处理和应急管理。\n县级以上人民政府住房和城乡建设主管部门负责本行政区域内的建设用地土壤污染防治和城乡生活垃圾处理等方面的监督管理。\n县级以上人民政府自然资源主管部门负责本行政区域内的矿产资源开发利用、土地复垦等过程中的土壤污染防治监督管理。\n县级以上人民政府发展改革、经济和信息化、科技、财政、交通运输、水行政、林业、卫生健康、文化和旅游等有关部门，依照有关法律、法规的规定对土壤污染防治实施监督管理，共同做好土壤环境保护工作。\n第十条 实行行政首长土壤污染防治责任制和土壤环境损害责任追究制。具体办法由省人民政府制定。\n县级以上人民政府应当将土壤污染防治目标完成情况纳入综合考核内容，对本级人民政府负有土壤污染防治监督管理职责的部门及其负责人和下级人民政府及其负责人进行考核，考核结果向社会公布。\n县级以上人民政府应当每年向本级人民代表大会或者其常务委员会报告本行政区域内的土壤污染防治工作。\n第十一条 省人民政府应当严格执行国家土壤环境保护和管理的标准，建立健全本省土壤环境保护有关标准体系，制定、完善土壤环境质量标准和土壤污染控制与修复技术规范。\n省人民政府对国家土壤环境质量标准体系中未作规定的项目，可以制定本省土壤环境质量标准；对国家土壤环境质量标准体系中已作规定的项目，可以制定严于国家标准的地方标准。\n土壤环境保护的有关标准应当根据经济技术发展水平、土壤环境质量安全和维护公众健康的需要，及时修订并公布实施。\n第十二条 省人民政府应当加强土壤环境监测能力建设，完善监测体系，组织生态环境、农业农村、住房和城乡建设、自然资源等有关部门制定监测规范，建立统一的监测网络和信息共享平台。\n县级以上人民政府生态环境主管部门对监测信息共享平台实行统一管理和协调，发布监测信息。\n第十三条 省人民政府应当组织生态环境、农业农村、住房和城乡建设、自然资源等部门开展全省土壤环境质量状况普查，建立土壤环境质量档案。\n县级以上人民政府应当组织相关部门对饮用水水源保护区土壤环境质量状况每年至少调查一次，对农产品产地和修复后的污染地块等重点区域土壤环境质量状况每三年至少调查一次，并建立土壤环境质量档案。\n第十四条 县级以上人民政府应当根据主体功能区规划和本行政区域内的土壤环境质量状况、土壤环境承载能力，编制土壤环境功能区划，确定土壤环境功能的类型并划定土壤环境功能区，报省人民政府生态环境主管部门批准后公布。\n第十五条 县级以上人民政府生态环境主管部门会同有关部门，根据土壤环境质量状况和主体功能区规划、土壤环境功能区划、水环境功能区划等，编制本行政区域内的土壤污染防治规划，报本级人民政府批准后公布实施。\n土壤污染防治规划应当与土地利用总体规划、城乡规划相衔接。\n第十六条 负有土壤污染防治监督管理职责的部门进行监督检查，有权采取下列措施，任何单位和个人不得拒绝或者阻碍：\n（一）进入可能造成污染的场所实施现场检查，向有关单位和个人了解情况，查阅、复制有关文件资料；\n（二）责令立即消除或者限期消除土壤污染事故隐患；\n（三）责令停止使用不符合法律、法规规定或者国家标准、行业标准的设施、设备；\n（四）依法查封、扣押造成污染物排放的设施、设备；\n（五）发现污染土壤环境的违法行为，责令改正。\n第十七条 上级人民政府及其生态环境主管部门对重大土壤污染事故的处理和重点排污单位的土壤污染防治工作，应当实行挂牌督办；对土壤污染问题突出、公众反映强烈的地方，应当约谈有关人民政府及其相关部门主要负责人。","level":1},{"name":"第三章 土壤污染的预防","text":"第十八条 省人民政府应当根据环境保护需要和土壤环境功能区划，制定土壤污染防治的经济政策，公布禁止新建、改建、扩建污染土壤环境的生产项目名录以及限期淘汰的工艺和设备名录。\n县级以上人民政府及其有关部门应当采取措施，限期淘汰排放重金属、持久性有机污染物等污染土壤环境的工艺和设备，关停不符合产业政策的污染企业。\n第十九条 省人民政府生态环境主管部门应当根据土壤环境质量状况调查结果，制定土壤污染高风险行业名录，并及时更新和公布；高风险行业名录应当包括有色金属、制革、石油、矿山、煤炭、焦化、化工、医药、铅酸蓄电池和电镀等。\n县级以上人民政府生态环境主管部门应当公布土壤污染高风险行业企业名单，对其废水、废气、固体废物等处理情况及其用地和周边土壤环境进行监测、监控、监督检查，监测数据实时上传土壤环境信息化管理平台。\n土壤污染高风险行业企业应当按照生态环境主管部门的规定和监测规范，对其用地及周边土壤环境每年至少开展一次监测，监测结果如实报所在地县级人民政府生态环境主管部门备案。\n推行土壤污染责任保险制度，对土壤污染高风险行业企业依据国家规定实行土壤污染强制责任保险。\n第二十条 实行重点行业清洁生产评价制度。支持重点行业清洁生产技术改造，完善评价指标体系，开展清洁生产绩效评价，提升重点行业清洁生产水平，减少或者避免生产、服务和产品使用过程中污染物的产生和排放，减轻或者消除对公众健康和环境的危害。\n县级以上人民政府生态环境主管部门会同发展改革、经济和信息化等有关部门，依照国家规定定期对土壤污染高风险行业企业实施清洁生产强制审核。\n第二十一条 县级以上人民政府应当统一规划、科学布局开发区、工业园区等产业集聚区，依法进行规划环境影响评价，配套建设污水和固体废物集中处理设施，建立从源头到末端污染治理和资源化利用的全过程控制体系。\n排放含传染病病原体的废物、危险废物、含重金属污染物或者持久性有机污染物等有毒有害物质的项目，通过环境影响评价后，方可分类进入开发区、工业园区等产业集聚区。\n第二十二条 建设项目的环境影响评价应当包含对土壤环境质量可能造成影响的评价及相应预防措施等内容。环境影响评价文件未经批准，不得开工建设。\n对土壤环境质量不能满足土壤环境功能区划要求的区域，生态环境主管部门应当停止审批新增污染物排放的建设项目的环境影响评价文件。\n建设项目的土壤污染防治设施应当与主体工程同时设计、同时施工、同时投入使用。土壤污染防治设施应当符合经批准的环境影响评价文件的要求，不得擅自拆除或者闲置。\n第二十三条 禁止直接向土壤环境排放有毒有害的工业废气、废水和固体废物等物质。\n从事工业生产活动的单位和个人应当采取下列措施，防止土壤污染：\n（一）优先选择无毒无害的原材料，采用消耗低、排放少的先进技术、工艺和设备，生产易回收、易拆解、易降解和低残留或者无残留的工业产品；\n（二）及时处理生产、贮存过程中有毒有害原材料、产品或者废物的扬散、流失和渗漏等问题；\n（三）防止在运输过程中丢弃、遗撒有毒有害原材料、产品或者废物；\n（四）定期巡查维护环境保护设施的运行，及时处理非正常运行情况。\n第二十四条 采矿企业应当采取科学的开采方法、选矿工艺和运输方式，执行重点污染物特别排放限值，减少尾矿、矸石、废石等矿业废物的产生量和贮存量。\n县级以上人民政府生态环境主管部门应当加强矿产资源开发利用的辐射安全监督管理。相关企业应当每年对矿区开展一次辐射环境监测。\n矿业废物贮存设施和矿场停止使用后，采矿企业应当采取防渗漏、封场、闭库等措施，防止污染土壤环境。\n第二十五条 县级以上人民政府应当建立健全城乡生活垃圾收集、转运、处理机制，采取经济、技术政策和措施，鼓励、支持市场主体参与城乡生活垃圾分类收集、资源化利用和无害化处理。\n对生活垃圾实行填埋、焚烧的，应当采取耐腐防渗、除尘等无害化措施，防止污染周边土壤。\n建设生活垃圾处置设施、场所的，应当按照国家标准设置卫生防护带。卫生防护带设置不符合要求的，应当及时整改。\n各级人民政府及生态环境、农业农村、住房和城乡建设等有关部门应当开展农村环境综合整治，完善生活垃圾分类收集、转运、处理设施，提高废弃物回收利用水平，改善村庄人居环境。\n第二十六条 省人民政府生态环境主管部门应当制定和完善污泥处理处置标准和技术规范。县级以上人民政府生态环境主管部门应当加强污泥处理处置的监督管理，防止污染土壤环境。\n产生、运输、贮存、处置污泥的单位，应当按照国家和地方相关处理处置标准及技术规范，对污泥进行资源化利用和无害化处理。\n禁止擅自倾倒、堆放、丢弃、遗撒污泥。\n第二十七条 从事放射性物质、含传染病病原体的废物或者其他有毒有害物质收集、贮存、转移、运输和处置活动的单位和个人，应当采取有效措施防止污染土壤环境。\n第二十八条 从事加油、洗染和车船修理、保养、清洗以及化学品贮存经营等活动的单位和个人，应当采取措施防止油品、溶剂等化学品挥发、遗撒、泄漏污染土壤环境。\n第二十九条 县级以上人民政府及其循环经济发展综合管理部门应当合理布局废物回收网点和交易市场，支持企业、组织和个人开展废物的收集、贮存、运输、交易、信息交流及回收利用。\n从事废旧电子产品、电池、车船、轮胎、塑料制品等回收利用活动的企业、组织和个人，应当采取预防土壤污染的措施，不得采用可能污染土壤环境的方法或者使用国家禁止使用的有毒有害物质。\n第三十条 各级人民政府及有关部门和可能发生土壤污染事故的企业事业单位，应当制定土壤污染事故的应急预案，并定期进行演练，做好应急准备。","level":1},{"name":"第四章 土壤污染的治理","text":"第三十一条 县级以上人民政府生态环境主管部门应当将土壤污染物含量达到或者超过限值的地块纳入污染地块名单，报告本级人民政府和上一级生态环境主管部门，并依法向社会公布。\n县级以上人民政府生态环境主管部门应当将污染地块的污染情况通报土地权属登记部门；土地权属登记部门应当自收到通报之日起十五日内载入土地登记文件档案，并为公众提供免费查询服务。\n第三十二条 县级以上人民政府生态环境主管部门应当组织开展污染地块的土壤环境风险评估，提出控制地块名单和修复地块名单。风险评估报告应当包括需要实施污染控制或者修复的土壤面积、范围、措施、期限和用途建议等内容。\n污染地块的控制和修复，由造成污染的单位和个人负责。\n土壤污染责任人无法认定的，土地使用权人应当实施土壤污染控制和修复。\n第三十三条 土壤污染控制责任人、修复责任人应当根据风险评估情况，制定土壤污染控制计划或者修复方案，依法报有关主管部门备案并实施。\n开展土壤污染控制或者修复活动不得对土壤及其周边环境造成新的污染。\n第三十四条 土壤污染控制、修复活动完成后，应当按照国家规定进行评估、评审。\n第三十五条 县级以上人民政府应当组织生态环境、农业农村、住房和城乡建设、自然资源、经济和信息化、卫生健康等部门对已搬迁、关闭企业原址场地土壤污染状况进行排查，掌握其特征污染物、原排放方式、扩散途径以及敏感目标等，建立已搬迁、关闭企业原址场地的潜在污染地块清单，并及时更新。\n第三十六条 县级以上人民政府及其生态环境主管部门应当根据污染地块的具体情况，划定并公告土壤污染控制区，采取下列管控措施，减轻土壤污染危害或者避免污染扩大：\n（一）设立明显标识物；\n（二）设置围栏、警戒线等，疏散居民或者限制人员活动；\n（三）责令停止排放污染物、限制生产或者停产；\n（四）责令移除或者清理污染物；\n（五）调整土地用途；\n（六）其他必要措施。\n土壤污染控制区内禁止新建、改建、扩建与土壤污染控制或者修复无关的建筑物、设施，以及其他可能损害公众健康和生活环境的土地利用行为。","level":1},{"name":"第五章 特定用途土壤的环境保护","text":"","level":1},{"name":"第一节 农产品产地","text":"第三十七条 县级以上人民政府应当对耕地、园地、牧草地、养殖业用地等农产品产地土壤实行优先保护。\n县级以上人民政府农业农村主管部门会同生态环境主管部门，根据土壤环境质量状况调查结果和农产品产地土壤环境质量标准，将农产品产地划分为优先保护类、安全利用类和严格管控类，设立标志，统一编号，建立档案，实行分类管理。\n第三十八条 对优先保护类农产品产地实行永久保护。在优先保护类农产品产地集中区域，不得新建可能造成土壤污染的建设项目；已经建成的，应当限期关闭拆除。\n对安全利用类的农产品产地，应当按照国家规定制定、实施安全利用方案，并采取下列措施：\n（一）对周边地区采取环境准入限制，加强污染源监督管理；\n（二）加强土壤环境监测和农产品质量监测；\n（三）采取农艺调控等措施控制重金属进入农产品；\n（四）实施轮耕、休耕；\n（五）法律、法规规定的其他措施。\n对严格管控类农产品产地，应当采取下列措施：\n（一）禁止种植食用农产品和饲料用草；\n（二）不适宜农产品生产的，由政府依法调整土地用途；\n（三）调整种植结构或者退耕还林（还草）；\n（四）实行土壤污染管控或者修复；\n（五）法律、法规规定的其他措施。\n第三十九条 县级以上人民政府可以根据土壤环境保护的实际，在农产品产地外围划出一定范围的隔离带，采取植树造林、湿地修复等生态保护措施，预防和控制土壤污染。\n在隔离带内，严格控制城镇开发建设，禁止新建、改建、扩建有色金属、制革、石油、矿山、煤炭、焦化、化工、医药、铅酸蓄电池和电镀等土壤污染高风险行业企业和项目。\n对本条例实施前在农产品产地及其隔离带范围内建设的影响土壤环境的企业和项目，县级以上人民政府应当责令关闭或者搬迁，并依法予以补偿。\n第四十条 禁止违法生产、销售、使用下列农业投入品：\n（一）剧毒、高毒、高残留农药（含除草剂）；\n（二）重金属、持久性有机污染物等有毒有害物质超标的肥料、土壤改良剂或者添加物；\n（三）不符合标准的农用薄膜。\n第四十一条 县级以上人民政府农业农村主管部门应当制定农药（含除草剂）、化肥、农用薄膜等农业投入品减量使用计划，定期公布农业投入品禁用目录，开展技术培训，指导农业生产者合理使用农业投入品，实施测土配方施肥，提高耕地质量，保护和改善土壤环境。\n农业生产者应当采取下列措施，改善农产品产地土壤环境质量：\n（一）按照规定的用药品种、用药量、用药次数、用药方法和安全间隔期施药，防止农药残留污染土壤环境；\n（二）减量使用化肥、农用薄膜、植物生长调节剂等农业投入品；\n（三）及时清除、回收农药、肥料的包装物和残留、废弃农用薄膜等。\n县级以上人民政府生态环境主管部门会同农业农村主管部门，因地制宜设置农药、肥料、农用薄膜等农业投入品废弃物回收点，健全回收、贮运和综合利用网络，实施集中无害化处理。\n县级以上人民政府应当采取激励措施，鼓励、支持企业和个人从事农业投入品废弃物的回收利用和无害化处理。\n第四十二条 县级以上人民政府应当鼓励发展有机农业和生态循环农业，指导农业生产者调整种植结构，通过政府补贴等经济政策，推行秸秆还田、轮作休耕等有利于保护和改善土壤环境的措施，对生产高效、低毒、低残留农药和有机肥、缓释肥的企业以及从事有机农业、生态循环农业活动的生产者给予扶持。\n第四十三条 县级人民政府生态环境主管部门应当定期检测农田灌溉用水水质，并报告本级人民政府。未达到农田灌溉用水水质标准的，县级人民政府应当采取措施限期予以改善。\n在农产品产地范围内，禁止使用不符合农用标准的污水、污泥。\n第四十四条 县级以上人民政府生态环境主管部门应当加强对畜禽、水产养殖污染防治的监督管理；农业农村主管部门应当加强畜禽、水产养殖废弃物综合利用的指导和服务。\n严格规范兽药、饲料添加剂的生产，依法规范、限制使用抗生素等化学药品，实施农产品产地和水产品集中养殖区环境激素类化学品淘汰、限制、替代等措施，防止兽药、饲料添加剂中的有害成分通过畜禽养殖废弃物还田污染土壤环境。\n从事畜禽、水产规模养殖和农产品加工的单位和个人，应当对粪便、废水和其他废弃物进行无害化处理、综合利用或者达标排放。","level":2},{"name":"第二节 居住、公共管理与服务、商业服务用地","text":"第四十五条 县级以上人民政府应当加强建设用地中的居住、公共管理与服务、商业服务用地土壤环境保护，保障人居环境安全。\n第四十六条 县级以上人民政府住房和城乡建设主管部门会同生态环境主管部门，根据土壤环境质量状况调查结果，确定建设用地用途，实施分类管理。\n第四十七条 作为居住、公共管理与服务、商业服务用地使用的，应当按照规定进行土壤环境质量状况评估，评估结果向社会公开。\n未按照规定进行评估或者经评估认定可能损害人体健康的建设用地，不得作为居住、公共管理与服务、商业服务用地使用，相关部门不得办理供地等手续。\n第四十八条 新增建设用地和改变现有建设用地用途的，在办理用地手续前，土地使用权人应当根据国家有关技术规定，委托具有法定资质的机构，开展土壤环境质量状况评估，评估结果报所在地县级人民政府生态环境主管部门备案。\n现有建设用地土地使用权转让的，在办理相关规划和土地手续时，转让方应当提供具有法定资质机构编制的土壤环境质量状况评估报告，报所在地县级人民政府生态环境主管部门备案。\n国有土地出让、划拨的，土壤环境质量状况评估和报备由自然资源主管部门负责。","level":2},{"name":"第六章 信息公开与社会参与","text":"第四十九条 县级以上人民政府及其负有土壤污染防治监督管理职责的部门，应当建立土壤环境信息公开与发布制度，完善社会参与程序，为公众参与和监督土壤污染防治工作提供便利。\n负有土壤污染防治监督管理职责的部门应当依照有关规定，编制本部门的土壤环境信息公开指南和公开目录，并及时更新。土壤环境信息公开指南应当明确政府土壤环境信息公开的范围、形式、内容、申请程序和监督方式等事项。\n第五十条 省人民政府应当定期公布本行政区域内的土壤环境质量状况。\n县级以上人民政府生态环境主管部门应当及时公布严重污染土壤环境的单位名称、个人姓名和污染状况。\n土壤污染高风险行业企业应当依据国家环境信息公开有关规定，如实向社会公开其产生的重金属和持久性有机污染物名称、排放方式、排放浓度、排放总量以及污染防治设施的建设和运行情况，接受社会监督。\n第五十一条 任何单位和个人有权对土壤环境保护的决策活动提出意见和建议。\n除依法需要保密的情形外，土壤环境保护有关标准的制定、规划编制、项目审批、环境影响评价、污染控制计划、污染修复方案等与公众土壤环境权益密切相关的事项，应当公开，并通过听证会、论证会、座谈会等形式向可能受影响的公众说明情况，充分征求意见。\n第五十二条 县级以上人民政府生态环境主管部门应当将生产经营者遵守土壤环境保护法律、法规和承担土壤环境保护社会责任的情况分类记入环保诚信档案。\n环保诚信档案应当向社会公开，并作为财政支持、政府采购、银行信贷、外贸出口、企业信用、上市融资、著名商标和名牌产品认定的重要依据。\n第五十三条 对污染土壤环境或者不依法履行土壤污染防治监督管理职责的行为，任何单位和个人有权举报。\n接受举报的机关应当及时调查处理，对举报人的信息予以保密，举报查证属实的，给予奖励。\n第五十四条 县级以上人民政府应当采取激励措施，鼓励第三方开展土壤环境质量状况调查、土壤环境监测、土壤环境风险评估、土壤污染控制与修复，建立土壤污染防治市场化机制。\n第五十五条 鼓励符合条件的社会组织对严重污染土壤环境、破坏生态，损害公众健康、公共利益的环境违法行为，依法提起公益诉讼。\n提起土壤环境污染公益诉讼的社会组织和因土壤环境污染受到损害的当事人向人民法院提起诉讼的，负有土壤污染防治监督管理职责的部门和有关社会团体应当在确定污染源、污染范围以及污染造成的损失等事故调查方面为其提供支持。\n法律援助机构应当对提起土壤环境污染公益诉讼的社会组织和因土壤污染受到损害请求赔偿的经济困难公民提供法律援助。","level":1},{"name":"第七章 法律责任","text":"第五十六条 违反本条例，法律、法规已有行政处罚规定的，从其规定。\n因土壤污染受到损害的单位和个人，有权依法要求污染者承担停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失等民事侵权责任。\n污染土壤环境违法行为涉嫌犯罪的，负有土壤污染防治监督管理职责的部门应当及时将案件移送司法机关，依法追究刑事责任。\n第五十七条 各级人民政府未完成土壤污染防治工作目标的，由上一级人民政府或者有关部门对其主要负责人进行诫勉谈话或者通报批评；对任期内不依法履行职责，使辖区内土壤环境质量恶化，造成严重后果的，政府负责人应当引咎辞职，并依照规定追责。\n第五十八条 国家机关及其工作人员违反本条例规定，有下列情形之一的，由其主管机关或者监察机关依法对直接负责的主管人员和其他直接责任人员给予处分；构成犯罪的，依法追究刑事责任：\n（一）未按照规定开展土壤环境质量状况普查、调查的；\n（二）未依法实行土壤污染防治工作目标责任考核评价制度的；\n（三）未按照规定监测、监控和督查的；\n（四）违反产业政策批准项目建设、造成土壤污染的；\n（五）应当停止审批新增污染物建设项目的环境影响评价文件而未停止审批的；\n（六）违法批准土壤污染控制计划或者修复方案的；\n（七）违法批准占用农产品产地的；\n（八）违法办理建设用地供地手续的；\n（九）未依法履行信息公开义务的；\n（十）其他不依法履行职责的行为。\n第五十九条 土壤污染高风险行业企业未按照规定对其用地及周边土壤进行监测的，由生态环境主管部门责令限期改正，处2万元以上20万元以下罚款；拒不改正的，责令停产整治。\n土壤污染高风险行业企业未按照规定公开信息的，由生态环境主管部门责令限期改正；逾期未改正的，处2万元以上5万元以下罚款；情节严重的，责令停产停业。\n第六十条 建设项目的土壤污染防治设施未建成，主体工程即投入生产、使用，或者建成后擅自拆除、闲置的，由生态环境主管部门责令限期改正，处20万元以上100万元以下罚款；逾期不改正的，处100万元以上200万元以下罚款；对直接负责的主管人员和其他责任人员，处5万元以上20万元以下罚款；造成重大环境污染或者生态破坏的，责令停止生产或者使用，或者报经有批准权的人民政府批准，责令关闭。\n第六十一条 违法生产、销售本条例第四十条所列农药（含除草剂）、肥料、土壤改良剂、添加物、农用薄膜的，由农业农村主管部门或者法律、行政法规规定的其他有关部门责令停止生产、销售，没收违法所得，并处违法所得五倍以上十倍以下罚款；没有违法所得的，处5万元以上10万元以下罚款；情节严重的，依法吊销有关资质证书。\n有下列情形之一的，由农业农村主管部门给予警告，责令改正；拒不改正的，公告违法单位名称和个人姓名；造成严重后果的，对农业生产经营组织可以并处1万元以上3万元以下罚款：\n（一）使用重金属等有毒有害物质超标的肥料、土壤改良剂或者添加物的；\n（二）使用不符合标准的农用薄膜的；\n（三）在农产品产地范围内，使用不符合农用标准的污水、污泥的。\n违法使用剧毒、高毒、高残留农药（含除草剂）的，由农业农村主管部门责令改正，农药使用者为农业生产经营组织的，处5万元以上10万元以下罚款，农药使用者为个人的，处1千元以上1万元以下罚款。\n第六十二条 土壤污染控制责任人、修复责任人未按照规定开展土壤污染控制或者修复活动的，由生态环境主管部门责令限期改正，处2万元以上20万元以下罚款；拒不改正的，处20万元以上100万元以下罚款，并委托他人代为履行，所需费用由土壤污染控制责任人、修复责任人承担；对直接负责的主管人员和其他直接责任人员处5千元以上2万元以下罚款。\n第六十三条 单位和其他生产经营者违法排放污染物受到罚款处罚，被责令改正，拒不改正的，生态环境主管部门可以自责令改正之日的次日起，按照原处罚数额按日连续处罚，对排放污染物的单位主要负责人处5万元以上10万元以下罚款；情节严重的，报经有批准权的人民政府批准，责令停产停业、关闭。","level":1},{"name":"第八章 附则","text":"第六十四条 本条例自2016年10月1日起施行。","level":1}]},{"id":"h0179","sections":[{"name":"","text":"（2016年3月30日湖北省第十二届人民代表大会常务委员会第二十一次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了规范价格行为，维护市场价格秩序，保护消费者、经营者合法权益和社会公共利益，促进经济和社会发展，根据《中华人民共和国价格法》、《中华人民共和国反垄断法》、《中华人民共和国反不正当竞争法》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内发生的价格行为及其监督管理活动，适用本条例。\n本条例所称价格包括商品价格和服务价格。\n第三条 完善市场决定价格机制，充分发挥市场配置资源的决定性作用。\n健全政府定价制度，政府定价范围主要限定在重要公用事业、公益性服务和网络型自然垄断环节。\n第四条 县级以上人民政府应当将价格调控目标纳入国民经济和社会发展计划，建立健全价格形成机制和调控机制，完善价格监督管理体系，保持价格总水平基本稳定，营造良好的价格环境。\n省人民政府可以在国家确定的区域内，按照先行先试的原则，依法制定促进区域经济社会发展的价格政策。\n第五条 县级以上人民政府价格主管部门负责本行政区域内的价格工作。\n县级以上人民政府其他相关部门在各自的职责范围内负责有关的价格工作。","level":1},{"name":"第二章 经营者价格行为","text":"第六条 经营者应当遵循合法、公平、诚实信用原则，依据生产经营成本、市场供求、质量状况等因素，自主制定政府定价目录以外的商品和服务价格。\n第七条 经营者进行价格活动，享有以下权利：\n（一）依法自主制定属于市场调节的价格；\n（二）在县级以上人民政府价格主管部门和其他有关部门（以下简称政府定价机构）规定的幅度内制定价格；\n（三）向政府定价机构提出制定或者调整价格的建议；\n（四）从政府定价机构获取有关价格信息；\n（五）检举、控告侵犯合法价格权益的行为；\n（六）法律、法规赋予的其他价格权利。\n第八条 经营者进行价格活动，应当履行以下义务：\n（一）执行政府定价以及政府定价机构依法制定的价格行为规范；\n（二）按照规定明码标价，真实明确标示品名、产地、规格、等级、计价单位、价格或者服务项目、收费标准等；\n（三）配合政府定价机构开展成本调查、成本监审、价格监测、价格认定等工作，如实提供价格统计信息和会计凭证、账簿、报表等有关资料；\n（四）执行法定的价格干预措施；\n（五）法律、法规规定的其他价格义务。\n公用事业和公益性服务的经营者应当按照规定公开成本。\n第九条 经营者不得有《中华人民共和国价格法》禁止的不正当价格行为。经营者不得利用虚假或者使人误解的标价形式、价格手段诱骗消费者进行交易，不得违反法律法规的规定牟取暴利。\n经营者不得有下列不公平价格行为：\n（一）强制、变相强制交易相对人接受交易价格或者有偿服务；\n（二）收取费用与提供商品或者服务质价不符；\n（三）在标价之外附加不合理费用或者条件以及在订制和取消计费服务时设置不对等条件；\n（四）将自身义务转嫁给交易相对人并收取费用；\n（五）未尽告知义务，单方面收取交易相对人费用；\n（六）法律、法规禁止的其他不公平价格行为。\n第十条 具有竞争关系的经营者之间、经营者与交易相对人之间不得达成价格垄断协议。具有市场支配地位的经营者不得滥用市场支配地位，利用价格手段排除、限制竞争。\n第十一条 机场、车站、码头、高速公路服务区、景区、大型展览区等相对封闭区域内的经营者，应当根据价格主管部门的规定合理制定其经营的商品或者服务价格，并明码标价。\n相对封闭区域内的业主或者管理单位应当按照价格主管部门的规定将有关价格信息向社会公布，并加强对经营者价格行为的监督管理。\n省人民政府价格主管部门应当按照与就近区域市场价格水平大体相当的原则，并参照经营成本，依法制定相对封闭区域内的商品和服务价格行为规范。\n第十二条 经营者通过网络销售商品或者提供服务，应当向网络交易平台的经营者提交其有效身份证明、经营地址、联系方式或者工商登记资料等真实信息，明示价格及相关信息，履行承诺，不得有价格欺诈等违法行为。\n网络交易平台的经营者应当核存并按照规定公开销售商品或者提供服务的经营者所提交的相关信息，协助价格主管部门进行监督管理，维护网络交易价格秩序。\n第十三条 行业组织应当依法加强价格行为自律，引导本行业的经营者依法诚信经营，接受价格主管部门的工作指导和监督，不得制定排除或者限制价格竞争的规则、决定、通知，不得组织经营者达成价格垄断协议。","level":1},{"name":"第三章 政府定价行为","text":"第十四条 政府定价的权限和具体适用范围，以国家定价目录和本省定价目录为依据。\n省人民政府价格主管部门应当依据法律、法规制定本省定价目录，明确定价的项目、内容和部门，经省人民政府审核同意，报国务院价格主管部门审定后十五日内公布，并定期评估价格改革成效和市场竞争程度，适时调整定价目录。\n政府定价机构应当将政府定价纳入权力清单和责任清单，并向社会公开。\n县级以上人民政府价格主管部门应当完善政府定价监督管理制度，建立政府定价与政府定价监督管理相分离的机制，加强对其他政府定价机构定价行为的监督。\n第十五条 省人民政府价格主管部门应当会同相关部门编制本省行政事业性收费清单，建立动态调整机制，向社会公开收费项目名称、单位、标准、依据等，接受社会监督。\n有明确法律法规依据且不具备放开条件的经营服务性收费清单，由省人民政府价格主管部门制定、调整并公布。\n行政事业性收费标准，由省人民政府价格主管部门会同财政部门按照合理补偿成本和非盈利的原则制定、调整。\n行政事业性收费单位应当按照国家和省有关规定，向财政、价格部门报告收费资金的收支情况，并接受审计部门的监督。\n第十六条 对于纳入本省定价目录的项目，政府定价机构应当制定具体的管理办法，规范定价行为和程序。\n第十七条 政府定价应当履行成本监审、公众参与、合法性审查、集体讨论决定、公布等程序。\n制定专业技术性较强的商品和服务价格，应当组织专家论证，听取专家意见和建议。\n政府定价应当统筹考虑商品和服务的社会平均成本或者行业合理成本、市场供求状况、经济与社会发展要求以及社会承受能力等因素。\n政府定价机构制定、调整价格，应当开展市场价格、市场供求、社会承受能力调查分析，按照规定进行成本监审，核定定价成本，并向社会公开成本监审结论。\n第十八条 政府定价机构制定与城乡居民生活关系密切的价格，应当合理区分基本与非基本需求，兼顾低收入群体的利益。\n第十九条 政府定价机构制定关系群众切身利益的公用事业价格、公益性服务价格和网络型自然垄断经营的商品价格，应当组织听证。定价听证目录由省人民政府价格主管部门依据本省定价目录制定，并向社会公布。定价听证目录以外的政府定价，也可以实行定价听证。听证会应当通过政府网站、新闻媒体向社会全程公开。\n定价听证由价格主管部门提出，也可以由其他政府定价机构向价格主管部门提出，公民、法人和其他社会组织可以向价格主管部门提出定价听证的建议。\n价格主管部门应当建立鼓励和支持第三方组织参与定价听证的机制。第三方组织可以提出定价方案建议，参与定价听证，接受政府定价机构委托主持定价听证，并接受价格主管部门监督，不得违规操纵价格听证和牟取非法利益。\n政府定价机构应当将听证笔录和听证报告作为制定、调整价格的重要参考。\n第二十条 价格听证应当保障听证参加人具有广泛性、代表性，充分反映各相关利益方的诉求和意见，政府定价机构及相关单位应当为听证参加人提供便利和条件。\n听证参加人分别按照下列方式产生：\n（一）消费者，以自愿报名、随机选取方式产生，并现场公证；必要时也可以由相关社会组织推荐。消费者不得少于听证参加人总数的百分之五十；\n（二）经营者，以自愿报名方式产生，需要随机选取的，应当现场公证；\n（三）与定价听证项目有关的其他利益相关方，以自愿报名的方式产生，需要随机选取的，应当现场公证；必要时也可以由相关行业组织推荐；\n（四）相关领域的专家，在相关专家库中随机选取产生，并现场公证；\n（五）有必要参加定价听证的国家机关、社会组织的代表，由政府定价机构聘请。\n定价听证程序和其他事项，按照国家相关规定执行。\n第二十一条 行政事业性收费单位和实行政府定价的经营服务性收费单位，应当在收费场所显著位置公示收费项目、标准和依据，不得有下列行为：\n（一）不按照规定标准或者执行时间收费；\n（二）分解收费项目、扩大收费范围、增加计费频次、减少或者不提供服务；\n（三）不执行收费减免优惠政策；\n（四）以保证金、抵押金、滞纳金、集资、赞助等形式变相收费；\n（五）擅自增加收费项目或者改变收费主体；\n（六）法律、法规禁止的其他收费行为。\n第二十二条 政府定价机构应当对政府定价执行情况进行跟踪调查和评估，根据调查或者评估情况，适时调整价格。","level":1},{"name":"第四章 价格调控","text":"第二十三条 省人民政府应当建立健全保持价格总水平基本稳定的长效机制，合理运用法律手段、经济手段和必要的行政手段，综合运用财政、价格、投资、产业和物资储备等政策措施，保持价格总水平处于合理区间。\n第二十四条 省人民政府应当建立健全资源有偿使用制度和生态效益补偿制度，推进自然资源及其产品价格制度改革，使自然资源及其产品价格反映市场供求、资源稀缺程度、生态环境损害成本和修复效益。\n县级以上人民政府应当依法完善涉及水土保持、矿产、草原植被、森林植被、水资源等资源环境收费基金或者有偿使用收费政策，促进资源保护和节约利用。\n第二十五条 县级以上人民政府价格主管部门应当建立健全价格监测机构和网络，构建大宗商品价格指数体系，完善价格监测预警机制和应急处置体系，加强通货紧缩、通货膨胀预警，制定和完善相应防范治理预案，提升价格总水平调控能力。\n第二十六条 县级以上人民政府价格主管部门和有关部门应当建立健全价格公共服务制度和价格信息共享机制，及时发布大宗商品、重要服务市场价格行情以及相关警示信息，引导经营者合理定价和消费者理性消费，指导经营者调整优化生产经营结构。\n第二十七条 关系国计民生的重要商品或者服务价格显著上涨或者有可能显著上涨时，省人民政府可以对部分价格采取限定差价率或者利润率、规定限价、实行提价申报制度和调价备案制度等干预措施，并报国务院备案。\n省人民政府采取价格干预措施，应当及时向社会公告实施价格干预措施的地域范围、商品或者服务品种和具体内容。\n依照本条第一款规定采取价格干预措施的情形消除后，省人民政府应当及时解除价格干预措施，并向社会公告。\n第二十八条 县级以上人民政府应当建立健全社会救助、保障标准与物价上涨挂钩的联动机制，完善社会救助制度，保障困难群众基本生活不受物价上涨的影响。\n第二十九条 县级以上人民政府根据需要设立价格调控专项资金，用于调控价格、稳定市场，所需资金纳入财政预算。价格调控专项资金使用情况应当接受财政、审计监督，并向同级人民代表大会或者其常务委员会报告。","level":1},{"name":"第五章 价格监督与服务","text":"第三十条 县级以上人民政府应当建立健全以价格主管部门监督检查为主，行业组织、新闻媒体、社会公众等共同参与的价格监督体系。\n第三十一条 省人民政府价格主管部门应当建立健全公平、透明的市场价格监督管理规则，实施价格公平竞争审查制度，清理妨碍公平竞争的价格规定和措施，促进统一开放、竞争有序的市场体系形成。\n第三十二条 省人民政府价格主管部门依法开展反垄断调查。县级以上人民政府价格主管部门依法对价格活动进行监督检查。单位或者个人应当配合反垄断调查和价格监督检查，如实反映情况，提供有关资料，不得拒绝、阻挠、拖延。\n反垄断调查和价格监督检查人员不得泄露反垄断调查和价格监督检查中知悉的当事人的商业秘密和个人隐私。\n第三十三条 有下列情形之一的，县级以上人民政府价格主管部门可以采取书面通知、约谈、公告等方式，提醒告诫相关经营者、行业组织等履行法定价格义务和不履行义务需要承担的法律责任：\n（一）市场价格总水平出现剧烈波动等异常状态；\n（二）重要商品和服务价格异常波动或者可能异常波动；\n（三）社会反映强烈的价格问题；\n（四）重大价格政策出台；\n（五）重大活动期间。\n第三十四条 在经营者自主定价领域，政府定价机构应当依法制定相应的监督管理办法，加强对经济社会影响重大、与民生紧密相关价格的监督管理；对存在市场竞争不充分、交易双方地位不对等或者市场信息不对称等问题的领域，应当依法制定相应的价格行为规范，合理引导经营者价格行为。\n县级以上人民政府价格主管部门对公众投诉频繁、矛盾突出的价格，应当开展成本调查，向社会公开调查和处理结果。\n第三十五条 对涉案财物、有偿服务价格不明或者有争议的，经有关国家机关提出后，价格主管部门的价格认定机构应当依法进行价格认定。\n第三十六条 县级以上人民政府价格主管部门应当建立健全价格法律、政策、信息等方面的咨询服务制度和价格争议调解机制，根据经营者、消费者以及行业组织的申请，及时提供咨询服务或者组织调解价格争议。\n第三十七条 县级以上人民政府价格主管部门应当建立健全价格信用制度体系，建立经营者价格信用档案，按照规定公布失信者单位名称或者个人姓名，并与有关部门对失信者实施联合惩戒。\n第三十八条 任何单位和个人都有权举报、投诉价格违法行为。\n县级以上人民政府价格主管部门应当完善价格违法行为举报、投诉制度，建立健全价格举报、投诉信息系统，公布电话、通信地址等，及时受理和处理，并为举报和投诉者保密。\n举报、投诉事项办结后，应当及时将办理结果告知举报、投诉者。","level":1},{"name":"第六章 法律责任","text":"第三十九条 违反本条例规定，法律、法规有规定的，从其规定。\n第四十条 经营者违反本条例第八条规定，不执行政府定价机构依法制定的价格行为规范的，由价格主管部门责令限期改正；逾期不改正的，纳入失信者名单。\n经营者违反本条例第八条规定，拒不提供成本监审等相关资料或者不按照规定公开成本的，由价格主管部门责令限期改正，予以警告；逾期不改正的，处1万元以上5万元以下罚款。\n第四十一条 经营者违反本条例第九条第二款规定的，由价格主管部门责令限期改正，没收违法所得；逾期不改正的，处违法所得三倍以下罚款；没有违法所得的，处5万元以上20万元以下罚款；情节严重的，责令停业整顿，并处20万元以上50万元以下罚款。\n第四十二条 相对封闭区域的经营者违反本条例第十一条第一款规定，未明码标价的，由价格主管部门责令改正，没收违法所得，并处1千元以上5千元以下罚款。\n相对封闭区域内的业主或者管理单位违反本条例第十一条第二款规定，不按照规定向社会公布有关价格信息的，由价格主管部门责令限期改正；逾期不改正的，处2千元以上1万元以下罚款。\n第四十三条 网络平台经营者违反本条例第十二条第二款规定，不依法核存并公布网络销售商品或者提供服务经营者提交的身份信息、价格信息的，由工商行政管理部门、价格主管部门责令限期改正；逾期不改正的，纳入失信者名单，处以1万元以上3万元以下的罚款。\n第四十四条 行业组织违反本条例第十三条规定，制定排除或者限制价格竞争的规则、决定、通知的，由省人民政府价格主管部门责令限期改正；逾期不改正的，处20万元以上50万元以下罚款；情节严重的，由登记管理机关依法撤销登记。\n第四十五条 行政事业性收费单位违反本条例第二十一条规定的，由价格主管部门责令停止违法行为，限期退还违法收取的费用；无法退还的，予以没收，对收费单位处违法收取费用一倍以下罚款；由有权机关对直接负责的主管人员和其他直接责任人员依法给予处分。\n第四十六条 国家机关及其工作人员违反本条例规定，有下列行为之一的，由其主管机关或者监察机关依法对直接负责的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任：\n（一）不按照规定制定、调整价格和收费标准的；\n（二）不按照规定实施定价成本监审、公开成本监审结论，或者弄虚作假导致成本监审结论失真的；\n（三）不按照规定开展价格监测预警、发布监测预警信息的；\n（四）违法干预政府定价机构及其工作人员履行法定职责的；\n（五）其他滥用职权、玩忽职守、徇私舞弊的行为。","level":1},{"name":"第七章 附则","text":"第四十七条 本条例自2016年6月1日起施行。2000年6月1日湖北省第九届人民代表大会常务委员会第十八次会议通过的《湖北省实施〈中华人民共和国价格法〉办法》同时废止。","level":1}]},{"id":"h0180","sections":[{"name":"","text":"（2016年7月28日湖北省第十二届人民代表大会常务委员会第二十三次会议通过 根据2020年6月3日湖北省第十三届人民代表大会常务委员会第十六次会议《关于集中修改食品药品安全领域地方性法规的决定》第一次修正 根据2021年7月30日湖北省第十三届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及优化营商环境省本级地方性法规的决定》第二次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第三次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了保证食品安全，保障公众身体健康和生命安全，根据《中华人民共和国食品安全法》以及有关法律、行政法规，结合本省实际，制定本条例。\n第二条 在本省行政区域内从事食品、食品添加剂、食品相关产品生产经营和安全管理活动，应当遵守本条例。\n食用农产品的市场销售及其监督管理，适用本条例。\n第三条 食品生产经营者承担食品安全主体责任，对其生产经营食品的安全负责。\n食品生产经营者应当按照法律、法规和食品安全标准从事生产经营活动，恪守职业道德，诚信自律，接受社会监督，承担社会责任。\n第四条 县级以上人民政府应当对本行政区域内的食品安全监督管理工作负责，实行食品安全监督管理责任制，建立健全食品安全信用体系，完善食品安全评议、考核、奖惩机制，加强食品安全监督管理能力建设，将食品安全工作经费列入本级财政预算，为食品安全工作提供保障。\n第五条 县级以上人民政府食品安全委员会承担下列职责：\n（一）研究部署、统筹指导本行政区域内的食品安全工作；\n（二）制定食品安全监督管理的重大政策措施；\n（三）研究、协调、决定有关食品安全监督管理职责；\n（四）督促落实、考核评价食品安全监督管理责任；\n（五）组织协调食品安全事故应急处置和调查处理工作；\n（六）建立健全协调联动、综合监督管理和信息共享机制；\n（七）本级人民政府规定的其他职责。\n食品安全委员会办公室承担食品安全委员会的日常工作。\n第六条 县级以上人民政府食品安全监督管理部门负责对本行政区域内的食品生产经营活动实施监督管理。\n县级以上人民政府卫生健康、农业农村、住房和城乡建设、公安、出入境检验检疫等部门，按照各自职责共同做好食品安全监督管理工作。\n县级人民政府食品安全监督管理部门可以在乡镇或者特定区域设立派出机构。\n第七条 乡镇人民政府、街道办事处对本行政区域内的食品安全监督管理工作负责，明确专门人员，具体承担食品安全隐患排查、信息报告、协助执法和宣传引导等职责。\n乡镇人民政府、街道办事处应当在村（居）民委员会、社区聘用食品安全协管员或者信息员，协助做好食品安全监督管理工作。\n第八条 各级人民政府及有关部门、社会组织、基层群众性自治组织以及新闻媒体应当开展食品安全法律、法规以及食品安全标准和知识的宣传普及，倡导和培育健康、科学的食品安全文化，提高食品安全意识。\n第九条 食品行业协会应当建立完善行业自律机制，制定并组织实施行业职业道德准则，规范行业行为，推进行业诚信建设。\n消费者协会和其他消费者组织应当提高公众食品安全自我保护能力和维权意识，依法维护消费者的合法权益。","level":1},{"name":"第二章 食品生产经营","text":"","level":1},{"name":"第一节 一般规定","text":"第十条 从事食品生产、食品销售、餐饮服务，应当依法取得许可。销售食用农产品和仅销售预包装食品的除外。仅销售预包装食品的，应当报所在地县级以上人民政府食品安全监督管理部门备案。\n第十一条 建立食品安全全程追溯制度。\n食品生产经营者应当严格执行进货查验记录、出厂检验记录、销售记录等制度，建立完善食品安全追溯体系，保证食品可追溯。\n省人民政府食品安全监督管理部门会同同级农业农村主管部门等有关部门建立食品安全全程追溯协作机制，推进食品安全信息化追溯体系建设。\n鼓励和支持食品生产经营者运用物联网、云计算等现代信息技术建设追溯体系，对食品生产、贮存、运输和销售等环节进行全程的质量控制和追踪，提升食品安全管理水平，保障食品安全。\n第十二条 食品生产经营者采购食品、食品添加剂、食品相关产品时应当按照规定向供货者索取可追溯的销售凭证和查验质量合格证明文件，并查验其营业执照、生产经营许可证，每年复核不少于一次。\n采购婴幼儿配方乳粉应当按照批次查验质量合格证明文件。\n实行统一配送经营方式的食品经营企业，其分支机构应当建立配送食品台账；采用电子化管理的，应当保证各分支机构可以在其经营场所查询食品台账。\n第十三条 食品生产经营者应当按照国家有关规定和食品安全标准使用食品添加剂，不得超范围、超限量使用。\n食品生产经营者应当建立食品添加剂使用记录制度，如实记录使用食品添加剂的名称、使用范围、使用量、使用日期等事项，并在其生产经营场所进行公示。记录保存期限不得少于二年。\n食品生产经营者贮存食品添加剂，应当使用专用贮存设施，并标示“食品添加剂”字样。\n第十四条 食品生产者在食品生产许可证或者食品生产加工小作坊生产许可证有效期限内连续停产六个月以上的，应当在恢复生产后七日内向所在地食品安全监督管理部门备案。\n第十五条 从事保健食品经营的，应当依法取得相应的许可，并在许可的范围、地点从事保健食品经营活动。\n以会议或者讲座等形式宣传推介保健食品的，其宣传内容应当真实、全面，与广告审批部门批准的内容一致，不得作夸大功能、虚假或者误导消费者的宣传，不得在许可的经营场所以外进行现场销售。\n第十六条 利用自动售货设备从事食品销售的，应当在自动售货设备的显著位置公示经营者名称、地址、联系方式、营业执照、食品经营许可证等信息。自动售货设备、商品及其放置地点应当符合食品安全条件，对到期食品应当及时更换。\n利用电视购物从事食品销售的，应当以便于消费者识别的方式公示经营者名称、联系方式、营业执照、食品经营许可证等信息。\n第十七条 入网食品生产经营者应当依法取得许可，法律、法规规定不需要取得食品生产经营许可的除外。通过第三方平台进行交易的食品生产经营者应当在其经营活动主页面显著位置公示其许可证；通过自建网站交易的食品生产经营者应当在其网站首页显著位置公示营业执照、食品生产经营许可证等信息。\n第十八条 网络食品交易第三方平台提供者应当建立入网食品生产经营者审查登记、销售食品信息审核、食品安全检查、违法行为处理、投诉举报处理等管理制度，并在网络平台上予以公开。\n网络食品交易第三方平台提供者应当对入网食品生产经营者进行实名登记，审查其食品生产经营许可证等材料，并建立档案；设置专门的网络食品安全管理机构或者指定专职食品安全管理人员，对平台上的食品经营行为及信息进行检查。\n第十九条 学校实行食品安全校长负责制，建立健全食品安全管理制度以及突发事件的应急制度，配备专职或者兼职的食品安全管理人员，加强食品安全的日常管理，消除食品安全隐患。\n学校食堂应当建立严格的食品安全岗位责任制度，执行食品安全相关标准和操作规程；推行学校食堂食品安全视频监控，保障学校用餐安全。\n第二十条 餐饮服务提供者对外配送食品，应当使用专用封闭工具；分装、贮存、运输食品的容器、用具、温度和时间应当符合食品安全要求。\n从事集体用餐配送的，应当在食品容器或者包装显著位置注明配送单位、制作时间、保质期、贮存条件和食用方法等，并按照规定留存配送食品的样品。\n利用互联网经营的餐饮服务提供者，应当取得包含网络经营的食品经营许可；从事集体用餐配送的，应当取得包含集体用餐配送经营的食品经营许可。\n第二十一条 餐饮服务提供者应当保障消费者对食品安全的知情权和监督权。鼓励餐饮服务提供者通过设立透明式、开放式、视频监控式厨房等形式，展示食品加工制作过程，接受社会监督。\n第二十二条 食品生产经营者委托仓储、物流配送企业贮存、运输食品的，应当对受托的仓储、物流配送企业的食品安全保障能力进行审查。\n从事食品贮存、运输的，应当保证食品贮存、运输的容器、工具和设备安全清洁、无毒无害，并符合食品安全所需的温度、湿度等要求。\n受托从事食品贮存、运输的，应当按照规定查验委托方身份证明、食品生产经营许可证、营业执照以及合格证明文件、检验检疫证明等材料，并承担贮存和运输过程中的食品安全责任。\n第二十三条 为食品生产经营、冷藏冷冻、贮存等提供场所的出租者，应当查验食品生产经营者的许可证、营业执照等，并留存复印件；发现有食品安全违法行为的，应当及时报告所在地食品安全监督管理部门。\n第二十四条 食品交易会、展销会的举办者应当建立食品经营者档案，记录食品经营者的基本情况、许可证、经营范围和商品信息，并在举办前三个工作日向所在地食品安全监督管理部门报告，告知举办地点、举办时间、经营范围、经营规模、管理措施等信息。\n第二十五条 食品生产加工小作坊、小餐饮实行许可管理制度，食品摊贩实行登记管理制度；实施许可和登记不得收取任何费用。\n食品生产加工小作坊、小餐饮经营者应当按照许可的范围生产经营食品。未经许可或者登记的食品生产加工小作坊、小餐饮和食品摊贩不得从事食品生产经营活动。\n第二十六条 申请食品生产加工小作坊、小餐饮许可的，所在地县级人民政府食品安全监督管理部门应当进行现场核查，对符合规定条件的，在十个工作日内颁发食品生产加工小作坊生产许可证、小餐饮经营许可证；对不符合规定条件的，不予许可并书面告知理由。\n食品生产加工小作坊生产许可证、小餐饮经营许可证有效期为三年，有效期届满继续生产经营的，食品生产加工小作坊、小餐饮经营者应当在有效期届满三十日前向原发证机关申请延续。原发证机关收到申请后，应当进行现场核查，对符合规定条件的，应当在十个工作日内办理换证手续。\n食品生产加工小作坊、小餐饮许可事项发生变化的，应当在十个工作日内向原发证机关申请办理变更手续。对符合要求的，原发证机关应当在十个工作日内办理变更手续。\n第二十七条 食品生产加工小作坊、小餐饮和食品摊贩生产经营食品应当符合食品安全标准，并遵守下列规定：\n（一）食品原料、食品添加剂及食品相关产品来源合法并符合食品安全标准和国家相关规定；\n（二）用水符合国家规定的生活饮用水卫生标准；\n（三）食品添加剂使用符合有关食品安全标准和国家相关规定；\n（四）使用的洗涤剂、消毒剂等对人体安全、无害；\n（五）接触食品的餐具、饮具、设备和包装材料无毒、无害、清洁，一次性使用的包装容器和材料不得回收循环使用；\n（六）生产加工、贮存、运输和装卸食品的容器、工具和设备安全、无害，保持清洁，防止食品污染，并符合保证食品安全所需的温度、湿度等特殊要求，不得将食品与有毒、有害物品一同贮存、运输；\n（七）从事接触直接入口食品工作的生产经营人员应当持有效的健康证明，从事食品生产经营活动时穿戴清洁的工作衣、帽，保持个人卫生；\n（八）法律、法规规定的其他要求。","level":2},{"name":"第二节 食用农产品的市场销售","text":"第二十八条 县级以上人民政府食品安全监督管理部门负责食用农产品市场销售的质量安全监督管理。\n县级以上人民政府农业农村、食品安全监督管理部门应当建立食用农产品产地准出和市场准入衔接机制，保障食用农产品的质量安全。\n第二十九条 食用农产品集中交易市场（含批发市场、零售市场）开办者应当履行下列职责：\n（一）建立健全食用农产品质量安全管理制度，配备食品安全管理人员，组织食品安全知识培训，开展日常检查工作；\n（二）按照食用农产品类别实行分区销售，保证销售和贮存食用农产品的环境、设施、设备等符合食品安全要求；\n（三）建立食用农产品入场销售者档案，记录入场销售者基本信息，留存入场销售者的身份证明资料，档案或者证明资料保存期限不少于销售者停止销售后的六个月；\n（四）查验入场销售食用农产品的产地证明、购货凭证或者采购协议等来源证明和质量合格证明文件；\n（五）印制并督促入场销售者使用格式统一的销售凭证；\n（六）在市场醒目位置设置信息公示栏，公示食品安全管理制度、食用农产品检验结果、不合格食用农产品处理情况、投诉举报电话等信息。\n食用农产品批发市场开办者，除履行前款规定的职责外，还应当与入场销售者签订食用农产品质量安全协议，明确双方食用农产品质量安全权利义务；未签订食用农产品质量安全协议的，不得进入批发市场进行销售。\n第三十条 食用农产品批发市场应当配备检验设备和检验人员，或者委托具有资质的食品检验机构，对进入该批发市场销售的食用农产品进行快速检测或者抽样检验，并及时公布结果。\n食用农产品零售市场应当配备快速检测设备，每天抽查场内食用农产品，及时公布快检结果。\n第三十一条 建立食用农产品市场准入制度。食用农产品进入集中交易市场销售，销售者应当提供身份证明、产地证明或者购货凭证、合格证明文件。无法提供身份证明的，不得进入市场销售；无法提供产地证明、购货凭证、合格证明文件之一的，集中交易市场开办者应当进行抽样检验或者快速检测。检验检测合格的，方可进入市场销售，农民个人销售其自产自销的少量食用农产品除外。\n食用农产品生产企业和农民专业合作经济组织进入市场销售的，应当提供社会信用代码和合格证明文件。\n销售畜禽产品的，应当按照规定提供检疫证明；销售猪肉产品的，除提供检疫证明外，还应当提供肉品品质检验合格证明。\n销售进口食用农产品的，应当提供入境货物检验检疫证明。\n第三十二条 食用农产品销售者应当建立食用农产品进货查验记录制度，如实记录食用农产品名称、数量、进货日期以及供货者名称、地址、联系方式等内容，保存相关凭证。\n鼓励和支持有条件的食用农产品销售者采用电子数据追溯，建立食用农产品进货查验记录制度。","level":2},{"name":"第三节 食品生产加工小作坊","text":"第三十三条 从事食品生产加工的小作坊，应当符合下列条件，取得食品生产加工小作坊生产许可证：\n（一）具有与生产加工的食品品种、数量相适应的食品原料处理和食品加工、包装、贮存、经营等场所，生产经营区和生活区有效分隔，保持生产经营场所环境整洁，并与有毒、有害场所以及其他污染源保持规定的距离；\n（二）具有与生产加工的食品品种、数量相适应的生产设备、设施以及卫生防护设施；\n（三）具有合理的设备布局和工艺流程，防止待加工食品与直接入口食品、原料与成品交叉污染，避免食品接触有毒物、不洁物；\n（四）具有保证食品安全的管理制度；\n（五）法律、法规规定的其他要求。\n第三十四条 申请食品生产加工小作坊生产许可的，所在地县级人民政府食品安全监督管理部门应当核实以下信息：\n（一）申请书；\n（二）营业执照；\n（三）开办者的身份证及联系方式；\n（四）生产加工场所平面图及其使用证明；\n（五）主要食品原辅料、食品添加剂使用情况说明；\n（六）拟生产的食品品种和生产工艺说明；\n（七）生产加工场所的卫生与安全情况说明。\n第三十五条 食品生产加工小作坊生产许可证应当载明食品生产加工小作坊名称、经营者姓名、许可证编号、生产加工地址、生产加工范围等信息。\n食品生产加工小作坊应当在其生产经营场所显著位置公示营业执照、食品生产加工小作坊生产许可证、从业人员健康证明以及食品添加剂使用情况等信息，接受社会监督。\n第三十六条 禁止食品生产加工小作坊生产加工食品添加剂和下列食品：\n（一）保健食品、特殊医学用途配方食品和婴幼儿配方食品等特殊食品；\n（二）乳制品、罐头食品、瓶（桶）装饮用水、采用非固态法发酵工艺生产的白酒、配制酒；\n（三）采用非物理压榨方法生产加工的食用植物油和其他食用油脂及其制品；\n（四）国家和省规定禁止生产加工的其他食品。\n市（州）人民政府食品安全监督管理部门应当根据本地实际情况，制定食品生产加工小作坊禁止生产加工的食品目录，向社会公布，并根据食品安全监督抽检结果、食品安全风险评估结果适时进行调整。\n第三十七条 食品生产加工小作坊采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明，建立进货台账，如实记录供货者的名称、地址、联系方式、采购数量和时间等内容。\n食品生产加工小作坊应当建立生产销售台账，如实记录生产销售食品的名称、规格、数量、生产日期、保质期、销售日期、销售去向等内容。\n进货和生产销售台账保存期限不得少于食品保质期满后六个月；没有明确保质期的，保存期限不得少于一年。\n第三十八条 食品生产加工小作坊生产加工的预包装食品应当有包装和标签，标明食品名称、成分表或者配料表、生产日期、保质期以及小作坊的名称、生产地址、联系方式、许可证编号等信息。\n食品生产加工小作坊生产加工的散装食品，应当在散装食品的容器、外包装或者外置标签牌上标明食品的名称、生产日期、保质期，小作坊的名称、地址、联系方式等信息。\n第三十九条 省人民政府食品安全监督管理部门应当制定食品生产加工小作坊作业规范，加强食品生产加工小作坊监督指导。\n食品生产加工小作坊应当建立食品安全自查制度，定期对食品安全状况进行检查，发现不符合食品安全要求的，应当立即停止生产销售并采取整改措施。\n食品生产加工小作坊应当对新投产、停产后重新恢复生产以及改变生产工艺后生产的首批食品，委托有资质的检验机构进行检验，检验合格并报许可部门备案后，方可生产销售。","level":2},{"name":"第四节 小餐饮","text":"第四十条 从事小餐饮服务活动，应当符合下列条件，取得小餐饮经营许可证：\n（一）具有固定的经营场所，保持经营场所环境卫生整洁，与污染源保持规定的距离；\n（二）食品经营场所设在室内，食品处理区与就餐场所、卫生间有效隔离，制作冷荤凉菜应当设置专用操作间；\n（三）食品处理区各功能区布局合理，粗加工、烹饪、餐用具清洗消毒、食品原辅材料贮存等场所分区明确，防止食品在存放、操作中产生交叉污染；\n（四）具有与加工经营食品相适应的冷冻冷藏、排烟、防尘、防鼠、防虫害以及收集废水和废弃物的设备设施；\n（五）加工操作场所设置专用清洗设施，其数量或者容量应与加工食品的品种、数量相适应；\n（六）具有保证食品安全的管理制度；\n（七）法律、法规规定的其他要求。\n第四十一条 申请小餐饮经营许可的，所在地县级人民政府食品安全监督管理部门应当核实以下信息：\n（一）申请书；\n（二）营业执照；\n（三）经营者身份证及联系方式；\n（四）餐饮服务经营场所和设备布局、加工流程、卫生与安全设施等示意图。\n第四十二条 小餐饮经营许可证应当载明小餐饮服务单位名称、经营者姓名、许可证编号、经营地址、经营范围等信息。\n小餐饮服务提供者应当在就餐场所显著位置公示小餐饮经营许可证、营业执照、从业人员健康证明和食品添加剂使用情况等相关信息。\n第四十三条 禁止小餐饮服务提供者经营裱花类糕点、生食类水产品、自制生鲜乳饮品以及国家和省规定禁止经营的其他食品。","level":2},{"name":"第五节 食品摊贩","text":"第四十四条 乡镇人民政府、街道办事处应当根据国土空间规划要求，按照方便群众、合理布局、保障安全的原则，统筹考虑交通、市容、环境等因素，划定食品摊贩经营区域或者指定路段，确定经营时段供食品摊贩经营，并向社会公布。幼儿园、中小学校门口道路两侧一定范围内禁止食品摊贩经营，具体范围由乡镇人民政府、街道办事处规定。\n食品摊贩应当在指定的经营地点、确定的经营时段从事食品经营活动，保持周边环境卫生整洁，不得影响道路通畅、交通安全。\n第四十五条 乡镇人民政府、街道办事处负责本区域食品摊贩的登记工作，并将食品摊贩登记信息告知所在地的城市管理、食品安全监督管理部门。\n城市管理部门负责对食品摊贩在确定的区域和时段经营进行监督管理。食品安全监督管理部门负责对食品摊贩的食品安全进行监督管理。城市管理部门、食品安全监督管理部门应当加强协调、配合，做好食品摊贩的监督管理工作。\n第四十六条 食品摊贩经营者应当持有效健康证明向所在地乡镇人民政府、街道办事处登记，取得食品摊贩登记卡。\n食品摊贩登记卡有效期为一年，有效期届满继续经营的，食品摊贩经营者应当在有效期届满一个月前办理延续手续。\n食品摊贩经营者应当在其摊位显著位置公示食品摊贩登记卡。\n第四十七条 食品摊贩从事食品经营活动应当符合下列条件：\n（一）经营场所与垃圾堆放点等污染源保持25米以上的距离，保证食品不受污染；\n（二）具有符合食品卫生条件的食品制作和销售的亭（棚、车、台）等设施；\n（三）提供即食食品的，应当根据食品的种类配备相应的加热、保温或者冷藏、冷冻设备；\n（四）具有防尘、防虫、防蝇等设施以及密闭的废弃物收集设施；\n（五）食品容器和包装材料应当清洁、无毒、无害，符合食品卫生和包装材料要求；\n（六）餐具使用前按照规定清洗、消毒，不具备清洗、消毒条件的，应当使用符合规定的一次性餐饮具或者采用集中式消毒餐饮具；\n（七）法律、法规规定的其他要求。\n第四十八条 禁止食品摊贩经营下列食品：\n（一）不经复热处理的熟食，自制生鲜乳饮品；\n（二）发酵酒以外的散装酒；\n（三）国家和省规定禁止生产经营的其他食品。","level":2},{"name":"第三章 食品安全保障","text":"","level":1},{"name":"第一节 风险监测和食品安全标准","text":"第四十九条 省人民政府卫生健康主管部门会同同级食品安全监督管理、农业农村等部门，根据国家食品安全风险监测计划，制定、调整本行政区域食品安全风险监测方案，报国务院卫生健康主管部门备案并实施。市（州）人民政府卫生健康主管部门根据省食品安全风险监测方案，制定本行政区域食品安全风险监测方案，报省人民政府卫生健康主管部门备案。\n第五十条 省人民政府卫生健康主管部门应当加强食品安全风险监测能力建设，会同有关部门制定本省风险监测能力建设规划，建立覆盖县市区的食品安全风险监测工作网络，并逐步向社区、农村延伸。\n第五十一条 县级以上人民政府卫生健康主管部门会同同级食品安全监督管理等部门建立食品安全风险监测数据通报、会商机制，汇总、分析风险监测数据，形成食品安全风险监测分析报告，并报同级人民政府。\n第五十二条 对地方特色食品，没有食品安全国家标准的，省人民政府卫生健康主管部门应当会同同级食品安全监督管理部门制定食品安全地方标准。食品安全地方标准由省人民政府卫生健康主管部门公布，并报国务院卫生健康主管部门备案。\n食品安全地方标准应当包括地方特色食品及其原料、地方特色食品生产经营过程的卫生要求、质量要求以及检验方法与规程等内容。标准制定应当充分考虑地方食品特点和传统饮食习惯，广泛听取各方面意见，并经省人民政府卫生健康主管部门组织的食品安全地方标准审评委员会审查通过。\n食品安全监督管理相关部门、食品生产经营者、食品行业协会、科研机构等可以向省人民政府卫生健康主管部门提出制定或者修订地方标准的建议。省人民政府卫生健康主管部门认为需要制定或者修订地方标准的，应当及时组织制定或者修订。\n第五十三条 食品生产企业制定的本企业适用的食品安全标准应当报省人民政府卫生健康主管部门备案。发现备案的食品安全标准违反有关法律法规，或者低于食品安全国家标准、地方标准的，省人民政府卫生健康主管部门应当予以纠正。","level":2},{"name":"第二节 食品检验","text":"第五十四条 省人民政府应当统筹规划全省食品检验体系建设，明确省、市、县食品检验机构建设标准和检验职能，建立全省统一的食品检验平台，实行检验信息、资源共享。\n县级以上人民政府应当加强食品安全检验能力建设，整合本行政区域内的食品检验资源，建立统一的食品检验机构，将食品检验设施设备、抽检经费等纳入本级财政预算予以保障。\n第五十五条 县级以上人民政府应当组织本级食品安全监督管理、农业农村等部门制定本行政区域的食品安全年度监督抽检计划，明确抽样检验的重点领域、重点企业、重点品种，进行定期或者不定期的抽样检验，并依照相关规定向社会公布检验结果。\n县级以上人民政府食品安全监督管理部门可以委托具有检验资质的食品检验机构进行抽样工作。\n第五十六条 食品生产企业可以设立食品检验机构，配备相应的食品检验设备和检验人员，对所生产的食品进行检验。不具备设立检验机构条件的，应当委托具有法定资质的食品检验机构进行检验。\n第五十七条 鼓励和支持高等院校、科研院所和第三方食品检验机构，研究、开发、应用食品安全科学检测方法。通过购买服务等方式支持第三方食品检验机构参与食品检验和风险监测。","level":2},{"name":"第三节 监督管理","text":"第五十八条 县级以上人民政府食品安全监督管理、农业农村等部门应当根据食品安全风险监测、安全状况和信用信息等，确定监督管理的重点、方式和频次，实施风险分级管理。\n消费量较大、安全风险较高的食品，专供婴幼儿、其他特定人群的主辅食品和保健食品等，应当作为监督管理的重点。\n第五十九条 省人民政府食品安全监督管理部门应当推进全省食品安全信用体系建设，制定食品生产经营者信用分级分类管理评定标准，建立食品安全信用评价制度和奖惩机制。\n食品安全信用信息应当作为食品安全监督管理部门行政审批和日常监管的重要参考。对存在严重失信行为的食品生产经营者，可以依法向社会进行披露，并按照规定由有关部门对其进行联合惩戒。\n第六十条 县级以上人民政府卫生健康主管部门履行餐具、饮具集中消毒的监督管理职责，加强餐具、饮具集中消毒服务单位的日常卫生监督检查，对集中消毒餐具、饮具进行定期抽检；抽检不合格的，应当依法处理。\n第六十一条 各级人民政府应当对食品生产加工小作坊、小餐饮和食品摊贩进行综合治理，统筹规划、建设、改造适宜食品生产加工小作坊、小餐饮和食品摊贩生产经营的集中场所和街区，配套建设相应的供水、供电、排污等设施，改善生产经营环境。\n鼓励社会力量参与食品生产加工小作坊、小餐饮、食品摊贩集中经营场所和街区建设。\n第六十二条 食品安全监督管理部门应当对农村自办集体聚餐活动进行监督和指导，加强集体聚餐食品安全宣传教育，健全完善申报备案制度、流动厨师培训制度、食品安全事故报告和应急处置等制度。\n第六十三条 县级以上人民政府应当加强餐厨废弃物的管理，建立健全餐厨废弃物管理体系以及工作协调机制，防止以餐厨废弃物作为原料生产加工的食品进入食品生产经营环节；支持餐厨废弃物资源化利用和无害化处理项目建设，促进资源循环利用。餐厨废弃物的具体管理办法由省人民政府制定。\n第六十四条 食品安全监督管理部门在监督检查中发现食品生产经营者或者食用农产品销售者存在严重违法行为，可以将违法生产经营者、违法事项、行政处理决定等内容在其生产经营场所进行公布。\n第六十五条 食品安全监督管理部门在监督检查中现场发现食品腐败变质、霉变生虫、掺杂异物以及其他感官性状异常的，可以通过视听图像和现场检查笔录等方式记录现场情况，经当事人签字。当事人拒绝签字或者其他特殊原因不能签字，且无第三方人员证明的，应当注明原因，并由两名以上在场执法人员签字确认。\n第六十六条 县级以上人民政府应当建立健全食品安全监督管理相关部门与公安机关、人民检察院、人民法院的食品安全行政执法与刑事司法相衔接的工作机制，明确线索通报、案件移送、案情会商、信息共享等制度，协调、督促食品安全违法犯罪查处工作。","level":2},{"name":"第四章 信息公开和社会参与","text":"第六十七条 省人民政府食品安全监督管理部门应当建立健全食品安全信息平台和食品安全信用信息数据库，确定各类信息公开共享范围，及时向社会公开与发布。\n县级以上人民政府食品安全监督管理、农业农村等部门根据各自的职责发布食品安全日常监督管理信息，并相互通报各自获知的食品安全信息。\n食品安全风险警示信息、食品安全重大事故调查信息由省人民政府食品安全监督管理部门依法统一发布。\n第六十八条 任何单位和个人有权对食品安全管理决策活动提出意见和建议。\n除依法需要保密外，与食品安全有关的风险监测方案、地方标准制定、规划编制、生态环境影响评价以及其他事项应当公开，并通过听证会、论证会、座谈会等形式，向公众说明情况，充分征求意见。\n第六十九条 任何组织和个人有权举报食品安全违法行为。\n接受举报的机关应当对举报人的信息保密，对举报属实的予以奖励。\n县级以上人民政府应当建立食品安全举报奖励制度，设立食品安全举报奖励专项资金，用于食品安全举报的奖励。\n第七十条 县级以上人民政府建立统一的食品安全咨询、建议意见、投诉举报受理平台，公布投诉举报方式，完善投诉举报受理处置机制。\n食品安全监督管理部门接到投诉、举报，对属于本部门职责的，应当受理并在规定期限内及时进行处理、答复；对不属于本部门职责的，应当及时移交有权处理的部门处理并告知投诉人、举报人。有权处理的部门应当在法定期限内及时处理，不得推诿。\n第七十一条 新闻媒体应当公正、客观报道食品安全信息，正确发挥公众舆论引导和舆论监督作用，弘扬诚实守信的食品安全生产经营行为，依法对食品安全中的违法行为进行曝光，营造良好的食品安全社会舆论环境。","level":1},{"name":"第五章 法律责任","text":"第七十二条 违反本条例，法律、法规有规定的，从其规定；造成人身、财产或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第七十三条 违反本条例第十五条规定，在许可的经营场所以外进行保健食品销售的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法经营的食品；违法经营的食品货值金额不足5000元的，处1万元以上5万元以下罚款；货值金额5000元以上的，处货值金额10倍以上20倍以下罚款。\n第七十四条 违反本条例第十八条规定，网络食品交易第三方平台提供者未按照要求建立入网食品生产经营者登记、销售食品信息审核、食品安全检查、违法行为处理、投诉举报处理等管理制度的，由县级以上人民政府食品安全监督管理部门责令改正，予以警告；拒不改正的，处5000元以上3万元以下罚款。\n第七十五条 违反本条例规定，未取得食品生产加工小作坊生产许可证、小餐饮经营许可证，或者超出许可范围、许可证有效期届满未按照规定办理延续手续从事食品生产经营活动的，由县级以上人民政府食品安全监督管理部门责令改正，予以警告；拒不改正的，没收违法所得和违法经营的食品，以及用于违法生产经营的工具、设备、原料等物品，并处3000元以上3万元以下罚款。\n第七十六条 食品生产加工小作坊、小餐饮服务提供者违反本条例第二十七条规定的，由县级以上人民政府食品安全监督管理部门责令改正，予以警告；拒不改正的，处3000元以上3万元以下罚款；情节严重的，责令停产停业，直至吊销许可证。\n第七十七条 食用农产品集中交易市场开办者违反本条例第二十九条规定的，由县级以上人民政府食品安全监督管理部门责令改正，予以警告；拒不改正的，处1万元以上3万元以下罚款；情节严重的，责令停业整顿。\n第七十八条 违反本条例第三十六条第一款规定的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品，并可以没收违法生产经营的工具、设备、原料等物品；违法生产经营的食品货值金额不足2000元的，处2000元以上1万元以下罚款；货值金额2000元以上的，处货值金额5倍以上15倍以下罚款；情节严重的，责令停产停业，直至吊销许可证。\n违反本条例第四十三条规定的，由县级以上人民政府食品安全监督管理部门责令改正，予以警告；拒不改正的，处1000元以上1万元以下罚款；情节严重的，责令停产停业，直至吊销许可证。\n第七十九条 食品摊贩违反本条例第四十四条规定，擅自在指定的经营地点、确定的经营时段以外摆摊设点从事食品经营活动的，由县级以上人民政府城市管理部门或者承担城市管理行政执法职能的其他部门依据相关法律法规查处。\n食品摊贩违反本条例第二十七条、第四十六条第三款、第四十七条和第四十八条规定的，由县级以上人民政府食品安全监督管理部门责令改正，予以警告；拒不改正的，处200元以上2000元以下罚款。\n第八十条 有下列情形之一的，由县级以上人民政府食品安全监督管理部门责令改正，予以警告；拒不改正的，处500元以上2000元以下罚款：\n（一）实行统一配送经营方式的食品经营企业，在其分支机构经营场所不能查询食品台账的；\n（二）食品生产经营者未按照规定建立并保存食品添加剂使用记录，未按照规定使用专用贮存设施或者未标示“食品添加剂”字样的；\n（三）利用自动售货设备从事食品经营，未按照规定公示相关信息的；\n（四）餐饮服务提供者未按照规定对外配送食品，从事集体用餐配送未按照规定留存配送食品样品的；\n（五）提供食品生产经营、冷藏冷冻、贮存等场所的出租者，未查验食品生产经营者许可证、营业执照并留存复印件，或者发现有食品安全违法行为未及时报告的；\n（六）食品交易会、展销会的举办者未按照规定建立档案的；\n（七）食品生产加工小作坊未按照规定建立并保存进货、生产销售台账记录，查验相关证明的；\n（八）食品生产加工小作坊、小餐饮未按照规定在其生产经营场所公示相关信息的；\n（九）食品生产加工小作坊生产加工的食品未按照规定包装、标示相关信息的。\n第八十一条 已取得许可证的食品生产加工小作坊、小餐饮不再符合本条例规定的许可条件，继续从事食品生产经营的，由县级以上人民政府食品安全监督管理部门予以警告，责令限期改正；逾期不改正的，责令停产停业；情节严重的，吊销许可证。\n第八十二条 食品生产加工小作坊、小餐饮服务提供者在一年内累计三次因违反本条例规定受到责令停产停业、吊销许可证以外处罚的，由县级以上人民政府食品安全监督管理部门责令停产停业，直至吊销许可证。\n被吊销食品生产加工小作坊生产许可证、小餐饮经营许可证的食品生产经营者，自处罚决定作出之日起五年内，不得申请食品生产加工小作坊生产和小餐饮经营许可。\n第八十三条 国家机关及其工作人员不依法履行食品安全监督管理职责，有滥用职权、玩忽职守、徇私舞弊等行为的，依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第八十四条 本条例下列用语的含义：\n食品安全，是指食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或者慢性危害。\n入网食品生产经营者，是指通过第三方平台或者自建的网站进行交易的食品生产经营者。\n食用农产品市场销售，是指通过集中交易市场、商场、超市、便利店等销售食用农产品的活动。\n食品生产加工小作坊，是指有固定生产经营场所，从业人员较少、生产加工规模小、生产条件和工艺技术简单，从事传统、低风险食品生产加工以及销售活动的个体经营者。\n小餐饮，是指有固定经营场所，从业人员少、设施简单，从事餐饮服务活动的小餐馆、小吃店、小饮品店等个体经营者。\n食品摊贩，是指在有形市场或者固定店铺以外的划定经营区域或者指定经营场所，从事预包装食品或者散装食品销售以及现场制售食品的个体经营者。\n第八十五条 食品生产加工小作坊、小餐饮的规模标准，由市（州）人民政府根据本地的实际情况具体确定。\n第八十六条 本条例自2016年12月1日起施行。","level":1}]},{"id":"h0181","sections":[{"name":"","text":"（2016年7月28日湖北省第十二届人民代表大会常务委员会第二十三次会议通过 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了维护业主和物业服务企业的合法权益，规范物业服务和监督管理活动，营造安全、舒适、文明、和谐的生活和工作环境，根据《中华人民共和国物权法》、《物业管理条例》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内的物业服务及其监督管理活动。\n本条例所称物业服务，是指业主自行或者通过选聘物业服务企业等形式，对房屋及其配套设施设备和相关场地进行维修、养护和管理，维护物业区域内环境卫生和相关秩序的活动。\n第三条 县级以上人民政府应当将物业服务纳入现代服务业发展规划、社区建设规划和社会治理体系，建立物业服务综合协调机制和目标责任制，完善激励政策和措施，促进物业服务发展与和谐社区建设。\n第四条 县级以上人民政府房产行政主管部门负责本行政区域内物业服务活动的监督管理工作，依法履行下列职责：\n（一）对物业服务企业服务质量进行监督管理；\n（二）对物业服务企业组织开展信用评价；\n（三）对物业服务企业及其从业人员、业主委员会进行业务指导、培训和监督管理；\n（四）对物业的使用与维护进行监督管理；\n（五）对物业承接查验、物业服务企业退出交接活动进行指导和监督；\n（六）对住宅专项维修资金的交存、使用进行监督管理；\n（七）建立、维护物业服务和管理电子信息平台；\n（八）处理物业服务活动中的投诉；\n（九）法律、法规规定的其他职责。\n县级以上人民政府城乡规划、建设、公安、民政、生态环境、城市管理、市场监督管理等行政主管部门，按照各自职责共同做好物业服务监督管理工作。\n第五条 街道办事处、乡镇人民政府应当在同级党组织领导和民政部门指导监督下，依法组织和指导本辖区内的业主成立业主大会、选举业主委员会，监督业主大会、业主委员会依法履行职责，协调物业服务与社区管理、社区服务的关系，调解物业服务纠纷；居（村）民委员会协助街道办事处、乡镇人民政府做好与物业服务有关的工作。\n物业服务和管理应当纳入基层精神文明建设的考核内容。\n第六条 街道办事处、乡镇人民政府应当建立物业服务联席会议制度。\n联席会议由街道办事处、乡镇人民政府召集，房产、公安、民政、城市管理等行政主管部门和居（村）民委员会、业主委员会、物业服务企业、专业经营单位等各方代表参加，具体解决物业服务和管理活动中需要协调的问题。\n第七条 物业服务行业协会应当加强行业自律管理，制定物业服务规范和等级标准，建立和完善物业服务企业及其从业人员的自律制度，提高物业服务水平。","level":1},{"name":"第二章 物业区域的规划与建设","text":"第八条 物业区域的划分，应当遵循规划优先、功能完善、资源共享、便民利民的原则。\n城乡规划行政主管部门审查项目规划设计方案时，应当征求房产行政主管部门对物业区域划分的意见。\n第九条 建设单位应当根据建设项目用地规划许可证确定的红线图，结合物业的共用设施设备、社区建设等因素划分物业区域。\n物业配套设施设备共用的，应当划分为一个物业区域；规模过大划分为一个物业区域不便于管理或者已经分割成多个自然街区，且其配套设施设备能够分割、独立使用的，可以划分为不同的物业区域。\n第十条 建设单位应当在取得房屋预售许可或者现房销售前，向房产行政主管部门提出划分物业区域的备案申请。房产行政主管部门应当征求城乡规划行政主管部门、街道办事处、乡镇人民政府、居（村）民委员会等单位的意见，自受理备案申请之日起二十日内核定并予以答复。\n建设单位应当在核定的物业区域内显著位置公示物业区域详细分布图，以及属于全体业主共有部分、共用设施设备的配置和建设标准，并在房屋买卖合同中明示。\n第十一条 已投入使用但尚未划分物业区域或者需要调整物业区域的，由房产行政主管部门征求城乡规划行政主管部门、街道办事处、乡镇人民政府、居（村）民委员会以及相关业主意见后，确定物业区域。\n调整物业区域的，应当经专有部分占建筑物总面积过半数的业主且占总人数过半数的业主同意。\n第十二条 新建住宅的，建设单位应当按照下列要求在物业区域内配置物业服务用房：\n（一）不低于总建筑面积千分之二，且最少不低于一百平方米；\n（二）应当具备通水、通电、通信、采光、通风等基本使用功能和办公条件，配置独立合格的水、电等计量装置。\n物业服务用房属于全体业主共有，任何单位和个人不得分割、转让、抵押，也不得擅自变更用途。\n业主委员会办公用房从物业服务用房中安排，其面积不低于二十平方米。\n第十三条 城乡规划行政主管部门在建设工程规划许可过程中，应当对物业服务用房的设计指标进行审查。\n房产行政主管部门在核发房屋销售许可时，应当对物业服务用房进行核查。\n第十四条 集中建设的保障性住房应当按照不低于总建筑面积千分之三的比例增加配置物业服务经营性用房，由物业服务企业经营管理，收益用于补充物业服务费。\n第十五条 新建住宅物业区域内的供水、供电、供气、供热等专业经营设施设备，应当符合国家技术标准和技术规范，并与主体工程同时设计、同时施工、同时交付。\n建设项目竣工验收合格后，建设单位应当将物业区域内供水、供电、供气、供热等专业经营设施设备移交给专业经营单位维护管理，专业经营单位应当接收。\n第十六条 住宅物业区域内已投入使用的专业经营设施设备尚未移交专业经营单位维护管理的，由业主大会决定是否移交。\n决定移交的，房产行政主管部门应当组织有关专业经营单位按照国家技术标准和技术规范进行验收。验收合格的，专业经营单位应当接收。验收不合格的，由专业经营单位提出整改方案，经整改合格后移交。\n专业经营设施设备尚在质量保修期内的，其整改费用由建设单位承担。\n第十七条 对配套设施设备不齐全的老旧住宅区，县级以上人民政府应当制定老旧住宅区物业改造规划和年度实施计划，加大资金投入，完善配套基础设施和公共服务设施，改善老旧住宅区的综合环境和物业服务。\n街道办事处、乡镇人民政府、居（村）民委员会应当在征求老旧住宅区业主意见后，划分物业区域，并报房产行政主管部门备案。","level":1},{"name":"第三章 业主及业主大会","text":"第十八条 房屋所有权人为业主。尚未登记取得所有权，但基于买卖、赠与、继承、拆迁或者征收补偿等法律行为已经合法占有该房屋的人，认定为物业服务关系中的业主。\n业主可以依法委托物业使用人行使业主权利、履行业主义务。委托应当以书面形式提交业主委员会。\n第十九条 一个物业区域成立一个业主大会，业主大会由物业区域内全体业主组成。业主人数超过三百人的物业区域可以成立业主代表大会，履行业主大会议事规则规定的职责，业主代表的产生方式由业主大会决定。\n业主人数较少且经全体业主一致同意，决定不成立业主大会的，由业主共同履行业主大会、业主委员会职责。\n第二十条 符合下列条件之一的，街道办事处、乡镇人民政府应当组织召开物业区域内首次业主大会会议：\n（一）交付的房屋专有部分面积达到建筑物总面积百分之五十的；\n（二）交付的房屋套数达到总套数百分之五十的；\n（三）自首位业主入住之日起满两年且已入住户数比例达到百分之二十的。\n首次业主大会会议的筹备经费根据物业区域规模、业主人数和建筑面积等因素确定，由建设单位承担；老旧住宅区首次业主大会会议的筹备经费由县级人民政府承担。\n第二十一条 符合首次业主大会会议召开条件的，建设单位应当书面报告房产行政主管部门；业主也可以向房产行政主管部门提出召开首次业主大会会议的书面报告；房产行政主管部门应当书面通知街道办事处、乡镇人民政府。\n街道办事处、乡镇人民政府应当在收到通知之日起三十日内组织成立业主大会会议筹备组，并自筹备组成立之日起六十日内组织召开首次业主大会会议。\n第二十二条 业主大会会议筹备组由街道党工委、办事处或者乡镇党委、人民政府和业主、居（村）民委员会、建设单位的代表组成，其中业主代表人数比例不低于二分之一；业主代表的产生方式由街道办事处、乡镇人民政府征求业主意见后确定。筹备组组长由街道党工委、办事处或者乡镇党委、人民政府的代表担任。\n业主大会会议筹备组应当做好以下工作：\n（一）确认业主身份、业主人数以及业主所有的专有部分面积；\n（二）确定首次业主大会会议召开的时间、地点、形式、内容以及表决规则；\n（三）起草业主公约或者管理规约、业主大会议事规则、业主委员会选举办法、业主委员会工作规则；\n（四）提出首届业主委员会委员候选人名单；\n（五）首次业主大会会议的其他准备工作。\n前款内容应当在首次业主大会会议召开十五日前以书面形式告知全体业主，前款第二项内容还应当在物业区域内显著位置公告。业主对前款内容有异议的，业主大会会议筹备组应当记录、处理并答复。\n第二十三条 建设单位应当在首次业主大会会议召开前向街道办事处、乡镇人民政府报送物业区域证明、房屋及建筑面积清册、业主名册、竣工总平面图、交付使用共用设施设备的证明、物业服务用房配置证明等筹备首次业主大会会议所需的文件资料。街道办事处、乡镇人民政府应当将上述资料建档保存。\n第二十四条 业主大会会议讨论决定下列事项：\n（一）制定和修改业主公约或者管理规约、业主大会议事规则、业主委员会选举办法、业主委员会工作规则；\n（二）选举业主委员会、更换业主委员会委员或者撤销业主委员会委员职务；\n（三）选聘、续聘和解聘物业服务企业或者决定自行管理物业；\n（四）审议业主委员会提交的物业服务合同草案；\n（五）依法筹集、管理、使用住宅专项维修资金；\n（六）改建、重建共有建筑物及其附属设施；\n（七）改变共有部分的用途；\n（八）共用部位、共用设施设备经营的方式和所得收益的管理、分配、使用；\n（九）业主大会、业主委员会工作经费的筹集、管理、使用，以及业主委员会委员津贴的来源、支付标准；\n（十）改变或者撤销业主委员会作出的决定；\n（十一）法律、法规规定应当由业主共同决定的其他事项。\n业主大会的决定，对全体业主具有约束力。\n第二十五条 业主大会决定本条例第二十四条第一款第五项和第六项规定的事项，应当经专有部分占建筑物总面积三分之二以上的业主且占总人数三分之二以上的业主同意；决定其他事项的，应当经专有部分占建筑物总面积过半数的业主且占总人数过半数的业主同意。面积和业主人数按照下列方式确定：\n（一）专有部分面积按照建筑面积计算，建筑物总面积按照专有部分面积之和计算；\n（二）业主人数按照专有部分的数量计算，一个专有部分按照一人计算；建设单位尚未销售和虽已销售但尚未交付的部分，以及同一买受人拥有一个以上专有部分的，按照一人计算；总人数按照以上统计的总和计算。\n第二十六条 业主大会定期会议由业主委员会按照业主大会议事规则的规定组织召开。有下列情形之一的，业主委员会应当组织召开业主大会临时会议：\n（一）业主委员会半数以上委员或者百分之二十以上业主提议的；\n（二）需要提前终止物业服务合同或者重新选聘物业服务企业的；\n（三）业主公约或者管理规约、业主大会议事规则规定的其他情形。\n业主委员会不履行组织召开业主大会会议义务的，街道办事处、乡镇人民政府应当责令业主委员会三十日内组织召开；业主委员会逾期仍不组织召开的，由街道办事处、乡镇人民政府组织召开。\n第二十七条 业主委员会由业主大会依法选举产生，对其负责、受其监督。业主委员会委员名单应当在物业区域内显著位置公告。\n业主委员会由五至十一人单数组成，每届任期不超过五年，可以连选连任。业主委员会主任、副主任由业主委员会在业主委员会委员中推选产生。\n业主委员会委员只能由业主担任并履行职责，不得由他人代理。业主委员会委员出现空缺时，应当按照规定及时补足；缺额人数超过委员总人数百分之五十的，应当重新选举业主委员会。\n第二十八条 业主委员会应当自选举产生之日起三十日内，将业主大会决议和业主委员会委员名单向房产行政主管部门和街道办事处、乡镇人民政府备案。\n业主委员会持备案证明向公安机关申请刻制业主大会和业主委员会印章。业主大会印章根据业主大会决定使用；业主委员会印章经半数以上委员签字同意方可使用。\n第二十九条 业主委员会应当履行下列职责：\n（一）执行业主大会的决定和决议；\n（二）召集业主大会会议，定期向业主大会报告工作，并在物业区域内显著位置公布书面报告，接受业主询问；\n（三）根据业主大会决定，代表业主与业主大会选聘或者续聘的物业服务企业签订物业服务合同；\n（四）及时了解业主、物业使用人的意见和建议，监督物业服务企业履行物业服务合同，协调处理物业服务活动中的相关问题，维护业主合法权益；\n（五）督促业主、物业使用人遵守业主公约或者管理规约，调解因物业使用、维护和管理产生的纠纷；\n（六）组织、监督住宅专项维修资金的筹集和使用；\n（七）根据业主大会决定或者授权，决定共用部位、共用设施设备的经营方式和所得收益的管理、分配、使用，并公布经营所得收益和支出情况；\n（八）配合街道办事处、乡镇人民政府、居（村）民委员会、公安机关等做好物业区域内的社会治安、社区建设和公益宣传等工作；\n（九）法律、法规和业主公约或者管理规约规定的其他职责。\n业主委员会会议应当有过半数的委员出席，作出的决定应当经全体委员过半数同意。\n第三十条 业主委员会委员不得有下列行为：\n（一）拒绝或者放弃履行委员职责；\n（二）挪用、侵占业主共有财产；\n（三）利用职务之便接受减免物业服务费、停车费，以及索取、非法收受建设单位、物业服务企业或者有利害关系业主提供的利益、报酬；\n（四）打击、报复、诽谤、陷害有关投诉、举报人；\n（五）泄露业主信息或者将业主信息用于与物业服务无关的活动；\n（六）其他损害业主共同利益或者可能影响其公正履行职责的行为。\n业主委员会委员违反前款规定的，街道办事处、乡镇人民政府调查核实后，责令其暂停履行职责，由业主大会决定终止其委员职务。\n第三十一条 业主委员会委员有下列情形之一的，其委员职务自行终止：\n（一）以书面形式向业主大会、业主委员会或者居（村）民委员会提出辞职的；\n（二）不再具备业主身份的；\n（三）不再具备履行职责能力的；\n（四）任职期间被追究刑事责任的；\n（五）法律、法规和业主公约或者管理规约规定的其他情形。\n第三十二条 业主委员会任期届满六十日前，应当组织召开业主大会会议，完成换届选举。逾期未完成的，街道办事处、乡镇人民政府应当组织召开业主大会会议完成换届选举。\n第三十三条 业主委员会应当自任期届满之日起十日内，将其保管的档案资料、印章及其他属于全体业主所有的财物，移交新一届业主委员会。\n业主委员会委员职务在任期内终止的，应当自终止之日起三日内将其保管的前款所列财物移交业主委员会。\n拒不移交的，街道办事处、乡镇人民政府应当督促其移交，公安机关应当依法协助。\n第三十四条 业主大会、业主委员会工作经费从共用部位、共用设施设备经营所得收益中列支，不足部分由全体业主分摊。工作经费的收支情况，应当每年在物业区域内显著位置公布一次，接受业主监督。","level":1},{"name":"第四章 物业服务企业","text":"第三十五条 从事物业服务业的企业应当具有独立的法人资格和相应的专业技术人员，具备为业主提供专业服务的能力。\n第三十六条 物业服务企业在物业服务活动中享有下列权利：\n（一）根据物业服务合同约定收取物业服务费用；\n（二）劝阻、制止损害物业或者其他损害业主共同利益和公共安全的行为；\n（三）法律、法规规定和物业服务合同约定的其他权利。\n任何单位和个人不得强制物业服务企业代收有关费用或者提供无偿服务。\n第三十七条 物业服务企业在物业服务活动中应当履行下列义务：\n（一）按照物业服务合同、国家有关物业服务的规范提供物业服务；\n（二）在业主、物业使用人使用物业前，将物业的共用部位、共用设施设备的使用方法、维护要求、注意事项等有关规定书面告知业主、物业使用人；\n（三）落实安防人员、设施及安保措施，确保安防监控设施正常运转，按照法律、法规规定和物业服务合同约定做好物业区域内的安全防范工作；\n（四）维护物业区域环境卫生，引导业主进行垃圾分类处理；\n（五）定期对物业的共用部位、共用设施设备进行养护，按照物业服务合同约定组织维修；\n（六）做好物业维修、养护、更新及其费用收支的各项记录，妥善保管物业档案资料和有关财务账册，建立物业服务信息平台，为业主提供免费查询服务；\n（七）实行二十四小时值班制，建立和完善物业服务工作应急预案，及时处理物业服务中的突发事件；\n（八）听取业主委员会、业主、物业使用人的意见，改进和完善物业服务；\n（九）法律、法规规定和物业服务合同约定的其他义务。\n物业服务企业不得以业主拖欠物业服务费用、不配合管理等理由，减少服务内容，降低服务质量，中断或者以限时限量等方式变相中断供水、供电、供气、供热，以及实施损害业主合法权益的其他行为。\n第三十八条 物业服务企业应当将下列信息在物业区域内显著位置公示：\n（一）物业服务企业项目负责人的基本情况、联系方式、物业服务投诉电话；\n（二）物业服务合同约定的服务内容、服务标准、收费项目、收费标准、收费方式等；\n（三）电梯、消防、监控等专业设施设备的日常维修保养单位的名称、资质、联系方式和应急处置方案等；\n（四）业主交纳物业服务费用、公共水电分摊费用情况、住宅专项维修资金使用情况，物业共用部位、共用设施设备经营所得收益和支出情况；\n（五）物业区域内停车位、车库的销售、出租、分配以及使用情况；\n（六）房屋修缮、装饰装修以及使用过程中的结构变动等安全事项；\n（七）其他应当公示的信息。\n业主对公示内容有异议的，物业服务企业应当答复。\n第三十九条 物业服务企业不得在物业服务活动中有下列行为：\n（一）擅自允许他人利用共用部位、共用设施设备进行广告、宣传、经营等活动；\n（二）擅自设置营业摊点；\n（三）法律、法规和业主公约或者管理规约规定的其他行为。\n物业服务企业不得泄露业主信息，不得对业主进行骚扰、恐吓、打击报复或者采取暴力行为。\n第四十条 县级以上人民政府房产行政主管部门应当建立物业服务企业考核和信用评价体系，听取业主和业主委员会的评价意见，将评价意见作为物业服务企业服务质量考核的内容；定期组织对物业服务企业进行检查和考核，并向社会公布。\n物业服务企业应当向房产行政主管部门定期报送信用档案信息、统计报表等资料。","level":1},{"name":"第五章 物业服务","text":"第四十一条 住宅物业的建设单位在业主、业主大会首次选聘物业服务企业前，应当采取招标投标方式公开选聘前期物业服务企业。投标人少于三个或者住宅面积不超过三万平方米的，经房产行政主管部门批准，可以采取协议方式选聘前期物业服务企业。建设单位选聘前期物业服务企业应当接受街道办事处、乡镇人民政府监督。\n业主购买住宅物业后，建设单位更换前期物业服务企业的，应当征得半数以上业主同意。\n建设单位应当与选聘的物业服务企业签订前期物业服务合同，并报房产行政主管部门备案。\n第四十二条 前期物业服务收费标准纳入政府定价目录管理。\n前期物业服务合同生效之日至物业交付之日的前期物业服务费用，由建设单位承担；物业交付之日后的前期物业服务费用，由业主承担。\n第四十三条 建设单位应当按照国家规定和房屋买卖合同、前期物业服务合同的约定，向业主和前期物业服务企业交付权属明确、资料完整、质量合格、功能完备、配套齐全的物业。\n交付的物业应当具备以下条件：\n（一）建设项目竣工验收合格，取得城乡规划、消防、生态环境等行政主管部门出具的认可或者准许使用文件，并经建设行政主管部门备案；\n（二）供水、排水、供电、供气、供热、通信、公共照明、有线电视等市政公用设施设备按照规划设计要求建成，供水、供电、供气等计量装置已按照专有部分一户一终端结算表、共有部分独立计量表配置；\n（三）教育、邮政、医疗卫生、文化体育、环境卫生、社区服务等公共服务设施已按照规划设计要求建成；\n（四）道路、车位、绿地和物业服务用房等公共配套设施按照规划设计要求建成，并满足使用功能要求；\n（五）电梯、二次供水、高压供电、消防设施、压力容器、监控系统等共用设施设备取得使用合格证书；\n（六）同一住宅建设项目分期建设的，已建成的住宅周边场地与施工工地之间设置符合安全要求的隔离设施；\n（七）物业使用、维护和管理的相关技术资料完整齐全；\n（八）法律、法规规定的其他条件。\n建设单位将未达到交付条件的新建物业交付给买受人的，应当承担相应的责任，并承担前期物业服务费用。\n第四十四条 建设单位应当在物业交付十五日前，与选聘的前期物业服务企业完成物业共用部位、共用设施设备的承接查验工作，按照国家规定移交承接查验资料。承接查验后，双方应当签订物业承接查验协议，作为前期物业服务合同的补充协议。\n第四十五条 前期物业服务企业应当自物业承接查验完成之日起三十日内，向房产行政主管部门备案下列资料：\n（一）前期物业服务合同；\n（二）物业承接查验协议；\n（三）建设单位移交资料清单；\n（四）查验、交接记录；\n（五）其他与承接查验有关的资料。\n第四十六条 物业服务企业应当将承接查验有关的文件、资料和记录建档保存。\n物业承接查验档案属于全体业主所有，业主有权免费查询。前期物业服务企业应当在业主大会成立之日起十日内，向业主委员会移交物业承接查验档案。\n第四十七条 业主大会成立后，业主委员会应当与业主大会决定选聘的物业服务企业签订物业服务合同。鼓励业主大会采用招标投标方式选聘物业服务企业。\n物业服务合同应当对物业服务内容、服务标准、收费项目、收费标准及调整办法、收费方式、双方权利义务、物业服务用房、住宅专项维修资金的管理与使用、共用部位和共用设施设备的管理与使用、合同期限、物业服务企业的退出、资料的移交、违约责任等内容进行约定。\n物业服务企业应当自物业服务合同签订之日起十五日内，将物业服务合同报房产行政主管部门备案。\n第四十八条 业主、物业使用人应当遵守业主公约或者管理规约，按照物业服务合同约定履行义务。\n业主、物业使用人有权向相关行政主管部门投诉和举报，对侵害自己合法权益的行为，可以依法向人民法院提起诉讼。\n业主、物业使用人未按照合同约定交纳物业服务费用的，物业服务企业可以依法申请仲裁或者提起诉讼。\n第四十九条 业主委员会应当在物业服务合同期满九十日前组织召开业主大会会议，决定续聘或者选聘新的物业服务企业。合同期满仍未决定的，原物业服务合同应当继续履行，物业服务企业在物业服务合同期满九十日前书面告知业主委员会到期终止合同的除外。\n业主大会决定选聘新的物业服务企业的，原物业服务企业应当在物业服务合同终止之日与业主委员会办理完全部交接手续，并履行下列交接义务：\n（一）移交本条例第四十五条规定的资料；\n（二）移交物业服务用房；\n（三）提供物业服务期间形成的有关物业及设施设备改造、维修、运行、保养的有关资料；\n（四）移交提供物业服务期间配置的固定设施设备及其资料；\n（五）结清预收、代收和预付、代付的有关费用；\n（六）提供电梯、消防、监控等专业设施设备的技术手册、维护保养记录等相关资料；\n（七）移交利用共用部位、共用设施设备经营的相关资料、物业服务费用和公共水电分摊费用交纳记录等资料；\n（八）法律、法规规定和物业服务合同约定的其他事项。\n第五十条 业主可以采取业主直接管理、业主委员会负责管理、成立其他管理机构管理等形式对物业实施自行管理，并对下列事项作出决定：\n（一）自行管理的执行机构、管理人；\n（二）自行管理的内容、标准、费用和期限；\n（三）聘请专业经营单位的方案；\n（四）其他有关自行管理的内容。","level":1},{"name":"第六章 物业的使用与维护","text":"第五十一条 业主对物业专有部分享有占有、使用、收益和处分的权利。业主行使权利不得危及建筑物的安全，不得损害其他业主的合法权益。\n业主对物业专有部分以外的共有部分，享有共有和共同管理的权利，承担义务。\n第五十二条 业主将住宅改变为经营性用房的，除遵守法律、法规和业主公约或者管理规约外，影响相邻人合法权益的，应当经有利害关系的业主同意，并依法办理有关手续，同时告知业主委员会和物业服务企业。\n第五十三条 利用业主共用部位、共用设施设备进行经营的，应当在征得相关业主、业主委员会、物业服务企业的同意后，按照规定办理有关手续，经营所得收益属于全体业主共有。\n业主委员会、物业服务企业应当每半年公布一次经营所得收益和支出情况，接受业主监督。\n第五十四条 物业区域内按照建设工程规划许可证确定且初始登记所有权人为建设单位的停车位、车库的归属，由当事人通过销售、附赠或者出租等方式约定，不得销售给业主以外的单位和个人。优先满足业主需要后对外出租的，每次租赁期限不得超过一年。\n物业区域内占用业主共有道路或者场地用于停放车辆的车位，属于全体业主共有，其分配、使用及收费管理具体事项由业主大会决定；建设单位、物业服务企业不得销售或者变相销售。\n第五十五条 物业区域内划定车位、停放车辆，不得占用、堵塞、封闭疏散通道、安全出口、消防通道，不得妨碍其他车辆和行人的正常通行。\n第五十六条 业主、物业使用人修缮、装饰装修房屋的，应当事先告知物业服务企业。物业服务企业应当将房屋修缮、装饰装修中的禁止行为和注意事项告知业主、物业使用人，业主、物业使用人和房屋修缮、装饰装修单位或者个人应当遵守。\n第五十七条 物业区域内禁止下列行为：\n（一）损坏或者擅自改变房屋承重结构、主体结构和门窗位置，超荷载存放物品；\n（二）将没有防水功能的房间或者阳台改为卫生间、厨房，或者将卫生间改在下层住户的客厅、厨房、卧室、书房的上方；\n（三）违法建设建筑物、构筑物，破坏、擅自改变房屋外貌或者擅自改变架空层、设备层等共用部位、共用设施设备规划用途；\n（四）擅自占用、挖掘物业区域内道路、场地，损毁树木、绿地；\n（五）违反安全标准存放易燃、易爆、剧毒、放射性等危险物品，擅自占压、迁移燃气管道，损坏或者擅自停用公共消防设施和器材，妨碍公共通道、安全出口、消防通道畅通；\n（六）随意弃置垃圾、排放污水、高空抛物或者露天焚烧杂物，制造超过规定标准的噪声、振动、光源等；\n（七）擅自架设电线、电缆，在建筑物、构筑物上悬挂、张贴、涂写、刻画，在楼道等业主共用部位堆放物品；\n（八）违反规定停放车辆；\n（九）违反规定出租房屋；\n（十）违反规定饲养动物或者种植植物；\n（十一）法律、法规和业主公约或者管理规约禁止的其他行为。\n有前款所列行为的，物业服务企业应当及时劝阻、制止，并向业主委员会和建设、公安、生态环境、城市管理等有关行政主管部门报告，有关行政主管部门应当依法处理。\n第五十八条 禁止在物业区域内饲养烈性犬和大型犬，具体品种和体高、体重标准由省人民政府公安机关确定，并向社会公布。\n业主、物业使用人在物业区域内饲养前款规定以外其他犬只应当遵守有关法律、法规和业主公约或者管理规约，携犬只出户的，应当束犬链牵引；犬只伤害他人的，养犬人应当依法承担相应的法律责任。\n物业服务企业应当加强物业区域内养犬行为的监督，及时制止违法违规养犬行为。\n第五十九条 城乡规划、建设、公安、生态环境、城市管理、市场监督管理等行政主管部门，应当加强物业区域内公共秩序、治安消防、环境卫生、房屋使用、物业收费等方面的监督管理，建立违法行为投诉、处理和回复制度，并在物业区域内显著位置公布联系方式，依法及时处理物业区域内的违法行为。\n第六十条 建设单位应当按照国家和省有关规定承担物业的保修责任。\n第六十一条 业主专有部分出现危害安全、影响观瞻、妨碍公共利益及其他影响物业正常使用情形时，业主应当及时养护、维修，相邻业主应当提供便利。\n第六十二条 物业保修期满后，物业区域内共用部位、共用设施设备的维修和更新改造，由全体业主共同承担，法律、法规另有规定的除外。\n共用部位主要包括建筑物的基础、承重墙体、柱、梁、楼板、屋顶以及户外的墙面、门厅、楼梯间、走廊通道等；共用设施设备主要包括电梯、天线、公共照明、消防设施、安防设施、绿地、道路、沟渠、池、井、非专有车位车库、公益性文体设施和共用设施设备使用的房屋等。\n电梯等属于业主共有的特种设备，由物业服务企业或者业主根据物业服务合同约定，按照特种设备管理法律、法规的有关规定，委托专业服务单位负责定期维护、保养，确保使用安全。\n第六十三条 住宅物业、住宅物业区域内的非住宅物业或者与单幢住宅结构相连的非住宅物业的业主，应当交存住宅专项维修资金。\n住宅专项维修资金的交存、使用、管理，按照国家和省有关规定执行。住宅专项维修资金的使用，经业主大会依法决定，可以根据维修范围以单元（栋）为单位进行表决，也可以采取异议表决，即根据业主公约或者管理规约的规定，持不同意见的业主专有部分占建筑物总面积三分之一以下且占总人数三分之一以下的，视为表决通过。\n第六十四条 物业保修期满后，发生下列危及房屋安全和人身财产安全等紧急情况时，物业服务企业、业主委员会、居（村）民委员会应当先行采取应急措施，并向房产行政主管部门提出使用住宅专项维修资金的申请：\n（一）屋面、外墙渗漏的；\n（二）电梯故障的；\n（三）消防设施故障的；\n（四）公共护栏（围）破损严重的；\n（五）楼体外立面有脱落危险的；\n（六）共用排水设施因坍塌、堵塞、爆裂等造成功能障碍的；\n（七）危及房屋安全和人身财产安全的其他情形。\n房产行政主管部门收到维修申请后，应当即时核准并拨付住宅专项维修资金。\n第六十五条 住宅物业区域内供水、供电、供气、供热、通信、有线电视、宽带数据传输等专业经营单位，应当负责分户终端计量装置或者入户端口以外设施设备的维修、养护、更新，并承担相关费用。法律、法规另有规定的，从其规定。\n已经移交给专业经营单位维护管理的设施设备，其维修、养护、更新等费用，不得从物业服务费中列支。\n专业经营单位对专业经营设施设备进行维修、养护、更新时，业主应当配合。","level":1},{"name":"第七章 法律责任","text":"第六十六条 违反本条例，法律、法规有规定的，从其规定；造成他人损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第六十七条 建设单位有下列行为之一的，由县级以上人民政府房产行政主管部门依照下列规定处罚，并录入企业信用档案：\n（一）违反本条例第二十三条、第四十一条第三款，未按照规定报送相关资料或者备案的，责令限期改正；逾期未改正的，处1万元以上3万元以下罚款；\n（二）违反本条例第四十一条第一款，未通过招标投标方式或者未经批准擅自采用协议方式选聘前期物业服务企业的，责令限期改正，处5万元以上10万元以下罚款；\n（三）违反本条例第六十条，在物业保修期内未按照规定履行保修责任的，责令限期改正；逾期未改正的，依法确定有法定资质的第三方进行维修，所需费用由建设单位承担，并处所需维修费用一倍以上三倍以下罚款。\n第六十八条 专业经营单位违反本条例第十五条第二款、第十六条第二款和第六十五条第一款，未按照规定接收专业经营设施设备或者未按照规定对专业经营设施设备进行维修、养护、更新的，由县级以上人民政府相关行政主管部门责令限期改正；影响房屋交付使用、业主正常生活或者造成人身、财产损害的，依法承担民事责任。\n第六十九条 物业服务企业有下列行为之一的，由县级以上人民政府房产行政主管部门依照下列规定处罚，并录入物业服务企业信用档案：\n（一）违反本条例第三十七条第二款，中断或者以限时限量等方式变相中断供水、供电、供气、供热以及实施损害业主合法权益的其他行为的，责令限期改正，处1万元以上5万元以下罚款；逾期未改正的，按照原处罚数额按日连续处罚；\n（二）违反本条例第三十八条第一款，未按照规定在物业区域内公示有关信息的，责令限期改正；逾期未改正的，处1万元以上3万元以下罚款；\n（三）违反本条例第三十九条第一款规定的，责令限期改正，处1万元以上5万元以下罚款；有收益的，用于物业区域内共用部位、共用设施设备的维修和养护；逾期未改正的，按照原处罚数额按日连续处罚；\n（四）违反本条例第四十五条、第四十六条第一款、第四十七条第三款，未按照规定备案或者保存、移交物业承接查验资料、档案的，责令限期改正；逾期未改正的，处1万元以上3万元以下罚款；\n（五）违反本条例第四十九条，擅自撤离物业区域、停止物业服务的，或者被解聘的物业服务企业未按照规定办理交接手续、拒不退出的，责令限期改正，处5万元以上10万元以下罚款；逾期未改正的，按照原处罚数额按日连续处罚。\n第七十条 物业服务企业违反本条例第三十九条第二款，泄露业主信息或者对业主进行骚扰、恐吓、打击报复、采取暴力行为的，由公安机关按照《中华人民共和国治安管理处罚法》处罚，由房产行政主管部门录入物业服务企业信用档案。\n第七十一条 建设单位、物业服务企业违反本条例第五十四条，销售或者变相销售停车位、车库的，由县级以上人民政府房产行政主管部门责令改正，退还违法所得，并处违法所得一倍以上三倍以下罚款；未按照规定出租停车位、车库的，责令限期改正，没收违法所得，并处违法所得一倍以上三倍以下罚款。\n第七十二条 业主、物业使用人违反本条例第五十八条第一款，在物业区域内饲养烈性犬和大型犬的，由公安机关没收犬只，并处5千元以上1万元以下罚款。\n业主、物业使用人违反本条例第五十八条第二款，携犬只出户未束犬链牵引的，由公安机关责令改正；拒不改正的，处500元以上1千元以下罚款；情节恶劣或者造成严重后果的，没收犬只。\n第七十三条 国家机关及其工作人员有下列情形之一的，由其主管机关或者监察机关依法对直接负责的主管人员和其他直接责任人员给予处分：\n（一）未按照规定履行监督管理职责的；\n（二）未按照规定筹备、组织召开业主大会会议的；\n（三）未按照规定在物业区域内显著位置公布联系方式或者对物业服务活动中的投诉，不及时受理、依法处理的；\n（四）发现违法行为或者接到举报后不及时查处的；\n（五）截留、挪用、侵占或者未按时审核拨付住宅专项维修资金的；\n（六）违法实施行政许可或者行政处罚的；\n（七）其他玩忽职守、徇私舞弊、滥用职权的行为。","level":1},{"name":"第八章 附则","text":"第七十四条 本条例规定的业主公约或者管理规约、业主大会议事规则、业主委员会工作规则、物业服务合同示范文本，由省人民政府住房和城乡建设行政主管部门制订。\n第七十五条 本条例自2016年10月1日起施行。","level":1}]},{"id":"h0182","sections":[{"name":"","text":"（2016年9月14日湖北省第十二届人民代表大会常务委员会第二十四次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了保护华侨的合法权益，根据宪法和有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内华侨合法权益的保护。\n本条例所称华侨，是指定居在国外的中国公民。华侨身份的界定和确认，按照国家有关规定执行。\n第三条 华侨权益保护应当遵循平等保护的原则。\n华侨享有宪法和法律规定的权利，履行宪法和法律规定的义务。没有法律法规的依据，不得减损华侨的权利或者增加华侨的义务。\n第四条 县级以上人民政府应当加强对华侨权益保护工作的组织领导，建立华侨权益保护工作协调机制，制定华侨权益保护措施，将华侨权益保护工作所需经费列入本级财政预算。\n县级以上人民政府侨务部门负责华侨权益保护的服务、协调、监督和宣传工作。\n县级以上人民政府有关部门应当按照各自职责，做好华侨权益保护的相关工作。\n第五条 国家机关、企业事业单位、社会团体和村（居）民委员会，应当依法保护华侨合法权益，为华侨融入当地经济社会发展服务。\n各级归国华侨联合会应当宣传贯彻涉侨法律法规和政策，密切联系华侨，反映华侨的意见和要求。","level":1},{"name":"第二章 基本权益保护","text":"第六条 华侨依法享有参政议政的权利，各级人民政府及有关部门应当为华侨参政议政提供保障。\n县级以下人民代表大会代表选举期间，华侨在国内的，可以在原籍地或者出国前居住地参加选举。\n村（居）民委员会选举期间，华侨在国内的，可以依法参加居住地选举，行使民主管理和民主监督的权利。\n华侨在本省定居的，可以依法成立社会团体，并依照法律法规和章程开展活动。\n第七条 华侨可以凭本人的中华人民共和国护照依法办理金融、教育、医疗、交通、电信、社会保险、财产登记以及投资创业、税务、住宿登记、机动车驾驶证申领等事务，其护照与居民身份证、居住证、社会信用代码证明具有同等的身份证明效力。\n第八条 华侨在本省居住六个月以上，具备有合法稳定就业、合法稳定住所、连续就读等条件之一的，可以依法申领居住证，享受居住地基本公共服务和便利。\n第九条 华侨要求定居本省的，可以向拟定居地县级以上人民政府侨务部门提出申请，经批准后，由公安机关依法办理落户手续。\n第十条 夫妻一方或者双方为华侨申请生育的，或者因所生子女均在国外定居申请再生育的，按照国家和省人口计划生育的有关规定执行，依法享受计划生育相关服务。\n第十一条 华侨购买房产与本省居民享受同等待遇。\n华侨依法取得房屋等建筑物、构筑物所有权，耕地、林地、草地等土地承包经营权，以及建设用地使用权、宅基地使用权的，不动产登记机构应当依法为其办理不动产登记，颁发不动产权属证书或者登记证明。\n第十二条 华侨出国定居后，原以家庭为单位承包土地的合同未到期的，可以依法流转。有关组织和个人不得侵占、截留、扣缴或者挪用华侨的土地承包经营权流转收益。\n因公共利益需要征收或者征用华侨房屋及其他不动产的，应当依照法定程序进行，并依法给予补偿。征收或者征用华侨在集体土地上的房屋及其他不动产的，按照当地集体经济组织成员标准给予补偿。\n第十三条 因公共利益需要迁移华侨祖墓的，应当依法给予合理补偿；符合另行安置条件的，按照国家和省有关规定办理。\n第十四条 华侨对继承或者接受遗赠和赠与获得的财产，依法享有占有、使用、收益和处分的权利，任何组织和个人不得侵犯。\n第十五条 华侨在本省从事专业技术工作的，可以参加专业技术职务任职资格评审和专业技术人员资格考试，其在境外的专业工作年限和成果，可以作为专业技术职务任职资格评审的参考依据。\n华侨依照规定参加公务员录用考试和其他招聘考试的，有关部门和单位不得增设报考条件和录（聘）用条件。\n第十六条 华侨子女在本省接受学前教育和义务教育的，可以在其监护人户籍所在地或者居住地就读，享受当地居民入学同等待遇。\n华侨子女可以在本省参加高中阶段学校招生考试和普通高等学校招生统一考试，县级以上人民政府有关部门及相关学校在录取时应当按照国家和省的相关规定执行。\n第十七条 华侨及其子女在本省居住期间，可以按照有关规定参加社会保险，享受社会保险待遇。\n华侨出国定居前已经参加社会保险的，其基本养老保险、职工基本医疗保险个人账户应当继续保留；再次回本省居住或者就业的，其基本养老保险、职工基本医疗保险等社会保险关系按照有关规定接续，缴费年限及个人账户余额累计计算。\n华侨出国定居前提出申请的，可以将其职工基本医疗保险个人账户余额一次性支付给本人。\n第十八条 华侨达到法定领取基本养老金条件的，依法享受相应的养老保险待遇。定居国外的，应当至少每年向负责支付养老金的社会保险经办机构提供一次由中国驻其所在国的使馆、领馆或者由所在国公证机构出具的本人生存证明。\n第十九条 华侨因年老、疾病或者丧失劳动能力等符合救助条件的，可以依法申请社会救助。\n县级以上人民政府应当完善社会救助体系，按照公开、公平、公正、及时的原则对符合条件的华侨进行社会救助。\n第二十条 鼓励和支持华侨开展扶贫济困、扶老助残、助学助医等慈善活动。\n华侨为慈善事业捐赠资金、物资的，有权了解捐赠资金、物资的使用和管理情况，提出意见和建议；受赠单位应当尊重捐赠人的合理意见和建议。\n华侨捐赠的财产用于慈善事业和公益事业的，依法享受税收减免及其他优惠政策。","level":1},{"name":"第三章 投资创业保护","text":"第二十一条 鼓励和支持华侨以个人、企业或者其他经济组织的名义在本省投资创业。\n华侨在本省的投资和投资收益受法律保护，任何组织和个人不得损害、侵占。\n第二十二条 华侨在境外设立的企业、其他经济组织在本省投资的，适用市场准入负面清单管理模式。\n第二十三条 华侨投资企业依法享有自主经营权，任何组织和个人不得干预和侵犯。\n华侨合法投资获得的税后利润、清算后的个人资金以及其他合法收益，可以依法自主处置。\n未经法定程序，不得查封、扣押华侨投资企业的财产或者责令其停产停业。\n第二十四条 对华侨投资企业的收费项目和标准，应当依照法律法规和规章设定。任何单位和个人不得擅自设立收费项目、提高收费标准或者重复收费。\n第二十五条 华侨投资企业可以依法参加政府采购，任何组织和个人不得以不合理的条件对其实行歧视待遇。\n第二十六条 华侨回国创新创业，可以按照规定参与本省人才创新创业类的计划，享受人才项目的优惠政策，获得相应的工作待遇和生活条件保障。\n县级以上人民政府及有关部门应当为华侨人才及其家属办理户籍、医疗、教育、住房、出入境等手续以及项目申报、科研等提供便利。\n第二十七条 鼓励和支持华侨在本省依法设立研究开发机构，研究开发新技术、新产品、新工艺。\n支持华侨企业与高等院校、科研院所采取委托研发、技术许可、技术转让、技术入股以及共建研发机构等形式，开展产学研用合作。\n华侨在本省投资设立研究开发机构的，适用政府扶持企业技术创新的相关政策。\n支持华侨建设或者参与建设高水平智库和软科学研究基地，提出咨询建议，为科学决策提供依据和支撑。\n第二十八条 鼓励华侨及其投资企业开展专利申请、商标注册和著作权登记等活动；华侨利用其专利、专有技术等科技成果投资创业的，享受留学人员回国创业和省科技成果转化的相关政策。\n第二十九条 鼓励和引导华侨在战略性新兴产业、现代服务业和现代农业等领域创新创业，参与本省经济和社会建设。\n华侨在本省投资的企业可以利用国际资源，开展对外投资和经济合作，享受本省企业境外投资相关政策。\n第三十条 鼓励设立多种形式的创业基金、人才基金、投资担保基金，支持华侨创业创新。\n政府主导的高层次创新创业人才引进计划专项资金、科技专项资金、工业和信息产业转型升级专项资金、各类产业发展扶持资金等，对华侨予以同等支持。\n华侨可以申报本省各类科技计划项目，以及其他各类产业化项目。\n第三十一条 金融机构、担保机构和其他金融企业应当为华侨投资者提供金融服务。支持华侨投资企业依法通过信贷、股票、债券等方式融资。","level":1},{"name":"第四章 服务与保障","text":"第三十二条 县级以上人民政府及其有关部门应当制定政策措施，保障华侨依法享受义务教育、就业、卫生、计划生育、文化、体育、法律援助等基本公共服务以及便利。\n县级以上人民政府及其有关部门在制定公共政策时，应当通过座谈会、听证会、论证会等多种形式征询华侨的意见和建议。\n第三十三条 县级以上人民政府侨务部门应当建立华侨人才信息数据库，健全华侨人才引进、使用、评价、激励和服务机制。\n第三十四条 县级以上人民政府及其有关部门应当建立健全涉侨信息统一发布制度，为华侨提供经济社会发展的政策咨询和信息服务。\n鼓励和支持企业事业单位和其他组织为华侨就业创业、投资发展提供政策分析、法律咨询、风险防范等中介服务。\n第三十五条 华侨合法权益受到侵害或者发生争议的，可以向县级以上人民政府侨务部门和有关部门投诉，也可以通过下列途径解决：\n（一）协商和解或者调解解决；\n（二）申请仲裁；\n（三）申请行政复议；\n（四）向人民法院提起诉讼。\n对经济困难需要法律援助或者司法救助的华侨，有关国家机关应当为其提供法律援助或者司法救助。\n第三十六条 国家机关及其工作人员损害华侨合法权益的，侨务部门和归国华侨联合会可以向其所在机关或者上级主管部门提出追究其责任的意见建议，所在单位或者上级主管部门应当及时研究处理并告知结果。\n对于国家机关及其工作人员的违法失职行为，华侨有向有关机关提出申诉、控告或者检举的权利，任何人不得打击报复。\n对于华侨的申诉、控告或者检举，有关机关应当查清事实，负责处理。","level":1},{"name":"第五章 法律责任","text":"第三十七条 违反本条例，法律、法规有规定的，从其规定。\n第三十八条 国家机关及其工作人员有下列情形之一，致使华侨合法权益受到侵害的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任：\n（一）未按照规定对征收或者征用华侨房屋以及其他不动产、迁移华侨祖墓进行补偿和安置的；\n（二）擅自查封、扣押华侨投资企业的财产或者责令其停产停业的；\n（三）对华侨投资企业擅自增设行政事业性收费项目、提高收费标准或者重复收费的；\n（四）在政府采购、公务员招录等活动中，对华侨实行歧视待遇的；\n（五）其他滥用职权、玩忽职守、徇私舞弊的。\n第三十九条 违反本条例规定，有下列情形之一的，应当依法承担民事责任或者行政责任；构成犯罪的，依法追究刑事责任：\n（一）非法截留、扣缴或者以其他方式侵占华侨土地承包经营权流转收益的；\n（二）非法截留、侵占华侨继承或者接受遗赠和赠与获得的财产的；\n（三）非法侵占华侨投资和投资收益的；\n（四）其他侵犯华侨合法权益的。","level":1},{"name":"第六章 附则","text":"第四十条 赴香港、澳门特别行政区定居人员在本省的合法权益保护可以参照本条例执行。\n第四十一条 除法律法规和规章规定不可享有的特定权益外，外籍华人在本省的有关权益保护，可以参照本条例执行。\n第四十二条 本条例自2016年12月1日起施行。","level":1}]},{"id":"h0183","sections":[{"name":"","text":"（2016年9月14日湖北省第十二届人民代表大会常务委员会第二十四次会议通过）\n第一条 为了加强乡、民族乡、镇（以下简称乡镇）人民代表大会的制度建设，保证乡镇人民代表大会依法行使职权，根据《中华人民共和国宪法》、《中华人民共和国地方各级人民代表大会和地方各级人民政府组织法》、《中华人民共和国全国人民代表大会和地方各级人民代表大会选举法》和《中华人民共和国全国人民代表大会和地方各级人民代表大会代表法》的有关规定，结合本省实际，制定本条例。\n第二条 乡镇人民代表大会是基层国家权力机关，由选民直接选举的乡镇人民代表大会代表组成，对人民负责，受人民监督。\n乡镇人民代表大会每届任期五年，从每届乡镇人民代表大会举行第一次会议开始，到下一届乡镇人民代表大会举行第一次会议为止。\n乡镇人民代表大会实行民主集中制的原则。\n第三条 乡镇人民代表大会会议一般每年举行两次，每次会议会期不少于一天；有选举事项时，会期可以适当延长。\n乡镇人民代表大会会议有三分之二以上代表出席，始得举行。经五分之一以上代表提议，可以临时召集乡镇人民代表大会会议。\n乡镇人民代表大会举行会议时，可以设立议案审查委员会、财政预算审查委员会，在主席团领导下开展工作，对议案提出办理意见，对预算草案提出审查意见。\n乡镇人民代表大会会议审议各项报告、议案时，乡镇人民政府应当按照要求安排有关负责人到会听取意见，回答询问，会后认真研究处理代表的意见、建议并及时反馈。\n第四条 乡镇人民代表大会依法听取和审查本级人民政府工作报告，审查批准本级财政预算和预算执行情况的报告，讨论、决定重大改革举措、乡镇发展总体规划、重大城乡建设项目、重大民生和环境保护工程等重大事项。\n乡镇人民代表大会讨论、决定重大事项，可以根据实际情况，依法作出决议、决定，或者将有关意见、建议转交乡镇人民政府研究处理。\n乡镇人民政府对重大事项作出决策前，应当向本级人民代表大会报告。乡镇人民代表大会闭会期间，应当向乡镇人民代表大会主席团报告。\n第五条 乡镇人民代表大会依法对本级人民政府的工作实施监督。\n乡镇人民代表大会每年选取若干关系本行政区域改革发展稳定大局和人民群众切身利益、社会普遍关注的重大问题，有计划地组织代表开展视察、调研、执法检查、工作评议、询问、质询和预算执行情况监督等活动。\n乡镇人民代表大会有权撤销乡镇人民政府不适当的决定和命令。\n第六条 乡镇人民代表大会主席、副主席，乡长、副乡长，镇长、副镇长由本级人民代表大会选举产生。\n乡镇人民代表大会选举产生的本级人民代表大会主席、副主席，乡长、副乡长，镇长、副镇长，应当公开进行宪法宣誓。\n乡镇人民代表大会有权罢免本级人民代表大会主席、副主席，乡长、副乡长，镇长、副镇长。\n乡镇人民代表大会有权决定是否接受本级人民代表大会主席、副主席，乡长、副乡长，镇长、副镇长提出的辞职。\n第七条 乡镇人民代表大会设立代表资格审查委员会。代表资格审查委员会设主任委员一人、副主任委员一人，委员三人至五人，由乡镇人民代表大会主席团在代表中提名，乡镇人民代表大会第一次会议通过，行使职权至本届乡镇人民代表大会任期届满为止。\n代表资格审查委员会对当选代表是否符合宪法、法律规定的基本条件，选举是否符合法律规定的程序，以及是否存在破坏选举和其他当选无效的违法行为进行审查，提出代表当选是否有效的意见，向乡镇人民代表大会主席团报告。\n代表资格审查委员会应当认真受理对当选代表的举报，及时转交有关方面依法调查处理；需要继续调查核实的，可以延迟提出其当选有效或者无效的意见。\n代表资格审查委员会应当向本级人民代表大会报告代表资格终止、暂时停止执行代表职务，以及恢复执行代表职务的情况，由乡镇人民代表大会予以公告。\n第八条 乡镇人民代表大会设主席，并设副主席一人至二人。主席、副主席由乡镇人民代表大会从代表中选出，任期同本级人民代表大会每届任期相同。\n乡镇人民代表大会主席提名为县级人民代表大会代表人选；根据工作需要，副主席也可以提名为县级人民代表大会代表人选。\n乡镇人民代表大会主席、副主席不得担任国家行政机关的职务；如果担任国家行政机关的职务，应当向本级人民代表大会辞去主席、副主席的职务。\n第九条 乡镇人民代表大会主席、副主席履行下列职责：\n（一）负责联系本级人民代表大会代表，根据主席团的安排组织代表开展活动，为代表履职提供服务保障；\n（二）受理代表和人民群众的来信、来访，反映代表和人民群众对乡镇人民政府工作的建议、批评和意见；\n（三）指导代表组建代表小组，建设代表活动场所；\n（四）受理代表在闭会期间提出的建议、批评和意见，督办代表建议办理工作，向主席团报告代表建议交办情况，并印发下一次人民代表大会会议；\n（五）组织代表参加履职学习培训；\n（六）负责处理主席团的日常工作；\n（七）召集并主持主席团会议，协调安排主席团成员做好主席团的各项工作；\n（八）负责处理上级人民代表大会及其常务委员会委托的其他事项。\n第十条 乡镇人民代表大会召开会议时，选举主席团。主席团成员由七人至十三人组成，代表名额超过一百人的，主席团成员不超过十五人，具体名额由县级人民代表大会常务委员会决定。乡镇人民代表大会主席、副主席为主席团成员。\n主席团成员不得担任国家行政机关的职务；如果担任国家行政机关的职务，应当向本级人民代表大会辞去主席团成员的职务。\n乡镇人民代表大会闭会期间，主席团会议每三个月至少召开一次，有三分之二以上成员出席始得举行。主席团会议作出的决定，以主席团全体成员的过半数通过。主席团召开会议时，根据需要，可以邀请乡镇人民政府领导人员和有关人员列席。\n主席团在本级人民代表大会闭会期间的工作，向本级人民代表大会报告。\n第十一条 乡镇人民代表大会主席团在本级人民代表大会会议期间履行下列职责：\n（一）主持人民代表大会会议；\n（二）提出会议议程草案、选举办法草案和代表议案及建议、批评和意见处理办法草案，提请人民代表大会审议通过；\n（三）提出议案、罢免案；\n（四）提名乡镇人民代表大会主席、副主席，乡长、副乡长，镇长、副镇长人选，向代表如实介绍候选人情况，并主持人民代表大会选举工作；\n（五）提出各项决议、决定草案，提请人民代表大会审议和表决；\n（六）处理代表提出的议案、质询案、罢免案等有关事项；\n（七）将会议期间代表提出的建议、批评和意见转交有关机关和组织研究办理并答复代表；\n（八）法律、法规规定会议期间应当由主席团负责处理的其他事项。\n第十二条 乡镇人民代表大会主席团在本级人民代表大会闭会期间履行下列职责：\n（一）选择关系本行政区域人民群众切身利益和社会普遍关注的问题，有计划地安排代表听取和讨论本级人民政府的专项工作报告，开展视察、调研、执法检查和工作评议等活动；\n（二）根据代表的要求，联系安排本级或者上级人民代表大会代表持代表证就地进行视察、约见本级国家机关负责人；\n（三）听取、反映代表和人民群众对本级人民政府工作的建议、批评和意见；\n（四）将闭会期间代表提出的建议、批评和意见转交有关机关和组织研究办理，并督促其将研究办理情况及时答复代表；\n（五）督促乡镇人民政府依法办理代表提出的建议、批评和意见，听取和审议办理情况的报告，印发下一次人民代表大会会议，并向社会公开；\n（六）定期组织代表向原选区选民报告履职情况；\n（七）在换届选举和补选代表时，根据代表资格审查委员会提出的报告，确认代表的资格或者确定代表的当选无效，并公布代表名单；\n（八）组织开展代表接待选民、代表培训等活动，建立网络工作平台，公示代表信息，协调组织代表联系人民群众；\n（九）建立代表履职档案，收集代表履职情况，并向社会公开；\n（十）负责筹备、召集下一次人民代表大会会议；\n（十一）督促乡镇人民政府做好提交大会审议的工作报告和有关议案的准备工作；\n（十二）办理本级人民代表大会和上级人民代表大会及其常务委员会交办或者委托的其他事项。\n第十三条 乡镇人民代表大会会议期间，代表有权依法提出议案、质询案、罢免案，提出本级人民代表大会主席、副主席，乡长、副乡长，镇长、副镇长的人选；有权对本级人民代表大会主席团和代表依法提出的上述人员的人选，对本级人民代表大会主席团的人选提出意见；有权提出对各方面工作的建议、批评和意见。\n第十四条 乡镇人民代表大会代表应当优先执行代表职务，按时出席本级人民代表大会会议，遵守议事规则，认真审议各项议案、报告和其他议题，围绕议题发表意见；出席大会前，应当开展调研，听取人民群众的意见、建议，为会议期间执行代表职务做好准备。\n代表因健康等特殊原因不能出席本级人民代表大会会议的，应当在大会举行之前向乡镇人民代表大会主席团书面请假。未经批准两次不出席本级人民代表大会会议的，代表资格终止。缺席本级人民代表大会会议次数超过二分之一的，应当辞去代表职务。\n第十五条 乡镇人民代表大会代表闭会期间的活动以集体活动为主，以代表小组活动为基本形式。\n乡镇人民代表大会主席、副主席按照便于组织和开展活动的原则，指导有代表三人以上的居住地区或者单位组建代表小组。代表小组每三个月至少开展一次活动。\n代表小组活动应当有专门的记载，作为代表履职的重要内容。\n第十六条 乡镇人民代表大会代表应当积极参加主席团组织的闭会期间的活动，每名代表每年参加活动的时间不少于五天。每届任期内参加主席团组织的视察、调研、执法检查、工作评议等活动不少于五次，提出议案或者建议、批评和意见不少于五件，参加代表培训不少于两次。\n第十七条 乡镇人民代表大会代表应当保持同人民群众之间的联系，向人民群众宣传党的路线、方针、政策，国家法律、法规以及本级人民代表大会的决议、决定，并了解贯彻落实情况；走访、接待人民群众，听取人民群众的意见、建议，了解人民群众的要求；向原选区选民报告执行代表职务、履行代表义务的情况，回答选民提问，接受选民监督。\n第十八条 乡镇人民代表大会代表应当正确处理个人职业活动与执行代表职务的关系，不得利用代表身份，干涉行政执法、具体司法案件或者招标投标等经济活动，牟取私利；不得在会议期间和参加履职活动时从事商业活动；代表执行代表职务，不得接受企业事业单位、社会团体和个人的资助。\n第十九条 乡镇人民代表大会代表因工作变动不宜继续担任代表的，应当辞去代表职务；违反社会公德或者存在与代表身份不符的行为，本级人民代表大会主席团应当及时约谈或者函询，经提醒仍不改正的，应当责令其辞去代表职务；涉嫌严重违纪违法，犯罪事实已查清依法需要追究刑事责任的，应当责令其辞去代表职务或者依法罢免其代表职务。\n第二十条 各级国家机关和组织应当支持代表履职，为其履职提供物质保障和工作便利。\n代表在履职时，其所在单位应当给予时间保障，按照正常出勤对待，享受所在单位的工资和其他福利待遇。无固定工资收入的代表执行代表职务，根据实际情况由财政给予适当补贴。\n第二十一条 乡镇人民代表大会会议经费、代表活动经费、选举工作经费、办公经费应当列入财政预算并予以保证，专款专用。\n第二十二条 乡镇人民代表大会应当配备工作人员，协助乡镇人民代表大会主席团及主席、副主席开展工作。\n第二十三条 县级以上人民代表大会及其常务委员会依法加强对乡镇人民代表大会工作的联系、指导和监督。\n第二十四条 本条例自2016年11月1日起施行。1990年3月3日湖北省第七届人民代表大会常务委员会第十二次会议通过、1995年11月30日湖北省第八届人民代表大会常务委员会第十七次会议第一次修改、2010年7月30日湖北省第十一届人民代表大会常务委员会第十七次会议第二次修改的《湖北省乡镇人民代表大会主席团工作若干规定》同时废止。","level":0}]},{"id":"h0184","sections":[{"name":"","text":"（2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议通过 2026年5月28日湖北省第十四届人民代表大会常务委员会第二十四次会议修订）","level":0},{"name":"第一章 总则","text":"第一条 为了保障未成年人身心健康，培养未成年人良好品行，有效预防未成年人违法犯罪，根据《中华人民共和国预防未成年人犯罪法》和有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内未成年人犯罪的预防。\n第三条 预防未成年人犯罪是全社会的共同责任。\n预防未成年人犯罪工作坚持在党委领导、政府组织下，实行预防为主、依法矫治、综合治理。\n开展预防未成年人犯罪工作，应当尊重未成年人人格尊严，保护未成年人的名誉权、隐私权和个人信息等合法权益。\n第四条 省、市（州）、县（市、区）建立由平安建设主管机关负责，政府有关部门、人民检察院、人民法院、共产主义青年团、妇女联合会、关心下一代工作委员会等单位组成的预防未成年人犯罪工作协调机制，及时协调、解决预防未成年人犯罪工作中的重大问题。\n第五条 县级以上人民政府在预防未成年人犯罪工作方面履行下列职责：\n（一）将预防未成年人犯罪工作纳入本级国民经济和社会发展规划，制定预防未成年人犯罪工作规划和年度实施计划；\n（二）组织开展预防未成年人犯罪工作；\n（三）为预防未成年人犯罪工作提供政策支持和保障，将相关经费纳入本级财政预算；\n（四）组织开展监测评估、执法检查等；\n（五）组织开展预防未成年人犯罪宣传教育；\n（六）其他预防未成年人犯罪工作职责。\n乡镇人民政府、街道办事处依法做好本辖区内的预防未成年人犯罪工作。\n村（居）民委员会在乡镇人民政府、街道办事处指导下，依法做好预防未成年人犯罪有关工作。\n第六条 公安、司法行政、教育、财政、民政、人力资源和社会保障、文化和旅游、市场监督管理、网信、卫生健康、新闻出版、广播电视、电影、通信管理等有关部门，人民检察院、人民法院，应当按照各自职责做好预防未成年人犯罪工作。\n共产主义青年团、妇女联合会、工会、残疾人联合会以及有关社会组织应当按照职责做好预防未成年人犯罪工作，为预防未成年人犯罪培育社会力量，提供支持服务。\n第七条 省人民政府将专门教育发展和专门学校建设纳入国民经济和社会发展规划以及教育发展规划。专门教育工作由省人民政府统筹指导，属地教育行政部门主管，公安机关、司法行政部门、人民检察院、人民法院等相关单位协同配合。\n县级以上人民政府成立专门教育指导委员会。专门教育指导委员会负责研究确定专门学校教学、管理等相关工作，组织开展专门学校学生入学、转回普通学校就读等事项的评估。\n第八条 任何组织或者个人不得教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，以及为未成年人实施上述行为提供条件。\n第九条 接受专门教育、社区矫正、社会观护，以及被采取戒毒措施、刑满释放的未成年人，在复学、升学、就业等方面依法享有与其他未成年人同等的权利，任何单位和个人不得歧视。\n第十条 建立健全省内跨行政区域的预防未成年人犯罪工作联动机制，加强信息共享、联动协作。加强省际预防未成年人犯罪工作的交流、协作。\n第十一条 对在预防未成年人犯罪工作中作出突出贡献的组织和个人，按照国家和省有关规定给予表彰和奖励。","level":1},{"name":"第二章 预防支持体系","text":"第十二条 省、市（州）、县（市、区）建立健全部门配合、专业保障、社会协同、公众参与的预防未成年人犯罪工作支持服务体系，提高预防未成年人犯罪工作的专业化、社会化、智能化水平。\n第十三条 省、市（州）、县（市、区）平安建设主管机关应当加强预防未成年人犯罪工作信息化建设，组织有关部门依法做好信息共享、隐患排查和犯罪预警等工作，对未成年人违法犯罪相关信息进行识别、分析、预警，提高科学研判、干预处置的能力和水平。\n第十四条 公安机关、人民检察院、人民法院应当建立健全办理未成年人案件人才储备和培养机制，由专门机构或者经过专业培训、熟悉未成年人身心特点的专门人员负责预防未成年人犯罪工作。\n第十五条 公安、司法行政、教育、人力资源和社会保障、民政等部门，人民检察院、人民法院，以及共产主义青年团、妇女联合会等人民团体根据需要，加强预防未成年人犯罪志愿服务队伍建设。\n鼓励和支持志愿服务组织和志愿者参与预防未成年人犯罪工作，提供心理干预、家庭教育指导等志愿服务。\n第十六条 鼓励和支持社会工作服务机构等社会组织、社会工作者参与预防未成年人犯罪工作。\n有关部门和单位可以通过政府购买服务等方式，委托社会工作服务机构等社会组织开展预防未成年人犯罪的宣传教育、家庭教育指导、心理辅导和司法社会服务等工作，并加强对受托方的指导监督。\n第十七条 鼓励和支持高等学校、科研机构加强预防未成年人犯罪相关的学科建设、人才培养以及科学研究，开展国内外交流合作，为预防未成年人犯罪工作提供专业支撑。\n第十八条 12355青少年服务台应当受理可能涉及未成年人违法犯罪的咨询与求助，提供针对心理危机、家庭关系危机、人际交往危机、学生欺凌等容易引发未成年人犯罪问题的专业咨询服务。\n推进青少年服务台与110报警服务台、12345政务服务便民热线、12356心理援助热线、12309检察服务热线等互联互通，及时处置有关事项；对可能存在未成年人犯罪行为或者未成年人遭受不法侵害的，应当立即向公安机关报告。\n鼓励和支持国家机关、人民团体、社会组织、企业事业单位以及社会工作者、志愿者、心理咨询师、律师等通过青少年服务台提供预防未成年人违法犯罪方面的咨询、帮助。\n第十九条 有关单位、社会组织及其工作人员在预防未成年人犯罪工作中知悉的未成年人隐私、个人信息等，应当依法予以保密，不得泄露、篡改、毁损，不得出售或者非法向他人提供。","level":1},{"name":"第三章 预防犯罪的教育","text":"第二十条 国家机关、社会、学校和家庭应当加强未成年人社会主义核心价值观教育，开展预防犯罪教育和心理健康教育，增强未成年人的法治观念，提高未成年人防范违法犯罪的意识和自我管控能力。\n第二十一条 未成年人的父母或者其他监护人对未成年人的预防犯罪教育负有直接责任，应当采取下列措施，依法履行监护职责：\n（一）树立优良家风，引导未成年人养成积极健康的思想品德和行为习惯，为未成年人营造良好的家庭环境；\n（二）关注未成年人的生理、心理状况和情感需求，经常与未成年人沟通、交流，发现未成年人心理或者行为异常的，及时了解情况并进行教育和引导，必要时送相关专业机构诊治；\n（三）鼓励、引导未成年人参加有益身心健康的活动，避免沉迷网络、接触不良信息，或者进入不适宜未成年人活动的场所；\n（四）依法保障未成年人受教育的权利，及时了解未成年人在校情况，积极配合学校的教育和学生欺凌防控等工作；\n（五）自觉接受有关单位和组织开展的家庭教育指导。\n未成年人的父母或者其他监护人不得拒绝或者怠于履行监护职责。未成年人的父母分居或者离异的，应当互相配合做好未成年子女的预防犯罪教育。\n公安机关、学校、村（居）民委员会在工作中发现未成年人监护人缺失或者监护人无监护能力的，应当及时告知民政部门，由民政部门依法对未成年人进行临时监护。\n第二十二条 县级以上人民政府应当将家庭教育指导服务纳入城乡公共服务体系，根据需要确定家庭教育指导机构。\n家庭教育指导机构应当对辖区内学校（社区）家长学校及其他家庭教育指导服务站点进行指导，及时向有需求的家庭提供服务。\n鼓励和支持有关人民团体、社会组织、企业事业单位，依托学校、工人文化宫、青少年宫、妇女儿童活动中心、未成年人成长指导中心（社会实践基地）等设立家庭教育指导服务站点，开展家庭教育指导服务。\n第二十三条 未成年人家庭有下列情形之一的，家庭教育指导机构应当根据需求及时提供家庭教育指导服务：\n（一）未成年人实施学生欺凌行为的；\n（二）留守、困境未成年人家庭，或者家庭发生重大变故、未成年人曾遭受违法犯罪侵害的；\n（三）父母或者其他监护人被强制隔离戒毒、服刑或者侵犯未成年人合法权益的；\n（四）父母或者其他监护人对未成年人监护教育不当或者失管失教的；\n（五）其他需要提供家庭教育指导服务的情形。\n第二十四条 教育行政部门、学校应当将预防犯罪教育纳入学校教学计划，指导教职员工结合未成年人的特点，采取多种方式对未成年学生进行有针对性的预防犯罪教育。\n学校应当聘任从事法治教育的专职或者兼职教师，并按照国家有关规定聘任法治副校长，开展预防犯罪法治教育。\n鼓励和支持学校聘请社会工作者协助开展道德教育、法治教育、生命教育、青春期教育和心理健康教育等，参与预防和处理学生欺凌等工作。\n第二十五条 学校应当配备专职或者兼职的心理健康教育教师，开设心理健康课程，对未成年学生进行心理健康教育与辅导。学校应当设立心理辅导场所，根据实际情况与专业心理健康机构合作，为未成年学生提供心理健康筛查、咨询辅导与早期干预服务，预防和解决未成年学生心理、行为异常问题。\n学校应当与未成年学生的父母或者其他监护人加强沟通，共同做好未成年学生心理健康教育；发现未成年学生可能患有精神障碍的，应当立即告知其父母或者其他监护人，协助送相关专业机构诊治。\n第二十六条 教育行政部门应当会同有关部门建立健全学生欺凌防控制度，加强督导检查。\n学校应当按照规定建立学生欺凌防控工作早期预警、事中处理和事后干预制度，对教职员工、未成年学生等开展学生欺凌防范处置的教育培训，公布举报、求助渠道，定期开展学生欺凌调查评估。\n学校发现欺凌行为的，应当及时制止，并通知学生父母或者其他监护人，对实施欺凌的未成年学生加强管理教育；情节严重的，应当及时向公安机关、教育行政部门报告，并由公安机关依法采取相应的矫治教育措施。\n学校应当及时采取措施保护和帮助遭受欺凌的未成年学生，开展相应的心理疏导等。\n第二十七条 学校应当对有不良行为或者严重不良行为的未成年学生进行有针对性的教育，并与其父母或者其他监护人加强沟通，帮助未成年学生予以纠正。\n第二十八条 学校、幼儿园周边200米范围内不得设置营业性娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所。\n营业性歌舞娱乐场所、酒吧、互联网上网服务营业场所以及其他法律法规规定未成年人不宜进入的场所，不得允许未成年人进入。电竞酒店、文身服务场所等不得向未成年人提供服务。\n前款规定的营业场所应当在入口、大厅等显著位置设置禁止未成年人进入的标志，公布监督举报电话；对难以判明是否是未成年人的，应当要求其出示身份证件。\n公安、文化和旅游、市场监督管理、卫生健康等部门应当加强对前款规定的营业场所的监督检查。发现未成年人进入的，应当及时劝离，对有关经营者依法予以处理。\n第二十九条 乡镇人民政府、街道办事处应当对留守或者困境未成年人家庭建档立卡，提供生活帮扶、创业就业支持等关爱服务，为其监护人履行监护职责、实施家庭教育创造条件。\n学校、村（居）民委员会应当按照规定建立留守或者困境未成年人的信息档案，安排专人负责留守或者困境未成年人的关爱帮扶，协助提供监护指导，开展生活帮助、精神关怀、心理疏导等关爱服务，支持配合有关单位和社会组织等开展关爱服务。\n第三十条 政府及有关部门应当开展预防未成年人网络犯罪普法宣传，建立未成年人网络保护执法协作机制，依法查处涉未成年人网络违法犯罪行为。\n网络产品和服务提供者不得向未成年人提供诱导其沉迷的产品和服务。网络游戏、网络直播、网络音视频、网络社交等网络服务提供者应当针对未成年人设置身份验证、时间管理、消费管理等功能。\n第三十一条 教育、公安、司法行政、卫生健康等部门以及学校应当对未成年人进行毒品和具有成瘾性物质的危害教育，防止其吸食、注射毒品，或者滥用未列入国家规定管制的成瘾性物质。\n任何单位和个人不得强迫、引诱、教唆或者容留未成年人吸食、注射毒品和未列入国家规定管制的成瘾性物质，或者为未成年人实施上述行为提供条件。\n司法行政部门应当发挥戒治康复场所作用，依法面向滥用未列入国家规定管制的成瘾性物质的未成年人，提供戒断治疗和康复服务。\n第三十二条 鼓励有条件的国家机关、人民团体、社会组织、企业事业单位建立青少年法治教育基地，对未成年人开展法治教育。\n鼓励和支持学校联合青少年宫、妇女儿童活动中心等场所，对未成年人开展多种形式的法治宣传教育。","level":1},{"name":"第四章 对不良行为的干预","text":"第三十三条 未成年人不良行为，是指未成年人实施的不利于其健康成长的下列行为：\n（一）吸烟（含电子烟）、饮酒、文身；\n（二）非医疗目的滥用药品，或者滥用未列入国家规定管制的成瘾性物质；\n（三）多次旷课、逃学；\n（四）无故夜不归宿、离家出走；\n（五）沉迷网络；\n（六）与社会上具有不良习性的人交往，组织或者参加实施不良行为的团伙；\n（七）进入法律法规规定未成年人不宜进入的场所；\n（八）参与赌博、变相赌博，或者参加封建迷信、邪教等活动；\n（九）阅览、观看或者收听宣扬淫秽、色情、暴力、邪教、恐怖、极端等内容的读物、音像制品或者网络信息等；\n（十）其他不利于未成年人身心健康成长的不良行为。\n第三十四条 未成年人的父母或者其他监护人发现未成年人有不良行为的，应当及时制止并加强管教。在干预未成年人不良行为时遇到困难的，可以向学校、村（居）民委员会或者有关国家机关、人民团体、社会组织等寻求帮助，有关单位或者组织应当及时提供帮助。\n公安机关、村（居）民委员会发现本辖区内未成年人有不良行为的，应当及时制止，并督促其父母或者其他监护人依法履行监护职责。\n第三十五条 学校对有不良行为的未成年学生，应当予以制止，并加强管理教育；对拒不改正或者情节严重的，学校可以根据情况依法予以处分或者采取相应管理教育措施。\n未成年学生扰乱课堂秩序、学校教育教学秩序的，学校、教师应当予以制止；拒不改正或者情节严重的，学校可以采取相应的管理教育措施。\n学校应当及时将采取管理教育措施的相关情况告知未成年学生的父母或者其他监护人。未成年学生的父母或者其他监护人对学校管理教育措施有异议的，可以向教育行政部门提出申诉。\n第三十六条 未成年学生旷课、逃学的，学校应当及时联系其父母或者其他监护人，了解有关情况，必要时可以家访，对其父母或者其他监护人提供指导和帮助；无正当理由的，学校和未成年学生的父母或者其他监护人应当督促其返校学习。\n公安、民政等有关部门在工作中发现未成年学生存在无正当理由旷课、逃学等情况，应当及时与学校、未成年学生的父母或者其他监护人、村（居）民委员会取得联系，督促未成年学生返校学习。\n第三十七条 未成年人无故夜不归宿、离家出走的，父母或者其他监护人、所在的寄宿制学校应当及时查找，必要时向公安机关报告。\n对夜不归宿、离家出走或者流落街头的未成年人，公安机关、公共场所管理机构等发现或者接到报告后，应当及时采取有效保护措施，并通知其父母或者其他监护人、所在的寄宿制学校，必要时应当护送其返回住所、学校；无法与其父母或者其他监护人、学校取得联系的，应当护送未成年人到救助保护机构接受救助。\n第三十八条 教育行政部门和学校应当加强对教师的指导和培训，提高教师对未成年学生不良行为的早期识别和干预能力。","level":1},{"name":"第五章 对严重不良行为的矫治","text":"第三十九条 未成年人严重不良行为，是指未成年人实施的有刑法规定、因不满法定刑事责任年龄不予刑事处罚的行为，以及严重危害社会的下列行为：\n（一）结伙斗殴，追逐、拦截他人，强拿硬要或者任意损毁、占用公私财物等寻衅滋事行为；\n（二）非法携带枪支、弹药或者弩、匕首等国家规定的管制器具；\n（三）殴打、辱骂、恐吓，或者故意伤害他人身体；\n（四）盗窃、哄抢、抢夺或者故意损毁公私财物；\n（五）传播淫秽的读物、音像制品或者信息等；\n（六）卖淫、嫖娼，或者进行淫秽表演；\n（七）吸食、注射毒品，或者向他人提供毒品；\n（八）参与赌博赌资较大；\n（九）其他严重危害社会的行为。\n第四十条 未成年人的父母或者其他监护人以及学校、村（居）民委员会等对未成年人负有教育、看护、救助等职责的单位，发现有人教唆、胁迫、引诱未成年人实施严重不良行为的，应当立即向公安机关报告。公安机关接到报告或者发现有上述情形的，应当及时依法查处；对人身安全受到威胁的未成年人，应当立即采取有效保护措施。\n第四十一条 公安机关接到举报或者发现未成年人有严重不良行为的，应当及时制止，依法调查处理，并可以责令其父母或者其他监护人消除或者减轻违法后果，采取措施严加管教。\n公安机关可以根据具体情况对有严重不良行为的未成年人依法采取矫治教育措施，并根据需要邀请学校、村（居）民委员会以及社会工作服务机构等社会组织参与矫治教育。\n第四十二条 未成年人驾驶机动车或者非法改装的车辆轰鸣疾驶、追逐竞驶，或者在经营场所从事陪酒、陪唱等有偿陪侍活动的，公安机关可以依照本条例第四十一条规定采取相应的矫治教育措施。\n第四十三条 县级以上人民政府根据需要合理设置专门学校，加强对专门学校经费、人员、教育场所和设施等方面的保障，确保专门学校的财政保障水平高于当地普通学校。\n专门学校应当依法举办。除政府批准设立的专门学校外，任何组织或者个人不得以任何形式或者名义开展教育矫治类活动。\n专门学校应当充分尊重、关心、爱护学生，不得侮辱、体罚、虐待学生，不得采取损害学生身心健康的教育管理措施。\n专门学校应当与接受专门教育的未成年人的父母或者其他监护人加强联系，定期向其反馈未成年人的矫治和教育情况，为父母或者其他监护人、亲属等看望未成年人提供便利。\n第四十四条 本省专门学校建设、专门教育具体办法，由省人民政府教育行政部门会同有关部门制定。\n教育、人力资源和社会保障等有关部门应当建立健全适用于专门学校的教师职称评审、岗位聘用、奖励激励等机制。\n第四十五条 省人民政府结合实际情况确定符合条件的专门学校，按照分校区、分班级等方式设置专门场所，实施专门矫治教育。\n专门矫治教育场所实行闭环管理，公安机关、司法行政部门负责未成年人的矫治工作，教育行政部门承担未成年人的教育工作。\n对有严重不良行为的未成年人，需要送专门学校接受专门教育和专门矫治教育的，按照国家有关规定执行。\n第四十六条 专门学校应当统筹整合资源，按照义务教育、普通高中教育、职业教育贯通模式进行建设，合理设置课程；对未完成义务教育的未成年人，应当保证其继续接受义务教育。\n第四十七条 对经专门教育指导委员会评估适合转回普通学校就读的未成年学生，原决定机关决定将其转回普通学校的，其原所在学校不得拒绝接收。因特殊情况，不适宜转回原所在学校的，由教育行政部门安排转学。\n专门学校的未成年学生的学籍保留在原学校。专门学校学生毕业可以参加由教育行政部门组织的统一考试，也可以由专门学校根据学生特点，报经教育行政部门批准，自行命题单独组织考试，或者结合平时表现进行形成性评价。考核合格的，由教育行政部门核发原学校毕业证。\n符合参加升学考试条件的学生，可以用原学校学籍报名参加升学考试。\n第四十八条 教育、公安、司法行政、人力资源和社会保障等有关部门，以及人民团体、村（居）民委员会应当会同专门学校加强对离校未成年人的针对性教育帮扶。\n专门学校应当做好离校未成年人跟踪帮扶工作，及时发现和帮助解决就业、就学和生活上的问题。跟踪帮扶情况应当定期向专门教育指导委员会报告。","level":1},{"name":"第六章 对重新犯罪的预防","text":"第四十九条 公安机关、人民检察院、人民法院办理未成年人刑事案件，应当采用适合未成年人身心特点的办案制度和措施，并根据未成年人的生理、心理特点和犯罪的情况，结合其平常表现、家庭情况、犯罪原因、悔罪态度等开展法治教育，预防未成年人重新犯罪。\n公安机关、人民检察院、人民法院可以根据相关法律规定，对未成年犯罪嫌疑人、被告人进行社会调查和心理测评。社会调查和心理测评的报告可以作为办理案件和教育未成年人的参考。\n人民检察院、人民法院可以结合检察、审判办案实践，定期开展未成年人犯罪形势、特点和规律分析，提出预防未成年人犯罪社会治理建议。\n第五十条 公安机关、人民检察院、人民法院可以依托社会力量建立社会观护基地，共同做好未成年人取保候审观护帮教、附条件不起诉监督考察等工作，帮助其回归社会。\n鼓励和支持社会组织、社会工作者、志愿者对接受社会观护的未成年人提供生活帮助、心理干预、职业技能培训、就业指导、社会融入等支持和服务。\n社会观护基地应当建立观护对象的档案管理制度和信息保密制度，定期向有关机关报告观护情况。\n第五十一条 社区矫正机构应当针对未成年社区矫正对象的年龄、心理特点、发育需要、成长经历、犯罪原因、家庭监护教育条件等情况，采取有益其身心健康的监督管理措施；对未成年人的社区矫正应当与成年人分别进行。\n第五十二条 县级以上人民政府应当依法履行对刑满释放、接受社区矫正的未成年人的安置帮教工作职责，支持、督促司法行政部门与政府有关部门、人民检察院、人民法院、共产主义青年团、妇女联合会等单位协同配合，做好刑满释放和接受社区矫正的未成年人的就学就业、心理疏导、技能培训、帮扶救助等工作。\n未成年人的父母或者其他监护人、学校、村（居）民委员会对刑满释放和接受社区矫正的未成年人，应当在家庭关系修复、校园融入、邻里接纳等方面采取帮教措施，协助做好安置帮教工作。\n鼓励社会组织、企业事业单位和个人协助做好安置帮教工作。\n第五十三条 公安机关、司法行政部门、人民检察院、人民法院应当采取有效措施依法封存未成年人接受专门教育、专门矫治教育的记录，被行政处罚、采取刑事强制措施和不起诉的记录以及犯罪记录，但司法机关因办案需要或者有关单位根据国家有关规定进行查询的除外；保密的信息包括办案等过程中形成的案卷材料和电子档案信息。\n第五十四条 人民检察院依法对未成年人重新犯罪预防工作进行监督，发现违法行为或者不当履职情形的，可以提出检察建议或者启动相关监督程序。","level":1},{"name":"第七章 法律责任","text":"第五十五条 违反本条例，法律、法规有规定的，从其规定。\n第五十六条 违反本条例规定，未成年人的父母或者其他监护人拒绝或者怠于履行监护职责，放任未成年人实施严重不良行为或者犯罪行为的，由公安机关、人民检察院、人民法院予以训诫，并可以通过家庭教育指导令、督促监护令等形式责令其接受家庭教育指导、履行监护职责。\n第五十七条 学校及其教职员工违反本条例规定，不履行预防未成年人犯罪工作职责或者歧视、虐待相关未成年人的，由教育等部门责令改正，通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。构成违反治安管理行为的，由公安机关依法予以治安管理处罚。\n教职员工教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，以及品行不良、影响恶劣的，教育行政部门、学校应当依法予以解聘或者辞退。\n第五十八条 教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，构成违反治安管理行为的，由公安机关依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。\n第五十九条 国家机关及其工作人员在预防未成年人犯罪工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附则","text":"第六十条 本条例所称学校，是指普通中小学、特殊教育学校、中等职业学校、专门学校。\n第六十一条 本条例自2026年8月1日起施行。","level":1}]},{"id":"h0185","sections":[{"name":"","text":"（2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了防治林业有害生物，保护森林资源，维护生态安全，根据《中华人民共和国森林法》、《森林病虫害防治条例》、《植物检疫条例》等有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内的林业有害生物预防、治理和森林植物及其产品检疫等活动，适用本条例。\n林业有害生物是指对森林植物及其产品构成危害或者威胁的动物、植物和微生物。\n森林植物及其产品，包括乔木、灌木、竹类、花卉和其他森林植物，林木种子、苗木和其他繁殖材料，木材、竹材、药材、干果、盆景和其他林产品。\n第三条 林业有害生物防治工作遵循预防为主、综合治理、科学防治的原则，实行政府主导、部门协作、社会参与的工作机制。\n第四条 县级以上人民政府应当将林业有害生物防治工作纳入国民经济和社会发展规划，建立健全林业有害生物监测预警、检疫御灾、防治减灾体系，将林业有害生物防治工作纳入目标责任制考核内容。\n乡镇人民政府、街道办事处应当做好林业有害生物防治相关工作，组织村（居）民委员会、林业协会、专业合作社、林业生产经营者等开展林业有害生物防治工作。\n第五条 县级以上人民政府林业主管部门负责本行政区域内林业有害生物防治工作，其所属的林业有害生物防治检疫机构负责林业有害生物监测预警、检验检疫、防治督查以及相关技术服务、业务培训等工作。\n县级以上人民政府有关部门和单位按照各自职责，共同做好林业有害生物防治工作。\n第六条 林业生产经营者应当依法做好其所属或者经营管理的森林、林木的有害生物预防和治理工作。\n第七条 鼓励和支持公民、法人以及其他社会组织参与林业有害生物防治工作。\n各级人民政府及有关部门、新闻媒体应当加强林业有害生物防治知识的宣传普及，增强公众防御林业有害生物灾害的意识和能力，拓展公众参与林业有害生物防治的途径。\n县级以上人民政府及有关部门对在林业有害生物防治工作中做出突出贡献的单位和个人，给予表彰和奖励。","level":1},{"name":"第二章 预防","text":"第八条 县级以上人民政府林业主管部门应当制定本地区林业有害生物防治规划，科学布局测报站（点）、配备专（兼）职测报员，完善测报网络，组织开展监测预报工作。\n第九条 县级以上人民政府林业主管部门应当每五年组织一次林业有害生物普查，对重大、突发林业有害生物及时组织专项调查，并向本级人民政府和上级林业主管部门报告普查、调查情况。\n第十条 国有森林、林木由其经营管护单位组织开展林业有害生物监测。集体和个人所有的森林、林木由乡镇林业工作站组织开展监测；未设立林业工作站的，由县级以上人民政府确定相关机构开展监测。\n单位和个人发现森林植物出现异常情况，应当及时向林业主管部门报告，林业主管部门应当及时调查核实。\n第十一条 林业有害生物防治检疫机构应当按照国家规定定期发布林业有害生物短、中、长期趋势预报，及时发布重大或者突发林业有害生物预警信息，并提出防治建议或者方案。\n其他任何单位和个人不得发布林业有害生物预警预报信息。禁止伪造、篡改林业有害生物预警预报信息。\n气象部门应当无偿提供监测林业有害生物所需的公益性气象服务。广播、电视、报刊、网络等媒体应当无偿刊播林业有害生物预警预报信息。\n第十二条 县级以上人民政府林业主管部门应当将林业有害生物防治措施纳入造林绿化设计方案和森林经营方案，科学配置造林绿化树种，推广良种壮苗和抗性树（品）种。对林业有害生物灾害常发区，实施以营林措施为主，生物、化学和物理防治相结合的综合治理措施。\n林业生产经营者应当采取林业有害生物防治措施，优先选用优良乡土树种，采用混交栽植模式，适地适树适种源造林。\n禁止使用带有危险性林业有害生物的林木种子、苗木和其他繁殖材料进行育苗或者造林。\n第十三条 自然（文化）遗产保护区、自然保护区、森林公园、湿地公园、风景名胜区以及古树名木等需要特别保护的区域或者林木，由县级以上人民政府划定公布为林业有害生物重点预防区，并督促有关单位制定防治预案。\n林业有害生物重点预防区的经营管理者应当建立管护制度，采取防护措施，防止外来林业有害生物入侵。\n第十四条 县级以上人民政府应当制定林业有害生物防治应急预案，组建专群结合的应急防治队伍，加强林业有害生物应急防治设备、药剂的储备。\n第十五条 林业主管部门应当加强对林业有害生物监测预报站（点）及其监测设施的建设和维护。\n任何单位和个人不得占用、移动、损毁监测预报站（点）的监测设施或者破坏其周边环境。\n因城乡建设需要迁移监测预报站（点）的，应当征得林业主管部门同意，并承担相应费用。","level":1},{"name":"第三章 检疫","text":"第十六条 省人民政府林业主管部门应当根据国家林业检疫性有害生物名单和本省林业有害生物疫情情况，确定和调整本省的补充名单并向社会公布。\n林业有害生物防治检疫机构应当按照前款规定的名单实施检疫。\n第十七条 省人民政府林业主管部门应当建立森林植物及其产品检疫追溯信息系统，实行检疫标识管理，实现森林植物及其产品生产、运输、销售、使用全过程监管。\n第十八条 生产、经营林木种子、苗木和其他繁殖材料的单位或者个人，应当依法向林业有害生物防治检疫机构申请产地检疫。检疫不合格的，受检单位或者个人应当按照规定进行除害处理。\n第十九条 应施检疫的森林植物及其产品进入流通环节的，生产经营者应当依法向林业有害生物防治检疫机构申请流通检疫。\n应施检疫的森林植物及其产品跨县流通的，输入地林业有害生物防治检疫机构应当查验检疫证书。森林植物及其产品在省际间流通的，应当符合输入地检疫要求。\n对可能被检疫对象污染的包装材料、运载工具、场地、仓库等，林业有害生物防治检疫机构应当实施检疫。已被污染的，托运人应当按照要求进行除害处理。\n按照本条第一款规定运输应施检疫的森林植物及其产品，托运人不出具植物检疫证书的，承运人不得承运或者收寄。植物检疫证书应当随货运寄。\n第二十条 从国外引进林木种子、苗木，引进单位应当按照国家规定进行林业有害生物引种风险性评估，并向省林业有害生物防治检疫机构申请办理检疫审批手续；对可能潜伏有危险性林业有害生物的林木种子、苗木应当隔离试种，经试种确认不带危险性林业有害生物的，方可种植。\n出入境检验检疫、边防、海关等部门应当加强境外重大植物疫情输入风险管理，并与林业有害生物防治检疫机构建立信息沟通机制，共同做好防范外来有害生物入侵工作；林业有害生物防治检疫机构应当做好引种后的检疫监管工作。\n第二十一条 发生林业有害生物疫情时，应当按照国家有关规定划定疫区。\n林业有害生物防治检疫机构应当加强对木材流通场所、苗木集散地、车站、港口和市场等重点地区的检疫检查；发生特大疫情时，经省人民政府批准，可以设立临时林业植物检疫检查站开展检疫工作。\n第二十二条 在林地及其边缘500米范围内施工，使用松木或者其他可能携带疫病的木质材料承载、包装、铺垫、支撑、加固设施设备的，建设单位应当事先将施工时间、地点向林业有害生物防治检疫机构报告。\n施工结束后，建设单位应当及时回收、销毁松木或者其他可能携带疫病的木质材料，不得随意弃置。林业有害生物防治检疫机构应当对回收、销毁情况进行监督检查和技术指导。","level":1},{"name":"第四章 治理","text":"第二十三条 县级以上人民政府应当按照林业有害生物的危害程度和影响范围，对林业有害生物灾害实行分级管理。具体办法由省人民政府制定。\n第二十四条 林业有害生物的治理实行分类管理。\n生态公益林的林业有害生物治理和非生态公益林的重大、突发林业有害生物治理由县级以上人民政府负责，林业主管部门组织实施；生产经营者应当配合。\n非生态公益林的一般林业有害生物治理由生产经营者负责，县级以上人民政府给予适当补贴。\n第二十五条 林业生产经营者应当按照林业主管部门的要求，做好林业有害生物治理工作。\n林业主管部门应当做好林业有害生物治理技术指导和服务，并对治理情况进行监督检查。\n第二十六条 对新发现和新传入的林业有害生物，县级以上人民政府林业主管部门应当及时查清情况，报告省人民政府林业主管部门，并组织有关部门、林业经营者采取封锁、扑灭等必要的除治措施。\n第二十七条 对跨行政区域、危害严重的林业有害生物灾害，相邻地区人民政府及其林业主管部门应当加强协作配合，建立林业有害生物联防联治机制，健全疫情监测、信息通报和定期会商制度，开展联合防治。\n相邻地区共同的上级人民政府及其林业主管部门应当加强对跨行政区域林业有害生物灾害联防联治的组织协调和指导监督。\n县级以上人民政府林业主管部门应当鼓励和支持林业生产经营者建立联户、联组、联村的防治联合体和应急处置联合队，开展群防群治。\n第二十八条 发生重大、突发林业有害生物灾害或者疫情时，县级以上人民政府应当及时启动林业有害生物防治应急预案，必要时成立林业有害生物防治临时指挥机构，解决林业有害生物治理工作中的重大问题。\n第二十九条 因防治重大、突发林业有害生物灾害或者疫情需要，经县级以上林业有害生物防治检疫机构鉴定，报请县级以上人民政府林业主管部门同意，可以先行采伐林木，再按照规定办理相关手续；林业有害生物防治检疫机构应当指导相关单位或者个人进行除害处理。\n采伐疫木的单位或者个人应当按照疫区和疫木管理规定作业，并做好采伐山场和疫木堆场监管。任何单位或者个人不得擅自捡拾、挖掘、采伐疫木及其剩余物。\n实行疫木安全定点利用制度。疫木的安全利用，按照疫木安全利用管理规定，在林业有害生物防治检疫机构的监督下实施。\n第三十条 对在林业有害生物防治过程中强制清除、销毁森林植物及其产品和相关物品的，县级以上人民政府应当给予补偿，因生产经营者违法行为造成林业有害生物灾害或者疫情的除外。补偿的标准、程序、范围由省人民政府另行规定。\n第三十一条 省人民政府及其林业主管部门应当建立林业有害生物绿色防治体系和社会化服务机制，加大补贴和扶持力度，鼓励和支持生物防治技术的研发、引进、推广和使用，提高林业有害生物防治的科学技术水平。\n林业有害生物防治的措施、方法和技术应当进行生态环境风险评估，保护有益生物，保证人畜安全，防止污染环境。","level":1},{"name":"第五章 保障","text":"第三十二条 县级以上人民政府应当将林业有害生物防治纳入政府公共服务体系和防灾减灾体系，建立财政资金和社会资金相结合的多元化资金投入机制，加强林业有害生物防治基础设施建设，完善林业有害生物防治保障措施。\n第三十三条 县级以上人民政府应当将林业有害生物普查、监测、检疫、治理和监督管理所需经费纳入本级财政预算；对突发性林业有害生物灾情根据需要安排专项经费。\n自然（文化）遗产保护区、自然保护区、森林公园、湿地公园、风景名胜区以及古树名木等需要特别保护的区域和其他依托森林资源从事旅游活动的景区景点的管理者、经营者，应当安排专项资金用于林业有害生物防治。\n第三十四条 县级以上人民政府应当加强林业有害生物防治检疫机构队伍建设，合理配备专业技术人员，强化业务培训，保持队伍专业性和相对稳定。\n第三十五条 鼓励和扶持社会化防治组织开展林业有害生物调查监测、灾害鉴定、风险评估、疫情治理及其监理等活动。\n鼓励向林业有害生物社会化防治组织购买服务。\n第三十六条 县级以上人民政府应当出台激励措施，支持林业生产经营者参加林业有害生物灾害保险，鼓励保险机构开展林业有害生物灾害保险业务。\n第三十七条 任何单位和个人发现林业有害生物疫情的，应当向林业主管部门报告；对不依法履行林业有害生物防治义务和监督管理职责的行为，有权举报。\n县级以上人民政府林业主管部门和有关机关应当健全举报制度，公布举报电话，及时核实举报情况，依法处理并适时反馈；对查证属实的，给予奖励。","level":1},{"name":"第六章 法律责任","text":"第三十八条 违反本条例，法律、法规有规定的，从其规定；造成他人损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第三十九条 违反本条例第十一条第二款，擅自发布或者伪造、篡改林业有害生物预警预报信息的，由林业主管部门给予警告，责令改正，并处5千元以上1万元以下罚款；造成严重后果的，处1万元以上2万元以下罚款。\n第四十条 违反本条例第十五条第二款，占用、移动、损毁林业有害生物监测预报站（点）的监测设施或者破坏其周边环境的，由林业主管部门责令停止违法行为，限期改正，恢复原状；逾期不改正的，处5千元以上1万元以下罚款。\n第四十一条 违反本条例第十八条、第十九条第三款，未按照规定进行除害处理的，由林业有害生物防治检疫机构责令限期改正；逾期不改正的，依法确定第三方代为除治，所需费用由违法行为人承担。\n第四十二条 违反本条例第十九条第四款，承运人未按照规定承运或者收寄的，由林业有害生物防治检疫机构给予警告，责令改正，没收违法所得，并处1万元以上5万元以下罚款。\n第四十三条 违反本条例第二十条第一款，从国外引进林木种子、苗木未按照规定隔离试种即种植的，由林业有害生物防治检疫机构责令限期改正，没收违法所得；逾期不改正的，予以封存、销毁，并处2万元以上10万元以下罚款；造成外来危险性有害生物入侵的，处10万元以上30万元以下罚款。\n第四十四条 违反本条例第二十二条第二款，建设单位在施工结束后未及时回收、销毁松木或者其他可能携带疫病的木质材料的，由林业有害生物防治检疫机构责令限期回收、销毁，处1万元以上2万元以下罚款；逾期不回收、销毁的，依法确定第三方代为回收、销毁，所需费用由违法行为人承担；造成疫情扩散的，处5万元以上10万元以下罚款。\n第四十五条 违反本条例第二十九条第二款，擅自捡拾、挖掘、采伐疫木及其剩余物的，由林业有害生物防治检疫机构责令除治或者销毁，没收违法所得，可以并处1千元以上5千元以下罚款。\n第四十六条 违反本条例第二十九条第三款，未按照规定对疫木进行定点安全利用的，由林业有害生物防治检疫机构责令改正，没收违法所得；拒不改正或者造成疫木流失的，并处1万元以上5万元以下罚款。\n第四十七条 国家机关及其工作人员违反本条例规定，在林业有害生物防治检疫工作中滥用职权、玩忽职守、徇私舞弊的，由其所在单位或者上级主管机关、监察机关对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第四十八条 本条例自2017年2月1日起施行。","level":1}]},{"id":"h0186","sections":[{"name":"","text":"（2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议通过）\n第一条 为规范湖北省人民代表大会代表（以下简称代表）约见国家机关负责人的活动，支持和保障代表履行职责、充分发挥代表作用，根据有关法律法规的规定，结合本省实际，制定本办法。\n第二条 本办法所称约见，是指代表对闭会期间参加省人大常委会统一安排组织的视察、专题调研、执法检查和代表小组活动中发现的重要问题，按照规定的程序以个人或者联名的方式，向本级或者下级有关国家机关负责人当面进行询问、提出问题，被约见人予以答复或者解决的活动。\n本办法所称国家机关负责人，是指省人民政府及其所属工作部门负责人，省高级人民法院及其直属人民法院负责人，省人民检察院及其直属检察分院负责人，市县两级人民政府及其所属工作部门负责人、人民法院、人民检察院负责人，乡镇人民政府负责人。\n第三条 代表可以就下列事项提出约见：\n（一）宪法、法律、法规的实施中存在的问题；\n（二）本级及上级人民代表大会及其常务委员会决议、决定的执行中存在的问题；\n（三）全省改革、发展、稳定的重大问题；\n（四）人民群众普遍关注的热点、难点问题；\n（五）代表认为确有必要且属于代表履职范围的其他事项。\n第四条 代表不宜对下列事项提出约见：\n（一）仅涉及代表本人及其所在单位或者亲属个人利益的；\n（二）按照法律规定应当由司法机关处理，或者已经进入司法程序的；\n（三）其他不属于代表履职范围的事项。\n第五条 代表约见应当以书面形式向省人大常委会代表工作机构提出申请。约见申请应当主题明确，简明扼要，写明约见的对象和主要内容。\n第六条 省人大常委会代表工作机构根据代表约见申请的内容，及时联系协调相关机关，制定约见方案，组织安排约见；不宜安排约见的，应当在收到约见申请后七个工作日内向代表作出说明。多位代表同时对同一国家机关负责人提出约见的，可以合并安排。\n根据约见内容，约见活动可以邀请省人大相关专门委员会负责人和有关新闻媒体参加。\n第七条 代表约见活动的组织工作，可以按照分级负责的原则开展。约见对象为省级国家机关负责人的，由省人大常委会代表工作机构负责组织；约见对象为下级国家机关负责人的，由省人大常委会委托市（州）、直管市、神农架林区人大常委会负责组织；特殊原因需同时约见多级国家机关负责人的，由省人大常委会代表工作机构负责组织。\n第八条 被约见的国家机关负责人应当根据代表提出约见的内容做好相关准备，按时参加约见活动，不得拖延、推诿和回避。因特殊原因不能按时参加约见活动的，应当向组织约见活动的人大常委会提出延期举行的申请，并说明情况，但最长延期时间不得超过三十天。\n第九条 代表约见国家机关负责人由组织约见活动的人大常委会或者其相关工作机构负责人主持。被约见的国家机关负责人或者由其委托的负责人员应当积极回应代表提出的问题，认真听取代表的建议、批评和意见，能够当场答复的当场答复，不能当场答复的，应当在三个月内将处理情况书面答复提出约见的代表，同时抄送组织约见活动的人大常委会代表工作机构。\n第十条 提出约见的代表对处理情况不满意的，由组织约见活动的人大常委会代表工作机构交有关国家机关重新办理，并跟踪督办。\n第十一条 受省人大常委会委托的下级人大常委会，应当在约见活动结束后的一个月内向省人大常委会代表工作机构书面报告约见活动的有关情况。\n第十二条 本办法自2017年1月1日起施行。","level":0}]},{"id":"h0187","sections":[{"name":"","text":"（2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议通过）\n为贯彻落实党的十八届四中全会《关于全面推进依法治国若干重大问题的决定》，切实解决执行难，保障人民法院生效裁判及其他法律文书的执行，实现当事人合法权益，维护法律尊严，让人民群众在每一个司法案件中感受到公平正义，根据《中华人民共和国民事诉讼法》等法律和有关规定，特就进一步加强人民法院执行工作作如下决定：\n一、人民法院依法执行生效法律文书，是维护人民群众合法权益的基本职能，是促进社会诚信建设、实现社会公平正义的关键环节，是全面推进依法治国的重要内容，是国家治理体系及治理能力现代化的重要体现，对促进法治湖北建设、加快湖北经济社会发展具有重要作用。生效法律文书必须得到及时有效地执行。\n二、国家机关、企业事业单位、社会组织及个人应当自觉履行生效法律文书确定的义务，不得拖延、妨碍、抗拒人民法院执行。负有协助执行义务的单位、组织和个人，应当依法及时协助人民法院执行，禁止地方和部门保护。\n三、人民法院执行工作遵循依法、公正、高效、廉洁的原则。省高级人民法院统一管理、统一监督、统一指导、统一协调全省法院执行工作，上级人民法院管理、监督、指导、协调下级人民法院执行工作。\n人民法院在执行工作中必须公正执法、规范执行，严格依照法律规定强化执行措施，执行人员在执行时应当按规定着装，并出示人民法院执行公务证，依法使用警械和武器，完整记录执行过程，做到文明执行。\n人民法院要进一步推进执行权运行机制改革，健全执行实施权和执行裁判权相互监督制约机制。\n四、国家机关、企业事业单位、社会组织及个人应当自觉配合、支持人民法院执行工作，推动形成“党委领导、人大监督、政府支持、法院主办、部门配合、社会各界参与”综合治理执行难的工作格局。\n人民法院应当与检察、公安、监察、国土资源、建设、规划、房管、税务、工商、劳动保障、国有资产管理、银行、证券、保险、出入境管理、招投标管理等单位建立执行联动机制，不断拓宽协作内容和范围，形成执行工作合力。\n五、人民法院执行案件时，需要办理相关财产所有权、使用权的查询、查封、扣押、冻结、转移等手续及查询工商、税务、户籍等档案的，负有法定协助执行义务的单位和个人，应当支持、协助人民法院开展执行工作，不得推诿、拖延、阻碍执行。银行、证券、保险等金融机构，应当建立完善系统内统一查询、冻结、扣划功能，协助人民法院的执行工作。协助执行义务人违反法律、法规的规定，拒不履行协助义务的，人民法院除责令其履行协助义务外可依法采取强制措施。\n六、公安机关、检察机关要积极协助人民法院执行工作，对拒不执行生效判决、裁定以及其他妨碍执行构成犯罪的行为，应当及时依法侦查、提起公诉和审判，建立常态化的打击妨碍执行违法犯罪行为工作机制。公安机关应当根据人民法院协作要求，协助查找被执行人下落，对规避、妨碍、抗拒执行的被执行人，根据情节轻重，依法采取查扣车辆、限制出境、临时控制、网上追逃等强制措施，并及时处置暴力抗拒执行事件。人民法院决定拘留、逮捕的被执行人及协助执行义务人，被执行人及协助执行义务人所在地公安机关应当及时收押、负责看管。检察机关对于涉嫌犯罪的暴力抗拒执行、不协助执行、干预执行等行为，应当依法及时履行批捕、起诉等职能。\n七、被执行人有履行能力而拒不执行人民法院发生法律效力的判决、裁定及其他生效法律文书的，协助执行单位和个人不依法协助、配合人民法院执行的，人民法院应当通报其上级或行业主管部门及所在单位，并可以向监察机关或者有关部门提出对责任人或者直接责任人予以纪律处分的司法建议；同时根据情节轻重，依法予以罚款、拘留；构成犯罪的，依法追究刑事责任。\n国家机关及其工作人员拒不履行执行义务或滥用权力干预案件执行的，人民法院可以向有关部门提出司法建议，接到人民法院司法建议的有关部门应当依法及时处理。\n各级领导干部应当带头遵守宪法法律，维护司法权威，支持人民法院执行工作。对于领导干部干预司法活动、插手具体案件处理的，必须严格执行情况记录、通报和责任追究规定。\n八、人民法院应当依法公开执行裁判文书及其他执行案件信息，保障执行案件当事人和社会公众的知情权、参与权、监督权。有关单位应当在法定职责范围内，不断完善公民、法人、其他组织的财产及身份信息实名登记和信用采集制度，健全信息管理体制和通报机制，并与人民法院实现相关信息的互联互通和资源共享。\n九、执行联动单位应当积极配合人民法院进一步完善被执行人财产查控机制，建立健全不动产、存款、金融理财产品、证券、保险、股权、车辆等主要财产形式的网络化、自动化执行查控体系，进一步拓展财产查控范围，实现对被执行人财产查控的全覆盖和网络查询、冻结、扣划等功能一体化。\n十、负有信用惩戒职能的国家机关和其他组织，要实现与全国信用信息共享平台联合惩戒系统的网络对接，将人民法院发布的失信被执行人名单信息嵌入本单位管理、审批工作系统中，实现对失信被执行人名单信息的自动比对、自动监督，并在职能范围内对失信被执行人在从事特定行业或项目限制、政府支持或补贴限制、任职资格限制、准入资格限制、荣誉和授信限制、特殊市场交易限制、限制高消费及有关消费等方面实施信用监督、警示和惩戒。\n十一、各级财政部门应当将司法救助资金列入预算，加强执行救助和社会救助的衔接配合，保障执行救助工作需要，促进被执行人确无履行能力的“执行不能”案件得到妥善解决。\n十二、新闻宣传媒体要加大对人民法院执行工作的宣传力度，大力弘扬社会主义核心价值观和法治精神，教育社会公众诚实守信，增强法律意识和风险防范能力，理性认识执行难，为解决执行难营造良好舆论氛围。\n十三、各级人民法院要加强执行队伍建设，充实执行力量，足额配备执行工作人员，不断强化执行队伍思想政治建设、纪律作风教育、素质能力培训，建设一支信念坚定、执法为民、敢于担当、清正廉洁的执行队伍。\n人民法院执行人员在执行中存在消极执行、滥用职权、徇私枉法等行为，侵害当事人合法权益的，根据情节轻重，给予相应纪律处分；构成犯罪的，依法追究刑事责任。\n十四、各级人民政府要积极支持人民法院执行工作，把切实解决执行难作为法治湖北建设和平安湖北建设的重要内容，将执行联动单位履行职责情况、党政机关依法履行生效法律文书及支持人民法院执行工作情况纳入法治湖北建设绩效考核内容，认真落实社会治安综合治理目标责任制，充分发挥社会治安综合治理部门及基层组织的作用。\n十五、各级人民代表大会常务委员会应当加强对同级人民法院执行工作的监督，通过定期听取和审议人民法院执行工作专项工作报告、开展执法检查或者作出决议决定等方式，督促、支持人民法院依法开展执行工作。\n各级人民法院应当主动接受同级人民代表大会及其常委会的监督，依法接受人民检察院的法律监督，自觉接受新闻媒体、社会各界和人民群众的监督，完善内部监督机制，确保执行行为高效廉洁规范运行。\n十六、本决定自公布之日起施行。1996年11月22日湖北省第八届人民代表大会常务委员会第二十三次会议通过的《湖北省人民代表大会常务委员会关于进一步加强人民法院执行工作的决定》同时废止。","level":0}]},{"id":"h0188","sections":[{"name":"","text":"（2017年3月30日湖北省第十二届人民代表大会\n常务委员会第二十七次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了规范社会信用信息管理，促进社会信用体系建设，营造诚实守信的社会环境，保障社会信用信息安全和信用主体合法权益，实现社会信用信息共享，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内社会信用信息的归集、披露、应用及其管理活动，适用本条例。\n第三条 本条例所称社会信用信息,是指可用于识别自然人、法人和其他组织（以下简称信用主体）信用状况的数据和资料，包括公共信用信息和市场信用信息。\n公共信用信息是指国家机关、法律法规授权的具有管理公共事务职能的组织以及群团组织等（以下简称公共信用信息提供单位），在依法履职、提供服务过程中产生或者获取的，可用于识别信用主体信用状况的数据和资料。\n市场信用信息是指信用服务机构、行业协会、其他企业事业单位和组织，在生产经营和提供服务过程中产生或者获取的，可用于识别信用主体信用状况的数据和资料。\n信用服务机构是指依法设立，从事信用评级、信用管理咨询、信用风险控制等相关经营性活动的中介服务机构。\n第四条 社会信用信息管理应当按照社会信用体系建设和改革发展的需要，遵循合法、安全、及时、准确的原则，不得危害国家安全、泄露国家秘密，不得侵犯商业秘密和个人隐私。\n第五条 县级以上人民政府应当成立社会信用体系建设领导小组，将社会信用体系建设纳入国民经济和社会发展规划，编制社会信用体系建设规划或者实施方案，明确工作机构和专门人员，保障工作经费，并将社会信用信息管理工作纳入目标责任制考核体系。\n县级以上人民政府发展改革部门负责本行政区域内社会信用信息综合协调和监督管理工作。\n社会信用体系建设领导小组成员单位以及其他有关部门和组织按照各自职责，做好相关领域社会信用信息归集、披露、应用及其管理工作。\n征信业监督管理机构依照法律、行政法规的规定，做好金融信用信息和征信机构的监督管理工作。\n第六条 省人民政府应当建立全省统一的社会信用信息服务平台，通过汇集系统与有关部门、组织和地方建立的信用信息服务系统互联互通，实现社会信用信息跨部门、跨领域、跨地区共享使用。\n省人民政府设立的信用信息中心（以下简称“省信用信息中心”）具体负责省社会信用信息服务平台的建设、运行和维护工作，归集和管理社会信用信息，提供信息公开、查询、共享和应用等相关服务。\n省社会信用体系建设领导小组成员单位以及其他有关部门和组织负责本系统信用信息服务系统的建设、运行和维护，做好与省社会信用信息服务平台的数据交换和信息共享工作。\n第七条 国家机关及其工作人员应当依法履行职责，提高守法履约的意识和水平，在社会信用体系建设中发挥示范表率作用。\n信用服务机构、行业协会、其他企业事业单位和组织应当遵守行业信用规约和职业道德准则，加强自身信用管理，提高公信力。\n鼓励社会公众守信自律，提高诚信意识，参与诚信教育和信用监督活动，共同推进社会信用体系建设。\n第八条 广播、电视、报刊、网络等媒体应当通过新闻报道、专题专栏、公益广告等形式，宣传和普及社会信用知识，弘扬诚信文化，营造诚信的舆论环境和社会氛围。","level":1},{"name":"第二章 信息归集","text":"第九条 公共信用信息归集实行目录管理，公共信用信息的项目内容、提供单位、数据格式、使用权限、归集程序、归集路径、归集时限、披露方式等要素由公共信用信息目录规定。\n公共信用信息目录由省人民政府发展改革部门会同有关部门，根据国家有关规定和标准组织编制并适时调整，经征求省社会信用体系建设领导小组成员单位意见后，报省人民政府批准并向社会公布。\n拟纳入目录管理的项目内容可能减损信用主体权利或者增加信用主体义务、社会影响较大的，应当组织专家进行评估，并向社会公开征求意见。\n第十条 信用主体的下列信息应当纳入公共信用信息目录：\n（一）公共管理和服务中反映信用主体基本情况的登记类信息；\n（二）行政许可、行政处罚、行政强制、行政确认、行政检查、行政征收、行政奖励、行政给付等行政行为中反映信用主体信用状况的信息；\n（三）拒不履行生效法律文书的信息；\n（四）群团组织在履行职责过程中产生或者掌握的信用主体受表彰奖励以及参加社会公益、志愿服务等信息；\n（五）其他依法应当纳入目录管理的信息。\n第十一条 公共信用信息提供单位应当按照公共信用信息目录的规定，及时、准确地向省信用信息中心报送信息。\n第十二条 省人民政府发展改革部门应当会同有关部门根据国家有关规定和标准，制定和完善信用主体编码、信用信息技术规范。\n向省信用信息中心提供的公共信用信息，应当符合信用信息技术规范，并载明信用主体的姓名或者法定名称及其统一社会信用代码。\n第十三条 信用服务机构、行业协会、其他企业事业单位和组织应当按照真实、客观、全面的原则,依法采集市场信用信息。\n第十四条 鼓励企业事业单位记录自身生产经营、提供服务过程中产生的信用信息；鼓励行业协会根据管理和服务需要记录会员的信用信息，建立会员信用档案和行业信用信息数据库。\n鼓励信用主体以合法形式向省信用信息中心、信用服务机构、行业协会、其他企业事业单位和组织提供自身信用信息，并对信息的真实性、准确性负责。\n第十五条 信用信息提供单位应当对其提供的信用信息的真实性、准确性负责，不得篡改、虚构信用信息。\n省信用信息中心依法归集信用服务机构、行业协会、其他企业事业单位和组织采集的信用信息，应当按照规定或者约定对信息进行审核。\n第十六条 省信用信息中心应当对收到的社会信用信息在三日内完成比对、录入工作；不符合要求的，反馈给信用信息提供单位复核处理后重新报送。\n第十七条 任何单位和个人不得违法归集社会信用信息。\n信用服务机构、行业协会、其他企业事业单位和组织归集市场信用信息属于自然人信息的，应当经本人同意并约定用途，未经本人同意不得归集。法律、法规另有规定的除外。\n信用服务机构、行业协会、其他企业事业单位和组织不得归集自然人宗教信仰、基因、指纹、血型、疾病和病史等信息。\n信用服务机构、行业协会、其他企业事业单位和组织不得归集法律、法规禁止归集的法人和其他组织的信用信息。","level":1},{"name":"第三章 信息披露","text":"第十八条 公共信用信息通过公开公示、授权查询、政务共享等方式披露。\n涉及自然人的公共信用信息通过本人实名认证查询、授权查询、政务共享的方式披露，国家另有规定的除外。\n涉及法人和其他组织的公共信用信息的披露方式，由公共信用信息目录确定。\n第十九条 公共信用信息以公开为原则，法律、法规另有规定的除外。\n依法应当公开的公共信用信息，通过省社会信用信息服务平台和公共信用信息提供单位对外发布信息的平台向社会披露。\n涉及商业秘密、个人隐私的公共信用信息，经信用主体书面同意公开或者国家机关认为不公开可能对公共利益造成重大影响的，可以依法公开。\n依法不能公开的公共信用信息，经信用主体的书面授权可以查询，并按照约定的用途使用；未经其同意，不得将该信息向第三方提供。\n第二十条 信用主体享有查询自身信用信息的权利。\n省人民政府发展改革部门应当加强与有关部门合作，推动设立社会信用信息综合服务窗口，为社会提供查询服务。\n省信用信息中心应当制定并公布公共信用信息查询服务规范，通过平台网站、移动终端、服务窗口等途径向社会提供便捷的查询服务，查询情况应当记载并自查询之日起保存三年。\n第二十一条 县级以上人民政府及有关部门和组织根据履职需要，依法可以共享省信用信息中心归集的依法不能公开的公共信用信息。\n信用服务机构、行业协会、其他企业事业单位和组织可以根据与省人民政府发展改革部门签订的协议，共享省信用信息中心归集的公共信用信息；共享依法不能公开的公共信用信息，应当取得信用主体的书面授权。\n省社会信用信息服务平台与国家信用信息平台以及其他省、自治区、直辖市信用信息平台的信息共享和数据交换，依据有关规定和协议执行。\n第二十二条 省人民政府应当建立信用信息共享机制，推动省社会信用信息服务平台与金融信用信息基础数据库以及其他各类信用信息服务系统的信息共享与数据交换。\n金融信用信息基础数据库信用信息的披露和查询按照法律、行政法规的规定执行。","level":1},{"name":"第四章 信息应用","text":"第二十三条 省人民政府发展改革部门应当组织有关部门制定公共信用信息评价规范，报省人民政府批准后向社会公布。国家已制定公共信用信息评价规范的，从其规定。\n公共信用信息提供单位应当根据信用评价规范，对其履职过程中产生或者掌握的信用信息进行记录和评价，并将评价后的信息归集到省信用信息中心。\n公共信用信息提供单位向归集单位报送信用主体失信信用信息前，应当书面告知信用主体。法律、法规另有规定的除外。\n信用服务机构、行业协会、其他企业事业单位和组织可以依法对其获取的信用信息进行记录和评价，为社会提供专业化的信用服务。\n第二十四条 县级以上人民政府及有关部门和组织应当根据履职需要，在下列工作中查询信用信息、使用信用报告，作为行政管理、公共服务以及人事管理和监督工作的参考依据：\n（一）实施行政许可、行政处罚、行政检查；\n（二）财政支持、政府采购、政府投资项目招标、国有土地出让、科研管理等；\n（三）国家工作人员招录、任用和管理监督；\n（四）表彰奖励；\n（五）其他管理工作。\n鼓励自然人、法人和其他组织在开展市场交易、企业治理、行业管理、融资信贷、社会公益等活动中，依法查询信用信息、使用信用报告。\n第二十五条 县级以上人民政府应当支持和规范信用服务机构发展，制定促进信用服务产业发展的政策和措施，鼓励社会资本进入信用服务市场。\n鼓励和支持信用服务机构开发和创新信用产品，扩大信用服务领域和范围，参与国际合作，推动信用调查、信用评估、信用担保、信用保险等信用产品和服务在行政管理、公共服务、市场交易、生产生活中的应用。\n第二十六条 省人民政府应当建立跨部门、跨领域、跨地区的守信联合激励和失信联合惩戒机制，根据法律、法规和国家有关规定确定联合激励和惩戒事项，制定推荐性和强制性措施清单，并向社会公布。\n未经依法确认的公共事业及物业管理欠费信息不得作为实施联合惩戒的依据。\n第二十七条 对守信信用主体依法可以采取下列激励措施：\n（一）在行政管理和公共服务过程中给予支持和便利；\n（二）在财政支持、政府采购、政府投资项目招标、国有土地出让、融资信贷、媒体推介、荣誉评选等活动中，列为优先选择对象；\n（三）国家规定的其他激励措施。\n第二十八条 对失信信用主体在国家规定的期限内依法可以采取下列惩戒措施：\n（一）在行政监管中列为重点核查对象；\n（二）取消已经享受的行政便利措施；\n（三）限制申请财政资金或者政策支持；\n（四）国家规定的其他惩戒措施。\n第二十九条 国家机关可以根据履职需要建立严重失信名单，规范名单纳入程序和条件，并向社会公布。\n信用主体有下列行为之一的，应当纳入严重失信名单：\n（一）严重损害公众身体健康和生命安全的行为；\n（二）严重破坏市场公平竞争秩序和社会正常秩序的行为；\n（三）有履行能力但拒不履行、逃避履行生效法律文书确定的义务的行为；\n（四）拒不履行国防义务，危害国防利益的行为；\n（五）国家规定的其他严重失信行为。\n第三十条 对纳入严重失信名单的信用主体，依法可以采取下列特别惩戒措施：\n（一）限制从事特定行业或者项目；\n（二）限制任职资格；\n（三）限制从事特殊市场交易；\n（四）限制授予荣誉和融资信贷；\n（五）限制高消费以及有关消费；\n（六）限制出境；\n（七）法律、行政法规规定的其他特别惩戒措施。\n第三十一条 国家机关决定对失信信用主体采取惩戒措施的，应当告知实施理由、依据和救济途径以及解除惩戒措施的条件。","level":1},{"name":"第五章 信息安全与权益保障","text":"第三十二条 省人民政府发展改革部门应当会同有关部门制定信用信息安全保护制度，建立社会信用信息异议处理和信用修复机制，保障信用主体合法权益。\n第三十三条 省信用信息中心和信用信息提供单位应当建立健全社会信用信息安全管理和应急处理制度，采取安全保密措施，保障社会信用信息归集、查询、披露和应用全过程的安全。\n省社会信用信息服务平台和其他各类信用信息服务系统，应当符合国家计算机信息系统安全等级保护要求，保障社会信用信息系统正常运行和信用信息安全。\n第三十四条 信用主体有权知晓自身信用信息的采集、使用等情况，以及本人信用报告载明的信息来源和变动理由。\n信用服务机构、行业协会、其他企业事业单位和组织不得将个人信用信息采集与其他服务捆绑，强迫或者变相强迫信用主体同意。\n第三十五条 信用信息提供单位发现其向省信用信息中心提供的信息存在错误、遗漏的，应当及时更正，并将更正后的信息及时报送省信用信息中心。\n信用主体认为省信用信息中心记载的社会信用信息存在错误、遗漏或者侵犯其商业秘密、个人隐私等合法权益的，有权向省信用信息中心提出书面异议申请，并说明理由。\n省信用信息中心收到异议申请后，对属于自身原因造成的，应当自收到异议申请三日内依法作出处理。对属于信用信息提供单位更正范围的，应当自收到异议申请二日内转交信用信息提供单位办理；信用信息提供单位应当在七日内依法作出处理，并将结果报送省信用信息中心，省信用信息中心在二日内将处理结果告知异议申请人。\n信用信息提供单位未在规定期限内报送处理结果的，省信用信息中心应当中止披露、查询该信息。\n省信用信息中心在异议申请处理期间，应当对异议信息进行标注。\n第三十六条 信用主体依法纠正失信行为、消除不利影响，可以向信用信息提供单位提出信用修复的申请。\n经审查符合信用修复条件的，信用信息提供单位应当在三日内作出信用修复决定并报送省信用信息中心。省信用信息中心收到信用修复决定后，应当及时删除原始失信信用信息并将修复记录归档管理。国家另有规定的除外。\n信用主体的信用修复后，按照规定不再作为联合惩戒对象。\n第三十七条 信用主体向省信用信息中心申请删除其表彰奖励、志愿服务和慈善捐赠等信息的，省信用信息中心应当及时删除并归档管理。\n第三十八条 从事社会信用信息管理和服务的机构及其人员，不得非法提供、披露和使用信用信息，不得篡改、虚构、泄露、窃取和买卖信用信息。","level":1},{"name":"第六章 法律责任","text":"第三十九条 违反本条例，法律、法规有规定的，从其规定。\n第四十条 国家机关及其工作人员违反本条例规定，有下列行为之一的，由发展改革部门或者法律、法规规定的部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任：\n（一）未按照规定编制公共信用信息目录的；\n（二）未履行报送、归集和披露信用信息职责的；\n（三）未根据履职需要查询信用信息、使用信用报告的；\n（四）篡改、虚构、泄露、窃取和买卖信用信息的；\n（五）未履行异议信息处理、信用修复职责的；\n（六）违法执行守信联合激励和失信联合惩戒措施的；\n（七）未建立社会信用信息安全管理和应急处理制度，未履行保障信息安全职责的；\n（八）其他未按照本条例履行职责的行为。\n第四十一条 信用服务机构、行业协会、其他企业事业单位和组织及其工作人员违反本条例规定，有下列行为之一的，由发展改革部门或者法律、法规规定的部门责令限期改正，没收违法所得，对单位并处5万元以上20万元以下罚款，对个人并处1万元以上5万元以下罚款；逾期不改正的，责令停业整顿、依法吊销有关许可证件或者营业执照；构成犯罪的，依法追究刑事责任：\n（一）归集禁止归集的自然人、法人和其他组织的信用信息或者未经同意违法归集自然人信用信息的；\n（二）将个人信用信息采集与其他服务捆绑，强迫或者变相强迫信用主体同意的；\n（三）未履行保密义务以及超出法定或者约定范围披露、应用信用信息的；\n（四）篡改、虚构、泄露、窃取和买卖信用信息的。\n第四十二条 违反本条例规定，在信用信息采集、归集、使用等过程中损害信用主体合法权益的，依法承担相应的民事责任。","level":1},{"name":"第七章 附则","text":"第四十三条 本条例所称征信业监督管理机构，是指中国人民银行及其派出机构。\n第四十四条 本条例自2017年7月1日起施行。","level":1}]},{"id":"h0189","sections":[{"name":"","text":"（2018年5月31日湖北省第十三届人民代表大会常务委员会第三次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了有效保护和合理利用气候资源，满足公众对优美生态环境的需要，促进经济高质量发展，根据《中华人民共和国气象法》《中华人民共和国可再生能源法》《气象灾害防御条例》等法律、行政法规，结合本省实际，制定本条例。\n第二条 在本省行政区域内从事气候资源保护和利用活动，适用本条例。\n本条例所称气候资源，是指可以被人类生产和生活利用的太阳辐射、热量、风、云水、大气成分等自然物质和能量。\n第三条 气候资源的保护和利用，应当遵循自然生态规律，坚持统筹规划、保护优先、合理利用、趋利避害的原则，预防、控制和减少人类活动对生态环境的破坏。\n第四条 县级以上人民政府应当加强对气候资源保护和利用工作的领导和组织协调，将其纳入国民经济和社会发展规划以及相关生态文明建设规划，制定支持气候资源保护和利用的政策、措施，并将所需经费纳入财政预算。\n县级以上人民政府应当将气候资源保护和利用情况作为国有自然资源资产管理的内容，向本级人民代表大会常务委员会报告。\n第五条 县级以上气象主管机构是本行政区域内气候资源保护和利用的主管部门，负责组织开展气候资源探测、调查、评估、区划、气候可行性论证等工作以及气候资源保护和利用的服务、指导和监督管理，参与城乡规划编制工作。\n县级以上人民政府有关部门按照职责，共同做好气候资源保护和利用相关工作。\n第六条 县级以上人民政府及有关部门应当鼓励和支持气候资源保护和利用的科学研究、应用示范和产业化发展，促进技术进步和科研成果应用。\n第七条 各级人民政府及有关部门和媒体应当加强宣传教育，普及气候资源保护和利用基本知识和法律法规，增强公众的气候资源保护和利用意识。\n第八条 鼓励公民、法人和其他组织参与气候资源保护和利用工作，合理利用气候资源，保护生态环境。\n对在气候资源保护和利用工作中做出突出贡献的单位和个人，按照有关规定给予表彰和奖励。","level":1},{"name":"第二章 气候资源探测、区划和规划","text":"第九条 县级以上人民政府应当建立气候资源的探测和调查制度，加强对气候资源探测基础设施和站网的规划、建设，保护气候资源探测环境。\n第十条 县级以上气象主管机构应当组织开展气候资源探测。\n省气象主管机构应当建立气候资源探测公共信息平台和共享目录，实现信息共享共用；健全气候资源档案管理制度，定期向社会发布气候资源状况公报。\n第十一条 公民、法人和其他组织获取未公开的气候资源探测资料，应当按照国家有关规定向县级以上气象主管机构提出申请。\n县级以上气象主管机构应当自收到申请之日起七日内向申请人免费提供；涉及保密内容不予提供的，应当在三日内告知申请人。\n第十二条 依法从事气候资源探测的公民、法人和其他组织，应当按照国家有关规定向省气象主管机构汇交所获得的气候资源探测资料。\n第十三条 气候资源探测及其资料的收集、处理、存储、传输、发布等，应当符合国家有关标准、技术规范和保密规定。\n第十四条 省气象主管机构应当对本省行政区域内气候资源分布、变化及利用情况开展综合调查，对气候承载力、气候资源的有效性和可利用性进行评估。\n第十五条 省气象主管机构应当会同其他有关部门根据气候资源的分布情况和评估结果，按照国家有关标准和技术规范，组织编制综合气候资源区划以及太阳能、风能等单项气候资源区划和农业、林业等专业气候资源区划，为政府及有关部门提供决策服务。\n气候资源区划应当包括下列内容：\n（一）编制背景及依据；\n（二）气候资源区划方法；\n（三）气候资源区划指标；\n（四）气候资源分布状况；\n（五）气候资源区划结果；\n（六）其他应当列入区划的内容。\n第十六条 县级以上人民政府应当根据国民经济和社会发展规划以及本省气候资源区划，组织编制和实施气候资源保护和利用规划，并与有关区域规划、专项规划和产业规划相衔接。气候资源保护和利用规划应当每五年修编一次。\n气候资源保护和利用规划应当包括下列内容：\n（一）编制的依据、原则和目标；\n（二）气候资源及其承载力的现状、特点及评估；\n（三）气候资源保护的重点和利用的方向；\n（四）气候资源保护和利用的措施；\n（五）气候资源保护和利用项目建设；\n（六）气候资源保护和利用的宣传教育；\n（七）其他应当列入规划的内容。\n编制气候资源保护和利用规划应当进行科学性、可行性论证，征求有关单位、专家和公众的意见。","level":1},{"name":"第三章 气候资源的保护","text":"第十七条 省人民政府应当根据气候资源区划、气候资源保护和利用规划以及区域性气候资源的保护和利用重点，在气候资源丰富区域或者气候敏感区域内，划定气候资源保护区域。\n气候资源保护区域内不得建设破坏气候资源的项目。\n第十八条 县级以上人民政府应当采取生态修复、资源保护、城乡绿化等生态环境保护措施，加强森林、江河、湖泊、湿地、草地等生态环境的保护与修复，优化气候环境。\n第十九条 县级以上人民政府应当根据当地气候资源承载能力以及保护和利用规划，采取措施调整、优化产业发展区域布局，科学规划城乡建设和开发项目，建立落后产能退出机制，改善能源结构，控制温室气体排放，应对气候变化。\n第二十条 城市规划和建设应当按照国家规定和相关标准、技术规范，合理设置、调整通风廊道，保障空间环境空气流通、自净能力，避免或者减轻大气污染物的滞留。\n新建、改建、扩建建（构）筑物应当采取喷淋、覆盖、围挡、绿化、封闭施工等防尘措施，减少大气污染；采取防护措施，避免或者减轻热岛效应、狭管效应、光污染等不利气候条件影响。\n第二十一条 省气象主管机构应当建立气候资源变化分析与评估制度，定期分析本省气候资源变化和分布状况，组织开展气候变化对水资源、生态环境、气候敏感地区和相关行业的影响评估以及气候资源变化趋势分析，为改善气候环境、保护气候资源提供决策依据。\n第二十二条 开发利用太阳能、风能等气候资源，其范围和强度应当严守生态保护红线、符合环境保护要求；开发利用单位应当采取措施避免或者减少对生态环境的影响。\n第二十三条 与气候条件相关的城乡规划、国家重点建设工程、重大区域性经济开发项目和大型太阳能、风能等气候资源利用项目应当依法进行气候可行性论证，气候可行性论证报告应当作为项目审查的内容。\n应当进行气候可行性论证的项目实行目录管理，目录由省人民政府发展改革部门会同省气象主管机构按照国家和省有关规定编制。\n应当进行气候可行性论证的项目，未进行论证的，项目建设单位不得开工建设。\n第二十四条 气候可行性论证报告应当包括下列内容：\n（一）规划或者建设项目概况和技术要求；\n（二）基础资料来源及其代表性、可靠性说明，现场探测所取得的资料及探测仪器、探测方法、探测环境和探测数据有效性的说明；\n（三）气候可行性论证所依据的标准、规范和方法；\n（四）规划或者建设项目所在地的气候背景分析；\n（五）气候适宜性、风险性以及可能对局地气候产生影响的评估；\n（六）预防或者减轻气候影响的对策和建议；\n（七）论证结论和适用性说明；\n（八）其他有关内容。\n第二十五条 气候可行性论证报告应当客观、真实、完整。\n气候可行性论证机构和人员从事气候可行性论证服务，应当依法履行职责，不得伪造气象资料或者其他原始资料，不得出具虚假论证报告。\n气候可行性论证机构和项目负责人对气候可行性论证报告的内容和结论终身负责。\n第二十六条 经气候可行性论证的规划和建设项目实施过程中和完成后，规划单位和项目建设单位应当组织开展气候环境跟踪监测和气候影响后评估，并向县级以上气象主管机构报送结果。\n已经实施的建设项目对气候资源造成重大不利影响的，县级以上气象主管机构应当向项目所在地人民政府提出整改建议，项目所在地人民政府应当责成有关部门和建设单位采取相应补救措施。","level":1},{"name":"第四章 气候资源的利用","text":"第二十七条 县级以上人民政府应当根据气候资源区划、气候资源保护和利用规划，因地制宜选择气候资源利用项目，将气候资源利用统筹纳入能源供应计划，为项目的立项、用地、基础设施建设提供支持，促进气候资源的科学利用和合理利用。\n县级以上气象主管机构应当向本级人民政府提出推广应用气候资源区划成果和利用气候资源的建议；为气候资源利用项目的勘察选址、建设运行提供气象探测、评估和预报等服务；推行气候资源认证和标志制度，设立宜居、宜业、宜游等地域气候性标志。\n第二十八条 县级以上人民政府及有关部门应当充分利用太阳能资源区划成果，科学布局大中型太阳能开发利用项目，鼓励引导单位和个人安装使用太阳能热水系统、太阳能供热采暖和制冷系统、太阳能光伏发电系统等太阳能利用系统，提高太阳能利用率。\n第二十九条 县级以上人民政府及有关部门应当统筹考虑当地风能可利用程度和风能气候资源区划，科学规划和合理布局大型风能利用项目，促进风能资源规范有序利用，鼓励引导风电利用企业开展风电功率预报，提高风电利用效率。\n风力发电项目建设单位、施工单位应当防止工程实施和风能利用对山体、植被、道路、水土、野生动植物以及居民生产生活等方面的不利影响，做好项目建成后的修复、恢复等工作。\n第三十条 县级以上人民政府应当加强人工影响天气作业机构、站点基础设施和业务能力建设，组织有关部门适时开展以抗旱、防雹、储水、改善生态环境和空气质量等为目的的人工影响天气作业，科学合理利用空中云水资源，提高利用和调控能力。\n鄂东北、鄂西北、江汉平原北部等水资源短缺地区和其他季节性干旱地区的县级以上人民政府，应当组织协调云水资源利用工作，增强抗旱、蓄水、森林防火和生态修复能力。\n县级以上人民政府应当根据当地云水气候资源特点，推进屋顶绿化、透水铺装、雨水收集利用设施建设，实现雨污分流，增强城市下垫面雨水涵养能力，减缓城镇水涝灾害，提高城镇雨水资源利用的生态效益。\n第三十一条 县级以上人民政府及有关部门应当根据农业气候资源区划，合理调整农业布局，引导农民和农业生产经营组织合理利用当地农业气候资源，改善种养结构，提高农业生产效率和效益。\n第三十二条 县级以上人民政府应当结合本地实际，鼓励和支持市场主体合理利用雨雪景观、云雾景观、雨雾凇景观、物候景观以及避暑气候地等旅游、休憩气候资源，促进旅游休闲产业发展。\n第三十三条 气候资源利用活动应当遵守国家和省制定的标准、规范和规程，不得破坏生态环境、损害公共利益和他人合法权益。\n县级以上气象主管机构及有关部门应当对可能影响气候变化或者侵害公众气候环境权益的气候资源利用项目组织听证，并公示听证结果。","level":1},{"name":"第五章 法律责任","text":"第三十四条 违反本条例，法律法规有规定的，从其规定。\n第三十五条 国家机关及其工作人员有下列行为之一的，依法对直接负责的主管人员和其他直接责任人员给予处分；构成犯罪的，依法追究刑事责任：\n（一）未按照规定进行气候资源综合调查评估、编制气候资源区划和气候资源保护和利用规划的；\n（二）在气候资源保护区域内批准建设破坏气候资源的项目的；\n（三）未按照规定将气候可行性论证报告作为项目审查内容的；\n（四）未按照规定对可能影响气候变化或者侵害公众气候环境权益的气候资源利用项目组织听证的；\n（五）其他滥用职权、玩忽职守、徇私舞弊的行为。\n第三十六条 违反本条例第二十三条第三款规定，应当进行气候可行性论证而未进行论证的项目，项目建设单位擅自开工建设的，由县级以上气象主管机构责令改正，给予警告，并处1万元以上5万元以下罚款。\n第三十七条 违反本条例第二十五条第二款规定，气候可行性论证机构在气候可行性论证工作中不依法履行职责或者弄虚作假，致使气候可行性论证报告失实的，由县级以上气象主管机构责令改正，给予警告，并处所收费用一倍以上三倍以下罚款。","level":1},{"name":"第六章 附则","text":"第三十八条 本条例自2018年8月1日起施行。","level":1}]},{"id":"h0190","sections":[{"name":"","text":"（2018年5月31日湖北省第十三届人民代表大会常务委员会第三次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了加强广播电视管理，保障广播电视公共服务，促进广播电视事业繁荣发展，满足人民群众精神文化需求，根据《中华人民共和国公共文化服务保障法》《广播电视管理条例》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内广播电视播出机构的设立，广播电视传输覆盖网的建设、使用和保护，节目的制作、播放和传送等活动及其监督管理。\n本条例所称广播电视播出机构，包括广播电台、电视台、广播电视台等。\n本条例所称广播电视传输覆盖网，包括从事广播电视节目传输业务的无线台站、卫星上行站、卫星收转站、监测台(站)、有线广播电视传输覆盖网等。\n第三条 广播电视事业应当坚持以人民为中心，弘扬社会主义核心价值观，丰富人民群众精神文化生活。\n第四条 县级以上人民政府应当将广播电视事业纳入国民经济和社会发展规划，建立工作协调机制，研究解决广播电视工作中的重大问题，推动广播电视事业发展。\n第五条 县级以上人民政府广播电视行政部门负责本行政区域内广播电视管理和相关公共服务工作。其他有关部门按照各自职责做好相关工作。\n乡镇人民政府、街道办事处协助做好广播电视设施保护和相关公共服务工作。\n第六条 县级以上人民政府广播电视行政部门应当加强对广播电视相关工作的监督管理，建立健全广播电视监督举报和服务投诉制度，及时处理公众的举报和投诉。\n第七条 县级以上人民政府应当鼓励和支持广播电视行业研发、应用网络信息技术，建设智能化、集约化的广播电视技术平台，整合各类传播形式和节目资源，创新节目内容、业务形态和服务模式，实现平台、节目、人才、技术等要素共享融通，推动广播电视媒体与新兴媒体融合发展，提高广播电视服务质量。\n第八条 广播电视行业协会以及其他有关行业协会、社会团体在广播电视行政部门指导下，按照其章程开展行业服务、实行自律管理。\n广播电视从业人员应当遵守法律法规，恪守职业道德。\n第九条 对在发展广播电视事业中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。","level":1},{"name":"第二章 广播电视播出机构和传输覆盖网","text":"第十条 设立广播电视播出机构，应当符合国家有关规定，依法取得广播电视播出机构许可证。\n严禁未经批准擅自设立广播电视播出机构。\n第十一条 广播电视播出机构应当按照广播电视播出机构许可证载明的事项制作、播放节目。确需变更的，应当经省人民政府广播电视行政部门审核同意后，报国务院广播电视行政部门批准。\n广播电视播出机构不得出租、转让播出时段。\n第十二条 设立广播电视站，应当符合国家有关规定，经所在地县级以上人民政府广播电视行政部门审核后，报省人民政府广播电视行政部门审批。严禁未经批准擅自设立广播电视站。\n广播电视站不得出租、转让、承包给其他单位或者个人。\n第十三条 县级以上人民政府广播电视行政部门会同发展改革、建设等部门编制广播电视传输覆盖网专项规划，加强广播电视传输覆盖网建设，加快广播电视传输覆盖网与电信网、互联网的融合发展，推动信息网络基础设施互联互通和资源共享。\n第十四条 全省设立统一的有线广播电视传输覆盖网，实行统一规划、建设、运营和管理。\n已建成的有线广播电视站、有线广播电视分配网应当按照规划与全省统一的有线广播电视传输覆盖网联网。\n城市有线广播电视传输覆盖网地下管线工程应当符合城市地下管线综合规划，统一纳入地下综合管廊管理。\n第十五条 新建、改建、扩建住宅区、公共设施及其他建筑物，其建设主体应当按照国家、省有关规定规划和建设广播电视传输覆盖配套设施，并与主体工程同时设计、同时施工、同时验收。\n已建住宅区、公共设施及其他建筑物，没有广播电视传输覆盖配套设施，需要接入广播电视信号的，应当按照规定标准建设广播电视传输覆盖配套设施。\n第十六条 工程建设应当避开广播电视设施，并符合国家规定的保护要求。\n工程建设暂时影响广播电视设施正常使用的，建设主体应当在施工前十日告知广播电视设施管理单位，并协商制定解决方案。\n第十七条 重大工程项目确实无法避开广播电视设施，需要迁建广播电视设施的，政府相关部门应当在批准前征得广播电视行政部门同意。\n迁建广播电视设施应当按照先建设后拆除的原则进行，所需费用由造成广播电视设施迁建的单位承担。\n第十八条 未经许可，任何单位和个人不得安装、使用卫星电视广播地面接收设施。\n在有线电视网络未通达的地区，个人可以申请安装、使用卫星电视广播地面接收设施，接收境内广播电视节目。\n第十九条 任何单位和个人不得冲击广播电视播出机构，不得侵占、哄抢、损坏广播电视设施；不得侵占、干扰广播电视专用频率，不得擅自截传、干扰、解扰广播电视信号。","level":1},{"name":"第三章 广播电视节目传送","text":"第二十条 利用有线、无线、卫星等方式从事广播电视节目传送服务，应当按照国家规定取得广播电视节目传送业务经营许可，并按照许可证载明的事项提供服务。\n第二十一条 从事广播电视节目传送服务的单位不得利用所拥有的网络、频率或者其他资源擅自开办广播电视节目；不得为非法开办的节目以及来源非法的广播电视信号提供传送服务；不得擅自传送境外卫星电视节目；不得在所传送的节目中插播其他节目和信息。\n从事广播电视节目传送服务的无线台站经核准使用的频率、频段不得出租、转让，各项技术参数不得擅自变更。\n第二十二条 省人民政府广播电视行政部门应当制定广播电视传送服务质量标准和服务规范。\n广播电视传送服务单位应当按照国家和省有关规定建立健全服务质量管理制度，提高传送服务质量。\n第二十三条 有线电视基本收视维护费和相关服务收费实行政府定价；有线电视增值业务服务、信息网络传播视听节目服务实行市场调节价。\n第二十四条 有线广播电视传送服务单位应当向社会公布其业务种类、服务范围、服务时限和资费标准。\n广播电视用户有权自主选择接受依法开办的各项广播电视传送服务。\n有线广播电视传送服务单位、信息网络传播视听节目服务单位对所提供的服务应当明码标价，并为用户查询消费明细提供便利条件。\n第二十五条 用户申请安装、移装有线广播电视接收设施的，有线广播电视传送服务单位应当在其公布的时限内装机开通。\n有线广播电视传送服务单位逾期未能装机开通的，收视服务期应当顺延自开通之日起计算。\n第二十六条 有线广播电视传送出现故障，不能在服务协议约定的维修时间内修复的，应当顺延收视服务期；属于广播电视用户设备原因的除外。\n有线广播电视传送服务单位应当在用户收视服务期届满前通过手机短信、电视字幕等方式将收视服务期届满信息告知用户。收视服务期届满后未交费的，应当给予三十日的交费宽限期，宽限期内不得停止广播电视传送服务。","level":1},{"name":"第四章 节目制作和播放","text":"第二十七条 广播电视节目、信息网络视听节目和公共视听载体视听节目应当符合法律法规有关规定，坚持正确的价值导向和舆论导向，贴近实际、贴近生活、贴近群众，弘扬社会主义核心价值观。\n第二十八条 任何单位和个人不得制作、播放含有下列内容的节目：\n（一）危害国家统一、主权和领土完整的；\n（二）泄露国家秘密，危害国家安全，损害国家荣誉和利益的；\n（三）煽动民族分裂，破坏民族团结，侵害民族风俗习惯，损害民族优秀文化传统的；\n（四）宣扬邪教、迷信，渲染暴力、色情、赌博、恐怖活动，教唆犯罪或者传授犯罪方法的；\n（五）歪曲、丑化、亵渎、否定英雄烈士事迹和精神的；\n（六）侵害未成年人合法权益或者损害未成年人身心健康的；\n（七）诽谤、侮辱他人，或者侵害公民个人隐私等合法权益的；\n（八）危害社会公德，扰乱社会秩序，破坏社会稳定的；\n（九）法律、法规和国家规定禁止的其他内容。\n第二十九条 广播电视节目由广播电视播出机构和依法设立的广播电视节目制作经营单位制作。\n广播电视播出机构、信息网络传播视听节目服务单位、公共视听载体运营单位不得播放未取得发行许可的电影、电视剧、动画片等。\n第三十条 省人民政府广播电视行政部门设立专项资金，遴选体现时代精神、传承中华优秀传统文化的公益广播电视节目和电影、电视剧等进行补助扶持和推介。\n鼓励社会组织依法设立广播电视节目制作经营单位，投资制作优质广播电视节目和信息网络视听节目。\n第三十一条 从事信息网络传播视听节目服务应当依法取得信息网络传播视听节目许可。\n省、设区的市广播电视播出机构从事信息网络视听节目转播类服务的，应当按照国家有关规定办理备案手续。\n信息网络传播视听节目服务单位应当按照许可或者备案的事项开展视听节目服务，并在播出界面显著位置标注经批准的播出标识、名称、信息网络传播视听节目许可证或者备案编号。\n信息网络传播视听节目服务，包括互联网视听节目服务和专网及定向传播视听节目服务。\n第三十二条 任何单位和个人不得转播、链接、聚合、集成非法的广播电视节目和信息网络视听节目。\n任何单位和个人不得向无信息网络传播视听节目许可证或者未经备案的单位提供与信息网络传播视听节目服务有关的代收费以及信号传输、服务器托管等服务。\n第三十三条 利用公共视听载体播放视听节目的，运营单位应当在运营开播后十五日内，报所在地县级人民政府广播电视行政部门备案。\n公共视听载体，是指固定在广场、建筑物（构筑物）内外以及公共交通工具内，向公众播放节目的视听显示装置，仅发布广告的除外。\n第三十四条 广播电视播出机构、信息网络传播视听节目服务单位播放广告应当符合法律法规和国家有关规定，遵循公序良俗；应当保持节目的完整，除在节目自然的间歇外，不得擅自在节目中插播广告；应当对广告时间作出明显提示，不得超出国家规定的广告播出时间比例。\n广告应当真实、合法，以健康的表现形式表达广告内容，不得含有虚假或者引人误解的内容，不得欺骗、误导消费者。\n禁止以新闻报道形式变相发布广告或者以介绍健康、养生知识等形式变相发布医疗、药品、医疗器械、保健食品广告。\n广播电视播出机构、信息网络传播视听节目服务单位、公共视听载体运营单位应当按照规定制作、播放公益性广告。\n第三十五条 广播电视播出机构、信息网络传播视听节目服务单位、公共视听载体运营单位应当建立节目审查制度，对其播放的节目内容进行播前审查，重播重审。\n广播电视播出机构、广播电视传送服务单位、信息网络传播视听节目服务单位、公共视听载体运营单位负责本单位的安全播出工作，制定应急预案，发现节目中含有违法内容或者有非法信息侵入的，应当立即停止传送、播放，保存传送、播放记录，并向广播电视行政部门报告。\n第三十六条 县级以上人民政府广播电视行政部门应当加强广播电视监测平台建设，负责对各类节目信号的实时监控和预警应急处置。\n广播电视播出机构、广播电视传送服务单位、信息网络传播视听节目服务单位、公共视听载体运营单位应当依法接受广播电视行政部门监督检查，为节目监控、预警应急等公共管理系统提供信号接入条件，保障相关设备设施的正常运行，并提供相关数据资料；对已经播放的节目，应当按照国家、省有关规定确定的期限完整保存。","level":1},{"name":"第五章 公共服务","text":"第三十七条 县级以上人民政府应当将广播电视公共服务所需经费纳入财政预算，明确广播电视公共服务的内容和标准，保障公众免费收听、收看国家、省和当地一定数量的广播电视节目，并向社会公开。\n对纳入广播电视公共服务的免费节目，广播电视传送服务单位应当无偿传送，保障公众免费收听、收看。\n第三十八条 县级以上人民政府应当重点扶持农村、革命老区、少数民族地区和边远贫困地区的广播电视事业发展和公共服务能力建设，促进城乡广播电视公共服务均等化。\n第三十九条 县级以上人民政府应当统筹运用有线、无线、卫星等传输技术手段，做好广播电视节目无线数字化覆盖工程、应急广播、农村智能广播和广播电视直播卫星户户通等广播电视惠民工程，提高农村广播电视综合覆盖率。\n第四十条 县级以上人民政府采取政府购买服务等措施，支持社会力量参与广播电视公共服务。\n鼓励社会资本依法投入广播电视公共服务，拓宽公共服务资金来源渠道。\n第四十一条 县级以上人民政府广播电视行政部门应当建立覆盖城乡、统一协调、快速高效的应急广播体系，并将其建设、维护、管理纳入当地公共服务范围。\n纳入应急广播体系的广播电视播出机构、广播电视传送服务单位以及广播站、广播室，按照规定承担应急广播公共服务任务，负责应急广播电视设施的日常维护工作。\n第四十二条 有线广播电视传送服务单位应当按照国家和省有关规定对特困供养人员、最低生活保障家庭、农村贫困户、优抚对象以及敬老院、福利院等社会福利机构，实行收费减免政策。\n第四十三条 广播电视播出机构、广播电视传送服务单位应当按照国家和省有关规定履行提供广播电视公共服务的职责和义务，完善服务制度，提高服务质量，不得侵占、挪用广播电视公共服务资金。\n广播电视播出机构、广播电视传送服务单位应当将年度开展广播电视公共服务情况报当地广播电视行政部门。\n第四十四条 县级以上人民政府广播电视行政部门应当加强对本行政区域内广播电视公共服务工作的监督检查，建立反映公众需求的征询反馈制度和有公众参与的广播电视公共服务考核评价制度，提高公共服务质量和效益。","level":1},{"name":"第六章 法律责任","text":"第四十五条 违反本条例，法律法规有规定的，从其规定。\n第四十六条 违反本条例规定，制作、播放含有禁止内容的节目的，由县级以上人民政府广播电视行政部门责令改正，没收违法所得和节目载体，并处3万元以上5万元以下罚款；情节严重的，依法吊销许可证。\n第四十七条 违反本条例规定，未取得信息网络传播视听节目许可，擅自开展信息网络传播视听节目服务的，由县级以上人民政府广播电视行政部门给予警告、责令改正，没收违法所得，可以并处1万元以上3万元以下罚款；情节严重的，依法予以取缔，没收从事违法活动的设备，并处投资总额一倍以上二倍以下罚款。\n违反本条例规定，未按照许可或者备案的事项开展信息网络传播视听节目服务的，由县级以上人民政府广播电视行政部门给予警告、责令改正，可以并处1万元以上3万元以下罚款；情节严重的，依法吊销许可证。\n第四十八条 违反本条例规定,有下列行为之一的，由县级以上人民政府广播电视行政部门给予警告、责令改正，可以并处1万元以上3万元以下罚款；同时，可以对其主要出资者和经营者给予警告，可以并处5千元以上2万元以下罚款：\n（一）未在播出界面显著位置标注经批准的播出标识、名称、信息网络传播视听节目许可证或者备案编号的；\n（二）向无许可证或者未经备案的单位提供代收费以及信号传输、服务器托管等服务的；\n（三）以虚假证明、文件等手段骗取信息网络传播视听节目许可证的。\n有前款第三项规定行为的，依法撤销许可证。\n第四十九条 违反本条例规定，转播、链接、聚合、集成非法的广播电视节目和信息网络视听节目的，由县级以上人民政府广播电视行政部门给予警告、责令改正，没收违法所得，可以并处1万元以上3万元以下罚款；情节严重的，依法吊销许可证。\n第五十条 违反本条例规定，广播电视播出机构、广播电视传送服务单位、信息网络传播视听节目服务单位、公共视听载体运营单位有下列行为之一的，由县级以上人民政府广播电视行政部门责令限期改正；逾期不改正的，处1万元以上3万元以下罚款；情节严重的，责令停播整顿或者依法吊销许可证：\n（一）未按照规定为节目监控、预警应急等公共管理系统提供信号接入条件，保障相关设备设施的正常运行，并提供相关数据资料的；\n（二）未按照规定对已播放的节目予以保存的；\n（三）发现节目中含有非法内容或者有非法信息侵入，未立即停止传送、播放，并向广播电视行政部门报告的；\n（四）拒绝、阻挠广播电视行政部门依法进行监督检查的。\n第五十一条 广播电视播出机构、广播电视传送服务单位未按照国家和省有关规定履行广播电视公共服务的职责和义务的，由县级以上人民政府广播电视行政部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。\n第五十二条 国家机关及其工作人员在广播电视管理和相关公共服务工作中违法行使职权或者不依法履行职责的，对直接负责的主管人员和其他直接责任人员依法给予处分。","level":1},{"name":"第七章 附则","text":"第五十三条 本条例自2018年8月1日起施行。","level":1}]},{"id":"h0191","sections":[{"name":"","text":"（2018年7月26日湖北省第十三届人民代表大会常务委员会第四次会议通过）\n为全面贯彻落实中共中央、国务院和省委关于开展扫黑除恶专项斗争的决策部署，统一思想，凝聚共识，动员组织全社会力量投入扫黑除恶专项斗争，切实扫除黑恶势力，进一步巩固党的执政基础，保障人民安居乐业、社会安定有序、国家长治久安，特作出如下决定。\n一、牢固树立以人民为中心的发展思想，坚定深入开展扫黑除恶专项斗争的意志和决心\n在全国开展为期三年的扫黑除恶专项斗争，是以习近平同志为核心的党中央作出的重大决策，事关社会大局稳定和国家长治久安，事关人心向背和基层政权巩固，事关进行伟大斗争、建设伟大工程、推进伟大事业、实现伟大梦想。黑恶势力是社会的“毒瘤”，严重危害社会稳定、破坏市场经济秩序，严重损害人民群众人身权、财产权，严重侵蚀基层政权、动摇党的执政基础。黑恶不除，则民不安、国不宁。\n自扫黑除恶专项斗争开展以来，全省上下认真贯彻党中央、国务院和省委决策部署，精心组织，扎实推进，成功办理了一批黑恶势力犯罪案件，依法严惩了一批黑恶势力，深挖查处了一批“保护伞”，取得了阶段性成果，人民群众拍手称快。但全省涉黑涉恶问题在一些地方和领域仍然比较突出，扫黑除恶工作开展还不平衡，扫黑除恶工作面临新的形势和任务。全省各级国家机关、社会团体、企事业单位、基层群众性自治组织以及广大人民群众，要以习近平新时代中国特色社会主义思想为指导，切实把思想和行动统一到以习近平同志为核心的党中央决策部署上来，统一到省委的工作要求上来,进一步提高政治站位，强化“四个意识”，充分认识专项斗争的重要性、黑恶势力的危害性、不间断开展“大扫除”的必要性，准确把握开展扫黑除恶专项斗争的政治意义、现实意义和历史意义，坚决同黑恶势力作斗争，确保打赢扫黑除恶攻坚战。\n二、综合运用多种治理手段齐抓共管，压实扫黑除恶专项斗争的政治责任和法律责任\n开展扫黑除恶专项斗争，依法严惩黑恶势力，是全省各级人大及其常委会、人民政府、监察委员会、人民法院、人民检察院的重要职责。全省各级国家机关必须坚持党的领导，坚持人民主体地位，坚持尊崇宪法法律，坚持依法严惩、综合治理、标本兼治，综合运用法律、行政等多种治理手段，加强对扫黑除恶专项斗争的督导和监督问责，确保全省扫黑除恶专项斗争各项责任落到实处。\n各级人大及其常委会要通过完善地方立法、定期听取和审议专项工作报告、开展执法检查、作出决议决定等方式，在建立扫黑除恶长效机制方面发挥助推和保障作用，加强对同级“一府一委两院”扫黑除恶专项斗争工作的监督与支持；严把人大代表选举入口关，完善人大代表建议、批评、意见和人大信访的办理机制，畅通人大代表密切联系群众和及时反映涉黑涉恶问题的渠道，充分发挥人大代表督促、支持扫黑除恶专项斗争的重要作用。\n各级人民政府要将扫黑除恶专项斗争摆到重要位置，切实加强组织领导，定期听取工作汇报，深入研究工作措施，有效整合部门力量，认真落实人财物保障，及时解决突出问题，真正做到认识到位、领导到位、措施到位、责任到位。充分发挥乡镇（街道）在扫黑除恶中的基础作用，以扫黑除恶专项斗争成效护航乡村振兴、脱贫攻坚和基层治理。各级公安机关要充分发挥扫黑除恶主力军的作用，聚焦涉黑涉恶问题突出的重点地区、行业、领域，正确处理“打早打小”与“打准打实”的关系，以线索摸排核查、重点案件侦办、突出治安问题整治为抓手，在精准打击、深度打击、延伸打击上下功夫，切实打好扫黑除恶主动仗攻坚仗整体仗。各级教育部门要会同有关机关建立黑恶势力侵害校园案件及时报告制度，健全完善防范工作机制。各级民政部门要会同相关部门严格资格审查，从源头杜绝“恶人”治村（社区）现象。各级司法行政机关应当加强对律师办理黑社会性质组织犯罪案件辩护、代理工作的指导监督，严格落实涉黑涉恶服刑及刑满释放人员包保管控和教育帮扶措施。其他各有关部门要各司其职，依法行政，强化日常监管，防止不作为和乱作为，最大限度挤压黑恶势力滋生空间。\n各级监察委员会要坚持问题导向，加强与有关机关的协作配合，坚持把扫黑除恶同反腐败斗争和基层“拍蝇”结合起来，把深挖、查处“保护伞”与查办涉黑涉恶案件结合起来，重点查处发生在群众身边的党员干部和其他公职人员涉黑涉恶腐败尤其是充当黑恶势力“保护伞”问题，以及地方党政机关、相关职能部门及其工作人员推动扫黑除恶专项斗争工作不力等问题，强化监督，依法调查，严肃处置，堵塞漏洞。\n各级人民法院、人民检察院、公安机关、司法行政机关必须认真贯彻最高人民法院、最高人民检察院、公安部、司法部制定的《关于办理黑恶势力犯罪案件若干问题的指导意见》，坚持以事实为根据、以法律为准绳，准确把握法律政策界限，密切配合，相互支持，相互制约，及时会商疑难案件、分歧事项、法律适用等问题，切实加强对下级机关扫黑除恶工作的领导、指导，确保全省扫黑除恶专项斗争在法治轨道上运行。各级审判机关、检察机关要落实以审判为中心的刑事诉讼制度改革要求，严格掌握取保候审、不批捕、不起诉和缓刑、减刑、假释的适用条件，把好案件事实关、证据关、程序关和法律适用关，统筹调配办案力量，充分利用财产刑、资格刑降低再犯可能性，确保扫黑除恶专项斗争政治效果、法律效果和社会效果相统一。\n三、坚持专门工作与群众路线相结合，努力在全社会形成扫黑除恶的浓厚氛围\n采取多种形式，加强对开展扫黑除恶专项斗争重大意义的宣传教育，增强全社会的责任感、使命感、紧迫感。深入开展“七五”普法宣传和社会主义核心价值观宣传，提高人民群众的宪法意识和法治观念。加强正面宣传和舆论引导，做好法律政策宣讲、解疑释惑等工作，及时发现、封堵和依法查处有害信息。支持新闻媒体及时报道典型案件和扫黑除恶专项斗争进展情况，开展舆论监督，强力震慑黑恶势力，赢得人民群众支持。\n深入发动人民群众，广泛收集涉黑涉恶线索，提高深度扫黑除恶的能力和水平。设立和完善扫黑除恶专项斗争举报电话、举报信箱、网上举报平台以及有奖举报制度，鼓励公民、法人及其他组织依法及时举报涉黑涉恶犯罪和“村霸”等突出问题。完善并严格落实举报人、证人、鉴定人、被害人及其近亲属、扫黑除恶工作人员及其近亲属等人员的相关保护制度。\n以扫黑除恶专项斗争为牵引，着力解决人民群众深恶痛绝的赌博、吸毒、传销、拐卖、非法集资、金融诈骗等违法犯罪。探索和完善以乡镇(街道)、村(社区)为单位对全体村（居）民开展安全度、满意度调查测评，切实加大在扫黑除恶专项斗争绩效考评中群众意见的权重。\n四、大力加强基层基础建设，健全防止黑恶势力滋生的长效机制\n依法健全村（居）民自治机制，完善自治、法治、德治相结合的乡村治理体系，保障和支持村务监督委员会依法行使监督权，充分发挥村（居）民委员会在村（居）民自我管理、自我教育、自我服务中的重要作用。丰富群众精神文化生活，抵制落后腐朽文化侵蚀，鼓励群众勇于同一切不良风气和违法犯罪行为作斗争。\n贯彻执行村（居）民委员会法律法规，严格基层换届候选人资格审查，认真组织基层群众性自治组织换届选举，坚决防止“村霸”、涉黑涉恶等人员进入村（社区）“两委”。依法严厉打击黑恶势力通过威胁、贿赂、利诱等方式干扰破坏村（社区）“两委”选举的行为。采取“一村（社区）一策”持续精准整顿软弱涣散基层组织，对确属“村霸”、涉黑涉恶的村（社区）干部，依法依纪坚决处理。\n要立足当前，着眼长远，坚持边打边治边建，不断推进基层社会治理创新。加强社会治安防控体系和社会信用体系建设，完善社会矛盾排查预警机制和重大决策社会稳定风险评估机制，推进群众性治安防控“雪亮工程”建设，健全各级综治中心和网格化平台，推动社会治理重心向基层下移，将涉黑涉恶违法犯罪信息纳入社会信用惩戒体系，建立健全从源头上防止黑恶势力滋生的长效机制，着力打造共建共治共享的社会治理格局。\n深入开展扫黑除恶专项斗争，对于全面建成小康社会，维护全省改革发展稳定大局，实现荆楚人民安居乐业，意义重大。全省人民要紧密团结在以习近平同志为核心的党中央周围，在省委的坚强领导下，统一意志，坚定信心，主动作为，不胜不休，为建设平安湖北、法治湖北作出新的更大贡献！","level":0}]},{"id":"h0192","sections":[{"name":"","text":"（2018年9月30日湖北省第十三届人民代表大会常务委员会第五次会议通过 根据2020年6月3日湖北省第十三届人民代表大会常务委员会第十六次会议《关于集中修改、废止涉及取消证明事项的部分省本级地方性法规的决定》第一次修正 根据2021年9月29日湖北省第十三届人民代表大会常务委员会第二十六次会议《关于集中修改涉及长江保护法省本级地方性法规的决定》第二次修正 根据2022年11月25日湖北省第十三届人民代表大会常务委员会第三十四次会议《关于集中修改、废止部分省本级地方性法规的决定》第三次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第四次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了加强河道采砂管理，保障河势稳定和防洪、通航安全，推进长江经济带生态环境保护，根据《中华人民共和国生态环境法典》、《中华人民共和国水法》、《中华人民共和国河道管理条例》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内从事河道采砂及其管理活动。《长江河道采砂管理条例》有规定的，从其规定。\n本条例所称河道采砂，是指在河道（包括湖泊、水库、人工水道等）管理范围内开采砂石、取土和淘金等行为。\n第三条 河道砂石资源属于国家所有，任何单位或者个人不得非法开采。\n河道采砂管理应当遵循生态优先、科学规划、严格控制、规范开采、依法监管的原则。\n第四条 河道采砂管理实行行政首长负责制。\n县级以上人民政府应当加强对本行政区域内河道采砂管理工作的领导，健全部门、区域联动协作机制，推进河道采砂管理能力建设和信息化建设，将河道采砂管理工作纳入河湖长制管理，健全河道采砂管理的督察、通报、考核、问责制度。\n乡镇人民政府、街道办事处应当按照上级人民政府及其有关部门的要求做好河道采砂管理的相关工作。\n村（居）民委员会应当配合做好河道采砂管理相关工作。\n第五条 县级以上人民政府河道采砂主管部门负责本行政区域内河道采砂的管理和监督检查工作。\n交通运输主管部门负责采（运）砂船舶（车辆）的管理，依法查处证照不齐全的采（运）砂船舶(车辆)、非法码头以及违法运输砂石等行为。\n公安机关负责依法处置河道采砂活动中非法采砂、无证驾驶船舶（车辆）、妨害公务等治安违法和犯罪行为。\n船舶工业、标准化主管部门负责采（运）砂船舶建造和改造的管理。\n生态环境、自然资源、农业农村、市场监管、林业等主管部门按照各自职责，依法做好河道采砂相关监督管理工作。\n第六条 鼓励和支持开展制砂科学技术研究，推广应用先进适用的制砂技术、装备，发展现代、环保的砂石供应产业。\n第七条 国家机关及其工作人员不得违反规定参与河道采砂经营活动，不得纵容、包庇河道采砂违法行为。","level":1},{"name":"第二章 河道采砂规划","text":"第八条 河道采砂规划应当在调研论证的基础上，根据生态环境安全、防洪安全、通航安全和河势稳定的要求编制，并与流域综合规划和防洪、河道整治、航道整治、饮用水水源保护、水生生物资源保护等专业规划相衔接。\n汉江丹江口大坝以下河段、东荆河的采砂规划，由省人民政府河道采砂主管部门组织编制，报省人民政府批准实施。\n其他河道的采砂规划，由设区的市（自治州）、县级人民政府河道采砂主管部门按照省有关规定对每条河道组织编制，经上一级河道采砂主管部门同意后报本级人民政府批准实施。\n编制河道采砂规划应当征求交通运输、生态环境、自然资源、公安、农业农村、林业等主管部门的意见，并采取论证会、听证会或者其他方式征求专家、公众和利益相关方的意见。\n经批准的河道采砂规划应当向社会公开，并严格执行；确需调整的，应当经原批准机关批准。\n第九条 河道采砂规划应当包括以下内容：\n（一）砂石砂质、分布、储量，可利用砂石总量与补给分析；\n（二）采砂影响分析评价；\n（三）禁采区、可采区；\n（四）禁采期、可采期；\n（五）年度采砂控制总量、开采范围和开采高程；\n（六）采砂船舶（机具）的种类、控制数量和开采方式；\n（七）沿河两岸临时堆砂场的控制数量及布局；\n（八）弃料处理和河道清理、修复；\n（九）规划实施与管理。\n第十条 下列区域为禁采区：\n（一）饮用水水源保护区、水产种质资源保护区、鸟类栖息地；\n（二）自然保护区、风景名胜区、国家公园、森林公园、湿地公园、地质公园以及天然林保护范围；\n（三）河道防洪工程、河道整治工程、航道整治工程、航道构（建）筑物、航道配套设施、水库枢纽、水文监测设施、水环境监测设施、涵闸以及取水、排水、水电站等工程及其附属设施的安全保护范围；\n（四）桥梁、码头、浮桥、渡口、过河电缆、管道、隧道等工程及其附属设施的安全保护范围；\n（五）河道险工、险段和浅窄航道附近区域；\n（六）法律、法规规定禁止采砂的其他区域。\n第十一条 下列时段为禁采期：\n（一）主汛期；\n（二）河道达到或者超过警戒水位时；\n（三）法律、法规规定禁止采砂的其他时段。\n第十二条 县级以上人民政府依法划定和公告禁止采砂区、禁止采砂期，并设立明显的禁采区标志。禁止在禁采区和禁采期从事采砂活动。\n在可采区、可采期内，因防洪、河势改变、水工程建设、水生态环境遭受严重改变以及有重大水上活动等情形不宜采砂的，县级以上人民政府河道采砂主管部门应当划定临时禁采区或者规定临时禁采期，报同级人民政府批准后予以公告。\n第十三条 县级以上人民政府河道采砂主管部门应当根据河道采砂规划，制定本行政区域内可采区的年度采砂实施方案，经本级人民政府同意，报上一级河道采砂主管部门备案后予以公布。\n年度采砂实施方案应当包括下列内容：\n（一）采区基本情况，许可方式、期限；\n（二）采区采砂控制量、开采范围和开采高程；\n（三）采砂作业方式、船舶（机具）数量及采砂设备种类、功率；\n（四）临时堆砂场、卸砂点控制数量、布局、存放时限；\n（五）河道清理、修复方案；\n（六）采区现场监管方案；\n（七）其他需要明确的事项。","level":1},{"name":"第三章 河道采砂许可","text":"第十四条 河道采砂实行许可制度。\n县级以上人民政府河道采砂主管部门应当按照河道采砂分级管理权限实施许可。河道采砂分级管理权限由省人民政府河道采砂主管部门规定。\n未经许可，禁止在本行政区域内从事河道采砂活动。\n第十五条 河道采砂实行总量控制制度。河道采砂主管部门应当根据河道采砂规划严格控制本行政区域内每条河道的年度采砂总量，实际审批的年度采砂总量不得超过年度采砂控制总量，每一可采区实际审批的年度采砂量不得超过该可采区的年度采砂控制量。\n第十六条 申请从事河道采砂的单位和个人应当符合下列条件：\n（一）有依法取得的营业执照；\n（二）有符合环保等要求的采砂作业方式；\n（三）有符合要求的采砂设备和采砂技术人员；\n（四）用船舶采砂的，船舶、船员的证书齐全有效；\n（五）无非法采砂失信行为和不良记录；\n（六）法律、法规规定的其他条件。\n第十七条 申请办理河道采砂许可，应当提交或者提请许可机关核实下列资料：\n（一）河道采砂申请；\n（二）营业执照；\n（三）采砂船舶（机具）证书、采砂技术人员的基本情况；\n（四）砂石堆放地点和弃料处理方案；\n（五）船舶油污、生活废弃物的处理方案；\n（六）河道清理、修复方案；\n（七）规范开采的承诺书;\n（八）其他有关资料。\n第十八条 河道采砂许可由河道采砂主管部门通过招标、拍卖、挂牌等公平竞争的方式实施。\n河道采砂主管部门应当依法确定中标人或者买受人，发放河道采砂许可证，并书面告知从事河道采砂应当遵守的相关规定。\n第十九条 因吹填造地、路基填筑等重点工程需要进行河道采砂的，应当编制采砂可行性论证报告，经上一级人民政府同意，依法向有许可权的河道采砂主管部门申请。对符合河道采砂许可条件的，由河道采砂主管部门发放河道采砂许可证。\n因整修河道堤防进行吹填固基等公益性采砂活动的，不需要办理河道采砂许可证，但应当按照要求编制采砂可行性论证报告，报有许可权的河道采砂主管部门审批。所采砂石不得用于经营。\n第二十条 县级以上人民政府可以决定对本行政区域内的河道砂石资源按照政企分开的原则依法实行统一经营，具体办法由县级以上人民政府规定，并报上一级人民政府备案。\n第二十一条 河道采砂许可证由省人民政府河道采砂主管部门统一印制，载明采砂单位或者个人的名称（姓名），采砂船舶（机具）名称、编号、功率，采砂地点、时限、开采范围、开采高程以及作业方式、现场清理方式、许可证有效期限等事项。\n河道采砂许可证的有效期不得超过一年。河道采砂许可证的有效期届满或者累计采砂量达到规定开采量的，采砂单位和个人应当终止采砂行为，并按照规定对作业现场进行清理、修复；发证机关应当收回或者注销河道采砂许可证，并予以公告。\n河道采砂许可证载明的事项发生变更的，被许可人应当及时向作出许可决定的河道采砂主管部门申请办理变更手续。\n禁止伪造、涂改、买卖、出租、出借或者以其他方式非法转让河道采砂许可证。\n第二十二条 取得河道砂石开采权的单位和个人应当依法缴纳矿业权出让收益。矿业权出让收益的征收和使用管理，按照国家及省有关规定确定。国家另有规定的从其规定。\n第二十三条 依法整治疏浚河道、航道、涉水工程所产生的砂石需要综合利用的，应当由项目所在地县级以上人民政府报上一级人民政府河道采砂主管部门审批后依法处置。","level":1},{"name":"第四章 河道采砂监督管理","text":"第二十四条 从事河道采砂的单位和个人应当遵守下列规定：\n（一）按照河道采砂许可确定的时间、地点、采砂控制量、开采范围、开采高程和作业方式等进行开采；\n（二）设置采区边界标识，提供有关资料，接受监督检查；\n（三）及时清运砂石、平整弃料堆体或者采砂坑槽；\n（四）不得在河道管理范围内擅自设置砂场、堆积砂石或者弃料；\n（五）不得违反有关通航安全规定，不得向航道和通航水域抛弃废弃物，不得妨碍航道畅通、损害通航条件；\n（六）不得危及水工程、水文、桥梁、隧道、管线、环境保护等设施以及岸坡安全；\n（七）法律、法规有关河道采砂的其他规定。\n第二十五条 采（运）砂船舶（机具）应当依法持有合格的检验证书、登记证书、必要的航行资料。\n未依法持有前款规定证书、航行资料的采（运）砂船舶（机具），不得在河道管理范围内通行、采（运）砂。\n第二十六条 任何采砂船舶不得在禁采区滞留；未取得河道采砂许可证的采砂船舶不得在可采区滞留。\n采砂船舶在禁采期应当停放在所在地县级人民政府指定的集中停放地点。无正当理由，不得擅自离开。\n第二十七条 河道管理范围内的运砂船舶（车辆）装运河道砂石，应当持有负责现场监管的河道采砂主管部门核发的砂石合法来源凭证。没有砂石合法来源凭证的河道砂石，运砂船舶（车辆）不得装运，任何单位和个人不得收购、销售。\n砂石合法来源凭证由省人民政府河道采砂主管部门统一格式，内容包括河道砂石来源地、运输工具及所有人的证照号、装运时限、砂石数量等有关事项。\n第二十八条 县级以上人民政府河道采砂、交通运输等主管部门应当加强对河道采（运）砂活动的监督管理，组织开展巡查检查，及时发现和查处违法采（运）砂行为，对采砂作业现场的清理、修复等情况予以监督管理。\n第二十九条 县级以上人民政府应当建立河道采砂预警应急联动以及联合执法机制，组织河道采砂、公安、交通运输、生态环境等主管部门开展联合执法，对采砂现场的生产、交易、运输和水上交通、社会治安进行监督管理。\n对于交界水域，应当加强区域合作，建立健全交界水域联管联治机制，开展交界河段非法采砂联合整治。\n第三十条 县级以上人民政府应当组织交通运输、河道采砂、公安、船舶工业、市场监管等主管部门开展采砂船舶的综合整治工作，对本行政区域内的采砂船舶进行登记，对采砂船舶进行总量控制，查处违法建造和改造采砂船舶的行为。\n第三十一条 县级以上人民政府河道采砂主管部门应当建立河道采砂管理平台，交通运输、公安、市场监管等主管部门应当将执法监管信息数据纳入河道采砂管理平台，实现信息互换、监管互认、执法互助。\n县级以上人民政府应当在采砂船舶集中停放点、非法采砂多发水域安装监控系统，为采砂船舶安装电子信息化监控设备，提高信息化监管水平。\n从事采砂的单位和个人应当配合安装电子信息化监控设备，不得损坏或者擅自拆除。\n第三十二条 县级以上人民政府有关部门履行河道采砂监督管理职责时，有权采取下列措施：\n（一）进入采砂生产、运输、存放场所进行调查、取证；\n（二）要求采（运）砂单位和个人如实提供与河道采（运）砂有关的文件、证照、资料；\n（三）责令采（运）砂单位和个人停止违法采（运）砂行为；\n（四）依法扣押非法采砂船舶（机具）、运砂船舶(车辆)以及非法采（运）的砂石。\n第三十三条 县级以上人民政府有关部门应当建立河道采砂违法行为信用记录，并纳入社会信用信息服务平台，依法实行联合惩戒。\n第三十四条 出现影响河势稳定、防洪安全、通航安全或者生态环境的自然灾害或者其他重大事件需要暂停采砂的，采砂单位和个人应当按照县级以上人民政府河道采砂主管部门的规定暂停采砂活动。\n前款规定的情形消除后，县级以上人民政府河道采砂主管部门应当及时解除临时处置措施。\n第三十五条 县级以上人民政府河道采砂主管部门应当建立河道采砂违法行为的举报制度，公布举报电话、电子邮箱等。\n对河道采砂的违法行为，任何单位和个人有权向河道采砂主管部门举报。经查证属实的，对举报人给予奖励，并为其保密。","level":1},{"name":"第五章 法律责任","text":"第三十六条 违反本条例，法律、法规有规定的，从其规定。\n第三十七条 国家机关及其工作人员有下列行为之一的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）不执行已经批准的河道采砂规划，擅自修改河道采砂规划或者违反河道采砂规划批准采砂的；\n（二）不履行河道采砂监督管理职责，造成河道采砂管理秩序混乱或者重大责任事故的；\n（三）不按照规定审批发放河道采砂许可证或者其他批准文件的；\n（四）不按照规定征收砂石矿业权出让收益，致使国家资源流失的；\n（五）截留、挪用砂石矿业权出让收益的；\n（六）违反规定参与河道采砂经营活动或者纵容、包庇河道采砂违法行为的；\n（七）擅自利用因整治疏浚河道、航道、涉水工程所产生的砂石的；\n（八）其他滥用职权、玩忽职守、徇私舞弊的行为。\n第三十八条 违反本条例第十二条第一款、第十四条第三款规定，未依法取得许可从事采砂活动或者在禁采区和禁采期从事采砂活动的，由河道采砂主管部门责令停止违法行为，没收违法所得以及用于违法活动的船舶、设备、工具，并处货值金额二倍以上二十倍以下罚款；货值金额不足10万元的，并处20万元以上200万元以下罚款；已经取得河道采砂许可证的，吊销河道采砂许可证。\n第三十九条 违反本条例第二十一条第四款规定，伪造、涂改、买卖、出租、出借或者以其他方式非法转让河道采砂许可证的，由河道采砂主管部门吊销河道采砂许可证或者收缴伪造的河道采砂许可证，没收违法所得，并处3万元以上10万元以下罚款。\n第四十条 违反本条例第二十四条第一项规定，未按照河道采砂许可规定采砂的，由河道采砂主管部门责令停止违法行为，扣押违法采砂船舶（机具），没收违法所得，并处3万元以上10万元以下罚款；情节严重的，吊销河道采砂许可证，并处10万元以上20万元以下罚款。\n违反本条例第二十四条第四项规定，在河道管理范围内擅自设置砂场、堆积砂石或者弃料的，由河道采砂主管部门责令限期改正，清除堆积的砂石、弃料或者采取其他措施恢复原貌；逾期未改正的，处1万元以上5万元以下罚款。\n第四十一条 违反本条例第二十五条规定，未依法持有合格检验证书、登记证书、必要航行资料的采（运）砂船舶（机具）在河道通行的，由交通运输主管部门责令停止航行；拒不停止的，扣押采（运）砂船舶（机具）。在河道违法采砂的，由河道采砂主管部门按照本条例第三十八条规定处罚，并没收采砂船舶（机具）。\n第四十二条 违反本条例第二十六条规定，采砂船舶在禁采区滞留，未取得河道采砂许可证的采砂船舶在可采区滞留或者采砂船舶在禁采期未按指定位置集中停放或者擅自离开的，由河道采砂主管部门责令限期改正，并处1万元以上3万元以下罚款。\n第四十三条 违反本条例第二十七条第一款规定，在河道管理范围内装运没有合法来源凭证的河道砂石的，由交通运输主管部门扣押违法运砂船舶(车辆)，没收违法所得和所运砂石，并处1万元以上5万元以下罚款。在河道管理范围内收购、销售没有合法来源凭证的河道砂石的，由河道采砂主管部门没收违法所得和砂石，并处5万元以上20万元以下罚款。\n第四十四条 违反本条例第三十一条第三款规定，损坏或者擅自拆除采砂船舶电子信息化监控设备的，由河道采砂主管部门责令停止违法行为、限期恢复原状；逾期未改正的，处1万元以上3万元以下罚款。\n第四十五条 县级以上人民政府河道采砂主管部门及其他负有河道采砂监督管理职责的部门在查处采砂违法行为时，发现涉嫌犯罪的，应当依法移送司法机关追究刑事责任。","level":1},{"name":"第六章 附则","text":"第四十六条 本条例所称采砂机具，包括挖掘机械、吊杆机械、分离机械等与采运砂石相关的机械和工具。\n第四十七条 本条例自2018年12月1日起施行。","level":1}]},{"id":"h0193","sections":[{"name":"","text":"（2018年9月30日湖北省第十三届人民代表大会常务委员会第五次会议通过 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了保护天然林生态系统的原真性和完整性，加强长江经济带生态环境保护，保障国家生态安全，促进生态文明建设，根据《中华人民共和国生态环境法典》、《中华人民共和国森林法》、《中华人民共和国森林法实施条例》等有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内的天然林保护和管理。\n本条例所称天然林包括天然起源的原生林、次生林及其林地。\n本省天然林应当全部纳入保护范围；人工林中的公益林保护适用本条例。\n涉及自然保护区管理、国家公园管理、森林公园管理、风景名胜区管理、野生动植物保护、林业有害生物防治、森林防火等，法律、法规对天然林保护另有规定的，从其规定。\n第三条 天然林保护和管理应当坚持政府负责、社会参与，遵循生态优先、保护第一、自然恢复、严守红线、持续发展的原则，保护物种基因和生物多样性，提升生态系统质量和稳定性。\n第四条 县级以上人民政府应当加强对天然林保护工作的领导，将天然林保护工作纳入国民经济和社会发展规划以及生态文明建设相关规划，建立天然林保护生态效益补偿机制，将天然林普查、保护管理、生态修复及其基础设施建设等经费纳入财政预算。\n乡镇人民政府、街道办事处按照法律、法规的规定和上级人民政府的要求，开展天然林保护工作。\n村（居）民委员会应当协助当地人民政府开展天然林保护工作。\n第五条 天然林保护实行行政首长负责制和目标责任考核制，将天然林保护情况纳入领导干部自然资源资产离任审计的内容，实行生态环境损害责任终身追责制。\n第六条 县级以上人民政府林业主管部门负责本行政区域内天然林的保护和管理工作。\n县级以上人民政府其他相关部门按照各自职责，共同做好天然林保护和管理工作。\n第七条 鼓励公民、法人和其他组织依法通过捐赠、资助、认养、志愿服务等方式参与天然林保护、监督和管理活动。\n鼓励和支持开展天然林生态系统保护、野生动物救护、珍稀植物培育等科学研究和技术推广工作。\n第八条 各级人民政府及有关部门和媒体应当加强天然林保护的科普教育和生态文化宣传，促进公众了解天然林资源和价值，增强公众保护天然林的意识，培育和弘扬生态文化，营造爱护生态环境的社会氛围。\n对在天然林保护工作中做出突出贡献的公民、法人和其他组织，给予表彰和奖励。","level":1},{"name":"第二章 调查与规划","text":"第九条 省人民政府应当按照国家有关规定，组织林业、自然资源、生态环境、农业农村等主管部门每五年开展一次全省天然林资源状况普查，掌握全省天然林的数量、质量、结构和分布等情况，建立全省天然林资源分布地理信息系统和档案。\n县级以上人民政府林业主管部门应当开展天然林资源调查，建立天然林监测体系和信息系统，设立监测样点，建立天然林数据库，监测天然林资源消长和生态变化情况，实现天然林资源档案的动态管理和信息共享。\n第十条 省人民政府应当组织林业、发展改革、自然资源、生态环境、住房城乡建设等主管部门根据生态文明建设相关规划，结合全省天然林资源普查情况，按照应保尽保、分级保护的原则，编制全省天然林保护规划，确定保护范围和保护目标。\n编制天然林保护规划应当遵循自然生态规律，与国土空间规划、生态环境保护规划、林地保护利用规划等相衔接。\n市、县级人民政府应当组织林业主管部门及有关部门，根据全省天然林保护规划编制本行政区域内的天然林保护实施方案，报上一级人民政府批准。\n第十一条 编制天然林保护规划和实施方案，应当组织专家论证，并将依据和理由、保护范围、保护目标、保护措施、实施方法等内容进行公示，征求社会公众和利益相关者的意见；必要时，应当举行听证。\n天然林保护规划和实施方案应当向社会公布，由县级以上人民政府林业主管部门会同相关部门组织实施。\n第十二条 天然林保护规划和实施方案不得擅自调整；确需调整的，应当按照原编制、论证、报批、公布程序进行。\n第十三条 县级以上人民政府应当每五年组织一次天然林保护规划和实施方案的评估工作，必要时应当组织中期评估，提出修编建议。评估结果应当向社会公布，并作为调整本行政区域天然林保护规划和实施方案的依据。\n第十四条 县级以上人民政府林业主管部门应当根据天然林保护规划和实施方案，开展天然林区划落界，在天然林分布集中连片区域分界处设置界桩和标牌。\n任何单位和个人不得损坏、擅自移动界桩和标牌。","level":1},{"name":"第三章 保护与修复","text":"第十五条 按照国土空间规划、生态保护红线以及生态区位重要性、生态脆弱性、生态自然恢复能力和物种珍稀性等指标，将天然林划分为一级天然林和二级天然林，实行分级保护。\n本省重要生态功能区和生态保护红线内的天然林为一级天然林；其他天然林为二级天然林。\n一级天然林和二级天然林的具体范围由省人民政府确定，并在天然林保护规划和实施方案中予以明确。\n第十六条 省人民政府应当建立天然林保护制度，实行天然林保护林长制。省人民政府林业主管部门负责制定林长制实施办法。\n各级林长应当按照林长制实施办法履行天然林保护责任。\n各级人民政府应当根据天然林保护规划和实施方案组织开展天然林保护工作，严格执行天然林保护林长制，建立天然林管护体系，完善管护制度，划分管护责任区，落实管护责任主体、管护责任和措施。\n第十七条 县级以上人民政府林业主管部门应当加强天然林保护基础设施和队伍建设，建设管护站点及管护设施，配备专业技术人员和必要的交通、通讯工具，做好天然林保护工作。\n乡镇人民政府、村（居）民委员会和天然林所有权人或者承包经营权人应当按照规定建立护林组织或者配备护林员，优先聘用当地居民为护林员，在划定的天然林保护范围内开展日常巡护，报告并制止破坏天然林的行为。\n第十八条 县级人民政府应当与天然林的所有权人或者承包经营权人签订天然林区划落界协议书，明确天然林保护范围、措施、权利和义务。\n天然林所有权人或者承包经营权人有依法获得天然林保护相关补助补偿的权利。\n第十九条 国有的天然林管护责任主体为国有林场和自然保护区、国家公园、森林公园、风景名胜区管理单位及其他国有森林经营单位。\n集体所有的天然林管护责任主体为集体经济组织。\n个人所有的天然林管护责任主体为天然林所有权人或者承包经营权人；无能力管护或者自愿委托管护的个人所有天然林，由县级人民政府林业主管部门或者其委托的单位统一管护，履行管护责任。\n第二十条 天然林管护实行管护责任协议制度。\n县级以上人民政府林业主管部门或者其委托的乡镇人民政府应当与天然林管护责任主体签订管护责任协议书，明确天然林管护中各方的权利、义务以及管护范围、期限、措施和质量要求等，约定管护责任。\n各级人民政府对面积大、分布相对集中和防火、禁伐、禁牧任务重的天然林，可以采取购买专业管护服务或者专业承包管护的方式进行管护。\n第二十一条 对一级天然林实行全面封禁、永久保护。除依法建设必要的保护和科研监测设施外，禁止一切破坏天然林生态环境的生产经营活动。\n第二十二条 对二级天然林采取自然恢复为主、人工促进修复为辅的保护措施，恢复乔灌草植被。\n在二级天然林保护范围内从事采集种子、采挖野生植物、开展游憩等活动，应当依照法律、法规的规定办理相关手续，不得毁坏林木或者破坏林地，不得擅自改变林地用途，不得破坏生态环境。\n第二十三条 禁止在天然林保护范围内实施下列行为：\n（一）毁林开垦；\n（二）毁林造林；\n（三）建设光伏发电项目；\n（四）在有林地上建设风力发电项目；\n（五）建设可能造成水土流失、破坏生物多样性和污染环境的生产经营设施；\n（六）商业性采伐林木；\n（七）采挖移植林木或者树蔸，采割树脂；\n（八）倾倒石渣、垃圾等固体废弃物；\n（九）违反国家规定采石、采矿、取土；\n（十）使用剧毒、高毒、高残留农药（含除草剂等药剂）；\n（十一）法律、法规禁止的其他行为。\n第二十四条 严格控制征收、占用天然林林地。\n因国家和省人民政府批准的基础设施建设项目确需征收、占用的，应当依法办理审核、审批手续，按照国家和省公益林林地的征收标准征收森林植被恢复费。森林植被恢复费专项用于植树造林、恢复森林植被。\n经批准的建设项目，建设单位、施工单位应当制定污染防治、水土保持和生态保护方案，科学规划和设计，合理施工，并采取有效措施保护天然林。\n第二十五条 对林业有害生物危害较重、依照国家规定确需对天然林实施以保护和促进修复为目的的森林抚育，天然林经营者应当按照森林抚育技术规程编制森林抚育作业设计。\n县级以上人民政府林业主管部门应当组织专家对森林抚育的必要性及森林抚育作业设计进行评审，并将森林抚育对生物多样性保护、生态环境保护和水土保持的影响纳入评审内容。\n森林抚育作业设计经审核批准，由天然林经营者按照批准的作业设计组织实施。\n进行抚育性采伐的，天然林经营者应当依法申请林木采伐许可。县级以上人民政府林业主管部门应当加强对抚育性采伐的监督检查。\n第二十六条 县级以上人民政府应当将天然林保护范围内的宜林荒山、林中空地以及退化林地纳入生态修复范围，采取补植补造、人工点播、飞机撒播等措施，逐步进行生态修复，提升天然林质量。\n在天然林保护范围内以造林方式进行生态修复的，应当保留原生植被，禁止烧山开垦和全垦整地造林。\n第二十七条 县级以上人民政府应当根据天然林保护和恢复的需要，有计划地实施封山育林的生态修复措施。封山育林应当划定封育区、确定封育期，明确封育范围、面积和措施，并予以公告。\n第二十八条 县级以上人民政府应当建立健全森林防火组织，建立森林防火及林业有害生物监测预警体系，加强监测、预报和综合防治工作。\n第二十九条 各级人民政府应当积极营造木材战略储备林，鼓励使用木材替代品。\n鼓励天然林保护范围内的村（居）民使用电、气等清洁能源。\n第三十条 县级以上人民政府应当制定激励政策，鼓励保险机构开展森林保险业务，支持天然林经营者参加森林保险。\n第三十一条 跨行政区域天然林所在地人民政府及其有关部门应当建立联席会议制度和联防联护工作机制，共享信息，协同做好天然林保护工作。","level":1},{"name":"第四章 监督与保障","text":"第三十二条 县级以上人民政府及其林业主管部门应当建立健全天然林保护工作监督检查制度和考核督查机制，加强对下级人民政府及其林业主管部门天然林保护工作的督促检查。\n第三十三条 省人民政府应当每年对天然林保护工作进行检查考核并通报考核结果，对保护天然林不力的市、县级人民政府主要负责人进行约谈，督促其加强天然林保护工作。\n市、县级人民政府应当每年公布天然林保护情况，接受社会监督。\n第三十四条 县级以上人民政府及其有关部门应当对下列天然林保护工作情况实施监督检查：\n（一）应保尽保责任落实情况；\n（二）管护任务完成情况和成效；\n（三）天然林修复情况；\n（四）管护设施建设情况；\n（五）管护档案建立和管理情况；\n（六）相关补助补偿资金使用及管理情况；\n（七）奖惩措施落实情况；\n（八）天然林保护的其他工作情况。\n第三十五条 县级以上人民政府应当制定优惠政策和扶持措施，鼓励、引导天然林保护地区调整和优化产业结构，发展多元化经营，加强劳动技能培训，拓宽农民就业增收渠道。\n在天然林保护范围内，对居住在生态区位重要、生产和生活环境恶劣地区的居民，所在地县级以上人民政府应当结合城镇化建设，逐步实行生态移民，保障、改善移民的生产生活条件。\n第三十六条 省人民政府应当建立天然林保护相关补助补偿资金的动态调整机制，逐步提高补助补偿标准。市、县级人民政府可以根据当地经济发展情况，提高补助补偿标准。\n省人民政府应当对未纳入国家天然林保护范围的天然林，按照国家天然林保护补助资金的标准予以补助，所需资金纳入省级财政预算。\n第三十七条 天然林保护相关补助补偿资金实行专款专用，单独核算；按照国家和省的有关规定，专项用于天然林保护费用的支出和对天然林所有权人或者承包经营权人的补助补偿。补助补偿标准、分配比例、使用和管理具体办法由省人民政府另行制定。\n任何单位和个人不得挤占、截留、挪用天然林保护相关补助补偿资金。\n财政、审计部门应当加强对天然林保护相关补助补偿资金使用的监督、检查、审计，确保资金的合法有效利用。\n第三十八条 县级以上人民政府有关部门应当及时将毁坏天然林等违法行为及其处罚情况归集至省社会信用信息服务平台，依法实行联合惩戒。\n第三十九条 县级以上人民政府根据生态环境保护的需要，在生态区位重要或者生态环境脆弱的区域，采取依法置换、租赁或者征收等方式取得非国有天然林的所有权或者经营权，保护和发展天然林。","level":1},{"name":"第五章 法律责任","text":"第四十条 违反本条例，法律、法规有规定的，从其规定。\n第四十一条 国家机关及其工作人员违反本条例，有下列情形之一的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）未按照规定落实天然林应保尽保责任的；\n（二）未按照规定编制和组织实施天然林保护规划及实施方案的；\n（三）未按照规定审核批准森林抚育作业设计的；\n（四）因违法决策或者未依法履行监管职责等导致天然林受到毁坏的；\n（五）挤占、截留、挪用天然林保护相关补助补偿资金的；\n（六）发现违法行为或者接到违法行为的举报后不予查处的；\n（七）其他滥用职权、玩忽职守、徇私舞弊的行为。\n第四十二条 违反本条例第二十一条、第二十二条第二款规定的，由林业主管部门责令停止违法行为，限期恢复原状；毁坏林木的，补种毁坏林木株数一倍以上三倍以下的树木，可以处毁坏林木价值二倍以上五倍以下罚款；毁坏林地或者擅自改变林地用途的，限期恢复植被和林业生产条件，可以处恢复植被和林业生产条件所需费用三倍以下罚款。\n第四十三条 违反本条例第二十三条规定的，依法赔偿损失；由林业主管部门、农业农村主管部门按照职责分工责令停止违法行为，按照以下规定予以处罚：\n（一）违反第一项、第二项、第七项至第九项规定造成林木毁坏的，补种毁坏林木株数一倍以上三倍以下的树木，可以处毁坏林木价值二倍以上五倍以下罚款；造成林地毁坏的，限期恢复植被和林业生产条件，可以处恢复植被和林业生产条件所需费用三倍以下罚款；\n（二）违反第三项至第五项规定的，限期拆除、恢复植被和林业生产条件，补种毁坏林木株数十倍的树木，并处恢复植被和林业生产条件所需费用三倍以下罚款；\n（三）违反第六项规定的，补种采伐林木株数一倍以上五倍以下的树木，并处采伐林木价值五倍以上十倍以下罚款；\n（四）违反第十项规定，使用者为单位的，处5万元以上10万元以下罚款；使用者为个人的，处500元以上2千元以下罚款，情节严重的，处2千元以上1万元以下罚款。\n第四十四条 违反本条例第二十五条第三款规定，未经审核批准或者未按照审核批准的森林抚育作业设计实施森林抚育的，由林业主管部门责令停止违法行为，补种采伐林木株数一倍以上三倍以下的树木，并处采伐林木价值二倍以上五倍以下罚款。\n第四十五条 拒不按照本条例第四十二条至第四十四条规定补种树木或者补种树木不符合国家规定的，由林业主管部门组织代为补种，所需费用由违法行为人承担。","level":1},{"name":"第六章 附则","text":"第四十六条 本条例自2018年12月1日起施行。","level":1}]},{"id":"h0194","sections":[{"name":"","text":"（2016年9月29日恩施土家族苗族自治州第七届人民代表大会常务委员会第三十二次会议通过 2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议批准 根据2026年5月29日恩施土家族苗族自治州第九届人民代表大会常务委员会第三十五次会议通过 2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议批准的《恩施土家族苗族自治州人民代表大会常务委员会关于集中修改涉及生态环境法典地方性法规的决定》修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强酉水河保护，防治河流污染和生态破坏，推进绿色低碳发展，建设生态文明，根据《中华人民共和国生态环境法典》、《中华人民共和国长江保护法》等法律法规的规定，结合本州实际，制定本条例。\n第二条 本条例适用于本州行政区域内酉水河流域水生态环境的保护活动。\n第三条 酉水河保护坚持预防为主、系统治理、生态优先、绿色发展、公众参与、损害担责的原则。\n第四条 酉水河流域的县级以上人民政府建立跨行政区域保护协调制度。","level":1},{"name":"第二章 政府职责与公众参与","text":"第五条 自治州人民政府负责组织、协调、监督酉水河保护工作。\n酉水河流域的县级人民政府负责本行政区域内酉水河的保护工作，并向同级人民代表大会常务委员会报告本行政区域内酉水河保护工作情况。\n酉水河流域的乡（镇）人民政府应当做好本行政区域内酉水河保护的有关工作。\n酉水河流域的村（居）民委员会应当引导、鼓励村（居）民参与酉水河保护，采取乡规民约等方式规范村（居）民行为，保护和改善酉水河生态环境。\n第六条 酉水河流域实行河湖长制，州、县、乡（镇）各级河湖长负责本行政区域江河湖泊管理和保护相关工作。\n第七条 酉水河流域的县级以上人民政府应当设立酉水河生态环境保护专项资金，列入本级财政预算。\n积极鼓励和引导社会资本参与酉水河保护。\n第八条 生态环境主管部门在其职责范围内对酉水河流域水生态环境保护工作实施统一监督管理。\n水行政、住房城乡建设、农业农村、卫生健康、自然资源、交通运输、林业等有关部门在各自职责范围内，对本行政区域内酉水河流域水生态环境保护工作实施监督管理。\n第九条 酉水河流域的县级以上人民政府及行政主管部门应当建立酉水河保护信息公开制度，依法公开水功能区、饮用水源保护区、水生态环境质量、重点污染源环境监测、排污口设置、水生态环境保护责任区域、责任人、举报方式等信息。\n第十条 酉水河流域的乡（镇）以上人民政府及行政主管部门应当组织开展相关法律法规和生态环境保护知识的宣传普及工作，营造酉水河保护的良好社会环境。\n第十一条 酉水河保护中的重大决策事项应当采取座谈会、协商会、论证会、听证会等方式，听取公民代表和专家学者等方面的意见。对重大水污染案件的调查处理，可以邀请社会组织和公民代表参与。\n第十二条 酉水河流域的县级以上人民政府应当鼓励社会组织、公民参与酉水河保护。\n对酉水河保护做出显著成绩的单位和个人，给予褒扬、激励。","level":1},{"name":"第三章 跨行政区域保护协调机制","text":"第十三条 酉水河流域的县级以上人民政府建立跨行政区域联席会议制度，协调解决跨行政区域的酉水河保护重大事项。\n酉水河流域的县级以上人民政府与相关同级人民政府协商组织召开联席会议，共同执行会议决定。\n第十四条 酉水河流域的县级以上人民代表大会常务委员会应当与相邻同级人民代表大会常务委员会建立协同执法检查机制，监督本行政区域内跨行政区域保护协调制度的实施情况。\n第十五条 酉水河流域的县级以上人民政府之间可以通过签订协议等方式明确跨行政区域保护协调的事项和职责。\n第十六条 酉水河流域的县级以上人民政府之间应当建立联合监测制度。\n酉水河流域的生态环境主管部门对河流上下游交界断面的水质、水量及左右岸的水污染源等进行监测，实现资源共享。\n第十七条 酉水河流域的县级以上人民政府及相关行政主管部门之间应当建立生态环境违法行为相互告知制度，及时通报生态环境违法行为情况；建立生态环境违法行为协同执法制度，共同制定执法事项目录、执法时间表。\n积极推行相对集中行政处罚权制度，加强酉水河保护。\n第十八条 酉水河流域的县级以上人民政府之间应当建立突发生态环境事件等重大事项的通报机制和应急处置机制。\n第十九条 酉水河流域的县级以上人民政府应当建立河流交界断面的水生态环境质量考核机制，并定期向社会公布考核情况。\n第二十条 酉水河流域的县级以上人民政府及相关行政主管部门在作出河流最小生态下泄流量决定前，批准涉及减少河水流量、影响水流流态和可能影响河流交界断面水质的建设项目前，应当征询相邻地区同级人民政府及相关行政主管部门意见。有异议的，可以采取召开联席会议等方式协商解决。\n第二十一条 跨行政区域的水污染纠纷，由有关人民政府生态环境主管部门协商处理；协商不成的，可以报请本级人民政府启动跨行政区域联席会议处理，或者通过其他法定途径解决。\n第二十二条 酉水河流域的乡（镇）人民政府之间根据跨行政区域保护协调制度协调处理酉水河保护相关工作。协调不成的，报请上级人民政府解决。","level":1},{"name":"第四章 水资源保护与水污染防治","text":"第二十三条 酉水河流域的县级以上人民政府及相关行政主管部门应当组织酉水河沿岸集镇适时建设和改造城镇污水集中处理设施及配套管网、污泥无害化处理处置设施、危险废物集中处置设施以及固体废物的收集、运输和处置设施等生态环境保护公共设施，并保障其正常运行。\n酉水河流域的乡（镇）以上人民政府应当组织酉水河沿岸村庄、居民集中区建设垃圾分类收集、集中转运、无害化处理设施和污水处理设施。\n鼓励、支持公民、法人和其他组织投资垃圾和污水处理项目。\n第二十四条 穿越饮用水水源保护区的道路应当配备安保设施和警示标识。\n未经批准，禁止在穿越饮用水水源保护区的道路上通行装载剧毒化学品的车辆；运输其他危险化学品的车辆通行需根据危险化学品的危险特性采取相应的安全防护措施，或者配备必要的防护用品和应急救援器材，并由专人保障危险化学品运输安全。\n第二十五条 酉水河流域的各级人民政府应当采取有效措施，保护和改善渔业水域生态环境。\n从事水产养殖活动应当保护水域生态环境，排放水产养殖尾水污染物等应当符合污染物排放标准，防止污染水环境，禁止网箱养殖、投肥养殖。\n禁止违反禁渔区、禁渔期的规定从事捕捞活动。禁止渔业船舶违反禁渔区、禁渔期的规定航行、停泊。\n第二十六条 禁止新建装机容量1万千瓦以下的水力发电工程。\n酉水河流域的县级以上人民政府及相关行政主管部门应当严格管理生态流量，定期监测水力发电工程的下泄流量，防止出现脱水河段。已建成的水力发电工程项目不符合生态流量管理要求的，责令限期整改；整改后仍不符合要求的，由县级以上人民政府依法责令其停产。\n酉水河流域的县级以上人民政府生态环境主管部门应当划定水力发电工程影响区域范围，水电开发企业应当采取措施保护和改善水力发电工程影响区域内的生态环境。\n第二十七条 州、县人民政府应当对酉水河水域岸线等水生态空间实行分区管理，严格控制开发利用强度，最大程度保持岸线自然形态。沿河土地开发利用和产业布局，应与岸线分区要求相衔接，并为经济社会可持续发展预留空间。\n第二十八条 酉水河流域的县人民政府应当支持畜禽养殖场建设畜禽粪污的综合利用或者无害化处理设施。\n畜禽养殖场应当保证其畜禽粪污的综合利用或者无害化处理设施正常运行，保证粪污达标排放，防止污染水环境。\n畜禽散养密集区所在地县、乡（镇）人民政府应当组织对畜禽粪污进行分户收集、集中处理利用。县人民政府组织确定本行政区域的畜禽散养密集区。\n第二十九条 酉水河通航水域航行的船舶应当配备污水、废油和垃圾等污染物、废弃物收集设施，禁止向水体排放、弃置船舶污染物和废弃物。\n第三十条 未经行政主管部门批准，不得在酉水河河道管理范围内违法从事采砂、采矿、采石、取土、开采地下资源或者进行考古发掘等活动。\n第三十一条 禁止向河流排放、倾倒工业废渣、生活垃圾和其他废弃物。\n禁止私设暗管或者采取其他规避监管的方式向河流排放污染物。","level":1},{"name":"第五章 法律责任","text":"第三十二条 违反本条例，法律、法规有规定的，从其规定。\n第三十三条 违反本条例第二十四条第二款规定，未经批准在穿越饮用水水源保护区的道路上运输剧毒化学品的，由公安机关责令改正，并处五万元以上十万元以下的罚款；没有指定专人保障危险化学品运输安全的，由公安机关责令改正，并处一万元以上五万元以下的罚款。\n在穿越饮用水水源保护区的道路上运输危险化学品的车辆没有根据危险化学品的危险特性采取相应的安全防护措施，或者未配备必要的防护用品和应急救援器材的，由交通运输主管部门责令改正，并处五万元以上十万元以下的罚款。\n第三十四条 违反本条例第二十九条规定，对船舶未配备污水、废油和垃圾等污染物、废弃物收集设施的，由交通运输主管部门责令限期改正，处五千元以上五万元以下的罚款；逾期不改正的，责令船舶临时停航。\n第三十五条 违反本条例第三十一条第一款规定，向河流排放、倾倒工业废渣、生活垃圾和其他废弃物，由生态环境主管部门责令停止违法行为，采取治理措施消除污染，处十万元以上一百万元以下的罚款，可以责令采取限制生产、停产整治等措施；拒不采取治理措施的，可以指定有治理能力的单位代为治理，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。\n第三十六条 酉水河流域的乡（镇）以上人民政府、有关部门及其工作人员不履行条例规定的职责，由相关部门根据管理权限对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第三十七条 本条例自2017年3月1日起施行。\n第三十八条 自治州人民政府依据本条例制定实施细则。","level":1}]},{"id":"h0195","sections":[{"name":"","text":"（2018年9月30日湖北省第十三届人民代表大会常务委员会第五次会议通过 根据2022年11月25日湖北省第十三届人民代表大会常务委员会第三十四次会议《关于集中修改、废止部分省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了推进和保障中国（湖北）自由贸易试验区建设，深化改革开放，推动经济高质量发展，根据有关法律、行政法规和国务院批准的《中国（湖北）自由贸易试验区总体方案》，结合本省实际，制定本条例。\n第二条 本条例适用于中国(湖北)自由贸易试验区(以下简称自贸试验区)的建设和管理。\n自贸试验区包括武汉片区、襄阳片区、宜昌片区以及国务院批准的自贸试验区扩展区域。\n第三条 自贸试验区应当坚持改革引领、开放先导、创新驱动、产业聚集、绿色发展，建立与国际投资贸易规则相衔接的制度体系，建设战略性新兴产业和高技术产业集聚区、全面改革开放试验田、内陆对外开放新高地，在实施中部崛起战略和推进长江经济带发展中发挥示范作用。\n第四条 自贸试验区内建立鼓励改革创新、宽容失败的激励机制和容错纠错机制，完善以支持改革创新为导向的考核评价体系，激发创新活力。\n对法律法规未明确禁止的事项，自然人、法人和其他组织可以在自贸试验区开展创新活动。\n在自贸试验区进行的创新存在失误错误或者未实现预期目标，但是符合改革方向，决策程序未违反法律法规规定，且勤勉尽责、未牟取私利、未恶意串通损害公共利益或者他人合法权益的，免予追究相关单位和个人的责任。\n对在自贸试验区改革创新中作出突出贡献的单位和个人予以表彰和奖励。","level":1},{"name":"第二章 管理体制","text":"第五条 按照统筹管理、分级负责的原则，建立权责明确、部门协调、运行高效的自贸试验区管理体制。\n第六条 省人民政府、自贸试验区片区所在地的市人民政府（以下简称市人民政府）应当加强对自贸试验区建设的组织领导，将自贸试验区的发展纳入国民经济和社会发展规划，制定自贸试验区发展规划和政策措施，完善自贸试验区建设评估机制和绩效考核制度。\n省人民政府设立的自贸试验区工作领导小组（以下简称省领导小组）负责统筹协调自贸试验区建设和管理工作，研究决定自贸试验区建设的重大事项。\n市人民政府设立的自贸试验区片区工作领导小组负责统筹协调本片区建设和管理工作，组织实施各项改革试验任务。\n第七条 中国(湖北)自由贸易试验区工作办公室（以下简称省自贸办）承担省领导小组的日常工作，组织落实自贸试验区改革试点任务，协调自贸试验区有关事务，履行省领导小组赋予的其他工作职责。\n第八条 自贸试验区各片区管理机构（以下简称片区管理机构）行使市级相关管理权限，负责片区改革试验的具体事务，履行下列职责：\n（一）负责实施《中国（湖北）自由贸易试验区总体方案》，落实国家和省、市有关自贸试验区的各项政策措施；\n（二）组织实施自贸试验区各项发展规划，协调推进改革试点任务和重大投资建设项目；\n（三）负责自贸试验区内投资贸易、金融服务、科技创新、生态环境保护、产业发展、人才支撑、市场监管等有关工作；\n（四）协调海关、边防、金融、税务等部门在自贸试验区的相关事务；\n（五）依法履行知识产权保护职责，配合做好反垄断审查、国家安全审查；\n（六）建立综合统计制度和信息发布机制，及时发布自贸试验区相关信息；\n（七）履行省、市人民政府赋予的其他职责。\n第九条 省、市人民政府及其有关部门根据自贸试验区建设和改革创新需要，依法授权片区管理机构行使相关的省级、市级管理权限，推动关联、相近类别审批事项全链条授权；不能授权的，应当依法采取委托形式，法律法规明确规定不得授权或者委托的除外。\n片区管理机构根据需要，可以提出行使省级、市级管理权限的目录，依照法定程序报省、市人民政府批准后实施，并向社会公布。\n第十条 省、市人民政府有关部门应当按照各自职责，依法承担自贸试验区有关改革创新工作任务，并将其纳入年度目标考核管理。\n第十一条 海关、边防、金融、税务等部门驻自贸试验区的工作机构（以下简称驻区工作机构）依法履行相关行政管理职责，加强对自贸试验区工作的政策支持。\n片区管理机构应当与驻区工作机构建立联动互通机制，为驻区工作机构履行职责和落实国家支持自贸试验区先行先试的政策提供便利和协助。\n第十二条 自贸试验区各片区建立相对集中的行政执法和综合行政审批服务体系。集中实施行政许可、行政处罚和行政强制的具体事项，应当按照规定报批，实行清单管理，并向社会公布。\n第十三条 自贸试验区应当建立健全专家咨询机构，为自贸试验区的发展规划、重要改革措施、重大项目引进等提供专业咨询和决策支持。\n第十四条 自贸试验区各片区可以借鉴国内外先进经验，结合片区实际，采用市场化运营管理模式，由专业运营公司负责片区的规划、建设、管理和服务等工作。\n第十五条 省人民政府应当建立自贸试验区与省内国家级开发区、重点产业园区协同发展机制，实现优势互补、政策互惠、资源共享、相互促进；定期对自贸试验区改革创新经验进行总结评估，并及时复制推广。","level":1},{"name":"第三章 投资开放与贸易便利","text":"第十六条 自贸试验区对外商投资实行准入前国民待遇加负面清单管理制度。\n负面清单外的领域，按照内外资一致的原则，外商投资项目实行备案制，国务院规定对国内投资项目保留核准的除外。\n负面清单内的领域，外商投资项目实行核准制，负面清单明确禁止外商投资以及国务院规定对外商投资项目实行备案制的除外。\n外商投资企业应当依法登记注册，并通过企业登记系统以及国家企业信用信息公示系统向商务主管部门报送投资信息。\n除特殊领域外，取消对外商投资企业经营期限的特别管理要求；清理和取消外商投资企业在资质资格获取、招投标、权益保护等方面的差别化待遇，健全各类市场主体依法平等准入相关行业、领域和业务的公平竞争管理体系。\n第十七条 支持、引导自贸试验区内企业通过并购、参股、股权投资等形式开展境外投资或者设立境外研发机构。自贸试验区内企业开展境外投资，实行以备案制为主的管理方式。\n自贸试验区应当在产业合作、融资保障、知识产权保护、外汇管理、国家安全审查等方面创新机制，完善管理和服务，建立境外投资风险预警和应急处置机制。\n第十八条 自贸试验区实行国际货物贸易单一窗口服务模式，推动海关、边防、海事、税务、外汇管理等监管部门信息互换、监管互认、执法互助。\n探索推动将国际贸易单一窗口服务模式拓展至服务贸易领域，逐步将服务贸易的支付结算、资质登记、出口退税、自然人移动等纳入单一窗口管理。\n第十九条 自贸试验区海关特殊监管区域与境外之间的管理为一线管理，海关特殊监管区域与境内区外之间的管理为二线管理，按照“一线放开”“二线安全高效管住”的原则，建立与国际贸易发展需求相适应的监管模式。\n第二十条 加强商品归类和原产地预裁定等工作，探索境外货物通关部分事项由入关审查转为后续稽查，提高国际贸易通关效率。\n境外货物进入海关特殊监管区域、保税监管场所（以下统称围网区域），可以实行先入区、再报关的通关模式；在围网区域申报出境的货物，可以实行先出区、再报关的通关模式。对围网区域内保税存储货物不设存储期限；对围网区域间流转的保税货物允许自行运输。\n海关特殊监管区域实施货物状态分类监管制度，探索拓展货物状态分类监管制度的适用范围。\n第二十一条 境外货物进入自贸试验区，应当接受入境检疫;除重点敏感货物外，进入围网区域的其他货物免予检验。\n围网区域的货物出区进口前，依照企业申请，实行预检验，一次集中检验，分批核销放行。对流转于围网区域内企业之间的仓储物流货物，免予检验检疫。进出自贸试验区的保税展示商品免予检验。\n海关按照法律法规规定和国际通行规则，建立和完善第三方检测结果采信制度。推进进出口产品质量追溯体系建设，实现重点敏感产品全过程信息可追溯。\n第二十二条 自贸试验区应当按照国家规定开展税收政策试点改革，实施促进投资贸易、金融发展和人才集聚的有关税收激励政策。\n按照税制改革和国际惯例要求，在不导致利润转移和税基侵蚀的前提下，完善境外所得税收抵免的税收政策。\n自贸试验区建立便捷的税务服务体系，全面推行网上办税，提供在线纳税咨询、涉税事项办理情况查询等服务，逐步实行跨区域税务通办，实现办税便利化。\n第二十三条 自贸试验区实行内外贸一体化发展，鼓励自贸试验区内企业统筹开展国际和国内贸易，培育贸易新型业态和功能。\n自贸试验区支持新型要素交易平台、保税展示交易、境内外检测维修与再制造、跨境电子商务、外贸综合服务、技术贸易、对外文化贸易与版权贸易、中医药服务贸易和服务外包等多种贸易业态发展。\n第二十四条 自贸试验区探索完善服务贸易市场准入制度，放宽或者逐步取消限制措施，有序推进对外开放。\n自贸试验区发展仓储物流、研发设计、检验检测、维修、国际结算、分销、展览等服务贸易，重点建设数字产品与服务、维修、研发设计等特色服务出口基地。\n鼓励法律、会计、税务、知识产权、报关、认证、船舶和船员代理、公证、司法鉴定等第三方专业机构在自贸试验区开展业务。\n第二十五条 自贸试验区应当加大对跨境电子商务的扶持力度，支持跨境电商企业、跨境电商平台企业、跨境电商服务企业以及跨境电商公共机构和组织等开展跨境电商业务，在通关、税收征管和支付结算等方面依法给予便利。\n鼓励企业建设出口产品海外仓和海外运营中心。在符合相关监管政策前提下，支持跨境电商网购保税进口商品进入围网区域时先理货后报关。支持开展保税备货、境内交付模式的跨境电商保税展示业务。\n鼓励跨境电商行业开展跨国家、地区、行业之间的交流，支持跨境电商企业参加境内外展会，提高跨境电商行业的运营能力和发展水平。\n第二十六条 自贸试验区简化自贸试验区内有关单位和组织申请外国人工作许可的审批流程，按照国家规定放宽签证、居留许可有效期限，提供出入境、停居留便利。\n对接受自贸试验区内有关单位和组织邀请开展商务贸易的外籍人员，出入境管理部门应当按照国家规定给予过境免签和临时入境便利。\n第二十七条 支持自贸试验区发挥多双边经贸合作机制作用，加强与境外的国际贸易投资合作。\n推进与“一带一路”沿线国家和地区在海关、认证认可、标准计量等方面的合作与交流，开展贸易供应链安全与便利合作。","level":1},{"name":"第四章 金融服务","text":"第二十八条 支持自贸试验区扩大金融领域对外开放，增强金融服务功能，推进科技金融创新，健全金融风险防控体系。\n鼓励各类金融机构根据国家规定，在自贸试验区进行组织体系、金融产品、业务、服务和风险管理等方面的创新。\n第二十九条 自贸试验区探索建立本外币账户管理体系，开展自由贸易账户金融服务，实现分账核算管理，促进跨境贸易、投融资便利化。\n第三十条 自贸试验区探索以资本项目可兑换为重点的外汇管理改革。\n拓宽自贸试验区内企业资本项下外币资金结汇用途，企业资本项目外汇收入实行意愿结汇，境外投资者的投资收益可以按照国家规定自由转移。\n放宽跨国公司外汇资金集中运营管理准入条件，进一步简化资金池管理和经常项目外汇收支手续。\n统一中外资企业的借债标准，符合条件的中外资企业可以自主开展跨境融资。允许内保外贷项下资金调回境内使用。\n第三十一条 自贸试验区内企业经常项下和直接投资项下以及个人货物贸易与服务贸易可以直接办理跨境人民币结算业务。支持互联网支付机构开展跨境电子商务人民币结算。\n支持自贸试验区内跨国企业集团和融资租赁机构开展跨境双向人民币资金池业务。\n鼓励自贸试验区内金融机构和企业在境外发行人民币债券。支持自贸试验区银行向境内机构的境外项目发放人民币贷款。\n第三十二条 支持符合条件的发起人在自贸试验区内设立金融租赁、汽车金融、消费金融公司和企业集团财务公司等非银行金融机构。在符合法律法规及政策导向的前提下，支持外资在自贸试验区内设立金融机构，扩大外资金融机构业务范围。\n第三十三条 支持自贸试验区内的证券经营机构依法拓展境外证券投资相关业务。\n支持在自贸试验区内设立健康保险、科技保险和内河航运保险等专业保险机构，扩大出口信用保险覆盖面。完善保险市场体系，推动保险产品研发中心、再保险中心等功能型平台建设。\n第三十四条 自贸试验区统一内外资融资租赁准入标准、审批流程和事中事后监管，支持境内外投资者在自贸试验区设立融资租赁企业。\n支持开展跨境融资租赁服务，鼓励企业采用融资租赁方式开拓国际市场和引进国外先进设备，扩大高端设备进口。\n第三十五条 支持自贸试验区内银行业金融机构开展信贷资产证券化业务；鼓励金融机构开展动产融资业务，利用动产融资统一登记平台，服务中小企业发展。\n第三十六条 支持自贸试验区培育科技金融组织体系，创新科技金融产品和服务模式，完善股权、技术等资本和要素交易市场，建立健全科技金融服务风险分担机制。\n拓宽科技企业直接融资渠道，建立投融资结合的综合化金融服务体系。支持自贸试验区内金融机构开展投贷联动、供应链金融、知识产权质押融资、知识产权证券化等产品创新。\n符合条件的外资机构可以在自贸试验区发起管理人民币股权投资和创业投资基金，鼓励境外创业投资机构和风险投资机构在自贸试验区开展业务。\n支持自贸试验区内金融机构发展知识产权保险、信用保险、小额贷款保证保险等科技保险业务。\n第三十七条 自贸试验区应当加强金融监管协作，配合金融监管部门完善金融风险监测和评估机制，以大数据监管为依托建立与金融业务发展相适应的风险防范机制。\n在自贸试验区开展业务的金融机构和特定非金融机构应当按照规定，向金融监管部门报送相关信息，履行反洗钱、反恐怖融资和反逃税等义务，配合金融监管部门监管跨境异常资金流动，保护金融消费者和投资者权益。","level":1},{"name":"第五章 创新驱动发展和服务长江经济带建设","text":"第三十八条 自贸试验区全面推进产业技术创新、科技成果转移转化、国际创新合作等领域改革，完善以企业为主体的技术创新体系。\n第三十九条 自贸试验区建立知识产权综合管理体制和知识产权公共服务体系，建立专利导航产业发展机制，加强产业链关键环节的专利预警和导航，引导重大项目、重点企业加强知识产权储备与战略布局。\n引导企业开展知识产权海外布局，鼓励企业申请境外专利、商标注册及版权输出，对在境外授权的发明专利、注册商标及版权登记作品给予一定奖励。\n鼓励自贸试验区与高校、科研院所合作共建知识产权公共服务平台和创新支撑平台。\n第四十条 支持自贸试验区深化人才发展体制机制改革，探索构建具有国际竞争力的人才制度体系。\n自贸试验区设立专项资金，对引进高层次人才、团队及其创新项目予以支持。对持有外国人永久居留证的外籍高层次人才在自贸试验区内创办科技企业等创新活动，给予其与中国公民同等的待遇。\n自贸试验区应当制定高层次人才和技能型人才的引进、培养、服务、激励等相关管理办法，为人才签证、停居留、执业、创新创业、住房、子女入学、就医等提供便利。\n第四十一条 自贸试验区推进跨国教育和人才培养合作，支持境外知名大学、科研教育机构与中方合作在自贸试验区内创办人才培养机构，鼓励中外教育机构共建学校和人才实习实训基地。\n第四十二条 自贸试验区制定措施，吸引跨国公司在自贸试验区内设立总部、研发中心，支持在自贸试验区内建设国际化创新创业平台，重点吸引国际知名孵化器、创业投资机构、高端创新创业人才集聚。\n鼓励自贸试验区内的企业、高校院所在境外设立研发机构，参与国际科技项目合作。探索通过并购、技术转移、合作参股等多种方式在境外建立孵化基地、产业园和创新平台等。\n第四十三条 自贸试验区应当制定产业发展战略规划，完善信息技术、新能源、新材料、生命健康、智能制造、大数据、高技术服务业等核心产业上下游产业链，构建人才、研发、金融、营销、物流、信息服务等配套的产业生态环境。\n支持自贸试验区依托国家重点平台布局实施重大标志性项目，培育、打造中部地区和长江经济带世界级产业集群。\n第四十四条 在自贸试验区内建立生态环境硬约束机制，明确环境质量要求，促进自贸试验区绿色产业集聚发展。\n第四十五条 推动自贸试验区物流行业发展，推进多式联运的规划和建设，完善技术标准和服务规范。\n引进国际物流企业在自贸试验区内建立总部、营运中心，支持在自贸试验区内设立国际邮件互换局和交换站。\n支持中部、长江经济带其他地区在自贸试验区建设专属物流园，完善与中部、长江经济带其他地区集疏运体系和保税物流网络。\n第四十六条 推进中欧班列在自贸试验区的发展，优化、拓展班列线路。发挥中欧班列国际运输功能，加快布局境外营销服务网络，在境外设立代表处、办事处等。\n第四十七条 依托自贸试验区发展长江航运业务，培育航运保险、海事仲裁、船舶检测认证、船舶经纪等高端航运服务业态。\n放宽船舶融资租赁登记地选择，简化换证程序。逐步开放中国籍国际航行船舶入级检验，允许特定条件下租用外籍船舶从事临时运输。扩大内外贸同船运输、国轮捎带运输适用范围。\n第四十八条 自贸试验区加强与沿海沿江港口、“一带一路”沿线港口合作，建立跨区域港口联盟、港航联盟，增强江海联运服务功能。\n第四十九条 支持自贸试验区与中部、长江经济带其他地区建立协同发展机制，推进传统产业的跨区域整合、技术改造和转型升级，支持承接符合环保等要求的先进产业、国内外知名企业生产基地等向自贸试验区内转移，推动中部地区和长江经济带产业合理布局。\n第五十条 增强口岸服务辐射功能，推进自贸试验区与中部、长江经济带其他地区口岸互联互通，探索开展货物通关、贸易统计、经认证的经营者互认、检验检测认证等方面合作，打造中部和长江经济带国际贸易大通道。\n第五十一条 构建区域商品交易集散中心、信息中心和价格形成中心，支持中部地区产权交易市场、技术交易市场、排污权交易市场和碳排放权交易市场在自贸试验区内开展业务。","level":1},{"name":"第六章 综合管理与服务","text":"第五十二条 自贸试验区应当创新行政管理方式，减少行政审批事项，加强事中事后监管，推动形成行政监管、行业自律、社会监督、公众参与的综合监管体系。\n第五十三条 省自贸办应当参照国际通行的营商环境评价指标，制定自贸试验区营商环境科学评价体系，委托第三方机构开展自贸试验区企业开办、施工许可、产权登记、信贷获取、投资者保护、纳税、破产清算等方面的评估，定期编制、发布自贸试验区营商环境报告。\n第五十四条 自贸试验区推进证照分离、多证合一、一照一码等商事制度改革，简化企业登记程序，实现企业登记全程电子化。\n实行企业名称自主申报制度，除涉及前置审批事项或者企业名称核准与企业设立登记不在同一机关外，企业名称不再实行预先核准。\n支持自贸试验区放宽企业住所登记条件，按照分类型分业态，推行住所信息申报制、一址多照、一照多址、集群注册、托管登记等便利化措施。\n第五十五条 片区管理机构、驻区工作机构和有关部门应当明确职责边界，依法公布行政权力清单、责任清单和权力运行流程图。\n第五十六条 片区管理机构应当创新审批服务模式，推进审批服务标准化，在企业设立、经营许可、人才引进等方面实行一口受理、集中审批、限时办结、跟踪服务等服务制度。\n第五十七条 自贸试验区应当按照公开透明、便捷高效和信息共享的原则，推进电子政务建设，整合优化网上办事系统及业务流程，实现政务服务一网通办。\n自贸试验区应当为自贸试验区内企业定制专属网页，为企业提供政务信息个性化推送服务。\n第五十八条 自贸试验区推行行政许可告知承诺制度。许可部门将法定许可条件告知申请人，申请人承诺符合法定许可条件的，许可部门可以依照承诺作出许可决定，但涉及公共安全、人身财产安全、金融安全、生态环境保护等国家规定不适用告知承诺制的事项除外。\n许可部门应当在许可决定作出后，对被许可人是否符合法定许可条件进行检查；经检查不符合法定许可条件的，责令限期整改；整改后仍不符合条件的，撤销行政许可。\n告知承诺制许可事项的具体范围和程序，由省人民政府依法确定并向社会发布。\n第五十九条 自贸试验区应当依法将市场主体的信用信息纳入省社会信用信息平台，实行守信联合激励和失信联合惩戒。\n鼓励和支持信用服务机构开发和创新信用产品，扩大信用服务领域和范围，参与国际合作，推动信用调查、信用评估、信用担保、信用保险等信用产品和服务在行政管理、公共服务、市场交易、生产生活中的应用。\n第六十条 自贸试验区创新环境保护管理制度，实施企业环保承诺制，探索分类管理、同类简化、试行备案的建设项目环评管理模式，建立环境保护联防联控协作机制。\n第六十一条 自贸试验区应当建立涉及外商投资的国家安全审查工作机制，配合国家有关部门开展自贸试验区内外商投资国家安全审查工作。\n当事人应当配合国家安全审查工作，提供必要的材料和信息。\n第六十二条 自贸试验区应当建立反垄断审查工作机制，配合国家有关部门，对企业涉及经营者集中、垄断协议、滥用市场支配地位以及滥用行政权力排除、限制竞争等行为，依法开展调查和执法工作。\n第六十三条 自贸试验区应当完善公众参与制度，鼓励和支持企业、利益群体、相关组织和公众对自贸试验区建设提出意见建议，参与试点政策评估和市场监督。\n行业组织应当根据自贸试验区建设需要，制定并组织实施行业规划、服务标准、行业公约、职业道德等制度，规范会员行为，发挥行业自律的引导作用。","level":1},{"name":"第七章 法治环境","text":"第六十四条 自贸试验区改革创新需要暂时调整或者停止适用有关法律、行政法规、部门规章的部分规定的，有关部门应当及时提出意见，依照法定程序报请在自贸试验区先行先试。\n自贸试验区改革创新需要暂时调整或者停止适用有关地方性法规、政府规章或者规范性文件的，由制定机关按照法定程序作出决定。\n第六十五条 自贸试验区应当加强知识产权保护工作，建立统一的知识产权执法体制和快速协同保护机制，完善跨区域知识产权协同保护体系，健全涉外知识产权执法协作机制。\n第六十六条 自贸试验区完善多元化、国际化商事争议解决机制，加强行业性、专业性调解组织的建设，探索建立与境外商事调解机构的合作机制，协同解决跨境纠纷。\n行业协会、商会以及调解组织等可以参与自贸试验区商事纠纷调解，发挥争议解决作用。\n第六十七条 鼓励商事纠纷当事人遵循意思自治原则通过仲裁化解商事纠纷，当事人可以依照法律或者国家有关规定，协议选择仲裁规则、适用法律、审理方式和仲裁庭的组成方式等。\n仲裁机构应当依据中国缔结的国际条约、法律法规并借鉴国际商事仲裁惯例，适应自贸试验区特点，完善仲裁规则，提高商事仲裁的国际化程度，提供独立、公正、专业、高效的仲裁服务。\n第六十八条 自贸试验区培育和发展专业化、国际化的律师、仲裁、调解、公证、鉴定等法律服务机构，鼓励境内外法律服务机构和人才在自贸试验区开展法律专业服务。","level":1},{"name":"第八章 附则","text":"第六十九条 本条例自2019年1月1日起施行。","level":1}]},{"id":"h0196","sections":[{"name":"","text":"（2018年11月19日湖北省第十三届人民代表大会常务委员会第六次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了加强公共文化服务体系建设，保障人民群众基本文化权益，传承中华优秀传统文化，弘扬社会主义核心价值观，增强文化自信，促进文化繁荣兴盛，根据《中华人民共和国公共文化服务保障法》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内的公共文化服务及其保障活动。\n本条例所称公共文化服务，是指由政府主导、社会力量参与，以满足公民基本文化需求为主要目的而提供的公共文化设施、文化产品、文化活动以及其他相关服务。\n本条例所称公共文化设施，是指用于提供公共文化服务的建筑物、场地和设备。\n第三条 公共文化服务应当坚持以人民为中心，面向基层、面向群众，体现公益性、基本性、均等性、便利性。\n第四条 县级以上人民政府统一领导本行政区域内的公共文化服务工作，应当将公共文化服务纳入本级国民经济和社会发展规划，加强公共文化设施建设、产品供给和活动组织，完善公共文化服务体系，提高公共文化服务效能。\n县级以上人民政府文化、新闻出版、广播电视、电影、体育等主管部门根据其职责负责本行政区域内的公共文化服务工作；其他有关部门在各自职责范围内做好公共文化服务相关工作。\n工会、共青团、妇联等人民团体和社会组织应当结合工作实际，做好公共文化服务相关工作。\n第五条 县级以上人民政府应当建立健全公共文化服务综合协调机制，加强跨部门、跨行业、跨区域公共文化服务资源的整合，统筹推进公共文化服务重大工程实施，创新公共文化服务管理运行机制，实现公共文化服务网络互联互通、资源共建共享。文化主管部门负责综合协调具体工作。\n第六条 乡镇人民政府、街道办事处负责乡镇、街道综合文化服务中心和其他公共文化设施的日常管理，组织开展群众性文化体育活动，做好公共文化服务工作。\n村（居）民委员会应当根据村（居）民的需求开展群众性文化体育活动，协助当地人民政府有关部门开展公共文化服务工作。\n第七条 县级以上人民政府应当加大对农村地区和革命老区、民族地区、贫困地区公共文化服务工作的扶持，加大对基层公共文化设施建设和服务的投入，促进公共文化服务均衡协调发展。\n第八条 各级人民政府应当根据未成年人、老年人、妇女、残疾人和流动人口等群体的特点与需求，提供相应的公共文化服务。\n第九条 县级以上人民政府应当建立公共文化服务绩效评估、监督检查机制，将公共文化服务工作纳入政府目标责任考核内容，作为评价地区发展水平、发展质量和领导干部工作实绩的重要内容。\n第十条 鼓励、支持公民、法人和其他组织，向公众提供公共文化设施和产品，开展公共文化活动和服务。\n对在公共文化服务中作出突出贡献的公民、法人和其他组织，给予表彰和奖励。","level":1},{"name":"第二章 公共文化设施","text":"第十一条 省人民政府应当根据国家有关规定，结合经济社会发展水平和公共文化服务事业发展需要，制定全省公共文化设施建设专项规划。\n各级人民政府按照公共文化设施建设专项规划，结合当地实际需求和文化特色，建设公共文化设施。\n公共文化设施的种类、数量、规模、选址和布局，应当优化配置，形成场馆服务、流动服务和数字服务相结合，覆盖全面、便利可及的公共文化设施网络，满足人民群众基本文化需求。\n公共文化设施的设计和建设，应当安全实用、科学美观、环保节约，并符合无障碍设施工程建设等国家相关建设标准。\n第十二条 各级人民政府应当结合实际，在人员流动量较大的公共场所、务工人员较为集中的区域以及留守妇女儿童较为集中的农村地区，设置配备公共阅览设施、流动图书设施、公共数字文化服务点、体育健身器材等必要的公共文化设施设备，采取多种形式，提供便利的公共文化服务。\n第十三条 县级以上人民政府自然资源主管部门应当将公共文化设施建设用地纳入土地利用总体规划和城乡规划。\n任何单位和个人不得侵占公共文化设施建设用地或者擅自改变其用途。因特殊情况需要调整公共文化设施建设用地的，应当先确定公共文化设施建设用地，再进行调整。调整后的公共文化设施建设用地不得少于原面积。\n第十四条 任何单位和个人不得擅自拆除公共文化设施，不得擅自改变公共文化设施的功能、用途或者妨碍其正常运行，不得侵占、挤占、挪用公共文化设施，不得将公共文化设施用于与公共文化服务无关的商业经营活动。\n因公共利益需要，确需拆除公共文化设施或者改变其功能、用途的，应当按照不低于原有建筑面积和配置标准的要求进行重建或者改建。\n新建公共文化设施后，原有场馆能够继续发挥作用的，应当作为公共文化设施予以保留并对公众开放。\n第十五条 各级人民政府应当加强乡镇（街道）、村（社区)综合文化服务中心建设，整合文化宣传、科学普及、艺术普及、普法教育、体育健身等功能，推动基层公共文化设施的统一管理和综合利用，保障其发挥服务效能。\n村（居）民委员会负责村（社区）综合文化服务中心和其他公共文化设施的日常管理。\n第十六条 新建、改建和扩建居民住宅区，其建设、设计、施工单位应当按照国家和省有关居住区规划设计规范标准，将建设配套的公共文化设施纳入建设项目规划，与居民住宅区的主体工程同时设计、同时施工、同时投入使用。任何单位和个人不得擅自改变公共文化设施建设项目及其功能、用途。\n县级以上人民政府建设规划主管部门审查居民住宅区工程建设设计方案时，应当同步审查该居民住宅区公共文化设施的建设设计方案。\n第十七条 公共文化设施管理单位应当按照国家、省有关规定建立健全管理制度和服务规范，配置和更新必需的服务内容和设备，加强公共文化设施经常性维护管理，保障公共文化设施的正常使用和安全运转。\n公共文化设施管理单位应当开展公共文化设施及公众活动的安全评价，依法配备安全保护设备和人员，保障公共文化设施和公众活动安全。\n第十八条 公共文化设施管理单位应当编制公共文化服务情况年度报告，并向社会公开。\n县级以上人民政府及相关部门应当加强对公共文化设施管理单位的监督管理，建立有公众参与的公共文化设施使用效能考核评价制度，定期公布考评结果。公共文化设施管理单位根据考评结果改进工作，提高公共文化服务质量和水平。\n第十九条 鼓励和支持公民、法人和其他组织兴建、捐建或者与政府部门合作建设公共文化设施，依法参与公共文化设施的运营和管理。","level":1},{"name":"第三章 公共文化产品和活动","text":"第二十条 县级以上人民政府应当加强公共文化产品创作生产规划，支持和引导优秀公共文化产品的创作生产，加强优质公共文化产品的供给，弘扬社会主义核心价值观。\n县级以上人民政府应当积极推动优秀荆楚文化的创造性转化、创新性发展，结合本地特点，支持具有荆楚特色的文化产品生产和文化活动开展。\n县级以上人民政府应当依托国家和省级非物质文化遗产名录项目，创建具有本地特色的文化产品和活动品牌。\n第二十一条 县级以上人民政府及文化、新闻出版、广播电视、电影等主管部门应当发挥文艺创作、生产、演出单位的骨干作用，引导、扶持民间文化团体健康发展，丰富公共文化产品供给。\n鼓励公共文化机构和文化企业挖掘特色资源，加强文化创意产品研发，创新文化产品和服务内容。\n鼓励公民、法人和其他组织提供公共文化产品，满足多样化、多层次的文化需求。\n第二十二条 各级人民政府应当建立健全公共文化产品遴选、采购、推介、供给机制，构建各类优秀文化产品进入公共文化服务平台、载体的便捷通道。\n第二十三条 各级人民政府应当积极组织开展全民阅读、全民普法、全民健身、全民科普、全民艺术普及和优秀传统文化传承及家风培育活动，实施基层特色文化品牌建设项目。\n第二十四条 县级以上人民政府文化、体育等主管部门应当结合实际，在技术、场地、资金等方面对群众性文化体育活动给予支持和帮助，引导群众性文化体育活动健康、规范、有序开展。\n开展群众性文化体育活动，应当自觉维护社会公共秩序，遵守活动场所管理制度，不得影响他人的正常工作、生活和休息。\n第二十五条 各级人民政府应当加强农村地区图书、报刊、戏曲、电影、广播电视节目、网络信息内容、体育健身活动等公共文化产品的生产和供给，培养乡土文化人才、文化能人，支持开展农村群众性文化体育活动和节日民俗活动，重视乡土文化产品发掘，丰富农村公共文化服务内容。\n第二十六条 各级人民政府应当结合革命老区、民族地区的文化特点和发展实际，开发红色文化和民族文化产品，组织有地区特色的公共文化活动，打造有影响力的公共文化品牌。\n积极扶助贫困地区的公共文化建设，加强贫困地区公共文化产品供给和文化活动组织。鼓励、支持文化结对帮扶。\n第二十七条 广播、电视、报刊、网络等新闻媒体应当对重点公共文化产品创作生产和重大公共文化活动品牌进行策划报道、动态跟踪、专题访谈和热点评论，加强优秀公共文化产品和活动的传播推广。","level":1},{"name":"第四章 公共文化服务","text":"第二十八条 各级人民政府及有关部门应当充分利用公共文化设施，促进优秀公共文化产品的创作生产和供给传播，支持优秀公共文化活动的组织开展，创新公共文化服务方式，提高公共文化服务质量。\n第二十九条 公共文化设施应当根据其功能、特点，按照国家和省有关规定，向公众免费或者优惠开放。开放时间应当与公众工作时间、学习时间适当错开，公共假期和学生寒暑假期间应当适当延长开放时间。\n公共文化设施管理单位应当建立服务公示制度，向社会公开服务项目、服务内容、服务标准、开放时间等服务信息。\n第三十条 鼓励和支持机关、学校和其他企事业单位的文化体育设施向公众开放。机关、学校和其他企事业单位在确保正常工作、教学、生产秩序的前提下，确定并公布向公众开放的文化体育设施、场所和时间。\n第三十一条 各级人民政府应当组织实施农村公共文化服务惠民工程，为农村居民提供免费的书报阅读、广播播送、影视观赏、戏曲表演、互联网上网等公共文化服务。\n县级人民政府应当统筹县、乡、村三级公共文化资源，组织开展面向农村居民的公共文化服务和文明实践活动；乡镇人民政府、村民委员会结合当地实际，依托综合文化服务中心组织开展经常性、多样化的公共文化服务和活动，传播文明理念、培育文明乡风。\n第三十二条 县级人民政府应当按照国家和省有关规定，组织本级图书馆、文化馆在乡镇、村综合文化服务中心建立服务点。\n各级图书馆、文化馆等单位积极推动在基层、其他行业和部门建立服务点，扩大服务范围。\n第三十三条 各级人民政府及文化、新闻出版、广播电视、电影等主管部门应当组织公共文化机构和文化企业在农村、社区、校园、企业、军营等开展经常性的公共文化流动服务，并根据实际情况建立流动服务点，促进优质公共文化资源向基层流动。\n县级以上人民政府应当根据实际需要，为公共文化机构配备流动文化设施，并及时更换。\n第三十四条 省人民政府文化主管部门应当统筹规划公共数字文化建设，建立公共文化服务数字信息网络平台，建设公共文化信息资源库，构建标准统一、互联互通的公共数字文化服务网络。\n市县两级人民政府应当将公共数字文化建设纳入本地区信息化建设规划，加大公共数字文化资源开发利用力度，推动利用宽带互联网、移动互联网、广播电视网和卫星网络提供公共文化服务。\n第三十五条 公共文化设施管理单位应当通过信息化、数字化等技术手段，增强文化信息资源的存储、传输、供给和远程服务等能力。\n网络文化运营商应当提高网络文化产品和服务供给能力，促进优秀传统文化和当代文化精品网络传播，推动网络文化服务健康发展。\n第三十六条 各级人民政府及文化、体育等主管部门可以采取政府购买、项目补贴或者奖励等方式鼓励和支持社会力量提供公共文化服务，推动经营性文化设施、文化企业提供免费或者优惠的公益性文化服务。\n各级人民政府应当建立健全政府向社会力量购买公共文化服务的机制，制定本地区政府向社会力量购买公共文化服务的指导性目录或者具体购买目录，并及时向社会公布。\n第三十七条 鼓励和支持公民、法人和其他组织通过资助项目、赞助活动，提供设施、产品和服务等方式参与公共文化服务。\n经县级以上人民政府批准，对接受捐赠的公共文化设施和公共文化活动可以依法冠名。\n第三十八条 各级人民政府应当建立公共文化志愿服务体系，支持公共文化志愿服务活动。\n文化主管部门应当会同有关部门建立和完善公共文化服务志愿者注册招募、服务记录、管理评价和激励保障机制，加强指导和培训，实现志愿服务与政府服务、市场服务相衔接。\n公共文化设施管理单位应当建立公共文化服务志愿者队伍，组织开展公共文化志愿服务活动。","level":1},{"name":"第五章 保障措施","text":"第三十九条 省人民政府根据国家基本公共文化服务指导标准，制定公布本省基本公共文化服务实施标准，确定公共文化服务项目和内容、设施和设备、人员配备等指标，并根据经济社会发展和人民群众需求进行动态调整。\n市县两级人民政府根据国家基本公共文化服务指导标准和省基本公共文化服务实施标准，制定公布本行政区域的公共文化服务目录并组织实施。公共文化服务目录根据经济社会发展和人民群众需求进行动态调整，有条件的地区可以高于省基本公共文化服务实施标准。\n第四十条 县级以上人民政府应当将公共文化服务经费纳入本级财政预算，建立与公共文化服务发展需求相适应的财政投入增长机制，保证本行政区域公共文化服务需要。\n县级以上人民政府可以根据当地经济社会发展水平和公共文化服务发展需求，设立公共文化服务专项资金，主要用于公共文化设施设备配置维护更新、实施公共文化民生工程、人才队伍培养、群众性文化体育活动开展、引导社会力量参与公共文化服务等。\n第四十一条 县级以上人民政府应当建立健全公共文化服务资金使用的监督和统计公告制度，加强绩效考评，确保资金用于公共文化服务。任何单位和个人不得侵占、挪用公共文化服务资金。\n审计机关应当依法加强对公共文化服务资金的审计监督。\n第四十二条 县级以上人民政府应当按照国家和省有关规定，根据所承担的职能、任务及所服务的人口规模，采取县聘乡用、派出制等形式，配备乡镇（街道）综合文化服务中心工作人员；在村（社区）综合文化服务中心设立由政府购买的公益文化岗位负责公共文化服务工作。\n第四十三条 县级以上人民政府及文化、人力资源社会保障等主管部门，应当建立公共文化服务人才引进、培养和激励机制，通过专业培训或者委托培养、招聘选拔、兼职客座、项目合作、挂职交流等方式，加强公共文化服务人才队伍建设。\n加强民营文化企业、民间文化团体的人才队伍建设，对其在学习培训、职称评定、项目申报、表彰奖励等方面与国有文化单位实行同一标准。","level":1},{"name":"第六章 法律责任","text":"第四十四条 违反本条例，法律、法规有规定的，从其规定。\n第四十五条 违反本条例规定，国家机关及其工作人员未履行公共文化服务保障职责的，由其上级机关或者主管部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。\n第四十六条 违反本条例规定，公共文化设施管理单位有下列行为之一的，由其主管部门责令限期改正;情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分:\n（一）未按照规定向公众开放的;\n（二）未向社会公开服务项目、服务内容、服务标准、开放时间等服务信息的；\n（三）未按照规定建立管理制度和服务规范的；\n（四）因管理不善造成损失的；\n（五）未编制公共文化服务情况年度报告，并向社会公开的。\n第四十七条 违反本条例规定，侵占、挤占、挪用、擅自拆除公共文化设施，或者拆除公共文化设施未按照规定重建的，由其上级机关或者主管部门责令限期改正;情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。\n第四十八条 违反本条例规定，新建、改建、扩建居民住宅区，未按照规定规划和建设配套公共文化设施的，由建设规划主管部门责令限期改正；情节严重的，由建设规划主管部门依法处理。\n违反本条例规定，新建、改建、扩建居民住宅区，建设规划主管部门未按照规定同步审查该居民住宅区公共文化设施建设设计方案的，由其上级机关或者主管部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。\n第四十九条 违反本条例规定，侵占、挪用公共文化服务资金的，由其上级机关或者主管部门责令限期改正;情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。","level":1},{"name":"第七章 附则","text":"第五十条 本条例自2019年2月1日起施行。","level":1}]},{"id":"h0197","sections":[{"name":"","text":"（2018年11月19日湖北省第十三届人民代表大会常务委员会第六次会议通过）\n为了贯彻落实党的十九大和十九届二中、三中全会精神，按照《全国人民代表大会常务委员会关于国务院机构改革涉及法律规定的行政机关职责调整问题的决定》和《湖北省机构改革方案》确定的原则，平稳有序调整我省省本级地方性法规规定的行政机关职责和工作，确保行政机关依法履行职责、开展工作，推进我省国家机构设置和职能配置优化协同高效，现就省人民政府机构改革涉及省本级地方性法规规定的行政机关职责调整问题作出如下决定：\n一、省本级地方性法规规定的行政机关职责和工作，《湖北省机构改革方案》确定由组建后的行政机关或者划入职责的行政机关承担的，在有关地方性法规规定尚未修改之前，调整适用有关地方性法规规定，由组建后的行政机关或者划入职责的行政机关承担；相关职责尚未调整到位之前，由原承担该职责和工作的行政机关继续承担。\n我省市县两级地方行政机关承担省本级地方性法规规定的职责和工作需要进行调整的，按照上述原则执行。\n二、省本级地方性法规规定上级行政机关对下级行政机关负有管理监督指导等职责的，上级行政机关职责已调整到位、下级行政机关职责尚未调整到位的，由《湖北省机构改革方案》确定承担该职责的上级行政机关履行管理监督指导等职责。\n三、根据法律和行政法规制定、修改情况以及实施《湖北省机构改革方案》要求，需要制定、修改省本级地方性法规，或者需要由省人民代表大会常务委员会作出相关决定的，省人民政府应当及时提出议案，依照法定程序提请审议。\n四、省人民政府及其有关部门应当精心组织，周密部署，确保行政机关履行法定职责、开展工作的连续性、稳定性、有效性，特别是做好涉及民生、应急、安全生产等重点领域工作。\n五、本决定自2018年11月20日起施行。","level":0}]},{"id":"h0198","sections":[{"name":"","text":"（2019年3月29日湖北省第十三届人民代表大会\n常务委员会第八次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了预防和制止家庭暴力，保护家庭成员的合法权益，维护平等、和睦、文明的家庭关系，弘扬和践行社会主义核心价值观，促进家庭和谐、社会稳定，根据《中华人民共和国反家庭暴力法》等法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内预防、处置家庭暴力及相关工作。\n本条例所称家庭暴力，是指家庭成员之间以殴打、捆绑、残害、限制人身自由以及经常性谩骂、恐吓等方式,或者利用其他手段实施的身体、精神等侵害行为。\n第三条 反家庭暴力工作坚持党的领导，遵循预防为主，教育、矫治与惩处相结合原则，实行社会共治。\n反家庭暴力工作应当尊重受害人真实意愿，保护当事人隐私，不得泄露涉及家庭暴力案件举报人、报案人的信息。\n未成年人、老年人、残疾人、孕期和哺乳期的妇女、重病患者遭受家庭暴力的，应当给予特殊保护。\n第四条 县级以上人民政府应当加强对反家庭暴力工作的组织领导，建立健全反家庭暴力工作体系，将反家庭暴力工作纳入精神文明建设和基层社会治理工作内容，所需经费纳入同级财政预算。\n乡（镇）人民政府、街道办事处应当做好辖区内家庭暴力的预防、处置、救助等相关工作。\n村（居）民委员会应当协助做好反家庭暴力相关工作。\n第五条 县级以上人民政府负责妇女儿童工作的机构具体承担反家庭暴力的组织、协调、指导、监督工作,履行下列职责:\n（一）组织开展反家庭暴力法律法规宣传和实施工作；\n（二）定期组织召开联席会议，研究和解决反家庭暴力工作中的重大问题；\n（三）协调、督促相关单位依法履行职责,推动反家庭暴力多部门合作；\n（四）支持社会工作服务机构、志愿服务组织等社会组织开展心理健康咨询、家庭关系指导、家庭暴力预防知识教育等服务；\n（五）对在反家庭暴力工作中作出显著成绩的组织和个人给予表彰、奖励；\n（六）开展反家庭暴力的其他相关工作。\n县级以上人民政府负责妇女儿童工作的机构在同级妇女联合会设立的办事机构，负责日常工作。\n第六条 公安、教育、民政、卫生健康、司法行政等相关部门和人民法院、人民检察院以及人民团体、社会组织，应当按照各自职责，共同做好反家庭暴力工作。\n第七条 反家庭暴力是全社会的共同责任。\n禁止任何形式的家庭暴力。任何单位和个人有权对正在发生的家庭暴力予以劝阻、制止、举报。","level":1},{"name":"第二章 家庭暴力的预防","text":"第八条 各级人民政府应当将反家庭暴力相关法律法规宣传纳入普法工作规划，组织开展反家庭暴力宣传教育。\n各级妇女联合会应当开展反家庭暴力法治宣传和家庭美德教育活动，维护妇女儿童合法权益。工会、共产主义青年团、残疾人联合会应当在各自工作范围内，开展反家庭暴力和家庭美德宣传教育。\n广播、电视、报刊、网络等媒体应当加强反家庭暴力的公益宣传和教育引导，强化对家庭暴力的舆论监督。\n在国家规定有关妇女、儿童、老年人、残疾人等的节日，应当集中开展家庭美德和反家庭暴力宣传教育。\n第九条 县级以上人民政府以及公安、教育、民政、卫生健康、司法行政等相关部门和人民法院、人民检察院、人民团体、社会组织应当将预防和制止家庭暴力相关知识和技能纳入业务培训，提高相关工作人员预防、处置家庭暴力问题的能力。\n第十条 幼儿园、学校等教育机构应当将反家庭暴力教育纳入法治教育、安全教育的重要内容，提高儿童、学生的反家庭暴力意识和自我保护能力，并通过家校共建活动，向其父母或者其他监护人普及反家庭暴力法律和家庭教育知识。\n第十一条 民政部门应当指导婚姻登记机关将家庭美德教育和反家庭暴力宣传纳入婚前教育内容，提供婚姻家庭辅导服务，预防家庭矛盾和纠纷。\n第十二条 司法行政部门应当加强基层公共法律服务，重点面向农村开展法律咨询、法律援助等工作，预防家庭暴力的发生。\n司法行政部门应当推进婚姻家庭纠纷人民调解组织建设，加强人民调解员的专业培训，指导人民调解组织加大对涉及家庭矛盾纠纷的调解工作力度。\n第十三条 公安机关、司法行政部门、人民法院、人民检察院应当加强家庭暴力典型案例的收集、整理和发布工作。执法、司法、法律服务人员应当结合具体案件向家庭暴力加害人、受害人和公众释法说理，普及反家庭暴力法律知识。\n第十四条 县级以上人民政府负责妇女儿童工作的机构应当组织协调政府相关部门、乡镇人民政府、街道办事处、村（居）民委员会、社会组织等建立反家庭暴力联动机制，开展家庭暴力风险评估，发现家庭暴力隐患的，及时预防和处理。\n第十五条 乡镇人民政府、街道办事处应当指导村（居）民委员会将预防家庭暴力纳入村（居）民自治章程、村规民约，作为基层自治的重要内容，推动社区开展互助服务和志愿服务活动。\n村（居）民委员会应当加强家庭暴力防范宣传教育，开展文明家庭创建活动，弘扬文明新风，增强村（居）民的法治观念和道德素养。\n第十六条 用人单位应当将反家庭暴力纳入员工行为规范，及时做好本单位人员家庭矛盾的调解、化解工作；对家庭暴力加害人给予批评教育，责令改正，并视情节轻重给予相应处理。","level":1},{"name":"第三章 家庭暴力的处置","text":"第十七条 家庭暴力受害人及其法定代理人、近亲属可以向加害人或者受害人所在单位、村（居）民委员会、妇女联合会等单位投诉、反映或者求助。\n有关单位接到家庭暴力的投诉、反映或者求助后，应当开展下列工作：\n（一）劝阻和制止家庭暴力行为，对加害人进行批评教育和法治教育；\n（二）根据工作职责，提供家庭纠纷调解、婚姻家庭关系调适、心理辅导等服务；\n（三）根据受害人实际情况，积极协助报案、医疗救治、伤情鉴定、庇护救助、法律援助等，及时转介到有关部门或者机构。\n县级以上人民政府负责妇女儿童工作的机构应当建立家庭暴力投诉、处理机制，健全维权工作网络，对涉及多个单位职责范围的，协调相关单位共同处理。\n第十八条 家庭暴力受害人及其法定代理人、近亲属可以向公安机关报案或者依法向人民法院起诉。\n幼儿园、学校、村（居）民委员会、医疗机构、救助管理机构、社会工作服务机构、福利机构及其工作人员在工作中发现无民事行为能力人、限制民事行为能力人遭受或者疑似遭受家庭暴力的，应当及时向公安机关报案，并提供保护和帮助。\n第十九条 公安机关应当建立健全家庭暴力案件处理机制，将家庭暴力警情纳入110接处警平台，接到家庭暴力报案后应当及时出警，并做好下列处置工作：\n（一）立即制止正在发生的家庭暴力行为，控制加害人；\n（二）及时询问加害人、受害人和目击证人，固定有关证据，制作出警记录；\n（三）受害人需要立即就医的，应当积极协助联系医疗机构组织救治、委托伤情鉴定；\n（四）无民事行为能力人、限制民事行为能力人以及孕期和哺乳期的妇女、重病患者因家庭暴力身体受到严重伤害，面临人身安全威胁或者处于无人照料等危险状态的，应当通知并协助民政部门将其安置到临时庇护场所、救助管理机构或者福利机构。\n第二十条 对家庭暴力案件情节较轻，依法不给予治安管理处罚的，公安机关对加害人可以给予批评教育或者出具告诫书；对具有下列情形之一的，应当出具告诫书：\n（一）未取得受害人谅解的；\n（二）对未成年人、老年人、残疾人、孕期和哺乳期的妇女、重病患者实施家庭暴力的；\n（三）因实施家庭暴力曾被公安机关给予批评教育的；\n（四）其他依法应当出具告诫书的情形。\n第二十一条 对予以告诫的家庭暴力案件，由行为发生地的公安机关自受理家庭暴力报案之日起七十二小时内出具。家庭暴力事实清楚，加害人拒不接受批评教育的，公安机关应当当场出具告诫书。\n告诫书应当包括加害人的身份信息、家庭暴力的事实陈述、禁止加害人实施家庭暴力等内容。具体式样由省人民政府公安机关统一规定。\n公安机关应当将告诫书及有关档案信息录入执法办案信息系统。\n第二十二条 公安机关应当将告诫书送交加害人、受害人，并通知加害人、受害人住所地或者经常居住地的村（居）民委员会。\n公安机关应当向加害人当场宣读告诫内容，并由加害人签名。在实施告诫时，可以邀请妇女联合会等基层组织参加；应受害人要求，可以通知加害人所在单位。加害人拒绝签收告诫书的，不影响告诫书的效力。\n第二十三条 公安机关、村（居）民委员会应当在告诫书送达之日起定期回访加害人、受害人，监督加害人不再实施家庭暴力并记录存档。\n加害人违反告诫书，再次实施家庭暴力的，由公安机关依法予以处理。\n第二十四条 医疗机构及工作人员在诊断治疗活动中发现家庭暴力伤害病例的，应当做好诊断治疗记录，并告知受害人妥善保存相关资料，有关机关调查取证时，应当据实出具诊断、医疗证明。\n第二十五条 司法鉴定机构应当依法开展家庭暴力伤情司法鉴定工作，及时出具鉴定意见。\n对符合法律援助条件的受害人，法律援助机构应当提供法律援助，司法鉴定机构应当依法减免司法鉴定费用。\n第二十六条 人民法院依法受理和审理因家庭暴力引发的民事和刑事案件，可以安排专人或者接受过专门培训的审判人员审理。\n人民检察院对公安机关、人民法院办理家庭暴力案件，依法进行监督。\n第二十七条 县级以上人民政府应当单独或者依托救助管理机构设立临时庇护场所，或者通过政府购买服务等方式，提供临时庇护场所，为家庭暴力受害人提供临时生活帮助。\n公安机关、妇女联合会、村（居）民委员会等应当告知受害人享有临时庇护的权利，受害人提出临时庇护请求的，应当协助安排至临时庇护场所。\n第二十八条 临时庇护场所应当符合下列条件：\n（一）有必要的经费、设施、专业人员和固定场所，能够稳定持续运营；\n（二）有安全保障，能够防止加害人继续实施加害行为；\n（三）与公安机关以及接受家庭暴力投诉的机构、组织有畅通的合作与转介机制。\n民政部门负责对社会力量设立的临时庇护场所依法进行监督、管理。\n第二十九条 临时庇护场所应当做好下列工作：\n（一）根据性别、年龄实行分类分区救助，妥善安排食宿，保护受害人隐私；\n（二）协调社会工作服务机构、心理咨询机构等对受害人进行需求评估，提供个性化服务；\n（三）协调卫生健康、司法行政等相关部门、人民法院和社会组织，为受害人提供医疗救助、司法救助、法律援助等转介服务。\n第三十条 出现下列情形之一的，工会、共产主义青年团、妇女联合会、残疾人联合会以及村（居）民委员会应当结合工作特点，为家庭暴力受害人、加害人提供心理辅导，对加害人进行法治教育：\n（一）因家庭暴力造成较重侵害后果的；\n（二）加害人长期、多次实施家庭暴力的；\n（三）受害人为未成年人、老年人、残疾人、孕期和哺乳期妇女、重病患者的；\n（四）未成年人、老年人、残疾人、孕期和哺乳期妇女、重病患者虽未直接遭受家庭暴力，但因目睹家庭暴力造成精神伤害的。\n第三十一条 县级以上人民政府应当建立健全反家庭暴力工作信息沟通机制，公安、民政、司法行政等相关部门和人民法院、人民检察院以及妇女联合会等单位相关信息系统应当互联互通，共享共用，做好家庭暴力的干预、救助等工作。","level":1},{"name":"第四章 人身安全保护令","text":"第三十二条 受害人因遭受家庭暴力或者面临家庭暴力现实危险的，可以依法向人民法院申请人身安全保护令。\n受害人是无民事行为能力人、限制民事行为能力人，或者因受到强制、威吓等原因无法申请人身安全保护令的，其近亲属、公安机关、妇女联合会、村（居）民委员会、救助管理机构可以代为申请。\n第三十三条 申请人身安全保护令，应当具备下列条件：\n（一）有明确的被申请人；\n（二）有具体的请求；\n（三）有遭受家庭暴力或者面临家庭暴力现实危险的情形。\n申请人身安全保护令应当以书面方式提出；书面申请确有困难的，可以口头申请，由人民法院记入笔录。\n第三十四条 人身安全保护令案件由申请人或者被申请人居住地、家庭暴力发生地的基层人民法院管辖。\n人民法院受理申请后，应当依法在七十二小时内作出人身安全保护令或者驳回申请；情况紧急的，应当在二十四小时内作出。\n人身安全保护令的有效期不超过六个月，自作出之日起生效。人身安全保护令失效前，人民法院可以根据申请人的申请撤销、变更或者延长。\n第三十五条 人身安全保护令可以包括下列措施：\n(一）禁止被申请人实施家庭暴力；\n(二）禁止被申请人骚扰、跟踪、接触申请人及其相关近亲属；\n(三）责令被申请人迁出申请人住所；\n(四）保护申请人人身安全的其他措施。\n人身安全保护令应当送达申请人、被申请人、公安机关以及村（居）民委员会等有关组织。\n人身安全保护令由人民法院执行，公安机关以及村（居）民委员会等应当协助执行。\n第三十六条 被申请人拒不履行人身安全保护令的，申请人可以向人民法院申请执行或者向公安机关报案。\n村（居）民委员会发现被申请人存在违反人身安全保护令行为的，应当及时向人民法院报告或者向公安机关报案。\n第三十七条 公安机关在接到被申请人违反人身安全保护令的报案后，应当依法进行调查取证，对申请人采取救助措施，并通知人民法院。\n对被申请人违反人身安全保护令尚不构成犯罪的，公安机关应当将案件材料移送作出人身安全保护令的人民法院，由人民法院依法处理；涉嫌犯罪的，公安机关应当依法处理。","level":1},{"name":"第五章 法律责任","text":"第三十八条 违反本条例，法律、法规有规定的，从其规定。\n第三十九条 加害人违反人身安全保护令的，有关部门或者机构应当依法纳入社会信用信息平台，实行失信联合惩戒。\n第四十条 幼儿园、学校、村（居）民委员会、医疗机构、救助管理机构、社会工作服务机构、福利机构及其工作人员，违反本条例第十八条规定，未向公安机关报案，造成严重后果的，对直接负责的主管人员和其他直接责任人员依法给予处分。\n第四十一条 负有反家庭暴力职责的国家工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第四十二条 家庭成员以外具有监护、扶养、寄养等关系的共同生活人员之间实施的暴力行为，参照本条例执行。\n第四十三条 本条例自2019年6月1日起施行。2003年7月25日湖北省第十届人民代表大会常务委员会第四次会议通过的《湖北省人民代表大会常务委员会关于预防和制止家庭暴力的决议》同时废止。","level":1}]},{"id":"h0199","sections":[{"name":"","text":"（2019年7月26日湖北省第十三届人民代表大会常务委员会第十次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了规范司法鉴定活动，促进司法公正，维护当事人合法权益，根据《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》和有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内的司法鉴定及其服务保障和监督管理活动。\n本条例所称司法鉴定，是指在诉讼活动中司法鉴定人运用科学技术或者专门知识对诉讼涉及的专门性问题进行鉴别和判断并提供鉴定意见的活动,包括法医类鉴定、物证类鉴定、声像资料鉴定、环境损害鉴定以及国家规定的其他鉴定事项。\n本条例所称司法鉴定机构和司法鉴定人，是指符合本条例规定条件，经司法行政部门登记，从事前款规定司法鉴定业务的机构和人员。\n第三条 司法鉴定活动应当遵循客观、公正、科学原则，依法独立进行，实行司法鉴定人负责制度。\n司法鉴定机构和司法鉴定人从事司法鉴定活动，应当遵守法律和法规，恪守职业道德和执业纪律，执行司法鉴定程序、技术标准和操作规范。\n司法鉴定机构和司法鉴定人依法开展司法鉴定活动，受法律保护，任何组织和个人不得非法干预。\n第四条 县级以上人民政府应当加强对司法鉴定工作的组织领导和统筹协调，健全统一司法鉴定管理体制，完善司法鉴定服务体系，保障司法鉴定服务和管理工作经费，提高司法鉴定质量和公信力。\n发展改革、教育、科学技术、财政、人力资源和社会保障、生态环境、卫生健康、市场监督管理等相关部门应当依法按照各自职责，支持司法鉴定行业发展，优化司法鉴定执业环境。\n第五条 省人民政府司法行政部门负责本省行政区域内司法鉴定活动的监督管理，依法履行司法鉴定机构和司法鉴定人的登记、名册编制、公告等管理职责。\n设区的市、自治州人民政府（以下简称市级人民政府）司法行政部门负责本行政区域内司法鉴定活动的监督管理，协助开展司法鉴定机构和司法鉴定人的登记、名册编制等管理工作。\n县级人民政府司法行政部门配合开展司法鉴定管理相关工作。\n第六条 司法鉴定机构和司法鉴定人实行统一登记管理制度。未经登记并编入司法鉴定机构和司法鉴定人名册，任何组织和个人不得从事统一登记管理范围内的司法鉴定业务。\n侦查机关根据侦查工作需要设立的司法鉴定机构及其鉴定人，由其设立机关进行资格审核并负责监督管理，按照有关规定向省人民政府司法行政部门备案登记、编入名册，不得面向社会接受委托从事司法鉴定业务。\n人民法院和司法行政部门不得设立司法鉴定机构。\n第七条 司法鉴定机构、司法鉴定人依法组建或者参加司法鉴定行业协会。\n司法鉴定行业协会依照协会章程开展活动，加强会员职业道德建设和行业自律管理，依法保护会员的合法权益，提高行业业务能力、鉴定质量和服务水平。","level":1},{"name":"第二章 司法鉴定机构","text":"第八条 法人或者其他组织申请从事司法鉴定业务，应当具备下列条件：\n（一）有自己的名称、住所和符合规定的资金；\n（二）有明确的司法鉴定业务范围；\n（三）有在业务范围内进行司法鉴定所必需的仪器、设备；\n（四）按照国家有关规定，有在业务范围内进行司法鉴定所必需的依法通过计量认证或者实验室认可的检测实验室；\n（五）每项司法鉴定业务有三名以上司法鉴定人。\n申请从事环境损害司法鉴定业务的，每项鉴定业务至少有二名具有相关专业高级专业技术职称的司法鉴定人。申请从事的司法鉴定业务涉及相关行业特殊资质要求的，申请人还应当具备相应的资质。\n司法鉴定机构设立分支机构，按照国家有关规定执行。\n第九条 申请从事司法鉴定业务的法人或者其他组织，应当向市级人民政府司法行政部门提交申请材料，报省人民政府司法行政部门。\n省人民政府司法行政部门应当依法审核申请材料，并在二十日内作出决定。符合条件的予以登记，颁发《司法鉴定许可证》；不符合条件的，不予登记，书面告知申请人并说明理由。审核时，按照国家有关规定组织专家评审。\n第十条 《司法鉴定许可证》自颁发之日起五年内有效。有效期届满需要延续的，司法鉴定机构应当在届满三十日前提出延续申请。\n司法鉴定机构变更登记事项的，按照申请登记的程序办理。\n《司法鉴定许可证》不得涂改、出借、出租、转让。\n第十一条 司法鉴定机构应当履行下列职责：\n（一）建立健全执业、收费、公示、鉴定材料、鉴定档案、财务、投诉举报处理等管理制度；\n（二）在登记的业务范围内接受司法鉴定委托，指派司法鉴定人并组织实施司法鉴定；\n（三）管理本机构人员，监督司法鉴定人执业活动；\n（四）接受司法行政部门的监督管理；\n（五）协助、配合司法行政部门和有关部门调查、处理涉及本机构的投诉、举报；\n（六）依法组织开展司法鉴定援助；\n（七）执行司法鉴定收费管理规定；\n（八）组织本机构人员的业务培训；\n（九）法律、法规规定的其他职责。\n第十二条 司法鉴定机构接受委托从事司法鉴定业务，不受地域范围的限制。\n司法鉴定机构不得以诋毁其他司法鉴定机构、司法鉴定人或者支付回扣、介绍费以及进行虚假宣传、违规设立分支机构等不正当手段招揽业务。\n第十三条 司法鉴定机构应当对鉴定档案实行集中统一管理，任何组织和个人不得据为己有或者拒绝归档。除约定退还委托人的鉴定材料外，其他与鉴定事项相关的鉴定材料都应当及时立卷归档保存。\n含有鉴定意见的鉴定档案保管期限按照国家和省有关规定执行。司法鉴定机构被撤销或者注销的，鉴定档案应当移交当地档案馆。\n第十四条 司法鉴定机构有下列情形之一的，省人民政府司法行政部门应当依法注销登记：\n(一)依法申请终止司法鉴定活动的；\n(二)自愿解散或者无正当理由停止执业一年以上的；\n(三)登记事项发生变化，不再符合设立条件的；\n(四)《司法鉴定许可证》有效期届满未申请延续的；\n(五)法律、法规规定的其他情形。","level":1},{"name":"第三章 司法鉴定人","text":"第十五条 具备下列条件之一的人员，可以申请登记从事司法鉴定业务：\n（一）具有与所申请从事的司法鉴定业务相关的高级专业技术职称；\n（二）具有与所申请从事的司法鉴定业务相关的专业执业资格或者高等院校相关专业本科以上学历，从事相关工作五年以上；\n（三）申请从事经验鉴定型或者技能鉴定型司法鉴定业务的，应当具有相关专业工作十年以上经历，具有较强的专业技能。\n第十六条 有下列情形之一的人员，不得申请登记从事司法鉴定业务：\n（一）因故意犯罪或者职务过失犯罪受过刑事处罚的；\n（二）受过开除公职处分的；\n（三）被撤销司法鉴定人登记的；\n（四）法律、法规规定的其他情形。\n第十七条 申请登记从事司法鉴定业务的人员，应当通过拟执业的司法鉴定机构向市级人民政府司法行政部门提交申请材料，报省人民政府司法行政部门。\n省人民政府司法行政部门应当依法审核申请材料，并在二十日内作出决定。符合条件的予以登记，颁发《司法鉴定人执业证》；不符合条件的，不予登记，书面告知申请人并说明理由。审核时，按照国家有关规定组织执业能力考核。\n第十八条 《司法鉴定人执业证》自颁发之日起五年内有效。有效期届满需要继续从事司法鉴定业务的，司法鉴定人应当通过所在司法鉴定机构在届满三十日前提出延续申请。\n司法鉴定人变更登记事项的，按照申请登记的程序办理。\n第十九条 司法鉴定人应当在登记的业务范围内从事司法鉴定业务，并接受所在司法鉴定机构的管理和监督。\n司法鉴定人不得同时在两个以上司法鉴定机构中从事司法鉴定业务。\n司法鉴定机构可以根据业务需要聘用司法鉴定人助理，辅助司法鉴定人开展司法鉴定活动。司法鉴定人助理不得实施法律、法规规定必须由司法鉴定人实施的司法鉴定工作。\n第二十条 司法鉴定人享有下列权利：\n（一）依法独立进行司法鉴定；\n（二）了解、查阅与鉴定事项有关的情况和资料，询问与鉴定事项有关的当事人、证人和见证人等；\n（三）要求委托人无偿提供鉴定所需要的鉴定材料；\n（四）进行鉴定所必需的检验、检查和模拟实验；\n（五）拒绝接受不合法、不具备鉴定条件或者超出登记业务范围的鉴定委托；\n（六）拒绝解决、回答与鉴定无关的问题；\n（七）鉴定意见不一致时，保留不同意见；\n（八）依法获得报酬；\n（九）法律、法规规定的其他权利。\n第二十一条 司法鉴定人应当履行下列义务：\n（一）受所在司法鉴定机构指派按照时限完成鉴定工作，并出具鉴定意见；\n（二）对鉴定意见负责；\n（三）依法回避；\n（四）妥善保管鉴定材料，如需进行破坏性检验检测，必须征得委托人同意；\n（五）保守在执业活动中知悉的国家秘密、商业秘密和个人隐私；\n（六）依法出庭作证，回答与鉴定有关的询问；\n（七）接受司法行政部门的监督管理；\n（八）参加司法鉴定教育培训；\n（九）法律、法规规定的其他义务。\n第二十二条 司法鉴定人有下列情形之一的，省人民政府司法行政部门应当依法注销登记：\n（一）依法申请终止司法鉴定活动的；\n（二）《司法鉴定人执业证》有效期届满未申请延续的；\n（三）所在司法鉴定机构被撤销或者注销的；\n（四）相关专业的执业资格被撤销的；\n（五）死亡或者丧失行为能力的；\n（六）法律、法规规定的其他情形。","level":1},{"name":"第四章 司法鉴定活动","text":"第二十三条 在诉讼活动中需要进行司法鉴定的，公安机关、人民检察院、人民法院等办案机关应当根据鉴定事项对专业技术的要求，从司法行政部门统一编制并公告的名册中选择和委托司法鉴定机构。\n司法鉴定机构应当统一受理办案机关的司法鉴定委托。司法鉴定人不得私自接受委托、收取费用或者当事人财物。\n第二十四条 委托人委托司法鉴定，应当提供真实、完整、充分的鉴定材料，并对材料的真实性、合法性负责。\n委托人应当对鉴定材料进行审核登记、封存、加盖公章后移送司法鉴定机构。人民法院提供的鉴定材料应当经过质证或者确认。\n司法鉴定机构应当核对并记录鉴定材料的名称、种类、数量、性状、保存状况和收件时间等，并出具材料接收凭证。\n未经委托人同意，司法鉴定机构不得接收除委托人外其他单位和个人提供的鉴定材料。\n第二十五条 司法鉴定机构应当对委托鉴定事项、鉴定材料等进行审查，并自收到委托之日起七个工作日内作出是否接受委托的决定。\n对属于本机构司法鉴定业务范围的委托鉴定事项，提供的鉴定材料能够满足鉴定需要的，应当受理。对委托鉴定事项不明确，鉴定材料不完整、不充分，不能满足鉴定需要的，司法鉴定机构可以要求委托人补充；经补充后能够满足鉴定需要的，应当受理。\n司法鉴定机构无正当理由不得拒绝接受司法鉴定委托。\n第二十六条 司法鉴定机构决定受理鉴定委托的，应当与委托人签订司法鉴定委托书，明确委托鉴定事项、鉴定用途、与鉴定有关的基本案情、鉴定时限、鉴定材料、鉴定费用等事项。\n第二十七条 具有下列情形之一的鉴定委托，司法鉴定机构不得受理：\n（一）委托鉴定事项超出本机构司法鉴定业务范围的；\n（二）发现鉴定材料不真实、不完整、不充分或者取得方式不合法的；\n（三）鉴定用途不合法或者违背社会公德的；\n（四）鉴定要求不符合司法鉴定执业规则或者相关鉴定技术规范的；\n（五）鉴定要求超出本机构技术条件或者鉴定能力的；\n（六）委托人就同一鉴定事项同时委托其他司法鉴定机构进行鉴定的；\n（七）法律、法规规定不得受理的其他情形。\n对不予受理的，司法鉴定机构应当书面说明理由并退还鉴定材料。\n第二十八条 司法鉴定机构受理鉴定委托后，应当指派本机构具有该鉴定事项执业资格的司法鉴定人进行鉴定。对同一鉴定事项，应当指派二名司法鉴定人进行鉴定；对复杂、疑难或者特殊鉴定事项，可以指派多名司法鉴定人进行鉴定。\n委托人有特殊要求的，经双方协商一致，可以从本机构中选择符合条件的司法鉴定人进行鉴定。\n委托人不得要求或者暗示司法鉴定机构、司法鉴定人按照其意图或者特定目的提供鉴定意见。\n第二十九条 司法鉴定人有下列情形之一的，应当回避：\n（一）本人或者其近亲属与当事人或者鉴定事项涉及的案件有利害关系的；\n（二）曾参加过同一鉴定事项的鉴定或者为其提供过咨询意见的；\n（三）作为有专门知识的人出庭，就同一鉴定事项的鉴定意见提出意见的；\n（四）法律、法规规定应当回避的其他情形。\n司法鉴定人自行提出回避的，由其所在的司法鉴定机构决定；委托人要求司法鉴定人回避的，应当向司法鉴定人所在的司法鉴定机构提出，由司法鉴定机构决定。委托人对司法鉴定机构是否回避的决定有异议的，可以撤销鉴定委托。\n第三十条 司法鉴定人应当对鉴定过程进行实时记录并签名。记录应当载明主要的鉴定方法和过程，检查、检验、检测结果，以及仪器设备使用情况等。记录的内容应当真实、客观、准确、完整、清晰，记录的文本资料、声像资料等应当存入鉴定档案。\n第三十一条 司法鉴定机构应当在与委托人约定的鉴定时限内完成鉴定；没有约定鉴定时限的，应当自鉴定委托受理之日起三十个工作日内完成鉴定。\n第三十二条 在鉴定过程中有下列情形之一的，司法鉴定机构可以终止鉴定：\n（一）发现有本条例第二十七条第一款第二项至第七项规定情形的；\n（二）鉴定材料发生耗损，委托人不能补充提供的；\n（三）委托人拒不履行司法鉴定委托书规定的义务，被鉴定人拒不配合或者鉴定活动受到严重干扰，致使鉴定无法继续进行的；\n（四）委托人主动撤销鉴定委托，或者委托人、当事人拒绝支付鉴定费用的；\n（五）因不可抗力致使鉴定无法继续进行的；\n（六）法律、法规规定需要终止鉴定的其他情形。\n终止鉴定的，司法鉴定机构应当书面通知委托人，说明理由并退还鉴定材料。\n第三十三条 有下列情形之一的，司法鉴定机构可以根据委托人的要求进行补充鉴定：\n（一）原委托鉴定事项有遗漏的；\n（二）委托人就原委托鉴定事项提供新的鉴定材料的；\n（三）法律、法规规定需要补充鉴定的其他情形。\n补充鉴定是原委托鉴定的组成部分，应当由原司法鉴定人进行。\n第三十四条 有下列情形之一的，司法鉴定机构可以接受办案机关委托进行重新鉴定：\n（一）原司法鉴定人不具有从事委托鉴定事项执业资格的；\n（二）原司法鉴定机构超出登记的业务范围组织鉴定的；\n（三）原司法鉴定人应当回避没有回避的；\n（四）原司法鉴定程序严重违法的；\n（五）法律、法规规定需要重新鉴定的其他情形。\n第三十五条 办案机关应当对重新鉴定事项的必要性和可行性进行审查，必要时可以组织专家评审。\n重新鉴定应当委托原司法鉴定机构以外的其他司法鉴定机构进行；因特殊原因，也可以委托原司法鉴定机构进行，但原司法鉴定机构应当指派原司法鉴定人以外的其他符合条件的司法鉴定人进行。\n重新鉴定的司法鉴定人中应当至少有一名具有相关专业高级专业技术职称。\n第三十六条 鉴定过程中，涉及复杂、疑难、特殊技术问题的，可以向本机构以外的相关专业领域的专家进行咨询，但最终的鉴定意见应当由本机构的司法鉴定人出具。专家提供咨询意见应当签名，并存入鉴定档案。\n第三十七条 司法鉴定机构和司法鉴定人完成鉴定后，应当按照有关规定制作司法鉴定意见书，并送交委托人。\n司法鉴定意见书应当加盖司法鉴定机构的司法鉴定专用章并由司法鉴定人签名。多人参加的鉴定，对鉴定意见有不同意见的，应当注明。\n第三十八条 委托人对鉴定过程、鉴定意见提出询问的，司法鉴定机构和司法鉴定人应当给予解释或者说明。未经委托人同意，司法鉴定机构和司法鉴定人不得向其他个人或者组织提供与鉴定事项有关的信息，但法律、法规另有规定的除外。\n第三十九条 经人民法院依法通知，司法鉴定人应当出庭作证，回答与司法鉴定事项有关的问题。司法鉴定人确因法律规定的情形不能出庭作证的，应当经人民法院许可。无正当理由拒不出庭作证的，鉴定意见不得作为认定事实的根据，支付鉴定费用的当事人可以依法要求返还鉴定费用。\n第四十条 人民法院通知司法鉴定人出庭作证的，应当依法在开庭前将通知书送达司法鉴定机构。司法鉴定机构应当支持司法鉴定人出庭作证，为司法鉴定人出庭提供必要条件。\n人民法院应当为司法鉴定人出庭提供席位、通道等，保障司法鉴定人出庭作证时的人身安全及其他合法权益。经人民法院同意，司法鉴定人可以使用视听传输技术或者同步视频作证室等作证。\n第四十一条 当事人对鉴定意见提出异议的，办案机关应当引导当事人依法维护权利，不得要求或者暗示当事人直接到司法鉴定机构进行质询。\n办案机关不得向当事人透露司法鉴定人执业资格、业务范围以外的个人信息。司法鉴定人及其近亲属因鉴定执业活动、出庭作证而受到人身安全威胁的，相关机关应当依法及时采取必要的保护措施。\n对采用辱骂、殴打、恐吓、损毁财物等方式破坏司法鉴定机构工作秩序、干扰司法鉴定活动的当事人或者其他人员，公安机关应当依法及时处置。\n第四十二条 司法鉴定人在人民法院指定日期出庭发生的交通费、住宿费、生活费和误工补贴，按照国家有关规定应当由当事人承担的，由人民法院代为收取并支付给司法鉴定机构。","level":1},{"name":"第五章 服务保障和监督管理","text":"第四十三条 省人民政府司法行政部门应当制定本省司法鉴定发展专项规划，建立标准化、全覆盖的司法鉴定便民服务网络，支持司法鉴定机构加强技术装备和人才队伍建设，促进司法鉴定行业健康发展。\n市县两级人民政府司法行政部门应当加强司法鉴定机构质量管理和能力水平建设，推动司法鉴定机构专业化、规范化发展。\n支持依托高等院校、科研院所设立司法鉴定机构，支持司法鉴定机构与高等院校、科研院所合作，提高司法鉴定能力和水平。\n第四十四条 省人民政府司法行政部门应当统一编制司法鉴定机构和司法鉴定人名册，真实、准确反映司法鉴定机构和司法鉴定人的执业能力和水平，及时向社会公告、实行动态调整。\n第四十五条 省人民政府司法行政部门应当建立司法鉴定机构资质管理评估、司法鉴定质量评估和诚信评价机制，评估评价结果依法纳入社会信用信息服务平台，及时向社会公布。\n开展评估评价应当听取办案机关意见，并将司法鉴定能力水平、依法规范执业以及鉴定意见的采信情况作为评估评价的重要内容。\n第四十六条 省人民政府司法行政部门应当建立司法鉴定专家库，组织开展司法鉴定登记专家评审、司法鉴定质量专家评估和司法鉴定监督管理专家咨询等工作。\n第四十七条 县级以上人民政府司法行政部门应当加强司法鉴定培训工作，有计划地组织司法鉴定机构、司法鉴定人开展工作培训和业务交流。\n第四十八条 省人民政府司法行政部门应当建立司法鉴定信息化管理平台，实行司法鉴定实施程序全流程监督管理。司法行政部门和办案机关应当共同做好信息平台对接，实现信息共享。\n司法行政部门和办案机关建立司法鉴定管理与使用衔接机制。司法行政部门应当将司法鉴定机构、司法鉴定人变更和行政处罚等情况，及时告知办案机关。办案机关应当将鉴定意见的采信情况和司法鉴定机构、司法鉴定人的违法违规行为，及时告知司法行政部门；必要时，可以发出司法建议书。\n第四十九条 县级以上人民政府司法行政部门应当建立健全随机抽查机制，对司法鉴定机构和司法鉴定人的下列事项进行监督检查，并将抽查情况以及查处结果及时向社会公布：\n（一）遵守有关法律、法规情况；\n（二）执行司法鉴定程序、技术标准和操作规范情况；\n（三）遵守职业道德和执业纪律情况；\n（四）业务开展和鉴定质量情况；\n（五）制定和执行管理制度情况；\n（六）执行司法鉴定收费管理规定情况；\n（七）法律、法规规定的其他事项。\n第五十条 县级以上人民政府司法行政部门应当建立司法鉴定投诉举报处理机制，依法分级受理、调查处理司法鉴定投诉举报。\n司法鉴定案件当事人或者其他利害关系人认为司法鉴定机构和司法鉴定人在执业活动中有违法行为的，可以向司法行政部门投诉；其他个人或者组织发现司法鉴定机构和司法鉴定人违法执业的，可以向司法行政部门举报。司法行政部门应当依法及时调查处理。\n第五十一条 司法行政部门、司法鉴定行业协会应当建立投诉举报事项行政处罚与行业惩戒衔接制度。\n建立健全司法鉴定纠纷调解机制，对适合调解的鉴定纠纷，在双方自愿、平等的基础上，引导投诉人和被投诉人通过调解方式解决鉴定纠纷。\n第五十二条 司法鉴定的收费标准由省人民政府价格主管部门会同省人民政府司法行政部门制定。\n司法鉴定机构办理与法律援助案件相关的司法鉴定事项，应当按照有关规定减收或者免收鉴定费用。","level":1},{"name":"第六章 法律责任","text":"第五十三条 违反本条例，法律、法规有规定的，从其规定。\n第五十四条 未经依法登记的机构和人员从事司法鉴定业务的，由省人民政府司法行政部门责令其停止司法鉴定活动；有违法所得的，没收违法所得，并处违法所得一倍以上三倍以下的罚款。\n第五十五条 司法鉴定机构有下列情形之一的，由省人民政府司法行政部门给予警告，并责令改正；情节严重的，给予停止从事司法鉴定业务一个月以上三个月以下的处罚：\n（一）超出登记的业务范围从事司法鉴定业务的；\n（二）登记事项发生变化，未依法办理变更登记的；\n（三）涂改、出借、出租、转让《司法鉴定许可证》的；\n（四）无正当理由拒绝接受司法鉴定委托的；\n（五）违反司法鉴定程序、技术标准和操作规范进行司法鉴定的；\n（六）违反司法鉴定收费管理规定的；\n（七）以诋毁其他司法鉴定机构、司法鉴定人或者支付回扣、介绍费以及进行虚假宣传等不正当手段招揽业务的；\n（八）组织未取得《司法鉴定人执业证》的人员从事司法鉴定业务的；\n（九）拒绝接受司法行政部门监督、检查或者采取提供虚假材料等手段弄虚作假的；\n（十）违规设立分支机构的；\n（十一）法律、法规规定的其他情形。\n第五十六条 司法鉴定人有下列情形之一的，由省人民政府司法行政部门给予警告，并责令改正；情节严重的，给予停止从事司法鉴定业务一个月以上三个月以下的处罚：\n（一）超出登记的业务范围从事司法鉴定业务的；\n（二）同时在两个以上司法鉴定机构从事司法鉴定业务的；\n（三）私自接受委托、收取费用或者当事人财物的；\n（四）违反保密、回避规定的；\n（五）违反司法鉴定程序、技术标准和操作规范进行司法鉴定的；\n（六）拒绝接受司法行政部门监督、检查或者采取提供虚假材料等手段弄虚作假的；\n（七）法律、法规规定的其他情形。\n第五十七条 司法鉴定机构、司法鉴定人有下列情形之一的，由省人民政府司法行政部门给予停止从事司法鉴定业务三个月以上一年以下的处罚；情节严重的，撤销登记：\n（一）因严重不负责任给当事人合法权益造成重大损失的；\n（二）提供虚假证明文件或者采取其他欺诈手段，骗取登记的；\n（三）故意作虚假鉴定的；\n（四）经人民法院依法通知，无正当理由拒绝出庭作证的；\n（五）法律、法规规定的其他情形。\n第五十八条 司法鉴定机构、司法鉴定人在执业过程中，因故意或者重大过失给当事人造成损失的，依法承担民事责任。\n第五十九条 国家机关及其工作人员有下列情形之一的，对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）违反法定条件和程序办理司法鉴定机构、司法鉴定人登记的；\n（二）收受或者索取司法鉴定机构、司法鉴定人财物或者谋取其他不正当利益的；\n（三）收到投诉举报或者发现违法行为线索，不及时履行调查处理和监督职责的；\n（四）非法干预司法鉴定机构、司法鉴定人依法独立开展司法鉴定活动的;\n（五）其他滥用职权、玩忽职守、徇私舞弊情形的。","level":1},{"name":"第七章 附则","text":"第六十条 在诉讼活动外，司法鉴定机构和司法鉴定人依法开展相关鉴定业务的，参照本条例规定执行。\n第六十一条 本条例自2019年11月1日起施行。2002年3月28日湖北省第九届人民代表大会常务委员会第三十二次会议通过的《湖北省司法鉴定管理条例》同时废止。","level":1}]},{"id":"h0200","sections":[{"name":"","text":"（2019年7月26日湖北省第十三届人民代表大会常务委员会第十次会议通过）\n为合理利用土地资源，加强土地管理，保护耕地，根据《中华人民共和国耕地占用税法》第四条、第五条、第十二条规定，结合我省人均耕地面积和经济发展等情况，作出以下决定：\n一、各地区耕地占用税适用税额为：江岸区、江汉区、硚口区、汉阳区、武昌区、青山区、洪山区、黄石港区、西塞山区、下陆区、铁山区、茅箭区、张湾区、樊城区、鄂城区、黄州区、西陵区、伍家岗区、点军区、猇亭区，每平方米四十五元；东西湖区、大冶市、襄城区、咸安区、汉南区、蔡甸区、江夏区、黄陂区、新洲区、沙市区、荆州区、梁子湖区、华容区、东宝区、掇刀区、孝南区、云梦县、曾都区、武穴市，每平方米三十五元；阳新县、公安县、监利县、襄州区、老河口市、枣阳市、宜城市、京山市、沙洋县、钟祥市、孝昌县、大悟县、应城市、安陆市、汉川市、浠水县、蕲春县、石首市、洪湖市、松滋市、夷陵区、宜都市、当阳市、枝江市、随县、广水市、黄梅县、麻城市、嘉鱼县、恩施市、天门市、仙桃市、潜江市，每平方米三十元；郧阳区、郧西县、竹山县、竹溪县、房县、丹江口市、南漳县、谷城县、保康县、团风县、红安县、罗田县、英山县、江陵县、远安县、兴山县、秭归县、长阳土家族自治县、五峰土家族自治县、通城县、崇阳县、通山县、赤壁市、利川市、建始县、巴东县、宣恩县、咸丰县、来凤县、鹤峰县、神农架林区，每平方米二十二元。\n二、对人均耕地面积低于零点五亩的地区不再加成征收耕地占用税。\n三、对占用其他农用地的，比照占用耕地适用税额征收耕地占用税。\n四、本决定自2019年9月1日起施行。","level":0}]},{"id":"h0201","sections":[{"name":"","text":"（2019年7月26日湖北省第十三届人民代表大会常务委员会第十次会议通过）\n为贯彻落实党中央关于建立检察机关提起公益诉讼制度的重大决策部署和省委工作要求，全面实施《全国人民代表大会常务委员会关于修改〈中华人民共和国民事诉讼法〉和〈中华人民共和国行政诉讼法〉的决定》，维护国家利益和社会公共利益，根据《中华人民共和国各级人民代表大会常务委员会监督法》等有关法律规定，结合我省实际，特作出如下决定：\n一、建立检察机关提起公益诉讼制度，是党中央贯彻习近平新时代中国特色社会主义思想、坚持以人民为中心的发展理念、立足党和国家事业发展全局作出的重大决策部署，是推进全面深化改革、全面依法治国的一项重大举措，是充分发挥人民法院司法审判、人民检察院法律监督职能作用，促进依法行政、严格执法，加快推进社会治理现代化的一项重要制度安排。全省各级国家机关、企业事业单位、人民团体、社会组织要以习近平新时代中国特色社会主义思想为指导，提高对检察公益诉讼工作的思想认识和政治站位，切实增强责任感和使命感，共同支持和推进检察公益诉讼工作，更好地维护宪法法律权威，维护社会公平正义，维护国家和社会公共利益，用法治保障人民权益、增进民生福祉。\n二、各级人大常委会应当依法通过完善地方立法、听取和审议专项工作报告、开展执法检查、作出决议决定等方式，监督和支持行政机关、监察机关、审判机关、检察机关严格依法履行共同推进检察公益诉讼工作的职责，加强对检察机关提出的维护国家利益和社会公共利益的监督事项办理和落实工作的监督；畅通人大代表反映公益诉讼案件线索的渠道，通过邀请人大代表视察、旁听公益诉讼案件庭审等方式，充分发挥人大代表作用。\n三、各级人民政府应当将依法支持、配合检察公益诉讼工作作为法治政府建设重要内容，明确工作要求，完善相关制度；为检察公益诉讼案件的检验、鉴定、评估、勘验工作提供支持，将检察公益诉讼案件办案经费纳入财政预算予以保障；探索建立检察公益诉讼赔偿金管理机制和办法，确保赔偿款项依法用于公益修复或者赔偿。各级人民政府及其部门要自觉接受司法监督，积极配合检察机关依法开展查阅、利用行政执法卷宗材料和收集证据等调查核实工作；按照检察机关的检察建议全面自查、依法履职、按时回复，严格执行人民法院公益诉讼案件的生效判决；对于人民检察院提起的行政公益诉讼案件，被诉行政机关负责人应当出庭应诉。\n四、各级人民法院应当加强公益诉讼审判专门化、专业化建设；与人民检察院建立沟通协调机制，依法研究解决公益诉讼案件相关程序、案件管辖、证据规则及法律适用等工作问题；对人民检察院提起的公益诉讼案件及时立案受理，依法公正审判。对于公益诉讼案件审理中发现损害国家利益和社会公共利益的行为仍然继续存在的，应当依法及时采取禁止令等行为保全措施；积极探索补植复绿、增殖放流、替代性修复等恢复性司法裁判内容，确保生效判决执行；对于相关行政机关组织生态修复等协助执行事项，及时书面函告；对于不履行相关义务的被执行人、协助执行义务人，依法追究其相应责任。\n五、各级人民检察院应当聚焦党和国家工作大局，紧紧围绕助推打好“三大攻坚战”、服务长江经济带高质量发展、推动“一芯两带三区”发展战略实施以及人民群众关注的切身利益问题，持续在生态环境和资源保护、食品药品安全、国有财产保护和国有土地使用权出让、英雄烈士保护等重点领域推进公益诉讼工作，依法在安全生产、文物和文化遗产保护、电信互联网涉及众多公民个人信息保护等领域探索开展公益诉讼工作，实现公益诉讼案件法律效果、政治效果、社会效果的有机统一。加强检察公益诉讼专业化和职业化建设，不断提高办案能力和质量；综合运用检察建议、提起诉讼、督促和支持符合法律规定的机关和组织以及其他主体提起民事公益诉讼等方式，开展检察公益诉讼工作，充分发挥公益诉讼引领作用；坚持把通过诉前程序实现维护公益目的作为最佳目标，努力与行政机关形成双赢多赢共赢局面。对负有监督管理职责的行政机关，不采纳检察建议又不依法履行职责的，应当及时依法起诉。对检察公益诉讼案件反映的普遍性倾向性问题，向同级人民政府提出工作建议，促进依法行政和社会治理水平提升。对人民群众反映的公益诉讼案件线索，应当及时办理并回复。\n六、各级人民政府及其部门、监察委员会、人民法院、人民检察院应当健全检察公益诉讼协作机制，健全工作沟通、宣告送达、案件线索双向移送及反馈制度；建立检察公益诉讼案件信息共享平台，各级行政机关依法向人民检察院开放相关行政执法信息和数据库；探索检察公益诉讼制度与生态环境损害赔偿制度的有效衔接机制。司法行政部门应当加快公共法律服务体系建设，推进生态环境损害等领域司法鉴定机构建设，依法规范司法鉴定行为，积极探索重大典型检察公益诉讼案件先鉴定、后付费的办法；指导公证机构、律师为检察公益诉讼案件提供法律服务。公安机关对于以暴力、威胁、限制人身自由、聚众围攻等方式干扰、阻碍司法机关办理公益诉讼案件的违法行为，应当依法及时处理。\n七、各级人民政府及其部门、人民法院、人民检察院和新闻媒体应当加大宣传力度，提高人民群众对检察公益诉讼工作的知晓度，营造人民群众参与、支持检察公益诉讼工作的良好舆论环境和社会氛围。深入发动群众，鼓励社会组织、公众依法向人民检察院和有关国家机关举报公益诉讼案件线索，对于社会影响较大、人民群众广泛关注的检察公益诉讼案件，要及时公开案件办理情况，积极回应社会关切，主动接受社会监督。\n八、本决定自公布之日起施行。","level":0}]},{"id":"h0202","sections":[{"name":"","text":"（2016年1月20日随州市第三届人民代表大会第六次会议通过 2016年3月30日湖北省第十二届人民代表大会常务委员会第二十一次会议批准）","level":0},{"name":"第一章 总则","text":"第一条 为了规范市人民代表大会及其常务委员会立法活动，完善立法程序，提高立法质量，发挥立法的引领和推动作用，全面推进法治随州建设，根据宪法、地方组织法、立法法和我\n省立法条例的有关规定，结合本市实际，制定本条例。\n第二条 市人民代表大会及其常务委员会制定、修改、废止和解释地方性法规以及相关立法活动，适用本条例。\n第三条 市人民代表大会及其常务委员会根据本市的具体情况和实际需要，在不同宪法、法律、行政法规和我省地方性法规相抵触的前提下，对城乡建设与管理、环境保护、历史文化保\n护等方面的事项制定地方性法规。法律对设区的市制定地方性法规的事项另有规定的，从其规定。\n制定地方性法规，遵循立法法和我省立法条例规定的基本原则。对上位法已经明确规定的内容，一般不作重复性规定。\n第四条 规定本市特别重大事项的地方性法规，应当由市人民代表大会制定，其他地方性法规由市人民代表大会常务委员会（以下简称常务委员会）制定。\n在市人民代表大会闭会期间，常务委员会可以对市人民代表大会制定的地方性法规进行部分补充和修改，但不得同该法规的基本原则相抵触。补充和修改情况应当向市人民代表大会报告\n。\n第五条 市人民代表大会及其常务委员会应当加强对立法工作的组织协调，发挥在立法工作中的主导作用。","level":1},{"name":"第二章 立法准备","text":"","level":1},{"name":"第一节 立法规划和立法计划","text":"第六条 常务委员会应当编制年度立法计划，根据需要编制本届任期内的立法规划。\n编制立法规划和立法计划，应当征求省人民代表大会常务委员会的意见，并报省人民代表大会常务委员会备案。\n第七条 常务委员会编制立法规划和立法计划，应当分别征求市人民政府及其有关部门、市中级人民法院、市人民检察院以及有关人民团体、社会组织的立法建议,并向社会公开征集立法\n建议。\n国家机关、政党、团体、组织以及公民可以向常务委员会提出制定地方性法规的建议和意见。\n立法建议应当采用书面形式，并附有立法依据和主要内容等。\n第八条 常务委员会法制工作委员会（以下简称法制工作委员会）根据人民代表大会专门委员会（以下简称专门委员会）、市人民政府法制工作机构以及有关方面的立法建议，统一研究\n、协调论证，提出立法规划草案和立法计划草案，提请常务委员会主任会议审议通过。\n第九条 专门委员会、市人民政府及其有关部门、有关人民团体、社会组织应当认真组织实施立法规划和立法计划。\n立法规划和立法计划在执行过程中需要作适当调整的，由法制工作委员会根据专门委员会和有关方面的建议，提出方案，报主任会议审定。法规案未能按时提请审议的，提案人应当向主\n任会议报告并说明情况。","level":2},{"name":"第二节 法规草案的起草","text":"第十条 向市人民代表大会或者常务委员会提出法规案，由提案人组织起草法规草案。\n有关专门委员会、法制工作委员会以及有关方面应当提前参与法规草案起草工作，了解情况，提出意见。综合性、全局性、基础性的重要法规草案，可以由有关专门委员会或者法制工作\n委员会组织起草。\n专业性较强的法规草案，可以吸收相关领域的专家参与起草工作，或者委托有关专家、教学科研单位、社会组织起草。\n第十一条 起草法规草案，应当深入调查研究，广泛征求相关方面意见。\n法规草案的起草单位应当主动向有关专门委员会和法制工作委员会报告起草工作情况。","level":2},{"name":"第三章 立法程序","text":"","level":1},{"name":"第一节 市人民代表大会立法程序","text":"第十二条 市人民代表大会主席团可以向市人民代表大会提出法规案，由市人民代表大会会议审议。\n常务委员会、市人民政府、专门委员会可以向市人民代表大会提出法规案，由主席团决定列入会议议程，或者先交有关专门委员会审议、提出报告，再由主席团决定列入会议议程。\n市人民代表大会代表十人以上联名，可以向市人民代表大会提出法规案，由主席团决定是否列入会议议程，或者先交有关专门委员会审议，提出是否列入会议议程的意见，再决定是否列\n入会议议程。\n专门委员会审议法规案时，可以邀请提案人列席会议，发表意见。\n第十三条 拟提请市人民代表大会审议的法规案，在市人民代表大会闭会期间，可以先向常务委员会提出，经常务委员会会议依照本条例第三章第二节规定的有关程序审议后，决定提请\n市人民代表大会审议，由常务委员会或者提案人向大会全体会议作说明。\n第十四条 列入市人民代表大会会议议程的法规案，由有关专门委员会进行审议，向主席团提出审议意见，并印发会议。\n第十五条 列入市人民代表大会会议议程的法规案，大会全体会议听取常务委员会或者提案人的说明后，由各代表团进行审议。\n各代表团审议法规案时，提案人应当派人听取意见，回答询问。\n各代表团审议法规案时，根据代表团的要求，有关机关、团体或者组织应当派人介绍情况。\n第十六条 列入市人民代表大会会议议程的法规案，由法制委员会根据各代表团和有关专门委员会的审议意见，对法规案进行统一审议，向主席团提出审议结果的报告和法规草案修改稿\n，对重要的不同意见应当在审议结果报告中予以说明，经主席团审议通过后，印发会议。\n第十七条 列入市人民代表大会会议议程的法规案，必要时，主席团常务主席可以召开各代表团团长或者代表团推选的代表的会议，就法规案中的重大问题听取意见，进行讨论，并将讨\n论的情况和意见向主席团报告。\n第十八条 列入市人民代表大会会议议程的法规案，在交付表决前，提案人要求撤回的，应当提出书面报告，说明理由，经主席团同意，并向大会报告，对该法规案的审议即行终止。\n第十九条 法规案在审议中有重大问题需要进一步研究的，经主席团提出，由大会全体会议决定，可以授权常务委员会根据代表的意见进一步审议，作出决定，并将决定情况向市人民代\n表大会下次会议报告；也可以授权常务委员会根据代表的意见进一步审议，提出修改方案，提请市人民代表大会下次会议审议决定。\n第二十条 法规草案修改稿经各代表团审议，由法制委员会根据各代表团的审议意见进行修改，提出法规草案表决稿，由主席团提请大会全体会议表决，由全体代表的过半数通过。\n第二十一条 市人民代表大会通过的地方性法规，应当自通过之日起十五日内，由常务委员会报请省人民代表大会常务委员会批准；经批准后，由常务委员会发布公告予以公布。","level":2},{"name":"第二节 市人民代表大会常务委员会立法程序","text":"第二十二条 主任会议可以向常务委员会提出法规案，由常务委员会会议审议。\n市人民政府、专门委员会可以向常务委员会提出法规案，由主任会议决定列入常务委员会会议议程，或者先交有关专门委员会审议、提出报告，再决定列入常务委员会会议议程。如果主\n任会议认为法规案有重大问题需要进一步研究，可以建议提案人修改完善后再向常务委员会提出。\n市人民政府或者专门委员会提请常务委员会审议的法规案，应当分别经市人民政府常务会议或者专门委员会全体会议通过后，以书面形式提出。\n第二十三条 常务委员会组成人员五人以上联名，可以向常务委员会提出法规案，由主任会议决定是否列入常务委员会会议议程，或者先交有关专门委员会审议、提出是否列入会议议程\n的意见，再决定是否列入常务委员会会议议程。不列入常务委员会会议议程的，应当向常务委员会会议报告，并向提案人说明。\n第二十四条 拟提请常务委员会会议审议的法规草案，应当在常务委员会会议举行的二十日前报送常务委员会。未能提前二十日报送的，一般列入下次常务委员会会议议程。\n第二十五条 列入常务委员会会议议程的法规案，一般应当经两次常务委员会会议审议后再交付下次常务委员会会议表决。\n常务委员会会议第一次审议法规案，听取提案人的说明并进行审议；常务委员会会议第二次审议法规案，听取法制委员会关于法规草案审议结果的报告并再次审议。\n调整事项较为单一或者部分修改的法规案，各方面意见比较一致的，经主任会议决定，可以经一次或者两次常务委员会会议审议即交付表决。\n第二十六条 列入常务委员会会议议程的法规案，由有关专门委员会进行审议，提出审议意见，报告主任会议，并印发常务委员会会议。\n有关专门委员会审议法规案时，可以邀请其他常务委员会组成人员列席会议，发表意见。\n第二十七条 专门委员会审议法规案时，应当召开全体会议审议，根据需要，可以要求有关机关、团体或者组织派负责人说明情况。\n专门委员会之间对法规草案的重要问题意见不一致时，应当向主任会议报告。\n第二十八条 常务委员会审议法规案时，提案人应当派人听取意见，回答询问。根据需要，有关机关、团体或者组织应当派人介绍情况。列席会议的人员，经主持人同意，可以发表意见\n。\n第二十九条 列入常务委员会会议议程的法规案，由法制委员会根据常务委员会组成人员、有关专门委员会的审议意见和各方面提出的意见，对法规案进行统一审议，提出审议结果的报\n告和法规草案修改稿，对重要的不同意见应当在报告中予以说明。对有关专门委员会的重要审议意见没有采纳的，应当向有关专门委员会反馈。\n法制委员会审议法规案时，应当邀请有关专门委员会的成员列席会议，发表意见。\n第三十条 列入常务委员会会议议程的法规案，法制委员会、有关专门委员会和法制工作委员会应当广泛听取各方面的意见。听取意见可以采取座谈会、论证会、听证会等多种形式。\n法规案中有关问题专业性较强的，专门委员会可以组织有关方面专家、学者或者专业工作者进行论证。论证情况应当向常务委员会报告。\n法规案有关问题存在重大意见分歧或者涉及利益关系重大调整的，可以组织听证会，听取有关基层和群体代表、部门、人民团体、专家、市人民代表大会代表和社会有关方面的意见。听\n证情况应当向常务委员会报告。\n第三十一条 列入常务委员会会议议程的法规案，法制工作委员会应当在常务委员会会议后将法规草案及其说明等向社会公布，征求意见。向社会公布征求意见的时间一般不少于三十日\n。\n法制工作委员会应当将法规草案发送下级人民代表大会常务委员会、相关领域的市人民代表大会代表以及有关部门、团体、组织和专家征求意见。\n法制工作委员会应当收集整理常务委员会会议审议的意见和各方面提出的意见以及其他有关资料，分送法制委员会和有关专门委员会，并根据需要，印发常务委员会会议。\n第三十二条 常务委员会会议审议法规案，可以组织公民旁听和新闻媒体报道。专门委员会和法制工作委员会进行立法调研，可以邀请有关的市人民代表大会代表参加。\n第三十三条 列入常务委员会会议议程的法规案，在交付表决前，提案人要求撤回的，应当提出书面报告，说明理由，经主任会议同意，并向常务委员会报告，对该法规案的审议即行终\n止。\n第三十四条 法规案经常务委员会会议第二次审议后，仍有重大问题需要进一步研究的，经主任会议同意，可以暂不付表决，交法制委员会和有关专门委员会进一步审议，并根据审议情\n况，决定是否提请常务委员会会议第三次审议。\n第三十五条 列入常务委员会会议议程的法规案，因各方面对制定该法规的必要性、可行性等重大问题存在较大意见分歧，搁置审议满两年的，或者因暂不付表决经过两年没有再次列入\n常务委员会会议议程的，由主任会议向常务委员会报告，该法规案终止审议。\n第三十六条 拟提请常务委员会会议表决的法规案，法制工作委员会可以组织对法规草案中主要制度规范的可行性、法规出台时机、法规实施的社会效果和可能出现的问题等进行评估。\n评估情况由法制委员会在修改情况的说明中予以说明。\n第三十七条 法规草案修改稿经常务委员会会议审议，拟提请常务委员会会议表决的，由法制委员会根据常务委员会组成人员的审议意见进行修改，提出法规草案表决稿，由主任会议提\n请常务委员会全体会议表决，由常务委员会全体组成人员的过半数通过。\n表决前，由法制委员会向常务委员会全体会议作关于法规草案修改情况的说明。\n第三十八条 法规草案表决稿交付常务委员会会议表决前，主任会议根据常务委员会会议审议的情况，可以决定将意见分歧较大的重要条款提请常务委员会会议单独表决；根据单独表决\n的情况，可以将法规草案表决稿交付表决，或者暂不付表决，交法制委员会和有关专门委员会进一步审议。\n第三十九条 常务委员会通过的地方性法规，应当自通过之日起十五日内，由常务委员会报请省人民代表大会常务委员会批准；经批准后，由常务委员会发布公告予以公布。","level":2},{"name":"第四章 法规解释","text":"第四十条 市人民代表大会及其常务委员会通过的地方性法规由常务委员会解释。\n常务委员会的法规解释同法规具有同等效力。\n第四十一条 市人民政府、市中级人民法院、市人民检察院、专门委员会以及下级人民代表大会常务委员会可以向常务委员会提出法规解释要求。\n第四十二条 法制工作委员会研究拟订法规解释草案，由主任会议决定列入常务委员会会议议程。\n法规解释草案经常务委员会会议审议，由法制委员会根据常务委员会组成人员的审议意见，提出法规解释草案表决稿。\n第四十三条 法规解释草案表决稿由常务委员会全体组成人员的过半数通过。常务委员会的法规解释作出后，应当自公布之日起三十日内报省人民代表大会常务委员会备案。法规解释的\n公布适用本条例第五章有关规定。","level":1},{"name":"第五章 其他规定","text":"第四十四条 提出法规案，应当同时提出法规草案文本及其说明，并提供必要的参阅资料。修改法规的，还应当提交修改前后的对照文本。法规草案的说明应当包括制定该法规的必要性\n、可行性和主要内容以及起草过程中对重大分歧问题的协调处理情况。\n第四十五条 向市人民代表大会及其常务委员会提出的法规案，在列入会议议程前，提案人有权撤回，但应当以书面形式提出。\n第四十六条 交付市人民代表大会及其常务委员会全体会议表决未获得通过的法规案，提案人可以按规定程序就同一事项重新提出议案，由主席团、主任会议决定是否列入会议议程。其\n中，未获得市人民代表大会通过的法规案，应当提请市人民代表大会审议决定。\n第四十七条 地方性法规经批准后，常务委员会应当发布公告予以公布，及时在常务委员会公报刊登，并自公告之日起十五日内在《随州日报》上刊登。\n公布地方性法规的公告应当载明该地方性法规的制定机关、批准机关和通过、批准、施行的日期。\n对涉及公民、法人和其他组织权利义务以及其他重要事项的法规，从公布到施行的日期，一般不得少于六十日。\n第四十八条 法规的修改和废止程序，适用本条例第三章的有关规定。\n法规部分条文被修改的，应当公布新的法规文本。\n第四十九条 法规明确要求有关机关对专门事项作出配套规定的，有关机关应当自法规施行之日起一年内作出规定。法规另有规定的，从其规定。\n有关机关未能在期限内作出配套规定的，应当向常务委员会报告。\n第五十条 有关专门委员会、法制工作委员会应当组织对有关法规或者法规中有关规定进行立法后评估。评估情况应当向常务委员会报告。\n第五十一条 制定和修改后的法规实施满一定期限的，法规实施机关应当向常务委员会报告法规实施情况。\n第五十二条 市人民代表大会及其常务委员会制定的地方性法规应当自公布之日起十五日内由常务委员会报省人民代表大会常务委员会，由省人民代表大会常务委员会报全国人民代表大\n会常务委员会和国务院备案。\n第五十三条 法制工作委员会可以对市人民代表大会及其常务委员会制定的地方性法规具体应用的询问予以答复，并报常务委员会备案。","level":1},{"name":"第六章 附则","text":"第五十四条 本条例自公布之日起施行。","level":1}]},{"id":"h0203","sections":[{"name":"第一章 总则","text":"第一条 为保证本省各级人民代表大会代表依法行使代表的职权，履行代表的义务，发挥代表作用，根据《中华人民共和国全国人民代表大会和地方各级人民代表大会代表法》等法律的规定，结合本省实际，制定本办法。\n第二条 本省地方各级人民代表大会代表依照法律规定选举产生，是地方各级国家权力机关组成人员。\n代表每届任期五年，从每届本级人民代表大会举行第一次会议开始，到下届本级人民代表大会举行第一次会议为止。\n第三条 代表应当坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚定不移走中国特色社会主义政治发展道路，依照宪法和法律赋予本级人民代表大会的各项职权，遵循民主集中制原则，参加行使国家权力。\n第四条 代表应当以坚持好、完善好、运行好人民代表大会制度为己任，做到政治坚定、服务人民、尊崇法治、发扬民主、勤勉尽责，为各级人民代表大会及其常务委员会建设自觉坚持中国共产党领导的政治机关、保证人民当家作主的国家权力机关、全面担负宪法法律赋予的各项职责的工作机关、始终同人民群众保持密切联系的代表机关而积极履职。\n第五条 代表应当坚持以人民为中心，践行全过程人民民主，始终同人民群众保持密切联系，忠实代表人民的利益和意志，自觉接受人民监督。\n第六条 代表应当忠于宪法，弘扬宪法精神，维护宪法权威，维护社会主义法制的统一和尊严，为推进全面依法治国、建设更高水平的社会主义法治国家贡献力量。\n第七条 代表享有下列权利：\n（一）出席本级人民代表大会会议，参加审议各项议案、报告和其他议题，发表意见；\n（二）依法联名提出议案、质询案、罢免案等；\n（三）提出对各方面工作的建议、批评和意见；\n（四）参加本级人民代表大会的各项选举；\n（五）参加本级人民代表大会的各项表决；\n（六）参加本级人民代表大会闭会期间统一组织的履职活动；\n（七）获得依法履职所需的信息资料和各项保障；\n（八）法律法规规定的其他权利。\n第八条 代表应当履行下列义务：\n（一）模范地遵守宪法和法律法规，保守国家秘密，在自己参加的生产、工作和社会活动中，协助宪法和法律法规的实施；\n（二）按时出席本级人民代表大会会议，认真审议各项议案、报告和其他议题，发表意见，参加选举和表决，遵守会议纪律，做好会议期间的各项工作；\n（三）带头宣传贯彻本级人民代表大会会议精神；\n（四）积极参加统一组织的视察、专题调研、执法检查等履职活动；\n（五）加强履职学习和调查研究，不断提高履职能力；\n（六）与原选区选民或者原选举单位和人民群众保持密切联系，听取和反映他们的意见和要求，努力为人民服务；\n（七）带头践行社会主义核心价值观，铸牢中华民族共同体意识，自觉遵守社会公德、职业道德，廉洁自律，公道正派，勤勉尽责；\n（八）法律法规规定的其他义务。\n第九条 代表依照《中华人民共和国全国人民代表大会和地方各级人民代表大会代表法》及本办法的规定，在本级人民代表大会会议期间的工作和在本级人民代表大会闭会期间的活动，都是执行代表职务。\n本省各级国家机关、社会团体、企业事业单位等应当为代表执行代表职务提供支持和保障。\n代表不脱离各自的生产和工作。代表出席本级人民代表大会会议，参加闭会期间统一组织的履职活动，应当安排好本人的生产和工作，优先执行代表职务。\n第十条 代表受原选区选民或者原选举单位的监督。\n第十一条 县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团应当密切同代表的联系，丰富代表联系人民群众的内容和形式，加强代表工作能力建设，支持和保障代表依法履职，充分发挥代表作用。\n本省各级人民政府、监察委员会、人民法院、人民检察院应当加强同代表的联系，听取代表的意见和建议，加强和改进各方面工作。\n第十二条 有下列情形之一的，县级以上的地方各级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团给予褒扬激励：\n（一）代表议案、建议、批评和意见等发挥重要作用的；\n（二）代表小组、代表联络站做出突出贡献的；\n（三）有关机关、组织高质量办理代表建议、批评和意见的；\n（四）有关机关、组织密切联系代表、联系人民群众的；\n（五）其他在代表工作中发挥重要作用的。\n县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团应当通过多种方式宣传代表依法履职、发挥作用的典型事迹，展现代表践行全过程人民民主的生动实践。","level":1},{"name":"第二章 代表在本级人民代表大会会议期间的工作","text":"第十三条 代表应当按时出席本级人民代表大会会议。代表因健康等特殊原因不能出席会议的，应当在会议前向本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团书面请假。未经批准，不得缺席会议。\n在人民代表大会会议期间，代表不能出席大会全体会议的，应当向代表团书面请假，报大会秘书处或者乡、民族乡、镇的人民代表大会主席团批准；代表不能出席代表团全体会议、小组会议的，应当报代表团批准。\n第十四条 代表在出席本级人民代表大会会议前，应当通过走访、调研、座谈等多种方式听取原选区选民或者原选举单位以及人民群众的意见和要求，根据安排认真研读拟提请会议审议的议案和报告，为会议期间执行代表职务做好准备。\n第十五条 县级以上的地方各级人民代表大会代表按照选举单位、行政区域等组成代表团。乡、民族乡、镇的人民代表大会代表根据实际需要，可以组成代表团。\n代表根据大会主席团、代表团的组织和安排，参加大会全体会议、代表团全体会议、小组会议，审议列入会议议程的各项议案、报告和其他议题。\n代表可以被推选或者受邀请列席主席团会议、专门委员会会议，发表意见。\n代表应当围绕会议议题发表意见，遵守议事规则。\n第十六条 县级以上的地方各级人民代表大会代表十人以上联名，乡、民族乡、镇的人民代表大会代表五人以上联名，在大会主席团决定的截止时间前，有权依照法律规定的程序向本级人民代表大会书面提出属于本级人民代表大会职权范围内的议案。\n议案应当有案由、案据和方案，案由明确清楚，案据充分合理，方案具体可行。不符合要求的，可以经修改后重新提出或者改作代表建议、批评和意见提出。\n第十七条 代表依法提出的议案，由本级人民代表大会主席团决定是否列入会议议程，或者先交有关的专门委员会审议、提出是否列入会议议程的意见，再决定是否列入会议议程。\n专门委员会审议代表提出的议案时，可以邀请提出议案的代表列席会议，发表意见。\n列入会议议程的议案，在交付大会表决前，提出议案的代表要求撤回的，经主席团同意，会议对该项议案的审议即行终止。\n经主席团通过的关于代表提出议案处理意见的报告应当印发大会。\n第十八条 代表参加本级人民代表大会的各项选举，有权依照法律规定对选举的人选提出意见。\n省人民代表大会代表三十人以上联名，设区的市和自治州的人民代表大会代表二十人以上联名，县级的人民代表大会代表十人以上联名，有权依照法律规定的程序提出本级人民代表大会常务委员会组成人员、人民政府领导人员、监察委员会主任、人民法院院长、人民检察院检察长的人选。\n县级以上的地方各级人民代表大会代表十人以上联名，有权依照法律规定的程序提出上一级人民代表大会代表的人选。\n乡、民族乡、镇的人民代表大会代表十人以上联名，有权依照法律规定的程序提出本级人民代表大会主席、副主席和人民政府领导人员的人选。\n代表有权对本级人民代表大会主席团的人选，提出意见。\n代表对确定的候选人，可以投赞成票，可以投反对票，也可以投弃权票；表示反对的，可以另选他人。\n县级以上的地方各级人民代表大会代表参加表决通过本级人民代表大会各专门委员会组成人员的人选。\n第十九条 代表在审议议案和报告时，可以向本级有关国家机关提出询问。有关国家机关应当派负责人或者负责人员到会听取意见，回答询问；需要进一步研究的，有关国家机关应当认真研究处理，在闭会后两个月内向代表反馈处理情况。\n第二十条 县级以上的地方各级人民代表大会代表十人以上联名，有权依照法律规定的程序提出对本级人民政府及其所属各部门、监察委员会、人民法院、人民检察院的质询案。\n乡、民族乡、镇的人民代表大会代表十人以上联名，有权依照法律规定的程序提出对本级人民政府的质询案。\n质询案应当写明质询对象、质询的问题和内容。\n质询案按照主席团的决定由受质询机关答复。提出质询案的代表半数以上对答复不满意的，可以要求受质询机关再作答复。\n第二十一条 县级以上的地方各级人民代表大会十分之一以上代表联名，有权依照法律规定的程序提出对本级人民代表大会常务委员会组成人员、人民政府组成人员、监察委员会主任、人民法院院长、人民检察院检察长以及由本级人民代表大会选出的上一级人民代表大会代表的罢免案。\n乡、民族乡、镇的人民代表大会五分之一以上代表联名，有权依照法律规定的程序提出对本级人民代表大会主席、副主席和人民政府领导人员的罢免案。\n罢免案应当写明罢免的理由。\n第二十二条 县级以上的地方各级人民代表大会十分之一以上代表联名，有权依法提议组织关于特定问题的调查委员会。\n第二十三条 代表参加本级人民代表大会表决，可以表示赞成，可以表示反对，也可以表示弃权。\n第二十四条 代表有权向本级人民代表大会提出对各方面工作的建议、批评和意见。建议、批评和意见应当明确具体，注重反映实际情况和问题。","level":1},{"name":"第三章 代表在本级人民代表大会闭会期间的活动","text":"第二十五条 县级以上的地方各级人民代表大会常务委员会组织本级人民代表大会代表开展闭会期间的活动。\n县级以上的地方各级人民代表大会常务委员会受上一级人民代表大会常务委员会的委托，组织本级人民代表大会选举产生的上一级人民代表大会代表开展闭会期间的活动。\n乡、民族乡、镇的人民代表大会主席、副主席根据主席团的安排，组织本级人民代表大会代表开展闭会期间的活动。\n第二十六条 代表在闭会期间的活动以集体活动为主，以代表小组活动为基本形式。代表可以通过多种方式听取、反映原选区选民或者原选举单位以及人民群众的意见和要求。\n县、自治县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表分工联系选民。\n第二十七条 代表在本级或者下级人民代表大会常务委员会以及乡、民族乡、镇的人民代表大会主席团协助下，可以按照便于组织和开展活动的原则，根据选区、工作单位、居住状况等，组成地域代表小组。\n代表在县级以上的地方各级人民代表大会各专门委员会和常务委员会工作机构的协助下，可以按照专业和行业特点，组成领域代表小组。\n代表小组应当推选小组召集人。小组召集人负责组织制定小组年度活动计划，常态化开展活动。\n县级以上的各级人民代表大会代表，可以参加下级人民代表大会代表的代表小组活动。\n第二十八条 代表小组活动的主要内容包括：\n（一）学习、宣传宪法和法律法规；\n（二）开展视察；\n（三）进行调查研究；\n（四）了解各项法律法规的贯彻实施情况；\n（五）听取和反映人民群众的意见和要求；\n（六）开展代表履职经验交流活动；\n（七）法律法规规定的其他代表活动。\n第二十九条 县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团按照就地就近的原则，定期组织和协助本行政区域内的代表开展联系人民群众的活动，健全吸纳民意、汇集民智的工作机制，发挥代表在践行全过程人民民主中的作用。\n县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团根据安排，组织开展代表主题活动，推动解决关系人民群众切身利益、社会普遍关注的问题，服务经济社会高质量发展。\n第三十条 县级以上的地方各级人民代表大会代表根据本级人民代表大会常务委员会的安排，对本级或者下级国家机关和有关单位的工作进行视察。乡、民族乡、镇的人民代表大会代表根据本级人民代表大会主席团的安排，对本级人民政府和有关单位的工作进行视察。根据安排，省、设区的市、自治州的人民代表大会代表也可以在本行政区域内跨原选举单位进行视察。\n代表按照前款规定进行视察，可以提出约见本级或者下级有关国家机关负责人。被约见的有关国家机关负责人或者由其委托的负责人员应当听取代表的建议、批评和意见，及时研究处理，并按照规定的时限将有关处理情况答复代表。\n代表可以持代表证就地进行视察。县级以上的地方各级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团根据代表的要求，联系安排本级或者上级的代表持代表证就地进行视察。\n第三十一条 代表根据本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团的安排，围绕经济社会发展和关系人民群众切身利益、社会普遍关注的重大问题、重大事项，以及本级人民代表大会常务委员会重点工作，开展专题调研。根据安排，省、设区的市、自治州的人民代表大会代表也可以在本行政区域内跨原选举单位开展专题调研。\n第三十二条 代表参加视察、专题调研活动形成的报告，由本级人民代表大会常务委员会办事机构、工作机构或者乡、民族乡、镇的人民代表大会主席团转交有关机关、组织。有关机关、组织对报告中提出的意见和建议的研究处理情况应当及时向代表和交办机构反馈。\n代表参加视察、专题调研活动时，可以向有关机关、组织提出建议、批评和意见，但不直接处理问题。\n第三十三条 代表有权依照法律规定的程序提议临时召集本级人民代表大会会议。\n第三十四条 县级以上的地方各级人民代表大会代表可以应邀列席本级人民代表大会常务委员会会议、本级人民代表大会各专门委员会会议，并可以应邀参加本级人民代表大会常务委员会、各专门委员会和常务委员会办事机构、工作机构组织的有关会议；根据安排参加本级人民代表大会常务委员会组织的执法检查、专题询问等活动，或者各专门委员会和常务委员会办事机构、工作机构组织的有关活动。\n乡、民族乡、镇的人民代表大会代表参加本级人民代表大会主席团组织的执法检查和其他活动。\n第三十五条 全国人民代表大会代表，省、设区的市、自治州的人民代表大会代表可以列席原选举单位的人民代表大会会议，并可以应邀列席原选举单位的人民代表大会常务委员会会议。\n县级的人民代表大会代表可以列席原选区所在的乡、民族乡、镇的人民代表大会会议。\n第三十六条 县级以上的地方各级人民代表大会代表根据本级人民代表大会或者本级人民代表大会常务委员会的决定，参加关于特定问题的调查委员会。\n第三十七条 代表在本级人民代表大会闭会期间，有权向本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团提出对各方面工作的建议、批评和意见。\n第三十八条 县级以上的地方各级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团应当根据代表进村、社区联系人民群众等履职需要，做好组织安排。\n第三十九条 代表向本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团反映的人民群众提出的意见和要求，由本级人民代表大会常务委员会办事机构、工作机构或者乡、民族乡、镇的人民代表大会主席团交有关机关、组织研究办理。有关机关、组织应当按照规定的时限办理并反馈交办机构，交办机构应当及时向代表和人民群众反馈。","level":1},{"name":"第四章 代表执行职务的保障","text":"第四十条 代表在人民代表大会各种会议上的发言和表决，不受法律追究。\n第四十一条 县级以上的地方各级人民代表大会代表，非经本级人民代表大会主席团许可，在本级人民代表大会闭会期间，非经本级人民代表大会常务委员会许可，不受逮捕或者刑事审判。如果因为是现行犯被拘留，执行拘留的机关应当立即向该级人民代表大会主席团或者人民代表大会常务委员会报告。\n对县级以上的地方各级人民代表大会代表，如果采取法律规定的其他限制人身自由的措施，应当经该级人民代表大会主席团或者人民代表大会常务委员会许可。\n人民代表大会主席团或者常务委员会受理有关机关依照本条规定提请许可的申请，应当审查是否存在对代表在人民代表大会各种会议上的发言和表决进行法律追究，或者对代表提出建议、批评和意见等其他执行职务行为打击报复的情形，并据此作出决定。\n乡、民族乡、镇的人民代表大会代表，如果被逮捕、受刑事审判、或者被采取法律规定的其他限制人身自由的措施，执行机关应当立即报告乡、民族乡、镇的人民代表大会。\n第四十二条 代表在本级人民代表大会闭会期间，参加统一组织和安排的代表履职活动，由本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会主席团提前书面告知代表所在单位，代表所在单位必须给予时间保障。\n第四十三条 代表依法执行代表职务，其所在单位应当支持，按正常出勤对待，保证其工资和其他待遇不受影响。\n无固定工资收入的代表依法执行代表职务，由本级财政按照有关规定给予适当补贴。\n代表依法执行代表职务，按照有关规定给予往返的旅费和必要的物质上的便利或者补贴。\n本省行政区域内的民航、铁路、交通、邮电等单位，应当为代表依法执行代表职务提供便利条件。\n第四十四条 代表活动、代表履职学习培训等经费以及代表依法执行代表职务的相关补贴，应当列入本级财政预算予以保障。乡、民族乡、镇财政困难的，由上级财政给予支持。\n县级以上的地方各级人民代表大会常务委员会应当统筹制定本行政区域内代表经费和补贴管理制度，明确使用范围、标准和程序等，确保专款专用。\n第四十五条 县级以上的地方各级人民代表大会常务委员会制定年度代表工作计划，依法统筹组织和安排代表履职活动，增强代表履职活动的计划性、组织性和规范性。\n年度代表工作计划由主任会议通过，向本级人民代表大会代表通报，并向社会公布。\n第四十六条 县级以上的地方各级人民代表大会常务委员会应当采取多种方式同本级人民代表大会代表保持联系，建立健全常务委员会组成人员、各专门委员会和常务委员会办事机构、工作机构联系代表的工作机制，扩大代表对立法、监督等各项工作的参与。\n乡、民族乡、镇的人民代表大会主席、副主席在本级人民代表大会闭会期间负责联系本级人民代表大会代表。\n县级的人民代表大会常务委员会在街道设立的工作机构负责联系辖区内的代表，组织代表开展活动，反映代表和人民群众的建议、批评和意见。\n第四十七条 县级以上的地方各级人民代表大会常务委员会应当加强同本行政区域内的代表的联系，为代表依法履职提供必要的条件。\n县级以上的地方各级人民代表大会常务委员会应当建立健全代表履职网络平台，为代表依法履职、反映人民群众的意见、加强履职学习培训等提供便利和服务。\n第四十八条 县级的人民代表大会常务委员会应当综合考虑选区划分、代表分布等因素，统筹规划本行政区域内的代表联络站建设，与党群服务中心、政务服务中心、基层立法联系点等共建共管。省、设区的市、自治州的人民代表大会常务委员会应当加强指导。\n代表联络站应当建立代表进站履职工作机制，健全代表联系选民、接待群众、履职管理、履职信息公示等制度，科学制定活动计划，丰富活动内容和形式，提高代表联络站运行质量。\n第四十九条 县级以上的地方各级人民代表大会常务委员会和各级人民政府及其所属各部门、监察委员会、人民法院、人民检察院，应当及时向本级人民代表大会代表通报工作情况，提供信息资料，保障代表的知情权。\n代表根据依法履职需要，可以要求有关机关、组织提供拟提议案以及建议、批评和意见涉及的相关信息资料，有关机关、组织应当提供，但涉及国家秘密、商业秘密、个人隐私等不宜公开的内容除外。\n本省各级人民政府及其所属各部门、监察委员会、人民法院、人民检察院，根据本级人民代表大会常务委员会的统筹安排，邀请代表参与相关工作和活动，听取代表的意见和建议。\n第五十条 县级以上的地方各级人民代表大会常务委员会应当有计划、有针对性地组织代表参加初任学习、履职基础学习、专题学习等履职学习培训和交流，提高代表履职能力。\n代表应当学习贯彻中国共产党的理论和路线、方针、政策，熟悉宪法和人民代表大会制度，掌握履职所需的法律知识和其他专业知识。\n乡、民族乡、镇的人民代表大会代表应当参加上级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团组织的代表履职学习培训。县级的人民代表大会常务委员会应当将乡、民族乡、镇的人民代表大会代表履职学习培训纳入本级代表工作计划。\n第五十一条 县级以上的地方各级人民代表大会常务委员会的办事机构和代表工作委员会等工作机构是代表执行代表职务的集体服务机构，为代表执行代表职务提供服务保障。\n第五十二条 为了便于代表执行代表职务，本省地方各级人民代表大会应当为本级人民代表大会代表制发代表证。\n第五十三条 县级以上的地方各级人民代表大会专门委员会审议本级人民代表大会主席团交付的代表议案，应当与代表联系沟通，充分听取意见，并及时通报情况。\n第五十四条 县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团应当制定代表建议、批评和意见办理工作制度，明确交办、承办、督办等工作程序和要求。\n有关机关、组织应当将代表建议、批评和意见办理工作纳入年度工作计划，主要负责人应当认真组织研究。在办理过程中，应当与代表见面沟通，充分听取代表意见，并自交办之日起三个月内答复。涉及面广、处理难度大的建议、批评和意见，应当自交办之日起六个月内答复。\n代表对答复不满意的，有关机关、组织应当按照有关规定重新办理。重新办理后仍不满意的，县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团应当听取代表意见，会同本级人民政府或者有关机关、组织研究并向代表说明办理情况。\n第五十五条 县级以上的地方各级人民代表大会有关专门委员会和常务委员会办事机构、工作机构，乡、民族乡、镇的人民代表大会主席团，应当加强与有关机关、组织的联系、协调，通过调研、视察、开展满意度测评等多种方式，加强对代表建议、批评和意见的督办。\n主任会议可以围绕经济社会发展和关系人民群众切身利益、社会普遍关注的问题，自交办之日起一个月内，确定重点督办的代表建议、批评和意见，由主任会议成员、有关专门委员会和常务委员会工作机构负责重点督办。重点督办工作情况应当向主任会议报告。\n代表建议、批评和意见的办理情况，由常务委员会办事机构、工作机构或者有关机关、组织向代表反馈，并向本级人民代表大会常务委员会报告，印发下一次人民代表大会会议；或者由乡、民族乡、镇的人民代表大会主席团或者有关机关、组织向代表反馈，并向乡、民族乡、镇的人民代表大会报告。代表建议、批评和意见办理情况的报告，应当予以公开。\n县级以上的地方各级人民代表大会常务委员会代表工作委员会应当会同有关专门委员会和常务委员会办事机构、工作机构做好代表建议、批评和意见办理工作的指导和服务。\n第五十六条 少数民族代表执行代表职务时，有关部门和单位应当在语言文字、生活习惯等方面给予必要的帮助和照顾。\n身体残疾或者其他行动不便的代表执行代表职务时，有关部门和单位应当根据需要给予必要的帮助和照顾。\n第五十七条 一切组织和个人都必须尊重代表的权利，支持代表执行代表职务。\n有义务协助代表执行代表职务而拒绝履行义务的，有关单位应当予以批评教育，直至给予处分。\n阻碍代表依法执行代表职务的，根据情节，由所在单位或者有关机关给予处分，或者适用《中华人民共和国治安管理处罚法》的有关规定给予处罚；以暴力、威胁方法阻碍代表依法执行代表职务的，依照刑法有关规定追究刑事责任。\n对代表依法执行代表职务进行打击报复的，由所在单位或者有关机关责令改正或者给予处分；国家工作人员进行打击报复构成犯罪的，依照刑法有关规定追究刑事责任。","level":1},{"name":"第五章 对代表的监督","text":"第五十八条 代表应当坚定政治立场，履行政治责任，加强思想作风建设，自觉接受监督，自觉维护代表形象。\n第五十九条 代表应当采取多种方式经常听取人民群众对代表履职的意见，回答原选区选民或者原选举单位对代表工作和代表活动的询问，接受监督。\n代表应当以多种方式向原选区选民或者原选举单位报告履职情况。县级以上的地方各级人民代表大会常务委员会和乡、民族乡、镇的人民代表大会主席团应当建立健全代表履职档案，记录代表履职情况，定期组织本级人民代表大会代表向原选区选民或者原选举单位报告履职情况，并公示代表基本信息和履职信息。代表履职情况作为推荐下一届连任代表候选人的重要参考依据。\n不在原选区居住或者不在原选举单位所在地工作的代表，每年应当回原选区或者原选举单位参加代表活动不少于一次。\n第六十条 代表迁出、调离本行政区域或者居住地、工作单位、联系方式等发生变化的，应当及时告知本级和原选举单位的人民代表大会常务委员会工作机构或者乡、民族乡、镇的人民代表大会主席或者副主席。\n第六十一条 代表应当正确处理从事个人职业活动与执行代表职务的关系，不得利用执行代表职务干预具体执法、司法案件，插手招标投标等经济活动或者变相从事商业活动牟取个人利益。\n第六十二条 选民或者选举单位有权依法罢免自己选出的代表。被提出罢免的代表有权出席罢免该代表的会议提出申辩意见，或者书面提出申辩意见。\n第六十三条 代表因法定情形而终止代表资格、被暂时停止执行代表职务的，由代表资格审查委员会向本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会报告。代表资格终止的，由本级人民代表大会常务委员会或者乡、民族乡、镇的人民代表大会予以公告。\n代表被依法终止代表资格的，其所担任的人民代表大会常务委员会组成人员、专门委员会组成人员或者乡、民族乡、镇的人民代表大会主席、副主席的职务相应终止或者撤销，并予以公告。","level":1},{"name":"第六章 附则","text":"第六十四条 本办法自2026年3月1日起施行。","level":1}]},{"id":"h0204","sections":[{"name":"","text":"第一条 为了保护归侨、侨眷的合法权益，根据《中华人民共和国归侨侨眷权益保护法》和《中华人民共和国归侨侨眷权益保护法实施办法》的规定，结合本省实际，制定本办法。\n第二条 华侨是指定居在国外的中国公民。归侨是指回国定居的华侨。\n侨眷是指华侨、归侨在国内的眷属，包括：华侨、归侨的配偶，父母，子女及其配偶，兄弟姐妹，祖父母、外祖父母，孙子女、外孙子女，以及同华侨、归侨有长期抚养关系的其他亲属。\n归侨、侨眷的身份，由其户籍所在地的县级以上（含县级，下同）地方人民政府侨务部门根据其所在工作单位、街道办事处或者乡（镇）人民政府出具的证明审核认定；必要时可以由我国驻外国的外交代表机关、领事机关或者归国华侨联合会组织提供协助。\n华侨、归侨去世后，其国内眷属的侨眷身份不变；因婚姻、抚养关系取得侨眷身份的，在其依法解除婚姻关系或者抚养关系后，其侨眷身份自行丧失。\n同华侨、归侨有5年以上抚养关系的其他亲属，且申请侨眷身份时仍保持抚养关系的，其侨眷身份由公证机关出具抚养公证文书后审核认定。\n第三条 归侨、侨眷依法享有宪法和法律规定的公民的权利，并履行宪法和法律规定的公民的义务。\n国家机关、人民团体、企业事业单位、基层群众性自治组织，应当依照法律、法规的规定，落实侨务政策，保护归侨、侨眷的合法权益。\n第四条 本省各级人民政府侨务部门负责管理本行政区域内的侨务工作，对保护归侨、侨眷合法权益的工作负有统筹、协调、督促、检查的职责。\n第五条 本省各级归国华侨联合会是归侨、侨眷依法成立的人民团体，代表归侨、侨眷的利益，依法维护归侨、侨眷的合法权益。\n归侨、侨眷可以依法组织其他社会团体。\n归侨、侨眷依法组织的社会团体的合法权益受法律保护，其依法拥有的财产，任何组织或者个人不得侵犯。\n第六条 省人民代表大会和归侨、侨眷人数较多的地方人民代表大会，应当有适当名额的归侨、侨眷代表。\n第七条 华侨要求回本省定居的，应当按照《中华人民共和国归侨侨眷权益保护法实施办法》的规定办理有关手续。\n第八条 经批准回本省定居的华侨，各级人民政府和有关部门应当按照下列规定给予安置：\n（一）对回本省定居的华侨科技人员，凡未达到退休年龄的，应当根据本人专长和双向选择的原则优先安置；\n（二）对出境定居不满1年复归，出境前有工作单位且出境时办理了离职手续的，原工作单位或原工作单位的上一级主管部门应当负责安置；\n（三）对回到农村定居、从事农业生产的，当地人民政府应当为其生产和生活提供方便；\n（四）对其他回省定居的，其居住地人民政府应当妥善安置。\n第九条 原籍不在本省，根据国家有关规定经批准来本省定居的华侨，各级人民政府和有关部门参照本办法第七条、第八条的规定执行。\n第十条 鼓励华侨采取兼职、咨询、讲学、科研和技术合作、技术入股、投资兴办企业等形式，来本省创业、工作或者服务，并享受国家和省有关优惠待遇。\n各级人民政府及其有关部门应当及时为在本省创业、工作或者服务的华侨落实有关优惠政策。\n第十一条 归侨、侨眷职工依法享有国家规定的养老、医疗、失业、工伤、生育等社会保障权益。用人单位和归侨、侨眷职工应当依法参加当地的社会保险，缴纳社会保险费用。各级社会保险经办机构必须按时足额支付归侨、侨眷职工依法享受的各项社会保险金。\n对离休、退休、退职的归侨、侨眷的离休金、退休金、退职金和归侨、侨眷退休生活津贴，应当按时足额发放。\n持有非农业户口的归侨、侨眷，凡共同生活的家庭收入低于当地城市居民生活保障标准的，应当确保其享受当地城市居民最低生活保障待遇，并由市（县、市辖区）人民政府再给予一定数额的生活补贴；对丧失劳动能力又无经济来源或者生活确有困难的持有农业户口的归侨、侨眷，由市（县、市辖区）人民政府给予适当救济。\n各级人民政府应当把扶持贫困归侨、侨眷脱贫致富纳入本地扶贫工作整体规划，在项目和资金等方面优先安排。\n第十二条 归侨、侨眷可以依法以各种形式投资兴办工商企业。归侨、侨眷兴办企业的财产所有权及其他合法权益受法律保护。\n本省各级人民政府应当鼓励和支持归侨、侨眷利用自身优势，引进资金、技术和人才，促进当地经济发展；对归侨、侨眷以独资、合资、合作形式兴办的企业，应当按照国家和本省的现行规定给予优惠。\n第十三条 归侨、侨眷投资开发荒山、荒地、滩涂或者从事农、林、牧、副、渔业生产，各级人民政府应当给予支持，其依法取得的土地使用权及其他合法权益受法律保护。\n第十四条 归侨、侨眷接受境外亲友赠与直接用于工农业生产、加工、维修的小型生产工具，以及经批准进口的优良种苗、种畜、种禽、种蛋等，按照国家有关规定办理。\n第十五条 归侨、侨眷在本省兴办公益事业，各级人民政府应当给予支持和保护。\n归侨、侨眷兴办公益事业，当地人民政府应当尊重兴办者的意愿，经过协商议定的所兴办项目的用途、命名等，未征得兴办者的同意，不得随意更改，其资金不得侵占或者挪用。\n归侨、侨眷接受境外亲友赠与的物资，直接用于公益事业的，由举办该项公益事业的组织提出申请，经有关主管部门核准，依照法律、行政法规的规定享受减征或者免征关税和进口环节增值税的待遇。\n第十六条 归侨、侨眷在本省境内依法拥有的私有房屋，受法律保护。归侨、侨眷对其私有房屋，依法享有占有、使用、收益和处分的权利，任何组织或者个人都不得侵占或者非法拆迁。\n第十七条 凡单位或者个人租用归侨、侨眷私有房屋，必须事先征得产权人的同意，按规定签订租赁合同，并到房屋所在地的房地产管理机关登记备案。\n租赁合同终止时，承租人应当将房屋退还给出租人。承租人愿意继续租赁，出租人表示同意的，应当续签租赁合同。\n承租人违反租赁合同的，出租人可以解除租赁合同，收回房屋使用权。\n第十八条 因公共利益需要征收归侨、侨眷私有房屋的，市、县级人民政府及其房屋征收部门应当依照有关法律法规的规定，作出征收决定，签订征收补偿协议，并给予妥善安置补偿。\n第十九条 归侨、华侨子女、归侨子女报考各类学校，享受以下照顾：\n（一）报考普通高等学校的，在所报录取学校投档分数线下降低10分投档；\n（二）报考成人高等学校的，在所报录取学校投档分数线下降低20分投档；\n（三）报考普通高中的，在其考试总分基础上加5分。\n第二十条 归侨、侨眷在本省就业的，各级人民政府及其有关部门应当在职业培训、向用人单位推荐等方面对其予以扶持和帮助。用人单位对符合录用条件的归侨、侨眷应优先录用。\n对已失业的归侨、侨眷职工，当地人民政府及其有关部门、企事业单位应当在同等条件下优先培训，优先推荐，优先录用，帮助其再就业。\n第二十一条 归侨，华侨、归侨的配偶、子女、孙子女、外孙子女、兄弟姐妹及其子女，申请自费出国留学，符合国家有关规定的，有关部门应当优先审批。对其中具有大学或者大学以上学历的，按国家有关规定应当给予优惠待遇。\n第二十二条 归侨，华侨、归侨的配偶、子女、孙子女、外孙子女、兄弟姐妹及其子女，获准自费出国留学，本人属在职职工的，自获准离境之日起，可以保留公职1年；属于高等院校在校学生的，其学籍管理按照有关规定办理，本人要求保留学籍的，可以保留学籍1年。\n归侨、侨眷自费出国学习，学成回国要求国家安排工作的，按照公派留学生对待。\n第二十三条 国家或者有关单位派出公费留学生要求回省工作，属于归侨、侨眷的，在同等条件下优先安排。\n第二十四条 华侨子女在国内监护人所在地就读幼儿园、中小学的，应当视同就读地居民子女办理就学手续，收费按国家和省有关规定执行。\n第二十五条 归侨、侨眷的合法侨汇收入，受国家法律保护。经办侨汇的银行应当及时兑付侨汇，任何单位和个人都不得强索、侵吞、冒领、冻结、截留和克扣。\n归侨、侨眷依法享有使用侨汇的自由，任何单位和个人不得干涉。\n第二十六条 归侨、侨眷因继承或者接受境外亲友的遗产或者赠与以及处理其在境外的财产需要办理有关手续的，有关部门应当按照国家有关规定及时办理，并提供必要的帮助。\n第二十七条 归侨、侨眷与境外亲友的合法联系与往来受法律保护。任何组织或者个人不得非法限制和干涉，有关单位和部门应当提供方便。\n任何单位或者个人不得毁弃、隐匿或者私拆归侨、侨眷的邮件。归侨、侨眷的邮件发生丢失、损毁、内件短少的，邮政企业应当按照有关法律、法规的规定给予赔偿，或者及时采取补救措施。\n第二十八条 归侨、侨眷向户口所在地公安机关提出出境申请，公安机关应当在规定期限内作出审批决定，并且通知申请人。\n申请人在规定期限内未收到审批决定通知的，有权提出查询，公安机关应当及时作出答复。\n归侨、侨眷因境外亲属病危、死亡或者限期处理境外财产等特殊情况急需出境，并符合出境条件的，公安机关应当优先办理手续。\n第二十九条 国家机关、人民团体和国有及其控股企业事业单位的归侨、侨眷职工经批准出境探亲的，可以按照有关规定享受探亲假和报销国内旅费；探亲假期间的工资和补贴，享受国内其他职工探亲的同等待遇；境外的旅费和在境外的医疗费自理。\n非国有及其控股企业事业单位的归侨、侨眷职工获准出境探亲的，参照前款规定办理。\n归侨、侨眷出境探望在境外定居的子女，享受国家规定的关于已婚归侨、侨眷出境探望父母的同等待遇。\n第三十条 国家机关、人民团体和国有及其控股企业事业单位的归侨、侨眷职工，申请出境定居并离职的，其离职手续的办理和离职金的发放，按照国家的有关规定办理；发放的离职金可以按照有关规定兑换外币汇出或携带出境。\n国家机关、人民团体和国有及其控股企业事业单位的离休、退休、退职的归侨、侨眷职工出境定居后，可以按照规定委托亲友或者采取其他方式定期向有关机构提出申请，经核实后，继续领取离休金、退休金、退职金等补贴，并允许兑换外币汇出境外。\n非国有及其控股企业事业单位的归侨、侨眷职工申请离职出境定居或者退休、退职的归侨、侨眷职工出境定居的，其离职金、退休金、退职金的发放事项，可以参照本条第一款、第二款的规定办理。\n第三十一条 归侨、侨眷申请出境，各单位不得作出损害其合法权益的规定。在获得前往国家（地区）的入境签证前，所在单位不得因其申请出境而要求其停职、停薪、离职、免职或者退学，不得自行规定收取保证金、抵押金。\n第三十二条 归侨、侨眷全家获准出境定居的，可以要求保留原承租居住的公房1年。离休、退休的归侨、侨眷职工获准出境定居的，在房改中享受国内其他职工同等的待遇。\n归侨、侨眷出境探亲因私逾假未归，或者作为公房承租人自费出国留学，申请保留公有房屋租赁使用权的，在交纳租金的前提下，可以保留3年。\n获准出境定居的归侨、侨眷出境前，按照国家和地方的房改政策购买的住房，出境定居后房产权属不变。\n第三十三条 归侨、侨眷职工出境定居后1年内又回本省定居，按照国家有关规定经批准安排工作的，退回离职金，且补足出境期间的养老保险金后，其工龄可以连续计算。出境在1年以上的，参照本办法第八条的规定执行，其出境前的工龄和入境后的工龄合并计算连续工龄。\n第三十四条 在国家机关、人民团体、企业事业单位工作的归侨，在人员精简、企业改制中应当照顾，妥善安排。\n第三十五条 对违反本办法，有下列行为之一的，视情节轻重，由有关主管部门给予批评教育、责令改正、处分或者行政处罚；构成犯罪的，由司法机关依法追究刑事责任：\n（一）侵占、破坏归侨、侨眷合法组织的财产的；\n（二）侵害归侨、侨眷兴办企业的合法权益的；\n（三）侵占或非法拆除归侨、侨眷房屋的；\n（四）敲诈、勒索归侨、侨眷财物的；\n（五）侵害归侨、侨眷通讯自由和通信秘密的；\n（六）停发、扣发、侵占或者挪用出境定居的归侨、侨眷的离休金、退休金、退职金、养老金的；\n（七）侵害归侨、侨眷其他合法权益的。\n第三十六条 归侨、侨眷在其合法权益受到侵害时，有权要求侨务行政主管部门或者其他有关部门依法处理，受理部门应当在接到书面要求之日起30日内处理，并将处理结果告知申请人；归侨、侨眷也可以依法向人民法院提起诉讼。\n第三十七条 国家机关工作人员玩忽职守或者滥用职权，致使归侨、侨眷合法权益受到损害的，其所在单位或者上级主管机关应当责令改正或者给予处分；构成犯罪的，依法追究刑事责任。\n第三十八条 香港、澳门同胞及外籍华人居住在本省的眷属合法权益的保护，参照本办法执行。\n第三十九条 本办法自公布之日起施行。","level":0}]},{"id":"h0205","sections":[{"name":"","text":"为了规范政府规章设定行政处罚罚款的行为，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》第十四条的规定，结合我省实际，对政府规章设定行政处罚罚款的限额作如下规定：\n一、对非经营活动中的违反行政管理秩序行为，设定罚款数额不得超过5000元。\n二、对经营活动中的违反行政管理秩序行为，有违法所得的，设定罚款数额不得超过违法所得的3倍，但最高不得超过15万元；没有违法所得的，设定罚款数额不得超过5万元。\n三、政府规章可以在罚款限额规定的范围内，根据过罚相当的原则，对非经营活动和经营活动中公民、法人或者其他组织违反行政管理秩序的行为设定不同幅度的罚款。\n四、本规定自1996年10月1日起施行。","level":0}]},{"id":"h0206","sections":[{"name":"","text":"（2018年1月18日湖北省第十二届人民代表大会常务委员会第三十二次会议通过 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》修正）","level":0},{"name":"第一章 总则","text":"第一条 为了有效保护和合理利用风景名胜资源，加强和规范风景名胜区管理，满足公众对优美生态环境的需要，根据国务院《风景名胜区条例》等有关法律、行政法规的规定，结合本省实际，制定本条例。\n第二条 本省行政区域内的风景名胜区的设立、规划、保护、管理和服务，适用本条例。\n本条例所称风景名胜区，是指经依法设立，具有观赏、文化或者科学价值，自然景观、人文景观比较集中，环境优美，可供公众游览或者进行文化、科学活动的区域。\n第三条 风景名胜区应当遵循科学规划、统一管理、严格保护、永续利用的原则。\n第四条 县级以上人民政府应当加强对风景名胜区工作的领导，将风景名胜资源的保护和利用纳入国民经济和社会发展规划，协调解决保护和管理工作中的重大问题,并将风景名胜资源的保护和利用所需经费纳入本级财政预算。\n第五条 省人民政府林业主管部门负责全省风景名胜区的监督管理工作；省人民政府发展改革、民族宗教、自然资源、生态环境、水行政、住房和城乡建设、文化和旅游、文物等相关部门按照各自职责，做好风景名胜区的有关监督管理工作。\n风景名胜区所在地县级以上人民政府依法设置的风景名胜区管理机构，具体负责风景名胜区保护和统一管理工作。\n乡镇人民政府、街道办事处应当按照职责，协助相关部门和风景名胜区管理机构，做好风景名胜区的有关工作。\n第六条 任何单位和个人都有保护风景名胜资源的义务，并有权制止、检举破坏风景名胜资源的行为。","level":1},{"name":"第二章 设立","text":"第七条 省人民政府林业主管部门应当组织开展风景名胜资源的调查和评估，对自然景观和人文景观符合以下情形之一的，应当督促和指导所在地人民政府依法申请设立风景名胜区：\n（一）珍贵的、不可再生的；\n（二）能够反映重要自然变化过程或者重大历史文化发展过程的；\n（三）基本处于自然状态或者保持历史原貌，具有国家代表性或者区域代表性的。\n第八条 风景名胜区划分为国家级风景名胜区和省级风景名胜区。\n国家级风景名胜区的设立按照法律、行政法规规定的条件和程序执行。\n设立省级风景名胜区，由县级以上人民政府提出申请，省人民政府林业主管部门应当会同发展改革、民族宗教、自然资源、生态环境、水行政、住房和城乡建设、文化和旅游、文物等有关部门组织论证，听取专家和公众的意见，提出审查意见，报省人民政府批准公布。\n第九条 申请设立风景名胜区的人民政府在报请批准前，应当与相关的土地、森林、滩涂、水流等自然资源和建（构）筑物、其他地上附着物等财产的所有权人、使用权人充分协商。\n因设立风景名胜区对相关土地、森林、滩涂、水流等自然资源和建（构）筑物、其他地上附着物等合法财产的所有权人、使用权人造成损失的，应当依法给予补偿，补偿具体办法由省人民政府制定。\n第十条 申请设立风景名胜区的人民政府应当组织有关部门对补偿方案进行论证并征求利益相关方意见，征求意见期限不得少于三十日；必要时应当组织财产的所有权人、使用权人和公众代表听证。\n第十一条 风景名胜区经批准设立并公布后，风景名胜区管理机构应当按照批准的风景名胜区范围及核心景区范围，设置界桩、徽志。\n第十二条 因不可抗力因素导致风景名胜资源遭受严重破坏，省人民政府林业主管部门应当组织进行评估，对不符合风景名胜区设立条件且无法恢复的，国家级风景名胜区由省人民政府提请国务院撤销，省级风景名胜区由省人民政府林业主管部门提请省人民政府撤销。","level":1},{"name":"第三章 规划","text":"第十三条 风景名胜区经批准设立后，应当自批准设立之日起二年内编制完成风景名胜区总体规划，并依法编制风景名胜区详细规划。\n国家级风景名胜区规划由省人民政府林业主管部门组织编制；省级风景名胜区规划由所在地县级人民政府组织编制；跨行政区域的省级风景名胜区规划，由共同的上一级人民政府林业主管部门组织编制。\n风景名胜区总体规划和详细规划按照法律法规和国家技术规范组织编制、征求意见、评估、论证、审批和备案，并符合主体功能区划，与国民经济和社会发展规划、国土空间规划相衔接，严守生态保护红线。\n第十四条 编制镇规划、乡规划、村庄规划时，涉及风景名胜区的，应当符合风景名胜区总体规划的要求，并在报批前征求风景名胜区管理机构的意见；已编制的镇规划、乡规划、村庄规划，不符合风景名胜区总体规划的，应当按照风景名胜区总体规划进行修改和调整。\n第十五条 编制风景名胜区规划，不得在核心景区内规划下列项目、设施或者建（构）筑物：\n（一）索道、室外观光电梯、缆车、风力发电、铁路、高等级公路等重大建设工程项目；\n（二）宾馆、酒店、招待所、培训中心、疗养院等设施；\n（三）大型文化、体育和游乐设施；\n（四）与风景名胜资源保护无关的其他项目、设施或者建（构）筑物。\n确需在风景名胜区核心景区内安排索道、室外观光电梯、缆车工程项目的，组织编制单位应当组织专家进行专题论证，形成专题论证报告，按照法定程序报请批准。\n第十六条 风景名胜区规划报送批准前，组织编制机关应当依法将规划草案予以公示。公示时间不得少于三十日。\n第十七条 风景名胜区规划批准后，应当由风景名胜区规划的组织编制单位和风景名胜区管理机构向社会公布，并为公众查阅提供便利。\n经批准的风景名胜区规划不得擅自修改。确需对风景名胜区总体规划中的风景名胜区范围、性质、保护目标、生态资源保护措施、重大建设项目布局、开发利用强度以及风景名胜区的功能结构、空间布局、游客容量进行修改的，应当报原批准机关批准；对其他内容进行修改的，应当报原批准机关备案。\n风景名胜区详细规划确需修改的，应当报原批准机关批准。\n第十八条 任何单位和个人应当遵守风景名胜区规划，服从规划管理，不得违反规划进行各类建设活动；已经建设的，风景名胜区所在地县级以上人民政府应当按照风景名胜区规划，制定拆迁计划或者方案，限期拆除或者迁出。\n风景名胜区规划未经批准前，任何单位和个人不得在风景名胜区内进行各类建设活动。","level":1},{"name":"第四章 保护","text":"第十九条 风景名胜区管理机构应当建立健全风景名胜资源保护的各项管理制度和技术规范，对风景名胜资源进行调查评估、鉴定登记、建立档案，并会同有关部门按照下列规定进行保护：\n（一）划定生态保护区域，保护野生动植物及其栖息、生长环境，维护生态平衡；\n（二）划定文物古迹、历史建筑、传统民居等保护范围和建设控制地带，设立标志，并采取防火、防洪、避雷、防震、防蛀、防腐、防盗等措施；\n（三）加强对特殊地质地貌、地表水和地下水的管理，防止过度开发利用和水体污染；\n（四）加强护林防火和病虫害防治，保护植被，并对重要景区、景点实施定期封闭养护；\n（五）对古树名木登记造册，设立标志，保护古树名木生长环境和风貌；\n（六）根据风景名胜区的特点，保护民族民间传统文化，开展健康有益的文化活动；\n（七）采取其他保护措施。\n风景名胜区内涉及自然资源保护、文物保护、自然保护区管理、宗教活动场所管理的，法律法规有规定的，从其规定。\n第二十条 在风景名胜区内禁止从事下列活动：\n（一）开山、采石、开矿、开荒、修坟立碑等破坏景观、植被和地形地貌的活动；\n（二）修建储存爆炸性、易燃性、放射性、毒害性、腐蚀性物品的设施；\n（三）填湖建房、围湖造田、筑坝拦汊以及以其他方式侵占和分割水面；\n（四）违反规定养殖、种植、放牧、狩猎、捕捞；\n（五）砍伐或者擅自移植古树名木；\n（六）在禁火区内吸烟、点火、烧香、燃放烟花爆竹或者孔明灯等带有明火的空中飘移物；\n（七）在景物、设施上刻划、涂污或者以其他方式损坏景物、设施；\n（八）乱扔垃圾；\n（九）法律法规规定的其他破坏景观、污染环境的活动。\n第二十一条 风景名胜区内从事本条例禁止活动以外的建设活动，应当经风景名胜区管理机构审核，并依法办理相关建设审批手续。\n经依法批准并按照规划在风景名胜区修建高等级公路、铁路、机场、水库、高压走廊、隧道、索道、室外观光电梯、缆车和大型文化、体育、游乐设施以及宾馆、酒店等建设项目，其选址方案由风景名胜区管理机构初审后，依法报省人民政府林业主管部门核准。\n在风景名胜区内修建其他建设项目的选址方案，由风景名胜区管理机构初审后，报所在地市级林业主管部门核准。\n第二十二条 风景名胜区内建设项目的选址、布局及其造型、风格、色调、高度、体量等，应当与周围景观、文物古迹和生态环境相协调，避免对主要景观造成观赏障碍和游览线路阻断。\n经批准在风景名胜区内进行建设活动，不得破坏景观景物、水体、林草植被、野生动植物资源和地形地貌。\n第二十三条 在风景名胜区从事建设活动的，应当依法开展生态环境影响评价和地质灾害危险性评估，制定污染防治和水土保持方案，采取有效措施，加强对景观景物、水体、林草植被、野生动植物资源、地形地貌的保护，保护和防治工程应当与主体工程同时设计、同时施工、同时投产使用。\n第二十四条 在风景名胜区内从事下列活动，应当经风景名胜区管理机构审核后，依照有关法律法规的规定报有关主管部门批准：\n（一）设置、张贴商业广告；\n（二）举办大型游乐、展销或者进行实景演艺、影视拍摄等活动；\n（三）以围、填、堵、截等方式临时改变水资源、水环境自然状态的活动；\n（四）其他影响生态和景观的活动。\n经批准在风景名胜区内从事前款所列活动，应当制定保护风景名胜资源的方案和措施，不得破坏景物、水体、林草植被、野生动植物资源和地形地貌。\n第二十五条 风景名胜区内的单位、经营者、居民和游客应当保护风景名胜资源，爱护景区内公共设施，维护环境卫生和公共秩序。","level":1},{"name":"第五章 管理和服务","text":"第二十六条 省人民政府林业主管部门应当建立风景名胜区管理信息系统，健全和完善风景名胜区生态环境、资源保护、项目建设、经营服务等方面的管理制度和规范，对风景名胜区规划编制和实施情况、风景名胜资源保护状况等进行监督检查和评估，指导、监督风景名胜区管理机构依法履行风景名胜区保护和管理职责。\n风景名胜区管理机构应当每年向省人民政府林业主管部门报送风景名胜区规划实施和风景名胜资源保护的情况；省人民政府林业主管部门应当每年将风景名胜区规划实施和资源保护情况报送省人民政府。\n第二十七条 风景名胜区管理机构应当建立健全信息公开制度，做好风景名胜区监管信息平台建设和管理工作，及时提供风景名胜资源、保护管理、旅游路线、游客容量、天气等相关信息。\n第二十八条 风景名胜区管理机构应当根据风景名胜区规划，合理利用风景名胜资源，制定游客流量控制方案，对游客进行最大承载量控制，实施动态监测、预警预报；游客数量达到最大承载量时，应当采取疏导、分流等措施，保障游览活动有序、正常和安全进行。禁止超过最大承载量接纳游客。\n第二十九条 风景名胜区管理机构应当在风景名胜区完善以下服务设施：\n（一）设置服务设施和游览导向等标志；\n（二）按照规定和标准，设置游客服务中心和供水、供电、公共厕所等配套服务设施以及垃圾分类收运、污水处理等设施；\n（三）建设残疾人、老年人、未成年人、孕妇旅游服务设施，提供语音提示等无障碍信息服务，配备出行辅助器具。\n第三十条 风景名胜区管理机构应当建立健全安全保障制度，加强消防等安全设施建设，配备安全保障人员，保障游客安全，做好下列游览安全保障工作：\n（一）在危险地段、水域以及危险动物出没、有害植物生长区域设置安全防护设施和明显的警示标志；\n（二）定期检查风景名胜区公共设施的安全运营状况，及时采取措施消除各类安全隐患；\n（三）督促风景名胜区内的经营者采取措施，确保其经营的设施设备安全运营；\n（四）制定风景名胜区安全突发事件、高峰期大客流应对处置和救援应急预案；\n（五）其他游览安全保障工作。\n县级以上人民政府特种设备安全监督管理部门应当依法加强对风景名胜区内索道、缆车、电梯等特种设备的安全监督管理。\n第三十一条 风景名胜区内交通、住宿、餐饮、旅游服务商品和文化产业等经营项目，应当由风景名胜区管理机构依据法律法规和风景名胜区规划，采用招标等公平竞争的方式确定经营者，签订经营合同；经营者应当缴纳风景名胜资源有偿使用费，不得超出风景名胜区管理机构确定的地点和范围从事经营活动。\n风景名胜区管理机构应当依法对经营规模、经营质量、价格水平等进行监督管理。\n第三十二条 风景名胜区门票由风景名胜区管理机构负责出售，门票价格按照有关价格法律法规的规定执行，体现公益性。制定和调整门票价格，应当征求公众意见，并依法进行听证。\n风景名胜区对现役军人、残疾人、老年人、未成年人、在校学生等游客，应当按照有关规定实行票价优惠。鼓励有条件的风景名胜区向社会免费开放。\n风景名胜区门票收入和风景名胜资源有偿使用费，应当专门用于风景名胜资源的保护和管理以及对风景名胜区内财产的所有权人、使用权人损失的补偿。风景名胜区门票收入和风景名胜资源有偿使用费的征收、使用办法由省人民政府制定。\n第三十三条 省人民政府林业主管部门和风景名胜区管理机构应当完善公众参与制度，鼓励和支持公众、社会组织对风景名胜区的设立、规划编制与实施、资源保护、开发利用、监督管理等方面的决策活动提出意见和建议。\n省人民政府林业主管部门和风景名胜区管理机构应当建立举报、投诉制度，公布电话、通信地址等，及时受理和处理公众的举报、投诉，并将办理结果告知举报、投诉者。","level":1},{"name":"第六章 法律责任","text":"第三十四条 违反本条例，法律法规有规定的，从其规定。\n第三十五条 违反本条例第二十条第三项、第六项规定的，由风景名胜区管理机构责令停止违法行为，限期恢复原状或者采取其他生态修复措施，没收违法所得，并按照下列规定予以处罚：\n（一）填湖建房、围湖造田、筑坝拦汊以及其他侵占和分割水面的，处5万元以上20万元以下罚款;情节严重的，处20万元以上50万元以下罚款；\n（二）在禁火区内吸烟、点火、烧香、燃放烟花爆竹或者孔明灯等带有明火的空中飘移物的，给予警告，处100元以上500元以下罚款；情节严重的，处500元以上5千元以下罚款。\n第三十六条 未经批准从事本条例第二十四条第一款所列活动的，由风景名胜区管理机构责令停止违法行为、限期恢复原状或者采取其他生态修复措施，没收违法所得，并处5万元以上10万元以下罚款；情节严重的，并处10万元以上20万元以下罚款。\n违反本条例第二十四条第二款规定，对景物、水体、林草植被、野生动植物资源和地形地貌造成破坏的，由风景名胜区管理机构责令停止违法行为、限期恢复原状或者采取其他生态修复措施，处2万元以上10万元以下罚款。\n第三十七条 国家机关及其工作人员违反本条例规定，滥用职权、玩忽职守、徇私舞弊的，由其主管机关或者监察机关对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第三十八条 本条例自2018年5月1日起施行。","level":1}]},{"id":"h0207","sections":[{"name":"","text":"（1999年12月13日湖北省第九届人民代表大会常务委员会第十四次会议通过 2017年9月29日湖北省第十二届人民代表大会常务委员会第三十次会议修订）\n第一条 为了保障和规范本省各级人民代表大会常务委员会（以下简称人大常委会）依法行使讨论、决定重大事项的职权，根据宪法和有关法律的规定，结合本省实际，制定本规定。\n第二条 本规定适用于本省各级人大常委会讨论、决定本行政区域内经济建设、政治建设、文化建设、社会建设、生态文明建设中，关系改革发展稳定大局和人民群众切身利益、社会普遍关注的重大事项。\n第三条 人大常委会讨论、决定重大事项，应当坚持党的领导、人民当家作主、依法治国有机统一，坚持围绕中心、服务大局，坚持民主集中制、集体行使职权，坚持科学决策、民主决策、依法决策，促进经济社会发展和民主法治建设。\n人大常委会讨论、决定重大事项的情况，应当向本级人民代表大会报告，并向社会公开，接受监督。\n第四条 人大常委会对重大事项作出的决议、决定具有法律效力，本行政区域内的国家机关、组织和个人都应当遵守和执行。\n第五条 人民政府、人民法院、人民检察院应当建立完善相关制度，在作出重大决策前依法向本级人大常委会报告。\n第六条 下列重大事项，应当向人大常委会报告，由人大常委会审议，并作出决议、决定：\n（一）同级党委建议人大常委会讨论、决定的重大事项；\n（二）贯彻执行宪法、法律、法规和上级以及本级人民代表大会及其常务委员会决议、决定的重大措施，加强社会主义民主法治建设的重大措施；\n（三）本级人民代表大会授权人大常委会讨论、决定的重大事项；\n（四）需要人大常委会授权依法开展的重大改革措施；\n（五）本级人民政府对国民经济和社会发展五年规划、年度计划的调整方案；\n（六）本级预算调整方案、地方政府债务限额和上一年度决算；\n（七）人民代表大会换届选举工作中的有关重大事项；\n（八）撤销本级人民政府不适当的决定和命令；\n（九）撤销下一级人民代表大会及其常务委员会不适当的决议、决定；\n（十）授予或者撤销地方的荣誉称号；\n（十一）法律、法规规定应当由人大常委会讨论、决定的其他重大事项。\n第七条 下列重大事项，应当向人大常委会报告，由人大常委会审议提出意见、建议，根据需要可以作出决议、决定：\n（一）推进依法行政、公正司法的重大决策部署；\n（二）涉及经济社会发展全局和人民群众切身利益、社会普遍关注的重大民生事项和建设项目；\n（三）上半年国民经济和社会发展计划、预算的执行情况；\n（四）上一年度预算执行和其他财政收支的审计情况以及查出问题整改情况；\n（五）环境保护规划、土地利用总体规划、城镇体系规划、城市总体规划、主体功能区规划等的编制、修改和实施情况；\n（六）环境状况和环境保护目标完成情况，重大环境事件的应对处置情况；\n（七）行政区划调整方案；\n（八）法律、法规规定应当向人大常委会报告的其他重大事项。\n人民政府工作部门的设立、撤销或者合并方案,报经上一级人民政府批准后，应当报本级人大常委会备案。\n第八条 下列国家机关、机构和人员可以依法向本级人大常委会提出有关重大事项的议案、报告：\n（一）人大常委会主任会议；\n（二）人民政府、人民法院、人民检察院；\n（三）人民代表大会各专门委员会（以下简称专门委员会）；\n（四）省、市（州）人大常委会组成人员五人以上联名，县（市、区）人大常委会组成人员三人以上联名；\n（五）法律、法规规定的其他国家机关。\n第九条 建立完善讨论、决定重大事项协调机制，定期召开党委、人大常委会、人民政府、人民法院、人民检察院工作机构参加的讨论、决定重大事项联席会议，及时通报本行政区域的重大决策和工作部署及进展情况，沟通协调重大事项议题的提出、决议决定的贯彻执行、意见建议的研究处理等相关事宜。\n第十条 人大常委会讨论、决定重大事项，应当制定年度计划，并列入人大常委会年度工作计划，向社会公开。\n人大常委会工作机构应当每年年底向人民政府、人民法院、人民检察院和专门委员会、人大常委会组成人员、人大代表以及社会公众征集重大事项议题，研究提出下一年度计划方案，通过联席会议等形式沟通协调相关方面意见后，提交人大常委会主任会议讨论通过。\n年度计划需要作个别调整或者临时需要提请人大常委会讨论、决定的重大事项，由人大常委会主任会议研究决定。\n第十一条 人大常委会主任会议、人民政府、人民法院、人民检察院和专门委员会提出的重大事项议案、报告，应当分别经人大常委会主任会议、政府常务会议、审判委员会会议、检察委员会会议、专门委员会会议通过。\n人民政府、人民法院、人民检察院提出的重大事项议案、报告由其主要负责人签署。人大常委会组成人员联名提出的重大事项议案、报告，由联名人共同签署。\n第十二条 重大事项的议案、报告应当包括下列内容：\n（一）重大事项的基本情况；\n（二）与重大事项有关的法律、法规和政策依据；\n（三）决策方案及其必要性、可行性说明，相关的统计数据、调研报告等资料；\n（四）按照有关规定，组织公众参与、专家论证、风险评估、合法性审查、集体讨论决定的情况。\n重大事项的议案、报告应当在人大常委会会议召开的十五日前送达人大常委会工作机构。\n第十三条 人民政府、人民法院、人民检察院有关重大事项的议案、报告，应当提前送交有关专门委员会、人大常委会工作机构征求意见。\n有关专门委员会、人大常委会工作机构根据需要，提前参与重大事项前期研究协调和论证过程，了解情况、提出意见；或者组织专题调研，提出意见。\n第十四条 重大事项的议案、报告，按照下列程序提请审议：\n（一）人大常委会主任会议提出的，由人大常委会会议审议；\n（二）人民政府、人民法院、人民检察院和专门委员会提出的，由人大常委会主任会议决定提请人大常委会会议审议，或者先交有关专门委员会审议、提出报告，再决定提请人大常委会会议审议；\n（三）人大常委会组成人员依法联名提出的，由人大常委会主任会议决定是否提请人大常委会会议审议，或者先交有关专门委员会审议、提出报告，再决定是否提请人大常委会会议审议。\n第十五条 讨论、决定重大事项前，人大常委会应当组织人大常委会组成人员、人大代表开展视察、专题调研，或者由有关专门委员会、人大常委会工作机构组织专题调研，广泛听取各方面意见。\n对专业性、技术性较强的重大事项，应当组织专家、科研机构进行深入论证和评估，或者要求有关国家机关、机构、组织进行补充论证、评估。\n对存在重大意见分歧或者涉及利益关系重大调整的重大事项，应当召开听证会听取各方面意见。\n对社会普遍关注的重大事项，应当公开相关信息，通过报刊、网络等媒体向社会公开征求意见。\n第十六条 人大常委会会议审议重大事项的议案、报告时，提案机关负责人或者提案人应当到会作出说明、听取意见、回答询问。\n人大常委会主任会议应当安排参与前期视察或者专题调研的人大代表列席人大常委会会议，提出意见；根据需要，可以组织相关专业机构和人员列席人大常委会会议，回答询问。\n社会团体、企业事业单位以及公民经人大常委会主任会议决定，可以列席或者旁听人大常委会会议。\n第十七条 人大常委会讨论、决定重大事项，重点审查重大事项及决策方案的合法性，同时对科学性、合理性、可行性提出意见、建议。\n第十八条 对需要作出决议、决定的重大事项，人大常委会自收到重大事项的议案、报告之日起三个月内作出决议、决定；情形复杂的，经人大常委会主任会议决定可以适当延长期限。\n对不需要作出决议、决定的重大事项，有关专门委员会或者人大常委会工作机构应当在闭会后十五日内汇总整理人大常委会会议审议提出的意见、建议，经人大常委会主任会议决定交有关国家机关研究处理。\n第十九条 人大常委会对重大事项作出的决议、决定或者提出的意见、建议，在闭会后十五日内通过报刊、网络等媒体向社会公布。\n人大常委会作出的决议、决定在人大常委会公报上刊登。\n第二十条 人大常委会对重大事项作出的决议、决定，有关国家机关应当在一年内向人大常委会报告贯彻执行情况；决议、决定已明确办结期限的，应当在规定期限内办结；情形复杂需要延长期限的，应当提出书面报告，由人大常委会主任会议决定。\n人大常委会对重大事项提出的意见、建议，有关国家机关应当研究处理，并在六个月内向人大常委会报告研究处理情况。\n报告决议、决定贯彻执行情况，应当包括决议、决定执行的整体情况、实施效果、存在的问题和改进工作意见等。报告意见、建议研究处理情况，应当包括重大事项决策方案修改完善情况、实施效果、存在的问题和改进工作意见等。\n第二十一条 人大常委会通过听取和审议专项工作报告、开展执法检查或者组织代表视察、专题调研、专题询问等方式，对决议、决定的贯彻执行情况或者意见、建议的研究处理情况进行监督检查；根据需要，可以结合审议相关议题进行满意度测评。\n有关专门委员会或者人大常委会有关工作机构负责组织跟踪督办，并向人大常委会主任会议报告；必要时，由人大常委会主任会议决定，向人大常委会报告。\n第二十二条 违反本规定，有关国家机关有下列情形之一的，人大常委会可以依法组织询问、质询、特定问题调查，并根据具体情况提出监督纠正意见、责令限期改正或者依法撤销已经作出的决定：\n（一）应当向人大常委会报告的重大事项不报告的；\n（二）应当由人大常委会决定的重大事项越权作出决定的；\n（三）对人大常委会作出的决议、决定不贯彻执行的；\n（四）对人大常委会提出的意见、建议不研究处理的；\n（五）未按照期限报告决议、决定的贯彻执行情况或者意见、建议的研究处理情况的；\n（六）决议、决定的贯彻执行情况或者意见、建议的研究处理情况，经人大常委会满意度测评结果不满意的。\n有前款规定情形之一的，依法追究相关国家机关主要负责人责任，并向有关方面通报，作为其职务任免、考核的重要依据；造成重大损失或者恶劣影响的，相关国家机关主要负责人应当引咎辞职。\n第二十三条 市（州）、县（市、区）人大常委会根据本规定，结合本地实际，可以制定讨论、决定重大事项的具体办法。\n第二十四条 本规定自2017年12月1日起施行。","level":0}]},{"id":"h0208","sections":[{"name":"","text":"（2016年9月28日随州市第三届人民代表大会常务委员会第三十五次会议通过 2016年12月1日湖北省第十二届人民代表大会常务委员会第二十五次会议批准 根据2026年5月29日随州市第五届人民代表大会常务委员会第二十八次会议通过 2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议批准的《随州市人民代表大会常务委员会关于集中修改涉及生态环境法典地方性法规的决定》修正）\n第一条 为加强燃放烟花爆竹管理，保障公共安全和公民人身、财产安全，保护和改善生态环境和生活环境，根据《中华人民共和国生态环境法典》、《中华人民共和国治安管理处罚法》、《烟花爆竹安全管理条例》和有关法律、法规的规定，结合本市实际，制定本条例。\n第二条 本市城区禁止燃放烟花爆竹，具体范围由市人民政府划定并向社会公开。\n第三条 在禁止燃放烟花爆竹区域内，禁止生产、经营、储存烟花爆竹。\n禁止非法经由道路运输烟花爆竹，禁止携带烟花爆竹搭乘公共交通工具。\n第四条 本条例由市人民政府组织实施。\n县（市、区）人民政府、高新区管委会负责所辖区域内禁止燃放烟花爆竹工作的组织领导。\n第五条 公安机关是禁止燃放烟花爆竹工作的主管部门，负责禁止燃放烟花爆竹的公共安全管理工作。\n负有应急管理、生态环境、城市管理、市场监督管理等职责的部门和组织，按照各自的职责配合公安机关做好禁止燃放烟花爆竹的工作。\n第六条 禁止燃放烟花爆竹区域内的乡镇人民政府、街道办事处、村（居）民委员会、机关以及其他企事业单位和组织应当履行其辖区、单位禁止燃放烟花爆竹管理职责，设置禁鞭标识，深入开展禁止燃放烟花爆竹宣传教育，及时制止、劝阻违反本条例的行为。\n禁止燃放烟花爆竹区域内的宾馆、饭店等经营单位应当告知有关人员禁止燃放烟花爆竹管理规定，及时劝阻、举报违反本条例的行为。\n第七条 任何单位和个人对违反本条例的行为均有权制止、劝阻和举报。接受举报的部门应当及时调查处理，并对举报人的信息予以保密。对举报属实的，可以给予适当奖励。\n第八条 监护人应当履行教育和管理的监护职责，引导被监护人遵守禁止燃放烟花爆竹管理规定。\n第九条 在禁止燃放烟花爆竹区域内燃放烟花爆竹的，由公安机关依法责令停止燃放、收缴其烟花爆竹、予以警告或者罚款，并可以实施信用惩戒，纳入社会诚信档案。\n在禁止燃放烟花爆竹区域内的宾馆、饭店等公共场所燃放烟花爆竹，宾馆、饭店等经营单位未履行本条例第六条第二款规定责任的，除对违法燃放者进行处罚外，对场所经营责任人并处罚款。\n第十条 各级党政机关、人民团体、国有企事业单位及其工作人员违反条例规定燃放烟花爆竹的，应当从重处罚；主管部门应当予以通报批评、责令作出检查或者诫勉谈话。\n第十一条 被监护人违反本条例规定燃放烟花爆竹的，责令监护人对被监护人进行教育；造成国家、集体、个人财产损失或其他人身伤害的，由其监护人依法承担民事赔偿责任。\n第十二条 在禁止燃放烟花爆竹区域内生产、经营、储存烟花爆竹的，由应急管理、市场监督管理、公安等部门按照各自职责依法处理。\n第十三条 非法经由道路运输烟花爆竹的，由公安机关依法予以处罚。\n携带烟花爆竹搭乘公共交通工具的，由公安机关没收烟花爆竹，并处500元以上1000元以下罚款。\n第十四条 违反本条例，构成违反治安管理行为的，依照治安管理法律、法规予以处罚；构成犯罪的，依法追究刑事责任；造成国家、集体、个人财产损失或者他人人身伤害的，依法承担民事赔偿责任。\n第十五条 对打击报复制止人、举报人的，公安机关应当依法追究法律责任。\n第十六条 在禁止燃放烟花爆竹管理工作中负有职责的单位、部门及其工作人员，有下列行为之一的，由其上级行政管理部门或监察机关责令改正；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）不履行禁止燃放烟花爆竹管理职责的；\n（二）对举报人的举报不受理、不及时调查处理的；\n（三）违法实施行政处罚的；\n（四）徇私枉法、以权谋私、贪污受贿的；\n（五）其他违法行为。\n第十七条 重大节庆活动确需在禁止燃放烟花爆竹区域内燃放烟花爆竹的，由市人民政府决定并予以公告。\n第十八条 在禁止燃放烟花爆竹区域内施放电子礼炮、燃放孔明灯等的，参照燃放烟花爆竹管理。\n第十九条 本条例自2017年3月1日起施行。","level":0}]},{"id":"h0209","sections":[{"name":"","text":"（2017年5月24日湖北省第十二届人民代表大会常务委员会第二十八次会议通过）","level":0},{"name":"第一章总则","text":"第一条 为了鼓励发明创造，保护专利权人的合法权益，推动专利运用，促进科学技术进步和经济社会发展，推进知识产权强省建设，根据《中华人民共和国专利法》和有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内专利的创造、运用、保护、服务和管理等活动。\n第三条 专利工作应当遵循激励创造、注重质量、促进运用、依法保护、完善服务、科学管理的原则。\n第四条 县级以上人民政府应当加强对专利工作的领导，将专利工作纳入国民经济和社会发展规划，制定和实施专利发展战略，健全专利工作体系，加大专利经费投入，促进专利事业发展。\n第五条 县级以上人民政府管理专利工作的部门（以下简称专利管理部门）负责本行政区域内的专利工作。有关部门按照各自职责，做好专利相关工作。\n第六条 县级以上人民政府及其有关部门、学校以及新闻媒体等应当加强专利宣传教育，普及专利知识，增强全社会的专利意识，营造尊重知识产权、激励创新创业的社会环境。\n第七条 省人民政府设立湖北专利奖，对为国家和本省经济社会发展作出突出贡献的专利项目的单位或者发明人、设计人给予奖励。具体办法由省人民政府制定。\n县级以上人民政府应当对产生显著效益的专利项目给予表彰和奖励。","level":1},{"name":"第二章专利创造与运用","text":"第八条 鼓励单位和个人进行发明创造并申请国内外专利。\n县级以上人民政府应当制定激励、保障措施，鼓励、支持单位和个人开展技术创新形成专利，采取专利权入股、质押、转化、许可实施等多种形式运用专利，实现专利技术的商品化和产业化。\n对涉及重点产业发展、生态环境保护和人身财产安全等重大发明创造和运用，县级以上人民政府应当给予重点扶持。\n第九条 县级以上人民政府应当设立专项资金，用于发明创造和专利申请的资助、专利奖励、专利运用和产业化引导、专利保护和服务、专利人才培养和引进等方面。\n第十条 县级以上人民政府有关部门应当加强对财政资金支持项目的专利管理；科研项目可能产生专利的，项目主管部门应当与项目承担单位就专利成果的研究开发目标及验收标准进行约定。\n第十一条 鼓励、支持企业事业单位建立健全专利管理体系，制定专利发展战略，加强科技研发和创新能力建设。\n鼓励、支持企业事业单位对国内外专利状况、发展趋势、竞争态势等信息进行收集、分析、运用，开展专利布局、专利储备、专利导航、专利预警，推动专利集成运营。\n县级以上人民政府有关部门应当指导、帮助中小微企业、初创企业建立健全专利管理制度，为拥有专利技术的中小微企业、初创企业提供办公与生产场所、融资、信息、技术咨询等方面的服务，提高专利创造和运用能力。\n第十二条 企业事业单位专利技术及产品的研究开发费用以及专利申请费、专利代理费等费用，按照法律法规和国家有关规定,在计算企业所得税应纳税所得额时加计扣除。\n财政资金支持的科研开发、技术改造和高新技术产业化等项目实施过程中，与专利形成、实施等相关的费用，可以在项目经费中列支。\n第十三条 被授予专利权的单位应当按照约定或者有关规定，对发明人或者设计人给予奖励和报酬，不得取消或者以不合理的条件限制发明人、设计人依法获得奖励和报酬的权利。\n国有企业事业单位对职务发明创造的发明人或者设计人给予奖励和报酬的支出，计入当年单位工资总额，但不受当年单位工资总额限制，不纳入单位工资总额基数。\n第十四条 鼓励高等院校、科研机构建立专利激励机制，高等院校、科研机构可以与发明人或者设计人依法约定专利权属，共同申请专利，成为专利权的共有人。\n高等院校、科研机构的职务发明创造获得专利授权之后，未自行实施也未许可他人实施的，发明人或者设计人可以与单位以协议的方式予以实施，并按照协议享有相应权益。\n第十五条 企业事业单位将其拥有的专利转让或者许可他人实施的，发明人或者设计人在同等条件下可以优先受让或者优先获得许可，法律法规另有规定的除外。\n第十六条 鼓励企业事业单位建立内部专利人才绩效评价和激励机制。在绩效考核、职称评定、职位晋升等方面，可以将专利的创造与运用作为重要评价指标。\n获得中国专利金奖的主要发明人或者设计人可以破格申报相关技术职称和各类人才计划；获得中国专利优秀奖、湖北专利奖的，可以优先推荐申报相关技术职称。\n第十七条 县级以上人民政府应当采取激励措施，鼓励、支持企业与高等院校、科研机构等开展多渠道、多形式的合作，建立以专利为纽带的产学研协同创新机制，创立专利联盟，共同研究开发和实施专利技术。\n鼓励、支持高等院校、科研机构建立专门的专利转移转化机构，推动专利技术的运营。\n鼓励第三方机构托管、运营高等院校、科研机构专利技术。\n第十八条 鼓励在校学生开展发明创造、申请专利，并给予奖励。具体奖励办法由教育主管部门、学校制定。\n鼓励高等院校、科研机构采取有效措施，支持本单位员工和在校学生运用专利技术创新创业。\n第十九条 鼓励、支持企业事业单位运用专利参与国际标准、国家标准、行业标准或者地方标准的制定,推动自主研发的专利技术形成相关技术标准。\n第二十条 县级以上人民政府应当根据实际需要，制定专利密集型产业目录和发展规划，培育具有地方特色和比较优势的专利密集型产业，加强专利导航和专利联盟，建设专利密集型产业集聚区。\n第二十一条 县级以上人民政府应当建立健全专利投融资综合服务体系，运用资金补助、风险补偿、创业投资引导等方式，引导金融资本与专利技术对接，鼓励、支持社会资本参与专利投融资。\n第二十二条 鼓励、支持金融机构开展专利质押贷款等业务，建立完善专利质权处置机制，加大对中小微企业、初创企业专利实施的信贷支持，促进专利转化和产业化。\n鼓励保险公司开发专利质押融资保险、专利执行保险、专利侵权责任保险等与专利相关的保险产品。\n第二十三条 县级以上人民政府应当建立军民融合的专利管理体制机制，国防专利与民用专利的发明人、设计人享受同等的奖励政策。\n省国防科技工业主管部门、专利管理部门在符合国家安全、保密等相关法律法规前提下，推动科技协同创新，实现国防专利、民用专利的信息共享和双向转化。","level":1},{"name":"第三章专利保护","text":"第二十四条 专利管理部门应当依法处理专利侵权纠纷，查处假冒专利、重复侵权等违法行为，调解其他专利纠纷。\n第二十五条 县级以上人民政府应当建立健全专利行政执法与司法衔接机制，加强专利管理部门与公安机关、检察机关、人民法院的沟通和协作，打击假冒专利等违法行为。\n第二十六条 专利侵权纠纷的当事人请求行政机关处理的，可以依法向侵权行为地或者被请求人所在地专利管理部门提出。\n涉外专利侵权纠纷、跨市（州）的专利侵权纠纷和在全省范围内有重大影响的专利侵权纠纷的处理，由省人民政府专利管理部门负责，必要时可以依法指定市（州）人民政府专利管理部门处理。\n第二十七条 请求专利管理部门处理专利侵权纠纷，应当符合下列条件：\n（一）请求人是专利权人或者利害关系人；\n（二）有明确的被请求人和具体的请求事项、事实和理由；\n（三）当事人未向人民法院提起诉讼；\n（四）属于专利管理部门的受案和管辖范围。\n第二十八条 专利管理部门应当自专利侵权纠纷受理之日起三个月内作出处理决定。因特殊情形需要延长期限的，经专利管理部门负责人批准，可以延长一个月。案件处理过程中的公告、鉴定、中止等时间不计入办理期限。\n第二十九条 专利管理部门可以采用下列方式处理专利侵权纠纷：\n（一）认定侵权行为成立的，责令侵权人立即停止侵权行为；\n（二）认定侵权行为不成立的，驳回请求；\n（三）专利权被宣告无效，或者请求人撤回请求的，作出撤销案件的决定。\n专利管理部门责令停止侵权行为，当事人不服的，可以自收到处理决定之日起十五日内向人民法院起诉；侵权人期满不起诉又不停止侵权行为的，专利管理部门可以申请人民法院强制执行。\n第三十条 应当事人请求，专利管理部门可以对下列专利纠纷进行调解：\n（一）专利申请权和专利权归属纠纷；\n（二）发明人、设计人资格纠纷；\n（三）职务发明创造的发明人、设计人的奖励和报酬纠纷；\n（四）发明专利申请公布后专利权授予前使用费纠纷；\n（五）侵犯专利权的赔偿数额纠纷；\n（六）专利实施许可纠纷；\n（七）其他专利纠纷。\n经调解达成协议的，专利管理部门应当制作调解书；调解不成或者不同意调解的，当事人可以向人民法院起诉。\n第三十一条 专利管理部门在处理专利侵权纠纷时，根据当事人申请或者案件审理需要，可以组织专家咨询论证或者委托具备资格的鉴定机构进行技术鉴定。\n第三十二条 专利管理部门在处理专利侵权纠纷、查处假冒专利行为过程中，可以根据需要依职权调查收集有关证据。有关单位或者个人应当协助调查并提供有关证据材料，不得拒绝、阻挠。对有证据证明是假冒专利的产品，专利管理部门可以依法查封或者扣押。\n对于应当保密的证据，专利管理部门、有关单位和个人负有保密义务。\n第三十三条 专利管理部门及有关部门应当加强对生产流通环节以及技术贸易、展会、电子商务等领域涉及专利产品或者技术的监督管理,查处假冒专利、重复侵权等违法行为，维护市场经济秩序。\n第三十四条 专利管理部门应当建立健全专利信用档案制度，公开专利行政处罚案件信息，将假冒专利、重复侵权等违法行为纳入社会信用信息服务平台。\n第三十五条 网络、电视等交易平台运营商应当建立健全专利保护制度。专利权人或者利害关系人有证据证明相关产品、技术和服务假冒专利的，或者证明侵犯他人专利权并提供相关担保的，交易平台运营商应当及时采取删除、屏蔽等必要措施予以制止。\n专利管理部门和知识产权维权援助机构应当为交易平台运营商处理专利纠纷给予必要的专业指导和帮助。\n第三十六条 大型零售企业经营者、各类展会举办者应当建立产品专利保护制度，对涉及专利产品或者技术的，应当要求供货企业、参展单位提供专利有效证明文件并进行查验；未能提供专利有效证明文件的，经营者、举办者应当拒绝其入场销售或者以专利产品、技术名义参展。\n专利管理部门可以在大型零售企业、展会场所设立专利监督平台，现场受理专利纠纷。大型零售企业经营者、展会举办者应当协助和配合专利管理部门查处专利违法行为。\n第三十七条 利用广播、电视、报刊、网络等媒介发布涉及专利的广告的，应当向广告审查机关和广告经营者、发布者提供专利有效证明文件，并对广告内容的真实性负责。\n广告经营者、广告发布者应当严格按照有关规定查验专利有效证明文件。对未提供专利有效证明文件的单位或者个人，广告经营者不得为其提供设计、制作或者代理服务，广告发布者不得为其发布广告。\n第三十八条 任何单位和个人有权对假冒专利、重复侵权等违法行为向专利管理部门和有关部门举报。\n专利管理部门应当建立专利违法行为举报处理机制，公布举报方式，对有关举报及时调查、处理；对查证属实的举报给予奖励，并为举报人保密。","level":1},{"name":"第四章专利服务与管理","text":"第三十九条 省人民政府专利管理部门应当建立健全专利综合服务平台，提供专利政策咨询、专利信息检索、专利交易、专利运营、专利导航、专利预警等公共服务，推动全省专利信息资源开放共享。\n专利管理部门应当建立专利信息共享机制，提供专利公共服务。支持有条件的企业、行业协会建立或者参与建立重点行业、支柱产业和重点技术领域的专利信息数据库。\n第四十条 县级以上人民政府及其有关部门应当培育专利服务市场，鼓励、支持专利服务机构提供专利代理、运营、评估、咨询、人才培训等服务。\n专利服务机构及其从业人员应当依法取得执业资质或者资格，不得泄露、剽窃委托人的发明创造，不得出具虚假报告，不得与当事人串通牟取不正当利益，不得损害国家利益和社会公共利益。\n专利管理部门应当依法对专利服务机构及其从业人员进行监督和管理，及时向社会披露专利服务机构及其从业人员信用评价等相关信息。\n第四十一条 鼓励专利服务机构开展国际专利中介服务，支持单位和个人申请国外专利，支持企业通过专利转让、专利许可或者企业并购等方式引进国外先进专利技术。\n第四十二条 经济技术开发区、保税区、自由贸易试验区等各类园区应当开展知识产权综合管理改革，建立健全知识产权综合管理体制和知识产权公共服务体系,探索建立重点产业专利导航制度和快速协同保护机制。\n第四十三条 县级以上人民政府及其有关部门应当建立健全重大科技经济活动专利评议制度，对涉及科技立项、专利保护、运用和转移的重大产业规划以及使用财政资金的重大投资项目、高层次人才引进等事项进行专利评议，避免盲目引进、重复研发、专利侵权、技术泄密等风险。\n第四十四条 专利管理部门应当建立健全专利预警机制，监测重点行业和领域的国内外专利状况、发展趋势和竞争态势，发布预警报告，为政府决策及企业事业单位发展服务。\n第四十五条 专利管理部门应当建立社会化专利维权援助机制，鼓励专利维权援助机构、法律服务机构、专利服务机构等通过多种方式，依法开展专利维权服务。\n鼓励行业协会建立区域性、专业性专利保护联盟和协作机制，组织企业在国内外贸易和投资中开展集体维权。\n省人民政府应当建立健全海外知识产权争端处理机制，支持建立海外知识产权维权服务中心，推动形成海外知识产权服务网络，加强海外知识产权风险防控和维权援助。\n第四十六条 县级以上人民政府应当建立健全专利指标体系，将专利指标纳入对政府及有关部门的目标责任考核范围。\n县级以上人民政府及其有关部门应当将专利申请量、专利授权量、万人发明专利拥有量、国外专利拥有量、专利技术转化运用率等专利指标和专利发展情况纳入国民经济和社会发展统计范围。\n省人民政府应当每年向社会发布全省专利发展情况报告。\n第四十七条 县级以上人民政府应当制定和实施专利人才培养计划，加强对专利人才的培养和引进，并纳入地方人才规划。\n省人民政府专利管理部门应当建立专利人才数据库，加强专利人才培训基地建设。\n企业事业单位应当重视培养和引进专利人才，强化在职人员专利知识培训。\n鼓励教育机构、社会机构提供专利相关知识培训，为专利人才培养提供社会服务。","level":1},{"name":"第五章法律责任","text":"第四十八条 违反本条例，法律法规有规定的，从其规定。\n第四十九条 有下列行为之一的，由专利管理部门责令改正，没收违法所得；拒不改正的，处5千元以上2万元以下罚款；情节严重的，处2万元以上10万元以下罚款：\n（一）网络、电视等交易平台运营商对假冒专利或者侵犯专利权，未采取必要措施的；\n（二）大型零售企业经营者、展会举办者对未提供专利有效证明文件的单位，未拒绝其入场销售或者参展的。\n第五十条 重复侵犯专利权的，由专利管理部门责令改正，非法经营额5万元以上的，处非法经营额1倍以上5倍以下罚款。非法经营额5万元以下的，处5万元以上10万元以下罚款；情节严重的，处10万元以上20万元以下罚款。没有非法经营额的，处1万元以上5万元以下罚款。\n第五十一条 从事专利服务，未依法取得相关资质或者资格的，由专利管理部门责令停止违法行为，没收违法所得，并处违法所得1倍以上5倍以下罚款。\n专利服务机构及其从业人员泄露、剽窃委托人的发明创造，出具虚假报告，牟取不正当利益或者损害国家利益和社会公共利益的，由专利管理部门责令改正；拒不改正的，处5千元以上2万元以下罚款；情节严重的，处2万元以上10万元以下罚款。\n第五十二条 单位或者个人弄虚作假，骗取政府专利资助、奖励的，由实施资助、奖励的机关撤销奖励，追回资助、奖励资金，有关单位或者个人五年内不得申报政府专利资助，相关信息纳入社会信用信息服务平台。\n第五十三条 国家机关及其工作人员滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第五十四条 本条例自2017年9月1日起施行。1998年4月2日湖北省第九届人民代表大会常务委员会第二次会议通过的《湖北省专利保护条例》同时废止。","level":1}]},{"id":"h0210","sections":[{"name":"","text":"（2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议通过 根据2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第二次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了规范神农架国家公园管理和服务活动，保护神农架自然生态系统的原真性和完整性，保障国家生态安全，促进生态文明建设，依据有关法律、行政法规和国家《建立国家公园体制总体方案》，制定本条例。\n第二条 本条例适用于神农架国家公园的保护和管理等活动。\n神农架国家公园经国家批准设立并主导管理，由神农架的世界自然遗产地、国家级自然保护区、国家湿地公园、国家森林公园、国家地质公园、省级风景名胜区、大九湖省级自然保护区等自然保护地整合而成。\n省人民政府根据神农架国家公园保护需要，划定毗邻保护区并向社会公布，促进神农架国家公园与周边区域的协同保护。\n第三条 神农架国家公园的保护和管理，应当遵循保护第一、科学规划、分区管理、社会参与、永续发展的原则，严格按照国家相关规定执行。\n第四条 省人民政府负责神农架国家公园的组织领导工作，将神农架国家公园的发展纳入国民经济和社会发展规划，建立健全神农架国家公园管理体制，完善生态保护绩效考核制度和生态保护补偿机制，将神农架国家公园生态管护、生态修复、生态建设等保护和管理经费列入财政预算。\n第五条 省人民政府应当制定政策措施，采取定向援助、产业调整、生态移民等方式，支持神农架国家公园内居民改善生产条件、提高生活水平，加大对神农架林区（以下简称林区）重点生态功能区的财政转移支付力度，促进神农架区域经济社会发展。\n第六条 各级人民政府及有关部门应当加强神农架国家公园的宣传教育，促进神农架国家公园的保护和管理。\n广播、电视、报刊、网络等媒体应当加强宣传引导，普及生态文化，增强公众生态保护意识，开展舆论监督。\n鼓励基层群众性自治组织、社会组织、志愿者开展国家公园法律法规和生态保护知识宣传，营造良好氛围。","level":1},{"name":"第二章 管理体制","text":"第七条 省人民政府建立国家公园管理联席会议制度，研究制定国家公园管理制度和措施，统筹协调神农架国家公园规划、国土空间用途管制、自然资源资产管理、特许经营、生态保护补偿等重大事项，研究解决国家公园管理和保护中的重大问题。联席会议的日常工作由省人民政府确定的部门承担。\n第八条 省人民政府设立的神农架国家公园管理机构（以下简称国家公园管理机构）负责统一履行神农架国家公园内生态保护、自然资源资产管理、特许经营管理、社会参与管理、宣传推介等行政管理职责。国家公园管理机构权力清单和责任清单由省人民政府制定。\n国家公园管理机构在神农架国家公园范围内履行资源环境综合执法职责，依法集中行使行政处罚权。\n省人民政府按照精简高效的原则，将林区人民政府涉及神农架国家公园自然资源资产管理和生态保护的有关部门职责和人员部分整合纳入国家公园管理机构。\n第九条 省人民政府发展改革、财政、自然资源、生态环境、住房和城乡建设、水行政、农业农村、文化和旅游等部门按照各自职责做好相关工作，依法加强对神农架国家公园管理情况的监管。\n第十条 林区人民政府履行神农架国家公园内经济社会发展综合协调、公共服务、社会管理、市场监管等职责。\n有关乡镇人民政府协助国家公园管理机构加强生态管护。\n有关村（居）民委员会引导居民养成绿色环保的生产生活方式，协助开展神农架国家公园生态保护。\n第十一条 国家公园管理机构依照国家有关规定统一履行神农架国家公园内现有的世界自然遗产地、自然保护区、湿地公园、森林公园、地质公园、风景名胜区等各类自然保护地的管理职责。\n第十二条 建立神农架国家公园生态保护绩效考核制度，实行领导干部自然资源资产离任审计和生态环境损害责任追究制，具体办法由省人民政府制定。\n省人民政府应当组织对神农架国家公园的自然资源资产管理、生态系统状况、环境质量变化、生态文明制度执行情况等进行第三方评估，评估结果作为生态保护绩效考核的重要依据。\n第十三条 神农架国家公园设立专家咨询委员会，为国家公园的保护和管理提供专业咨询和决策支持。","level":1},{"name":"第三章 规划与分区","text":"第十四条 编制神农架国家公园规划应当符合国家和省主体功能区划，与国土空间规划相衔接，严守生态保护红线。\n第十五条 神农架国家公园规划包括总体规划和专项规划，应当包含总体布局、功能区划、资源保护、科研监测、科普教育、游憩展示、社区发展、公众参与、管理体系等方面内容。\n神农架国家公园规划由国家公园管理机构组织编制，报省人民政府审核，其中总体规划由省人民政府提请省人民代表大会常务委员会审议，再依照法定程序报请批准。\n第十六条 编制神农架国家公园规划应当依法进行生态环境影响评价，并履行风险评估、专家论证、公开征求意见等程序，必要时进行听证。\n经批准的神农架国家公园规划应当及时公布并严格执行，不得擅自变更或者调整；确需变更或者调整的，应当按照原程序报请批准。\n第十七条 神农架国家公园按照生态功能和保护目标，划分为严格保护区、生态保育区、游憩展示区和传统利用区。\n严格保护区是神农架国家公园内自然生态系统最完整、核心资源集中分布以及自然环境脆弱的区域,采取封禁和自然恢复的方式保护，除科学研究需要外，禁止任何人进入。\n生态保育区是神农架国家公园内维持较大面积的原生生态系统以及已遭到一定程度破坏而需要修复的区域，采取必要的生物措施予以保护。\n游憩展示区是集中承担国家公园游憩、展示、科普、教育等功能的区域。\n传统利用区是生产和生活的区域，允许对自然资源进行可持续性利用。\n第十八条 国家公园管理机构应当设立国家公园界碑，并在严格保护区分界处设立界碑、界桩。\n任何单位和个人不得破坏、擅自移动界碑、界桩。\n第十九条 神农架国家公园实行严格规划建设管控，除不损害生态系统的生产生活设施改造和自然观光、科研、教育、旅游外，禁止其他开发建设活动。\n神农架国家公园内各类建设项目应当依法取得许可，有关机关许可前应当征求国家公园管理机构意见。\n经批准的重大基础设施建设项目不得穿越严格保护区和生态保育区；通讯、电网等建设项目确需穿越生态保育区的，应当经充分论证并科学设计、合理施工，避免对生态环境的影响。\n现有建设项目不符合神农架国家公园规划的，应当按照规划要求限期改造或者拆除。\n经批准的建设项目，建设单位、施工单位应当制定污染防治和水土保持方案，并采取有效措施，维护植被、水体、野生动植物资源和地形地貌；因施工造成环境破坏的，应当同步进行生态修复。","level":1},{"name":"第四章 资源保护","text":"第二十条 神农架国家公园资源保护对象为：\n（一）自然资源，包括地质地貌奇观、北亚热带原始森林、常绿落叶阔叶混交林生态系统、泥炭藓湿地生态系统、北亚热带古老孓遗、以金丝猴和冷杉、珙桐为代表的珍稀濒危特有物种及其关键栖息地等核心资源；\n（二）人文资源，包括神农炎帝文化、川鄂古盐道、南方哺乳动物群化石、远古人类旧石器遗址以及汉民族神话史诗等；\n（三）其他需要保护的资源。\n第二十一条 省人民政府应当建立神农架国家公园自然资源和人文资源调查制度，组织对神农架国家公园内自然资源、人文资源等各类资源进行本底普查和定期调查，编制反映资源存量及变动情况的资产负债表。\n第二十二条 不动产登记机构应当根据有关法律法规，会同国家公园管理机构和有关部门开展国家公园内水流、森林、山岭、草原、荒地、滩涂等自然资源资产的确权登记工作，明确各类自然资源的种类、面积和所有权性质。\n神农架国家公园内全民所有的自然资源资产，省人民政府根据国家规定代理行使所有权，国家公园管理机构负责具体保护和管理工作。\n神农架国家公园内集体或者个人所有的自然资源资产，国家公园管理机构可以和所有权人、承包权人依照国家规定通过租赁、置换等方式规范流转，或者通过合作协议的方式实现统一有效管理。\n第二十三条 省人民政府应当组织制定神农架国家公园生态环境管控、自然文化遗产保护、生物多样性保护等相关管理办法和标准，并向社会公布，接受社会监督。\n第二十四条 国家公园管理机构应当合理划分管理和管护责任区域，建立巡护制度，制定统一工作规范，制止破坏资源和环境的行为。\n第二十五条 国家公园管理机构应当建立监测预警制度，构建自然资源基础数据库及统计分析平台，定期组织开展地质地貌、野生动植物、森林、草地、湿地等自然资源和生态系统的动态监测，并根据监测情况进行风险预警，采取相应保护措施。\n国家公园管理机构应当会同有关部门加强动植物检疫和林业有害生物防治工作，制定应急预案。发生疫情或者生物灾害时，及时采取有效的预防与控制措施。\n第二十六条 国家公园管理机构应当加强生态系统多样性、生物多样性的保护，在野生动植物集中、生物多样性丰富的区域建立生物多样性保护基地、重要物种栖息地。\n国家公园管理机构会同有关部门和周边地区建立生物多样性保护协调机制，构建绿色生态廊道，提高生态保护区域的连通性。\n第二十七条 国家公园管理机构应当依照神农架国家公园规划，开展森林、草地、河流、湖泊、水库、湿地、野生动植物、地质资源等专项保护工程，必要时开展生态系统修复。生态系统修复以自然恢复为主，生物措施和工程措施相结合。\n保护大九湖湿地生态系统的原真性和多样性，恢复大九湖泥炭藓沼泽、植被和水系生态系统，保障南水北调水源涵养地的生态功能。\n第二十八条 国家公园管理机构应当会同有关部门制定文化遗产保护方案并组织实施，依法保护文物、遗址等物质文化遗产和非物质文化遗产。\n第二十九条 国家公园管理机构应当会同有关部门建立防灾减灾应急机制，制定应急救援预案，建立防灾减灾队伍，开展技能培训和应急演练，提高防范森林火灾、山体崩塌滑坡、泥石流、雷电、大风、暴雪等灾害的能力。\n第三十条 禁止在神农架国家公园内从事下列活动：\n（一）狩猎、捕捞、开垦、烧荒、采集泥炭、揭取草皮、捡拾鸟卵；\n（二）违反规定养殖、种植、砍伐、放牧、采石、挖沙、取土、取水；\n（三）擅自采集国家和省级重点保护野生植物；\n（四）损毁、擅自挖掘地质遗迹，擅自采集化石、矿石标本；\n（五）使用剧毒、高毒、高残留农药（含除草剂等药剂）；\n（六）引进或者投放外来物种；\n（七）改变自然水系状态；\n（八）法律法规规定的其他破坏生态环境的活动。\n严格保护区和生态保育区内，禁止进行养殖、种植、砍伐、放牧、采药、开垦、烧荒、开矿、采石、挖沙等活动。\n第三十一条 神农架国家公园内禁止新建、改建、扩建矿产资源开发、水电等项目。\n现有的矿产资源开发、水电项目应当有序退出。省人民政府应当自本条例实施之日起一年内制定退出办法，明确退出时限、补偿标准、资金来源等。\n第三十二条 在神农架国家公园各分区内开展活动，应当遵守下列规定：\n（一）严格保护区内，禁止建设任何生产经营设施；\n（二）生态保育区内，允许建设必要的保护和科研监测的建筑物和构筑物，禁止建设生产经营设施；\n（三）游憩展示区内，经批准允许建设必要的餐饮、游憩、住宿等基础设施，开展参观、旅游等活动，禁止进行大规模开发，禁止建设污染环境、破坏资源和景观的生产经营设施，禁止开展与保护方向不一致的参观、旅游等活动；\n（四）传统利用区内禁止从事对自然生态系统有影响的生产经营活动。\n第三十三条 在神农架国家公园内从事下列活动，应当经国家公园管理机构同意：\n（一）在严格保护区内建设防火、科研、监测等保护设施或者因科学研究确需进入严格保护区的；\n（二）进入生态保育区、游憩展示区和传统利用区从事科学研究、教学实习和标本采集的；\n（三）在游憩展示区和传统利用区内拍摄影视作品、举办大型群众性活动的；\n（四）其他可能影响神农架国家公园生态环境的活动。\n从事前款规定的科学研究、拍摄影视作品等活动的，应当在规定的期限内向国家公园管理机构提交活动成果副本。\n第三十四条 省人民政府建立神农架国家公园生态保护补偿机制，将林区、神农架国家公园及其毗邻保护区的生态保护补偿资金纳入省级财政预算；对神农架国家公园森林、湿地、水流、耕地等重点领域以及下列事项进行生态保护补偿：\n（一）依法许可的矿产资源开发、水电项目以及其他建设项目，限期关闭、退出或者改造、拆除的；\n（二）依法取得的特许经营权被收回的；\n（三）重要自然资源的所有权、使用权被依法征收的；\n（四）生态移民搬迁；\n（五）开展清洁能源建设项目的；\n（六）农业清洁生产的；\n（七）污水、垃圾等环境治理的；\n（八）野生动物致害的；\n（九）其他应当进行补偿的事项。\n省人民政府应当建立资金、技术、实物、就业岗位等相结合的补偿机制，探索开展综合补偿并加强生态保护补偿效益评估。生态保护补偿和效益评估的具体办法由省人民政府制定。\n第三十五条 省人民政府应当建立协调机制，鼓励受益地区采取转移支付、资金补助、对口协作、产业转移、人才培训、共建园区等方式，支持神农架林区的生态保护、产业优化和民生改善。\n第三十六条 按照神农架国家公园规划，需要进行生态移民搬迁的，国家公园管理机构应当组织制定生态移民搬迁方案，明确住房、土地、就业、产业发展、社会保障、生态保护补偿等事项，经专家论证，并征求相关乡镇人民政府、村（居）民委员会和移民的意见，报省人民政府批准后实施。\n国家公园管理机构应当对移民组织开展技能培训，支持其依法参与特许经营和其他经营活动，保障、改善移民的生产生活条件。\n第三十七条 建立健全神农架国家公园科研机制，设立神农架国家公园科研机构，进行森林生态系统、珍稀植物培育、野生动物救护和金丝猴、高山生态、地质等研究。\n国家公园管理机构应当建立科学研究合作机制，推动神农架国家公园与国内外国家公园、科研机构、专家学者的交流合作，加强神农架国家公园资源保护。\n鼓励高等院校、企业事业单位开展科学研究、建立国家公园人才教育培训基地，为国家公园保护提供科技支撑和人才保障。\n第三十八条 国家公园管理机构与毗邻保护区和其他周边地区，通过合作共建等方式，共同保护神农架国家公园及周边区域的自然资源。","level":1},{"name":"第五章 服务与监管","text":"第三十九条 国家公园管理机构应当根据神农架国家公园规划，合理利用森林、山地、河流、湖泊、湿地、古迹等自然生态和人文景观，提供科研科普、环境教育、生态体验等服务，处理好神农架国家公园保护与利用服务的关系。\n第四十条 国家公园管理机构应当建设多元化的教育展示体系及解说系统，设立宣教中心和野外宣教基地，开展科普和环境教育，促进公众了解国家公园的资源和价值，培育守护意识。\n第四十一条 神农架国家公园门票由国家公园管理机构负责管理，实行政府定价，体现公益性。制定和调整门票价格，应当征求公众和利害关系人的意见并依法进行听证。\n第四十二条 神农架国家公园游憩展示区内生态体验、交通、住宿、餐饮、商店及文化产业等经营项目实行特许经营。\n公益性项目一般不纳入特许经营范围，不得以特许经营名义将公益性项目和经营项目整体转让、垄断经营。\n特许经营管理办法由省人民政府制定，经专家论证、公开征求意见后向社会公布。特许经营管理办法应当明确特许经营的目录、期限、费用、监督管理等。\n涉及能源、交通运输、水利、环境保护、市政工程等基础设施和公用事业的特许经营依据国家有关规定执行。\n第四十三条 国家公园管理机构应当依法对特许经营规模、经营质量、价格水平等进行监督管理。发现特许经营者未履行保护职责，可能损害生态系统、自然资源和人文资源的，应当终止特许经营合同，并要求经营者承担相应责任。\n省人民政府应当组织对特许经营实施情况和监督管理情况进行定期审查和评估。\n第四十四条 神农架国家公园实行收支两条线管理，依托自然资源设立的景区门票收入、特许经营收入等各项收入应当上缴财政，纳入预算专项管理，统筹用于资源保护、生态保护补偿以及扶持神农架国家公园和毗邻保护区居民的发展等。\n第四十五条 国家公园管理机构应当科学合理设置生态体验区域和路线，完善生态体验服务体系，加强公共服务设施和信息基础设施建设，推进神农架国家公园的信息化、智能化，建成智慧国家公园。\n国家公园管理机构应当根据环境承载能力和资源监测结果，合理确定访客容量，实行限额管理、提前预约和定期休园制度，及时向公众公布访客实时流量和最大承载量等信息。\n第四十六条 国家公园管理机构应当按照国家有关规定配套建设垃圾分类收集和无害化处理设施。\n神农架国家公园内单位和个人应当按照垃圾分类要求，将垃圾投入指定的垃圾容器或者收集场所。\n第四十七条 神农架国家公园应当设置服务设施标志、游园导向标志以及安全警示标志，并采取必要的防范措施。\n国家公园管理机构应当建立健全安全管理责任制和应急处置制度，为访客提供必要的救助服务。\n第四十八条 林区人民政府、国家公园管理机构应当规范、引导园区居民在传统利用区开展与生态保护相适应的观光休闲、民俗体验等服务，发展绿色低碳产业，增加居民收入。","level":1},{"name":"第六章 社会参与","text":"第四十九条 国家公园管理机构应当完善公众参与制度，鼓励公众对神农架国家公园的设立、规划编制与实施、资源保护、利用服务、监督管理等提出意见和建议。\n国家公园管理机构应当建立健全信息公开制度，构建神农架国家公园综合信息平台，提供自然资源、保护管理、科研监测、科普教育、旅游线路等信息服务。\n第五十条 鼓励和支持社会组织、企业事业单位和个人通过协议保护和授权管理等方式参与神农架国家公园生态保护活动。\n鼓励国家公园管理机构与神农架国家公园内乡镇人民政府、村（居）民委员会等建立社区共管共建机制，通过联户参与、签订管护协议等形式，协助开展自然资源保护工作。\n国家公园管理机构通过提供国家公园服务就业岗位、委托管理、产业转移、扶持集体经济发展项目等形式支持社区发展。\n第五十一条 国家公园管理机构应当建立健全生态管护制度，设置公益岗位，优先聘用神农架国家公园内居民为生态管护员。实行管护考核与奖惩制度，合理确定管护报酬与绩效奖励标准，管护所需经费纳入省级财政预算。\n生态管护员协助国家公园管理机构对生态环境进行日常巡护和保护，报告并制止破坏生态环境的行为，监督各项保护措施执行情况。\n第五十二条 鼓励企业、有关组织和个人通过投资、捐赠、信贷支持等形式，参与神农架国家公园的保护和建设。\n支持设立国家公园生态保护基金会，接受社会捐赠资金等。基金的筹集、管理和使用依据国家有关规定执行。\n第五十三条 建立国家公园志愿者制度。国家公园管理机构应当会同有关部门建立志愿者平台，制定志愿者招募与准入、教育与培训、管理与激励的相关政策和措施。\n鼓励和支持政府部门、企业事业单位、其他组织和个人参与国家公园的资源保护、解说教育、科普宣传等志愿服务工作。\n第五十四条 国家公园管理机构应当建立决策咨询合作机制，与公益组织、教育科研机构、企业事业单位等建立合作伙伴关系，建立社会公众参与决策和意见反馈制度，为神农架国家公园的保护和管理提供智力支持。\n第五十五条 任何单位和个人都有保护神农架国家公园生态系统和自然资源、人文资源的义务，有权对违法行为进行制止、投诉和举报。\n国家公园管理机构应当建立公民、社会组织、利益群体、媒体参与的国家公园社会监督机制，建立社会监督员和举报制度；对有关投诉、举报事项，应当及时组织核查、依法处理。","level":1},{"name":"第七章 法律责任","text":"第五十六条 违反本条例，法律法规有规定的，从其规定。\n第五十七条 国家机关及其工作人员在神农架国家公园保护和管理工作中，有下列情形之一的，责令改正；情节严重或者造成生态环境恶化等严重后果的，对负有责任的领导人员和直接责任人员，由其主管机关或者监察机关依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）未按照法定程序组织编制、变更、调整神农架国家公园规划的；\n（二）违反神农架国家公园规划批准建设项目的；\n（三）对矿产资源开发、水电以及其他不符合神农架国家公园规划的建设项目，未按照规定退出或者改造、拆除的；\n（四）未按照规定管理、监督神农架国家公园特许经营项目的；\n（五）发现违法行为不予查处的；\n（六）其他滥用职权、玩忽职守、徇私舞弊行为。\n第五十八条 违反本条例第三十条第一款第一项、第二项、第四项至第七项规定的，由国家公园管理机构责令停止违法行为、限期恢复原状或者采取其他生态修复措施，没收违法所得，处1万元以上5万元以下罚款；情节严重的，处5万元以上20万元以下罚款。\n违反本条例第三十条第一款第三项规定的，由国家公园管理机构责令停止违法行为，没收违法所得，处违法所得十倍以下罚款。\n第五十九条 违反本条例第三十一条第一款规定的，由国家公园管理机构责令停止建设、限期拆除、采取生态修复措施，没收违法所得，并处50万元以上150万元以下罚款。\n第六十条 违反本条例第三十二条规定的，由国家公园管理机构责令停止建设、限期拆除、采取生态修复措施，没收违法所得，并按照下列规定予以处罚：\n（一）在严格保护区违规建设设施的，处50万元以上100万元以下罚款；\n（二）在生态保育区建设生产经营设施的，处20万元以上50万元以下罚款；\n（三）在游憩展示区进行大规模开发或者建设污染环境、破坏资源或者景观的生产经营设施的，处20万元以上100万元以下罚款；\n（四）在传统利用区从事对自然生态系统有影响的生产经营活动的，对个人处1千元以上3千元以下罚款，对单位处1万元以上5万元以下罚款。\n第六十一条 违反本条例第三十三条第一款规定的，按照下列规定予以处罚：\n（一）擅自在严格保护区内建设防火、科研、监测等保护设施或者擅自进入严格保护区的，由国家公园管理机构责令改正，处1千元以上5千元以下罚款；对自然资源造成破坏的，处5千元以上2万元以下罚款；\n（二）擅自进入生态保育区、游憩展示区和传统利用区从事科学研究、教学实习和标本采集的，由国家公园管理机构责令限期改正；逾期未改正的，处1万元以上5万元以下罚款；\n（三）擅自在游憩展示区和传统利用区内拍摄影视作品、举办大型群众性活动的，由国家公园管理机构责令限期改正；逾期未改正的，处2千元以上1万元以下罚款。","level":1},{"name":"第八章 附则","text":"第六十二条 本条例自2018年5月1日起施行。","level":1}]},{"id":"h0211","sections":[{"name":"","text":"（2017年11月29日湖北省第十二届人民代表大会\n常务委员会第三十一次会议通过）\n为认真贯彻落实党的十九大精神，规范和加强全省各级人民代表大会常务委员会（以下简称常务委员会）对本行政区域内司法工作的监督，促进严格执法、公正司法，不断提升司法公信力，根据《中华人民共和国各级人民代表大会常务委员会监督法》等法律法规的规定，结合本省实际，特作出如下决定。\n一、常务委员会在党的领导下，按照民主集中制的原则集体行使职权，依法对本级人民法院、人民检察院（以下统称司法机关）以及人民政府的公安、国家安全、司法行政等机关（以下统称具有司法职能的机关）的司法工作实施监督，支持司法机关和具有司法职能的机关依法行使职权。\n二、常务委员会主任会议（以下简称主任会议）依法处理对司法工作监督的重要日常工作。人民代表大会内务司法委员会、常务委员会内务司法工作委员会（以下简称内务司法专工委）和常务委员会有关工作机构负责组织实施对司法工作监督的具体事务。\n三、常务委员会对下列事项实施监督：\n（一）遵守和执行宪法、法律、法规以及上级和本级人民代表大会及其常务委员会决议、决定的情况;\n（二）全面履行法定职责的情况；\n（三）贯彻落实司法体制综合配套改革和其他重大改革的部署的情况；\n（四）司法机关、具有司法职能的机关之间相互配合及监督制约机制建立和落实的情况;\n（五）人民代表大会选举产生及其常务委员会任命和决定任命的司法工作人员履行法定职责的情况;\n（六）办理人民代表大会代表提出的有关司法工作的建议、批评、意见的情况;\n（七）办理常务委员会依法转办、交办、督办的公民、法人和其他组织申诉、控告或者检举的情况;\n（八）错案及重大司法过错责任追究的情况；\n（九）依法需要监督的其他情况。\n四、常务委员会可以采取下列方式实施监督：\n（一）听取和审议专项工作报告；\n（二）法律法规实施情况的检查；\n（三）询问和质询；\n（四）特定问题调查；\n（五）撤职案的审议和决定；\n（六）旁听庭审、运用人大司法监督工作平台察看庭审活动；\n（七）法律、法规规定的其他方式。\n五、内务司法专工委和常务委员会有关工作机构可以从下列途径发现的问题中提出监督议题，由主任会议研究决定：\n（一）在监督司法工作中发现的突出问题；\n（二）人民代表大会代表对司法工作提出的建议、批评和意见集中反映的问题；\n（三）常务委员会组成人员对司法工作提出的比较集中的问题；\n（四）社会普遍关注的司法工作热点、难点问题；\n（五）人民群众来信来访反映的司法工作中存在的突出问题；\n（六）其他途径反映的问题。\n六、常务委员会每年选择若干关系改革发展稳定大局和人民群众切身利益、社会普遍关注的重大问题，有计划地安排听取和审议司法方面的专项工作报告。\n常务委员会应当将每年年中听取和审议司法机关半年工作情况的报告列入年度监督工作计划。\n常务委员会听取和审议司法方面的专项工作报告后，主任会议可以决定对专项工作报告、审议意见研究处理的情况进行满意度测评。\n七、常务委员会开展司法方面法律法规实施情况的检查，应当坚持问题导向，增强针对性和实效性，推动法律得到正确有效实施。\n八、常务委员会根据监督工作需要，可以组织人民代表大会代表、常务委员会组成人员旁听庭审、参加司法机关和具有司法职能的机关的公众开放日等活动；也可以通过人大司法监督工作平台（庭审监督系统）对庭审活动实施远程在线监督。\n九、司法机关和具有司法职能的机关应当向常务委员会报告下列重大事项:\n（一）贯彻执行宪法、法律、法规以及上级和本级人民代表大会及其常务委员会决议、决定的重大措施；\n（二）履行审判、检察、公安、国家安全、司法行政职责的重大工作部署；\n（三）拟提请常务委员会审议并需要作出决议、决定的事项；\n（四）对人民代表大会代表因涉嫌犯罪提请采取限制人身自由措施许可的事项；\n（五）人民代表大会选举产生、常务委员会任命或者决定任命的司法工作人员被追究刑事责任的情况；\n（六）执法、司法过程中发生的重大暴力抗法事件及处理情况；\n（七）错案和重大司法过错责任追究情况；\n（八）根据法律、法规规定或者常务委员会认为需要报告的其他重大事项。\n十、司法机关和具有司法职能的机关制定的下列重要文件，应当自印发之日起三十日内报送常务委员会:\n（一）全局性工作部署;\n（二）贯彻落实司法体制综合配套改革和其他重大改革的部署的情况；\n（三）指导和规范本行政区域司法工作的文件；\n（四）常务委员会认为需要报送的其他文件。\n十一、司法机关提请常务委员会任命或者决定任命司法工作人员时，应当将拟任人员近三年履行法定职责、廉洁自律、工作中存在的问题以及改进措施等情况书面报送常务委员会人事任免工作机构，并抄送内务司法专工委。\n十二、内务司法专工委和常务委员会有关工作机构应当加强与司法机关和具有司法职能的机关的沟通联系，通过听取专题工作汇报、列席相关会议、建立联席会议制度、完善人大监督司法工作与人民检察院法律监督工作衔接机制等方式，协助常务委员会推动人大及其常务委员会关于司法工作的决议、决定的贯彻实施，协调解决监督司法工作中的有关问题。\n十三、人民代表大会代表提出的关于司法工作的建议、批评和意见，由常务委员会代表工作机构按照《湖北省人民代表大会代表建议、批评和意见办理规定》办理。\n常务委员会受理的公民、法人或者其他组织对司法机关、具有司法职能的机关及其工作人员的申诉、控告或者检举，由常务委员会信访工作机构办理；对属于检察机关法律监督职能范围的涉法涉诉事项，由内务司法专工委、常务委员会信访工作机构按照《湖北省人大常委会加强人大司法监督工作与省人民检察院法律监督工作衔接的办法》处理。\n十四、常务委员会应当将对司法工作监督的情况采取适当形式向人民代表大会报告。\n内务司法专工委、常务委员会有关工作机构应当定期向主任会议报告组织实施对司法工作监督的有关情况。\n十五、常务委员会可以组建法律专家咨询小组，对司法工作中的突出问题开展对策理论研究，并对司法工作监督的重大事项向常务委员会提出决策建议。\n十六、常务委员会监督司法工作的情况，依法向社会公开，接受社会监督。\n对司法工作监督中涉及国家秘密、商业秘密、个人隐私和其他不宜公开的事项，应当依法予以保密。\n十七、常务委员会监督司法工作中发现的违法线索，应当交由有关机关调查处理；需要免去或者撤销相关人员职务的，通报其主管部门依法按照人事管理权限和程序办理；属于常务委员会任命或者决定任命的司法工作人员需要免职、撤职的，由常务委员会按照法定程序办理。\n司法机关、具有司法职能的机关及其工作人员对常务委员会的决议、决定怠于执行的，常务委员会可以根据不同情况，分别作出如下处理:\n（一）责成有关机关作出书面说明；\n（二）对有关机关提出质询；\n（三）对常务委员会任命或者决定任命的司法工作人员依法决定免职、撤职；\n（四）对人民代表大会选举产生的司法工作人员向人民代表大会依法提出罢免案。\n常务委员会对司法机关和具有司法职能的机关不研究处理常务委员会审议意见等妨碍人大依法行使司法工作监督职权的情形，依照前款第（一）、（二）项的规定处理。\n十八、在监督司法工作中，内务司法专工委和常务委员会工作机构的相关工作人员与监督事项有利害关系的，应当依法回避；存在滥用职权、以权谋私、徇私舞弊、泄露秘密等违法行为的，由有关机关依法追究相应责任。\n十九、本决定自公布之日起施行。","level":0}]},{"id":"h0212","sections":[{"name":"","text":"（2017年11月29日湖北省第十二届人民代表大会\n常务委员会第三十一次会议通过）\n为认真贯彻党的十九大精神，加强对预算绩效管理的监督，进一步推进我省全面实施预算绩效管理，切实提高财政资金使用效益，提升公共服务质量和水平，提高人民满意度，根据《中华人民共和国预算法》《中华人民共和国各级人民代表大会常务委员会监督法》等法律法规规定，结合我省实际，作出以下决定。\n一、预算绩效管理应当坚持统一领导、分级负责，分类管理、突出重点，规范透明、注重实效，强化问责、激励约束的原则。\n二、各级人民代表大会和县级以上各级人民代表大会常务委员会依法对本级政府预算绩效管理进行监督，按照民主集中制原则，集体行使职权。县级以上各级人民代表大会有关专门委员会、常务委员会相关工作机构具体组织实施预算绩效管理监督工作。\n三、各级政府负责本地区预算绩效管理工作的统一领导，将预算绩效管理纳入政府绩效管理，加强对下级政府和本级财政及各预算部门（单位）（以下简称“预算部门”）的督导和考核，统筹推进预算绩效管理。\n四、各级财政部门具体负责本行政区域预算绩效管理工作，制定管理制度，组织并指导本级预算部门和下级财政部门开展预算绩效管理工作。\n各预算部门是本部门预算绩效管理的责任主体，负责组织本部门及下属单位开展预算绩效管理工作。\n五、各级政府及其财政部门、各预算部门应当树立绩效理念，强化支出责任，健全预算绩效管理相关制度，建立以绩效目标为导向、以绩效评价为手段、以结果运用为保障的预算绩效管理体系，全面实施预算绩效管理。\n六、各预算部门在编制下一年度预算时，应当按照指向明确、细化量化、合理可行、相应匹配的原则，根据本级政府预算编制总要求及财政部门和本部门中长期规划、年度计划，科学合理设定预算绩效目标，围绕绩效目标编制预算绩效指标。\n各级财政部门应当对各预算部门编制的预算绩效目标进行审核。新设立预算支出项目，应当将绩效目标审核结果作为立项的重要参考。\n各级政府预算经同级人民代表大会审查批准后，财政部门应当在批复部门预算的同时批复预算绩效目标。各预算部门应当及时公开预算绩效目标，接受社会监督。各级财政部门应当督促预算部门公开预算绩效目标。\n七、各级财政部门和预算部门应当建立预算绩效运行跟踪监控机制，对绩效目标运行情况进行跟踪管理和督促检查，促进绩效目标实现。\n各预算部门、各级财政部门发现预算执行偏离绩效目标的，应当及时采取措施予以纠正。\n八、各预算部门应当对本部门财政资金使用情况进行绩效评价。\n各级财政部门应当对各预算部门的绩效评价工作进行指导、监督和检查，建立对各预算部门绩效自评报告抽查、核实或再评价的工作机制，并选择部分重大（重点）支出项目开展绩效评价。\n各级财政部门、各预算部门应当建立和完善统一、科学、客观、公正的绩效评价体系，探索对部门整体支出和政策、制度、管理等方面的绩效评价，提高绩效评价质量和实效性。\n九、各级政府及其财政部门、各预算部门应当加强绩效评价结果的综合应用，将绩效评价结果作为安排预算的基本依据，建立并完善支出项目设立、动态调整与退出机制。\n各级政府及其财政部门、各预算部门应当完善管理制度，改进管理措施，提高管理水平，及时解决绩效评价发现的问题。各预算部门应当将绩效报告、评价结果等绩效管理信息依法向社会公开；财政部门应当将重点项目绩效评价结果向社会公开，接受社会监督。\n十、各级财政部门、各预算部门委托专家、中介机构等第三方参与预算绩效管理时，应当建立和完善相关工作机制，为第三方独立、公正开展工作提供必要条件。\n受委托的第三方应当对其出具的评价报告负责，保证报告的公信力和客观性。\n十一、各级监察机关及财政、审计部门应当依照法律法规及有关规定，对预算绩效实施有效监督。\n各级审计部门应当探索开展绩效审计，将绩效审计列入年度审计计划。\n十二、各级政府向本级人民代表大会提交年度预算草案及其报告，应当包括上一年度政府预算绩效管理情况和本年度部分重大（重点）支出项目的绩效目标。向本级人民代表大会常务委员会提交上一年度决算草案，应当选择部分重大（重点）支出项目绩效评价报告作为附件，提请本级人民代表大会常务委员会一并审查。向本级人民代表大会常务委员会提交关于上一年度预算执行和其他财政收支的审计工作报告，应当包括绩效审计情况。\n十三、各级人民代表大会常务委员会听取和审议本级政府预算绩效管理专项报告前，应当听取人大代表和社会公众意见，提高审议质量。可以探索引入第三方评价、满意度测评等方式进行跟踪监督，增强监督实效。监督情况应当向社会公开，接受社会公众监督。\n十四、各级人民代表大会有关专门委员会、常务委员会相关工作机构，应当协助常务委员会加强对预算绩效管理事前、事中、事后全过程监督。可以采取第三方评价、组织视察、专题调研、问卷调查等方式方法，对重点支出、重大投资项目等方面的绩效目标设立、绩效情况实施重点监督。\n各级人民代表大会有关专门委员会、常务委员会相关工作机构组织开展预算绩效监督活动，应当邀请本级人大代表、常委会组成人员、专门委员会成员参加，可以邀请预算决算审查监督专家库成员、第三方机构和行业专家等参加。\n各级人民代表大会有关专门委员会、常务委员会相关工作机构，应当加快将本级政府的预算绩效管理情况纳入预算联网监督的查询、分析、预警、服务等功能范围。\n各级人民代表大会有关专门委员会、常务委员会相关工作机构，在审查本级政府预算决算、预算调整方案，监督预算执行情况时，应当依法对预算绩效管理提出意见和建议，按有关程序交政府及其有关部门。政府及其有关部门应当依法办理，并及时回复办理情况。\n十五、各级政府应当建立预算绩效管理工作考核制度，考核结果作为评价地区和部门工作、实施激励和问责的重要依据。\n对在预算绩效管理中出现的违法行为，应当依据《中华人民共和国预算法》《财政违法行为处罚处分条例》等有关法律法规规定追究责任。\n受委托参与预算绩效管理工作的第三方违反本《决定》第十条规定的，委托方应当解除委托协议，并取消相关资格；情节严重的，依照有关法律法规的规定移交有关部门处理。\n十六、本决定自公布之日起施行。","level":0}]},{"id":"h0213","sections":[{"name":"","text":"（2017年11月29日湖北省第十二届人民代表大会\n常务委员会第三十一次会议通过）\n根据《中华人民共和国环境保护税法》（简称环境保护税法）的规定和我省环境保护费改税的实际情况，现决定我省应税大气污染物和水污染物的具体适用税额及项目数如下：\n一、大气污染物的税额。废气中的二氧化硫和氮氧化物的税额为每污染当量2.4元；其余大气污染物的税额为每污染当量1.2元。\n二、水污染物的税额。废水中的化学需氧量、氨氮、总磷和五项主要重金属（铅、汞、铬、镉、类金属砷）的税额为每污染当量2.8元；其余水污染物的税额为每污染当量1.4元。\n环境保护税法第九条的规定已经涵盖了我省大气污染物和水污染物中的主要污染指标和主要污染物，暂不增加同一排放口征收环境保护税的应税污染物项目数。\n省人民政府应当根据我省环境承载能力、污染物排放情况的变化和经济社会生态发展目标要求,对决定中规定的应税污染物税额及项目数的适用情况进行跟踪检查和评估，适时提出调整方案，按程序报省人大常委会决定。\n本决定自2018年1月1日起施行。","level":0}]},{"id":"h0214","sections":[{"name":"","text":"第一条 为了加速民族自治地方社会主义建设事业的发展，实现各民族的共同繁荣，根据《中华人民共和国民族区域自治法》，结合我省实际情况，制定本规定。\n第二条 上级国家机关(指湖北省和辖有自治县的市的国家机关，下同)及其所属部门，应当认真实施《中华人民共和国民族区域自治法》，尊重和保障民族自治地方自治机关的自治权，维护和发展平等、团结、互助的社会主义民族关系，领导和帮助民族自治地方建设社会主义物质文明和精神文明。\n第三条 上级国家机关作出有关民族自治地方的决议、决定、命令和指示，应当征求民族自治地方自治机关的意见，适合民族自治地方的实际情况。\n上级国家机关的决定、决议、命令和指示，如有不适合民族自治地方实际情况的，自治机关可以报经该上级国家机关批准，变通执行或者停止执行。对于自治机关的报告，上级国家机关从收到之日起应当在六十日以内做出答复。\n上级国家机关隶属的在民族自治地方的企业、事业单位，应当尊重当地自治机关的自治权，遵守当地自治条例、单行条例，接受当地自治机关的监督。\n第四条 民族自治地方的自治机关要发扬自力更生、艰苦奋斗精神，根据国家的有关规定，制定经济建设和社会发展计划，自主地安排和管理地方性的经济建设和社会发展事业。\n上级国家机关在制定国民经济和社会发展计划时，应当照顾民族自治地方的特点和需要，扶持民族自治地方合理开发利用资源、加强基础设施和小城镇建设以及技术改造，优化产业结构，保护生态环境，增强民族自治地方自我发展能力，实现可持续发展。\n上级国家机关根据统一规划和市场需求，依法优先合理安排对民族自治地方发展具有重大作用的基础设施及其他重大建设项目；对国家在民族自治地方安排的建设项目、投资和贷款比重以及减少或者免除民族自治地方自行出资的配套资金等方面给予照顾，并帮助民族自治地方争取国家扶持。\n第五条 上级国家机关及有关部门在民族自治地方开发资源、进行建设时，对输出自然资源的民族自治地方给予一定的利益补偿。民族自治地方财政因此而增加的收入，作为民族自治地方经济建设和社会发展的自有资金留用，不得抵减上级补贴。\n第六条 民族自治地方的自治机关应坚持改革开放的方针，加快对外开放和开发建设的步伐。在法律和政策允许的范围内，可自行制定优惠措施，引进国内其他地区以及国外的资金、技术、设备，开发资源、兴办企业。\n上级国家机关应当组织、支持和鼓励所属部门、经济发达地区和企业、事业单位对口支援民族自治地方，开展经济技术协作，帮助和促进民族自治地方的经济和社会发展。\n第七条 民族自治地方应优化农村产业结构，重视粮食生产，发展多种经营。上级有关部门在农业投资和生产资料的供应等方面，应当对民族自治地方优先安排。\n第八条 民族自治地方应当保护森林资源，发展林业，保持生态平衡。上级国家机关应当逐步加大对民族自治地方林业项目的投资，扶持建立林、果、土特产品基地。从民族自治地方提取的育林基金、林业保护建设费等，应当通过林业建设项目安排给民族自治地方发展林业。对民族自治地方实施的退耕还林、天然林保护等工程，应当按规定落实工程建设资金、补贴经费和退耕还林补助。\n第九条 民族自治地方应重视发展畜牧业，鼓励兴办家庭牧场。上级国家机关应从资金、技术和设备等方面，扶持民族自治地方建设草山、草场、畜禽商品基地，提高畜禽产品的商品率。\n第十条 民族自治地方应当利用当地资源优势，发展能源建设。\n上级国家机关应当帮助民族自治地方发展小水电。在民族自治地方兴建的水电站按照国家和省有关规定返还库区维护基金，收取的水资源费，对民族自治地方的返还比例高于其他地区。安排农村改水补助经费和城镇自来水工程建设资金时，应当对民族自治地方予以照顾，逐步实现城镇普及自来水；民族自治地方小水电建设资金自筹有困难的，要予以必要的扶持。适当增加小水电建设的低息贷款指标和延长还贷期、限。鼓励农村集体经济组织和个人投资按照统一规划兴办小水电。\n上级国家机关帮助民族自治地方发展农村沼气和农村改水项目，并在资金、技术等方面予以扶持，逐步减少农村使用薪材燃料的数量，解决农村人口及牲畜饮水问题。\n第十一条 上级国家机关应当帮助民族自治地方发展交通运输业。对民族自治地方干线公路、县乡公路的建设和改造以及航道、航空设施建设，在项目和资金上予以重点扶持。民族自治地方可以根据本地实际制定发展乡村公路的具体措施。\n第十二条 上级有关部门应当扶持民族自治地方加速邮电通讯网络和信息化工程建设，并在资金、设备、人才等方面予以照顾。\n第十三条 上级国家机关应当扶持、引导民族自治地方因地制宜地发展中小企业、民营经济和少数民族特需产品的企业，并在投资、金融和税收方面给予照顾。\n对民族自治地方的烟草种植和烟草制品生产予以扶持，促其增加科技含量，提高经济效益。\n第十四条 上级国家机关应当将民族自治地方的旅游业纳入旅游总体规划，扶持民族自治地方合理开发和利用自然、人文等旅游资源，加强旅游景点及其配套设施建设，发展旅游业。\n第十五条 民族自治地方有管理本级财政的自治权，并享受国家财政优惠政策。上级财政应当逐步加大对民族自治地方财政转移支付的力度。通过一般性财政转移支付、专项财政转移支付、民族优惠政策财政转移支付以及国家确定的其他方式，增加对民族自治地方的资金投入。省财政对民族自治地方的转移支付和定额补帖在保持一定总量的基础上逐步增加，对民族自治地方上划增值税、消费税等共享收入增长系数中央返还部分，全额留给民族自治地方统筹安排使用。\n根据国家有关规定，对民族自治地方财政实行机动金、预备费和民族补助费三项照顾。照顾的资金由民族自治地方自行安排使用，主要用于经济文化事业的建设。其中，民族补助款由民族事务主管部门会同财政主管部门提出使用意见。\n上述三项照顾的资金以及国家设立的其他专用资金和临时性的民族补助专款，任何单位、部门不得扣减、截留、挪用，也不得充抵其他按正常渠道划拨的经费。\n国家安排的用于民族自治地方的不发达地区发展资金和其他专项资金，规定由上级国家机关安排配套资金的，有关上级国家机关应当落实。省财政和辖有民族自治地方的市的财政安排的民族工作事业费，根据财政收入的增长逐步增加，主要用于民族自治地方和其他方面的民族工作。\n第十六条 民族自治地方的自治机关可以根据国家和省有关规定，并结合本地实际，制定税收征收具体办法。对属于地方财政收入的部分税收项目需要实行减税或者免税的，报省人民政府批准。\n对民族自治地方的公路、铁路及民航建设耕地占用税和企业所得税，凡符合国家对西部开发实行税收优惠照顾条件的，应当按规定予以减免。\n第十七条 民族自治地方应当根据有关规定，发展以国家银行为主体的多种金融机构，多渠道筹集和融通资金。上级银行对民族自治地方分配银行自有资金和下达信贷规模、货币投放与回笼等计划指标时，应给予照顾。要按照国家有关规定，疏通渠道，办好对民族自治地方的优惠利率贷款，并适当扩大民族自治地方银行专项贷款的审批权限。\n第十八条 上级国家机关根据国家民族贸易优惠政策，对民族自治地方的民族贸易和民族用品定点生产企业从投资、金融、税收等方面给予扶持。\n上级国家机关扶持民族自治地方建设物资集散中心和农副产品、矿产品、民族工业用品贸易中心，促进民族贸易的发展。\n第十九条 民族自治地方依照国家有关规定，多形式地开展对外贸易，并在对外贸易活动中享受国家的优惠政策。\n上级国家机关应当扩大民族自治地方对外贸易经营的自主权，扶持民族自治地方发展适合市场需求和有地方优势的产品，并落实民族自治地方对外经济贸易中的优惠政策。\n第二十条 民族自治地方应当采取多种形式扩大劳动就业，发展社会保障事业，完善社会保障体系。上级国家机关对民族自治地方的社会保障事业给予扶持。在分配国家和省财政对社会保障方面的补助经费时，对民族自治地方予以照顾。\n第二十一条 上级国家机关和有关部门，应当帮助民族自治地方大量培养少数民族干部，使少数民族干部在当地干部总数中所占的比例，同当地少数民族人口在当地总人口中所占的比例相适应，并注重选拔优秀少数民族干部担任领导工作。\n第二十二条 在民族自治地方工作的大中专毕业生，根据有关规定享受工资浮动和山区津贴的待遇。\n在民族自治地方工作的国家机关和全民所有制企业、事业单位的干部职工，享受民族自治地方生活补贴。国家机关和全民所有制事业单位干部职工的补贴款，由民族自治地方财政和省财政共同承担。全民所有制企业干部职工的补贴款，由企业承担，可税前列支。\n第二十三条 民族自治地方的自治机关录用工作人员时，对实行区域自治的民族和其他少数民族的人员应当给予适当照顾。\n上级国家机关帮助民族自治地方的自治机关制定人才优惠政策，稳定和引进各类专门人才，建立人才市场，开发人才资源。\n第二十四条 上级国家机关扶持民族自治地方发展民族教育事业，普及九年义务教育，扫除青壮年文盲，办好民族高等学校和中等专业学校，发展普通高级中学教育、职业教育和成人教育，创造条件逐步在民族自治地方中小学推广信息技术教育，加快教育信息化建设。\n上级国家机关和民族自治地方的各级政府应当重视民族自治地方的智力投资，每年教育经费的增长应当高于财政经常性收入的增长，并使在校学生人数的平均教育费用逐年有所增加。上级国家机关用于民族自治地方教育的基本建设投资比例应当高于其他地区。\n省设立民族教育补助专款，主要用于帮助民族自治地方逐步办一批寄宿制和半寄宿制的民族中小学或民族班。\n省、辖有自治县的市和民族自治地方应当安排少数民族义务教育助学金，用于家庭经济特别困难学生的补助，确保其完成学业。\n第二十五条 高等学校、中等专业学校、技工学校在招生时，应当按照国家和省里的规定，对民族自治地方的考生，通过降分录取等形式适当放宽录取标准和条件。扩大民族自治地方定向招生的比例，并积极创造条件，开办民族班和公寓走读班。\n第二十六条 上级国家机关应当采取有效措施，帮助民族自治地方发展科技事业，建立必要的科研机构和技术培训中心，培养和引进科技人才。在安排科技项目时，对适宜于民族自治地方的项目，应优先安排。\n第二十七条 上级国家机关应当帮助民族自治地方发展文化艺术事业，开展文化艺术交流，培养少数民族的文艺人才，继承和发掘民族民间文化艺术遗产，加强具有民族特点的广播、电视和体育等设施的建设，丰富人民群众的文化生活。\n上级国家机关对民族自治地方的民族历史文化遗产保护、文化研究机构、文化艺术团体、体育队伍和传统文化体育活动予以扶持，并设立民族文化事业补助费，纳入每年的财政预算。\n第二十八条 上级国家机关支持、帮助民族自治地方发展医药卫生事业和农村合作医疗，逐步建立适合民族自治地方特点的医疗保障体系，加强医药卫生专业人员的教育和培训，重视发展民族传统医药和开展群众性卫生活动，切实解决缺医少药的问题，加强妇幼保健和地方病的防治工作，提高各民族人民的健康水平。\n省设立民族医疗减免费，用于补助少数民族特困群众的医疗费。\n第二十九条 民族自治地方的自治机关根据《中华人民共和国人口与计划生育法》和省有关规定，结合本地方的实际情况，制定人口与计划生育的具体规定。\n第三十条 民族自治地方属于革命老根据地、贫困山区、库区的，同时享受国家对革命老根据地、贫困山区、库区的各项优惠政策。\n第三十一条 上级国家机关和民族自治地方的自治机关应当保障本地方内各民族都享有平等权利。教育各民族干部和群众尊重其他民族使用的语言文字及其风俗习惯和宗教信仰。\n民族自治地方的自治机关要照顾散居在本地方的其他少数民族的特点和需要，在处理涉及本地方各民族特殊问题的时候，必须与他们的代表充分协商，尊重他们的意见。\n第三十二条 本规定自1989年1月1日起施行。","level":0}]},{"id":"h0215","sections":[{"name":"","text":"（2019年9月26日湖北省第十三届人民代表大会常务委员会第十一次会议通过 根据2021年9月29日湖北省第十三届人民代表大会常务委员会第二十六次会议《关于集中修改涉及长江保护法省本级地方性法规的决定》第一次修正 根据2022年11月25日湖北省第十三届人民代表大会常务委员会第三十四次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》第三次修正）","level":0},{"name":"第一章 总则","text":"第一条 为了保护和改善清江流域水生态环境，防治水污染，保障饮用水安全和公众健康，推进生态文明建设，促进绿色发展和高质量发展，根据《中华人民共和国生态环境法典》等有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内清江流域水生态环境的保护活动。\n本条例所称清江流域，是指恩施土家族苗族自治州的利川市、恩施市、建始县、巴东县、咸丰县、宣恩县、鹤峰县，宜昌市的长阳土家族自治县、五峰土家族自治县、宜都市境内清江干流及其支流汇水面积内的水域和陆域。\n第三条 清江流域水生态环境保护应当坚持党的领导，遵循保护优先、预防为主、综合治理、严格监管、公众参与、损害担责的原则。\n第四条 省和清江流域县级以上人民政府应当将清江流域水生态环境保护工作纳入国民经济和社会发展规划，建立健全保护工作机制，将保护经费纳入同级财政预算，支持水生态环境保护的科学研究和先进技术的推广应用，加强清江流域水生态环境的保护。\n乡镇人民政府、街道办事处负责本辖区内的水生态环境保护相关工作。\n村（居）民委员会协助开展水生态环境的保护工作，将水生态环境保护纳入村规民约、居民公约。\n第五条 省人民政府对清江流域水生态环境质量负总责，清江流域各级人民政府对本行政区域内清江流域水生态环境质量负责。\n清江流域水生态环境保护实行目标责任制和考核评价制度。饮用水水源地水质达标、水功能区水质达标、地表水考核断面水质达标、重点水污染物总量控制、水电站生态流量监督管理等应当纳入目标考核内容。\n清江流域实行河（湖）长制，各级河（湖）长组织领导本行政区域内水资源保护、水域岸线管理、水污染防治、水环境治理等工作。\n第六条 省人民政府建立清江流域水生态环境保护联席会议制度，统筹协调清江流域水生态环境保护规划、国土空间用途管制、自然资源资产管理、生态保护补偿等重大事项，研究解决清江流域水生态环境保护中的重大问题。联席会议的日常工作由省人民政府生态环境主管部门承担。\n省人民政府生态环境主管部门应当会同清江流域市（州）人民政府建立清江流域水生态环境保护联合协调机制，实行统一规划、统一标准、统一监测、统一防治。\n第七条 省和清江流域县级以上人民政府生态环境主管部门对本行政区域内清江流域水生态环境保护实施统一监督管理。\n发展改革、经济和信息化、科技、公安、自然资源、住房和城乡建设、交通运输、水行政、农业农村、文化和旅游、卫生健康、市场监督管理等有关主管部门在各自的职责范围内，负责本行政区域内清江流域水生态环境保护的监督管理工作。\n第八条 清江流域对重点水污染物排放实施总量控制制度。\n排放水污染物，不得超过国家和省规定的水污染物排放标准和重点水污染物排放总量控制指标。\n第九条 社会公众应当遵守环境保护法律法规，养成绿色、低碳、环保的生产生活方式。\n省和清江流域各级人民政府及有关主管部门应当组织开展水生态环境保护法律法规和知识的宣传教育，增强保护水生态环境的意识。\n广播、电视、报刊、网络等媒体应当加强清江流域水生态环境保护的公益宣传，对违法行为开展舆论监督。\n鼓励和支持公众、环保志愿者和社会组织参与清江流域水生态环境的保护和监督。","level":1},{"name":"第二章 标准与规划","text":"第十条 清江干流执行省人民政府划定的水功能区类别及相应的水环境质量标准。\n清江流域市（州）人民政府应当依照相关规定划定本行政区域内清江支流的水功能区类别，报省人民政府批准后实施。\n第十一条 清江流域城乡污水集中处理设施出水水质应当执行《城镇污水处理厂污染物排放标准》一级A排放标准；现有污水集中处理设施出水水质达不到排放标准的，应当限期改造。鼓励污水集中处理设施出水水质执行高于一级A排放标准。\n第十二条 省人民政府生态环境主管部门应当会同发展改革、自然资源、交通运输、水行政、农业农村、文化和旅游、卫生健康等有关主管部门以及清江流域市（州）人民政府组织编制清江流域水生态环境保护规划，报省人民政府批准，并报国务院生态环境主管部门备案。\n清江流域县级以上人民政府根据清江流域水生态环境保护规划和实际需要，组织编制本行政区域的水生态环境保护规划。\n清江流域水生态环境保护规划应当向社会公开，并严格执行；确需调整的，应当经原批准机关批准。\n第十三条 编制清江流域水生态环境保护规划应当严格遵守生态保护红线、环境质量底线、资源利用上线和生态环境准入清单，符合国土空间规划、生态环境保护规划。\n饮用水水源地保护、城乡污水处理、农业面源污染防治、畜禽养殖污染防治、船舶污染防治、生态修复、岸线利用、产业发展等专项规划或者方案，应当根据清江流域水生态环境保护规划编制。\n第十四条 清江流域有关市（州）、县级人民政府应当按照水生态环境保护规划确定的水生态环境质量改善目标，依法编制限期达标规划、改善规划及其实施方案，并采取有效措施按期达标、改善生态环境质量。限期达标规划、改善规划及其实施方案应当报上一级人民政府备案，并向社会公开。","level":1},{"name":"第三章 水污染防治","text":"第十五条 省人民政府应当根据长江流域发展规划、国土空间规划的要求，调整优化清江流域产业结构和布局，制定清江流域发展负面清单。负面清单应当包括岸线、河段、区域和产业等方面的禁止性规定，并向社会公开。\n清江流域禁止新建纳入清江流域发展负面清单的项目；已经建成的，县级以上人民政府应当制定限期整治方案，予以改造、转产、搬迁或者关闭。\n第十六条 工业园区等区域应当同步配套建设污水集中处理设施，实行清污分流、雨污分流，实现废水分类收集、分质处理。污水集中处理设施应当安装自动监控系统，并与生态环境主管部门的监控设备联网。\n排放工业废水的企业应当收集和处理产生的全部废水；含有毒有害水污染物的工业废水应当分类收集和处理，不得稀释排放。向污水集中处理设施排放工业废水的，应当按照国家有关规定进行预处理，达到处理工艺要求后方可排放至污水集中处理设施。\n鼓励排放工业废水的企业采用高效清洁工艺设备，实行清洁生产和资源循环利用，减少水污染物排放量。\n第十七条 清江流域市（州）人民政府生态环境主管部门根据省人民政府下达的重点水污染物排放总量控制计划，制定本行政区域内清江流域重点水污染物排放总量控制实施方案，报市（州）人民政府批准后下达各县级人民政府执行。\n重点水污染物排放总量控制指标应当按照规定分解落实到排污单位，并向社会公布。\n第十八条 省人民政府生态环境主管部门应当会同有关主管部门确定清江流域实行排污许可重点管理的企业事业单位和其他生产经营者名录，并向社会公布。\n清江流域实行排污许可重点管理的企业事业单位和其他生产经营者，应当按照国家规定安装、使用、维护污染物排放自动监测设备，开展监控、自动监测，并与生态环境主管部门的监控设备联网，保证自动监测设备正常运行，保存原始监测记录。\n清江流域实行排污许可管理的企业事业单位和其他生产经营者应当按照排污许可证的要求和有关标准规范，依法开展自行监测，建立管理台账，并保存原始监测记录和管理台账。原始监测记录和管理台账保存期限不得少于五年。\n清江流域实行排污许可管理的企业事业单位和其他生产经营者应当按照规定向社会公开污染物排放种类、排放浓度和排放量，以及污染防治设施的建设运行情况、自行监测数据等污染物排放信息，接受社会监督。\n第十九条 禁止违反排污许可及国家有关规定向清江流域水体排放水污染物。\n向水体排放污染物的企业事业单位和其他生产经营者应当按照国家和省的规定设置、监测、管理排污口，在排污口安装标注单位名称和排放污染物的种类、浓度及数量要求等内容的标志牌，并建立污水排放台账。\n省和清江流域县级以上人民政府生态环境等主管部门应当对职责范围内设置的排污口建立档案制度和统计制度，组织开展排污口监测和溯源，明确排污口的责任者，对违法排污口依法予以处置。\n第二十条 清江流域县级、乡镇人民政府应当依照城乡污水处理设施建设规划，按期完成污水集中处理设施和配套管网的建设和改造，并加强对污水集中处理设施运营的监督管理。\n城镇新区建设应当按照先规划后建设的原则，优先建设污水集中处理设施和配套管网，配套管网应当与污水集中处理设施同时设计、同时施工、同时投产使用，实行雨污分流。老旧城区应当推进污水收集管网和雨污分流设施建设和改造。\n第二十一条 城乡污水集中处理设施的运营单位或者污泥处理处置单位应当按照国家规定和标准对污泥进行无害化和资源化处置,对处置后的污泥流向、用途、用量等进行跟踪、记录，并报告城镇排水主管部门、生态环境主管部门，不得擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧，不得排入水体。属于危险废物的，应当委托有资质的单位处置。\n省人民政府住房和城乡建设主管部门应当会同生态环境主管部门制定污泥处置规定，规范污泥处理设施的规划、建设以及污泥的收集、贮运、处理和监管等。\n第二十二条 清江流域县级人民政府应当根据地区特点，对未纳入城乡污水管网的村庄的生活污水，因地制宜建设分散式污水处理设施以及人工湿地、生态沟渠、生物滤池等，就近净化处理生活污水。\n第二十三条 清江流域各级人民政府应当加强环境综合治理工作，开展生活垃圾分类收集、分类处理，因地制宜采取科学的垃圾处理模式，提高垃圾减量化、资源化、无害化处理水平。\n清江流域县级以上人民政府应当规范塑料废弃物的回收利用，推广可循环、易回收、可降解替代产品，有序禁止、限制部分塑料制品的生产、销售和使用，有效治理塑料污染。\n第二十四条 清江流域县级以上人民政府应当制定并组织实施本行政区域的化肥、农药减量计划，开展测土配方施肥和农作物病虫害统防统治与绿色防控；完善废旧农用薄膜以及化肥、农药包装废弃物等回收处理制度；推进农作物秸秆露天禁烧和综合利用。\n禁止在清江流域内销售和使用剧毒、高毒、高残留农药及其混剂。省人民政府农业农村主管部门应当会同生态环境、自然资源等有关主管部门制定清江流域禁止使用的农药目录。\n省和清江流域县级以上人民政府应当支持和推进绿色有机农业发展，引导建设示范基地，加大绿色有机农产品标准化种养技术和科技成果推广应用，支持创建绿色有机农产品品牌。\n第二十五条 清江流域县级以上人民政府应当按照国家和省有关规定编制畜禽规模养殖污染防治规划，科学划定本行政区域畜禽养殖禁养区，并向社会公布。\n禁养区内不得从事畜禽规模养殖。\n省人民政府应当制定畜禽规模以下养殖污染防治办法，根据畜禽养殖数量确定畜禽规模以下养殖污染防治的标准和要求，实施分类管理。\n第二十六条 省和清江流域县级以上人民政府农业农村等有关主管部门应当加强对水产养殖的监督管理，鼓励和支持水产生态健康养殖。\n水产养殖生产者应当开展循环水、洁水养殖，加强养殖投入品管理，依法规范、限制使用抗生素等药品，开展水产环境和养殖尾水治理。水产养殖尾水排放应当符合相关规定和要求。\n禁止在江河、湖泊、水库、运河、塘堰养殖珍珠；禁止在江河、湖泊、水库、运河围栏围网（含网箱）养殖、投肥（粪）养殖。\n禁止在渔用饲料中添加激素类药品和国家规定的其他禁用药品。禁止将原料药直接添加到饲料或者用于水产养殖。\n第二十七条 省人民政府交通运输主管部门应当会同生态环境主管部门制定船舶污染防治规范；根据清江流域水环境质量状况和承载能力，对船舶实行总量控制、分类管理。\n清江流域船舶应当按照船舶污染物排放相关标准和规范，完成升级改造。县级以上人民政府交通运输主管部门应当限期淘汰不能达到污染物排放标准的船舶，强制报废超过使用年限的船舶。\n鼓励和支持清江流域船舶采用和升级改造为环保型动力。现有旅游船舶应当逐步改造为环保型动力，新入河旅游船舶应当采用环保型动力。\n第二十八条 清江流域各类船舶应当按照国家有关规定配置和使用污水、废油、垃圾等污染物、废弃物收集或者处理设备和器材，并持有合法有效的防止水域环境污染的证书与文书。\n清江流域港口、码头、装卸站和船舶修造厂应当设置船舶污染物、废弃物接收设施，接收靠泊船舶产生的残废油、含油污水、化学品洗舱水、生活污水和垃圾等，并按照规定转运和处置。未设置接收设施的，由县级以上人民政府责令限期设置。\n第二十九条 清江流域禁止生产、销售和使用含磷的洗衣粉、洗涤剂、清洁剂等洗涤用品。\n前款所称含磷洗涤用品，是指总磷酸盐含量（以五氧化二磷计）超过国家标准的洗涤用品。\n第三十条 清江流域发展旅游业应当以生态环境承载力为前提，旅游发展规划和旅游景点、线路、项目的确定应当符合清江流域水生态环境保护等规划和生态环境保护的要求，不得建设与周边环境不协调的建（构）筑物，对自然景观和环境造成破坏。\n清江流域经营餐饮、娱乐、住宿等服务行业的企业和个人，应当采用节能、节水、节材等有利于保护生态环境的技术、设备和设施，禁止将未经处理达标的污水排入水体。\n任何单位和个人不得在清江水域利用船舶或者浮动设施提供除成品快餐之外的餐饮服务。\n第三十一条 清江水域综合枢纽坝址前的漂浮物和影响水生态环境的水生植物，由综合枢纽管理单位负责打捞。\n清江水域港口、码头作业范围内的漂浮物和影响水生态环境的水生植物，由港口、码头的经营管理单位负责打捞。\n清江水域其他范围内的漂浮物和影响水生态环境的水生植物，由所在地县级人民政府负责组织打捞。\n第三十二条 地下工程设施建设或者进行地下勘探、采矿、工程降排水、人工回灌补给地下水等可能干扰地下含水层的活动，应当采取防护性措施，防止污染地下水。\n禁止利用渗井、渗坑、裂隙、溶洞以及私设暗管等方式向地下水体排放水污染物。","level":1},{"name":"第四章 生态保护与修复","text":"第三十三条 省和清江流域县级以上人民政府及其有关主管部门应当统筹流域山水林田湖草系统保护工作，建立健全水生态环境保护与修复的长效机制，促进水生态环境功能的保护与修复。\n第三十四条 省和清江流域县级以上人民政府及其有关主管部门应当加强水源涵养林的建设与保护，加大退耕还林、还草、还湿力度，开展湿地保护与修复，防止湿地面积减少和生态功能退化。禁止侵占自然湿地等水源涵养空间，已侵占的应当限期予以恢复。\n第三十五条 清江流域各级人民政府应当统筹生态清洁小流域建设，因地制宜制定生态清洁小流域建设方案，组织实施水土保持综合治理工程，采取综合治理措施控制土壤侵蚀，预防和治理水土流失。\n第三十六条 清江流域各级人民政府应当加强河流生态系统修复，适时组织符合生态要求的水生生物增殖放流，加强对外来水生物种的预警监测，维护水生生物多样性。\n水电站应当依法履行工程控制流域内水生生物保护义务，对渔业资源有影响的，应当建设渔业资源增殖放流站、洄游通道或者采取其他补救措施。\n禁止使用外来物种、杂交物种、转基因物种或者其他非本地原有物种进行增殖放流。\n禁止在禁渔区、禁渔期进行捕捞。禁止使用电鱼、毒鱼、炸鱼或者密眼网具等法律法规禁用的渔具、捕捞方法进行捕捞。\n第三十七条 省人民政府应当制定清江岸线保护和开发利用规划，统筹清江岸线资源的保护利用，严格分区管理与用途管制。\n清江流域县级以上人民政府应当按照岸线保护和开发利用规划，加强水域岸线管理，严格控制与生态保护无关的开发活动，组织开展清江岸线生态保护和生态修复；在一定范围划定生态缓冲带，开展生态缓冲带综合整治。\n第三十八条 省人民政府水行政主管部门应当加强清江流域水资源的统一调度，科学确定清江流域各河道的生态流量，保证生态用水需求，保障枯水期和鱼类产卵期生态流量。\n第三十九条 清江流域县级以上人民政府水行政、生态环境等有关主管部门应当确定本行政区域生态流量管控指标，建立生态流量监控平台，实现对流域内生态流量泄放情况的实时监控。水利水电、航运枢纽等工程应当将生态用水调度纳入日常运行调度规程，建立常规生态调度机制，保证清江流域生态流量。\n清江流域内的水电站应当配套建设生态流量泄放设施，合理安排闸坝下泄水量，保证最小下泄生态流量不低于本河段多年平均径流流量的10%。来水流量不能满足最小下泄生态流量的，来水流量应当全部泄放。配套建设的生态流量泄放设施未建成、未经验收或者验收不合格的，水电站不得投入生产。\n清江流域内的水电站应当按照要求安装生态流量监测监控设施，实行在线实时监测监控，并及时将真实、完整的生态流量数据传输到政府有关部门生态流量监控平台。\n第四十条 清江流域严格控制新建水电站。禁止新建装机5万千瓦以下的小水电站。\n省人民政府生态环境主管部门应当会同发展改革、水行政等主管部门组织对清江流域内水电站进行生态环境影响评估。对不符合国家和省有关规定的，责令限期整改或者退出，同步开展生态修复。\n第四十一条 严格限制在清江流域新建拦水坝。因供水、防洪、灌溉等确需建设的，应当依法进行生态环境影响评价。已经建成的，县级以上人民政府及其有关主管部门应当组织论证，对生态影响较大的拦水坝限期拆除。\n第四十二条 清江流域各级人民政府以及自然资源等有关主管部门应当建立健全地质灾害防治工作责任制，制定地质灾害防治方案，组织开展地质灾害隐患点排查，加强地质灾害险情的动态监测和预报，及时发现、防范地质灾害。","level":1},{"name":"第五章 保障与监督管理","text":"第四十三条 省人民政府应当加大对清江流域水生态环境保护的财政资金投入。清江流域县级以上人民政府应当建立生态保护和治理方面专项资金整合机制，统筹用于清江流域水生态环境保护。\n省和清江流域县级以上人民政府应当建立政府引导、市场运作、社会参与的多元化投融资机制，鼓励和引导社会力量参与清江流域水生态环境保护建设。\n第四十四条 省人民政府应当建立健全清江流域生态保护补偿机制，制定清江流域生态保护补偿办法，实施清江流域生态保护修复奖励政策，加大清江流域生态保护补偿资金投入。\n省人民政府及其有关主管部门应当引导受益地区与生态保护地区、流域上游与下游之间实施横向生态保护补偿。\n第四十五条 省和清江流域县级以上人民政府应当加大扶持力度，做好产业转型、就业帮扶、技能培训、社会保障、移民后扶等工作，保障和改善清江沿岸村（居）民的生产生活。\n第四十六条 清江流域县级以上人民政府应当加强对饮用水水源地保护和管理，组织相关主管部门定期监测和评估本行政区域内饮用水水源、供水单位供水、用水端水质等饮用水安全状况。饮用水安全状况信息应当定期向社会公开。\n第四十七条 清江流域县级以上人民政府有关主管部门应当对工业源、化学品仓储、污水处理厂、垃圾填埋场、采矿地、污染场地、尾矿库等固定风险源进行排查，建立风险源档案，定期开展风险评估和环境安全隐患排查。\n第四十八条 省人民政府生态环境主管部门应当会同水行政等有关主管部门完善清江流域水环境监测网络，健全水环境监测、预警、应急系统，提高监测、预警和应急处置能力。\n省和清江流域县级以上人民政府生态环境主管部门应当科学规划、合理设定清江流域水环境质量监测点位或者断面，加强对清江干支流交汇处、饮用水水源地、工业园区、人口密集区等区域的水质监测。\n第四十九条 清江流域各级人民政府应当对本行政区域内水体进行排查，向社会公布黑臭水体名称、地点、责任人及达标期限;编制黑臭水体整治方案，采取控源截污、垃圾清理、清淤疏浚、生态修复等措施综合整治，每半年向社会公开治理情况。\n第五十条 清江流域县级以上人民政府及其有关部门应当组织开展跨行政区域水污染的联合监测、联合检查和联合执法，建立健全重大建设项目生态环境影响评价会商、监测数据实时共享、突发水环境事件应急预警和联动机制，加强水污染联合防治和纠纷协调处理。\n第五十一条 任何单位和个人有权对清江流域水生态环境保护工作提出意见和建议，对污染水生态环境的行为进行投诉、举报。\n省和清江流域县级以上人民政府有关主管部门应当完善水环境信息公开机制，依法公开排污口设置、水环境质量监测、实行排污许可重点管理的企业事业单位和其他生产经营者名录、突发水环境事件处置、违法行为行政处罚等信息。\n省和清江流域各级人民政府及有关主管部门应当完善公众参与程序，规划编制、项目审批、生态环境影响评价、预防和修复治理等与公众密切相关的事项，应当充分听取公众的意见。\n第五十二条 省和清江流域县级以上人民政府生态环境等有关主管部门应当定期通报清江流域破坏水生态环境的违法行为，并将相关信息纳入省社会信用信息管理平台，作为有关主管部门实施失信联合惩戒的依据。\n第五十三条 清江流域县级以上人民政府应当每年向本级人民代表大会或者其常务委员会报告清江流域水生态环境保护情况，对发生的重大水生态环境事件应当及时向本级人民代表大会常务委员会报告，依法接受监督。","level":1},{"name":"第六章 法律责任","text":"第五十四条 违反本条例，法律、法规有规定的，从其规定。\n第五十五条 违反本条例第二十一条第一款规定，将污泥排入水体的，由生态环境主管部门责令停止违法行为，采取治理措施消除污染，没收违法所得，并处20万元以上200万元以下罚款，对直接负责的主管人员和其他直接责任人员处2万元以上10万元以下罚款；情节严重的，责令限制生产、停产整治；造成严重后果的，处200万元以上500万元以下罚款；拒不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。\n第五十六条 违反本条例第二十四条第二款规定，在清江流域销售剧毒、高毒、高残留农药及其混剂的，由农业农村主管部门责令停止销售，没收违法所得和违法经营的农药以及用于违法经营的工具、设备等，违法销售的农药货值金额不足1万元的，并处5千元以上5万元以下罚款，货值金额1万元以上的，并处货值金额五倍以上十倍以下罚款。使用剧毒、高毒、高残留农药及其混剂，使用者为单位的，处5万元以上10万元以下罚款；使用者为个人的，处500元以上2千元以下罚款，情节严重的，处2千元以上1万元以下罚款。\n第五十七条 违反本条例第二十九条第一款规定，在清江流域生产、销售含磷洗涤用品的，由市场监督管理部门责令其停止生产、销售，没收违法生产、销售的产品和违法所得，并处违法生产、销售产品货值金额等值以上三倍以下罚款。服务业经营者以及工业企业使用含磷洗涤用品的，由生态环境主管部门予以警告，责令停止使用，处2千元以上1万元以下罚款；情节严重的，处1万元以上3万元以下罚款。\n第五十八条 违反本条例第三十条第三款规定，在清江水域利用船舶或者浮动设施提供除成品快餐之外的餐饮服务的，由市场监督管理部门责令停止违法行为，处5千元以上2万元以下罚款。\n第五十九条 违反本条例第三十六条第三款规定，使用外来物种、杂交物种、转基因物种或者其他非本地原有物种进行增殖放流的，由农业农村主管部门责令限期捕回，处5万元以上10万元以下罚款；造成严重后果的，处10万元以上100万元以下罚款；逾期不捕回的，由农业农村主管部门代为捕回或者采取降低负面影响的措施，所需费用由违法者承担。\n第六十条 违反本条例第三十九条第二款规定，水电站未按照规定保证下泄生态流量的，由生态环境主管部门责令改正，处5万元以上20万元以下罚款；拒不改正的，可以自责令改正之日的次日起，按照原处罚数额按日连续处罚；造成严重后果的，责令停产或者关闭。\n配套建设的生态流量泄放设施未建成、未经验收或者经验收不合格，水电站即投入生产的，或者在验收中弄虚作假的，由生态环境主管部门责令限期改正，处20万元以上100万元以下罚款；逾期不改正的，处100万元以上200万元以下罚款；对直接负责的主管人员和其他责任人员处5万元以上10万元以下罚款；造成严重后果的，责令停产或者关闭。\n第六十一条 违反本条例第四十条第一款规定，在清江流域新建装机5万千瓦以下小水电站的，由水行政主管部门责令限期拆除；逾期不拆除的，依法强制拆除，所需费用由违法者承担，并处1万元以上10万元以下罚款。\n第六十二条 国家机关及其工作人员在清江流域水生态环境保护工作中滥用职权、玩忽职守、徇私舞弊的，由其主管机关或者监察机关对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第六十三条 本条例自2020年1月1日起施行。","level":1}]},{"id":"h0216","sections":[{"name":"","text":"(2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议通过 根据2026年7月30日湖北省第十四届人民代表大会常务委员会第二十五次会议《关于集中修改、废止涉及生态环境法典省本级地方性法规的决定》修正)","level":0},{"name":"第一章 总则","text":"第一条 为了加强开发区建设,规范开发区管理服务，促进开发区体制机制创新，发挥开发区的功能优势和开放引领作用，推动全省高质量发展，根据有关法律、行政法规，结合本省实际，制定本条例。\n第二条 本省行政区域内开发区的规划建设、管理服务以及相关活动，适用本条例。\n本条例所称开发区，包括经国务院批准设立的经济技术开发区、高新技术产业开发区等国家级开发区和经省人民政府批准设立的经济开发区、高新技术产业园区、工业园区、产业园等省级开发区。\n第三条 开发区应当坚持创新、协调、绿色、开放、共享的发展理念，遵循统一规划、市场主导、产业集聚、特色发展的原则，建设成为新型工业化发展的引领区、开放型经济和体制创新的先行区、创新创业的集聚区、生态文明和可持续发展的绿色生态区、高水平营商环境的示范区。\n第四条 县级以上人民政府应当加强对开发区工作的领导，将开发区的建设和发展纳入国民经济和社会发展规划，制定促进开发区建设和发展的政策措施，建立议事协调机制，完善和落实开发区工作目标责任制。\n县级以上人民政府有关部门按照各自职责，做好开发区的相关工作。\n第五条 省人民政府设立开发区工作领导小组，统筹开发区的建设与发展，研究解决开发区建设与发展中的重大问题。\n省开发区工作领导小组办公室设在省人民政府发展改革部门，统筹负责全省开发区改革和创新发展的指导、协调和服务工作。\n省人民政府有关部门按照职责分工负责开发区的具体指导、管理和服务工作。","level":1},{"name":"第二章 管理体制","text":"第六条 开发区管理机构作为开发区所在地人民政府的派出机关,依法履行以下职责：\n（一）宣传、贯彻执行有关法律、法规，制定和实施开发区各项管理制度；\n（二）负责组织实施全省开发区总体发展规划、市（州）开发区发展规划，编制开发区综合发展规划和有关专项规划；\n（三）依法或者根据授权对开发区权限范围内的投资建设项目进行审批、核准、备案；\n（四）协调落实区域内基础设施和公共服务设施的建设和管理；\n（五）发布公共信息，为企业和相关机构提供指导、咨询和服务；\n（六）健全招商引资制度，建立招商引资服务体系；\n（七）协调解决企业发展中存在的难题；\n（八）协助落实各项监管责任；\n（九）法律、法规规定的其他职责。\n第七条 开发区所在地人民政府应当做好开发区的社会管理、公共服务和市场监管等工作。\n开发区管理机构根据实际需要和承接能力，提出行使有关管理和服务职能的目录，依照法定程序报请批准后公布实施。\n第八条 开发区所在地人民政府及其有关部门可以依法委托开发区管理机构行使相应的行政执法权。\n开发区管理机构经依法批准，可以整合内部执法力量，设立综合执法机构，优化执法环境，提高执法效率。\n第九条 开发区所在地人民政府应当按照国家和省有关规定，依法制定并公布开发区管理机构权力清单、责任清单，健全权力监管、制约和协调机制，加强事中事后监管和信用监管。\n第十条 鼓励和支持开发区管理机构按照机构编制管理相关规定，根据开发区发展需要，在核定的机构总数内，自主设置内设机构，推进机构设置和职能配置优化、协同、高效。\n鼓励和支持开发区管理机构根据干部人事政策和发展需要，在核定的用人额度内，创新选人用人机制。\n鼓励和支持开发区管理机构探索实行兼职兼薪、年薪制、协议工资制等多种分配方式。\n第十一条 鼓励和支持开发区在管理工作中，推行政企分开、政资分开，实行管理机构与运营企业分离的制度，管理机构负责开发区的政策制定、发展规划、行政审批、投资促进、企业服务等工作，专业运营企业负责开发区的区域开发、投融资、基础设施建设、招商引资、专业服务等工作。\n第十二条 健全开发区财政预算管理和独立核算机制，开发区预算纳入所在地人民政府预算。开发区所在地人民政府应当与开发区明确投入和收益分配机制，支持和促进开发区发展。\n开发区应当加强债务管理，提升稳健发展能力。开发区所在地人民政府应当加强对开发区债务的举借、使用和管理情况的监督。\n第十三条 省人民政府应当建立全省开发区综合评价考核制度，对各类开发区实行差异化评价，重点评价增量增幅和质量效益，考核结果与新增建设用地指标、扩区调区升级、项目资金等奖励机制挂钩。对资源利用效率低下、生态环境保护不到位、发展滞后等考核不合格且整改不到位的开发区，按照有关规定进行撤并整合。","level":1},{"name":"第三章 规划建设","text":"第十四条 省人民政府组织编制全省开发区总体发展规划，科学确定开发区的区域布局，明确开发区的数量、规模、产业布局、发展目标，并与全省国民经济和社会发展规划、国土空间规划、生态环境保护规划等相衔接。\n市（州）人民政府应当根据全省开发区总体发展规划，结合本地经济基础、产业特点、资源和环境条件等，组织编制市（州）开发区发展规划，确定开发区的空间布局、产业定位和建设运营模式等。\n第十五条 开发区管理机构应当根据全省开发区总体发展规划和市（州）开发区发展规划，综合考虑区位优势、资源禀赋、产业基础和生态环境承载能力等条件，编制本开发区综合发展规划，并报开发区所在地人民政府批准后组织实施。\n开发区管理机构编制开发区综合发展规划应当科学布局，突出生产功能，统筹生活区、商务区和办公区等城市功能，促进产业发展和人居环境改善，推进产城融合和新型城镇化建设。\n第十六条 开发区的设立应当符合全省开发区总体发展规划和国家、省规定的条件。\n申报省级开发区的，由省人民政府发展改革、科技、经济和信息化、商务等部门按照职责分工会同有关部门提出审核意见，报省人民政府批准。\n申报国家级开发区的，经省人民政府发展改革、科技、经济和信息化、商务等部门按照职责分工会同有关部门提出审核意见，由省人民政府报国务院批准。\n开发区需要进行更名、调整的，应当按照设立程序报请批准。\n第十七条 开发区的规划和建设应当遵守生态保护红线、环境质量底线、资源利用上线和生态环境准入清单，严格执行生态环境影响评价制度，在空间布局、总量管控、生态环境准入方面运用生态环境影响评价结果。\n第十八条 开发区应当建立安全风险评估论证机制，科学合理规划企业选址和生活空间布局，确定重大危险区域安全风险等级和风险容量，健全和完善重大安全风险联防联控制度。\n第十九条 开发区所在地人民政府应当将开发区基础设施和公共服务设施建设纳入国土空间规划，实现共建共享。开发区应当配套建设雨污分流系统、污水集中处理设施和污染在线监控系统。\n鼓励有条件的开发区建设地下综合管廊和雨水回收利用系统。\n第二十条 开发区应当依法合理、节约集约开发利用土地资源，制定开发区土地的投资强度、产出效益等标准，提升土地产出率。\n开发区所在地人民政府应当将开发区用地纳入土地统一供应管理，合理确定用地结构，优先保障重大基础设施、科技创新、文化创意、先进制造业、现代服务业项目的合理用地。新增工业和生产性服务业用地计划原则上安排在开发区，推行新增工业用地标准地出让。\n开发区可以通过收购储备、流转、协议置换、合作经营、自主开发等方式，对开发区闲置土地、低效用地等进行开发利用。\n省人民政府应当加强开发区土地节约集约利用评价，并将其纳入全省开发区综合评价考核体系。\n第二十一条 开发区应当建立和完善投资主体多元化、融资渠道多样化、资本管理市场化的运营管理机制。\n鼓励社会资本参与开发区公共服务、基础设施项目建设，或者在现有的开发区投资建设、运营特色产业园。\n第二十二条 鼓励开发区按照优势互补、产业联动、市场导向、利益共享的原则，对接国家发展战略，与其他地区、开发区或者跨国公司开展合作，建设产业园区和国际合作园区。\n支持开发区与国家自主创新示范区、自由贸易试验区等联动发展。","level":1},{"name":"第四章 产业发展","text":"第二十三条 省人民政府应当加强对市（州）产业发展规划的统筹指导。开发区所在地人民政府应当制定本行政区域内开发区产业发展规划，因地制宜，发挥比较优势，形成专业化、特色化、差异化的产业格局。\n第二十四条 县级以上人民政府应当支持开发区优化产业结构，推进产业基础高级化、产业链现代化，构建企业集聚、产业集群、要素集约、技术集成、服务集中的产业生态体系。\n开发区应当加快产业结构优化，支持战略性新兴产业、先进制造业和现代服务业的发展。\n鼓励和支持开发区加快产业转型升级，改造提升传统产业，培育壮大本地特色主导产业。\n第二十五条 开发区所在地人民政府应当制定并公布开发区产业优先发展目录和产业准入负面清单，对建设项目产业政策、规划选址、环境、安全、用地标准等方面进行审查，实现绿色、循环、低碳发展。\n第二十六条 开发区管理机构应当根据开发区产业发展规划和产业配套，制定招商引资政策，创新招商引资方式，开展市场化、专业化和规范化招商，建立健全招商项目跟踪服务机制，履行依法作出的招商引资承诺。\n第二十七条 鼓励开发区创建各类国家级、省级示范基地或者示范园区，支持企业建设新兴产业发展联盟和产业技术创新战略联盟。\n第二十八条 支持开发区发展科技咨询、现代物流、知识产权服务、金融服务、法律服务、资产评估、信用评级、人力资源服务等服务业，为开发区的生产经营和创新创业活动提供服务。\n第二十九条 开发区所在地人民政府应当综合运用政府购买服务、资助、奖励等方式，支持建设各种形式的协同创新平台。\n鼓励企业、高等院校、科研机构以及其他组织和个人在开发区设立研究开发机构，创办科技企业孵化器、科技园、创客空间、创业服务中心等产业促进机构。\n开发区应当促进区内企业与高等院校、科研机构共建实验室、企业技术中心、工业技术研究院等技术开发平台，形成以企业为主体、市场为导向、政产学研用融合的技术创新体系，加速科技成果的转化。\n第三十条 县级以上人民政府设立的产业扶持、科技创新、生态环保等专项资金应当向开发区倾斜，产业转型升级发展等各类基金项目应当优先安排在开发区。\n开发区可以按照市场化原则设立科技创新发展基金、产业投资基金、创业投资基金，建立基金规模动态补充机制。\n支持开发区通过设立创业投资引导基金、创业投资贴息资金、知识产权作价入股等方式，搭建科技人才与产业对接平台。\n第三十一条 鼓励和支持科技含量高、质量效益好、产业关联强、拥有高价值知识产权的项目进入开发区。支持区内企业建立境外研发、生产基地和销售网络，开展对外投资，拓展知识产权境外布局。","level":1},{"name":"第五章 服务保障","text":"第三十二条 县级以上人民政府及其有关部门应当在体制机制创新、规划编制、要素供给、项目安排、科技创新、基础设施建设等方面支持开发区的发展。\n第三十三条 开发区应当建立和完善综合服务和促进体系，根据需要设立招商、产业促进、创新创业、投融资、法律服务、土地开发利用等服务平台。\n第三十四条 开发区所在地人民政府应当支持开发区建设市场化、法治化、国际化的营商环境。\n开发区管理机构应当按照便利、高效、透明的原则，简化办事程序，提高办事效率和政务服务水平。\n省人民政府应当定期开展开发区营商环境评价，将开发区营商环境作为所在地营商环境评价的重要内容。\n第三十五条 开发区所在地人民政府和开发区管理机构应当统筹政务信息系统和服务资源，统一服务标准，优化服务流程，为开发区市场主体提供一个窗口受理、一站式服务、一网通办的政务服务。\n第三十六条 开发区所在地人民政府和开发区管理机构应当制定高层次人才、高技能领军人才和创新创业人才引进、培养、服务、激励等相关办法，为开发区人才签证、停（居）留、项目与奖励申报、执业、创新创业、购买或者租赁住房、子女入学、医疗保障等提供便利。\n开发区管理机构对招商引资和专业岗位急需的高层次人才、高技能领军人才、特殊人才，可以实行特职特聘、特岗特薪。\n探索实行开发区海外高层次人才和急需紧缺人才的高级职称直聘制度。\n第三十七条 支持在开发区组建行业商（协）会等社会组织，支持其依法开展工作。\n第三十八条 开发区所在地人民政府和开发区管理机构应当健全知识产权保护体系，完善知识产权快速审查、快速确权、快速维权机制和纠纷多元化解机制。\n鼓励开发区企业和行业商（协）会组建产业知识产权联盟，提升产业竞争力。\n第三十九条 开发区培育和发展专业化、国际化的律师事务所以及仲裁、调解、公证、鉴定等法律服务机构，鼓励境内外法律服务机构在开发区依法开展法律专业服务。\n第四十条 开发区所在地人民政府和开发区管理机构应当建立健全信息公开制度，及时准确向社会公布有关信息。\n支持开发区管理机构与开发区所在地人民政府有关部门可靠交换、安全共享经济和社会发展相关统计数据以及公共资源交易、人口、交通和空间地理等信息。\n第四十一条 开发区所在地人民政府及其有关部门应当按照国家有关规定，依法及时公布、公示和共享市场主体的社会信用信息，并纳入省社会信用信息平台，实行守信联合激励和失信联合惩戒。\n鼓励和支持信用服务机构开发和创新信用产品，推动信用调查、信用担保、信用保险等信用产品在开发区的应用。\n第四十二条 开发区管理机构应当健全依法决策机制，规范行政决策和执行程序，建立重大决策公众参与、专家论证、风险评估、合法性审查、公平竞争审查、集体讨论决定和责任追究制度。\n开发区设立专家咨询委员会，为开发区的改革发展和管理创新提供专业咨询和决策支持。\n开发区制定涉企政策时，应当充分听取市场主体、行业商（协）会以及其他利益相关人的意见、建议。\n第四十三条 开发区所在地人民政府和开发区管理机构应当建立健全维权投诉协调机制，受理企业、投资者反映的诉求以及对各类违法违规行为的投诉和举报。有关方面接到投诉、举报后，应当依法及时处理。\n第四十四条 开发区内进行的创新活动，未能达到预期效果或者造成一定损失，但同时符合以下情形的，免予追究相关人员的责任，对其不进行负面评价：\n（一）创新活动不违反法律、法规规定；\n（二）创新活动符合决策程序；\n（三）相关人员履行了勤勉尽责义务；\n（四）相关人员未非法牟取私利；\n（五）相关人员未恶意串通损害公共利益或者他人合法权益。\n第四十五条 国家机关及其工作人员在开发区工作中滥用职权、玩忽职守、徇私舞弊的，由其主管机关或者监察机关对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第四十六条 本省行政区域内海关特殊监管区域、开发区托管区域可以参照本条例执行。\n第四十七条 本条例自2020年3月1日起施行。1996年7月24日湖北省第八届人民代表大会常务委员会第二十一次会议通过的《湖北省经济技术开发区条例》同时废止。","level":1}]},{"id":"h0217","sections":[{"name":"","text":"（2009年7月31日湖北省第十一届人民代表大会常务委员会第十一次会议通过 根据2010年7月30日湖北省第十一届人民代表大会常务委员会第十七次会议《关于集中修改、废止部分省本级地方性法规的决定》第一次修正 根据2017年11月29日湖北省第十二届人民代表大会常务委员会第三十一次会议《关于集中修改、废止部分省本级地方性法规的决定》第二次修正 2019年11月29日湖北省第十三届人民代表大会常务委员会第十二次会议修订）","level":0},{"name":"第一章 总则","text":"第一条 为了保障公民宗教信仰自由，维护宗教和睦与社会和谐，规范宗教事务管理，提高宗教工作法治化水平，根据宪法、有关法律和国务院《宗教事务条例》等行政法规，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内的宗教事务及其管理活动。\n第三条 公民有宗教信仰自由。\n任何组织或者个人不得强制公民信仰宗教或者不信仰宗教，不得歧视信仰宗教的公民（以下简称信教公民）或者不信仰宗教的公民（以下简称不信教公民）。\n信教公民和不信教公民、信仰不同宗教的公民应当相互尊重、和睦相处。\n第四条 坚持党对宗教工作的领导，积极引导宗教与社会主义社会相适应。\n宗教事务管理坚持保护合法、制止非法、遏制极端、抵御渗透、打击犯罪的原则。\n第五条 各宗教坚持中国化方向，践行社会主义核心价值观；坚持独立自主自办的原则，宗教团体、宗教院校、宗教活动场所和宗教事务不受外国势力支配。\n第六条 宗教团体、宗教院校、宗教活动场所、信教公民的合法权益和正常的宗教活动受法律保护。\n宗教团体、宗教院校、宗教活动场所、信教公民应当遵守宪法、法律、法规、规章，维护国家统一、民族团结、宗教和睦与社会稳定。\n任何组织或者个人不得利用宗教破坏民族团结、分裂国家、制造矛盾冲突和进行恐怖活动；不得宣扬、支持、资助宗教极端主义；不得利用宗教干预行政、司法、教育等国家职能的实施；不得利用宗教进行其他违法活动。\n第七条 各级人民政府应当建立健全宗教工作机制，落实宗教工作责任制，保障工作力量和条件。\n县级以上宗教事务部门依法对本行政区域内涉及国家利益和社会公共利益的宗教事务进行管理。教育、公安、民政、自然资源、住房和城乡建设、文化和旅游、应急管理、新闻出版等有关部门在各自职责范围内，做好宗教事务管理工作。\n乡镇人民政府、街道办事处应当明确宗教事务管理人员，做好本行政区域内的宗教事务管理工作。\n村（居）民委员会应当依法协助人民政府管理宗教事务，发现非法宗教团体、非法宗教活动场所、非法传教人员以及非法宗教活动等违法行为的，及时制止并向当地人民政府报告。\n第八条 各级人民政府应当为宗教团体、宗教院校和宗教活动场所提供公共服务，支持宗教界人士和信教公民在促进经济社会发展中发挥积极作用。\n有关部门以及广播、电视、报刊、网络等媒体应当加强宗教相关法律、法规、政策的宣传，营造良好的舆论氛围。","level":1},{"name":"第二章 宗教团体","text":"第九条 宗教团体的成立、变更和注销，应当按照国家社会团体管理的有关规定，向县级以上宗教事务部门提出申请，经审查同意后，向同级人民政府民政部门申请办理登记。\n民政部门应当将宗教团体准予成立、变更或者注销登记的情况依法予以公告。\n第十条 宗教团体应当履行以下职能：\n(一)协助人民政府宣传和贯彻落实法律、法规、规章和政策，教育、引导信教公民爱国守法，弘扬社会主义核心价值观，维护信教公民的合法权益；\n(二)指导宗教教务，规范教务活动，加强教风建设，制定有关宗教院校、宗教活动场所、宗教教职人员等方面的规章制度并督促落实；\n(三)从事宗教文化研究，挖掘教义教规中有利于社会和谐、民族团结、时代进步、健康文明的内容，对教义教规作出符合当代中国发展进步要求、符合中华优秀传统文化的阐释，开展宗教思想建设；\n(四)开展宗教教育培训，培养宗教教职人员；\n(五)认定、管理宗教教职人员，健全宗教教职人员奖惩和退出机制；\n(六)法律、法规、规章和章程规定的其他职能。\n第十一条 宗教团体应当建立健全内部管理制度，明确议事、决策、执行和监督等方面的职责。\n宗教院校、宗教活动场所和宗教教职人员应当遵守宗教团体制定的规章制度。","level":1},{"name":"第三章 宗教院校","text":"第十二条 宗教院校应当依法设立。\n省宗教团体申请设立宗教院校的，应当向省宗教事务部门提出。省宗教事务部门应当自收到申请之日起30日内，提出审核意见，报国家宗教事务部门审批。\n宗教院校变更校名、校址、隶属关系、培养目标、学制、办学规模等以及合并、分设和终止，应当按照前款规定的程序办理。\n经批准设立的宗教院校，可以按照有关规定向省人民政府民政部门申请法人登记。\n第十三条 省宗教团体应当履行办学主体责任，指导宗教院校明确培养目标、制定办学章程和课程设置计划、规范教学管理，落实必要的办学资金，提供必需的办学条件。\n宗教院校应当坚持正确的办学方向，加强爱国主义教育；建立健全内部管理制度和运行机制，加强教学能力建设，合理设置课程，提高教学质量，维护正常教学秩序。\n第十四条 宗教院校应当按照审批核定的招生对象、范围、学制和规模进行招生。\n宗教院校招生，应当由符合条件的考生自愿报名，经考生经常居住地或者宗教教职人员资格认定地的宗教团体推荐，通过考试择优录取，并报省宗教事务部门备案。\n第十五条 宗教院校聘用外籍专业人员，应当征得省宗教团体同意后，向省宗教事务部门提出申请。\n省宗教事务部门应当自收到申请材料之日起20日内提出审核意见，报国家宗教事务部门审批。经国家宗教事务部门同意后，宗教院校到所在地外国人工作管理部门办理相关手续。\n第十六条 宗教团体和寺院、宫观、清真寺、教堂（以下简称寺观教堂）开展培养宗教教职人员的宗教教育培训，学习时间在3个月以上的，应当报省或者设区的市、自治州宗教事务部门审批；学习时间在3个月以下的，应当报县级以上宗教事务部门备案。\n非宗教团体、非宗教院校、非宗教活动场所不得开展宗教教育培训。","level":1},{"name":"第四章 宗教活动场所","text":"第十七条 宗教活动场所包括依法登记的寺观教堂和其他固定宗教活动处所，其具体区分标准由省宗教事务部门制定，报国家宗教事务部门备案。\n县级以上宗教事务部门应当根据本地区信教公民宗教活动需求以及相关宗教团体意见，提出宗教活动场所布局设置建议，报同级人民政府。\n县级以上人民政府应当根据实际需要，将宗教活动场所建设纳入国土空间规划；相关部门编制规划时，应当听取宗教事务部门的意见。\n第十八条 筹备设立、扩建、异地重建宗教活动场所，应当符合国家规定的条件，按照程序报请批准。\n宗教活动场所的建设应当严格按照审批规定进行，不得擅自变更建设规划、扩大建设规模、超过筹备设立期限。\n第十九条 宗教活动场所经批准筹备并建设完工后，应当按照国家和省的有关规定向所在地县级宗教事务部门申请登记。未办理登记的，不得对外开放、组织开展宗教活动。\n宗教活动场所符合法人条件的，经所在地宗教团体同意，并报县级宗教事务部门审查同意后，可以到同级人民政府民政部门办理法人登记。\n第二十条 在宗教活动场所内新建或者改建建筑物，应当由该宗教活动场所向所在地县级以上宗教事务部门提出申请，经批准后，依法办理规划、建设、消防、环保、文物等方面的手续。\n第二十一条 宗教活动场所的名称、地址、负责人等登记内容发生变化的，应当及时向原登记管理机关申请变更登记。\n宗教活动场所有以下情形之一的，原登记管理机关应当依法注销登记：\n（一）已登记的宗教活动场所不再符合相关登记条件，宗教团体或者宗教活动场所申请注销的；\n（二）宗教活动场所自行解散、合并或者由于其他原因终止，宗教团体或者宗教活动场所申请注销的；\n（三）宗教活动场所登记证或者宗教活动场所法人登记证依法被吊销的；\n（四）法律、法规规定应当注销的其他情形。\n宗教活动场所注销登记后，任何组织或者个人不得以原宗教活动场所名义开展活动。\n第二十二条 宗教活动场所应当成立管理组织，实行民主管理。宗教活动场所管理组织成员由宗教教职人员或者符合本宗教规定的主持宗教活动的其他人员和所在地信教公民代表等组成，经过民主协商推选产生，并报该场所的登记管理机关备案。\n宗教活动场所管理组织成员应当爱国守法，其健康状况、年龄等能够胜任职责要求。\n第二十三条 宗教活动场所管理组织应当履行以下职责：\n（一）团结和引导信教公民爱国守法，维护国家安全、民族团结、宗教和睦，维护信教公民合法权益，抵制非法传教；\n（二）建立健全本场所管理制度；\n（三）安排本场所的宗教活动，处理日常事务，定期公布财务管理情况；\n（四）保护和维护本场所的建筑、文物、园林等，做好安全、消防、卫生等工作，维护正常秩序；\n（五）防范和处理突发事件，并及时向相关部门报告；\n（六）法律、法规、规章规定的其他职责。\n第二十四条 宗教活动场所应当加强场所内常住或者暂住人员的管理，并按照国家有关规定到所在地公安机关办理相关登记。\n任何组织或者个人进入宗教活动场所，应当尊重该宗教的信仰和习惯，不得干扰正常的宗教活动。\n第二十五条 宗教活动场所内可以经销宗教用品、宗教艺术品和宗教出版物，并遵守国家对经销商品、出版物方面的有关规定。\n宗教活动场所不得进行违背社会公德、违背本宗教教义教规的活动，不得利用宗教非法敛财，不得为他人非法敛财等违法活动提供条件。\n第二十六条 宗教事务部门应当对宗教活动场所遵守法律、法规、规章，建立和执行场所管理制度，登记项目变更以及宗教活动和涉外事务等情况进行监督检查。\n宗教活动场所应当接受宗教事务部门和其他有关部门的监督检查和指导。\n第二十七条 宗教团体、寺观教堂拟在寺观教堂内修建大型露天宗教造像的，应当符合国家有关规定，由省宗教团体向省宗教事务部门提出申请。省宗教事务部门应当自收到申请之日起30日内提出意见，报国家宗教事务部门审批。\n在寺观教堂外，任何组织或者个人不得修建大型露天宗教造像，不得利用投影、灯光或者其他方式营造大型露天宗教造像的图像、影像。\n第二十八条 景区内有宗教活动场所的，其所在地县级以上人民政府应当协调、处理宗教活动场所与景区管理组织及园林、自然资源、文化和旅游等方面的利益关系，依法维护宗教活动场所、宗教教职人员、信教公民的合法权益，保护正常的宗教活动。\n已有以宗教活动场所为主要游览内容的景区，景区内的宗教活动场所由宗教事务部门依法管理。\n有关部门到景区内的宗教活动场所依法执行公务的，景区管理组织应当予以配合。\n景区、游览参观点内不属于宗教活动场所的建筑物、构筑物，不得设置宗教设施、宗教标识物，不得接受宗教性捐赠或者进行宗教活动。\n第二十九条 信教公民有进行经常性集体宗教活动需要，尚不具备条件申请设立宗教活动场所的，由信教公民代表依法向县级宗教事务部门提出申请设立临时活动地点。信教公民代表应当是拟设临时活动地点所在地的户籍居民或者常住居民。\n县级宗教事务部门指定临时活动地点时，应当征求所在地乡镇人民政府、街道办事处和宗教团体的意见；对涉及公共利益或者与他人有重大利益关系的，应当听取周边单位、居民和其他利益相关人的意见。\n县级宗教事务部门作出批准决定的，应当自作出决定之日起10日内书面通知申请人，同时抄送临时活动地点所在地乡镇人民政府、街道办事处和宗教团体，并报设区的市、自治州宗教事务部门备案。\n临时活动地点有效期最长为三年。期满后不具备设立宗教活动场所条件、仍有举行经常性集体宗教活动需要的，应当重新申请。\n第三十条 临时活动地点应当布局合理，不得妨碍周边单位、学校和居民的正常生产、学习、生活等。同一宗教的活动场所能够满足信教公民进行经常性集体宗教活动需要的，一般不得指定临时活动地点。\n在临时活动地点举行集体宗教活动的，人数不得超过其容纳规模。\n乡镇人民政府、街道办事处在县级宗教事务部门指导下对临时活动地点的活动进行监督管理，村（居）民委员会应当予以协助。","level":1},{"name":"第五章 宗教教职人员","text":"第三十一条 宗教教职人员经宗教团体按照全国性宗教团体制定的办法认定，报县级以上宗教事务部门备案后，可以从事宗教教务活动。\n宗教团体应当建立宗教教职人员档案。宗教事务部门应当对宗教教职人员档案管理进行指导。\n第三十二条 宗教教职人员有以下情形之一的，宗教团体应当到原备案部门办理注销手续，收回其宗教教职人员证书，并予以公告：\n（一）宗教团体根据本宗教的有关规定取消宗教教职人员资格的；\n（二）宗教教职人员违反法律、法规、规章，情节严重，宗教事务部门建议取消宗教教职人员资格的；\n（三）宗教教职人员放弃或者因其他原因丧失宗教教职人员资格的。\n未取得或者已丧失宗教教职人员资格的，不得以宗教教职人员的身份从事活动。\n第三十三条 宗教教职人员拟任或者离任宗教活动场所主要教职的，应当经该宗教活动场所征得所在地宗教团体同意后，报所在地县级以上宗教事务部门备案。\n担任宗教活动场所主要教职的，应当具备宗教教职人员资格，具有较高的宗教修养，爱国守法，其健康状况、年龄等能够胜任职责要求。\n第三十四条 宗教教职人员一般只能担任本省一个宗教活动场所的主要教职。特殊情况下，需要兼任本省另外一个宗教活动场所主要教职的，应当经拟兼职的宗教活动场所征得所在地宗教团体同意后，由县级宗教事务部门逐级报省宗教事务部门备案。\n第三十五条 宗教教职人员在省内跨县（市、区）担任宗教活动场所主要教职的，应当经拟任职的宗教活动场所征得所在地宗教团体同意后，报县级宗教事务部门。县级宗教事务部门征求该宗教教职人员备案地县级宗教事务部门意见后，予以备案。\n外省宗教教职人员到本省担任主要教职的，应当符合国家有关规定，并经拟任职的宗教活动场所征得所在地宗教团体同意后，由县级宗教事务部门逐级报省宗教事务部门。省宗教事务部门征求该宗教教职人员备案地省级宗教事务部门意见后，予以备案。\n第三十六条 宗教教职人员应当按照本宗教团体规定，在确定的教务区域内主持宗教活动。\n本省宗教教职人员应邀到省外主持宗教活动，或者邀请省外宗教教职人员到本省主持宗教活动，应当经省宗教团体同意，并报省宗教事务部门备案。\n第三十七条 宗教教职人员依法参加社会保障并享有相关权利。宗教团体、宗教院校、宗教活动场所应当按照国家和本省有关规定为宗教教职人员办理社会保险登记。\n宗教教职人员可以按照当地有关规定，享受基本公共服务和便利。\n生活困难且符合最低生活保障条件的宗教教职人员，可以按照规定向当地申请最低生活保障待遇。","level":1},{"name":"第六章 宗教活动","text":"第三十八条 宗教活动不得影响社会秩序、工作秩序、教学秩序、生活秩序。\n信教公民的集体宗教活动，应当在宗教活动场所内或者指定的临时活动地点举行，由宗教活动场所、宗教团体或者宗教院校组织，由宗教教职人员或者符合本宗教规定的其他人员主持，按照教义教规进行。\n非宗教团体、非宗教院校、非宗教活动场所、非指定的临时活动地点不得设置宗教设施、接受宗教性的捐赠，不得组织、举行宗教活动。\n第三十九条 宗教团体、宗教院校、宗教活动场所举办研讨会、讲坛、论坛等，应当符合本宗教的宗旨或者章程规定的范围，并报县级以上宗教事务部门备案。\n非宗教团体、非宗教院校、非宗教活动场所不得组织公民出境参加宗教方面的培训、会议、活动等。\n第四十条 跨省举行超过宗教活动场所容纳规模的大型宗教活动，或者在宗教活动场所外举行大型宗教活动，主办的宗教团体、寺观教堂应当按照国家和省有关规定办理报批手续，并加强组织管理，保证宗教活动安全、有序。\n举办地的乡镇人民政府、街道办事处和县级以上人民政府有关部门应当按照各自职责做好大型宗教活动的相关协调、管理工作。\n第四十一条 宗教团体、宗教院校、宗教活动场所依法开展放生活动，应当向农业农村部门报告放生的种类、数量、规格、时间和地点等事项，并接受监督检查。\n第四十二条 涉及宗教的行为和活动不得违反教育、未成年人保护等方面的法律、法规、规章和国家其他相关规定。\n任何组织或者个人不得在宗教院校以外的学校、托幼机构、校外培训机构等教育机构以及学生公寓等场所传教、举行宗教活动、成立宗教组织、设立宗教活动场所。\n任何组织或者个人不得组织、诱使、强迫未成年人参加宗教活动。\n第四十三条 宗教团体、宗教院校和寺观教堂编印、发送宗教内部资料性出版物的，应当按照国家规定，经省宗教事务部门批准并取得相关准印许可；宗教内部资料性出版物，应当按照批准的数量印制，在规定的范围内，免费交流赠阅。\n出版公开发行的宗教出版物，按照国家出版管理的规定办理。\n任何组织或者个人不得擅自出版、印刷或者复制、发行、进口境外宗教出版物。\n第四十四条 从事互联网宗教信息服务，应当经省宗教事务部门审核同意后，按照国家互联网信息服务管理有关规定办理。\n互联网宗教信息服务提供者应当按照国家和省有关规定，加强对服务内容和传播平台的管理；发现违法信息，应当立即采取处置措施，并向有关部门报告。\n县级以上宗教事务部门应当会同有关部门加强对互联网宗教信息服务的指导和监督检查。\n第四十五条 涉及宗教内容的出版物和互联网宗教信息服务，应当符合有关法律、法规、规章的规定，并不得含有以下内容：\n（一）破坏信教公民与不信教公民和睦相处的；\n（二）破坏不同宗教之间和睦以及宗教内部和睦的；\n（三）歧视、侮辱信教公民或者不信教公民的；\n（四）宣扬宗教极端主义的；\n（五）违背宗教的独立自主自办原则的；\n（六）其他依法禁止传播的内容。","level":1},{"name":"第七章 宗教财产","text":"第四十六条 宗教团体、宗教院校、宗教活动场所对依法占有的属于国家、集体所有的财产，按照法律和国家有关规定管理和使用；对其他合法财产，依法享有所有权或者其他财产权利。\n第四十七条 宗教团体、宗教院校、宗教活动场所合法使用的土地，合法所有或者管理、使用的房屋、构筑物、文物、宗教用品、设施，接受的宗教性捐赠以及其他合法财产、收益等，受法律保护。任何组织或者个人不得侵占、哄抢、私分、损毁或者非法查封、扣押、冻结、没收、处分。\n规划和工程建设应当保护具有历史价值的宗教活动场所。\n宗教团体、宗教院校、宗教活动场所应当按照文物保护法律、法规的规定，保护、管理其占有和使用的国家文物。\n第四十八条 宗教团体、宗教院校、宗教活动场所所有的房屋和使用的土地等不动产，应当依法向县级以上人民政府不动产登记机构申请办理不动产登记；产权变更、转移的，应当及时办理变更、转移登记。\n涉及宗教团体、宗教院校、宗教活动场所不动产权属变更或者转移时，不动产登记机构应当征求同级宗教事务部门的意见。\n第四十九条 因公共利益需要，征收宗教团体、宗教院校或者宗教活动场所房屋、构筑物及附属的宗教教职人员的生活用房、用于自养的其他房屋的，应当与该宗教团体、宗教院校、宗教活动场所协商，并征求宗教事务部门的意见，按照国家房屋征收的有关规定执行。宗教团体、宗教院校或者宗教活动场所可以选择货币补偿，也可以选择房屋产权调换或者重建。\n第五十条 宗教团体、宗教院校、宗教活动场所、宗教教职人员可以依法兴办公益慈善事业。\n宗教团体、宗教院校、宗教活动场所依法设立的公益慈善组织可以开展慈善募捐。\n任何组织或者个人不得利用公益慈善活动传教。\n第五十一条 宗教团体、宗教院校、宗教活动场所可以开展以自养为目的的生产经营活动，所得收入应当用于与其宗旨相符的活动以及公益慈善事业，不得用于分配。\n第五十二条 宗教团体、宗教院校、宗教活动场所接受境内外组织和个人的捐赠应当符合国家有关规定，并用于与其宗旨相符的活动。\n宗教团体、宗教院校、宗教活动场所不得接受境外组织和个人附带条件的捐赠。\n宗教团体、宗教院校、宗教活动场所依法接受境外捐赠金额超过10万元的，应当报县级以上宗教事务部门审批；接受境外捐赠金额10万元以下的，应当报县级宗教事务部门备案。\n第五十三条 任何组织或者个人捐资修建宗教活动场所，不享有该宗教活动场所的所有权、使用权，不得从该宗教活动场所获得经济收益，不得干预其内部事务。\n禁止投资、承包经营宗教活动场所或者大型露天宗教造像，禁止对宗教活动场所进行商业运作并获取经济收益，禁止以宗教名义进行商业宣传。\n宗教活动场所用于宗教活动的房屋、构筑物及其附属的宗教教职人员生活用房不得转让、抵押或者作为实物投资。\n第五十四条 宗教团体、宗教院校、宗教活动场所应当遵守国家有关财务、税收等规定，每年定期向宗教事务部门报告财务状况、收支情况和接受、使用捐赠情况，接受其监督管理，并向信教公民公布。\n县级以上人民政府相关部门可以依法组织对宗教团体、宗教院校、宗教活动场所进行财务、资产检查和审计。","level":1},{"name":"第八章 法律责任","text":"第五十五条 违反本条例，法律、法规有规定的，从其规定。\n第五十六条 违反本条例规定，宗教活动场所有以下行为之一的，由宗教事务部门责令改正；情节较重的，由宗教事务部门责令撤换直接负责的主管人员；情节严重的，由宗教事务部门责令停止日常活动，改组管理组织，限期整改；拒不整改的，由登记管理机关依法吊销其登记证书；有违法所得、非法财物的，没收违法所得和非法财物：\n(一)未按照规定成立管理组织或者管理组织不符合要求、未履行相关职责的；\n(二)在宗教活动场所内擅自新建、改建建筑物的；\n(三)利用宗教非法敛财的；\n(四)违反宗教团体制定的规章制度的。\n第五十七条 违反本条例规定，宗教活动场所为他人非法敛财等违法活动提供条件的，由宗教事务部门给予警告，有违法所得、非法财物的，没收违法所得和非法财物，情节严重的，并处2万元以上20万元以下罚款；有违法房屋、构筑物的，由自然资源、住房和城乡建设等部门依法处理。\n第五十八条 违反本条例规定，在寺观教堂外利用投影、灯光或者其他方式营造大型露天宗教造像图像、影像的，由宗教事务部门责令改正，没收违法工具、设施设备等，处2千元以上1万元以下罚款；有违法所得的，没收违法所得。\n第五十九条 违反本条例规定，在景区、游览参观点内不属于宗教活动场所的建筑物、构筑物设置宗教设施、宗教标识物的，由宗教事务部门责令改正；拒不改正的，处2千元以上1万元以下罚款。\n在景区、游览参观点内不属于宗教活动场所的建筑物、构筑物接受宗教性捐赠或者进行宗教活动的，由宗教事务部门会同文化和旅游等有关部门责令改正；有违法所得、非法财物的，没收违法所得和非法财物，可以并处违法所得一倍以上三倍以下罚款；违法所得无法确定的，处1万元以上5万元以下罚款。\n第六十条 违反本条例规定，宗教活动场所筹备设立期对外开放、组织开展宗教活动的，由宗教事务部门责令改正；有违法所得、非法财物的，没收违法所得和非法财物，可以并处违法所得一倍以上三倍以下罚款；情节严重的，撤换筹备组织负责人。\n第六十一条 违反本条例规定，任何组织或者个人有以下行为之一的，由宗教事务部门会同相关部门责令改正；有违法所得、非法财物的，没收违法所得和非法财物，可以并处1千元以上5千元以下罚款；情节严重的，处5千元以上2万元以下罚款：\n（一）干扰正常宗教活动的；\n（二）利用公益慈善活动传教的；\n（三）宗教活动影响社会秩序、工作秩序、教学秩序、生活秩序的。\n第六十二条 未取得或者已丧失宗教教职人员资格，以宗教教职人员的身份进行宗教活动或者骗取钱财等违法活动的，由宗教事务部门责令改正；有违法所得、非法财物的，没收违法所得和非法财物，并处2千元以上1万元以下罚款。\n第六十三条 国家机关及其工作人员在宗教事务管理工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第九章 附则","text":"第六十四条 本省涉外宗教事务，本省与香港特别行政区、澳门特别行政区和台湾地区进行宗教交往，香港特别行政区、澳门特别行政区、台湾地区的居民在本省进行宗教活动，按照有关法律、法规和国家有关规定办理。\n第六十五条 本条例自2020年3月1日起施行。","level":1}]},{"id":"h0218","sections":[{"name":"第一章 总 则","text":"第一条 为了规范市人民代表大会及其常务委员会立法活动，健全地方立法制度，提高立法质量和效率，发挥立法的引领、推动、规范、保障作用，全面推进依法治市，根据《中华人民共和国立法法》《湖北省人民代表大会及其常务委员会立法条例》等法律、法规，结合本市实际，制定本条例。\n第二条 市人民代表大会及其常务委员会制定、修改、废止、解释市本级地方性法规（以下简称法规），以及相关立法活动，适用本条例。\n第三条 地方立法应当坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚持以经济建设为中心，坚持改革开放，贯彻新发展理念，推动高质量发展，保障在法治轨道上推进中国式现代化咸宁实践。\n第四条 地方立法应当符合宪法的规定、原则和精神，维护社会主义法制的统一、尊严和权威。\n地方立法应当科学合理地规定公民、法人和其他组织的权利与义务、国家机关的权力与责任。\n地方立法应当尊重和把握客观规律，从本市实际出发，体现地方特色，解决突出问题，具有针对性和可操作性。\n第五条 地方立法应当坚持和发展全过程人民民主，体现人民意志，维护人民权益，保障和促进社会公平正义。\n地方立法应当深入开展调查研究，广泛听取意见，保障人民通过多种途径参与立法活动。\n第六条 地方立法应当倡导和弘扬社会主义核心价值观，坚持法治和德治相结合，铸牢中华民族共同体意识，推动社会主义精神文明建设。\n第七条 市人民代表大会及其常务委员会根据本市的具体情况和实际需要，在不同宪法、法律、行政法规和湖北省法规相抵触的前提下，对城乡建设与管理、生态文明建设、历史文化保护、基层治理等方面的事项制定法规。法律对设区的市制定法规的事项另有规定的，从其规定。\n制定法规，对上位法已经明确规定的内容，一般不作重复性规定。\n第八条 规定本市行政区域内特别重大事项的法规，应当由市人民代表大会制定，其他法规由市人民代表大会常务委员会（以下简称常务委员会）制定。\n在市人民代表大会闭会期间，常务委员会可以对市人民代表大会制定的法规进行部分补充和修改，但不得同该法规的基本原则相抵触。补充和修改情况应当向市人民代表大会报告。\n第九条 市人民代表大会及其常务委员会应当加强对立法工作的组织协调，发挥在立法工作中的主导作用。\n市人民代表大会及其常务委员会坚持科学立法、民主立法、依法立法，通过制定、修改、废止、解释法规等多种形式，增强立法的系统性、整体性、协同性、时效性。\n市人民代表大会及其常务委员会可以根据区域、流域协调发展的需要，建立协同立法工作机制，协同制定法规，在有关区域、流域内实施。\n第十条 常务委员会根据实际需要设立基层立法联系点，推动基层立法联系点与代表之家、代表联络站等融合建设，深入听取人民代表大会代表、基层群众和有关方面对法规草案和立法工作的意见。\n常务委员会应当加强立法智库建设，通过聘请立法顾问、设立地方立法研究基地等方式，发挥专家在立法论证评估、立法理论研究等方面的作用。\n市人民代表大会及其常务委员会应当加强市人民代表大会专门委员会（以下简称专门委员会）和常务委员会工作机构的立法能力建设，推进立法人才队伍正规化、专业化、职业化。","level":1},{"name":"第二章 立法准备","text":"","level":1},{"name":"第一节 立法规划和立法计划","text":"第十一条 常务委员会通过编制立法规划和年度立法计划等形式，加强对立法工作的统筹安排。\n编制立法规划和立法计划，应当深入开展调查研究，认真研究人民代表大会代表议案和建议，征求市人民政府、市监察委员会、市中级人民法院、市人民检察院、县（市、区）人民代表大会常务委员会和有关机关、团体、组织的立法建议，并向社会公开征集立法建议。\n第十二条 国家机关、政党、团体、组织以及公民可以向常务委员会提出制定法规的建议。\n立法建议应当采用书面形式，并附有立法依据和主要内容等。公民提出的立法建议，可以只写明需要通过立法解决的主要问题和初步建议。\n第十三条 常务委员会应当组织开展立法项目课题研究、论证评估，根据经济社会发展和民主法治建设的需要，科学确定立法项目。\n立法规划和立法计划由常务委员会主任会议（以下简称主任会议）通过，并向社会公布。\n常务委员会工作机构负责编制立法规划、立法计划的具体工作，并按照常务委员会的要求，督促立法规划和立法计划的落实。\n第十四条 常务委员会立法计划应当与年度工作要点、监督工作计划、代表工作计划以及省人民代表大会常务委员会立法计划相衔接。\n市人民政府编制立法计划时，应当加强与常务委员会立法计划的衔接。\n常务委员会编制立法规划和立法计划，应当征求省人民代表大会专门委员会、常务委员会工作机构的意见；立法规划、立法计划通过后应当报省人民代表大会常务委员会备案，并组织实施。\n第十五条 专门委员会、市人民政府及其有关部门、有关团体和组织应当认真组织实施立法规划和立法计划。法规案未能按时提请审议的，提案人应当向主任会议报告并说明情况。\n立法规划和立法计划在执行过程中需要作适当调整的，由常务委员会工作机构根据专门委员会和有关方面的建议，提出方案，报主任会议审定，并报省人民代表大会常务委员会备案。\n第十六条 立法项目应当在法规立项、起草、提出法规案以及审议、提请表决等环节开展论证评估，保证立法质量。\n列入立法计划的法规项目，应当成立法规项目领导小组，组建由有关专门委员会、常务委员会工作机构、市人民政府法制机构、有关部门的工作人员和专家等组成的立法工作专班，组织制定立法工作方案，保证立法工作按照计划完成。","level":2},{"name":"第二节 法规草案的起草","text":"第十七条 向市人民代表大会或者常务委员会提出法规案，由提案人组织起草法规草案。\n有关专门委员会、常务委员会工作机构以及有关方面应当提前参与法规草案起草工作，了解情况，提出意见；综合性、全局性、基础性的重要法规草案以及推动地方经济社会发展急需的法规草案，可以由有关专门委员会或者常务委员会工作机构组织起草。\n专业性较强的法规草案，可以吸收相关领域的专家参与起草工作，或者委托有关专家、单位、组织起草。\n第十八条 起草法规草案，应当深入调查研究，广泛征求相关方面意见。涉及行政管理的法规草案，应当征求利益相关方的意见；涉及多个行政管理部门的，应当征求相关部门的意见。\n法规草案的起草单位应当主动向有关专门委员会和常务委员会工作机构报告起草工作情况。","level":2},{"name":"第三章 立法程序","text":"","level":1},{"name":"第一节 市人民代表大会立法程序","text":"第十九条 市人民代表大会主席团（以下简称主席团）可以向市人民代表大会提出法规案，由市人民代表大会会议审议。\n常务委员会、市人民政府、专门委员会可以向市人民代表大会提出法规案，由主席团决定列入会议议程，或者先交有关专门委员会审议、提出报告，再由主席团决定列入会议议程。\n市人民代表大会代表十人以上联名，可以向市人民代表大会提出法规案，由主席团决定是否列入会议议程，或者先交有关专门委员会审议，提出是否列入会议议程的意见，再由主席团决定是否列入会议议程。\n专门委员会审议法规案时，可以邀请提案人列席会议，发表意见。\n第二十条 拟提请市人民代表大会会议审议的法规案，在市人民代表大会闭会期间，可以先向常务委员会提出，经常务委员会会议依照本条例第三章第二节规定的有关程序审议后，决定提请市人民代表大会会议审议，由常务委员会或者提案人向大会全体会议作说明。\n第二十一条 常务委员会决定提请市人民代表大会会议审议的法规案，应当在会议举行的十五日前将法规草案发给代表，并可以适时组织代表研读讨论，征求意见。\n第二十二条 列入市人民代表大会会议议程的法规案，大会全体会议听取常务委员会或者提案人的说明后，由各代表团进行审议。\n各代表团审议法规案时，提案人应当派人听取意见，回答询问。\n各代表团审议法规案时，根据代表团的要求，有关机关、团体或者组织应当派人介绍情况。\n第二十三条 列入市人民代表大会会议议程的法规案，由有关专门委员会进行审议，向主席团提出审议意见，并印发会议。\n第二十四条 列入市人民代表大会会议议程的法规案，由市人民代表大会法制委员会（以下简称法制委员会）根据各代表团和有关专门委员会的审议意见，对法规案进行统一审议，向主席团提出审议结果的报告和法规草案修改稿，对重要的不同意见应当在审议结果报告中予以说明，经主席团审议通过后，印发会议。\n第二十五条 列入市人民代表大会会议议程的法规案，必要时，主席团常务主席可以召开各代表团团长或者代表团推选的代表的会议，就法规案中的重大问题听取意见，进行讨论，并将讨论的情况和意见向主席团报告。\n第二十六条 列入市人民代表大会会议议程的法规案，在交付表决前，提案人要求撤回的，应当提出书面报告，说明理由，经主席团同意，并向大会报告，对该法规案的审议即行终止。\n第二十七条 法规案在审议中有重大问题需要进一步研究的，经主席团提出，由大会全体会议决定，可以授权常务委员会根据代表的意见进一步审议，作出决定，并将决定情况向市人民代表大会下次会议报告；也可以授权常务委员会根据代表的意见进一步审议，提出修改方案，提请市人民代表大会下次会议审议决定。\n第二十八条 法规草案修改稿经各代表团审议，由法制委员会根据各代表团的审议意见进行修改，提出法规草案表决稿，由主席团提请大会全体会议表决，由全体代表的过半数通过。\n第二十九条 市人民代表大会通过的法规，应当自通过之日起十五日内，由常务委员会报请省人民代表大会常务委员会批准；经批准后，由常务委员会发布公告予以公布。","level":2},{"name":"第二节 市人民代表大会常务委员会立法程序","text":"第三十条 主任会议可以向常务委员会提出法规案，由常务委员会会议审议。\n市人民政府、专门委员会可以向常务委员会提出法规案，由主任会议决定列入常务委员会会议议程，或者先交有关专门委员会审议、提出报告，再决定列入常务委员会会议议程。如果主任会议认为法规案有重大问题需要进一步研究，可以建议提案人修改完善后再向常务委员会提出。\n市人民政府、专门委员会提请常务委员会会议审议的法规案，应当分别经市人民政府常务会议、专门委员会全体会议通过后，以书面形式提出。\n第三十一条 常务委员会组成人员五人以上联名，可以向常务委员会提出法规案，由主任会议决定是否列入常务委员会会议议程，或者先交有关专门委员会审议、提出是否列入会议议程的意见，再决定是否列入常务委员会会议议程。不列入常务委员会会议议程的，应当向常务委员会会议报告，并向提案人说明。\n专门委员会审议法规案时，可以邀请提案人列席会议，发表意见。\n第三十二条 拟提请常务委员会会议审议的法规案，应当在常务委员会会议举行的三十日前报送常务委员会，常务委员会办事机构应当及时送交有关专门委员会。未能提前三十日报送的法规案，一般不列入本次常务委员会会议议程。\n列入常务委员会会议议程的法规案，除特殊情况外，应当在会议举行的七日前将法规草案及其说明等相关材料发给常务委员会组成人员。\n第三十三条 列入常务委员会会议议程的法规案，一般应当经三次常务委员会会议审议后再交付下次常务委员会会议表决。\n常务委员会会议第一次审议法规案，在全体会议上听取提案人的说明，由分组会议进行审议。\n常务委员会会议第二次审议法规案，在全体会议上听取法制委员会关于法规草案审议结果的报告，由分组会议再次审议。\n常务委员会会议第三次审议法规案，在全体会议上听取法制委员会关于法规草案审议结果的报告，由分组会议进一步审议。\n列入常务委员会会议议程的法规案，各方面的意见比较一致的，经主任会议决定，可以经两次常务委员会会议审议后交付表决；调整事项较为单一或者部分修改的法规案，各方面意见比较一致，或者法规废止案以及遇有紧急情形的，经主任会议决定，可以经一次常务委员会会议审议后交付表决。\n第三十四条 常务委员会会议审议法规案，应当安排充足的审议时间，保证常务委员会组成人员充分发表意见。\n常务委员会分组会议审议法规案时，提案人应当派人听取意见，回答询问；立法工作专班应当派人参加。\n常务委员会分组会议审议法规案时，根据小组的要求，有关机关、团体或者组织应当派人介绍情况。\n第三十五条 常务委员会审议法规案时，主任会议根据需要，可以决定对法规草案中的主要问题召开联组会议或者全体会议进行审议。\n联组会议或者全体会议由各组推选的代表发表意见；常务委员会其他组成人员可以发表意见；列席会议的人员，经主持人同意，也可以发表意见。\n第三十六条 列入常务委员会会议议程的法规案，由有关专门委员会进行审议，提出审议意见，报告主任会议，并印发常务委员会会议。\n有关专门委员会审议法规案时，可以邀请其他专门委员会的成员、人民代表大会代表列席会议，发表意见。\n第三十七条 列入常务委员会会议议程的法规案，由法制委员会根据常务委员会组成人员、有关专门委员会的审议意见和各方面提出的意见，对法规案进行统一审议，提出审议结果的报告和法规草案修改稿，对重要的不同意见应当在审议结果的报告中予以说明。对有关专门委员会的重要审议意见没有采纳的，应当向有关专门委员会反馈。\n法制委员会审议法规案时，应当邀请有关专门委员会的成员列席会议，发表意见。\n第三十八条 专门委员会审议法规案时，应当召开全体会议审议，根据需要，可以要求有关机关、团体或者组织派人说明情况。\n专门委员会之间对法规草案的重要问题意见不一致时，应当向主任会议报告。\n第三十九条 列入常务委员会会议议程的法规案，法制委员会、有关专门委员会和常务委员会工作机构应当深入开展调查研究，广泛听取各方面的意见。听取意见可以采取座谈会、论证会、听证会等多种形式。\n法规案有关问题专业性较强，需要进行可行性评价的，应当召开论证会，听取有关专家、部门和人民代表大会代表等方面的意见。论证情况应当向常务委员会报告。\n法规案有关问题存在重大意见分歧或者涉及利益关系重大调整，需要进行听证的，应当召开听证会，听取有关基层和群体代表、部门、团体、专家、人民代表大会代表和社会有关方面的意见。听证情况应当向常务委员会报告。\n常务委员会工作机构应当将法规草案发送县（市、区）人民代表大会常务委员会、相关领域的人民代表大会代表以及有关部门、团体、组织、基层立法联系点和专家征求意见。\n第四十条 列入常务委员会会议议程的法规案，常务委员会工作机构应当在常务委员会会议后将法规草案及其说明等向社会公布，征求意见，但是经主任会议决定不公布的除外。向社会公布征求意见的时间一般不少于三十日。征求意见的情况应当向社会通报。\n常务委员会工作机构应当收集整理分组审议的意见和各方面提出的意见以及其他有关资料，分送法制委员会和有关专门委员会，并根据需要，印发常务委员会会议。\n第四十一条 常务委员会会议审议法规案，应当邀请有关的人民代表大会代表列席会议，听取意见；可以组织公民旁听和新闻媒体报道。\n专门委员会和常务委员会工作机构进行立法调研，应当邀请有关的人民代表大会代表参加。\n第四十二条 列入常务委员会会议议程的法规案，在交付表决前，提案人要求撤回的，应当提出书面报告，说明理由，经主任会议同意，并向常务委员会报告，对该法规案的审议即行终止。\n第四十三条 法规案经常务委员会会议第三次审议后，仍有重大问题需要进一步研究的，经主任会议同意，可以暂不付表决，交法制委员会和有关专门委员会进一步审议。\n第四十四条 列入常务委员会会议议程的法规案，因各方面对制定该法规的必要性、可行性等重大问题存在较大意见分歧，搁置审议满两年的，或者因暂不付表决经过两年没有再次列入常务委员会会议议程的，主任会议可以决定终止审议，并向常务委员会报告；必要时，主任会议也可以决定延期审议。\n第四十五条 拟提请常务委员会会议表决的法规案，常务委员会工作机构应当组织对法规草案中主要制度规范的可行性、法规出台时机、法规实施的社会效果和可能出现的问题等进行评估。评估情况由法制委员会在法规草案修改情况的说明中予以说明。\n拟提请常务委员会会议表决的法规案，常务委员会工作机构应当将法规草案提前报送省人民代表大会常务委员会工作机构征求意见。\n第四十六条 法规草案修改稿经常务委员会会议审议，拟提请常务委员会会议表决的，由法制委员会根据常务委员会组成人员的审议意见进行修改，提出法规草案表决稿，由主任会议提请常务委员会全体会议表决，由常务委员会全体组成人员的过半数通过。\n表决前，由法制委员会向常务委员会全体会议作关于法规草案修改情况的说明。\n第四十七条 法规草案表决稿交付常务委员会会议表决前，主任会议根据常务委员会会议审议的情况，可以决定将意见分歧较大的重要条款提请常务委员会会议单独表决；根据单独表决的情况，可以决定将法规草案表决稿交付表决，或者决定暂不付表决，交法制委员会和有关专门委员会进一步审议。\n第四十八条 对多部法规中涉及同类事项的个别条款进行修改，一并提出法规案的，经主任会议决定，可以合并表决，也可以分别表决。\n第四十九条 常务委员会通过的法规，应当自通过之日起十五日内，由常务委员会报请省人民代表大会常务委员会批准；经批准后，由常务委员会发布公告予以公布。","level":2},{"name":"第四章 法规解释","text":"第五十条 市人民代表大会及其常务委员会通过的法规由常务委员会解释。\n常务委员会的法规解释同法规具有同等效力。\n第五十一条 市人民政府、市监察委员会、市中级人民法院、市人民检察院、专门委员会以及县（市、区）人民代表大会常务委员会可以向常务委员会提出法规解释要求。\n第五十二条 常务委员会工作机构研究拟订法规解释草案，由主任会议决定列入常务委员会会议议程。\n拟提请常务委员会会议表决的法规解释，常务委员会工作机构应当将法规解释草案提前报送省人民代表大会常务委员会工作机构征求意见。\n法规解释草案经常务委员会会议审议，由法制委员会根据常务委员会组成人员的审议意见进行审议、修改，提出法规解释草案表决稿。\n第五十三条 法规解释草案表决稿由常务委员会全体组成人员的过半数通过，由常务委员会发布公告予以公布。\n常务委员会通过的法规解释，应当自公布之日起七日内，由常务委员会报省人民代表大会常务委员会备案。","level":1},{"name":"第五章 其他规定","text":"第五十四条 提案人提出法规案，应当同时提出法规草案文本及其说明，并提供必要的参阅资料。以修改决定形式提出的法规案，还应当提交修改前后的对照文本。\n法规草案的说明应当包括制定或者修改该法规的必要性、可行性、起草过程和主要内容以及对重大分歧问题的协调处理情况。\n第五十五条 向市人民代表大会及其常务委员会提出的法规案，在列入会议议程前，提案人有权撤回，但应当以书面形式提出。\n第五十六条 交付市人民代表大会及其常务委员会全体会议表决未获得通过的法规案，如果提案人认为必须制定该法规，可以按照本条例规定的程序重新提出法规案，由主席团、主任会议决定是否列入会议议程；其中，未获得市人民代表大会通过的法规案，应当提请市人民代表大会审议决定。\n第五十七条 法规应当明确规定施行日期。对涉及公民、法人和其他组织权利义务以及其他重要事项的法规，从公布到施行的日期，一般不得少于六十日。\n法规标题的题注应当载明制定、批准机关和通过、批准日期。经过修改的法规，应当依次载明修改、批准机关和修改、批准日期。\n法规经批准后，常务委员会工作机构应当及时将法规文本以及发布的公告等在常务委员会公报、咸宁人大信息网和《咸宁日报》上刊登。\n在常务委员会公报上刊登的法规文本为标准文本。\n第五十八条 法规的修改和废止程序，适用本条例的有关规定。\n法规被修改的，应当公布新的法规文本。\n法规被废止的，除由其他法规规定废止该法规的以外，由常务委员会发布公告予以公布。\n第五十九条 法规通过后，有关法规实施机关应当起草法规实施工作方案，明确责任主体、工作任务、完成时限等内容，并征求法制委员会、有关专门委员会、常务委员会工作机构和有关部门、单位的意见，按照程序报请批准后实施。\n法规实施机关应当按照工作方案的要求及时跟踪、评估法规实施情况。\n有关专门委员会、常务委员会工作机构应当将法规实施工作方案的落实情况作为执法检查的重要内容。\n第六十条 法规明确要求有关国家机关对专门事项作出配套规定的，有关国家机关应当自法规施行之日起一年内作出规定。法规对配套规定制定期限另有规定的，从其规定。有关国家机关未能在期限内作出配套规定的，应当向常务委员会报告。\n有关国家机关制定的配套规定应当报常务委员会备案，与相关法规相抵触或者不适当的，常务委员会有权要求其予以修改或者重新制定。\n有关专门委员会、常务委员会工作机构应当对配套规定的制定情况进行督促、检查。\n第六十一条 有关专门委员会、常务委员会工作机构应当组织对有关法规或者法规中有关规定进行立法后评估。评估情况应当向常务委员会报告。\n第六十二条 制定和修改后的法规实施满一定期限的，法规实施机关应当向常务委员会报告法规实施情况。\n第六十三条 市人民代表大会及其常务委员会制定的法规，应当自公布之日起七日内，由常务委员会将有关备案材料报省人民代表大会常务委员会。\n第六十四条 常务委员会工作机构可以对市人民代表大会及其常务委员会制定的法规具体应用的询问予以答复，并报常务委员会备案。\n第六十五条 常务委员会应当加强立法宣传工作，通过召开新闻发布会等形式发布立法信息、介绍情况、回应关切。\n新闻媒体应当加强法规制定、实施等工作的公益宣传。\n第六十六条 有关专门委员会、常务委员会工作机构可以对报送备案的规章和其他规范性文件进行主动审查，并可以根据需要进行专项审查。\n第六十七条 备案审查机关应当建立健全备案审查衔接联动机制，对应当由其他机关处理的备案审查要求或者建议，及时移送有关机关处理。\n第六十八条 对法规、规章和其他规范性文件，制定机关根据维护法制统一的原则和改革发展的需要进行清理。\n有关专门委员会、常务委员会工作机构、市人民政府法制机构和有关部门、单位发现法规存在与宪法、法律、行政法规和湖北省法规相抵触，以及与本市其他法规不协调或者与改革发展不适应等情形的，应当及时提出修改或者废止有关法规的建议。","level":1},{"name":"第六章 附 则","text":"第六十九条 本条例自公布之日起施行。","level":1}]},{"id":"h0219","sections":[{"name":"","text":"（2020年2月11日湖北省第十三届人民代表大会常务委员会第十四次会议通过）\n为了深入贯彻落实习近平总书记重要指示、党中央决策部署、中央赴湖北指导组和省委工作要求，依法全力做好当前新型冠状病毒肺炎疫情防控工作, 保障人民群众生命健康安全和社会公共安全，根据《中华人民共和国传染病防治法》《中华人民共和国突发事件应对法》《中华人民共和国野生动物保护法》《中华人民共和国动物防疫法》和《突发公共卫生事件应急条例》等法律、行政法规，结合本省疫情防控实际，作如下决定:\n一、疫情防控工作必须坚持党的领导，始终把人民群众生命安全和身体健康放在首位，全面贯彻坚定信心、同舟共济、科学防治、精准施策的总要求，坚持依法依规、联防联控、群防群治，落实属地责任，采取最严格的防控措施，内防扩散、外防输出，切实提高疫情防控的科学性、针对性、及时性和有效性。\n国家机关、企业事业单位、社会团体以及其他组织和个人都应当遵守疫情防控规定，自觉服从本地区疫情防控指挥机构的统一指挥和管理。\n二、县级以上人民政府应当建立健全省、市（州）、县（市、区）、乡镇（街道）、村（社区）等防控网络，运用现代信息技术，加强疫情监测、排查、预警、防控等工作，做到早发现、早报告、早隔离、早治疗，确保应收尽收、应治尽治。\n乡镇人民政府和街道办事处应当按照疫情防控工作的统一部署，组织指导辖区内相关方面采取针对性防控措施，切实做好疫情防控工作。\n村（居）民委员会、社区应当严格落实相关防控措施，强化防控网格化管理，协助做好宣传教育、人员排查、健康监测、集中收治隔离等工作。居民小区业主委员会、物业服务企业应当按照要求做好疫情防控工作。\n三、县级以上人民政府根据相关法律、行政法规的规定和本行政区域疫情防控需要，可以在医疗卫生、防疫管理、交通运输、社区治理、市场监管、场所管理、生产经营、劳动保障、市容环境卫生、野生动物保护等方面，规定临时性应急行政管理措施，并组织实施；可以紧急调集人员或者调用储备物资，临时征用房屋、交通工具以及相关设施、设备，相关单位和个人应当积极配合。\n四、国家机关、企业事业单位、社会团体以及其他组织应当落实本单位疫情防控主体责任，建立健全防控工作责任制和管理制度，发现异常情况及时报告相关部门并采取相应的防控措施。\n航空、铁路、城市公共交通、轨道交通、道路长途客运、水路客运等公共交通服务单位和超市、农贸市场、银行、宾馆等经营服务单位以及物业服务企业应当采取严密防控措施，确保公共交通工具、经营服务场所和居民小区符合疫情防控要求。\n个人应当按照疫情防控要求做好自我防护，不组织、不参加聚会活动，出门应当佩戴口罩；如实提供与疫情防控有关信息，配合相关部门采取相应的防控措施。\n五、县级以上人民政府及其有关部门应当统筹各方面资源，按照集中患者、集中专家、集中资源、集中救治的原则，及时充实医疗力量，全力保障医疗机构、集中隔离场所建设，推行确诊患者、疑似患者、发热患者以及密切接触者分类集中收治隔离。\n县级以上人民政府及其有关部门应当加强对疫情防控物资生产的政策支持，加强统筹协调，优先保障一线医疗单位、医护人员诊疗需要；关爱、保护医护人员和一线防疫人员，为对口支援医疗队伍、医护人员的医疗活动及生活提供服务保障和便利。\n县级以上人民政府及其有关部门应当加强对生活物资的生产、调配，保证居民正常生活需要；乡镇人民政府、街道办事处应当组织、协调村（居）民委员会、社区、物业服务企业为居民采购生活物资提供便利，并及时对辖区内居民特别是孕产妇、孤寡老人、残疾人、特困家庭等开展必要的生活援助。\n六、鼓励、支持单位和个人依法开展捐赠活动。县级以上人民政府及其有关部门应当加强对慈善组织和捐赠活动的监督管理，确保捐赠资金及物资的接收和分配公开透明、及时高效、公平合理。\n鼓励、支持志愿者组织和志愿者在做好自身防护基础上，依法有序参与疫情防控、应急救援和社区服务等。县级以上人民政府及其有关部门应当为志愿服务活动提供必要的保障和便利。\n七、县级以上人民政府及其有关部门应当统筹做好返岗、返工、返校工作，强化属地政府、企业事业单位和学校责任，落实疫情防控措施，维护正常的工作、生产和教学秩序；加强与省外协调配合，做好在外地滞留人员和在鄂滞留人员的帮扶和安全有序返回工作。\n八、县级以上人民政府应当严格落实疫情报告制度，依法及时准确向社会公布、解读疫情，加强信息公开，及时回应社会关切。\n各级人民政府、有关部门以及广播、电视、报刊、网络等媒体应当加大对疫情防控法律法规、政策措施和防控知识的宣传解读，加强舆论引导，在全社会营造同心同德、众志成城、全民抗疫的良好氛围。\n任何单位和个人不得缓报、漏报、瞒报、谎报疫情信息，不得编造、传播有关疫情的虚假信息。\n九、各级行政机关应当加强社会治理、治安管理、市场监管等工作，严厉打击抗拒疫情防控、伤害医护和防疫人员、制售伪劣疫情防控产品、哄抬疫情防控产品和民生商品价格、非法捕杀交易运输野生动物等违法行为。疫情防控期间，个人因上述行为受到相关行政处罚的，纳入社会信用信息服务平台，依法实行联合惩戒。\n各级监察机关应当对疫情防控工作中不作为、乱作为以及形式主义、官僚主义问题依法依规追责问责。\n各级司法机关应当依法处理涉及疫情防控的民商事以及行政纠纷，依法严惩妨碍疫情防控的违法犯罪行为。\n十、县级以上人民代表大会常务委员会和乡镇人民代表大会应当加强对疫情防控、应急处置法律法规和本决定执行情况的监督；组织动员各级人大代表积极参与和支持疫情防控工作，充分发挥人大代表作用。\n本决定自公布之日起生效，在本次疫情防控期间施行。","level":0}]},{"id":"h0220","sections":[{"name":"","text":"（2020年1月17日湖北省第十三届人民代表大会第三次会议通过）","level":0},{"name":"第一章 总则","text":"第一条 为了实施乡村振兴战略，推进农业农村现代化，增进乡村居民福祉，根据国家有关法律法规和方针政策，结合本省实际，制定本条例。\n第二条 本条例适用于本省行政区域内乡村振兴战略的实施、保障及监督等工作。\n第三条 实施乡村振兴战略，必须坚持中国共产党的领导，坚持农业农村优先发展、农民主体地位，坚持城乡融合发展、人与自然和谐共生，坚持改革创新、激发活力，坚持因地制宜、循序渐进，按照产业兴旺、生态宜居、乡风文明、治理有效、生活富裕的总要求，促进乡村产业振兴、人才振兴、文化振兴、生态振兴、组织振兴。\n第四条 建立乡村振兴工作领导责任制，实行省负总责、市县乡抓落实的工作机制。\n省人民政府负责全省乡村振兴工作，将乡村振兴工作纳入国民经济和社会发展规划，建立健全城乡融合发展体制机制和政策体系，建立联席会议制度，研究解决乡村振兴工作中的重大问题，统筹推进乡村振兴战略的实施。\n市（州）、县（市、区）人民政府组织实施本行政区域内乡村振兴工作。\n乡镇人民政府、街道办事处根据法律法规规定和上级人民政府的要求，结合本地区实际组织开展乡村振兴工作。\n村（居）民委员会在乡镇人民政府、街道办事处的指导下，组织、动员乡村居民积极参与乡村振兴。\n第五条 县级以上人民政府农业农村主管部门负责本行政区域内乡村振兴的协调指导、推动落实和监督检查等具体工作；其他相关部门按照职责分工共同做好乡村振兴工作。\n第六条 发挥乡村居民在乡村振兴中的积极性、主动性、创造性，尊重乡村居民意愿，保障和维护乡村居民合法权益。\n鼓励、支持和引导企业事业单位、人民团体、社会组织和个人参与、服务乡村振兴，建立政府、市场、社会协同推进的机制。\n各级人民政府及有关部门和媒体应当加强对乡村振兴战略及政策措施的宣传，引导社会广泛参与。\n第七条 各级人民政府应当做好脱贫攻坚与乡村振兴的有机衔接，巩固脱贫攻坚成果，建立解决相对贫困、防止返贫的长效机制，持续推动经济社会协调发展和乡村居民增收致富。","level":1},{"name":"第二章 规划引领","text":"第八条 省人民政府编制全省乡村振兴总体规划。\n省人民政府有关部门编制乡村振兴产业发展、生态环境保护、人居环境整治、基本公共服务等专项规划。\n市（州）、县（市、区）人民政府及其有关部门编制乡村振兴地方规划。\n第九条 乡村振兴规划的编制，应当与国土空间规划相衔接，符合本地实际，统筹城乡产业发展、基础设施、基本公共服务、资源能源、生态环境保护等布局，推动城乡生产生活要素自由流动、平等交换和公共资源合理配置，形成城乡融合、区域一体、多规合一的规划体系。\n第十条 县（市、区）人民政府编制村庄布局规划，指导乡镇人民政府编制村庄规划。\n村庄布局规划和村庄规划的编制，应当体现地方特色，符合乡村振兴规划要求，统筹村庄基础设施和公共服务设施建设、产业发展空间、耕地和永久基本农田保护、生态环境保护与修复、人居环境整治、历史文化传承与保护、防灾减灾措施。\n省人民政府自然资源、住房和城乡建设主管部门按照职责分工，制定村庄规划编制导则、农村住房设计导则和村庄整治导则，加强对村庄规划、农村住房设计和人居环境整治的指导。\n第十一条 乡村振兴规划的编制和修改，应当征求乡村居民、专家以及其他利益相关方的意见，并经本级人民代表大会常务委员会讨论后，依照法定程序批准实施。未经法定程序，不得擅自修改。\n建立监督检查评估机制，推进乡村振兴规划的执行。\n乡村振兴规划及其执行情况依法向社会公开，接受社会监督。","level":1},{"name":"第三章 产业发展","text":"第十二条 坚持新发展理念，以市场为导向，推进农业供给侧结构性改革，构建现代农业产业体系、生产体系、经营体系，提高农业创新力、竞争力和全要素生产率，实现农业高质量发展。\n培育农村新产业、新业态、新模式，推动一二三产业融合发展，突出优势特色，发展壮大乡村产业。\n第十三条 各级人民政府应当依法保护耕地和永久基本农田，加强农村土地综合整治和高标准农田建设，探索实行耕地轮作休耕制度，建立健全耕地质量保护与提升长效机制。\n统筹推进大中型灌区续建配套节水改造与现代化建设，以及小型农田水利设施达标提质，完善农村水利基础设施网络，提高节水供水和防汛抗旱能力。\n第十四条 县级以上人民政府应当加强粮食生产、收购、储备和流通能力建设，完善粮食生产功能区、重要农产品生产保护区支持政策，实施藏粮于地、藏粮于技战略，确保粮食安全；支持粮食重点企业发展，依托粮食主产区、特色粮油产区和关键粮食物流节点，建设优势粮食产业集群，推进粮食产业化。\n第十五条 县级以上人民政府应当调整优化农业生产力布局，推进农业绿色化、优质化、特色化、品牌化，重点培育壮大农业全产业链，促进农业结构优化升级。\n推进国有农场、林场规划建设和改革，发挥其在乡村振兴中的作用。\n第十六条 县级以上人民政府应当推进农业全程标准化，完善农产品质量安全标准体系，健全农产品质量安全监管体系、监测检测体系、追溯体系，落实生产经营主体责任，提高农产品质量，推进质量兴农。\n省人民政府应当支持开展绿色食品、有机农产品和农产品地理标志认证，建立地理标志产品重点支持和保护清单，支持创建农业区域公用品牌、企业品牌、大宗农产品品牌、特色农产品品牌，建立健全品牌运营、管理和保护机制，推进品牌强农。\n第十七条 县级以上人民政府应当推进农产品产地初加工、精深加工和副产品综合利用，培育农产品加工产业集群和龙头企业，建设主导产业突出的农产品加工园、农产品专业村镇和加工强县。\n第十八条 县级以上人民政府应当支持农产品批发市场、综合加工配送中心、产地集中配送中心建设，健全农产品冷链仓储物流体系，建立农产品销售公共服务平台。\n加强乡村电子商务人才培养和平台建设，培育和壮大乡村电子商务市场，推进乡村电子商务综合示范，发展线上线下融合的现代乡村商品流通和服务网络，实现城乡生产与消费多层次对接。\n第十九条 各级人民政府应当保护、利用乡村生态环境、自然景观、传统文化和乡俗风情等特色资源，丰富乡村旅游产品，提高服务管理水平，提升乡村旅游发展质量和综合效益。\n支持适应城乡居民需求的休闲农业、餐饮民宿、文化体验、健康养生、养老服务等产业发展。\n第二十条 各级人民政府应当引导乡村特色文化产业发展，建设特色鲜明、优势突出的农耕文化产业展示区、特色文化产业乡镇、特色文化产业村，支持培育传统工艺产品和民间技艺项目，促进乡村文化产品适应现代消费需求。\n第二十一条 省人民政府应当培育支撑现代农业发展的创新主体，加强农业科技创新中心、创新基地和创新联盟建设，完善现代农业科技创新体系和产业技术体系，促进农业关键核心技术创新发展。\n建设农业高新技术产业示范区、农业科技园区、现代农业产业园，培育国际领先的农业高新技术企业，形成具有国际竞争力的农业高新技术产业。\n支持大专院校、科研院所、农业技术推广机构、新型农业经营主体围绕优势和特色产业开展适用技术研究和应用，建设农业科技成果转化基地，发挥示范带动作用。\n加强农业种质资源保护利用，支持种业科技创新，加快发展现代种业。\n第二十二条 县级以上人民政府应当加强基层农业技术推广机构和队伍建设，健全基层农业技术推广体系，创新服务方式，支持社会力量参与农业技术推广，实施农业技术推广服务特聘计划，加强农业重大技术协同推广应用。\n第二十三条 县级以上人民政府应当支持先进适用农业机械装备的研发、推广应用，促进作物品种、栽培技术和机械装备集成配套，建立农机农艺融合的机械化生产技术体系，实施农机补贴政策，推进主要作物生产全程机械化，提高农业机械化水平。\n第二十四条 县级以上人民政府应当推进农业农村信息化和智能化，加强信息化基础设施建设，健全农业信息监测预警、发布机制，推动物联网、大数据、云计算、区块链、人工智能等现代信息技术在农业各环节和农村各领域的应用，发展智慧农业。\n第二十五条 各级人民政府应当推进专业大户、家庭农场、农民合作社、农业产业化龙头企业等新型农业经营主体与小农户建立利益联结机制，完善面向小农户的社会化服务体系，促进小农户和现代农业发展有机衔接。\n组织和引导小农户发展地方优势特色产业，开展标准化生产、专业化经营；扶持小农户发展生态农业、设施农业、体验农业、定制农业，提高产品档次和附加值；支持小农户在家庭种养基础上发展特色手工和乡村旅游，实现家庭生产的多业经营、综合创收。\n支持新型农业经营主体通过订单收购、保底分红、股份合作等多种形式带动小农户共同发展，保障小农户共享全产业链增值收益。建立绩效评价机制，将新型农业经营主体带动小农户数量和成效作为政府项目扶持、资金支持的重要依据。\n第二十六条 县级以上人民政府应当支持特色农产品和高附加值农产品出口，加强农业国际合作，提高农业对外合作水平。","level":1},{"name":"第四章 生态宜居","text":"第二十七条 各级人民政府应当坚持节约优先、保护优先、自然恢复为主的方针，统筹山水林田湖草系统治理，加强乡村生态环境保护，推行绿色生产生活方式，改善乡村人居环境，建设美丽宜居乡村。\n第二十八条 开展生态系统保护和修复，加强河湖、湿地、天然林保护和水土保持，实施退耕还林还草、退田还湖还湿、退圩退垸还湖，统筹生态清洁小流域建设，全面推行河湖（库）长制、林长制。\n加强乡村饮用水水源地保护，推进乡村饮水安全巩固提升工程，健全农业用水安全监测和管理机制；加强乡村土壤污染监测、风险管控和修复治理；全面实施农作物秸秆露天禁烧和综合利用。\n支持依法开展生态环境公益诉讼，对污染乡村生态环境、破坏自然资源等行为进行监督；实施生态环境损害赔偿制度。\n省人民政府应当建立生态保护补偿机制，加大对重点生态功能区补偿力度。具体办法由省人民政府制定。\n第二十九条 各级人民政府应当鼓励发展生态循环农业，防治农业面源污染，支持农业生产经营主体采用先进种植养殖技术、设备和模式，推动投入品减量化、生产清洁化、废弃物资源化、产业模式生态化。\n推进农业有害生物绿色防控、有机肥替代化肥、畜禽粪污无害化处理和资源化利用、废旧农膜和包装废弃物回收处理。\n农产品生产经营中禁止使用国家和省禁用的农药（含除草剂）、兽药等禁用物质或者其他有毒有害物质，禁止违反农产品质量安全标准超剂量、超范围使用农药（含除草剂）、兽药、肥料、饲料和饲料添加剂等农业投入品。\n省人民政府农业农村主管部门应当制定禁用限用农业投入品目录，适时调整，并及时向社会公布。\n第三十条 县级以上人民政府应当建立工业和城镇污染向农业农村转移的防控机制。禁止将破坏生态、污染环境的产业、企业向农村转移；禁止将城镇垃圾和未经达标处理的城镇污水等违法向农村转移或者排放。\n第三十一条 各级人民政府应当加强乡村生活垃圾治理，推行垃圾源头减量、分类和资源化利用，建立健全符合乡村实际、方式多样的生活垃圾收运处置体系，鼓励运用垃圾处理新技术。\n统筹推进乡村生活污水治理，因地制宜实行集中与分散相结合的乡村污水处理方式和运行维护模式，推进城镇污水管网向周边村庄延伸覆盖。\n建设经济适用、维护方便、生态环保的无害化厕所，加强改厕与乡村生活污水处理的有效衔接，推进厕所粪污无害化处理和资源化利用。\n第三十二条 农民一户只能拥有一处宅基地。乡镇人民政府应当依法规范乡村宅基地审批和建房规划许可管理，整治违法建设。禁止非法买卖宅基地。\n加强村庄公共照明设施建设，推进村庄绿化，提升村容村貌。\n建立以乡村居民为主体、政府引导、社会参与的乡村人居环境治理和管护长效机制，推行环境治理依效付费制度，健全服务绩效评价考核机制。","level":1},{"name":"第五章 乡风文明","text":"第三十三条 各级人民政府应当坚持以社会主义核心价值观为引领，传承和发展中华优秀传统文化，加强乡村思想道德建设和公共文化服务，培育文明乡风、良好家风、淳朴民风，提升乡村社会文明程度。\n第三十四条 各级人民政府应当加强乡村精神文明建设，建立新时代文明实践中心，丰富乡村居民精神文化生活，倡导科学健康的生产生活方式。\n支持乡村开展群众性精神文明创建活动，开展文明村镇、文明家庭等评选表彰活动。\n加强家庭教育，倡导尊老爱幼。推动全民阅读，开展科普活动，抵制封建迷信。\n推进移风易俗，遏制大操大办、天价彩礼、厚葬薄养等陈规陋习。\n第三十五条 各级人民政府应当健全乡村公共文化服务体系，加强乡村公共文化体育设施和综合性文化服务中心规划、建设，推进乡、村两级公共文化服务全覆盖，丰富乡村公共文化产品供给，满足乡村居民基本文化需求。\n加强基层文化队伍建设，培养专兼职相结合的乡村文化工作队伍，培育乡村文化本土人才，发展乡村文艺团队。开展文化结对帮扶，引导社会力量参与乡村文化建设。\n第三十六条 各级人民政府应当完善乡村文化体育扶持机制，支持开展形式多样、健康向上的文化体育活动，推进全民健身。\n鼓励开展乡村群众性节日民俗活动，传承和发展民族民间传统文化和体育。\n繁荣乡村文化市场，丰富乡村文化业态，加强乡村文化市场监管。\n第三十七条 各级人民政府应当挖掘、保护、传承和发展荆楚传统文化中的优秀思想观念、人文精神、道德规范。\n保护古镇、古建筑、古树名木、传统村落、民族村寨、文物古迹、农业遗迹等。\n完善乡村传统戏曲、音乐、舞蹈、美术、技艺、民俗、医药等非物质文化遗产保护制度，推进乡村非物质文化遗产传承和发展。","level":1},{"name":"第六章 乡村治理","text":"第三十八条 建立健全党委领导、政府负责、民主协商、社会协同、公众参与、法治保障、科技支撑的乡村治理体制，完善自治、法治、德治相结合的乡村治理体系，推动社会治理和服务重心向基层下移，提高乡村治理效能，实现共建共治共享。\n第三十九条 加强乡村基层组织建设，健全组织领导、宣传教育、服务群众、民主管理、推动发展等工作体系。选派优秀干部到软弱涣散村（社区）和集体经济薄弱村（社区）担任负责人。\n支持从本村（社区）致富能手、外出务工经商返乡能人、回乡大中专毕业生、退役军人等人员中培养、选任村（社区）干部。\n健全从优秀村（社区）干部中选拔乡镇领导干部、考录乡镇公务员、招聘乡镇事业编制人员机制。\n健全村（社区）后备干部培养、储备机制，采取本土人才回引、院校定向培养、县乡统筹招聘等方式，培养、储备村（社区）后备干部。\n第四十条 县（市、区）、乡镇人民政府和街道办事处应当加强农村群众性自治组织建设，完善民主选举、民主协商、民主决策、民主管理、民主监督制度，发挥自治章程、村规民约和公序良俗在乡村治理中的作用，引导村民有序参与村务管理和乡村建设。\n依托村民会议、村民代表会议、村民议事会、村民理事会、村民监事会等，创新民事民提、民事民议、民事民办、民事民评的多层次基层议事协商形式。\n全面建立健全村务监督委员会，健全村务监督机制，推行和规范村务公开。\n第四十一条 省人民政府应当统筹机构编制资源，依法推进乡镇整合行政执法、公共服务相关职能，设立综合性机构，提高乡村治理能力和服务水平。\n第四十二条 县级以上人民政府应当支持乡村推动政务平台建设与政务公开，推进乡村政务服务事项一窗式办理、信息系统一平台整合、社会服务管理大数据一口径汇集，提高乡村治理智能化、便民化水平。\n第四十三条 加强乡村干部队伍建设，建立和完善乡村干部培养、配备、管理、使用、评价和激励机制。\n省人民政府应当统筹县乡工作人员待遇标准，提高乡镇工作补贴标准，保障乡镇工作人员收入高于县级机关同职级人员水平；按照规定合理确定并落实村干部基本报酬，保障正常离任村干部生活补贴。具体办法由省人民政府制定。\n第四十四条 各级人民政府应当加大乡村法治宣传教育，培育法治文化，增强基层干部法治观念、法治意识、法治思维，引导乡村居民尊法学法守法用法。\n推进综合行政执法改革向基层延伸，整合执法队伍，创新监管方式，提高基层执法能力和水平。\n健全乡村公共法律服务体系，整合法律服务资源，加强法律援助和司法救助。\n完善人民调解、行政调解、司法调解联动工作体系，推动调解、仲裁、行政裁决、行政复议、诉讼等有机衔接，健全社会矛盾纠纷多元预防调处化解综合机制。\n第四十五条 各级人民政府应当健全乡村社会治安防控体系和公共安全体制机制，加强乡村警务工作，推进乡村公共安全视频监控等技防系统建设，加强乡村公路安全防护设施建设，完善乡村网格化服务管理机制，强化乡村安全生产、防灾减灾救灾、食品、药品、交通、消防等安全管理责任，建设平安乡村。\n依法惩治乡村黑恶势力、黄赌毒盗拐骗以及乡村非法宗教活动、邪教活动等违法犯罪。依法治理乡村乱建寺观教堂、滥塑宗教造像等。\n第四十六条 各级人民政府应当加强社会公德、职业道德、家庭美德、个人品德教育，建立乡村道德激励约束机制，强化德治在乡村治理中的作用。\n加强乡村诚信建设，开展诚信教育，培育诚信文化，建立健全覆盖乡村的信用信息系统，规范信用信息使用，完善守信激励与失信惩戒机制。","level":1},{"name":"第七章 民生保障","text":"第四十七条 县级以上人民政府应当加强乡村基础设施建设，统筹布局道路交通、供水、供电、供气、信息网络、广播电视、垃圾和污水处理等设施，推进城乡基础设施统一规划、统一建设、统一管护。\n第四十八条 县级以上人民政府应当健全城乡一体、全民覆盖、均衡发展、普惠共享的基本公共服务体系，推进教育、医疗卫生、社会保障等资源向乡村倾斜，促进城乡基本公共服务均等化，保障和改善民生。\n第四十九条 县级以上人民政府应当优先发展乡村教育事业，推进城乡教育资源优质均衡配置，统筹规划、合理调整乡村学校布局，推行义务教育学校标准化建设，加强寄宿制学校建设，加强学校安全管理，推进教育信息化发展，全面改善薄弱学校办学条件。\n实施乡村教师支持计划，建立完善省级统筹的乡村义务教育学校教师补充机制和教师待遇保障机制，提升乡村教师队伍素质。\n发展乡村学前教育，提高高中阶段教育普及水平，发展面向乡村的职业教育和继续教育，加强乡村特殊教育。\n第五十条 县级以上人民政府应当完善乡村医疗卫生服务体系，健全乡村医疗卫生服务网络，稳步提高人均基本公共卫生服务经费补助标准，加强乡镇卫生院和村卫生室标准化、信息化建设，保障基本药物的供给和及时配送，推进县域医疗卫生共同体和乡村远程医疗系统建设。\n鼓励和支持乡村医疗卫生人才引进，加强全科医生培养，提高乡村医疗卫生人员待遇，提高乡镇卫生院骨干人员特岗津贴和大学生招聘补贴标准。\n推进健康乡村行动，建立健全乡村健康服务体系，加强健康教育、健康干预，加强疾病预防，倡导科学文明健康的生活方式。\n第五十一条 省人民政府应当健全覆盖城乡居民的养老保险制度，建立完善城乡居民基本养老保险待遇确定和基础养老金正常调整机制。\n完善统一的城乡居民基本医疗保险制度，逐步提高城乡居民基本医疗保险个人缴费和财政补助标准，完善城乡居民大病保险制度，开展重特大疾病救助工作。\n健全医疗救助与城乡居民基本医疗保险、大病保险以及相关保障制度的衔接机制，推进城乡居民医保异地就医联网直接结算。\n第五十二条 县级以上人民政府应当建立多元化乡村养老服务体系，统筹规划建设养老服务设施，与乡村基本公共服务、乡村特困供养服务、乡村互助养老服务相互配合，形成乡村基本养老服务网络。\n第五十三条 县级以上人民政府应当完善乡村最低生活保障、特困人员救助供养、医疗救助、临时救助等社会救助制度，健全标准动态调整机制，推进城乡统筹。\n各级人民政府可以通过购买服务、设置基层公共管理和社会服务岗位、引入社会工作者和志愿者等方式，为乡村留守儿童和妇女、老年人以及残疾人、困境儿童等提供关爱服务。发展乡村托幼服务。\n第五十四条 县级以上人民政府应当实施就业优先政策，健全城乡一体的公共就业创业服务体系，实施促进乡村居民就业创业的扶持政策，完善就业创业培训指导、就业援助、劳动维权工作机制。\n第五十五条 依法保障进城落户农民土地承包权、宅基地使用权、集体收益分配权。取得城镇居住证的农民依法享受城镇基本公共服务。\n省人民政府应当完善农业转移人口市民化财政支持政策，实施城镇建设用地增加规模与吸纳农业转移人口落户数量挂钩政策。","level":1},{"name":"第八章 支持措施","text":"第五十六条 县级以上人民政府应当建立健全乡村振兴财政投入优先保障和稳定增长机制，其增长幅度高于财政经常性收入的增长幅度。\n省人民政府应当设立乡村振兴专项资金或者发展基金，发挥农业领域政府投资基金对社会资本的引导作用；加强对相对贫困地区、少数民族地区、革命老区乡村振兴的财政支持力度；建立乡村振兴资金统筹机制，支持县（市、区）人民政府整合相关项目和资金，提高资金使用效益。\n第五十七条 鼓励和支持金融机构面向小农户、新型农业经营主体、中小企业等开展小微普惠金融服务。\n完善涉农主体的融资增信机制，建立健全政府性融资担保和风险分担机制，支持和推动农业信贷担保机构降低担保门槛、扩大担保覆盖面，发挥农业信贷担保体系作用。\n支持农业保险发展，扩大农业政策性保险的品种和范围，适当提高赔付比例和标准。\n第五十八条 各级人民政府应当加强对村级的财政投入力度，推进农村集体产权制度改革，支持开展多种形式的股份合作，发展新型农村集体经济。\n健全农村集体经济组织资产登记、交易、监督等各项管理制度，发挥农村集体经济组织在管理集体资产、合理开发集体资源、服务集体成员等方面的作用。\n第五十九条 保持农村土地承包关系稳定并长久不变。完善农村承包地“三权分置”制度，在依法保护集体土地所有权和农户承包权前提下，平等保护土地经营权。\n农村承包土地经营权可以依法向金融机构融资担保、入股从事农业产业化经营。\n第六十条 探索农村宅基地“三权分置”，落实宅基地集体所有权，保障宅基地农户资格权和农民房屋财产权，适度放活宅基地和农民房屋使用权。\n进城落户的农民可以依法自愿有偿退出宅基地，鼓励农村集体经济组织及其成员依法利用闲置宅基地和闲置住宅。\n鼓励依法利用闲置住宅发展休闲农业、乡村旅游、餐饮民宿、文化体验、电子商务等新产业新业态，以及农产品冷链、初加工、仓储等一二三产业融合发展项目。\n第六十一条 土地利用总体规划、城乡规划确定为工业、商业等经营性用途，并经依法登记的集体经营性建设用地，土地所有权人可以依法通过出让、出租等方式交由单位或者个人使用。\n农村集体经济组织在农民自愿前提下，可以依法将有偿收回的闲置宅基地、废弃的集体公益性建设用地转变为集体经营性建设用地入市。\n第六十二条 在符合土地利用总体规划前提下，县（市、区）人民政府可以依法通过村土地利用规划调整优化村庄用地布局，有效利用农村零星分散的存量建设用地。\n对利用收储农村闲置建设用地发展农村新产业新业态的，给予新增建设用地指标奖励。\n第六十三条 建立被征地农民多元化保障机制，征收土地应当给予公平、合理的补偿。\n依法征收集体土地的，可以在符合规划用地条件下预留被征地面积一定比例的土地，作为被征地集体经济组织建设用地，发展二三产业。\n第六十四条 县级以上人民政府应当统筹农业农村各项土地利用活动，乡镇土地利用总体规划可以预留一定比例的规划建设用地指标，用于农业农村发展。\n在符合国土空间规划前提下，通过村庄整治、土地整理等方式节余的农村集体建设用地优先用于发展乡村产业项目。\n第六十五条 县级以上人民政府应当建立高素质农民教育体系，培育新型农业经营主体骨干、现代青年农场主、农村实用人才带头人、农业职业经理人等高素质农民。\n支持农民通过弹性学制参加中高等农业职业教育，支持符合条件的农民参加职业技能鉴定和专业职称评定，支持农民合作社、专业技术协会、龙头企业等主体参与和承担培训。\n第六十六条 县级以上人民政府应当加强乡村专业人才队伍建设，建立县域专业人才统筹使用制度和乡村专业人才定向委托培养制度，提升乡村专业人才待遇。\n建立城乡、区域、校地之间人才培养合作与交流机制，支持国家工作人员和城市教师、医生、科技人员等专业人才到乡村挂职和定期服务、退休后服务乡村。\n第六十七条 各级人民政府应当加强农业科研、技术推广人才和农村生产型、经营型、技能服务型人才队伍建设，推行科技特派员制度，提高农业生产经营服务保障能力。\n推进农业技术人才职称制度改革，建立健全农村实用人才评价认定体系。\n第六十八条 各级人民政府应当鼓励和支持市民下乡、能人回乡、企业兴乡，引导社会力量通过下乡担任志愿者、投资兴业、结对帮扶、行医办学、捐资捐物、法律服务以及其他方式参与和服务乡村振兴。","level":1},{"name":"第九章 监督考核","text":"第六十九条 省人民政府应当建立实施乡村振兴战略的目标责任制，制定考核办法，建立完善考核评价指标体系。\n县级以上人民政府应当定期对所属有关部门和下级人民政府落实乡村振兴政策、开展乡村振兴工作情况进行考核。考核结果作为有关领导干部综合考核、选拔任用的重要依据。\n第七十条 县级以上人民政府应当定期向本级人民代表大会或者其常务委员会报告乡村振兴战略实施情况，并接受监督。\n第七十一条 县级以上人民政府及其财政、审计部门应当对乡村振兴资金管理、使用和绩效等情况进行监督检查，对发现的问题依法予以处理。\n第七十二条 建立和实施乡村振兴激励机制和容错机制，鼓励和支持担当作为、改革创新。\n对在乡村振兴工作中做出突出贡献或者显著成绩的单位和个人，给予表彰和奖励。","level":1},{"name":"第十章 法律责任","text":"第七十三条 违反本条例，法律、法规有规定的，从其规定。\n第七十四条 国家机关及其工作人员有下列行为之一的，由其上级机关或者主管部门责令改正，对负有责任的领导人员和直接责任人员依法给予处理；构成犯罪的，依法追究刑事责任：\n（一）未按照规定编制、修改乡村振兴规划的；\n（二）未按照规定拨付乡村振兴相关财政资金的；\n（三）截留、挪用、侵占和套取乡村振兴相关专项资金、基金或者补贴资金的；\n（四）虚报、瞒报、拒报或者伪造、篡改乡村振兴战略实施情况以及相关数据的；\n（五）其他滥用职权、玩忽职守、徇私舞弊的行为。\n第七十五条 村民委员会及其成员有下列行为之一的，由乡镇人民政府或者有关主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处理；构成犯罪的，依法追究刑事责任：\n（一）侵占、挪用、贪污农村集体资产或者政府拨付、社会捐赠的乡村振兴资金、物资的；\n（二）强迫或者阻碍农民流转土地经营权的；\n（三）其他未按照规定履行相关职责的行为。\n第七十六条 任何组织和个人侵害农民、农村集体经济组织、新型农业经营主体合法权益的，依法承担民事责任；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第十一章 附则","text":"第七十七条 本条例自2020年5月1日起施行。\n","level":1}]}]);
